Object.assign(window.TEM8_DICTIONARY, {"repaired":{"lemma":"repair","media":{"uk":"media/uk/repair__gb_1.mp3","us":"media/us/repair__us_1.mp3"}},"reduction":{"media":{"uk":"media/uk/reduction__gb_1.mp3","us":"media/us/reduction__us_1.mp3"},"oxford":{"phon":"rɪˈdʌkʃn","pos":"noun","senses":[{"en":"an act of making something less or smaller; the state of being made less or smaller","cn":"减少；缩小；降低","g":"[countable, uncountable]","ex":{"en":"Some staff received wage rises, while others experienced a reduction.","cn":"一些员工的工资上涨，而另一些员工的工资则下降。"}},{"en":"an amount of money by which something is made cheaper","cn":"减价；折扣","g":"[countable]","ex":{"en":"price reductions","cn":"降价"}},{"en":"a copy of a photograph, map, picture, etc. that is made smaller than the original one","cn":"（照片、地图、图片等的）缩图，缩版","g":"[countable]"},{"en":"the fact of adding one or more electrons to a substance or of removing oxygen from a substance","cn":"还原；去氧；脱氧","g":"[uncountable, countable]","lab":"chemistry"},{"en":"a sauce made by boiling a liquid until it becomes thick","cn":"浓缩酱汁（将汤汁熬至浓稠而成）","ex":{"en":"a red wine reduction","cn":"红酒减少"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"减少；降低","en":"When there is a reduction in something, it is made smaller.","ex":{"en":"...a future reduction in UK interest rates","cn":"未来英国利率的下调"}},{"pos":"N-UNCOUNT 不可数名词","cn":"减少；降低；缩小","en":"Reduction is the act of making something smaller in size or amount, or less in degree.","ex":{"en":"...a new strategic arms reduction agreement.","cn":"新的战略武器削减协议"}}]},"examples":[{"en":"There are reductions for children sharing a room with two adults.","cn":"孩子和两个大人合住一间房可以打折。"},{"en":"a 33% reduction in the number of hospital beds available","cn":"医院的床位减少 33%"}]},"red":{"media":{"uk":"media/uk/red__gb_1.mp3","us":"media/us/red__us_1.mp3"},"oxford":{"phon":"red","pos":"adjective","senses":[{"en":"having the colour of blood or fire","cn":"红的；红色的","ex":{"en":"bright/light/dark red lipstick","cn":"鲜／浅／深红色口红"}},{"en":"red-brown in colour","cn":"红褐色的","ex":{"en":"her flaming red hair","cn":"她火红的头发"}},{"en":"bright red or pink, especially because you are angry, embarrassed or ashamed","cn":"涨红的；通红的","lab":"British English","ex":{"en":"I felt my face go red.","cn":"我觉得我的脸涨红了。"}},{"en":"bloodshot (= with thin lines of blood in them) or surrounded by red or very pink skin","cn":"充血的；布满血丝的；红肿的","ex":{"en":"Her eyes were red from crying.","cn":"她的眼睛都哭红了。"}},{"en":"(of an area in the US) having more people who vote for the Republican candidate than the Democratic one","cn":"（美国某一地区）红色的（支持共和党候选人多于民主党候选人）","lab":"politics","ex":{"en":"red states/counties","cn":"红州；红县"}},{"en":"having very left-wing political opinions; communist or socialist","cn":"具有非常左翼的政治观点；共产主义或社会主义","lab":"informal, usually disapproving, politics，，，，"},{"en":"the colour of blood or fire","cn":"红色","g":"[countable, uncountable]","ex":{"en":"She often wears red.","cn":"她经常穿红色的衣服。"},"pos":"noun"},{"en":"red wine","cn":"红葡萄酒","g":"[uncountable, countable]","ex":{"en":"Would you prefer red or white?","cn":"你喜欢喝红葡萄酒还是白葡萄酒？"},"pos":"noun"},{"en":"an offensive word for a communist or socialist","cn":"共产主义者，社会主义者（含贬义）","g":"[countable]","lab":"informal, disapproving, politics，，，，","pos":"noun"},{"en":"a British women's magazine published every month since 1998 which contains articles and photographs about fashion, beauty, famous people, travel and issues of interest to women","cn":"红色：自1998年以来每月出版的英国女性杂志，其中包含有关时尚，美丽，名人，旅行和妇女关注的问题的文章和照片","pos":""}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"红色;血色","en":"Something that is red is the colour of blood or fire.","ex":{"en":"...a bunch of red roses","cn":"一束红玫瑰"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（因为尴尬、生气或气短）脸红的","en":"If you say that someone's face is red, you mean that it is redder than its normal colour, because they are embarrassed, angry, or out of breath.","ex":{"en":"With a bright red face I was forced to admit that I had no real idea","cn":"我的脸涨得通红，被迫承认自己实际上没什么想法。"}},{"pos":"ADJ 形容词","cn":"（头发）红褐色的","en":"You describe someone's hair as red when it is between red and brown in colour.","ex":{"en":"...a girl with red hair","cn":"红褐色头发的女孩"}},{"pos":"ADJ 形容词","cn":"（细胞）红的","en":"Your red blood cells or red corpuscles are the cells in your blood which carry oxygen around your body."},{"pos":"N-MASS 物质名词","cn":"红酒","en":"You can refer to red wine as red .","ex":{"en":"The spicy flavours in these dishes call for reds rather than whites.","cn":"这些菜的味道辛辣，应该配红酒而不是白葡萄酒。"}},{"pos":"N-COUNT 可数名词","cn":"共产党员;社会主义者;左翼思想者","en":"If you refer to someone as a red or a Red, you mean that they are a communist, a socialist, or have left-wing ideas.","ex":{"en":"They're all so terrified of Reds.","cn":"他们所有人都非常害怕红色人士。"}},{"pos":"PHRASE 短语","cn":"有赤字;亏空;负债","en":"If a person or company is in the red or if their bank account is in the red, they have spent more money than they have in their account and therefore they owe money to the bank.","ex":{"en":"The theatre is £500,000 in the red","cn":"这座电影院亏空50万英镑。"}},{"pos":"PHRASE 短语","cn":"（突然）发怒；震怒","en":"If you see red, you suddenly become very angry.","ex":{"en":"I didn't mean to break his nose. I just saw red.","cn":"我不是故意要打断他的鼻梁。我只是一时气急。"}},{"pos":"","cn":"","en":"like a red rag to a bull→see: ;"}]},"examples":[{"en":"He stammered something and went very red in the face.","cn":"他结结巴巴地说了些什么，脸涨得通红。"},{"en":"The company has plunged $37 million into the red.","cn":"公司负债已达 3 700 万元。"}]},"representative":{"media":{"uk":"media/uk/representative__gb_1.mp3","us":"media/us/representative__us_1.mp3"},"oxford":{"phon":"ˌreprɪˈzentətɪv","pos":"noun","senses":[{"en":"a person who has been chosen to speak or vote for somebody else or for a group of people, or to take the place of somebody else","cn":"代表","ex":{"en":"Our elected representatives in government should be doing something about this.","cn":"我们选出的政府代表应该对此采取一些行动。"}},{"en":"a person who works for a company and travels around selling its products","cn":"销售代表；销售代理；代销人","lab":"informal","ex":{"en":"a sales representative","cn":"销售代表"}},{"en":"a person who is typical of a particular group","cn":"典型人物；代表性人物","ex":{"en":"The singer is regarded as a representative of the youth of her generation.","cn":"这位歌手被看作是她那一代年轻人的典型代表。"}},{"en":"(in the US) a member of the House of Representatives, the Lower House of Congress; a member of the House of Representatives in the lower house of a state parliament","cn":"（美国）众议院议员"},{"en":"typical of a particular group of people; that is a typical example of something","cn":"典型的；有代表性的","ex":{"en":"Is a questionnaire answered by 500 people truly representative of the population as a whole?","cn":"由 500 人参加的问卷调查能真正代表所有民众吗？"},"pos":"adjective"},{"en":"containing or including examples of all the different types of people or things in a large group","cn":"代表各类人（或事物）的","g":"[usually before noun]","ex":{"en":"We interviewed a representative sample of teachers.","cn":"我们采访了一些教师代表。"},"pos":"adjective"},{"en":"consisting of people who have been chosen to speak or vote for the rest of a group","cn":"由代表组成的；代议制的","ex":{"en":"a representative democracy","cn":"代议制民主政体"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"代表;代理人","en":"A representative is a person who has been chosen to act or make decisions on behalf of another person or a group of people.","ex":{"en":"...trade union representatives","cn":"工会代表"}},{"pos":"N-COUNT 可数名词","cn":"销售代表;销售代理","en":"A representative is a person whose job is to sell a company's products or services, especially by travelling round and visiting other companies.","ex":{"en":"She had a stressful job as a sales representative.","cn":"作为一名销售代表，她的工作压力很大。"}},{"pos":"ADJ 形容词","cn":"由代表组成的;代议制的","en":"A representative group consists of a small number of people who have been chosen to make decisions on behalf of a larger group.","ex":{"en":"The new head of state should be chosen by an 87 member representative council.","cn":"新的国家元首应该由包括87名成员的代表委员会选出。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"典型的;有代表性的","en":"Someone who is typical of the group to which they belong can be described as representative .","ex":{"en":"He was in no way representative of dog-trainers in general.","cn":"他远不是一般意义上的驯狗师。"}},{"pos":"N-COUNT 可数名词","cn":"(美国)众议员","en":"In the United States, a Representative is a member of the House of Representatives, the less powerful of the two parts of Congress."}]},"examples":[{"en":"Is a questionnaire answered by 500 people truly representative of the population as a whole?","cn":"由 500 人参加的问卷调查能真正代表所有民众吗？"},{"en":"The singer is regarded as a representative of the youth of her generation.","cn":"这位歌手被看作是她那一代年轻人的典型代表。"}]},"rend":{"oxford":{"phon":"rend","pos":"verb","senses":[{"en":"to tear something apart with force or violence","cn":"撕开；撕碎","lab":"figurative","ex":{"en":"The women rend their clothes in grief.","cn":"妇女们悲痛地扯碎了自己的衣服。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"撕碎;撕裂;扯破","en":"To rend something means to tear it.","ex":{"en":"...pain that rends the heart.","cn":"钻心的疼痛"}},{"pos":"VERB 动词","cn":"(声音)响彻，刺破","en":"If a loud sound rends the air, it is sudden and violent.","ex":{"en":"He bellows, rends the air with anguish.","cn":"他咆哮着，痛苦的喊声划破长空。"}}]},"media":{"uk":"media/uk/rend__gb_1.mp3","us":"media/us/rend__us_1.mp3"},"examples":[{"en":"They rent their clothes in grief.","cn":"他们在悲痛之中扯碎了自己的衣服。"},{"en":"( figurative ) Loud screams rent the air.","cn":"高声的尖叫划破了天空。"}]},"retreat":{"media":{"uk":"media/uk/retreat__gb_1.mp3","us":"media/us/retreat__us_1.mp3"},"oxford":{"phon":"rɪˈtriːt","pos":"noun","senses":[{"en":"a movement away from a place or an enemy because of danger or defeat","cn":"撤退；退却","g":"[countable, usually singular, uncountable]","sc":"from danger/defeat","ex":{"en":"Napoleon’s retreat from Moscow","cn":"拿破仑从莫斯科的撤退"}},{"en":"an act of trying to escape from a particular situation to one that you think is safer or more pleasant","cn":"逃避；退避；躲避","g":"[countable, usually singular, uncountable]","sc":"escape","ex":{"en":"Is watching television a retreat from reality?","cn":"看电视是对现实的一种逃避吗？"}},{"en":"an act of changing a decision because of criticism or because a situation has become too difficult","cn":"（由于批评或环境过于恶劣）改变决定，退缩","g":"[countable, usually singular]","sc":"change of decision","ex":{"en":"The Senator made an embarrassing retreat from his earlier position.","cn":"这位参议员很尴尬地改变了他早先的立场。"}},{"en":"a quiet, private place that you go to in order to get away from your usual life","cn":"僻静处；隐居处","g":"[countable]","sc":"quiet place","ex":{"en":"a country retreat","cn":"乡间隐居处"}},{"en":"a period of time when somebody stops their usual activities and goes to a quiet place for prayer and thought; an organized event when people can do this","cn":"静修期间（或活动）","g":"[uncountable, countable]","sc":"quiet place","ex":{"en":"He went into retreat and tried to resolve the conflicts within himself.","cn":"他去静修并试图调节自己内心的矛盾冲突。"}},{"en":"to move away from a place or an enemy because you are in danger or because you have been defeated","cn":"退却；撤退","g":"[intransitive]","sc":"from danger/defeat","ex":{"en":"The army was forced to retreat after suffering heavy losses.","cn":"部队因伤亡惨重被迫撤退。"},"pos":"verb"},{"en":"to move away or back","cn":"离开；离去；退去；后退","g":"[intransitive]","sc":"move away/back","ex":{"en":"He watched her retreating figure.","cn":"他看着她的身影渐渐远去。"},"pos":"verb"},{"en":"to escape to a place that is quieter or safer","cn":"隐退；逃避；躲避","g":"[intransitive]","lab":"figurative","sc":"to quiet place","ex":{"en":"Bored with the conversation, she retreated to her bedroom.","cn":"她厌倦了这样的交谈，躲进了自己的卧室。"},"pos":"verb"},{"en":"to change your mind about something because of criticism or because a situation has become too difficult","cn":"（由于批评或环境过于恶劣）改变主意，退缩","g":"[intransitive]","sc":"change decision","ex":{"en":"The government had retreated from its pledge to reduce class sizes.","cn":"政府已经改变了缩小班级规模的承诺。"},"pos":"verb"},{"en":"to lose value","cn":"跌价","g":"[intransitive]","sc":"finance","ex":{"en":"Share prices retreated 45p to 538p.","cn":"股票价格下跌 45 便士，降到了 538 便士。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"退避;后退;离开","en":"If you retreat, you move away from something or someone.","ex":{"en":"'I've already got a job,' I said quickly, and retreated from the room","cn":"“我已经有了一份工作。”我马上说道，并从房间里退了出来。"}},{"pos":"VERB 动词","cn":"(军队)撤退，退却","en":"When an army retreats, it moves away from enemy forces in order to avoid fighting them.","ex":{"en":"The French, suddenly outnumbered, were forced to retreat","cn":"人数突然处于劣势的法军被迫撤退。"}},{"pos":"VERB 动词","cn":"放弃，远离（计划、生活方式等）；从…中隐退","en":"If you retreat from something such as a plan or a way of life, you give it up, usually in order to do something safer or less extreme.","ex":{"en":"I believe people should live in houses that allow them to retreat from the harsh realities of life","cn":"我认为人们所居住的房子应该能让他们远离残酷的现实生活。"}},{"pos":"N-COUNT 可数名词","cn":"隐居地;静养所","en":"A retreat is a quiet, isolated place that you go to in order to rest or to do things in private.","ex":{"en":"He spent yesterday hidden away in his country retreat.","cn":"他昨天躲在了他乡下的静养地。"}},{"pos":"PHRASE 短语","cn":"匆匆离开;仓皇撤退","en":"If you beat a retreat, you leave a place quickly in order to avoid an embarrassing or dangerous situation.","ex":{"en":"Cockburn decided it was time to beat a hasty retreat.","cn":"科伯恩认为到了该紧急撤退的时候了。"}}]},"examples":[{"en":"Share prices retreated 45p to 538p.","cn":"这股票价格下跌 45 便士，降到了 538 便士。"},{"en":"Bored with the conversation, she retreated to her bedroom.","cn":"她厌倦了这样的交谈，躲进了自己的卧室。"}]},"reporter":{"media":{"uk":"media/uk/reporter__gb_1.mp3","us":"media/us/reporter__us_1.mp3"},"oxford":{"phon":"rɪˈpɔːtə(r)","pos":"noun","senses":[{"en":"a person who collects and reports news for newspapers, radio or television","cn":"记者；通讯员","ex":{"en":"He leaked the story to a news reporter.","cn":"他把这个故事泄露给了一名新闻记者。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"记者","en":"A reporter is someone who writes news articles or who broadcasts news reports.","ex":{"en":"...a TV reporter.","cn":"电视记者"}}]},"examples":[{"en":"a reporter from the New York Times 《","cn":"纽约时报》的记者"},{"en":"a reporter from the New York Times","cn":""}]},"regeneration":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something develop and grow strong again","cn":""},{"en":"to grow again, or make something grow again","cn":""}]},"examples":[{"en":"efforts to regenerate the US economy","cn":"","src":"ld"},{"en":"The Marshall Plan sought to regenerate the shattered Europe of 1947.","cn":"","src":"ld"}],"media":{"uk":"media/uk/regeneration__gb_1.mp3","us":"media/us/regeneration__us_1.mp3"},"oxford":{"phon":"rɪˌdʒenəˈreɪʃn","pos":"noun","senses":[{"en":"the process of making an area, institution, etc. develop and grow strong again","cn":"使一个地区、机构等重新发展和壮大的过程","ex":{"en":"economic regeneration","cn":"经济复兴"}},{"en":"the process of growing again","cn":"（动植物组织的）再生","lab":"biology","ex":{"en":"the regeneration of cells in the body","cn":"身体细胞的再生"}}]}},"retrain":{"oxford":{"phon":"ˌriːˈtreɪn","pos":"verb","senses":[{"en":"to learn, or to teach somebody, a new type of work, a new skill, etc.","cn":"（接受）重新培养，再教育，再培训","ex":{"en":"She retrained as a teacher.","cn":"她接受了教师再培训。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（尤指为再就业）接受再培训，对…再培训","en":"If you retrain, or if someone retrains you, you learn new skills, especially in order to get a new job.","ex":{"en":"Why not retrain for a job which will make you happier?","cn":"为什么不接受新的培训，找一份让你更快乐的工作？"}}]},"media":{"uk":"media/uk/retrain__gb_1.mp3","us":"media/us/retrain__us_1.mp3"},"examples":[{"en":"Staff have been retrained to use the new technology.","cn":"为使员工学会运用新技术，对他们进行了再培训。"},{"en":"She retrained as a teacher.","cn":"她接受了教师再培训。"}]},"reaction":{"media":{"uk":"media/uk/reaction__gb_1.mp3","us":"media/us/reaction__us_1.mp3"},"oxford":{"phon":"riˈækʃn","pos":"noun","senses":[{"en":"what you do, say or think as a result of something that has happened","cn":"反应；回应","g":"[countable, uncountable]","sc":"to event/situation","ex":{"en":"to provoke/cause/get a reaction","cn":"激起／引起／得到反应"}},{"en":"a change in people’s attitudes or behaviour caused by disapproval of the attitudes, etc. of the past","cn":"（对旧观念等的）抗拒","g":"[countable, usually singular, uncountable]","sc":"change in attitudes","ex":{"en":"The return to traditional family values is a reaction against the permissiveness of recent decades.","cn":"传统家庭价值观的回归是对近几十年来放纵自由的一种反动。"}},{"en":"a response by the body, usually a bad one, to a drug, chemical substance, etc.","cn":"生理反应；副作用","g":"[countable, uncountable]","sc":"to drugs","ex":{"en":"If you have a bad reaction, discontinue use immediately.","cn":"如果有不良反应，请立即停止使用。"}},{"en":"the ability to move quickly in response to something, especially if in danger","cn":"反应能力","g":"[plural]","sc":"to danger","ex":{"en":"a skilled driver with quick reactions","cn":"反应敏捷的熟练司机"}},{"en":"a chemical change produced by two or more substances acting on each other","cn":"化学反应","g":"[countable, uncountable]","lab":"chemistry","sc":"science","ex":{"en":"a chemical reaction","cn":"化学反应"}},{"en":"a force shown by something in response to another force, which is of equal strength and acts in the opposite direction","cn":"反（作用）力","g":"[uncountable, countable]","lab":"physics","sc":"science","ex":{"en":"Action and reaction are equal and opposite.","cn":"作用和反作用是相等且相反的。"}},{"en":"opposition to social or political progress or change","cn":"反对；反动；阻碍","g":"[uncountable]","sc":"against progress","ex":{"en":"The forces of reaction made change difficult.","cn":"反动势力使得改革举步维艰。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"反应；回应；反响","en":"Your reaction to something that has happened or something that you have experienced is what you feel, say, or do because of it.","ex":{"en":"Reaction to the visit is mixed","cn":"对这次访问的反应不一。"}},{"pos":"N-COUNT 可数名词","cn":"反对;反抗;抵制","en":"A reaction against something is a way of behaving or doing something that is deliberately different from what has been done before.","ex":{"en":"All new fashion starts out as a reaction against existing convention","cn":"所有新时尚都是从打破现有常规开始的。"}},{"pos":"N-SING 单数名词","cn":"抵制；抵触","en":"If there is a reaction against something, it becomes unpopular.","ex":{"en":"Premature moves in this respect might well provoke a reaction against the reform","cn":"在这方面不成熟的举动很可能引发对改革的抵触情绪。"}},{"pos":"N-PLURAL 复数名词","cn":"反应力;应变能力","en":"Your reactions are your ability to move quickly in response to something, for example when you are in danger.","ex":{"en":"If his reactions are so slow, he shouldn't be in charge of a bus","cn":"如果他的反应太慢，就不应该开公交汽车。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"保守思想;反动思想","en":"Reaction is the belief that the political or social system of your country should not change.","ex":{"en":"Thus, he aided reaction and thwarted progress.","cn":"因此，他帮助反动派阻挠进步。"}},{"pos":"N-COUNT 可数名词","cn":"（化学）反应，变化","en":"A chemical reaction is a process in which two substances combine together chemically to form another substance.","ex":{"en":"Ozone is produced by the reaction between oxygen and ultraviolet light","cn":"臭氧由氧气和紫外线发生反应而产生。"}},{"pos":"N-COUNT 可数名词","cn":"过敏;不良反应","en":"If you have a reaction to a substance such as a drug, or to something you have touched, you are affected unpleasantly or made ill by it.","ex":{"en":"Every year, 5000 people have life-threatening reactions to anaesthetics","cn":"每年有5,000人对麻醉剂产生致命反应。"}}]},"examples":[{"en":"A spokesman said the changes were not in reaction to the company's recent losses.","cn":"一位发言人说，这些变动不是针对公司最近的损失而作出的反应。"},{"en":"The return to traditional family values is a reaction against the permissiveness of recent decades.","cn":"传统家庭价值观的恢复是对近几十年来放纵自由的一种改变。"}]},"remaining":{"media":{"uk":"media/uk/remaining__gb_1.mp3","us":"media/us/remaining__us_1.mp3"},"oxford":{"phon":"rɪˈmeɪnɪŋ","pos":"adjective","senses":[{"en":"still needing to be done or dealt with","cn":"仍需做的；还需处理的","ex":{"en":"The remaining twenty patients were transferred to another hospital.","cn":"其余的二十名病人被转送到另一家医院去了。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"余下的;剩余的","en":"The remaining things or people out of a group are the things or people that still exist, are still present, or have not yet been dealt with.","ex":{"en":"The three parties will meet next month to work out remaining differences","cn":"三方将在下个月会面，以解决余下的分歧。"}}]},"examples":[{"en":"The remaining twenty patients were transferred to another hospital.","cn":"其余的二十名病人给转送到另一家医院去了。"},{"en":"Any remaining tickets for the concert will be sold on the door.","cn":"其余门票均于音乐会时即场发售。"}],"base":"remain"},"reckon":{"media":{"uk":"media/uk/reckon__gb_1.mp3","us":"media/us/reckon__us_1.mp3"},"oxford":{"phon":"ˈrekən","pos":"verb","senses":[{"en":"to think something or have an opinion about something","cn":"想；认为","g":"[transitive, intransitive]","lab":"especially British English, informal，，","ex":{"en":"I reckon (that) I’m going to get that job.","cn":"我认为我会得到那份工作。"}},{"en":"to be generally considered to be something","cn":"被普遍认为是；被看作是","g":"[transitive]","ex":{"en":"Children are reckoned to be more sophisticated nowadays.","cn":"人们认为今天的孩子比过去世故。"}},{"en":"to expect to do something","cn":"料想；预计；指望","g":"[transitive]","lab":"British English, informal，，","ex":{"en":"We reckon to finish by ten.","cn":"我们预计十点钟以前结束。"}},{"en":"to calculate an amount, a number, etc.","cn":"估算；估计；计算","g":"[transitive]","ex":{"en":"I could see him reckoning the cost as I spoke.","cn":"当我说话时，我可以看到他正在计算成本。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"料想;估计;认为","en":"If you reckon that something is true, you think that it is true.","ex":{"en":"Toni reckoned that it must be about three o'clock","cn":"托妮估计当时肯定是3点钟左右。"}},{"pos":"VERB 动词","cn":"认为…；把…当作","en":"If you say that something is reckoned to be true, you mean that people think that it is true.","ex":{"en":"The sale has been held up because the price is reckoned to be too high.","cn":"销售陷入停滞，因为大家认为价格太高了。"}},{"pos":"VERB 动词","cn":"预计；料想；期望","en":"If you say that someone reckons to do something, you mean that they expect to do it.","ex":{"en":"The merged banks reckon to raise 4 billion dollars of new equity next year","cn":"几家银行合并后明年有望增发40亿美元的新股。"}},{"pos":"VERB 动词","cn":"估算;估计","en":"If something is reckoned to be a particular figure, it is calculated to be roughly that amount.","ex":{"en":"The star's surface temperature is reckoned to be minus 75 degrees Celsius","cn":"这颗恒星的表面温度估计在零下75摄氏度左右。"}},{"pos":"","cn":"","en":"相关词组：reckon on reckon with reckon without"}]},"examples":[{"en":"He'll be famous one day. What do you reckon (= do you agree)?","cn":"总有一天，他会成为名人的。你觉得呢？"},{"en":"They were already a political force to be reckoned with.","cn":"他们已经成为一支不容忽视的政治力量。"}]},"realm":{"media":{"uk":"media/uk/realm__gb_1.mp3","us":"media/us/realm__us_1.mp3"},"oxford":{"phon":"relm","pos":"noun","senses":[{"en":"an area of activity, interest or knowledge","cn":"领域；场所","ex":{"en":"in the realm of literature","cn":"在文学领域内"}},{"en":"a country ruled by a king or queen","cn":"王国","lab":"formal","ex":{"en":"The Crown maintains armed forces for the defence of the realm.","cn":"国王拥有武装部队来保卫王国。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（活动、兴趣或思想的）领域，范围","en":"You can use realm to refer to any area of activity, interest, or thought.","ex":{"en":"...the realm of politics","cn":"政治领域"}},{"pos":"N-COUNT 可数名词","cn":"王国","en":"A realm is a country that has a king or queen.","ex":{"en":"Defence of the realm is crucial.","cn":"王国的国防至关重要。"}},{"pos":"PHRASE 短语","cn":"可能的范围","en":"If you say that something is not beyond the realms of possibility, you mean that it is possible.","ex":{"en":"A fall of 50 per cent or more on prices is not beyond the realms of possibility","cn":"降价50%或更多并非不可能。"}}]},"examples":[{"en":"At the end of the speech he seemed to be moving into the realms of fantasy.","cn":"讲话的最后，他似乎进入了虚幻的境地。"},{"en":"A successful outcome is not beyond the realms of possibility.","cn":"最后取得成功并非没有可能。"}]},"recommends":{"lemma":"recommend"},"refocus":{"oxford":{"phon":"ˌriːˈfəʊkəs","pos":"verb","senses":[{"en":"to give attention, effort, etc. to something new or different","cn":"将（注意力、精力等）转向；调整…的重点","g":"[intransitive, transitive]","ex":{"en":"Policy must refocus on people instead of places.","cn":"政策重心必须改变，针对人而非地方。"}},{"en":"to adapt or be changed again so that things can be seen clearly; to change something again so that you can see things clearly","cn":"（使）重新聚焦；调整…的焦距","g":"[intransitive, transitive]"}]},"media":{"uk":"media/uk/refocus__gb_1.mp3","us":"media/us/refocus__us_2.mp3"},"examples":[{"en":"We need to refocus attention on the real issues facing this country.","cn":"我们需要将注意力转向国家所面临的实际问题。"},{"en":"Policy must refocus on people instead of places.","cn":"政策重心必须改变，针对人而非地方。"}]},"readings":{"lemma":"read","media":{"uk":"media/uk/reading__gb_1.mp3","us":"media/us/reading__us_1.mp3"}},"regulated":{"lemma":"regulate"},"renowned":{"media":{"uk":"media/uk/renowned__gb_1.mp3","us":"media/us/renowned__us_1.mp3"},"oxford":{"phon":"rɪˈnaʊnd","pos":"adjective","senses":[{"en":"famous and respected","cn":"有名的；闻名的；受尊敬的","ex":{"en":"a renowned author","cn":"著名的作家"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有名的;有声望的","en":"A person or place that is renowned for something, usually something good, is well known because of it.","ex":{"en":"The area is renowned for its Romanesque churches","cn":"这个地区以其罗马式的教堂闻名。"}}]},"examples":[{"en":"It is renowned as one of the region's best restaurants.","cn":"这是本地区最好的饭店之一。"},{"en":"She is renowned for her patience.","cn":"她的耐心是出了名的。"}]},"retirement":{"media":{"uk":"media/uk/retirement__gb_1.mp3","us":"media/us/retirement__us_1.mp3"},"oxford":{"phon":"rɪˈtaɪəmənt","pos":"noun","senses":[{"en":"the fact of leaving your job and stopping work, usually because you have reached a particular age; the time when you do this","cn":"退休；退职；退休年龄","g":"[uncountable, countable]","lab":"British English","ex":{"en":"At 60, he was now approaching retirement.","cn":"他 60 岁了，就要退休了。"}},{"en":"the period of your life after you have stopped work, usually because you have reached a particular age","cn":"退休生活","g":"[uncountable, singular]","lab":"often ironic) 102／23 （） 102／23 （）","ex":{"en":"He provided for a comfortable retirement by selling the business.","cn":"他把企业卖掉，过上了舒适的退休生活。"}},{"en":"the act of stopping a particular type of work, especially in sport, politics, etc.; the period of your life after a career in sport, politics, etc.","cn":"（尤指从体育、政治等方面的）退出（期），退役（期），退职（期）","g":"[uncountable]","ex":{"en":"He announced his retirement from football.","cn":"他宣布退出足球运动。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"退休;退休年龄","en":"Retirement is the time when a worker retires.","ex":{"en":"...the proportion of the population who are over retirement age","cn":"超过退休年龄的人口比例"}},{"pos":"N-UNCOUNT 不可数名词","cn":"退休期间;退休生活","en":"A person's retirement is the period in their life after they have retired.","ex":{"en":"...financial support for the elderly during retirement.","cn":"为退休期间的老年人提供的经济支持"}}]},"examples":[{"en":"Up to a third of one's life is now being spent in retirement.","cn":"现在人们一生中能有三分之一的时间过退休生活。"},{"en":"We all wish you a long and happy retirement.","cn":"我们大家祝愿你的退休生活长久而幸福。"}]},"ref":{"collins":{"senses":[{"pos":"","cn":"档案编号;文件编号","en":"Ref is an abbreviation for (缩略=) reference. It is written in front of a code at the top of business letters and documents. The code refers to a file where all the letters and documents about the same matter are kept.","ex":{"en":"Our Ref: JAH/JW.","cn":"我们的编号: JAH/JW。"}},{"pos":"N-COUNT 可数名词","cn":"（比赛中的）裁判","en":"The ref in a sports game, such as football or boxing, is the same as the referee.","ex":{"en":"The ref gave a penalty and Zidane scored.","cn":"裁判判罚点球，齐达内操刀命中。"}}]},"media":{"uk":"media/uk/ref__gb_1.mp3","us":"media/us/ref__us_1.mp3"},"examples":[{"en":"The game's not over till the ref blows the whistle.","cn":"裁判吹响哨子，比赛才算结束。"},{"en":"The game was badly reffed.","cn":"这场比赛的裁判糟透了。"}],"oxford":{"phon":"ref","pos":"noun","senses":[{"en":"the official who controls the game in some sports","cn":"（某些体育比赛的）裁判，裁判员","ex":{"en":"The game's not over till the ref blows the whistle.","cn":"裁判吹响哨子，比赛才算结束。"}},{"en":"reference (used especially in business as a way of identifying something such as a document)","cn":"文件编号（尤用于商业文件分类）","ex":{"en":"our ref.: 3498","cn":"我方编号：3498"},"pos":"abbreviation"},{"en":"to act as the ref in a game","cn":"当裁判","ex":{"en":"The game was badly reffed.","cn":"这场比赛的裁判糟透了。"},"pos":"verb"}]}},"realistic":{"media":{"uk":"media/uk/realistic__gb_1.mp3","us":"media/us/realistic__us_1.mp3"},"oxford":{"phon":"ˌriːəˈlɪstɪk","pos":"adjective","senses":[{"en":"accepting in a sensible way what it is actually possible to do or achieve in a particular situation","cn":"现实的；实际的；实事求是的","ex":{"en":"a realistic assessment/approach/view","cn":"实事求是的评估／方法／观点"}},{"en":"sensible and appropriate; possible to achieve","cn":"明智的；恰如其分的；能够实现的","ex":{"en":"a realistic prospect/chance/possibility","cn":"现实的前景／机会／可能性"}},{"en":"representing things as they are in real life","cn":"逼真的；栩栩如生的","ex":{"en":"a realistic portrayal/depiction/picture","cn":"逼真的描绘"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"现实的;务实的;实事求是的","en":"If you are realistic about a situation, you recognize and accept its true nature and try to deal with it in a practical way.","ex":{"en":"Police have to be realistic about violent crime","cn":"警方需要对暴力犯罪持务实态度。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（目标或目的等）现实的，明智的，能实现的","en":"Something such as a goal or target that is realistic is one which you can sensibly expect to achieve.","ex":{"en":"Multi-party elections are scheduled for sometime next year but many doubt that this is a realistic goal","cn":"多党选举计划在明年某个时间进行，但是许多人怀疑这个目标是否现实。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（绘画、小说或电影）现实主义风格的，写实的，逼真的","en":"You say that a painting, story, or film is realistic when the people and things in it are like people and things in real life.","ex":{"en":"...extraordinarily realistic paintings of Indians","cn":"关于印第安人的极为逼真的绘画"}}]},"examples":[{"en":"We try to make these training courses as realistic as possible.","cn":"我们努力使这些训练课程尽可能地贴近实际情况。"},{"en":"We have to be realistic about our chances of winning.","cn":"我们必须实事求是地估计我们获胜的可能性。"}]},"recruit":{"media":{"uk":"media/uk/recruit__gb_1.mp3","us":"media/us/recruit__us_1.mp3"},"oxford":{"phon":"rɪˈkruːt","pos":"verb","senses":[{"en":"to find new people to join a company, an organization, the armed forces, etc.","cn":"吸收（新成员）；征募（新兵）","g":"[transitive, intransitive]","lab":"British English","ex":{"en":"We are trying to recruit officers from more diverse backgrounds.","cn":"我们正在努力招募来自更多元化背景的官员。"}},{"en":"to persuade somebody to do something, especially to help you","cn":"动员…（提供帮助）","g":"[transitive]","ex":{"en":"We were recruited to help peel the vegetables.","cn":"我们被找来帮着给蔬菜去皮。"}},{"en":"to form a new army, team, etc. by persuading new people to join it","cn":"（通过招募）组成，组建","g":"[transitive]","ex":{"en":"to recruit a task force","cn":"组建特遣部队"}},{"en":"a person who has recently joined the armed forces or the police","cn":"新兵；新警员","ex":{"en":"the training of new recruits","cn":"新兵训练"},"pos":"noun"},{"en":"a person who joins an organization, a company, etc.","cn":"新成员","ex":{"en":"They are stepping up attempts to attract new recruits to the nursing profession.","cn":"他们正在加紧努力吸引新员工加入护理行业。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"招收；招募；征召","en":"If you recruit people for an organization, you select them and persuade them to join it or work for it.","ex":{"en":"The police are trying to recruit more black and Asian officers","cn":"警方正在试图招募更多黑人和亚裔警官。"}},{"pos":"N-COUNT 可数名词","cn":"新手；新兵；新成员","en":"A recruit is a person who has recently joined an organization or an army."}]},"examples":[{"en":"The police are trying to recruit more officers from ethnic minorities.","cn":"警察机关正试图从少数民族中征募更多的新警员。"},{"en":"They recruited several new members to the club.","cn":"他们吸收了几名新成员进入俱乐部。"}]},"realism":{"media":{"uk":"media/uk/realism__gb_1.mp3","us":"media/us/realism__us_1.mp3"},"oxford":{"phon":"ˈriːəlɪzəm","pos":"noun","senses":[{"en":"a way of seeing, accepting and dealing with situations as they really are without being influenced by your emotions or false hopes","cn":"务实作风；现实主义方式","ex":{"en":"There was a new mood of realism among the leaders at the peace talks.","cn":"参加和平谈判的领导人之间有着一种务实的新气氛。"}},{"en":"the quality of being very like real life","cn":"现实性；逼真","ex":{"en":"the gritty realism of the new drama serial","cn":"新连续剧的坚韧现实主义"}},{"en":"a style in art or literature that shows things and people as they are in real life","cn":"（文艺的）现实主义风格，现实主义","ex":{"en":"realism in Dutch art","cn":"荷兰艺术中的现实主义"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"现实主义；现实态度；务实精神","en":"When people show realism in their behaviour, they recognize and accept the true nature of a situation and try to deal with it in a practical way.","ex":{"en":"It was time now to show more political realism","cn":"现在是拿出更多政治务实精神的时候了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（绘画、小说或电影的）现实主义","en":"If things and people are presented with realism in paintings, stories, or films, they are presented in a way that is like real life.","ex":{"en":"Greene's stories had an edge of realism that made it easy to forget they were fiction","cn":"格林的小说带有现实主义色彩，很容易让人忘记它们是虚构的。"}}]},"examples":[{"en":"There was a new mood of realism among the leaders at the peace talks.","cn":"参加和平谈判的领导人之间有着一种务实的新气氛。"},{"en":"He has hope, but also a scientist’s sense of realism.","cn":"他抱着希望﹐但同时又有着一个科学家的务实感。"}]},"responded":{"lemma":"respond","media":{"uk":"media/uk/respond__gb_1.mp3","us":"media/us/respond__us_1.mp3"}},"refugees":{"lemma":"refugee"},"rear":{"media":{"uk":"media/uk/rear__gb_1.mp3","us":"media/us/rear__us_1.mp3"},"oxford":{"phon":"rɪə(r)","pos":"adjective","senses":[{"en":"at or near the back of something","cn":"后面的；后部的","ex":{"en":"front and rear windows","cn":"前面和后面的窗户"}},{"en":"the back part of something","cn":"后部","g":"[singular]","ex":{"en":"A trailer was attached to the rear of the truck.","cn":"卡车后面挂了一辆拖车。"},"pos":"noun"},{"en":"the part of the body that you sit on","cn":"屁股","g":"[countable, usually singular]","lab":"informal","ex":{"en":"a kick in the rear","cn":"踢了一下屁股"},"pos":"noun"},{"en":"to care for young children or animals until they are fully grown","cn":"抚养；养育；培养","g":"[transitive]","ex":{"en":"She reared a family of five on her own.","cn":"她一个人养活五个孩子。"},"pos":"verb"},{"en":"to keep and breed (= produce young from) animals or birds, for example on a farm","cn":"饲养；养殖","g":"[transitive]","ex":{"en":"to rear cattle","cn":"养牛"},"pos":"verb"},{"en":"to raise itself on its back legs, with the front legs in the air","cn":"用后腿直立","g":"[intransitive]","ex":{"en":"The horse reared, throwing its rider.","cn":"这匹马后腿直立，将骑手摔下。"},"pos":"verb"},{"en":"to seem to lean over you, especially in a way that makes you feel frightened","cn":"（尤指可怖地）巍然耸立","g":"[intransitive]","ex":{"en":"The great bulk of the building reared up against the night sky.","cn":"夜幕下，巨大的高楼显得阴森森的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（建筑物或车辆的）后部，后面，背面","en":"The rear of something such as a building or vehicle is the back part of it.","ex":{"en":"He settled back in the rear of the taxi.","cn":"他靠坐在出租车的后排座上。"}},{"pos":"N-SING 单数名词","cn":"（队列的）尾部，最后一个","en":"If you are at the rear of a moving line of people, you are the last person in it.","ex":{"en":"Musicians played at the front and rear of the procession","cn":"乐师们在队前和队尾表演。"}},{"pos":"N-COUNT 可数名词","cn":"臀部;屁股","en":"Your rear is the part of your body that you sit on.","ex":{"en":"I turned away from the phone to see Lewis pat a waitress on her rear.","cn":"我打完电话后转过头，看见刘易斯拍了拍一个女招待的屁股。"}},{"pos":"VERB 动词","cn":"抚养;养育;养大","en":"If you rear children, you look after them until they are old enough to look after themselves.","ex":{"en":"She reared sixteen children, six her own and ten her husband's","cn":"她养大了16个孩子，其中6个是她亲生的，10个是她丈夫带来的。"}},{"pos":"VERB 动词","cn":"饲养（小动物）","en":"If you rear a young animal, you keep and look after it until it is old enough to be used for work or food, or until it can look after itself.","ex":{"en":"She spends a lot of time rearing animals.","cn":"她花费大量时间饲养动物。"}},{"pos":"VERB 动词","cn":"（马）用后腿直立，暴跳","en":"When a horse rears, it moves the front part of its body upwards, so that its front legs are high in the air and it is standing on its back legs.","ex":{"en":"The horse reared and threw off its rider.","cn":"那匹马前蹄腾空向后仰，把骑手摔了下去。"}},{"pos":"VERB 动词","cn":"高耸，耸立（在眼前）","en":"If you say that something such as a building or mountain rears above you, you mean that is very tall and close to you.","ex":{"en":"The exhibition hall reared above me behind a high fence","cn":"高高的围墙后面，展览大厅耸立在我面前。"}},{"pos":"PHRASE 短语","cn":"殿后","en":"If a person or vehicle is bringing up the rear, they are the last person or vehicle in a moving line of them.","ex":{"en":"...police motorcyclists bringing up the rear of the procession.","cn":"摩托骑警行进在队伍最后"}},{"pos":"PHRASE 短语","cn":"（令人不快之物）显现，露头，显露","en":"If something unpleasant rears its head or rears its ugly head, it becomes visible or noticeable.","ex":{"en":"The threat of strikes reared its head again this summer","cn":"今年夏天又显现出了罢工的势头。"}},{"pos":"","cn":"","en":"相关词组：rear up"}]},"examples":[{"en":"A high gate blocks the only entrance to the rear.","cn":"一座高大的门挡住了通往后面的唯一入口。"},{"en":"I was the son of sailors and reared on stories of the sea.","cn":"我是水手的儿子，是听海的故事长大的。"}]},"reviews":{"lemma":"review"},"relive":{"media":{"uk":"media/uk/relive__gb_1.mp3","us":"media/us/relive__us_1.mp3"},"oxford":{"phon":"ˌriːˈlɪv","pos":"verb","senses":[{"en":"to experience something again, especially in your imagination","cn":"（尤指在想象中）再次体验，重温；回味","ex":{"en":"He relives the horror of the crash every night in his dreams.","cn":"每天晚上他都会梦见那次撞车的可怕情景。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（在记忆或想象中）再次体验，回味，重温","en":"If you relive something that has happened to you in the past, you remember it and imagine that you are experiencing it again.","ex":{"en":"There is no point in reliving the past","cn":"回味过去没有任何意义。"}}]},"examples":[{"en":"He relives the horror of the crash every night in his dreams.","cn":"每天晚上他都会梦见那次撞车的可怕情景。"},{"en":"The girls watch the tape, eager to relive their victory against UCLA.","cn":"女孩们观看录像带﹐急于重温打败加州大学洛杉矶分校队的胜利时刻。"}]},"renting":{"lemma":"rent","media":{"uk":"media/uk/rent__gb_2.mp3","us":"media/us/rent__us_2.mp3"}},"really":{"media":{"uk":"media/uk/really__gb_1.mp3","us":"media/us/really__us_1.mp3"},"oxford":{"phon":"ˈriːəli","pos":"adverb","senses":[{"en":"used to emphasize an adjective or adverb","cn":"（加强形容词或副词的语气）","ex":{"en":"That's a really good idea.","cn":"这是一个非常好的想法。"}},{"en":"used to emphasize something you are saying or an opinion you are giving","cn":"（强调观点等）确实，的确","ex":{"en":"I really want to go home now.","cn":"我真想现在就回家。"}},{"en":"used to express interest in or surprise at what somebody is saying","cn":"（答话时表示感兴趣或惊讶）","ex":{"en":"‘We're going to Japan next month.’ ‘Oh, really?’","cn":"“我们下个月要去日本。”“哦，真的吗？”"}},{"en":"used to say what is actually the fact or the truth about something","cn":"（表明事实或真相）事实上，真正地，真实地","ex":{"en":"What do you really think about it?","cn":"你到底对这事怎么看？"}},{"en":"used, often in negative sentences, to reduce the force of something you are saying","cn":"（常用于否定句以减弱语气）","ex":{"en":"I don't really agree with that.","cn":"对此我不太赞同。"}},{"en":"used in questions and negative sentences when you want somebody to say ‘no’","cn":"（用于疑问句和否定句，期望对方给以否定的答复）","ex":{"en":"Do you really expect me to believe that?","cn":"你真以为我会相信吗？"}},{"en":"used to show that you think something that somebody has done is bad","cn":"（表示不赞同某人所为）","ex":{"en":"Really, you could have told us before.","cn":"真是的，其实你大可事先跟我们说一声的。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（表示强调）的确，确实","en":"You can use really to emphasize a statement.","ex":{"en":"I'm very sorry. I really am","cn":"我很抱歉。真的。"}},{"pos":"ADV 副词","cn":"（放在形容词或副词前表示强调）极其，非常","en":"You can use really to emphasize an adjective or adverb.","ex":{"en":"It was really good","cn":"好极了。"}},{"pos":"ADV 副词","cn":"实际上；实在；事实上","en":"You use really when you are discussing the real facts about something, in contrast to the ones someone wants you to believe.","ex":{"en":"My father didn't really love her","cn":"我父亲实际上并不爱她。"}},{"pos":"ADV 副词","cn":"（用于问句或否定句中引出否定回答）真的，说实在的","en":"People use really in questions and negative statements when they want you to answer 'no'.","ex":{"en":"Do you really think he would be that stupid?","cn":"你真的认为他会那么蠢吗？"}},{"pos":"ADV 副词","cn":"真正地（开始）","en":"If you refer to a time when something really begins to happen, you are emphasizing that it starts to happen at that time to a much greater extent and much more seriously than before.","ex":{"en":"That's when the pressure really started","cn":"那就是真正开始有压力的时候。"}},{"pos":"ADV 副词","cn":"（放在否定陈述句中减轻语气）真的，真正，其实","en":"People sometimes use really to slightly reduce the force of a negative statement.","ex":{"en":"I'm not really surprised","cn":"我其实并不惊讶。"}},{"pos":"ADV 副词","cn":"（放在句中表示不那么确定）真的，还是","en":"People sometimes add really to statements in order to make them less definite and more uncertain.","ex":{"en":"She is a quiet girl really","cn":"她算得上是个蛮安静的女孩。"}},{"pos":"ADV 副词","cn":"（表示惊讶）还真是，还真的","en":"People use really to show that they are surprised or that the person they are speaking to may be surprised about something.","ex":{"en":"Actually it was quite good really","cn":"事实上那还真的不错呢。"}},{"pos":"CONVENTION 惯用语","cn":"（对某人所说的话表示怀疑或不相信）真的，是吗","en":"You can say really to express surprise or disbelief at what someone has said.","ex":{"en":"'We discovered it was totally the wrong decision.' — 'Really?'","cn":"“我们发现那完全是个错误的决定。”——“真的吗？”"}},{"pos":"CONVENTION 惯用语","cn":"（用在对话中表示对对方所说的内容感兴趣）是吗，真的吗","en":"You can say 'really' in a conversation to show that you are interested in what someone is saying.","ex":{"en":"'We had a very interesting chat.' — 'Really? About what?'","cn":"“我们相谈甚欢。”——“是吗？谈了些什么？”"}},{"pos":"EXCLAM 感叹语","cn":"（表示有些恼怒或厌烦）说真的，坦白讲","en":"Some people say really when they are slightly annoyed or offended by something.","ex":{"en":"Really, Mr Riss, I expected better of you.","cn":"坦白讲，里斯先生，我没想到你会那样。"}}]},"examples":[{"en":"‘We're going to Japan next month.’ ‘Oh, really?’ “","cn":"我们下个月要去日本。” “哦，真的吗？”"},{"en":"Really, you could have told us before.","cn":"真是的，其实你大可事先跟我们说一声的。"}]},"reserve":{"media":{"uk":"media/uk/reserve__gb_1.mp3","us":"media/us/reserve__us_1.mp3"},"oxford":{"phon":"rɪˈzɜːv","pos":"noun","senses":[{"en":"a supply of something that is available to be used in the future or when it is needed","cn":"储备（量）；贮藏（量）","g":"[countable, usually plural]","sc":"supply","ex":{"en":"cash/foreign currency reserves","cn":"现金／外汇储备"}},{"en":"a piece of land that is a protected area for animals, plants, etc.","cn":"（动植物）保护区；自然保护区","g":"[countable]","lab":"North American English also","sc":"protected land","ex":{"en":"a wildlife/forest reserve","cn":"野生生物／森林保护区"}},{"en":"an area of land in the US that is kept separate for native North Americans to live in","cn":"（美国为美洲土著居民划出的）保留地，居留地","g":"[countable]","sc":"protected land"},{"en":"the quality that somebody has when they do not talk easily to other people about their ideas, feelings, etc.","cn":"内向；寡言少语；矜持","g":"[uncountable]","sc":"quality/feeling","ex":{"en":"She found it difficult to make friends because of her natural reserve.","cn":"她因天性矜持很难交到朋友。"}},{"en":"a feeling that you do not want to accept or agree to something, etc. until you are quite sure that it is all right to do so","cn":"谨慎；保留","g":"[uncountable]","lab":"formal","sc":"quality/feeling","ex":{"en":"Any contract should be treated with reserve until it has been checked.","cn":"任何契约在经过核实之前都应谨慎对待。"}},{"en":"an extra player who plays in a team when one of the other players is injured or not available to play","cn":"替补队员；后备队员","g":"[countable]","sc":"in sport"},{"en":"a team that is below the level of the main team","cn":"替补队；预备队；后备队","g":"[plural]","sc":"in sport"},{"en":"an extra military force, etc. that is not part of a country’s regular forces, but is available to be used when needed","cn":"预备役部队；后备部队","g":"[singular]","sc":"military force","ex":{"en":"the Army Reserve","cn":"预备役部队"}},{"en":"the lowest price that somebody will accept for something, especially something that is sold at an auction","cn":"（尤指拍卖中的）底价，最低价","g":"[countable]","sc":"price","ex":{"en":"The painting failed to reach to its reserve and was withdrawn from the sale.","cn":"这幅画未能达到其保留价，因此被从拍卖中撤回。"}},{"en":"to ask for a seat, table, room, etc. to be available for you or somebody else at a future time","cn":"预订，预约（座位、席位、房间等）","ex":{"en":"I'd like to reserve a table for three for eight o'clock.","cn":"我想预订八点钟供三人用餐的桌位。"},"pos":"verb"},{"en":"to keep something for somebody/something, so that it cannot be used by any other person or for any other reason","cn":"保留；预留","ex":{"en":"These seats are reserved for special guests.","cn":"这些座位是留给贵宾的。"},"pos":"verb"},{"en":"to have or keep a particular power","cn":"拥有，保持，保留（某种权力）","lab":"law","ex":{"en":"The management reserves the right to refuse admission.","cn":"管理部门有权拒绝接收。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"保留;留出;预留","en":"If something is reserved for a particular person or purpose, it is kept specially for that person or purpose.","ex":{"en":"A double room with a balcony overlooking the sea had been reserved for him","cn":"特地为他预留了一间带阳台的海景双人房。"}},{"pos":"VERB 动词","cn":"预订;保留;预约","en":"If you reserve something such as a table, ticket, or magazine, you arrange for it to be kept specially for you, rather than sold or given to someone else.","ex":{"en":"I'll reserve a table for five","cn":"我要预订一张5人的桌子。"}},{"pos":"N-COUNT 可数名词","cn":"储备;储存物资;储藏量","en":"A reserve is a supply of something that is available for use when it is needed.","ex":{"en":"The Gulf has 65 per cent of the world's oil reserves","cn":"海湾地区拥有全世界65％的石油储藏。"}},{"pos":"N-COUNT 可数名词","cn":"预备队员;替补队员","en":"In sports, a reserve is someone who is available to play as part of a team if one of the members is ill or cannot play.","ex":{"en":"He ended up as a reserve, but still qualified for a team gold medal.","cn":"他最后成了替补队员，但仍有资格获得团体金牌。"}},{"pos":"N-COUNT 可数名词","cn":"（野生生物）保护区","en":"A nature reserve is an area of land where the animals, birds, and plants are officially protected.","ex":{"en":"Marine biologists are calling for Cardigan Bay to be created a marine nature reserve to protect the dolphins.","cn":"海洋生物学家号召将卡迪根湾建成一个海洋自然保护区，以保护那里的海豚。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"寡言;矜持;内敛","en":"If someone shows reserve, they keep their feelings hidden.","ex":{"en":"The subject is one which must be discussed with reserve","cn":"对这个话题必须进行慎重的讨论。"}},{"pos":"PHRASE 短语","cn":"留出备用;保留;储存","en":"If you have something in reserve, you have it available for use when it is needed.","ex":{"en":"...the bottle of whisky that he kept in reserve","cn":"他特地留的那瓶威士忌"}},{"pos":"N-COUNT 可数名词","cn":"后备军;预备役部队","en":"A military reserve is a group of soldiers who are ready to join a military operation if they are needed."},{"pos":"","cn":"","en":"to reserve judgment→see: ; to reserve the right→see: ;"}]},"examples":[{"en":"Any contract should be treated with reserve until it has been checked.","cn":"任何契约在经过核实之前都应谨慎对待。"},{"en":"I'd prefer to reserve (my) judgement (= not make a decision) until I know all the facts.","cn":"在了解全部事实之前我不想发表意见。"}]},"requested":{"lemma":"request","media":{"uk":"media/uk/request__gb_1.mp3","us":"media/us/request__us_1.mp3"}},"replace":{"media":{"uk":"media/uk/replace__gb_1.mp3","us":"media/us/replace__us_1.mp3"},"oxford":{"phon":"rɪˈpleɪs","pos":"verb","senses":[{"en":"to be used instead of somebody/something else; to do something instead of somebody/something else","cn":"代替；取代","ex":{"en":"The new design will eventually replace all existing models.","cn":"新的设计最终将会取代全部现有的型号。"}},{"en":"to remove somebody/something and put another person or thing in their place","cn":"（用…）替换；（以…）接替","ex":{"en":"He will be difficult to replace when he leaves.","cn":"他离开后，他的位置很难有人接替。"}},{"en":"to change something that is old, damaged, etc. for a similar thing that is newer or better","cn":"更换；更新","ex":{"en":"We're thinking of replacing our phone system.","cn":"我们正在考虑更新我们的电话系统。"}},{"en":"to put something back in the place where it was before","cn":"把…放回原处","ex":{"en":"I replaced the cup carefully in the saucer.","cn":"我小心翼翼地将杯子放回茶碟。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"替换;取代;代替","en":"If one thing or person replaces another, the first is used or acts instead of the second.","ex":{"en":"The council tax replaces the poll tax next April.","cn":"市政税在明年4月将取代人头税。"}},{"pos":"VERB 动词","cn":"以…取代;以…接替","en":"If you replace one thing or person with another, you put something or someone else in their place to do their job.","ex":{"en":"I clean out all the grease and replace it with oil so it works better in very low temperatures","cn":"我把所有的油脂清除干净，然后用油来代替，从而使它在低温条件下运转得更好。"}},{"pos":"VERB 动词","cn":"换下(坏的);以新的替换","en":"If you replace something that is broken, damaged, or lost, you get a new one to use instead.","ex":{"en":"The shower that we put in a few years back has broken and we cannot afford to replace it.","cn":"我们几年前安装的淋浴器坏了，但买不起新的来换。"}},{"pos":"VERB 动词","cn":"把…放回(原处)","en":"If you replace something, you put it back where it was before.","ex":{"en":"The line went dead. Whitlock replaced the receiver","cn":"线路中断了，惠特洛克把听筒放回原处。"}}]},"examples":[{"en":"It is not a good idea to miss meals and replace them with snacks.","cn":"不吃正餐，改吃点心，这不是什么好主意。"},{"en":"The new design will eventually replace all existing models.","cn":"新的设计最终将会取代所有现有的型号。"}]},"renewable":{"media":{"uk":"media/uk/renewable__gb_1.mp3","us":"media/us/renewable__us_1.mp3"},"oxford":{"phon":"rɪˈnjuːəbl","pos":"adjective","senses":[{"en":"that is replaced naturally or controlled carefully and can therefore be used without the risk of using it all up","cn":"可更新的；可再生的；可恢复的","g":"[usually before noun]","lab":"especially British English","ex":{"en":"renewable sources of energy such as wind and solar power","cn":"像风力和太阳能这种用之不竭的能源"}},{"en":"that can be made legally acceptable for a further period of time after it has finished","cn":"可续期的；可展期的；可续订的","ex":{"en":"a renewable lease","cn":"可展期的租约"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(资源)可再生的，可更新的","en":"Renewable resources are natural ones such as wind, water, and sunlight which are always available.","ex":{"en":"...renewable energy sources.","cn":"可再生能源"}},{"pos":"N-COUNT 可数名词","cn":"可再生资源","en":"Renewables are natural energy sources such as wind, water, and sunlight which are always available."},{"pos":"ADJ 形容词","cn":"(合同或协议)可延期的，可续签的","en":"If a contract or agreement is renewable, it can be extended when it reaches the end of a fixed period of time.","ex":{"en":"A formal contract is signed which is renewable annually.","cn":"正式签订了每年可续签的合同。"}}]},"examples":[{"en":"renewable sources of energy such as wind and solar power","cn":"像风力和太阳能这种用之不竭的能源"},{"en":"The work permit is not renewable.","cn":"这份工作许可证不能延期。"}]},"reflect":{"media":{"uk":"media/uk/reflect__gb_1.mp3","us":"media/us/reflect__us_1.mp3"},"oxford":{"phon":"rɪˈflekt","pos":"verb","senses":[{"en":"to show the image of somebody/something on the surface of something such as a mirror, water or glass","cn":"反映；映出（影像）","g":"[transitive, usually passive]","ex":{"en":"His face was reflected in the mirror.","cn":"他的脸映照在镜子里。"}},{"en":"to throw back light, heat, sound, etc. from a surface","cn":"反射（光、热、声等）","g":"[transitive, intransitive]","ex":{"en":"The windows reflected the bright afternoon sunlight.","cn":"窗户反射着午后明媚的阳光。"}},{"en":"to show or be a sign of the nature of something or of somebody’s attitude or feeling","cn":"显示，表明，表达（事物的自然属性或人们的态度、情感等）","g":"[transitive]","ex":{"en":"Our newspaper aims to reflect the views of the local community.","cn":"本报的宗旨是表达当地人民的心声。"}},{"en":"to think carefully and deeply about something","cn":"认真思考；沉思","g":"[intransitive, transitive]","ex":{"en":"Before I decide, I need time to reflect.","cn":"在作出决定以前，我需要时间认真考虑考虑。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"反映；表现；显示","en":"If something reflects an attitude or situation, it shows that the attitude or situation exists or it shows what it is like.","ex":{"en":"The Los Angeles riots reflected the bitterness between the black and Korean communities in the city","cn":"洛杉矶的暴乱反映出这个城市的黑人社区和韩裔社区之间的仇恨。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（光、热或其他射线）反射","en":"When light, heat, or other rays reflect off a surface or when a surface reflects them, they are sent back from the surface and do not pass through it.","ex":{"en":"The sun reflected off the snow-covered mountains","cn":"冰雪覆盖的山峰反射着阳光。"}},{"pos":"VERB 动词","cn":"（在镜子或水中）映出","en":"When something is reflected in a mirror or in water, you can see its image in the mirror or in the water.","ex":{"en":"His image seemed to be reflected many times in the mirror.","cn":"那面镜子里好像映现出很多个他的影像。"}},{"pos":"VERB 动词","cn":"沉思；深思","en":"When you reflect on something, you think deeply about it.","ex":{"en":"We should all give ourselves time to reflect","cn":"我们都应该给自己时间好好想想。"}},{"pos":"VERB 动词","cn":"认为;想","en":"You can use reflect to indicate that a particular thought occurs to someone.","ex":{"en":"Things were very much changed since before the war, he reflected.","cn":"情况与战前大不同了，他想。"}},{"pos":"VERB 动词","cn":"使对…产生某种印象","en":"If an action or situation reflects in a particular way on someone or something, it gives people a good or bad impression of them.","ex":{"en":"The affair hardly reflected well on the British","cn":"这个事件很难让人们对英国人有好印象。"}}]},"examples":[{"en":"When the sun's rays hit the earth, a lot of the heat is reflected back into space.","cn":"太阳光线照射到地球时，大量的热力被反射回太空。"},{"en":"Before I decide, I need time to reflect.","cn":"在作出决定以前，我需要时间认真考虑考虑。"}]},"resulting":{"lemma":"result","media":{"uk":"media/uk/result__gb_1.mp3","us":"media/us/result__us_1.mp3"}},"remarkably":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"use this when you want to use a stronger word than 'very'","cn":""},{"en":"as much as it is possible to imagine - use this to emphasize adjectives that already have a strong meaning","cn":""}]},"examples":[{"en":"She plays the violin remarkably well.","cn":"她的小提琴拉得特别好。","src":"ld"},{"en":"Remarkably, all of the passengers survived the crash.","cn":"令人称奇的是﹐这次事故中所有乘客都幸免于难。","src":"ld"}],"media":{"uk":"media/uk/remarkably__gb_1.mp3","us":"media/us/remarkably__us_1.mp3"},"oxford":{"phon":"rɪˈmɑːkəbli","pos":"adverb","senses":[{"en":"in a way that is unusual or surprising and causes people to take notice","cn":"非凡地；奇异地；显著地；引人注目地","ex":{"en":"The car is in remarkably good condition for its age.","cn":"就车龄而论，这辆车的状况好极了。"}}]}},"resume":{"oxford":{"phon":"rɪˈzjuːm","pos":"verb","senses":[{"en":"if you resume an activity, or if it resumes, it begins again or continues after being interrupted","cn":"重新开始；（中断后）继续","g":"[transitive, intransitive]","ex":{"en":"to resume talks/negotiations","cn":"重新进行会谈／谈判"}},{"en":"to go back to the seat or place that you had before","cn":"回到（原来的座位、地方或位置）","g":"[transitive]","ex":{"en":"He resumed his seat opposite her.","cn":"他回到座位上，与她面对面坐着。"}},{"en":"a short summary or account of something","cn":"摘要；概述；概要","ex":{"en":"a brief résumé of events so far","cn":"到目前为止事件的概述"},"pos":"noun"},{"en":"a written record of your education and the jobs you have done, that you send when you are applying for a job","cn":"（求职用的）履历，简历","lab":"North American English","ex":{"en":"Yes, I've read your résumé. Very impressive.","cn":"是的，我看过你的简历。非常令人印象深刻。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）重新开始;（使）继续进行","en":"If you resume an activity or if it resumes, it begins again.","ex":{"en":"After the war he resumed his duties at Emmanuel College","cn":"战争过后，他重新开始了在伊曼纽尔学院的工作。"}},{"pos":"VERB 动词","cn":"恢复(职位);回到（座位）","en":"If you resume your seat or position, you return to the seat or position you were in before you moved.","ex":{"en":"'I changed my mind,' Blanche said, resuming her seat.","cn":"“我改变主意了，”布兰奇说着回到她的座位上。"}},{"pos":"VERB 动词","cn":"继续说;接着说","en":"If someone resumes, they begin speaking again after they have stopped for a short time.","ex":{"en":"'Hey, Judith,' he resumed, 'tell me all about yourself.'","cn":"“嘿，朱迪思，”他接着说，“跟我谈谈你自己吧。”"}}]},"media":{"uk":"media/uk/resume__gb_2.mp3","us":"media/us/resume__us_1.mp3"},"examples":[{"en":"She resumed her career after an interval of six years.","cn":"经过六年的间歇之后她又重新上岗。"},{"en":"The noise resumed, louder than before.","cn":"噪声再起，比先前更大。"}]},"resistant":{"media":{"uk":"media/uk/resistant__gb_1.mp3","us":"media/us/resistant__us_1.mp3"},"oxford":{"phon":"rɪˈzɪstənt","pos":"adjective","senses":[{"en":"not affected by something; able to resist something","cn":"抵抗的；有抵抗力的","ex":{"en":"plants that are resistant to disease","cn":"抗病植株"}},{"en":"opposing something and trying to stop it happening","cn":"抵制的；阻止的","ex":{"en":"Elderly people are not always resistant to change.","cn":"上了年纪的人并不总是抵制变革。"}},{"en":"not damaged by the thing mentioned","cn":"抗…的；耐…的","ex":{"en":"disease-resistant plants","cn":"抗病植株"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"反对的;抵制的;抗拒的","en":"Someone who is resistant to something is opposed to it and wants to prevent it.","ex":{"en":"Some people are very resistant to the idea of exercise.","cn":"有些人十分反对锻炼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有抵抗力的;不受…损害的","en":"If something is resistant to a particular thing, it is not harmed by it.","ex":{"en":"...how to improve plants to make them more resistant to disease","cn":"如何改良植物以增强它们对病害的抵抗力"}}]},"examples":[{"en":"Elderly people are not always resistant to change.","cn":"上了年纪的人并不总是抵制变革。"},{"en":"plants that are resistant to disease","cn":"抗病植株"}]},"related":{"media":{"uk":"media/uk/related__gb_1.mp3","us":"media/us/related__us_1.mp3"},"oxford":{"phon":"rɪˈleɪtɪd","pos":"adjective","senses":[{"en":"connected with something/somebody in some way","cn":"相关的；有联系的","ex":{"en":"The amount of protein you need is directly related to your lifestyle.","cn":"蛋白质的需求量与生活方式直接相关。"}},{"en":"in the same family","cn":"属同一家族的；有亲属关系的","ex":{"en":"We're distantly related.","cn":"我们是远亲。"}},{"en":"belonging to the same group","cn":"属于同一种类的；同一组别的","ex":{"en":"related species","cn":"近缘物种"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"相关的;有联系的","en":"If two or more things are related, there is a connection between them.","ex":{"en":"The philosophical problems of chance and of free will are closely related.","cn":"或然性和自由意志这两个哲学问题是紧密相关的。"}},{"pos":"ADJ 形容词","cn":"有亲属关系的;属同一家族的","en":"People who are related belong to the same family.","ex":{"en":"...people in countries like Bangladesh who have been able to show they are related to a spouse or parent living in Britain.","cn":"能够证明自己和生活在英国的配偶或父母有亲属关系的孟加拉国等国家的公民"}},{"pos":"","cn":"(动物)有亲缘关系的;(语言)同源的","en":"If you say that different types of animal or different languages are related, you mean that they have developed from the same type of animal or language.","ex":{"en":"Sanskrit is related very closely to Latin, Greek, and the Germanic and Celtic languages.","cn":"梵语和拉丁语、希腊语、日耳曼和凯尔特语是联系密切的同源语言。"}}]},"examples":[{"en":"Much of the crime in this area is related to drug abuse.","cn":"这一地区的许多犯罪都与滥用药物有关。"},{"en":"These problems are closely related.","cn":"这些问题都是密切相关的。"}],"base":"relate"},"resistance":{"media":{"uk":"media/uk/resistance__gb_1.mp3","us":"media/us/resistance__us_1.mp3"},"oxford":{"phon":"rɪˈzɪstəns","pos":"noun","senses":[{"en":"dislike of or opposition to a plan, an idea, etc.; the act of refusing to obey","cn":"反对；抵制；抗拒","g":"[uncountable, singular]","ex":{"en":"As with all new ideas it met with resistance.","cn":"和所有的新观念一样，它受到了抵制。"}},{"en":"the act of using force to oppose somebody/something","cn":"抵抗；反抗","g":"[uncountable, singular]","ex":{"en":"There were a number of episodes of armed resistance during the early years of occupation.","cn":"占领初期发生了多起武装抵抗事件。"}},{"en":"the power not to be affected by something","cn":"抗力；抵抗力","g":"[uncountable, singular]","ex":{"en":"AIDS lowers the body's resistance to infection.","cn":"艾滋病降低了身体的抗感染能力。"}},{"en":"a force that stops something moving or makes it move more slowly","cn":"阻力","g":"[uncountable, singular]","ex":{"en":"wind/air resistance (= in the design of planes or cars)","cn":"风阻；空气阻力"}},{"en":"the opposition of a substance or device to the flow of an electrical current","cn":"电阻","g":"[uncountable, countable]","lab":"physics"},{"en":"a secret organization that resists the authorities, especially in a country that an enemy has control of","cn":"（尤指敌占区的）秘密抵抗组织","g":"[singular + singular or plural verb]","ex":{"en":"resistance fighters","cn":"秘密抵抗战士"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"抵抗;抵制;反对","en":"Resistance to something such as a change or a new idea is a refusal to accept it.","ex":{"en":"The US wants big cuts in European agricultural export subsidies, but this is meeting resistance.","cn":"美国想大幅度削减欧洲农业出口补贴，但此举遭到了抵制。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"抵抗;抵御","en":"Resistance to an attack consists of fighting back against the people who have attacked you.","ex":{"en":"The troops are encountering stiff resistance","cn":"军队遭遇了顽强抵抗。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"抵抗力;免疫力","en":"The resistance of your body to germs or diseases is its power to remain unharmed or unaffected by them.","ex":{"en":"This disease is surprisingly difficult to catch as most people have a natural resistance to it.","cn":"由于多数人对这种病具有天然免疫力，所以发病率低得出奇。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(风或空气的)阻力","en":"Wind or air resistance is a force which slows down a moving object or vehicle.","ex":{"en":"The design of the bicycle has managed to reduce the effects of wind resistance and drag.","cn":"这种自行车的设计成功地减少了风的阻力和摩擦力。"}},{"pos":"N-VAR 可变名词","cn":"电阻;阻抗","en":"In electrical engineering or physics, resistance is the ability of a substance or an electrical circuit to stop the flow of an electrical current through it.","ex":{"en":"...materials that lose all their electrical resistance.","cn":"电阻为零的材料"}},{"pos":"N-SING 单数名词","cn":"（被他国军队占领或被专制政府统治的国家中的）抵抗组织，地下组织","en":"In a country which is occupied by the army of another country, or which has a very harsh and strict government, the resistance is an organized group of people who are involved in illegal activities against the people in power.","ex":{"en":"They managed to escape after being arrested by the resistance.","cn":"他们被抵抗组织抓住后又设法逃脱了。"}},{"pos":"PHRASE 短语","cn":"阻力最小的路线;最容易的途径","en":"If you take the line of least resistance in a situation, you do what is easiest, even though you think that it may not be the right thing to do. In American English, you usually talk about the path of least resistance .","ex":{"en":"They would rather take the line of least resistance than become involved in arguments.","cn":"他们倾向采用阻力最小的方案，不愿卷入纷争。"}}]},"examples":[{"en":"As with all new ideas it met with resistance.","cn":"和所有的新观念一样，它受到了抵制。"},{"en":"There has been a lot of resistance to this new law.","cn":"这项新的法规已经遇到很多的抵制。"}]},"respectively":{"oxford":{"phon":"rɪˈspektɪvli","pos":"adverb","senses":[{"en":"in the same order as the people or things already mentioned","cn":"分别；各自；顺序为；依次为","ex":{"en":"Julie and Mark, aged 17 and 19 respectively","cn":"朱莉和马克，年龄分别为 17 岁和 19 岁"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"分别地;各自地","en":"Respectively means in the same order as the items that you have just mentioned.","ex":{"en":"Their sons, Ben and Jonathan, were three and six respectively","cn":"他们的儿子，本和乔纳森，分别是3岁和6岁。"}}]},"media":{"uk":"media/uk/respectively__gb_1.mp3","us":"media/us/respectively__us_1.mp3"},"examples":[{"en":"Julie and Mark, aged 17 and 19 respectively","cn":"朱莉和马克，年龄分别为 17 岁和 19 岁"},{"en":"The cups and saucers cost £5 and £3 respectively.","cn":"茶杯和茶碟的价钱分别为5英镑和3英镑。"}]},"reproducing":{"lemma":"reproduce"},"realize":{"media":{"uk":"media/uk/realize__gb_1.mp3","us":"media/us/realize__us_1.mp3"},"oxford":{"phon":"ˈriːəlaɪz","pos":"verb","senses":[{"en":"to understand or become aware of a particular fact or situation","cn":"理解；领会；认识到；意识到","g":"[transitive, intransitive]","sc":"be/become aware","ex":{"en":"I didn’t realize (that) you were so unhappy.","cn":"我没有察觉到你那么不开心。"}},{"en":"to achieve something important that you very much want to do","cn":"实现；将…变为现实","g":"[transitive]","sc":"achieve something","ex":{"en":"to realize your dream","cn":"实现梦想"}},{"en":"if somebody’s fears are realized, the things that they are afraid will happen, do happen","cn":"（所担心的事）发生，产生","g":"[transitive, usually passive]","sc":"happen","ex":{"en":"His worst fears were realized when he saw that the door had been forced open.","cn":"他一看门被撬了，就知道最担心的事还是发生了。"}},{"en":"to sell things that you own, for example property, in order to get the money that you need for something","cn":"把（财产等）变卖，变现","g":"[transitive]","lab":"formal","sc":"sell"},{"en":"to be sold for a particular amount of money","cn":"以…价格卖出","g":"[transitive]","lab":"formal","sc":"sell","ex":{"en":"The paintings realized $2 million at auction.","cn":"这些绘画在拍卖会上以 200 万美元卖出。"}},{"en":"to produce something that can be seen or heard, based on written information or instructions","cn":"把（概念等）具体表现出来","g":"[transitive]","lab":"formal","sc":"make something real","ex":{"en":"The stage designs have been beautifully realized.","cn":"舞台设计得到了完美的体现。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"认识到；意识到；了解","en":"If you realize that something is true, you become aware of that fact or understand it.","ex":{"en":"As soon as we realised something was wrong, we moved the children away","cn":"我们刚意识到有什么不对劲就把孩子转移了。"}},{"pos":"VERB 动词","cn":"（希望、心愿或恐惧）实现，成为现实，发生","en":"If your hopes, desires, or fears are realized, the things that you hope for, desire, or fear actually happen.","ex":{"en":"Straightaway our worst fears were realised","cn":"我们最恐惧的事情一下发生了。"}},{"pos":"VERB 动词","cn":"实现;实施;实行","en":"When someone realizes a design or an idea, they make or organize something based on that design or idea.","ex":{"en":"Various textile techniques will be explored to realise design possibilities","cn":"将尝试和探索纺织技巧来把这些设计变为现实。"}},{"pos":"VERB 动词","cn":"发挥，实现（潜力）","en":"If someone or something realizes their potential, they do everything they are capable of doing, because they have been given the opportunity to do so.","ex":{"en":"The support systems to enable women to realize their potential at work are seriously inadequate","cn":"使妇女在工作中发挥潜力的支持体系严重不足。"}},{"pos":"VERB 动词","cn":"实现（利润）；卖得…","en":"If something realizes a particular amount of money when it is sold, that amount of money is paid for it.","ex":{"en":"A selection of correspondence from P G Wodehouse realised £ 1,232.","cn":"P.G.沃德豪斯的书信选集卖了1,232英镑。"}}]},"examples":[{"en":"There was a cheer when it was realized that everyone was safely back.","cn":"人们意识到大家都已平安归来的时候便发出了一阵欢呼声。"},{"en":"His worst fears were realized when he saw that the door had been forced open.","cn":"他一看门被撬了，就知道最担心的事还是发生了。"}]},"regularly":{"media":{"uk":"media/uk/regularly__gb_1.mp3","us":"media/us/regularly__us_1.mp3"},"oxford":{"phon":"ˈreɡjələli","pos":"adverb","senses":[{"en":"at regular intervals or times","cn":"有规律地；间隙均匀地","ex":{"en":"We meet regularly to discuss the progress of the project.","cn":"我们定期会面，讨论工程进展情况。"}},{"en":"often","cn":"经常","ex":{"en":"I go there quite regularly.","cn":"我经常去那儿。"}},{"en":"in an even or balanced way","cn":"均匀地；匀称地","ex":{"en":"The plants were spaced regularly, about 50 cm apart.","cn":"这些植株分布均匀，间距大约为 50 厘米。"}}]},"examples":[{"en":"The plants were spaced regularly, about 50 cm apart.","cn":"这些植株分布均匀，间距大约为 50 厘米。"},{"en":"We meet regularly to discuss the progress of the project.","cn":"我们定期会面，讨论工程进展情况。"}]},"rectangular":{"media":{"uk":"media/uk/rectangular__gb_1.mp3","us":"media/us/rectangular__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"长方形的;矩形的","en":"Something that is rectangular is shaped like a rectangle.","ex":{"en":"...a rectangular table.","cn":"长方形桌子"}}]},"oxford":{"phon":"rekˈtæŋɡjələ(r)","pos":"adjective","senses":[{"en":"having a shape like a rectangle (= a flat shape with four straight sides, two of which are longer than the other two, and four angles of 90°)","cn":"长方形；矩形","ex":{"en":"a rectangular box/grid/enclosure","cn":"矩形盒子/网格/外壳"}}]}},"refer":{"media":{"uk":"media/uk/refer__gb_1.mp3","us":"media/us/refer__us_1.mp3"},"oxford":{"phon":"rɪˈfɜː(r)","pos":"verb","senses":[{"en":"to send somebody/something to somebody/something for help, advice or a decision","cn":"将…送交给（以求获得帮助等）","lab":"formal","ex":{"en":"My doctor referred me to a specialist.","cn":"我的医生让我去找一位专家诊治。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"谈及;提到;提及","en":"If you refer to a particular subject or person, you talk about them or mention them.","ex":{"en":"In his speech, he referred to a recent trip to Canada.","cn":"他在讲演中提到了前不久的加拿大之行。"}},{"pos":"VERB 动词","cn":"称…（为）","en":"If you refer to someone or something as a particular thing, you use a particular word, expression, or name to mention or describe them.","ex":{"en":"Marcia had referred to him as a dear friend","cn":"马西娅把他称作好朋友。"}},{"pos":"VERB 动词","cn":"涉及；提及；描述","en":"If a word refers to a particular thing, situation, or idea, it describes it in some way.","ex":{"en":"The term electronics refers to electrically-induced action.","cn":"电子学这个术语涉及电感作用。"}},{"pos":"VERB 动词","cn":"将…转到（医院就医）；将…转给（专科医生）","en":"If a person who is ill is referred to a hospital or a specialist, they are sent there by a doctor in order to be treated.","ex":{"en":"Patients are mostly referred to hospital by their general practitioners","cn":"病人大多数是在他们的全科医生建议下转往医院就医。"}},{"pos":"VERB 动词","cn":"提交；送交；委托","en":"If you refer a task or a problem to a person or an organization, you formally tell them about it, so that they can deal with it.","ex":{"en":"He could refer the matter to the high court.","cn":"他可以将此事交由高等法院裁决。"}},{"pos":"VERB 动词","cn":"推荐;介绍","en":"If you refer someone to a person or organization, you send them there for the help they need.","ex":{"en":"Now and then I referred a client to him.","cn":"我不时地介绍客户给他。"}},{"pos":"VERB 动词","cn":"查阅，参考（资料）","en":"If you refer to a book or other source of information, you look at it in order to find something out.","ex":{"en":"He referred briefly to his notebook.","cn":"他简单地看了看自己的笔记。"}},{"pos":"VERB 动词","cn":"指引;让…去查询","en":"If you refer someone to a source of information, you tell them the place where they will find the information which they need or which you think will interest them.","ex":{"en":"Mr Bryan also referred me to a book by the American journalist Anthony Scaduto.","cn":"布赖恩先生还建议我去查阅美国记者安东尼·斯卡杜托的一本书。"}}]},"examples":[{"en":"( formal ) May I refer you to my letter of 14 May?","cn":"你查看一下我 5 月 14 日给你的信好吗？"},{"en":"The star refers to items which are intended for the advanced learner.","cn":"标有星号的项目是给高阶学习者的。"}]},"rejecting":{"lemma":"reject","media":{"uk":"media/uk/reject__gb_1.mp3","us":"media/us/reject__us_1.mp3"}},"regardless":{"media":{"uk":"media/uk/regardless__gb_1.mp3","us":"media/us/regardless__us_1.mp3"},"oxford":{"phon":"rɪˈɡɑːdləs","pos":"adverb","senses":[{"en":"paying no attention, even if the situation is bad or there are difficulties","cn":"不顾；不加理会","ex":{"en":"The weather was terrible but we carried on regardless.","cn":"天气非常恶劣，但我们并不理会，照常进行。"}}]},"collins":{"senses":[{"pos":"PREP-PHRASE 短语介词","cn":"不顾；不管；不论","en":"If something happens regardless of something else, it is not affected or influenced at all by that other thing.","ex":{"en":"It takes in anybody regardless of religion, colour, or creed","cn":"任何人，不论宗教、肤色或信仰，都可以加入。"}},{"pos":"ADV 副词","cn":"不管怎样;无论如何;不顾一切地","en":"If you say that someone did something regardless, you mean that they did it even though there were problems or factors that could have stopped them, or perhaps should have stopped them.","ex":{"en":"Despite her recent surgery she has been carrying on regardless.","cn":"尽管最近做了手术，她还是不顾一切地进行下去。"}}]},"examples":[{"en":"The weather was terrible but we carried on regardless.","cn":"天气非常恶劣，但我们并不理会，照常进行。"},{"en":"The law requires equal treatment for all, regardless of race, religion, or sex.","cn":"法律规定人人平等﹐无论种族﹑宗教或性别。"}]},"reliable":{"media":{"uk":"media/uk/reliable__gb_1.mp3","us":"media/us/reliable__us_1.mp3"},"oxford":{"phon":"rɪˈlaɪəbl","pos":"adjective","senses":[{"en":"that can be trusted to do something well; that you can rely on","cn":"可信赖的；可依靠的","ex":{"en":"We are looking for someone who is reliable and hard-working.","cn":"我们在物色可靠而又勤奋的人。"}},{"en":"that is likely to be correct or true","cn":"真实可信的；可靠的","ex":{"en":"reliable information/data","cn":"可靠的信息／数据"}},{"en":"able to work or operate for long periods without breaking down or needing attention","cn":"性能可靠的；稳定耐用的","ex":{"en":"My car's not as reliable as it used to be.","cn":"我的车不像过去那样耐用了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可靠的;可信赖的","en":"People or things that are reliable can be trusted to work well or to behave in the way that you want them to.","ex":{"en":"She was efficient and reliable","cn":"她办事很有效率，也很可靠。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(信息)可靠的，可信的,确凿的","en":"Information that is reliable or that is from a reliable source is very likely to be correct.","ex":{"en":"There is no reliable information about civilian casualties","cn":"关于平民的伤亡还没有确凿的信息。"}}]},"examples":[{"en":"The incident cast doubt on her motives and reliability.","cn":"这件事使人怀疑她有何动机，以及她是否可靠。"},{"en":"I am reliably informed (= told by sb who knows the facts) that the company is being sold.","cn":"有可靠知情人告诉我公司要被卖掉。"}]},"require":{"media":{"uk":"media/uk/require__gb_1.mp3","us":"media/us/require__us_1.mp3"},"oxford":{"phon":"rɪˈkwaɪə(r)","pos":"verb","senses":[{"en":"to need something; to depend on somebody/something","cn":"需要；依靠；依赖","lab":"British English also","ex":{"en":"These pets require a lot of care and attention.","cn":"这些宠物需要悉心照顾。"}},{"en":"to make somebody do or have something, especially because it is necessary according to a particular law or set of rules","cn":"使做（某事）；使拥有（某物）；（尤指根据法规）规定","g":"[often passive]","ex":{"en":"I just require a signature on the form.","cn":"我只需要在表格上签名。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"需要;有赖于","en":"If you require something or if something is required, you need it or it is necessary.","ex":{"en":"If you require further information, you should consult the registrar","cn":"如果需要进一步了解信息，请咨询教务主任。"}},{"pos":"VERB 动词","cn":"要求;命令;规定","en":"If a law or rule requires you to do something, you have to do it.","ex":{"en":"The rules also require employers to provide safety training","cn":"这些规定还要求雇主提供安全培训。"}},{"pos":"PHRASE 短语","cn":"必读的","en":"If you say that something is required reading for a particular group of people, you mean that you think it is essential for them to read it because it will give them information which they should have.","ex":{"en":"...an important research study that should be required reading for every member of the cabinet.","cn":"每一位内阁成员都应阅读的一份重要研究论文"}}]},"examples":[{"en":"True marriage requires us to show trust and loyalty.","cn":"真正的婚姻有赖于我们表现出信任与忠诚。"},{"en":"‘Hamlet’ is required reading (= must be read) for this course. 《","cn":"哈姆雷特》是这门课程的指定读物。"}]},"reality":{"media":{"uk":"media/uk/reality__gb_1.mp3","us":"media/us/reality__us_1.mp3"},"oxford":{"phon":"riˈæləti","pos":"noun","senses":[{"en":"the true situation and the problems that actually exist in life, in contrast to how you would like life to be","cn":"现实；实际情况","g":"[uncountable]","ex":{"en":"She refuses to face reality.","cn":"她不肯面对现实。"}},{"en":"a thing that is actually experienced or seen, in contrast to what people might imagine","cn":"事实；实际经历；见到的事物","g":"[countable]","ex":{"en":"Will time travel ever become a reality?","cn":"时光旅行真的会成为现实吗？"}},{"en":"television/shows, etc. that use real people (not actors) in real situations, presented as entertainment","cn":"真人秀节目","g":"[uncountable]","ex":{"en":"a reality TV star","cn":"一个真人秀电视明星"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"现实;事实","en":"You use reality to refer to real things or the real nature of things rather than imagined, invented, or theoretical ideas.","ex":{"en":"Fiction and reality were increasingly blurred","cn":"虚构和现实越来越难以区分了。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指不愉快的或困难的）真实情况，实际情形","en":"The reality of a situation is the truth about it, especially when it is unpleasant or difficult to deal with.","ex":{"en":"...the harsh reality of top international competition","cn":"高层次的国际竞争的严酷现实"}},{"pos":"N-SING 单数名词","cn":"现实存在;真实发生的事","en":"You say that something has become a reality when it actually exists or is actually happening.","ex":{"en":"...the whole procedure that made this book become a reality","cn":"本书成书的整个过程"}},{"pos":"PHRASE 短语","cn":"事实上；实际上","en":"You can use in reality to introduce a statement about the real nature of something, when it contrasts with something incorrect that has just been described.","ex":{"en":"He came across as streetwise, but in reality he was not.","cn":"他给人的印象是很适应都市生活，但实际上并非如此。"}}]},"examples":[{"en":"Outwardly she seemed confident but in reality she felt extremely nervous.","cn":"表面上看，她显得信心十足，而实际上她紧张得要命。"},{"en":"The reality is that there is not enough money to pay for this project.","cn":"实际情况是没有足够的钱花在这个项目上。"}]},"restriction":{"media":{"uk":"media/uk/restriction__gb_1.mp3","us":"media/us/restriction__us_1.mp3"},"oxford":{"phon":"rɪˈstrɪkʃn","pos":"noun","senses":[{"en":"a rule or law that limits what you can do or what can happen","cn":"限制规定；限制法规","g":"[countable]","ex":{"en":"import/speed/travel restrictions","cn":"进口／速度／旅行限制"}},{"en":"the act of limiting or controlling somebody/something","cn":"限制；约束","g":"[uncountable]","ex":{"en":"sports clothes that prevent any restriction of movement","cn":"宽松的运动服"}},{"en":"a thing that limits the amount of freedom you have","cn":"制约因素","g":"[countable]","ex":{"en":"the restrictions of a prison","cn":"监狱的种种约束"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"限制;约束;规定","en":"A restriction is an official rule that limits what you can do or that limits the amount or size of something.","ex":{"en":"...the lifting of restrictions on political parties and the news media","cn":"取消对政治党派和新闻媒体的限制"}},{"pos":"N-COUNT 可数名词","cn":"（对行动的）限定，约束，限制因素","en":"You can refer to anything that limits what you can do as a restriction.","ex":{"en":"His parents are trying to make up to him for the restrictions of urban living","cn":"他的父母正试图弥补他在城市生活的局限。"}}]},"examples":[{"en":"The government has agreed to lift restrictions on press freedom.","cn":"政府已经同意撤销对新闻自由的限制。"},{"en":"to impose/place a restriction on sth","cn":"对某事实行限制"}]},"rented":{"media":{"uk":"media/uk/rented__gb_1.mp3","us":"media/us/rented__us_1.mp3"},"oxford":{"phon":"ˈrentɪd","pos":"adjective","senses":[{"en":"that you pay rent for","cn":"租用的；租借的","ex":{"en":"a rented studio","cn":"租来的工作室"}}]},"examples":[{"en":"a rented studio","cn":"租来的工作室"}],"base":"rent"},"respectable":{"media":{"uk":"media/uk/respectable__gb_1.mp3","us":"media/us/respectable__us_1.mp3"},"oxford":{"phon":"rɪˈspektəbl","pos":"adjective","senses":[{"en":"considered by society to be acceptable, good or correct","cn":"体面的；得体的；值得尊敬的","ex":{"en":"a highly respectable neighbourhood","cn":"非常体面的街区"}},{"en":"fairly good; that there is no reason to be ashamed of","cn":"相当好的；不丢面子的","ex":{"en":"It was a perfectly respectable result.","cn":"这是个非常好的结果。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"体面的;可敬的;正派的","en":"Someone or something that is respectable is approved of by society and considered to be morally correct.","ex":{"en":"He came from a perfectly respectable middle-class family","cn":"他出身于一个非常正派的中产阶级家庭。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好的;可观的;令人满意的","en":"You can say that something is respectable when you mean that it is good enough or acceptable.","ex":{"en":"...investments that offer respectable rates of return","cn":"回报率可观的投资"}}]},"examples":[{"en":"Go and make yourself look respectable.","cn":"去把自己弄得体面点儿。"},{"en":"a highly respectable neighbourhood","cn":"非常体面的城区"}]},"restricted":{"oxford":{"phon":"rɪˈstrɪktɪd","pos":"adjective","senses":[{"en":"limited or small in size or amount","cn":"（大小或数量）有限的，很小的","ex":{"en":"a restricted space","cn":"有限的空间"}},{"en":"limited in what you are able to do","cn":"（指能做的事）有限的，受限制的","ex":{"en":"In those days women led fairly restricted lives.","cn":"那时，妇女过着相当受限制的生活。"}},{"en":"controlled by rules or laws","cn":"受（法规）制约的；受控制的；受约束的","lab":"British English","ex":{"en":"to allow children only restricted access to the internet","cn":"只允许儿童有限地接触互联网"}},{"en":"only open to people with special permission, especially because it is secret or dangerous","cn":"不对公众开放的","g":"[usually before noun]","ex":{"en":"to enter a restricted zone","cn":"进入禁区"}},{"en":"officially secret and only available to people with special permission","cn":"保密的；限于内部传阅的","lab":"British English","ex":{"en":"a restricted document","cn":"保密文件"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有限的;很少的","en":"Something that is restricted is quite small or limited.","ex":{"en":"...the monotony of a heavily restricted diet","cn":"受到严格限制的饮食的单调"}},{"pos":"ADJ 形容词","cn":"仅限…使用的;仅限…所有的","en":"If something is restricted to a particular group, only members of that group have it. If it is restricted to a particular place, it exists only in that place.","ex":{"en":"Discipline problems are by no means restricted to children in families dependent on benefits","cn":"绝不只是依靠救济金生活的家庭的孩子才有纪律问题。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地区)不对外开放的","en":"A restricted area is one that only people with special permission can enter.","ex":{"en":"...a highly restricted area close to the old Khodinka airfield.","cn":"老科丁卡机场附近的一个禁区"}},{"pos":"ADJ 形容词","cn":"(文件等)保密的，仅限于内部的","en":"A restricted document is one that only people with special permission can read.","ex":{"en":"The charge was that, in February 1975, he had leaked a restricted document to a journalist.","cn":"对他的指控是他在1975年2月将一份保密文件泄露给了一位记者。"}}]},"media":{"uk":"media/uk/restricted__gb_1.mp3","us":"media/us/restricted__us_1.mp3"},"examples":[{"en":"The tournament is restricted to players under the age of 23.","cn":"这次比赛只允许 23 岁以下的选手参加。"},{"en":"In those days women led fairly restricted lives.","cn":"那时，妇女过着相当受限制的生活。"}],"base":"restrict"},"retrained":{"lemma":"retrain"},"relic":{"media":{"uk":"media/uk/relic__gb_1.mp3","us":"media/us/relic__us_1.mp3"},"oxford":{"phon":"ˈrelɪk","pos":"noun","senses":[{"en":"an object, a tradition, a system, etc. that has survived from the past","cn":"遗物；遗迹；遗风；遗俗","ex":{"en":"The building stands as the last remaining relic of the town's cotton industry.","cn":"这座建筑物是小镇棉纺业仅存的遗迹。"}},{"en":"a part of the body or clothing of a holy person, or something that they owned, that is kept after their death and respected as a religious object","cn":"圣髑；圣骨；圣人遗物","ex":{"en":"holy relics","cn":"圣人遗物"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"遗物;遗迹;纪念物","en":"If you refer to something or someone as a relic of an earlier period, you mean that they belonged to that period but have survived into the present.","ex":{"en":"The tower is a relic of grim days when big houses had to be fortified against invaders","cn":"这座塔是那些灰暗岁月的遗迹，那时大房子不得不被加固,以抵御侵略者。"}},{"pos":"N-COUNT 可数名词","cn":"(有历史价值的)遗物，遗迹，遗址","en":"A relic is something which was made or used a long time ago and which is kept for its historical significance.","ex":{"en":"...a museum of war relics.","cn":"战争遗迹纪念馆"}},{"pos":"N-COUNT 可数名词","cn":"圣物;圣骨","en":"A relic is the body of a saint or something else associated with a saint, which some people regard as holy."}]},"examples":[{"en":"The building stands as the last remaining relic of the town's cotton industry.","cn":"这座建筑物是小镇棉纺业仅存的遗迹。"},{"en":"Videotapes may already seem like relics of a bygone era.","cn":"录像带似乎已成为过去时代的遗物。"}]},"rent":{"media":{"uk":"media/uk/rent__gb_2.mp3","us":"media/us/rent__us_2.mp3"},"oxford":{"phon":"rent","pos":"noun","senses":[{"en":"an amount of money that you regularly pay so that you can use a house, room, etc.","cn":"租金","g":"[uncountable, countable]","lab":"British English","ex":{"en":"I earn just about enough to pay the rent.","cn":"我挣的钱勉强够付房租。"}},{"en":"the amount of money that you pay to use something for a particular period of time","cn":"租金","g":"[uncountable, countable]","lab":"especially North American English"},{"en":"a torn place in a piece of material or clothing","cn":"破裂处；裂口；撕裂","g":"[countable]","lab":"old use or literary"},{"en":"to regularly pay money to somebody so that you can use something that they own, such as a house, a room, some land, etc.","cn":"租用，租借（房屋、土地等）","g":"[transitive, intransitive]","ex":{"en":"Are you looking to buy or rent?","cn":"你想买还是租？"},"pos":"verb"},{"en":"to allow somebody to use something that you own such as a house or some land in exchange for regular payments","cn":"出租；将…租给","g":"[transitive]","ex":{"en":"We rented our house out for a year when we went abroad.","cn":"我们出国时把房子租出去一年。"},"pos":"verb"},{"en":"to pay money to somebody so that you can use something for a short period of time","cn":"（短期）租用，租借","g":"[transitive]","lab":"especially North American English","ex":{"en":"to rent a film/movie/DVD","cn":"租影片；租影碟"},"pos":"verb"},{"en":"to be available for somebody to use if they pay a particular amount of money","cn":"以…出租；租金为","g":"[intransitive]","lab":"North American English","ex":{"en":"The apartment rents for $500 a month.","cn":"这套房间每月租金为 500 美元。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"租来;租借","en":"If you rent something, you regularly pay its owner a sum of money in order to be able to have it and use it yourself.","ex":{"en":"She rents a house with three other girls","cn":"她和其他3个女孩合租一套房子。"}},{"pos":"VERB 动词","cn":"出租;租给","en":"If you rent something to someone, you let them have it and use it in exchange for a sum of money which they pay you regularly.","ex":{"en":"She rented rooms to university students.","cn":"她把房间租给了大学生。"}},{"pos":"N-VAR 可变名词","cn":"租金;租用费","en":"Rent is the amount of money that you pay regularly to use a house, flat, or piece of land.","ex":{"en":"She worked to pay the rent while I went to college","cn":"在我读大学期间，她打工挣钱来付租金。"}},{"pos":"","cn":"","en":"Rent is the past tense and past participle of rend ."},{"pos":"","cn":"","en":"相关词组：rent out"}]},"examples":[{"en":"We rented a car for the week and explored the area.","cn":"我们租了一个星期的车探索这个地区。"},{"en":"We can hire bikes for a day to explore the town.","cn":"我们可租用自行车一天来游览这城镇。"}]},"retailer":{"media":{"uk":"media/uk/retailer__gb_1.mp3","us":"media/us/retailer__us_1.mp3"},"oxford":{"phon":"ˈriːteɪlə(r)","pos":"noun","senses":[{"en":"a person or business that sells goods to the public","cn":"零售商；零售店","ex":{"en":"one of the country’s largest food retailers","cn":"该国最大的食品零售商之一"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"零售商;零售店","en":"A retailer is a person or business that sells goods to the public.","ex":{"en":"Furniture and carpet retailers are among those reporting the sharpest annual decline in sales.","cn":"据称年销售额下滑幅度最大的零售商中包括家具和地毯零售商。"}}]}},"relieving":{"lemma":"relieve"},"reluctantly":{"oxford":{"phon":"rɪˈlʌktəntli","pos":"adverb","senses":[{"en":"in a way that involves hesitating before doing something because you do not want to do it or because you are not sure that it is the right thing to do","cn":"不情愿的；勉强的","ex":{"en":"We reluctantly agreed to go with her.","cn":"我们勉强答应跟她一起去。"}}]},"media":{"uk":"media/uk/reluctantly__gb_1.mp3","us":"media/us/reluctantly__us_1.mp3"},"examples":[{"en":"We reluctantly agreed to go with her.","cn":"我们勉强答应跟她一起去。"},{"en":"She gave a reluctant smile.","cn":""}]},"retrieve":{"media":{"uk":"media/uk/retrieve__gb_1.mp3","us":"media/us/retrieve__us_1.mp3"},"oxford":{"phon":"rɪˈtriːv","pos":"verb","senses":[{"en":"to bring or get something back, especially from a place where it should not be","cn":"取回；索回","lab":"formal","ex":{"en":"She bent to retrieve her comb from the floor.","cn":"她弯腰从地板上捡起她的梳子。"}},{"en":"to find and get back data or information that has been stored in the memory of a computer","cn":"检索数据","lab":"computing","ex":{"en":"to retrieve information from the database","cn":"从数据库检索资料"}},{"en":"to make a bad situation better; to get back something that was lost","cn":"扭转颓势；挽回；找回","ex":{"en":"You can only retrieve the situation by apologizing.","cn":"你只有道歉才能挽回这个局面。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"取回;找回","en":"If you retrieve something, you get it back from the place where you left it.","ex":{"en":"He reached over and retrieved his jacket from the back seat","cn":"他伸手从后座上取回了自己的夹克。"}},{"pos":"VERB 动词","cn":"使重新回到，挽回(某种局面)","en":"If you manage to retrieve a situation, you succeed in bringing it back into a more acceptable state.","ex":{"en":"He is the one man who could retrieve that situation.","cn":"他是唯一能挽回局面的人。"}},{"pos":"VERB 动词","cn":"（计算机、大脑）检索，搜索（信息）","en":"To retrieve information from a computer or from your memory means to get it back.","ex":{"en":"Computers can instantly retrieve millions of information bits","cn":"计算机可以立即检索到数百万条信息。"}}]},"examples":[{"en":"The program allows you to retrieve items quickly by searching under a keyword.","cn":"这个程序通过关键词进行搜索，能让你迅速获取数据项。"},{"en":"The police have managed to retrieve some of the stolen money.","cn":"警方已经追回了部分被盗钱款。"}]},"reduces":{"lemma":"reduce","media":{"uk":"media/uk/reduce__gb_1.mp3","us":"media/us/reduce__us_1.mp3"}},"registration":{"oxford":{"phon":"ˌredʒɪˈstreɪʃn","pos":"noun","senses":[{"en":"the act of making an official record of something/somebody","cn":"登记；注册；挂号","g":"[uncountable, countable]","ex":{"en":"the registration of letters and parcels","cn":"信件和包裹的挂号"}},{"en":"a document showing that an official record has been made of something","cn":"登记文档；注册项目","g":"[uncountable, countable]","ex":{"en":"my Democratic party registration","cn":"我加入民主党的登记"}},{"en":"the series of letters and numbers that are shown on a number plate at the front and back of a vehicle to identify it","cn":"车辆的登记号码；牌照号码","g":"[countable]","lab":"both British English","ex":{"en":"The police are looking for a black car with German registration plates.","cn":"警方正在寻找一辆挂着德国牌照的黑色轿车。"}},{"en":"the time when a teacher looks at the list of students on the class register and checks that the students are present","cn":"（教师对上课学生的）点名","g":"[uncountable]","lab":"British English"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"注册；登记","en":"The registration of something such as a person's name or the details of an event is the recording of it in an official list.","ex":{"en":"They have campaigned strongly for compulsory registration of dogs","cn":"他们强烈呼吁实行犬类强制登记。"}}]},"media":{"uk":"media/uk/registration__gb_1.mp3","us":"media/us/registration__us_1.mp3"},"examples":[{"en":"the registration of letters and parcels","cn":"信件和包裹的挂号"},{"en":"the registration of students for a course","cn":"学生的选课登记"}]},"resemblance":{"oxford":{"phon":"rɪˈzembləns","pos":"noun","senses":[{"en":"the fact of being or looking similar to somebody/something","cn":"相似；相像","ex":{"en":"a striking/close/strong resemblance","cn":"明显的／不小的／显著的相似之处"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"相似之处;类似之处","en":"If there is a resemblance between two people or things, they are similar to each other.","ex":{"en":"There was a remarkable resemblance between him and Pete","cn":"他和皮特之间有着惊人的相似之处。"}}]},"media":{"uk":"media/uk/resemblance__gb_1.mp3","us":"media/us/resemblance__us_1.mp3"},"examples":[{"en":"The resemblance between the two signatures was remarkable.","cn":"两个签名的相似之处非常明显。"},{"en":"She bears an uncanny resemblance to Dido.","cn":"她跟迪多长得像极了。"}]},"refined":{"oxford":{"phon":"rɪˈfaɪnd","pos":"adjective","senses":[{"en":"made pure by having other substances taken out of it","cn":"精炼的；提纯的；精制的","g":"[usually before noun]","ex":{"en":"Avoid foods rich in fat or refined sugar.","cn":"避免摄入高脂或富含精制糖的食物。"}},{"en":"polite, well educated and able to judge the quality of things; having the sort of manners that are considered typical of a high social class","cn":"有礼貌的；优雅的；有教养的","ex":{"en":"Beneath his refined manners and superficial elegance the man was a snake.","cn":"在他优雅的举止和表面的优雅之下，这个人是个阴险的人。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精炼的；去杂质的；提纯的","en":"A refined substance has been made pure by having other substances removed from it.","ex":{"en":"...refined sugar.","cn":"精制白糖"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）有礼貌的，有教养的，彬彬有礼的，有品位的","en":"If you say that someone is refined, you mean that they are very polite and have good manners and good taste.","ex":{"en":"...refined and well-dressed ladies","cn":"举止优雅、衣着考究的女士们"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"经过完善的；经过提升的","en":"If you describe a machine or a process as refined, you mean that it has been carefully developed and is therefore very efficient or elegant.","ex":{"en":"...a more refined engine","cn":"更加完善的引擎"}}]},"media":{"uk":"media/uk/refined__gb_1.mp3","us":"media/us/refined__us_1.mp3"},"examples":[{"en":"refined sugar","cn":"精制糖"},{"en":"Laser surgery has become much more refined over the last decade.","cn":"在过去十年间﹐激光手术已日臻完善。"}],"base":"refine"},"record":{"media":{"uk":"media/uk/record__gb_1.mp3","us":"media/us/record__us_1.mp3"},"oxford":{"phon":"ˈrekɔːd","pos":"noun","senses":[{"en":"a written account of something that is kept so that it can be looked at and used in the future","cn":"记录；记载","g":"[countable]","sc":"written account","ex":{"en":"You should keep a record of your expenses.","cn":"你应该记下你的各项开支。"}},{"en":"the best result or the highest or lowest level that has ever been reached, especially in sport","cn":"（尤指体育运动中最高或最低的）纪录","g":"[countable]","sc":"highest/best","ex":{"en":"She holds the world record for the 100 metres.","cn":"她保持着 100 米的世界纪录。"}},{"en":"the facts that are known about somebody/something’s past behaviour, character, achievements, etc.","cn":"（有关过去的）事实；记录；经历；功过","g":"[singular]","sc":"of somebody/something’s past","ex":{"en":"The airline has a good safety record.","cn":"这家航空公司的安全记录一向很好。"}},{"en":"rocks, fossils, the parts of buildings and objects found in the ground, etc. that provide evidence about the past","cn":"记录；遗迹","g":"[countable]","sc":"of somebody/something’s past","ex":{"en":"Fossil records suggest that the region was covered in water until relatively recently.","cn":"化石记录表明该地区不久之前还一直淹没在水中。"}},{"en":"the fact of having committed crimes in the past","cn":"前科；犯罪记录","g":"[countable]","sc":"of crimes","ex":{"en":"Does he have a record?","cn":"他有没有前科？"}},{"en":"a thin, round piece of plastic on which music, etc. is recorded","cn":"唱片","g":"[countable]","sc":"music","ex":{"en":"to play a record","cn":"播放唱片"}},{"en":"a piece or collection of music released as a record, or on CD, the internet, etc.","cn":"唱片；专辑","g":"[countable]","lab":"British English","sc":"music","ex":{"en":"a record company (= one which produces and sells records)","cn":"唱片公司"}},{"en":"to keep a permanent account of facts or events by writing them down, filming them, storing them in a computer, etc.","cn":"记录；记载","g":"[transitive]","sc":"keep account","ex":{"en":"Her childhood is recorded in the diaries of those years.","cn":"她的童年生活都记在当年的日记里。"},"pos":"verb"},{"en":"to make a copy of music, a film, etc. or to convert sound or a performance into a permanent form, so that you can listen to or watch it again","cn":"录制；录（音）；录（像）","g":"[transitive, intransitive]","sc":"sound/music/film","ex":{"en":"Did you remember to record that programme for me?","cn":"你记得为我录下那个节目了吗？"},"pos":"verb"},{"en":"to perform music so that it can be copied, stored and played back","cn":"演奏音乐供录制；灌（唱片）","g":"[transitive, intransitive]","sc":"music","ex":{"en":"The band is back in the US recording their new album.","cn":"乐队回美国录制新唱片去了。"},"pos":"verb"},{"en":"to make an official or legal statement about something","cn":"发表正式（或法律方面的）声明；申明","g":"[transitive]","sc":"make official statement","ex":{"en":"The coroner recorded a verdict of accidental death.","cn":"验尸官得出了意外死亡的结论。"},"pos":"verb"},{"en":"to show a particular measurement or amount","cn":"标明；显示","g":"[transitive]","sc":"of measuring instrument","ex":{"en":"The thermometer recorded a temperature of 40°C.","cn":"温度计显示气温达到了 40 摄氏度。"},"pos":"verb"},{"en":"to achieve a particular score or result","cn":"得（分）；取得（成绩）","g":"[transitive]","sc":"score/result","ex":{"en":"The team recorded their first win of the season.","cn":"该队取得了本赛季的第一场胜利。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（文字或影像）记录，记载","en":"If you keep a record of something, you keep a written account or photographs of it so that it can be referred to later.","ex":{"en":"Keep a record of all the payments","cn":"所有付款都要作记录。"}},{"pos":"VERB 动词","cn":"（用文字、照片或电脑）记录，记载","en":"If you record a piece of information or an event, you write it down, photograph it, or put it into a computer so that in the future people can refer to it.","ex":{"en":"...software packages which record the details of your photographs.","cn":"记录你的照片的各种细节的软件包"}},{"pos":"VERB 动词","cn":"（用磁带或胶片）记录，录制，记下","en":"If you record something such as a speech or performance, you put it on tape or film so that it can be heard or seen again later.","ex":{"en":"There is nothing to stop viewers recording the films on videotape","cn":"没有什么办法可以阻止观众用录像机把电影录下来。"}},{"pos":"VERB 动词","cn":"录制（音乐、电视或广播节目）","en":"If a musician or performer records a piece of music or a television or radio show, they perform it so that it can be put onto CD, tape, or film.","ex":{"en":"It took the musicians two and a half days to record their soundtrack for the film","cn":"乐师们花了两天半的时间为电影录制配乐。"}},{"pos":"N-COUNT 可数名词","cn":"（音乐）唱片","en":"A record is a round, flat piece of black plastic on which sound, especially music, is stored, and which can be played on a record player. You can also refer to the music stored on this piece of plastic as a record.","ex":{"en":"This is one of my favourite records.","cn":"这是我最喜欢的唱片之一。"}},{"pos":"VERB 动词","cn":"记录，表明（某种测量结果或数值）","en":"If a dial or other measuring device records a certain measurement or value, it shows that measurement or value.","ex":{"en":"The test records the electrical activity of the brain","cn":"试验记录下了脑电活动。"}},{"pos":"N-COUNT 可数名词","cn":"（体育运动或活动的）纪录，最好成绩","en":"A record is the best result that has ever been achieved in a particular sport or activity, for example the fastest time, the furthest distance, or the greatest number of victories.","ex":{"en":"Roger Kingdom set the world record of 12.92 seconds","cn":"罗杰·金德姆创造了12.92秒的世界纪录。"}},{"pos":"ADJ 形容词","cn":"创纪录的","en":"You use record to say that something is higher, lower, better, or worse than has ever been achieved before.","ex":{"en":"Profits were at record levels","cn":"利润创下新高。"}},{"pos":"N-COUNT 可数名词","cn":"经历;履历","en":"Someone's record is the facts that are known about their achievements or character.","ex":{"en":"His record reveals a tough streak","cn":"他的履历显示他性格强悍。"}},{"pos":"N-COUNT 可数名词","cn":"案底;犯罪记录","en":"If someone has a criminal record, it is officially known that they have committed crimes in the past.","ex":{"en":"...a heroin addict with a criminal record going back 15 years","cn":"15年前留有案底的海洛因瘾君子"}},{"pos":"PHRASE 短语","cn":"供记录（表示将公开申明某事）","en":"If you say that what you are going to say next is for the record, you mean that you are saying it publicly and officially and you want it to be written down and remembered.","ex":{"en":"We're willing to state for the record that it has enormous value.","cn":"我们愿意郑重声明那是有极大价值的。"}},{"pos":"PHRASE 短语","cn":"供记录在案；作为记录（备用）","en":"If you give some information for the record, you give it in case people might find it useful at a later time, although it is not a very important part of what you are talking about.","ex":{"en":"For the record, most Moscow girls leave school at about 18","cn":"需要指出的是，多数莫斯科女孩18岁从学校毕业。"}},{"pos":"PHRASE 短语","cn":"非正式的;不得发表的","en":"If something that you say is off the record, you do not intend it to be considered as official, or published with your name attached to it.","ex":{"en":"May I speak off the record?","cn":"我可以私下说说吗，不要发表？"}},{"pos":"PHRASE 短语","cn":"公开宣布的；记录在案的","en":"If you are on record as saying something, you have said it publicly and officially and it has been written down.","ex":{"en":"The Chancellor is on record as saying that the increase in unemployment is 'a price worth paying' to keep inflation down.","cn":"财政大臣公开宣称失业率上升是遏制通货膨胀“值得付出的代价”。"}},{"pos":"PHRASE 短语","cn":"记录下来;记录在案","en":"If you keep information on record, you write it down or store it in a computer so that it can be used later.","ex":{"en":"The practice is to keep on record any analysis of samples.","cn":"习惯上要把所有的样品分析记录在案。"}},{"pos":"PHRASE 短语","cn":"有记录的;有记载的","en":"If something is the best, worst, or biggest on record, it is the best, worst, or biggest thing of its kind that has been noticed and written down.","ex":{"en":"It's the shortest election campaign on record","cn":"这是史上为期最短的一次竞选活动。"}},{"pos":"PHRASE 短语","cn":"纠正记载；改正记录","en":"If you set the record straight or put the record straight, you show that something which has been regarded as true is in fact not true.","ex":{"en":"Let me set the record straight on the misconceptions contained in your article.","cn":"我来纠正一下你文章里的错误认识。"}}]},"examples":[{"en":"During her career Billie Holiday made over 100 records.","cn":"比利 · 哈乐黛在她的事业生涯中录制了 100 多张唱片。"},{"en":"It is recorded that, by the year 630, four hundred monks were attached to the monastery.","cn":"据记载，到了 630 年有 400 个僧侣隶属该寺院。"}]},"reporting":{"oxford":{"phon":"rɪˈpɔːtɪŋ","pos":"noun","senses":[{"en":"the presenting of and writing about news on television and radio, and in newspapers","cn":"新闻报道","lab":"British English","ex":{"en":"accurate/balanced/objective reporting","cn":"准确的／公正的／客观的新闻报道"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"新闻报道工作","en":"Reporting is the presenting of news in newspapers, on radio, and on television.","ex":{"en":"...honest and impartial political reporting.","cn":"坦诚而公正的政治新闻报道"}}]},"media":{"uk":"media/uk/reporting__gb_1.mp3","us":"media/us/reporting__us_1.mp3"},"examples":[{"en":"( BrE ) Reporting restrictions on the trial have been lifted (= it can now legally be reported).","cn":"对报道这次审讯的限制已经撤销。"},{"en":"Reporting restrictions on the trial have been lifted (= it can now legally be reported).","cn":""}],"base":"report"},"responsibilities":{"lemma":"responsibility","media":{"uk":"media/uk/responsibility__gb_1.mp3","us":"media/us/responsibility__us_1.mp3"}},"remedy":{"oxford":{"phon":"ˈremədi","pos":"noun","senses":[{"en":"a way of dealing with or improving an unpleasant or difficult situation","cn":"处理方法；改进措施；补偿","ex":{"en":"When the reservoir becomes blocked, the only remedy lies in cleaning the entire system.","cn":"水库堵塞，唯一的解决办法就是疏浚整个系统。"}},{"en":"a treatment or medicine to cure a disease or reduce pain that is not very serious","cn":"疗法；治疗；药品","ex":{"en":"He took a herbal remedy for his hay fever.","cn":"他服用草药治疗花粉热。"}},{"en":"a way of dealing with a problem, using the processes of the law","cn":"（通过法律程序的）解决方法，救济","lab":"law","ex":{"en":"Holding copyright provides the only legal remedy against unauthorized copying.","cn":"持有版权是制止盗版的唯一法律手段。"}},{"en":"to correct or improve something","cn":"改正；纠正；改进","ex":{"en":"to remedy a problem","cn":"解决问题"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(问题的)解决方法，解决良方","en":"A remedy is a successful way of dealing with a problem.","ex":{"en":"The remedy lies in the hands of the government.","cn":"解决良策掌握在政府手中。"}},{"pos":"N-COUNT 可数名词","cn":"药品;治疗方法","en":"A remedy is something that is intended to cure you when you are ill or in pain.","ex":{"en":"...natural remedies to help overcome winter infections.","cn":"有助于治疗冬季传染病的自然疗法"}},{"pos":"VERB 动词","cn":"纠正;补救;矫正","en":"If you remedy something that is wrong or harmful, you correct it or improve it.","ex":{"en":"A great deal has been done internally to remedy the situation.","cn":"已经做了很多内部工作对这种情形进行补救。"}}]},"media":{"uk":"media/uk/remedy__gb_1.mp3","us":"media/us/remedy__us_1.mp3"},"examples":[{"en":"There are a number of possible remedies to this problem.","cn":"这个问题有许多可能采取的解决办法。"},{"en":"Holding copyright provides the only legal remedy against unauthorized copying.","cn":"持有版权是反对盗版的唯一法律手段。"}]},"respondents":{"lemma":"respondent"},"revealing":{"media":{"uk":"media/uk/revealing__gb_1.mp3","us":"media/us/revealing__us_1.mp3"},"oxford":{"phon":"rɪˈviːlɪŋ","pos":"adjective","senses":[{"en":"giving you interesting information that you did not know before","cn":"揭露真相的；发人深省的","ex":{"en":"The document provided a revealing insight into the government's priorities.","cn":"这份文件使人看出政府的轻重缓急是怎样安排的。"}},{"en":"allowing more of somebody’s body to be seen than usual","cn":"暴露的；使身体过分裸露的","ex":{"en":"a revealing blouse","cn":"暴露的女式衬衫"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"透露内情的;揭露性的","en":"A revealing statement, account, or action tells you something that you did not know, especially about the person doing it or making it.","ex":{"en":"...a revealing interview.","cn":"揭秘访谈"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服等)袒胸露肩的，暴露的","en":"Revealing clothes allow more of a person's body to be seen than is usual.","ex":{"en":"She was wearing a tight and revealing gold dress.","cn":"她身穿一件暴露的金色紧身连衣裙。"}}]},"examples":[{"en":"The document provided a revealing insight into the government's priorities.","cn":"这份文件使人看出政府的轻重缓急是怎样安排的。"},{"en":"The answers the children gave were extremely revealing.","cn":"孩子们所给的答案极其发人深省。"}],"base":"reveal"},"review":{"oxford":{"phon":"rɪˈvjuː","pos":"noun","senses":[{"en":"a report in a newspaper or magazine, or on the internet, television or radio, in which somebody gives their opinion of a book, play, film, product, etc.; the act of writing this kind of report","cn":"（对书、戏剧、电影、产品等的）评介，评论","g":"[countable, uncountable]","lab":"US English","ex":{"en":"a book review","cn":"书评"}},{"en":"an act of looking again at something you have studied or written, especially in order to prepare for an exam","cn":"（尤指为准备考试的）温习，复习","g":"[countable, uncountable]","lab":"especially North American English","ex":{"en":"We need to do the review for the test tomorrow.","cn":"为了明天的考试，我们需要复习。"}},{"en":"an examination of something, with the intention of changing it if necessary","cn":"评审，审查，检查，检讨（以进行必要的修改）","g":"[countable, uncountable]","ex":{"en":"The government has embarked on a systematic review of transport policy.","cn":"政府已经开始对交通运输政策进行全面审查。"}},{"en":"an examination of all the relevant information on a subject or on a series of events","cn":"全面回顾；综述","g":"[countable]","ex":{"en":"to conduct/undertake a review of customer complaints","cn":"对客户投诉进行调查"}},{"en":"a ceremony that involves an official inspection of soldiers, etc. by an important visitor","cn":"阅兵式；检阅","g":"[countable]","lab":"formal"},{"en":"to write a report of a book, play, film, product, etc. in which you give your opinion of it","cn":"评论，评介（书、戏剧、电影、产品等）","g":"[transitive]","ex":{"en":"Please rate and review your purchase on our website.","cn":"请在我们的网站上为您的购买体验打分并发表评论。"},"pos":"verb"},{"en":"to look again at something you have studied, especially in order to prepare for an exam","cn":"（尤指为准备考试而）温习，复习","g":"[transitive, intransitive]","lab":"especially North American English","ex":{"en":"We will be reviewing all the topics covered this semester.","cn":"我们将复习本学期学过的所有内容。"},"pos":"verb"},{"en":"to check a piece of work to see if there are any mistakes","cn":"校阅；审核","g":"[transitive]","lab":"especially North American English","ex":{"en":"Review your work before you turn it in.","cn":"在上交作业之前先检查一下您的作业。"},"pos":"verb"},{"en":"to carefully examine or consider something again, especially so that you can decide if it is necessary to make changes","cn":"复查；重新考虑","g":"[transitive]","ex":{"en":"The government will review the situation later in the year.","cn":"政府将在今年晚些时候对形势重新加以研究。"},"pos":"verb"},{"en":"to read or study information about something, especially in order to reach an opinion about it","cn":"审阅；评述","g":"[transitive]","ex":{"en":"to review records/documents/data","cn":"审阅记录／文件／数据"},"pos":"verb"},{"en":"to think about past events, for example to try to understand why they happened","cn":"回顾；反思","g":"[transitive]","ex":{"en":"to review your failures and triumphs","cn":"回顾自己的失败和成功"},"pos":"verb"},{"en":"to make an official inspection of a group of soldiers, etc. in a military ceremony","cn":"检阅（部队）","g":"[transitive]","ex":{"en":"The Commander-in-Chief reviewed the troops.","cn":"总司令检阅了部队。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"检查;审查;审核","en":"A review of a situation or system is its formal examination by people in authority. This is usually done in order to see whether it can be improved or corrected.","ex":{"en":"The president ordered a review of US economic aid to Jordan","cn":"总统下令对美国向约旦提供的经济援助进行审查。"}},{"pos":"VERB 动词","cn":"仔细研究;审视;细查;详查","en":"If you review a situation or system, you consider it carefully to see what is wrong with it or how it could be improved.","ex":{"en":"The Prime Minister reviewed the situation with his Cabinet yesterday","cn":"昨天，首相和他的内阁对局势进行了审度。"}},{"pos":"N-COUNT 可数名词","cn":"（对书、电影等的）评论文章;书评;影评","en":"A review is a report in the media in which someone gives their opinion of something such as a new book or film.","ex":{"en":"Disney's 'Beauty And The Beast' has won rave reviews","cn":"迪斯尼出品的电影《美女与野兽》赢得了众多好评。"}},{"pos":"VERB 动词","cn":"写（新书、新上映电影等）的评论","en":"If someone reviews something such as a new book or film, they write a report or give a talk on television or radio in which they express their opinion of it.","ex":{"en":"Richard Coles reviews all of the latest video releases","cn":"理查德·科尔斯为所有最新发行的录影带都写了评论。"}},{"pos":"VERB 动词","cn":"检阅(军队)；阅（兵）","en":"When a military or political leader reviews troops, they examine them, or watch them marching.","ex":{"en":"When he reviewed the troops they cheered him as he smiled and raised his hat.","cn":"他检阅军队时微笑着举起帽子，人们与此同时都向他欢呼。"}},{"pos":"VERB 动词","cn":"（为备考）复习，温习","en":"When you review for an examination, you read things again and make notes in order to be prepared for the examination.","ex":{"en":"Reviewing for exams gives you a chance to bring together all the individual parts of the course","cn":"考前复习让你有机会把一门课程所有零碎的知识都融会贯通。"}}]},"media":{"uk":"media/uk/review__gb_1.mp3","us":"media/us/review__us_1.mp3"},"examples":[{"en":"good/bad/mixed/rave reviews in the national press","cn":"全国性报刊上良好的/不好的/毁誉参半的/高度赞誉的评论"},{"en":"The government will review the situation later in the year.","cn":"政府将在今年晚些时候对形势重新加以研究。"}]},"reflection":{"media":{"uk":"media/uk/reflection__gb_1.mp3","us":"media/us/reflection__us_1.mp3"},"oxford":{"phon":"rɪˈflekʃn","pos":"noun","senses":[{"en":"an image in a mirror, on a shiny surface, on water, etc.","cn":"映象；映照出的影像","g":"[countable]","ex":{"en":"He admired his reflection in the mirror.","cn":"他欣赏着自己在镜中的影像。"}},{"en":"the action or process of sending back light, heat, sound, etc. from a surface","cn":"（光、热、声等的）反射","g":"[uncountable]","ex":{"en":"There is reflection of heat from the metal surface.","cn":"金属表面反射传导热。"}},{"en":"a sign that shows the state or nature of something","cn":"反映；显示；表达","g":"[countable]","ex":{"en":"Your clothes are often a reflection of your personality.","cn":"穿着常常反映出一个人的个性。"}},{"en":"careful thought about something, sometimes over a long period of time","cn":"沉思；深思；审慎的思考","g":"[uncountable]","ex":{"en":"A week off would give him time for reflection.","cn":"歇上一周会使他有时间考虑考虑。"}},{"en":"your written or spoken thoughts about a particular subject or topic","cn":"（关于某课题的）思考，回忆","g":"[countable, usually plural]","ex":{"en":"a book of her reflections on childhood","cn":"一本关于她童年生活的回忆录"}},{"en":"an account or a description of something","cn":"记录；描述","g":"[countable]","ex":{"en":"The article is an accurate reflection of events that day.","cn":"这篇文章准确地记录了那天发生的事。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（镜子里的）映像;（水中的）倒影","en":"A reflection is an image that you can see in a mirror or in glass or water.","ex":{"en":"Meg stared at her reflection in the bedroom mirror.","cn":"梅格注视着卧室中镜子里的自己。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（光或热等的）反射","en":"Reflection is the process by which light and heat are sent back from a surface and do not pass through it.","ex":{"en":"...the reflection of a beam of light off a mirror.","cn":"一束光从镜子表面的反射"}},{"pos":"N-COUNT 可数名词","cn":"反映;表现;显示;体现","en":"If you say that something is a reflection of a particular person's attitude or of a situation, you mean that it is caused by that attitude or situation and therefore reveals something about it.","ex":{"en":"Inhibition in adulthood seems to be very clearly a reflection of a person's experiences as a child.","cn":"一个人成年期的情感压抑似乎很明显是其童年时期经历的反映。"}},{"pos":"N-SING 单数名词","cn":"坏的印象","en":"If something is a reflection or a sad reflection on a person or thing, it gives a bad impression of them.","ex":{"en":"Infection with head lice is no reflection on personal hygiene","cn":"头上生虱子并不说明不讲个人卫生。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"深思;见解;想法","en":"Reflection is careful thought about a particular subject. Your reflections are your thoughts about a particular subject.","ex":{"en":"After days of reflection she decided to write back","cn":"想了几天之后她决定回信。"}},{"pos":"N-COUNT 可数名词","cn":"评论;感想","en":"Reflections on something are comments or writings that express someone's ideas about it.","ex":{"en":"In his latest collection of poems readers are confronted with a series of reflections on death.","cn":"在他最新的诗集里，读者能够读到他对死亡的一系列感想。"}}]},"examples":[{"en":"The increase in crime is a sad reflection on (= shows sth bad about) our society today.","cn":"犯罪上升遗憾地反映了当今社会不太好的一面。"},{"en":"She decided on reflection to accept his offer after all.","cn":"经过审慎的思考，她还是决定接受他的提议。"}]},"remarks":{"lemma":"remark"},"replaces":{"lemma":"replace","media":{"uk":"media/uk/replace__gb_1.mp3","us":"media/us/replace__us_1.mp3"}},"received":{"media":{"uk":"media/uk/received__gb_1.mp3","us":"media/us/received__us_1.mp3"},"oxford":{"phon":"rɪˈsiːvd","pos":"adjective","senses":[{"en":"accepted by most people as being correct","cn":"被承认的；被一致认可的","ex":{"en":"The received wisdom is that they cannot win.","cn":"大家一致认为他们不会赢。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"被广为接受的；被认为是正确的","en":"The received opinion about something or the received way of doing something is generally accepted by people as being correct.","ex":{"en":"He was among the first to question the received wisdom of the time","cn":"他是那个时代首先质疑当时被普遍认可的处世之道的人之一。"}}]},"examples":[{"en":"The received wisdom is that they cannot win.","cn":"大家一致认为他们不会赢。"},{"en":"The received wisdom is that he will retire within the next year.","cn":"大家普遍认为他将于明年之内退休。"}],"base":"receive"},"retaining":{"oxford":{"phon":"rɪˈteɪnɪŋ","pos":"adjective","senses":[{"en":"intended to keep something in the correct position","cn":"固定的；矫正的","ex":{"en":"a retaining wall (= one that keeps the earth or water behind it in position)","cn":"挡土墙；挡水墙"}}]},"media":{"uk":"media/uk/retaining__gb_1.mp3","us":"media/us/retaining__us_1.mp3"},"examples":[{"en":"a retaining wall (= one that keeps the earth or water behind it in position)","cn":"挡土墙；挡水墙"}],"base":"retain"},"revenge":{"media":{"uk":"media/uk/revenge__gb_1.mp3","us":"media/us/revenge__us_1.mp3"},"oxford":{"phon":"rɪˈvendʒ","pos":"noun","senses":[{"en":"something that you do in order to make somebody suffer because they have made you suffer","cn":"报复；报仇","ex":{"en":"She is seeking revenge for the murder of her husband.","cn":"丈夫遭到谋杀，她在寻找机会报仇。"}},{"en":"the defeat of a person or team that defeated you in a previous game","cn":"（曾经失败一方的）雪耻，打败对手","lab":"sport","ex":{"en":"The team wanted to get revenge for their defeat earlier in the season.","cn":"球队想要为这个赛季早些时候的失败雪耻。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"报仇;报复","en":"Revenge involves hurting or punishing someone who has hurt or harmed you.","ex":{"en":"The attackers were said to be taking revenge on the 14-year-old, claiming he was a school bully","cn":"据说，这些攻击者是在报复这个14岁的孩子，说他是学校的小霸王。"}},{"pos":"VERB 动词","cn":"向…报仇;报复","en":"If you revenge yourself on someone who has hurt you, you hurt them in return.","ex":{"en":"The Sunday Mercury accused her of trying to revenge herself on her former lover","cn":"《星期日信使报》指责她企图报复她以前的情人。"}}]},"examples":[{"en":"The team wanted to get revenge for their defeat earlier in the season.","cn":"球队想要为这个赛季早先的失败雪耻。"},{"en":"She is seeking revenge for the murder of her husband.","cn":"丈夫遭到谋杀，她在寻找机会报仇。"}]},"resolute":{"oxford":{"phon":"ˈrezəluːt","pos":"adjective","senses":[{"en":"strong and determined","cn":"坚决的；有决心的","ex":{"en":"His resolute leadership was admired by many.","cn":"他果断的领导能力受到许多人的钦佩。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚决的;坚定的;果断的","en":"If you describe someone as resolute, you approve of them because they are very determined not to change their mind or not to give up a course of action.","ex":{"en":"Voters perceive him as a decisive and resolute international leader","cn":"投票者认为他是一位坚定果断的国际领导人。"}}]},"media":{"uk":"media/uk/resolute__gb_1.mp3","us":"media/us/resolute__us_1.mp3"},"examples":[{"en":"He became even more resolute in his opposition to the plan.","cn":"他甚至更坚决地反对这个计划。"},{"en":"They remain resolutely opposed to the idea.","cn":"他们仍然坚决反对这种观点。"}]},"resumes":{"lemma":"resume","media":{"uk":"media/uk/resume__gb_2.mp3","us":"media/us/resume__us_1.mp3"}},"relatively":{"media":{"uk":"media/uk/relatively__gb_1.mp3","us":"media/us/relatively__us_1.mp3"},"oxford":{"phon":"ˈrelətɪvli","pos":"adverb","senses":[{"en":"to a fairly large degree, especially in comparison to something else","cn":"相当程度上；相当地；相对地","ex":{"en":"relatively large/small/high/low","cn":"相对大／小／高／低"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"相对而言;比较起来;某种程度上","en":"Relatively means to a certain degree, especially when compared with other things of the same kind.","ex":{"en":"The sums needed are relatively small","cn":"需要的金额相对较小。"}}]},"examples":[{"en":"Lack of exercise is also a risk factor for heart disease but it's relatively small when compared with the others.","cn":"缺乏锻炼也是导致心脏病的一个因素。但和其他因素相比，这方面的危险较小。"},{"en":"We had relatively few applications for the job.","cn":"申请我们这项工作的人相对较少。"}]},"residential":{"media":{"uk":"media/uk/residential__gb_1.mp3","us":"media/us/residential__us_1.mp3"},"oxford":{"phon":"ˌrezɪˈdenʃl","pos":"adjective","senses":[{"en":"suitable for living in; consisting of houses rather than factories or offices","cn":"适合居住的；住宅的","ex":{"en":"a quiet residential area","cn":"安静的住宅区"}},{"en":"requiring a person to live at a particular place; offering living accommodation","cn":"需要在某地居住的；提供住宿的","ex":{"en":"a residential language course","cn":"需要住校的语言课程"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"居住的;住宅区的;居民区的","en":"A residential area contains houses rather than offices or factories.","ex":{"en":"...a smart residential area","cn":"整洁漂亮的住宅区"}},{"pos":"ADJ 形容词","cn":"（机构）寄宿制的，需住宿的","en":"A residential institution is one where people live while they are studying there or being cared for there.","ex":{"en":"Training involves a two-year residential course","cn":"培训包含一门为期两年的住校学习课程。"}}]},"examples":[{"en":"a residential home for the elderly","cn":"老人院"},{"en":"residential care for children","cn":"提供食宿的儿童福利院服务"}]},"recurrent":{"media":{"uk":"media/uk/recurrent__gb_1.mp3","us":"media/us/recurrent__us_1.mp3"},"oxford":{"phon":"rɪˈkʌrənt","pos":"adjective","senses":[{"en":"that happens again and again","cn":"反复出现的；重复发生的","ex":{"en":"recurrent infections","cn":"重复感染"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"重现的；再次发生的","en":"A recurrent event or feeling happens or is experienced more than once.","ex":{"en":"Race is a recurrent theme in the work.","cn":"种族问题是该作品里多次出现的主题。"}}]},"examples":[{"en":"Poverty is a recurrent theme in her novels.","cn":"贫穷是她的小说中惯有的主题。"},{"en":"recurrent infections","cn":"重复感染"}]},"repetitive":{"oxford":{"phon":"rɪˈpetətɪv","pos":"adjective","senses":[{"en":"saying or doing the same thing many times, so that it becomes boring","cn":"重复乏味的","ex":{"en":"a repetitive task","cn":"重复乏味的工作"}},{"en":"repeated many times","cn":"多次重复的","ex":{"en":"a repetitive pattern of behaviour","cn":"重复的行为模式"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"反复的;重复乏味的","en":"Something that is repetitive involves actions or elements that are repeated many times and is therefore boring.","ex":{"en":"...factory workers who do repetitive jobs","cn":"从事重复性工作的工厂工人"}},{"pos":"ADJ 形容词","cn":"重复多次的;反复性的","en":"Repetitive movements or sounds are repeated many times.","ex":{"en":"...problems that occur as the result of repetitive movements.","cn":"反复运动引起的问题"}}]},"media":{"uk":"media/uk/repetitive__gb_1.mp3","us":"media/us/repetitive__us_1.mp3"},"examples":[{"en":"a repetitive task","cn":"重复乏味的工作"},{"en":"a repetitive pattern of behaviour","cn":"重复的行为模式"}]},"rectangle":{"media":{"img":["media/pic/quadrilaterals_comp.jpg","media/thumb/rectangle.jpg"],"uk":"media/uk/rectangle__gb_1.mp3","us":"media/us/rectangle__us_1.mp3"},"oxford":{"phon":"ˈrektæŋɡl","pos":"noun","senses":[{"en":"a flat shape with four straight sides, two of which are longer than the other two, and four angles of 90°","cn":"长方形；矩形"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"长方形；矩形","en":"A rectangle is a four-sided shape whose corners are all ninety degree angles. Each side of a rectangle is the same length as the one opposite to it."}]}},"resemble":{"media":{"uk":"media/uk/resemble__gb_1.mp3","us":"media/us/resemble__us_1.mp3"},"oxford":{"phon":"rɪˈzembl","pos":"verb","senses":[{"en":"to look like or be similar to another person or thing","cn":"看起来像；显得像；像","ex":{"en":"She closely resembles her sister.","cn":"她和她姐姐很像。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"类似;与…相似;与…相像","en":"If one thing or person resembles another, they are similar to each other.","ex":{"en":"Some of the commercially produced venison resembles beef in flavour","cn":"有些商业化养殖的鹿肉味道和牛肉很相似。"}}]},"examples":[{"en":"So many hotels resemble each other.","cn":"许多酒店看上去都差不多。"},{"en":"The plant resembles grass in appearance.","cn":"这种植物的外形像草。"}]},"representation":{"media":{"uk":"media/uk/representation__gb_1.mp3","us":"media/us/representation__us_1.mp3"},"oxford":{"phon":"ˌreprɪzenˈteɪʃn","pos":"noun","senses":[{"en":"the act of presenting somebody/something in a particular way; something that shows or describes something","cn":"表现；描述；描绘；表现形式","g":"[uncountable, countable]","ex":{"en":"the negative representation of single mothers in the media","cn":"媒体对单身母亲的负面描述"}},{"en":"the fact of having representatives who will speak or vote for you or act in your place","cn":"代表；维护；支持","g":"[uncountable]","ex":{"en":"The green movement lacks effective representation in Parliament.","cn":"环境保护运动在议会中缺乏有力的支持者。"}},{"en":"formal statements made to somebody in authority, especially in order to make your opinions known or to protest","cn":"陈述；抗议","g":"[plural]","lab":"especially British English, formal，，","ex":{"en":"We have made representations to the prime minister, but without success.","cn":"我们同首相进行交涉，但没有效果。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"代表;代理","en":"If a group or person has representation in a parliament or on a committee, someone in the parliament or on the committee supports them and makes decisions on their behalf.","ex":{"en":"Puerto Ricans are U.S. citizens but they have no representation in Congress.","cn":"波多黎各人是美国公民，但是他们在国会里没有代表。"}},{"pos":"N-COUNT 可数名词","cn":"描写;描绘;体现;象征","en":"You can describe a picture, model, or statue of a person or thing as a representation of them.","ex":{"en":"...a lifelike representation of Christ","cn":"对基督的生动描绘"}},{"pos":"N-PLURAL 复数名词","cn":"投诉;交涉;要求","en":"If you make representations to a government or other official group, you make formal complaints or requests to them.","ex":{"en":"We have made representations to ministers but they just don't seem to be listening.","cn":"我们已经向部长们提出了抗议，但是他们却装聋作哑。"}}]},"examples":[{"en":"The green movement lacks effective representation in Parliament.","cn":"环境保护运动在议会中缺乏有力的支持者。"},{"en":"We have made representations to the prime minister, but without success.","cn":"我们同首相进行交涉，但没有效果。"}]},"regional":{"oxford":{"phon":"ˈriːdʒənl","pos":"adjective","senses":[{"en":"of or relating to a region","cn":"地区的；区域的；地方的","ex":{"en":"services available at a local and regional level","cn":"在当地和本地区可提供的服务"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"地区的；区域的","en":"Regional is used to describe things which relate to a particular area of a country or of the world.","ex":{"en":"...the autonomous regional government of Andalucia.","cn":"安达卢西亚自治区政府"}}]},"media":{"uk":"media/uk/regional__gb_1.mp3","us":"media/us/regional__us_1.mp3"},"examples":[{"en":"the conflict between regional and national interests","cn":"地方利益和国家利益的冲突"},{"en":"regional councils/elections/newspapers","cn":"地方议会/选举/报纸"}]},"reliant":{"media":{"uk":"media/uk/reliant__gb_1.mp3","us":"media/us/reliant__us_1.mp3"},"oxford":{"phon":"rɪˈlaɪənt","pos":"adjective","senses":[{"en":"needing somebody/something in order to survive, be successful, etc.","cn":"依赖性的；依靠的","ex":{"en":"The hostel is heavily reliant upon charity.","cn":"这家收容所在很大程度上依赖赞助。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"依赖的;依靠的","en":"A person or thing that is reliant on something needs it and often cannot live or work without it.","ex":{"en":"These people are not wholly reliant on Western charity","cn":"这些人并非完全依赖西方慈善团体。"}}]},"examples":[{"en":"The hostel is heavily reliant upon charity.","cn":"这家收容所在很大程度上依赖赞助。"},{"en":"Most companies are now reliant on computer technology.","cn":"大多数公司现在依赖计算机技术。"}]},"requisite":{"oxford":{"phon":"ˈrekwɪzɪt","pos":"adjective","senses":[{"en":"necessary for a particular purpose","cn":"必需的；必备的；必不可少的","ex":{"en":"She lacks the requisite experience for the job.","cn":"她缺少做这份工作所必需的经验。"}},{"en":"something that you need for a particular purpose","cn":"必需的事物","ex":{"en":"toilet requisites (= soap, toothpaste, etc.)","cn":"洗漱用品"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"必需的;必备的;必不可少的","en":"You can use requisite to indicate that something is necessary for a particular purpose.","ex":{"en":"She filled in the requisite paperwork.","cn":"她完成了必要的书面工作。"}},{"pos":"N-COUNT 可数名词","cn":"必需品;必备品;必要条件","en":"A requisite is something which is necessary for a particular purpose.","ex":{"en":"An understanding of accounting techniques is a major requisite for the work of the analysts.","cn":"懂得会计知识是从事分析员工作的一个必要条件。"}}]},"media":{"uk":"media/uk/requisite__gb_1.mp3","us":"media/us/requisite__us_1.mp3"},"examples":[{"en":"A university degree has become a requisite for entry into most professions.","cn":"大学学位已经成为在大多数行业谋职的必要条件。"},{"en":"She lacks the requisite experience for the job.","cn":"她缺少做这份工作所必需的经验。"}]},"respect":{"media":{"uk":"media/uk/respect__gb_1.mp3","us":"media/us/respect__us_1.mp3"},"oxford":{"phon":"rɪˈspekt","pos":"noun","senses":[{"en":"a strong feeling of approval of somebody/something because of their good qualities or achievements","cn":"尊敬；敬意；尊重","g":"[uncountable, singular]","ex":{"en":"I have the utmost respect for her and her work.","cn":"我对她和她的工作充满敬意。"}},{"en":"polite behaviour towards or care for somebody/something that you think is important","cn":"重视；尊重；维护","g":"[uncountable, singular]","ex":{"en":"to show a lack of respect for authority","cn":"蔑视权威"}},{"en":"a particular aspect or detail of something","cn":"（事物的）方面，细节","g":"[countable]","ex":{"en":"In this respect we are very fortunate.","cn":"在这方面，我们是很幸运的。"}},{"en":"to have a very good opinion of somebody/something; to admire somebody/something","cn":"尊敬；尊重；仰慕","ex":{"en":"I respect Jack's opinion on most subjects.","cn":"在大多数事情上，我尊重杰克的意见。"},"pos":"verb"},{"en":"to be careful about something; to make sure you do not do something that might be considered wrong","cn":"慎重对待；谨慎从事；尊重","ex":{"en":"Employers must respect employees' privacy.","cn":"雇主必须尊重雇员的隐私。"},"pos":"verb"},{"en":"to agree not to break a law, principle, etc.","cn":"遵守；不损害；不违背","ex":{"en":"The new leader has promised to respect the constitution.","cn":"新的领导人承诺遵守宪法。"},"pos":"verb"},{"en":"a British political party, started by Salma Yakoob and George Monbiot, that was active between 2004 and 2016. Respect's candidate George Galloway joined after he was forced to leave the Labour Party because he criticized Tony Blair and George W Bush for invading Iraq. The party was against war and supported traditional socialist ideas.","cn":"尊重：由萨尔玛·雅各布（Salma Yakoob）和乔治·蒙比奥特（George Monbiot）发起的英国政党，活跃于2004年至2016年。受尊敬的候选人乔治·加洛韦（George Galloway）因批评托尼·布莱尔（Tony Blair）和乔治·W·布什（George W Bush）入侵伊拉克而被迫离开工党，因此加入。该党反对战争，支持传统的社会主义思想。","pos":""}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"尊敬;敬重;尊重","en":"If you respect someone, you have a good opinion of their character or ideas.","ex":{"en":"I want him to respect me as a career woman","cn":"我希望他把我当作一个职业女性来尊重。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"尊敬;敬重;尊重","en":"If you have respect for someone, you have a good opinion of them.","ex":{"en":"I have tremendous respect for Dean","cn":"我非常敬重迪安。"}},{"pos":"VERB 动词","cn":"尊重;遵守;遵从;顾及","en":"If you respect someone's wishes, rights, or customs, you avoid doing things that they would dislike or regard as wrong.","ex":{"en":"Finally, trying to respect her wishes, I said I'd leave.","cn":"最后，为了尊重她的意愿，我说我会离开。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"尊重;遵守;遵从;顾及","en":"If you show respect for someone's wishes, rights, or customs, you avoid doing anything they would dislike or regard as wrong.","ex":{"en":"They will campaign for the return of traditional lands and respect for aboriginal rights and customs.","cn":"他们会争取讨回世代相传的土地，并要求尊重土著居民的权利和风俗。"}},{"pos":"VERB 动词","cn":"遵守，遵从（法律或道德规范）","en":"If you respect a law or moral principle, you agree not to break it.","ex":{"en":"It is about time tour operators respected the law and their own code of conduct.","cn":"旅行社是时候该遵守法律和行业规范了。"}},{"pos":"PHRASE 短语","cn":"恕我直言，恕我冒昧(用于礼貌地表示不同意见或批评)","en":"You can say with respect when you are politely disagreeing with someone or criticizing them.","ex":{"en":"With respect, Minister, you still haven't answered my question","cn":"部长，恕我冒昧，您还没有回答我的问题。"}},{"pos":"PHRASE 短语","cn":"探望，拜访（以示敬意）","en":"If you pay your respects to someone, you go to see them or speak to them. You usually do this to be polite, and not necessarily because you want to do it.","ex":{"en":"Carl had asked him to visit the hospital and to pay his respects to Francis.","cn":"卡尔已经让他去医院看望弗朗西斯。"}},{"pos":"PHRASE 短语","cn":"和(死者)告别;参加…的葬礼","en":"If you pay your last respects to someone who has just died, you show your respect or affection for them by coming to see their body or their grave.","ex":{"en":"The son had nothing to do with arranging the funeral, but came along to pay his last respects.","cn":"这个儿子没有参与葬礼的安排，但是来向遗体告别了。"}},{"pos":"PHRASE 短语","cn":"在这个方面/在许多方面","en":"You use expressions like in this respect and in many respects to indicate that what you are saying applies to the feature you have just mentioned or to many features of something.","ex":{"en":"The children are not unintelligent—in fact, they seem quite normal in this respect","cn":"这些孩子并非愚钝——事实上，在这个方面他们似乎很正常。"}},{"pos":"PHRASE 短语","cn":"关于，至于（英国英语中也用in respect of）","en":"You use with respect to to say what something relates to. In British English, you can also say in respect of .","ex":{"en":"Parents often have little choice with respect to the way their child is medically treated","cn":"关于孩子的治疗方法，父母通常没有什么选择的余地。"}}]},"examples":[{"en":"With all due respect, the figures simply do not support you on this.","cn":"恕我直言，这些数字根本不能支持你的观点。"},{"en":"She had always been honest with me, and I respect her for that.","cn":"她一直对我很诚实。我非常敬重她这一点。"}]},"read":{"media":{"uk":"media/uk/read__gb_1.mp3","us":"media/us/read__us_1.mp3"},"oxford":{"phon":"riːd","pos":"verb","senses":[{"en":"to look at and understand the meaning of written or printed words or symbols","cn":"识字；阅读；读懂","g":"[intransitive, transitive]","sc":"words/symbols","ex":{"en":"She's still learning to read.","cn":"她还在学习识字。"}},{"en":"to go through written or printed words, etc. in silence or speaking them to other people","cn":"读；朗读","g":"[intransitive, transitive]","sc":"words/symbols","ex":{"en":"I'm going to go to bed and read.","cn":"我要上床看书去。"}},{"en":"to discover or find out about somebody/something by reading","cn":"读到；查阅到","g":"[intransitive, transitive]","sc":"discover by reading","ex":{"en":"I read about the accident in the local paper.","cn":"我在当地的报纸上看到了这次事故。"}},{"en":"to guess what somebody else is thinking","cn":"猜测；揣摩","g":"[transitive]","sc":"somebody’s mind/thoughts","ex":{"en":"Tell me what you want—I can't read your mind!","cn":"告诉我你想要什么 － 我可猜不透你的心思！"}},{"en":"to look at the movements of somebody’s lips to learn what they are saying","cn":"观唇辨意；读唇语","g":"[transitive]","sc":"somebody’s lips"},{"en":"to understand something in a particular way","cn":"懂得；理解","g":"[transitive]","sc":"understand","ex":{"en":"How do you read the present situation?","cn":"你对目前的形势有何看法？"}},{"en":"to have something written on it; to be written in a particular way","cn":"写着；写成","g":"[transitive]","sc":"of a piece of writing","ex":{"en":"The sign read ‘No admittance’.","cn":"告示牌上写着“禁止入内”。"}},{"en":"to give a particular impression when read","cn":"读起来（给人以某种印象）","g":"[intransitive]","sc":"of a piece of writing","ex":{"en":"Generally, the article reads very well.","cn":"总的来说，这篇文章读起来很不错。"}},{"en":"to show a particular weight, pressure, etc.","cn":"读数为；显示","g":"[transitive]","sc":"measuring instrument","ex":{"en":"What does the thermometer read?","cn":"温度计的读数是多少？"}},{"en":"to get information from a measuring instrument","cn":"看读数","g":"[transitive]","sc":"measuring instrument","ex":{"en":"A man came to read the gas meter.","cn":"一个男子来查了煤气表。"}},{"en":"to hear and understand somebody speaking on a radio set","cn":"听到，听明白（用无线电机讲的话）","g":"[transitive]","sc":"hear","ex":{"en":"‘Do you read me?’ ‘I'm reading you loud and clear.’","cn":"“你听得见我的话吗？”“听见了，你的声音又大又清楚。”"}},{"en":"to replace one word, etc. with another when correcting a text","cn":"替换；将…改为","g":"[transitive]","sc":"replace word","ex":{"en":"For ‘madam’ in line 3 read ‘madman’.","cn":"第 3 行中的 madam 应为 madman。"}},{"en":"to study a subject, especially at a university","cn":"学习；攻读；主修","g":"[transitive, intransitive]","lab":"British English, rather old-fashioned，，","sc":"subject at university","ex":{"en":"I read English at Oxford.","cn":"我在牛津攻读英语。"}},{"en":"to take information from a disk","cn":"读（盘）；从磁盘提取信息","g":"[transitive]","sc":"computing","ex":{"en":"My computer can't read the CD-ROM you sent.","cn":"我的电脑不能读你送来的光盘。"}},{"en":"an act or a period of reading something","cn":"阅读；读书","lab":"especially British English","ex":{"en":"I was having a quiet read when the phone rang.","cn":"我在静静地看书，忽然电话铃响了。"},"pos":"noun"},{"en":"a book, an article, etc. that is good, etc.","cn":"好的（或有意思等的）读物；好书（或文章等）","ex":{"en":"His thrillers are always a gripping read.","cn":"他的惊险小说向来引人入胜。"},"pos":"noun"},{"en":"having knowledge that has been gained from reading books, etc.","cn":"博学的；熟知的；精通的","ex":{"en":"She's very widely read in law.","cn":"她在法律方面知识渊博。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"读;阅读;理解;看懂","en":"When you read something such as a book or article, you look at and understand the words that are written there.","ex":{"en":"Have you read this book?","cn":"你看过这本书吗？"}},{"pos":"VERB 动词","cn":"朗读;出声读;念出","en":"When you read a piece of writing to someone, you say the words aloud.","ex":{"en":"Jay reads poetry so beautifully","cn":"杰伊朗读诗歌很动听。"}},{"pos":"VERB 动词","cn":"读书，阅读（能力）","en":"People who can read have the ability to look at and understand written words.","ex":{"en":"He couldn't read or write","cn":"他不会读写。"}},{"pos":"VERB 动词","cn":"读，识（乐谱）","en":"If you can read music, you have the ability to look at and understand the symbols that are used in written music to represent musical sounds.","ex":{"en":"Later on I learned how to read music.","cn":"后来我学会了怎么识乐谱。"}},{"pos":"VERB 动词","cn":"（电脑）读取（文件或文档）","en":"When a computer reads a file or a document, it takes information from a disk or tape.","ex":{"en":"How can I read a Microsoft Excel file on a computer that only has Works installed?","cn":"我怎样在只安装了Works软件的电脑上读取微软的Excel文件呢？"}},{"pos":"VERB 动词","cn":"写着;标着","en":"You can use read when saying what is written on something or in something. For example, if a notice reads 'Entrance', the word 'Entrance' is written on it.","ex":{"en":"The sign on the bus read 'Private: Not In Service'.","cn":"巴士的标牌上写着“私家车：不对外出租”。"}},{"pos":"VERB 动词","cn":"（文章）读起来…","en":"If you refer to how a piece of writing reads, you are referring to its style.","ex":{"en":"The book reads like a ballad","cn":"这本书读起来像歌谣。"}},{"pos":"N-COUNT 可数名词","cn":"令人愉快的读物；好书（或杂志）","en":"If you say that a book or magazine is a good read, you mean that it is very enjoyable to read.","ex":{"en":"Ben Okri's latest novel is a good read.","cn":"本·奥克里的最新小说很精彩。"}},{"pos":"VERB 动词","cn":"理解;解读","en":"If something is read in a particular way, it is understood or interpreted in that way.","ex":{"en":"The play is being widely read as an allegory of imperialist conquest","cn":"这部剧被广泛解读为对帝国主义征服的讽喻。"}},{"pos":"VERB 动词","cn":"看得出，读懂，看透（想法或心思）","en":"If you read someone's mind or thoughts, you know exactly what they are thinking without them telling you.","ex":{"en":"As if he could read her thoughts, Benny said, 'You're free to go any time you like.'","cn":"班尼仿佛看出了她的心思，说道：“你随时都可以自由离开。”"}},{"pos":"VERB 动词","cn":"理解；读懂；了解","en":"If you can read someone or you can read their gestures, you can understand what they are thinking or feeling by the way they behave or the things they say.","ex":{"en":"If you have to work in a team you must learn to read people","cn":"如果要在一个团队中工作你必须学会了解他人。"}},{"pos":"VERB 动词","cn":"（无线通讯用语）听到","en":"If someone who is trying to talk to you with a radio transmitter says, 'Do you read me?', they are asking you if you can hear them.","ex":{"en":"Alpha-Bravo-Zulu 643 to Saltezar, do you read me? Over","cn":"阿尔法－布拉沃－祖鲁643呼叫萨德扎，能听到我的声音吗？完毕。"}},{"pos":"VERB 动词","cn":"读（表）；记下（仪表上的数字）","en":"When you read a measuring device, you look at it to see what the figure or measurement on it is.","ex":{"en":"When officials like gas and electricity men call to read the meter, ask for identification","cn":"当有燃气或电力公司的职员来抄表时，要请他们出示身份证件。"}},{"pos":"VERB 动词","cn":"（仪器）标明，显示","en":"If a measuring device reads a particular amount, it shows that amount.","ex":{"en":"The thermometer read 105 degrees Fahrenheit","cn":"温度计显示华氏105度。"}},{"pos":"VERB 动词","cn":"攻读;专修","en":"If you read a subject at university, you study it.","ex":{"en":"She read French and German at Cambridge University","cn":"她在剑桥大学学习法语和德语。"}},{"pos":"PHRASE 短语","cn":"完全相信；把…当作真理","en":"If you take something as read, you accept it as true or right and therefore feel that it does not need to be discussed or proved.","ex":{"en":"We took it as read that he must have been a KGB agent","cn":"我们完全相信他曾经是一名克格勃特工。"}},{"pos":"See also:","cn":"","en":"to read between the lines→see: ;"},{"pos":"","cn":"","en":"相关词组：read into read out read up on"}]},"examples":[{"en":"‘Do you read me?’ ‘I'm reading you loud and clear.’ “","cn":"你听得见我的话吗？” “听见了，你的声音又大又清楚。”"},{"en":"For ‘madam’ in line 3 read ‘madman’.","cn":"第 3 行中的 madam 应为 madman。"}]},"respectfully":{"oxford":{"phon":"rɪˈspektfəli","pos":"adverb","senses":[{"en":"in a way that shows respect","cn":"恭敬地","lab":"formal","ex":{"en":"He listened respectfully.","cn":"他恭敬地听着。"}}]},"media":{"uk":"media/uk/respectfully__gb_1.mp3","us":"media/us/respectfully__us_1.mp3"},"examples":[{"en":"He listened respectfully.","cn":"他恭敬地听着。"},{"en":"They listened in respectful silence.","cn":""}]},"recommend":{"oxford":{"phon":"ˌrekəˈmend","pos":"verb","senses":[{"en":"to tell somebody that something is good or useful, or that somebody would be suitable for a particular job, etc.","cn":"推荐；举荐；介绍","ex":{"en":"The hotel's new restaurant comes highly recommended (= a lot of people have praised it).","cn":"这家酒店的新餐厅得到了人们的普遍赞扬。"}},{"en":"to advise a particular course of action; to advise somebody to do something","cn":"劝告；建议","lab":"British English also","ex":{"en":"The report recommended a 10% pay increase.","cn":"报告提议工资增加 10%。"}},{"en":"to make somebody/something seem attractive or good","cn":"使显得吸引人；使受欢迎","ex":{"en":"This system has much to recommend it.","cn":"这套系统有很多可取之处。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"推荐;介绍","en":"If someone recommends a person or thing to you, they suggest that you would find that person or thing good or useful.","ex":{"en":"I have just spent a holiday there and would recommend it to anyone","cn":"我刚刚在那里度过假，很想把它推荐给每一个人。"}},{"pos":"VERB 动词","cn":"建议;劝说（做…)","en":"If you recommend that something is done, you suggest that it should be done.","ex":{"en":"The judge recommended that he serve 20 years in prison","cn":"法官建议判处他20年监禁。"}},{"pos":"VERB 动词","cn":"使受欢迎;使有优势","en":"If something or someone has a particular quality to recommend them, that quality makes them attractive or gives them an advantage over similar things or people.","ex":{"en":"La Noblesse restaurant has much to recommend it","cn":"“贵族”餐馆有很多值得称道之处。"}}]},"media":{"uk":"media/uk/recommend__gb_1.mp3","us":"media/us/recommend__us_1.mp3"},"examples":[{"en":"The hotel's new restaurant comes highly recommended (= a lot of people have praised it).","cn":"这家酒店的新餐厅得到了人们的极力推荐。"},{"en":"He recommended reading the book before seeing the movie.","cn":"他建议先看这本书，再去看这部电影。"}]},"reasoning":{"media":{"uk":"media/uk/reasoning__gb_1.mp3","us":"media/us/reasoning__us_1.mp3"},"oxford":{"phon":"ˈriːzənɪŋ","pos":"noun","senses":[{"en":"the process of thinking about things in a logical way; opinions and ideas that are based on logical thinking","cn":"推想；推理；理性的观点；论证","ex":{"en":"What is the reasoning behind this decision?","cn":"作出这个决定的依据是什么？"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"推理；论证","en":"Reasoning is the process by which you reach a conclusion after thinking about all the facts.","ex":{"en":"...the reasoning behind the decision","cn":"决定背后的论证"}}]},"examples":[{"en":"What is the reasoning behind this decision?","cn":"作出这个决定的依据是什么？"},{"en":"This line of reasoning is faulty.","cn":"这样的思路有问题。"}],"base":"reason"},"reflective":{"oxford":{"phon":"rɪˈflektɪv","pos":"adjective","senses":[{"en":"thinking deeply about things","cn":"沉思的；深思的","lab":"formal","ex":{"en":"a quiet and reflective man","cn":"文静而爱沉思的男子"}},{"en":"reflective surfaces send back light or heat","cn":"（指物体表面）反射热的，反光的","ex":{"en":"reflective car number plates","cn":"反光的汽车牌照"}},{"en":"typical of a particular situation or thing; showing the state or nature of something","cn":"典型的；代表性的；体现状态（或本质）的","ex":{"en":"His abilities are not reflective of the team as a whole.","cn":"他的能力并不代表整队的水平。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沉思的；深思的","en":"If you are reflective, you are thinking deeply about something.","ex":{"en":"I walked on in a reflective mood to the car","cn":"我心事重重地向车子走去。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"反映…的;表现…的;代表性的","en":"If something is reflective of a particular situation or attitude, it is typical of that situation or attitude, or is a consequence of it.","ex":{"en":"The German government's support of the US is not entirely reflective of German public opinion","cn":"德国政府对美国的支持不完全是德国公众意见的反映。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"反射的；反光的","en":"A reflective surface or material sends back light or heat.","ex":{"en":"...a garden of flowing streams, water basins, waterfalls, and a reflective pool","cn":"园里有流动的小溪、水池、瀑布和波光粼粼的游泳池"}}]},"media":{"uk":"media/uk/reflective__gb_1.mp3","us":"media/us/reflective__us_1.mp3"},"examples":[{"en":"On dark nights children should wear reflective clothing.","cn":"在漆黑的夜晚，儿童应该穿反光的衣服。"},{"en":"His abilities are not reflective of the team as a whole.","cn":"他的能力并不代表整队的水平。"}]},"real-world":{"oxford":{"phon":"ˈriːəl wɜːld","pos":"adjective","senses":[{"en":"existing in the real world and not specially invented for a particular purpose","cn":"存在于现实世界的；真实的","ex":{"en":"Teachers need to prepare their students to deal with real-world situations outside the classroom.","cn":"教师应该让学生做好应对课堂以外的现实世界的准备。"}}]},"media":{"uk":"media/uk/real_world_1_gb_1.mp3","us":"media/us/real_world_1_us_1.mp3"},"examples":[{"en":"Teachers need to prepare their students to deal with real-world situations outside the classroom.","cn":"教师应该让学生做好应对课堂以外的现实世界的准备。"}]},"respond":{"media":{"uk":"media/uk/respond__gb_1.mp3","us":"media/us/respond__us_1.mp3"},"oxford":{"phon":"rɪˈspɒnd","pos":"verb","senses":[{"en":"to give a spoken or written answer to somebody/something","cn":"（口头或书面）回答，回应","g":"[intransitive, transitive]","lab":"rather formal","ex":{"en":"I asked him his name, but he didn't respond.","cn":"我问他叫什么名字，可他没回答。"}},{"en":"to do something as a reaction to something that somebody has said or done","cn":"回应；作出反应","g":"[intransitive]","ex":{"en":"How did they respond to the news?","cn":"他们对这则消息有什么反应？"}},{"en":"to react quickly or in the correct way to something/somebody","cn":"反应灵敏；作出正确反应","g":"[intransitive]","ex":{"en":"The car responds very well to the controls.","cn":"这辆汽车操纵自如。"}},{"en":"to improve as a result of a particular kind of treatment","cn":"有改进；见起色；显出效果","g":"[intransitive]","ex":{"en":"The infection did not respond to the drugs.","cn":"这些药物对感染没有起作用。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"回复;回答;回应","en":"When you respond to something that is done or said, you react to it by doing or saying something yourself.","ex":{"en":"They are likely to respond positively to the President's request for aid","cn":"他们可能会对总统的援助要求作出积极回应。"}},{"pos":"VERB 动词","cn":"应对;作出回应;作出反应","en":"When you respond to a need, crisis, or challenge, you take the necessary or appropriate action.","ex":{"en":"This modest group size allows our teachers to respond to the needs of each student.","cn":"这样的小组规模适中，可以使老师照顾到每一个学生的需求。"}},{"pos":"VERB 动词","cn":"有良好反应;有积极效果","en":"If a patient or their injury or illness is responding to treatment, the treatment is working and they are getting better.","ex":{"en":"I'm pleased to say that he is now doing well and responding to treatment.","cn":"我很高兴地说，他现在恢复得不错，治疗取得了积极的效果。"}}]},"examples":[{"en":"When asked about the company's future, the director responded that he remained optimistic.","cn":"问到公司的未来的时候，经理回答说他依然乐观。"},{"en":"The government responded by banning all future demonstrations.","cn":"政府的反应是今后禁止一切示威活动。"}]},"repeated":{"media":{"uk":"media/uk/repeated__gb_1.mp3","us":"media/us/repeated__us_1.mp3"},"oxford":{"phon":"rɪˈpiːtɪd","pos":"adjective","senses":[{"en":"happening, said or done many times","cn":"重复的；反复发生的","ex":{"en":"repeated absences from work","cn":"一再旷工"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"重复的;反复发生的","en":"Repeated actions or events are ones which happen many times.","ex":{"en":"Mr Lawssi apparently did not return the money, despite repeated reminders","cn":"尽管被提醒了很多次，劳西先生显然没有把钱退回来。"}}]},"examples":[{"en":"The victim had been stabbed repeatedly in the chest.","cn":"受害者胸部多处被刺伤。"},{"en":"repeated absences from work","cn":"一再旷工"}],"base":"repeat"},"response":{"media":{"uk":"media/uk/response__gb_1.mp3","us":"media/us/response__us_1.mp3"},"oxford":{"phon":"rɪˈspɒns","pos":"noun","senses":[{"en":"a spoken or written answer","cn":"（口头的或书面的）回答，答复","g":"[countable, uncountable]","ex":{"en":"She made no response.","cn":"她没作任何回答。"}},{"en":"a reaction to something that has happened or been said","cn":"反应；响应","g":"[countable, uncountable]","ex":{"en":"The news provoked an angry response.","cn":"这条消息引起了人们的愤怒。"}},{"en":"a part of a church service that the people sing or speak as an answer to the part that the priest sings or speaks","cn":"（礼拜仪式中的）答唱咏，启应经","g":"[countable, usually plural]","ex":{"en":"The congregation sang the responses.","cn":"会众用歌声回应。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"回复;回答;回应","en":"Your response to an event or to something that is said is your reply or reaction to it.","ex":{"en":"There has been no response to his remarks from the government","cn":"政府尚未对他的言论作出回应。"}}]},"examples":[{"en":"We sent out over 1 000 letters but the response rate has been low (= few people replied).","cn":"我们寄出了 1 000 多封信，但回信寥寥。"},{"en":"The product was developed in response to customer demand.","cn":"这种产品是为了满足顾客的需要而开发的。"}]},"resent":{"media":{"uk":"media/uk/resent__gb_1.mp3","us":"media/us/resent__us_1.mp3"},"oxford":{"phon":"rɪˈzent","pos":"verb","senses":[{"en":"to feel bitter or angry about something, especially because you feel it is unfair","cn":"愤恨；感到气愤；愤愤不平","lab":"formal","ex":{"en":"I deeply resented her criticism.","cn":"我对她的批评感到非常气愤。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"怨恨;憎恶;愤恨","en":"If you resent someone or something, you feel bitter and angry about them.","ex":{"en":"She resents her mother for being so tough on her","cn":"她怨恨母亲对她太严厉。"}}]},"examples":[{"en":"He bitterly resents being treated like a child.","cn":"他十分厌恶被别人当孩子对待。"},{"en":"I deeply resented her criticism.","cn":"我对她的批评感到非常气愤。"}]},"reproduce":{"oxford":{"phon":"ˌriːprəˈdjuːs","pos":"verb","senses":[{"en":"to make a copy of a picture, piece of text, etc.","cn":"复制","g":"[transitive]","ex":{"en":"It is illegal to reproduce these worksheets without permission from the publisher.","cn":"未经出版者许可翻印这些习题是违法的。"}},{"en":"to produce something very similar to something else in a different medium or context; to make something happen again in the same way","cn":"再现；重现","g":"[transitive]","ex":{"en":"The atmosphere of the novel is successfully reproduced in the movie.","cn":"小说的氛围在电影中得到成功再现。"}},{"en":"if people, plants, animals, etc. reproduce or reproduce themselves, they produce young","cn":"繁殖；生育","g":"[intransitive, transitive]","ex":{"en":"Most reptiles reproduce by laying eggs on land.","cn":"大多数爬行动物在陆地产卵进行繁殖。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"复制;模拟;再现","en":"If you try to reproduce something, you try to copy it.","ex":{"en":"I shall not try to reproduce the policemen's English","cn":"我不会试图去模仿那个警察讲的英语。"}},{"pos":"VERB 动词","cn":"复制;临摹;翻印","en":"If you reproduce a picture, speech, or a piece of writing, you make a photograph or printed copy of it.","ex":{"en":"We are grateful to you for permission to reproduce this article.","cn":"非常感谢您允许我们复印这篇文章。"}},{"pos":"VERB 动词","cn":"重复","en":"If you reproduce an action or an achievement, you repeat it.","ex":{"en":"If we can reproduce the form we have shown in the last couple of months we will be successful.","cn":"如果我们能再采用前两个月的形式，我们就会成功。"}},{"pos":"VERB 动词","cn":"繁殖;生殖","en":"When people, animals, or plants reproduce, they produce young.","ex":{"en":"...a society where women are defined by their ability to reproduce","cn":"用生育能力衡量女性价值的社会"}}]},"media":{"uk":"media/uk/reproduce__gb_1.mp3","us":"media/us/reproduce__us_1.mp3"},"examples":[{"en":"Most reptiles reproduce by laying eggs on land.","cn":"大多数爬行动物通过在陆地产卵进行繁殖。"},{"en":"It is illegal to reproduce these worksheets without permission from the publisher.","cn":"未经出版者许可翻印这些习题是违法的。"}]},"respondent":{"oxford":{"phon":"rɪˈspɒndənt","pos":"noun","senses":[{"en":"a person who answers questions, especially in a survey","cn":"回答问题的人；（尤指）调查对象","ex":{"en":"60 per cent of the respondents agreed with the suggestion.","cn":"回复调查的人中 60% 同意这项建议。"}},{"en":"a person who is accused of something","cn":"被告","lab":"law"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(调查和问题的)回答者;答卷人","en":"A respondent is a person who replies to something such as a survey or set of questions.","ex":{"en":"60 percent of the respondents said they disapproved of the president's performance.","cn":"60％的调查对象表示不认可总统的表现。"}},{"pos":"N-COUNT 可数名词","cn":"被告","en":"A respondent is someone who has to defend a case in a law court.","ex":{"en":"In addition, the respondent disclosed professional confidences to one of the patients.","cn":"另外，被告还向其中一位病人透露了行业机密。"}}]},"media":{"uk":"media/uk/respondent__gb_1.mp3","us":"media/us/respondent__us_1.mp3"},"examples":[{"en":"60% of the respondents agreed with the suggestion.","cn":"回复调查的人中 60% 同意这项建议。"},{"en":"Only 62 percent of respondents said they were satisfied.","cn":"回复调查的人中只有62%表示满意。"}]},"relevant":{"oxford":{"phon":"ˈreləvənt","pos":"adjective","senses":[{"en":"closely connected with the subject you are discussing or the situation you are in","cn":"紧密相关的；切题的","ex":{"en":"relevant information/facts/documents/factors","cn":"相关信息／事实／文件／因素"}},{"en":"the fact of being valuable and useful to people in their lives and work","cn":"有价值的；有意义的","ex":{"en":"Her novel is still relevant today.","cn":"她的小说今天仍有现实意义。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"相关的;相应的;有重要性的","en":"Something that is relevant to a situation or person is important or significant in that situation or to that person.","ex":{"en":"We are trying to make politics more relevant to younger people.","cn":"我们试图使政治活动更加贴近年轻人。"}},{"pos":"ADJ 形容词","cn":"适当的;合适的;确切的","en":"The relevant thing of a particular kind is the one that is appropriate.","ex":{"en":"Make sure you enclose all the relevant certificates.","cn":"要保证把所有相关证书都放在里面。"}}]},"media":{"uk":"media/uk/relevant__gb_1.mp3","us":"media/us/relevant__us_1.mp3"},"examples":[{"en":"The applicant has experience in teaching and, more relevantly, in industry.","cn":"这名申请者有教学经验，更重要的是，还有行业经验。"},{"en":"What he said has no direct relevance to the matter in hand.","cn":"他所说的话与眼下的事没有直接关系。"}]},"real":{"media":{"uk":"media/uk/real__gb_1.mp3","us":"media/us/real__us_1.mp3"},"oxford":{"phon":"ˈriːəl","pos":"adjective","senses":[{"en":"actually existing or happening and not imagined or pretended","cn":"真实的；实际存在的；非凭空想象的","sc":"existing/not imagined","ex":{"en":"a real danger/risk/threat/concern","cn":"真正的危险／风险／威胁／担忧"}},{"en":"not false or artificial","cn":"真的；非假冒的；非人工的","sc":"true/not false","ex":{"en":"Are those real flowers?","cn":"那些是真花吗？"}},{"en":"actual or true, rather than what appears to be true","cn":"真正的；确实的；真实的","g":"[only before noun]","sc":"true/not false","ex":{"en":"Tell me the real reason.","cn":"告诉我真正的理由。"}},{"en":"having all the important qualities that it should have to deserve to be called what it is called","cn":"真正的；名副其实的","g":"[only before noun]","sc":"true/not false","ex":{"en":"She never had any real friends at school.","cn":"在学校，她从来没有真正的朋友。"}},{"en":"used to emphasize a state or quality","cn":"（强调状态或品质）","g":"[only before noun]","sc":"for emphasis","ex":{"en":"He looks a real idiot.","cn":"他看上去像个十足的白痴。"}},{"en":"when the effect of such things as price rises on the power of money to buy things is included in the sums","cn":"实际的（已按物价指数等调整）；按购买力衡量的","g":"[only before noun]","sc":"money/income","ex":{"en":"Real wage costs have risen by 10 per cent in the past year.","cn":"在过去的一年里，实际工资成本增加了 10%。"}},{"en":"very","cn":"非常；很","ex":{"en":"That tastes real good.","cn":"味道好极了。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"真的；真实的；非虚构的","en":"Something that is real actually exists and is not imagined, invented, or theoretical.","ex":{"en":"No, it wasn't a dream. It was real","cn":"不，它不是一个梦，它是真实的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"身临其境的;亲身经历的","en":"If something is real to someone, they experience it as though it really exists or happens, even though it does not.","ex":{"en":"Whitechild's life becomes increasingly real to the reader.","cn":"怀特蔡尔德的生活在读者面前显得越来越真实。"}},{"pos":"ADJ 形容词","cn":"天然的；真材实料的；非仿制的；非人工合成的","en":"A material or object that is real is natural or functioning, and not artificial or an imitation.","ex":{"en":"...the smell of real leather","cn":"真皮的气味"}},{"pos":"ADJ 形容词","cn":"真正的；完全的；不掺假的；货真价实的","en":"You can use real to describe someone or something that has all the characteristics or qualities that such a person or thing typically has.","ex":{"en":"...his first real girlfriend","cn":"他第一个真正的女友"}},{"pos":"ADJ 形容词","cn":"真正的;最初的","en":"You can use real to describe something that is the true or original thing of its kind, in contrast to one that someone wants you to believe is true.","ex":{"en":"This was the real reason for her call","cn":"这才是她打电话的真正原因。"}},{"pos":"ADJ 形容词","cn":"最重要的;最典型的","en":"You can use real to describe something that is the most important or typical part of a thing.","ex":{"en":"When he talks, he only gives glimpses of his real self","cn":"当他讲话时，他只流露少许个人的真实想法。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"真实存在的;严肃的","en":"You can use real when you are talking about a situation or feeling to emphasize that it exists and is important or serious.","ex":{"en":"Global warming is a real problem","cn":"全球变暖是个严重的问题。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"真实的;真诚的","en":"You can use real to emphasize a quality that is genuine and sincere.","ex":{"en":"You've been drifting from job to job without any real commitment","cn":"你从一个工作跳到另一个工作，从没有真正投入进去。"}},{"pos":"ADJ 形容词","cn":"（放在名词前）十足的，绝对的","en":"You can use real before nouns to emphasize your description of something or someone.","ex":{"en":"'It's a fabulous deal, a real bargain.'","cn":"“这桩买卖真让人难以置信，绝对合算。”"}},{"pos":"ADJ 形容词","cn":"（成本或价值）实际的，净的，实的","en":"The real cost or value of something is its cost or value after other amounts have been added or subtracted and when factors such as the level of inflation have been considered.","ex":{"en":"...the real cost of borrowing.","cn":"借款的实际成本"}},{"pos":"ADV 副词","cn":"（用于形容词或副词前表示强调）非常，真正","en":"You can use real to emphasize an adjective or adverb.","ex":{"en":"He is finding prison life 'real tough'","cn":"他发现监狱生活“确实难熬”。"}},{"pos":"PHRASE 短语","cn":"真实地;真正地;不是假装","en":"If you say that someone does something for real, you mean that they actually do it and do not just pretend to do it.","ex":{"en":"The sex scenes were just good acting. We didn't do it for real.","cn":"床戏只是逼真的表演。我们没有来真的。"}},{"pos":"PHRASE 短语","cn":"来真的，真是这样（表示令人吃惊）","en":"If you think that someone or something is very surprising, you can ask if they are for real .","ex":{"en":"Is this guy for real?","cn":"这家伙是来真的吗？"}},{"pos":"PHRASE 短语","cn":"真品；非仿冒品；真实事件","en":"If you say that a thing or event is the real thing, you mean that it is the thing or event itself, rather than an imitation or copy.","ex":{"en":"The counterfeits sell for about $20 less than the real thing","cn":"赝品比真货便宜大约20美元。"}}]},"examples":[{"en":"See the real Africa on one of our walking safaris.","cn":"参加一次我们的观察野兽徒步旅行，实地看一看非洲吧。"},{"en":"In the movies guns kill people instantly, but it's not like that in real life.","cn":"电影中，枪能使人在瞬间毙命，而实际情况并非如此。"}]},"region":{"media":{"uk":"media/uk/region__gb_1.mp3","us":"media/us/region__us_1.mp3"},"oxford":{"phon":"ˈriːdʒən","pos":"noun","senses":[{"en":"a large area of land, usually without exact limits or borders","cn":"（通常界线不明的）地区，区域，地方","g":"[countable]","ex":{"en":"mountainous/coastal regions","cn":"山区；沿海地区"}},{"en":"one of the areas that a country is divided into, that has its own customs and/or its own government","cn":"行政区","g":"[countable]","ex":{"en":"Bilbao is the largest city in the Basque region in northern Spain.","cn":"毕尔巴鄂是西班牙北部巴斯克地区最大的城市。"}},{"en":"all of a country except the capital city","cn":"（一国除首都以外的）全部地区，所有区域","g":"[plural]","lab":"British English","ex":{"en":"People in the regions should not have to travel to London to fly to the United States.","cn":"该地区的人们不必前往伦敦飞往美国。"}},{"en":"a part of the body, usually one that has a particular character or problem","cn":"（通常指有某种特性或问题的）身体部位","g":"[countable]","ex":{"en":"pains in the abdominal region","cn":"腹部的疼痛"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"地区;地带;行政区域","en":"A region is a large area of land that is different from other areas of land, for example because it is one of the different parts of a country with its own customs and characteristics, or because it has a particular geographical feature.","ex":{"en":"...Barcelona, capital of the autonomous region of Catalonia.","cn":"加泰罗尼亚自治区首府巴塞罗那"}},{"pos":"N-PLURAL 复数名词","cn":"（首都以外的）各地区，外省","en":"The regions are the parts of a country that are not the capital city and its surrounding area.","ex":{"en":"...London and the regions","cn":"伦敦和外省地区"}},{"pos":"N-COUNT 可数名词","cn":"（身体的）部位，区域","en":"You can refer to a part of your body as a region.","ex":{"en":"...the pelvic region.","cn":"骨盆区"}},{"pos":"PHRASE 短语","cn":"（指数量）差不多，在…左右，大约","en":"You say in the region of to indicate that an amount that you are stating is approximate.","ex":{"en":"The scheme will cost in the region of six million pounds.","cn":"这个计划将耗资大约600万英镑。"}}]},"examples":[{"en":"one of the most densely populated regions of North America","cn":"北美人口最为稠密的地区之一"},{"en":"He earns somewhere in the region of €50 000.","cn":"他大约赚 5 万欧元。"}]},"refugee":{"oxford":{"phon":"ˌrefjuˈdʒiː","pos":"noun","senses":[{"en":"a person who has been forced to leave their country or home, because there is a war or for political, religious or social reasons","cn":"避难者；逃亡者；难民","ex":{"en":"There has been a steady flow of refugees from the war zone.","cn":"难民持续从交战地区涌出。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"难民；寻求庇护者","en":"Refugees are people who have been forced to leave their homes or their country, either because there is a war there or because of their political or religious beliefs."}]},"media":{"uk":"media/uk/refugee__gb_1.mp3","us":"media/us/refugee__us_1.mp3"},"examples":[{"en":"a steady flow of refugees from the war zone","cn":"从交战地区不断涌出的难民"},{"en":"political/economic refugees","cn":"政治避难者；由于经济危机而造成的难民"}]},"religion":{"media":{"uk":"media/uk/religion__gb_1.mp3","us":"media/us/religion__us_1.mp3"},"oxford":{"phon":"rɪˈlɪdʒən","pos":"noun","senses":[{"en":"the belief in the existence of a god or gods, and the activities that are connected with the worship of them, or in the teachings of a spiritual leader","cn":"宗教；宗教信仰；精神信仰","g":"[uncountable]","ex":{"en":"Is there always a conflict between science and religion?","cn":"科学和宗教信仰之间是否永远存在着冲突？"}},{"en":"one of the systems of faith that are based on the belief in the existence of a particular god or gods, or in the teachings of a spiritual leader","cn":"宗教；教派","g":"[countable]","lab":"North American English","ex":{"en":"the Jewish religion","cn":"犹太教"}},{"en":"a particular interest or influence that is very important in your life","cn":"特别的兴趣；重大的影响","g":"[singular]","ex":{"en":"For him, football is an absolute religion.","cn":"对于他来说，足球就是他至高无上的追求。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"宗教信仰;宗教活动","en":"Religion is belief in a god or gods and the activities that are connected with this belief, such as praying or worshipping in a building such as a church or temple.","ex":{"en":"...his understanding of Indian philosophy and religion","cn":"他对印度哲学和宗教信仰的理解"}},{"pos":"N-COUNT 可数名词","cn":"宗教;教派","en":"A religion is a particular system of belief in a god or gods and the activities that are connected with this system.","ex":{"en":"...the Christian religion.","cn":"基督教"}},{"pos":"PHRASE 短语","cn":"(突然)信教，皈依（某种）宗教","en":"If you say that someone has got religion, you are referring in a mocking way to the fact that they have suddenly decided to follow a particular religion.","ex":{"en":"This guy got religion about a year back.","cn":"这家伙一年前信了教。"}}]},"examples":[{"en":"Is there always a conflict between science and religion?","cn":"科学和宗教信仰之间是否永远存在着冲突？"},{"en":"For him, football is an absolute religion.","cn":"对于他来说，足球就是他至高无上的追求。"}]},"result":{"media":{"uk":"media/uk/result__gb_1.mp3","us":"media/us/result__us_1.mp3"},"oxford":{"phon":"rɪˈzʌlt","pos":"noun","senses":[{"en":"a thing that is caused or produced because of something else","cn":"后果；结果","g":"[countable]","sc":"caused by something","ex":{"en":"And did your intervention produce the desired result?","cn":"你的干预得到满意的结果了吗？"}},{"en":"the final score or the name of the winner in a sports event, competition, election, etc.","cn":"结果（包括比分、得票、获胜者或当选者名单等）","g":"[countable]","sc":"of game/election","ex":{"en":"the election results","cn":"选举结果"}},{"en":"a victory or a success","cn":"胜利；成功","g":"[countable, usually singular]","lab":"British English, informal，，","sc":"of game/election","ex":{"en":"We badly need to get a result from this match.","cn":"这场比赛我们非赢不可。"}},{"en":"the mark or grade you get in an exam or in a number of exams","cn":"得分；成绩","g":"[countable, usually plural]","lab":"British English","sc":"of exam","ex":{"en":"Have you had your results yet?","cn":"你知道考试成绩了吗？"}},{"en":"the information that you get from a scientific test or piece of research","cn":"结果；成果","g":"[countable, usually plural]","sc":"of test/research","ex":{"en":"Other research has yielded similar results.","cn":"其他研究得出类似结果。"}},{"en":"the information that you get from a computer search","cn":"（计算机搜索的）结果","g":"[countable, usually plural]","sc":"of computer search","ex":{"en":"My search produced several thousand results.","cn":"我的搜索产生了数千个结果。"}},{"en":"things that are achieved successfully","cn":"成功实现的事；成果；成效","g":"[plural]","sc":"success","ex":{"en":"The project is beginning to show results.","cn":"这项工程开始显出成效。"}},{"en":"the amount of profit or loss made by a business over a particular period of time","cn":"财务情况；业绩","g":"[countable, usually plural]","sc":"of business","ex":{"en":"Companies are required by law to report their financial results on a quarterly basis.","cn":"按法律要求公司应按季度报告其财务情况。"}},{"en":"to make something happen","cn":"造成；导致","ex":{"en":"A heavy frost could result in loss of the crop.","cn":"严重的霜冻可能导致农作物歉收。"},"pos":"verb"},{"en":"to happen because of something else that happened first","cn":"（因…）发生；（随…）产生","g":"[intransitive]","ex":{"en":"When water levels rise, flooding results.","cn":"水位上升，就会发生洪水。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"结果;后果;成果;效果","en":"A result is something that happens or exists because of something else that has happened.","ex":{"en":"Compensation is available for people who have developed asthma as a direct result of their work","cn":"直接因工作原因患上哮喘的人会获得赔偿。"}},{"pos":"VERB 动词","cn":"导致;引起;造成","en":"If something results in a particular situation or event, it causes that situation or event to happen.","ex":{"en":"Fifty per cent of road accidents result in head injuries","cn":"50％的道路交通事故都会导致头部损伤。"}},{"pos":"VERB 动词","cn":"由…产生;由…引起","en":"If something results from a particular event or action, it is caused by that event or action.","ex":{"en":"Many hair problems result from what you eat","cn":"很多头发问题都是由饮食引起的。"}},{"pos":"N-COUNT 可数名词","cn":"(比赛的)结果，结局","en":"A result is the situation that exists at the end of a contest.","ex":{"en":"'What was the result?' — 'One-nil to Leeds.'","cn":"“比赛结果怎样？”——“利兹队以1比0获胜。”"}},{"pos":"N-COUNT 可数名词","cn":"(计算的)结果;得数","en":"A result is the number that you get when you do a calculation.","ex":{"en":"They found their computers producing different results from exactly the same calculation.","cn":"他们发现他们的计算机进行完全相同的计算会得出不同的结果。"}},{"pos":"N-COUNT 可数名词","cn":"(考试的)成绩，分数","en":"Your results are the marks or grades that you get for examinations you have taken.","ex":{"en":"Kate's exam results were excellent.","cn":"凯特的考试成绩非常出色。"}}]},"examples":[{"en":"It was a large explosion and the resulting damage was extensive.","cn":"爆炸相当剧烈，造成的破坏范围很大。"},{"en":"This decision could have serious consequences for the industry.","cn":"这项决定可能对该行业造成严重后果。"}]},"regret":{"media":{"uk":"media/uk/regret__gb_1.mp3","us":"media/us/regret__us_1.mp3"},"oxford":{"phon":"rɪˈɡret","pos":"verb","senses":[{"en":"to feel sorry about something you have done or about something that you have not been able to do","cn":"感到遗憾；惋惜；懊悔","ex":{"en":"If you don't do it now, you'll only regret it.","cn":"你如果现在不做，以后一定会后悔的。"}},{"en":"used to say in a polite or formal way that you are sorry or sad about a situation","cn":"（有礼貌地或正式地表示抱歉、痛惜或悲伤）","lab":"formal","ex":{"en":"The airline regrets any inconvenience.","cn":"航空公司对所造成的任何不便表示歉意。"}},{"en":"a sad feeling because of something that has happened or something that you have done or not done","cn":"痛惜；懊悔；遗憾；失望","ex":{"en":"a feeling/pang/twinge of regret","cn":"一阵痛悔之情"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"对…感到后悔;因…遗憾","en":"If you regret something that you have done, you wish that you had not done it.","ex":{"en":"I simply gave in to him, and I've regretted it ever since","cn":"我就向他屈服了，从那以后我一直后悔。"}},{"pos":"N-VAR 可变名词","cn":"悔恨;失望;后悔;惋惜","en":"Regret is a feeling of sadness or disappointment, which is caused by something that has happened or something that you have done or not done.","ex":{"en":"My great regret in life is that I didn't bring home the America's Cup","cn":"我这辈子最大的遗憾就是没有把美洲杯捧回家。"}},{"pos":"VERB 动词","cn":"为…抱歉;很遗憾地说/通知你","en":"You can say that you regret something as a polite way of saying that you are sorry about it. You use expressions such as I regret to say or I regret to inform you to show that you are sorry about something.","ex":{"en":"'I very much regret the injuries he sustained,' he said","cn":"“我对他的受伤感到很遗憾，”他说。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"抱歉；遗憾","en":"If someone expresses regret about something, they say that they are sorry about it.","ex":{"en":"He expressed great regret and said that surgeons would attempt to reverse the operation","cn":"他深表歉意，说外科医生会努力消除手术造成的损伤。"}}]},"examples":[{"en":"He gave up teaching in 2009, much to the regret of his students.","cn":"他于 2009 年放弃了教学，这使他的学生深感遗憾。"},{"en":"‘I've had a wonderful life,’ she said, ‘I don't regret a thing.’ “","cn":"我一辈子生活得很好，”她说，“我没什么可遗憾的。”"}]},"refrain":{"media":{"uk":"media/uk/refrain__gb_1.mp3","us":"media/us/refrain__us_1.mp3"},"oxford":{"phon":"rɪˈfreɪn","pos":"verb","senses":[{"en":"to stop yourself from doing something, especially something that you want to do","cn":"克制；节制；避免","ex":{"en":"They appealed to the protesters to refrain from violence.","cn":"他们呼吁抗议者避免使用暴力。"}},{"en":"a comment or complaint that is often repeated","cn":"经常重复的评价（或抱怨）","ex":{"en":"Complaints about poor food in schools have become a familiar refrain.","cn":"抱怨学校饭菜差已是耳熟能详的老调了。"},"pos":"noun"},{"en":"the part of a song or a poem that is repeated after each verse","cn":"副歌；迭歌；迭句","ex":{"en":"The choir's sopranos took up the refrain.","cn":"合唱队的女高音开始唱副歌部份。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"克制;忍住","en":"If you refrain from doing something, you deliberately do not do it.","ex":{"en":"Mrs Hardie refrained from making any comment","cn":"哈迪夫人忍住不作任何评论。"}},{"pos":"N-COUNT 可数名词","cn":"（歌曲的）叠句，副歌部分","en":"A refrain is a short, simple part of a song, which is repeated many times.","ex":{"en":"...a refrain from an old song.","cn":"一首老歌的副歌部分"}},{"pos":"N-COUNT 可数名词","cn":"反复说的话;老调","en":"A refrain is a comment or saying that people often repeat.","ex":{"en":"Rosa's constant refrain is that she doesn't have a life.","cn":"罗莎总是重复的一句话就是她没有像样的生活。"}}]},"examples":[{"en":"He has refrained from criticizing the government in public.","cn":"他克制住了自己，没有在公开场合批评政府。"},{"en":"Complaints about poor food in schools have become a familiar refrain.","cn":"抱怨学校饭菜差已是耳熟能详的老调了。"}]},"respecting":{"oxford":{"phon":"rɪˈspektɪŋ","pos":"preposition","senses":[{"en":"in connection with","cn":"关于；至于","ex":{"en":"information respecting the child’s whereabouts","cn":"关于孩子下落的消息"}}]},"media":{"uk":"media/uk/respecting__gb_1.mp3","us":"media/us/respecting__us_1.mp3"},"examples":[{"en":"information respecting the child's whereabouts","cn":"关于孩子下落的消息"},{"en":"A discussion took place respecting the provision of science teaching.","cn":"关于自然科学课的开设展开了一场讨论。"}],"base":"respect"},"recrimination":{"media":{"uk":"media/uk/recrimination__gb_1.mp3","us":"media/us/recrimination__us_1.mp3"},"oxford":{"phon":"rɪˌkrɪmɪˈneɪʃn","pos":"noun","senses":[{"en":"an angry statement that somebody makes accusing somebody else of something, especially in response to a similar statement from them","cn":"指责；反诉；反控","ex":{"en":"bitter recriminations","cn":"激烈的反诉"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"反诉;相互指责;反唇相讥","en":"Recriminations are accusations that two people or groups make about each other.","ex":{"en":"The bitter rows and recriminations have finally ended the relationship","cn":"激烈的争吵和相互指责最终为他们的感情画上了句号。"}}]},"examples":[{"en":"We spent the rest of the evening in mutual recrimination.","cn":"我们后来一晚上都在相互指责。"},{"en":"bitter recriminations","cn":"激烈的反诉"}]},"resize":{"oxford":{"phon":"ˌriːˈsaɪz","pos":"verb","senses":[{"en":"to make something bigger or smaller, especially an image on a computer screen","cn":"改变（尤指计算机图像等）的大小"}]},"media":{"uk":"media/uk/resize__gb_1.mp3","us":"media/us/resize__us_1.mp3"}},"reunion":{"media":{"uk":"media/uk/reunion__gb_1.mp3","us":"media/us/reunion__us_1.mp3"},"oxford":{"phon":"ˌriːˈjuːniən","pos":"noun","senses":[{"en":"a social occasion or party attended by a group of people who have not seen each other for a long time","cn":"重逢；团聚；聚会","g":"[countable]","ex":{"en":"a family reunion","cn":"家人团聚"}},{"en":"the act of people coming together after they have been apart for some time","cn":"相聚；团圆","g":"[countable, uncountable]","ex":{"en":"an emotional reunion between mother and son","cn":"母子团圆的激动场面"}},{"en":"the action of becoming a single group or organization again","cn":"重新结合；再度联合","g":"[uncountable]","ex":{"en":"the reunion of the Church of England with the Church of Rome","cn":"英格兰圣公会和天主教的再度联合"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（家庭、学校及其他团体成员的）团聚，重聚，聚会","en":"A reunion is a party attended by members of the same family, school, or other group who have not seen each other for a long time.","ex":{"en":"The Association holds an annual reunion","cn":"这个协会每年聚会一次。"}},{"pos":"N-VAR 可变名词","cn":"重聚;重逢;团圆","en":"A reunion is a meeting between people who have been separated for some time.","ex":{"en":"The children weren't allowed to see her for nearly a week. It was a very emotional reunion.","cn":"孩子们将近一周都没能见到她。这是一次令人激动的团聚。"}}]},"examples":[{"en":"the reunion of the Church of England with the Church of Rome","cn":"英国国教和罗马天主教的再度联合"},{"en":"Christmas is a time of reunion.","cn":"圣诞节是团聚的日子。"}]},"rental":{"media":{"uk":"media/uk/rental__gb_1.mp3","us":"media/us/rental__us_1.mp3"},"oxford":{"phon":"ˈrentl","pos":"noun","senses":[{"en":"the amount of money that you pay to use something for a particular period of time","cn":"租金","g":"[uncountable, countable, usually singular]","lab":"especially in North American English","ex":{"en":"Telephone charges include line rental.","cn":"电话费包括线路租用费。"}},{"en":"the act of renting something or an arrangement to rent something","cn":"出租；租赁；招租","g":"[uncountable]","lab":"especially North American English","ex":{"en":"the world’s largest car rental company","cn":"世界最大的汽车租赁公司"}},{"en":"a house, car or piece of equipment that you can rent","cn":"租用的房屋（或汽车、设备等）","g":"[countable]","lab":"especially North American English","ex":{"en":"‘Is this your own car?’ ‘No, it's a rental.’","cn":"“这是你自己的车吗？”“不，是租来的。”"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"租用;出租;租赁","en":"The rental of something such as a car or piece of equipment is the activity or process of renting it.","ex":{"en":"We can organise car rental from Chicago O'Hare Airport.","cn":"我们可以安排提供从芝加哥奥黑尔机场出发的租车服务。"}},{"pos":"N-COUNT 可数名词","cn":"租金;租用费","en":"The rental is the amount of money that you pay when you rent something such as a car, property, or piece of equipment.","ex":{"en":"It has been let at an annual rental of 393,000.","cn":"它以每年39.3万英镑的价格被租了出去。"}},{"pos":"ADJ 形容词","cn":"租用的;出租的","en":"You use rental to describe things that are connected with the renting out of goods, properties, and services.","ex":{"en":"A friend drove her to Oxford, where she picked up a rental car","cn":"一个朋友开车把她送到牛津，在那里她租了一辆车。"}}]},"examples":[{"en":"‘Is this your own car?’ ‘No, it's a rental.’ “","cn":"这是你自己的车吗？” “不，是租来的。”"},{"en":"Telephone charges include line rental.","cn":"电话费包括线路租用费。"}]},"replicate":{"oxford":{"phon":"ˈreplɪkeɪt","pos":"verb","senses":[{"en":"to copy something exactly","cn":"复制；（精确地）仿制","g":"[transitive]","lab":"formal","ex":{"en":"Subsequent experiments failed to replicate these findings.","cn":"后来的实验没有得出同样的结果。"}},{"en":"to produce exact copies of itself","cn":"再造；再生；自我复制","g":"[transitive, intransitive]","lab":"specialist","ex":{"en":"The drug prevents the virus from replicating itself.","cn":"这种药能防止病毒复制。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"复制;重做;使复现","en":"If you replicate someone's experiment, work, or research, you do it yourself in exactly the same way.","ex":{"en":"He invited her to his laboratory to see if she could replicate the experiment.","cn":"他邀请她到他的实验室看她能否复制该实验。"}},{"pos":"VERB 动词","cn":"(分子)复制","en":"If a molecule replicates, it divides into smaller molecules which are exact copies of itself.","ex":{"en":"Cells can reproduce but only molecules can replicate.","cn":"细胞可以再生，但是只有分子可以复制。"}}]},"media":{"uk":"media/uk/replicate__gb_1.mp3","us":"media/us/replicate__us_1.mp3"},"examples":[{"en":"Subsequent experiments failed to replicate these findings.","cn":"后来的实验没有得出同样的结果。"},{"en":"The drug prevents the virus from replicating itself.","cn":"这种药能防止病毒复制。"}]},"recovery":{"media":{"uk":"media/uk/recovery__gb_1.mp3","us":"media/us/recovery__us_1.mp3"},"oxford":{"phon":"rɪˈkʌvəri","pos":"noun","senses":[{"en":"the process of becoming well again after an illness or injury","cn":"恢复；痊愈","g":"[uncountable, countable, usually singular]","ex":{"en":"My father has made a full recovery from the operation.","cn":"我父亲手术后已完全康复了。"}},{"en":"the process of improving or becoming stronger again","cn":"改善；回升；复苏","g":"[uncountable, countable, usually singular]","ex":{"en":"The government is forecasting an economic recovery.","cn":"政府预测经济会复苏。"}},{"en":"the action or process of getting something back that has been lost or stolen","cn":"取回；收回；复得","g":"[uncountable]","ex":{"en":"There is a reward for information leading to the recovery of the missing diamonds.","cn":"凡能为找回丢失的钻石提供线索者可获奖赏。"}},{"en":"the room in a hospital where patients are kept immediately after an operation","cn":"（供刚做完手术的病人使用的）监护室","g":"[uncountable]","ex":{"en":"Your mother is now in recovery.","cn":"你的母亲现在正在康复中。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（身体的）恢复，康复","en":"If a sick person makes a recovery, he or she becomes well again.","ex":{"en":"He made a remarkable recovery from a shin injury","cn":"他的胫骨伤恢复得相当不错。"}},{"pos":"N-VAR 可变名词","cn":"（经济的）复苏，好转","en":"When there is a recovery in a country's economy, it improves.","ex":{"en":"Interest-rate cuts have failed to bring about economic recovery","cn":"利率下调没有带来经济复苏。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"收回；取回；失而复得","en":"You talk about the recovery of something when you get it back after it has been lost or stolen.","ex":{"en":"A substantial reward is being offered for the recovery of a painting by Turner","cn":"为追回特纳的一幅画，已发布了重金悬赏令。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（身体或精神状态的）恢复","en":"You talk about the recovery of someone's physical or mental state when they return to this state.","ex":{"en":"...the abrupt loss and recovery of consciousness.","cn":"意识的突然丧失和恢复"}},{"pos":"PHRASE 短语","cn":"在恢复当中；正在好转","en":"If someone is in recovery, they are being given a course of treatment to help them recover from something such as a drug habit or mental illness.","ex":{"en":"...Carole, a compulsive pot smoker and alcoholic in recovery.","cn":"卡萝尔，一位正在戒断康复当中的大麻吸食者和酗酒者"}}]},"examples":[{"en":"There is a reward for information leading to the recovery of the missing diamonds.","cn":"凡能为找回丢失的钻石提供线索者可获奖赏。"},{"en":"to make a remarkable/quick/speedy/slow, etc. recovery","cn":"恢复显著、很快、迅速、缓慢等"}]},"recording":{"media":{"uk":"media/uk/recording__gb_1.mp3","us":"media/us/recording__us_1.mp3"},"oxford":{"phon":"rɪˈkɔːdɪŋ","pos":"noun","senses":[{"en":"sound or pictures that have been recorded on computer files or on CD, DVD, video, etc.","cn":"录制的音像；录音；视频；录像","g":"[countable]","ex":{"en":"an audio recording","cn":"录音"}},{"en":"the process of making a record, film, radio or television show, etc.","cn":"录制","g":"[uncountable]","ex":{"en":"during the recording of the show","cn":"在录制这场表演期间"}},{"en":"the process or act of writing down and storing information for official purposes","cn":"（正式的）记录，记载","g":"[uncountable, singular]","ex":{"en":"the recording of financial transactions","cn":"关于金融交易的记载"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"唱片；录音带；录像带","en":"A recording of something is a record, CD, tape, or video of it.","ex":{"en":"...a video recording of a police interview.","cn":"警方讯问的录像带"}},{"pos":"N-UNCOUNT 不可数名词","cn":"录制","en":"Recording is the process of making records, CDs, tapes, or videos.","ex":{"en":"...the recording industry.","cn":"音像业"}}]},"examples":[{"en":"during the recording of the show","cn":"在录制这场表演期间"},{"en":"a video recording of the wedding","cn":"婚礼的录像"}],"base":"record"},"repair":{"media":{"uk":"media/uk/repair__gb_1.mp3","us":"media/us/repair__us_1.mp3","img":["media/ldoce/img/repair.jpg"]},"oxford":{"phon":"rɪˈpeə(r)","pos":"verb","senses":[{"en":"to fix something that is broken, damaged or torn","cn":"修理；修补；修缮","ex":{"en":"to repair a car/television","cn":"修车；修电视"}},{"en":"to say or do something in order to improve a bad or unpleasant situation","cn":"补救；纠正；弥补","ex":{"en":"to repair relations/a relationship","cn":"修复关系"}},{"en":"an act of repairing something","cn":"修理；修补；修缮","ex":{"en":"They agreed to pay the costs of any repairs.","cn":"他们答应支付所有的修理费。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"修理;修补","en":"If you repair something that has been damaged or is not working properly, you mend it.","ex":{"en":"Goldsmith has repaired the roof to ensure the house is wind-proof","cn":"戈德史密斯修理了屋顶，以确保房屋能够抗风。"}},{"pos":"VERB 动词","cn":"补救，挽救(关系或声誉)","en":"If you repair a relationship or someone's reputation after it has been damaged, you do something to improve it.","ex":{"en":"The government continued to try to repair the damage caused by the minister's interview","cn":"政府不断努力弥补因该部长接受采访带来的不良影响。"}},{"pos":"N-VAR 可变名词","cn":"修理;修补;补救","en":"A repair is something that you do to mend a machine, building, piece of clothing, or other thing that has been damaged or is not working properly.","ex":{"en":"Many women know how to carry out repairs on their cars","cn":"许多妇女懂得怎样修自己的车。"}},{"pos":"VERB 动词","cn":"到…去;前去","en":"If someone repairs to a particular place, they go there.","ex":{"en":"We then repaired to the pavilion for lunch.","cn":"然后我们就去凉亭吃午饭了。"}},{"pos":"PHRASE 短语","cn":"(建筑等)维修良好/糟糕，状况良好/ 糟糕","en":"If something such as a building is in good repair, it is in good condition. If it is in bad repair, it is in bad condition.","ex":{"en":"The monks of Ettal keep the abbey in good repair","cn":"埃塔尔的修道士把修道院维护得很好。"}}]},"examples":[{"en":"It's almost 15 years old. It isn't worth having it repaired.","cn":"这东西差不多 15 年了。不值得送去修了。"},{"en":"It was too late to repair the damage done to their relationship.","cn":"太晚了，无法弥补他们的关系所遭受的创伤了。"}]},"recent":{"media":{"uk":"media/uk/recent__gb_1.mp3","us":"media/us/recent__us_1.mp3"},"oxford":{"phon":"ˈriːsnt","pos":"adjective","senses":[{"en":"that happened or began only a short time ago","cn":"近来的；新近的","ex":{"en":"a recent study/report/survey","cn":"最近的研究／报告／调查"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"近来的；最近的；最新的","en":"A recent event or period of time happened only a short while ago.","ex":{"en":"In the most recent attack one man was shot dead and two others were wounded","cn":"在最近的一次袭击中，一名男子遇袭身亡，另外两人受伤。"}}]},"examples":[{"en":"There have been many changes in recent years.","cn":"近几年发生了许多变化。"},{"en":"his most recent visit to Poland","cn":"他最近到波兰的访问"}]},"regulate":{"oxford":{"phon":"ˈreɡjuleɪt","pos":"verb","senses":[{"en":"to control something by means of rules","cn":"（用规则条例）约束，控制，管理","g":"[transitive, intransitive]","ex":{"en":"The department is responsible for regulating the insurance industry.","cn":"该部门负责监管保险业。"}},{"en":"to control the speed, pressure, temperature, etc. in a machine or system","cn":"调节，控制（速度、压力、温度等）","g":"[transitive]","ex":{"en":"This valve regulates the flow of water.","cn":"这个阀门调节水流。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(尤指通过规章制度)管理，调整，控制","en":"To regulate an activity or process means to control it, especially by means of rules.","ex":{"en":"The powers of the European Commission to regulate competition are increasing","cn":"欧盟委员会对竞争的监管权越来越大。"}}]},"media":{"uk":"media/uk/regulate__gb_1.mp3","us":"media/us/regulate__us_1.mp3"},"examples":[{"en":"The activities of credit companies are regulated by law.","cn":"信贷公司的业务受法律的制约。"},{"en":"It is up to the regulating authority to put the measures into effect.","cn":"应该由管理部门落实这些措施。"}]},"refuse":{"media":{"uk":"media/uk/refuse__gb_1.mp3","us":"media/us/refuse__us_1.mp3"},"oxford":{"phon":"rɪˈfjuːz","pos":"verb","senses":[{"en":"to say or show that you will not do something that somebody has asked you to do","cn":"拒绝；回绝","g":"[intransitive, transitive]","ex":{"en":"Go on, ask her; she can hardly refuse.","cn":"去吧，去求她，她不大可能拒绝。"}},{"en":"to say that you do not want something that has been offered to you","cn":"推却；回绝","g":"[transitive, intransitive]","ex":{"en":"I politely refused their invitation.","cn":"我礼貌地回绝了他们的邀请。"}},{"en":"to say that you will not allow something; to say that you will not give or allow somebody something that they want or need","cn":"不准许；拒绝给（所需之物）","g":"[transitive]","ex":{"en":"He refused our request for an interview.","cn":"他拒绝了我们的采访请求。"}},{"en":"to fail to do what you want or expect it to do","cn":"拒不；未如所愿","g":"[transitive]","ex":{"en":"The car refused to start.","cn":"汽车发动不起来。"}},{"en":"waste material that has been thrown away","cn":"废弃物；垃圾","lab":"British English","ex":{"en":"domestic/household refuse","cn":"生活垃圾"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"拒绝;回绝","en":"If you refuse to do something, you deliberately do not do it, or you say firmly that you will not do it.","ex":{"en":"He refused to comment after the trial","cn":"庭审之后他拒绝作出评论。"}},{"pos":"VERB 动词","cn":"拒绝给予;不肯给予","en":"If someone refuses you something, they do not give it to you or do not allow you to have it.","ex":{"en":"The United States has refused him a visa","cn":"美国拒绝给他发放签证。"}},{"pos":"VERB 动词","cn":"拒绝（接受）","en":"If you refuse something that is offered to you, you do not accept it.","ex":{"en":"He offered me a second drink which I refused","cn":"他请我再喝一杯，我没有接受。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"废物，垃圾（主要用于官方语言）","en":"Refuse consists of the rubbish and all the things that are not wanted in a house, shop, or factory, and that are regularly thrown away; used mainly in official language.","ex":{"en":"The District Council made a weekly collection of refuse.","cn":"区政务委员会每周收取一次垃圾。"}}]},"examples":[{"en":"The job offer was simply too good to refuse.","cn":"这个工作机会太好了，简直无法推掉。"},{"en":"Go on, ask her; she can hardly refuse.","cn":"去吧，去求她，她不大会拒绝。"}]},"relief":{"media":{"img":["media/pic/architecture_comp.jpg","media/thumb/portico.jpg"],"uk":"media/uk/relief__gb_1.mp3","us":"media/us/relief__us_1.mp3"},"oxford":{"phon":"rɪˈliːf","pos":"noun","senses":[{"en":"the feeling of happiness that you have when something unpleasant stops or does not happen","cn":"（不快过后的）宽慰，轻松；解脱","g":"[uncountable, singular]","sc":"removal of anxiety/pain","ex":{"en":"I felt a huge sense of relief when I heard they were all OK.","cn":"听说他们都平安无事，我倍感轻松。"}},{"en":"the act of removing or reducing pain, worry, etc.","cn":"（焦虑、痛苦等的）减轻，消除，缓和","g":"[uncountable]","sc":"removal of anxiety/pain","ex":{"en":"modern methods of pain relief","cn":"消除疼痛的新办法"}},{"en":"food, money, medicine, etc. that is given to help people in places where there has been a war or natural disaster","cn":"（给灾区或交战地区人民提供的）救济，救援物品","g":"[uncountable]","sc":"help","ex":{"en":"disaster relief","cn":"救灾物资"}},{"en":"financial help given by the government to people who need it","cn":"救济金","g":"[uncountable]","lab":"especially North American English","sc":"help"},{"en":"a reduction in the amount of tax you have to pay","cn":"税款减免","g":"[uncountable]","sc":"on tax","ex":{"en":"relief on mortgage interest payments","cn":"支付按揭利息的税收减免"}},{"en":"something that is interesting or fun that replaces something boring, difficult or unpleasant for a short period of time","cn":"（暂时替代单调乏味事物的）调剂，轻松场面","g":"[uncountable, singular]","sc":"something different","ex":{"en":"a few moments of light relief in an otherwise dull performance","cn":"沉闷的表演中几处轻松的情节"}},{"en":"a person or group of people that replaces another when they have finished working for the day or when they are sick","cn":"替班者；接替人；换班者","g":"[countable + singular or plural verb]","sc":"workers","ex":{"en":"The next crew relief comes on duty at 9 o'clock.","cn":"下一批换班的员工 9 点钟接班。"}},{"en":"the act of freeing a town, etc. from an enemy army that has surrounded it","cn":"（被困城镇等的）解困，解围","g":"[singular]","sc":"from enemy","ex":{"en":"the relief of Mafeking","cn":"马弗京城的解围。"}},{"en":"a way of decorating wood, stone, etc. by cutting designs into the surface of it so that some parts stick out more than others; a design that is made in this way","cn":"浮雕；浮雕法；浮雕作品","g":"[uncountable, countable]","sc":"in art","ex":{"en":"The column was decorated in high relief (= with designs that stick out a lot) with scenes from Greek mythology.","cn":"柱子上饰有描述希腊神话中的场面的高浮雕。"}},{"en":"the effect of colours, light, etc. that makes an object easier to notice than others around it","cn":"（色彩、光等产生的）醒目效果；醒目；光彩夺目","g":"[uncountable]","sc":"making something easy to notice","ex":{"en":"The snow-capped mountain stood out in sharp relief against the blue sky.","cn":"顶端积雪的高山在蓝天的映衬下格外醒目。"}},{"en":"the quality of a particular situation, problem, etc. that makes it easier to notice than before","cn":"突出的品质；令人注目的特征","g":"[uncountable]","sc":"making something easy to notice","ex":{"en":"Their differences have been thrown into sharp relief by the present crisis.","cn":"目前的危机使得他们的分歧更加引人注目。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"宽慰;安心;欣慰;解脱","en":"If you feel a sense of relief, you feel happy because something unpleasant has not happened or is no longer happening.","ex":{"en":"I breathed a sigh of relief","cn":"我如释重负地松了口气。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(疼痛或苦痛的)解除，免除，减轻，缓解","en":"If something provides relief from pain or distress, it stops the pain or distress.","ex":{"en":"This brought considerable relief from the pain.","cn":"这相当大地缓解了疼痛。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"救济;救援物资","en":"Relief is money, food, or clothing that is provided for people who are very poor, or who have been affected by war or a natural disaster.","ex":{"en":"Relief agencies are stepping up efforts to provide food, shelter and agricultural equipment.","cn":"救济机构正加大力度提供食物、住所和农用器械。"}},{"pos":"N-COUNT 可数名词","cn":"代班人;换班工人","en":"A relief worker is someone who does your work when you go home, or who is employed to do it instead of you when you are sick.","ex":{"en":"No relief drivers were available.","cn":"找不到代班司机。"}},{"pos":"N-COUNT 可数名词","cn":"浮雕","en":"A relief is a sculpture that is carved out of a flat vertical surface."}]},"examples":[{"en":"The calm of the countryside came as a welcome relief from the hustle and bustle of city life.","cn":"离开喧嚣忙碌的城市生活，来到宁静的乡村，是一种令人愉快的调剂。"},{"en":"We all breathed a sigh of relief when he left.","cn":"他走了以后，我们大家都如释重负地松了口气。"}]},"regard":{"media":{"uk":"media/uk/regard__gb_1.mp3","us":"media/us/regard__us_1.mp3"},"oxford":{"phon":"rɪˈɡɑːd","pos":"verb","senses":[{"en":"to think about somebody/something in a particular way","cn":"把…视为；以…看待","g":"[often passive]","ex":{"en":"They regarded people outside their own town with suspicion.","cn":"他们对非本镇人都持有怀疑的态度。"}},{"en":"to look at somebody/something, especially in a particular way","cn":"（尤指以某种方式）注视，凝视","lab":"formal","ex":{"en":"He regarded us suspiciously.","cn":"他以怀疑的眼光看着我们。"}},{"en":"attention to or thought and care for somebody/something","cn":"注意；关注；关心","g":"[uncountable]","lab":"formal","ex":{"en":"to have scant/little/no regard for somebody/something","cn":"几乎不／很少／不顾及某人／某事物"},"pos":"noun"},{"en":"respect for somebody/something","cn":"尊敬；敬重","g":"[uncountable]","lab":"formal","ex":{"en":"He held her in high regard (= had a good opinion of her).","cn":"他对她非常敬重。"},"pos":"noun"},{"en":"used to send good wishes to somebody at the end of an email or letter, or when asking somebody to give your good wishes to another person who is not present","cn":"（用于邮件或信函结尾或转达问候）致意，问候","g":"[plural]","ex":{"en":"With best/kind regards, Yours…","cn":"谨此致意，…敬上"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"认为;把…看作","en":"If you regard someone or something as being a particular thing or as having a particular quality, you believe that they are that thing or have that quality.","ex":{"en":"He was regarded as the most successful Chancellor of modern times","cn":"他被认为是现代最为成功的财政大臣。"}},{"pos":"VERB 动词","cn":"对…怀有（某种感情）;以（某种感情）看待","en":"If you regard something or someone with a feeling such as dislike or respect, you have that feeling about them.","ex":{"en":"He regarded drug dealers with loathing","cn":"他对贩毒分子深恶痛绝。"}},{"pos":"VERB 动词","cn":"（以某种方式）看，注视","en":"If you regard someone in a certain way, you look at them in that way.","ex":{"en":"She regarded him curiously for a moment","cn":"她好奇地看了他一会儿。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"尊重;重视;敬爱","en":"If you have regard for someone or something, you respect them and care about them. If you hold someone in high regard, you have a lot of respect for them.","ex":{"en":"I have a very high regard for him and what he has achieved","cn":"我非常钦佩他的为人和成就。"}},{"pos":"N-PLURAL 复数名词","cn":"问候，致意（尤用于信中表示问好）","en":"Regards are greetings. You use regards in expressions such as best regards and with kind regards as a way of expressing friendly feelings towards someone, especially in a letter.","ex":{"en":"Give my regards to your family","cn":"请代我向你家人问好。"}},{"pos":"PREP-PHRASE 短语介词","cn":"至于;关于","en":"You can use as regards to indicate the subject that is being talked or written about.","ex":{"en":"As regards the war, Haig believed in victory at any price.","cn":"至于这场战争，黑格认为要不惜任何代价取得胜利。"}},{"pos":"PREP-PHRASE 短语介词","cn":"关于;至于","en":"You can use with regard to or in regard to to indicate the subject that is being talked or written about.","ex":{"en":"The department is reviewing its policy with regard to immunisation.","cn":"这个部门正在审度其有关疫苗接种的政策。"}},{"pos":"PHRASE 短语","cn":"在这/那方面；就这/那一点","en":"You can use in this regard or in that regard to refer back to something that you have just said.","ex":{"en":"In this regard nothing has changed","cn":"在这方面没什么变化。"}}]},"examples":[{"en":"Social services should pay proper regard to the needs of inner-city areas.","cn":"社会服务机构应该对市中心贫民区的需要给予应有的关注。"},{"en":"to do sth with scant/little/no regard for sb/sth","cn":"做事不怎么/几乎不/根本不顾及某人/某事物"}]},"repeatedly":{"collins":{"senses":[{"pos":"ADV 副词","cn":"重复地;反复地;再三地","en":"If you do something repeatedly, you do it many times.","ex":{"en":"Both men have repeatedly denied the allegations","cn":"两个人都一再否认指控。"}}]},"media":{"uk":"media/uk/repeatedly__gb_1.mp3","us":"media/us/repeatedly__us_1.mp3"},"examples":[{"en":"The victim had been stabbed repeatedly in the chest.","cn":"受害者胸部多处被刺伤。"},{"en":"Graham was repeatedly warned not to work so hard.","cn":"格雷厄姆一再被提醒工作不要这么拼命。"}],"oxford":{"phon":"rɪˈpiːtɪdli","pos":"adverb","senses":[{"en":"many times","cn":"时常；常常","ex":{"en":"He has repeatedly denied the claims.","cn":"他一再否认这些说法。"}}]}},"receive":{"media":{"uk":"media/uk/receive__gb_1.mp3","us":"media/us/receive__us_1.mp3"},"oxford":{"phon":"rɪˈsiːv","pos":"verb","senses":[{"en":"to get or accept something that is sent or given to you","cn":"拿到；接到；收到","g":"[transitive]","lab":"rather formal","sc":"get/accept"},{"en":"to experience or be given a particular type of treatment or attention","cn":"体验，受到（某种对待或关注）","g":"[transitive]","sc":"treatment","ex":{"en":"Her work has not received the attention it deserves.","cn":"她的工作没有得到应有的关注。"}},{"en":"to form an idea or impression of somebody/something as a result of what you see, experience, etc.","cn":"形成；留下","sc":"impression","ex":{"en":"I did not receive the impression that he was afraid.","cn":"我没有留下他害怕的印象。"}},{"en":"to be injured in a particular way","cn":"受到（伤害）","g":"[transitive]","sc":"injury","ex":{"en":"Several of the passengers received severe injuries.","cn":"几名乘客受了重伤。"}},{"en":"to react to something new, in a particular way","cn":"对…作出反应","g":"[transitive, usually passive]","sc":"react to something","ex":{"en":"The play was well received by the critics.","cn":"这出戏受到剧评家的认可。"}},{"en":"to welcome or entertain a guest, especially formally","cn":"接待；欢迎；招待","g":"[transitive, often passive]","lab":"formal","sc":"guests","ex":{"en":"He was received as an honoured guest at the White House.","cn":"他在白宫受到贵宾的礼遇。"}},{"en":"to officially recognize and accept somebody as a member of a group","cn":"接纳；允许加入","g":"[transitive]","lab":"formal","sc":"as member of something","ex":{"en":"Three young people were received into the Church at Easter.","cn":"复活节时有三位年轻人入教。"}},{"en":"to change broadcast signals into sounds or pictures on a television, radio, etc.","cn":"接收；收看；收听","g":"[transitive]","sc":"TV/radio","ex":{"en":"to receive programmes via satellite","cn":"通过卫星收看节目"}},{"en":"to be able to hear a radio message that is being sent by somebody","cn":"接收到，收听到（无线电消息）","g":"[transitive]","sc":"TV/radio","ex":{"en":"I'm receiving you loud and clear.","cn":"我听得到你的声音，又清晰又响亮。"}},{"en":"to buy or accept goods that you know have been stolen","cn":"购买，接受（贼赃）","g":"[transitive, intransitive]","lab":"especially British English","sc":"stolen goods"},{"en":"to be the player that the server hits the ball to","cn":"接（发球）","g":"[intransitive, transitive]","sc":"in sport","ex":{"en":"She won the toss and chose to receive.","cn":"她猜中了掷币结果，选择接发球。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"收到;接到;得到","en":"When you receive something, you get it after someone gives it to you or sends it to you.","ex":{"en":"They will receive their awards at a ceremony in Stockholm","cn":"他们会在斯德哥尔摩举行的仪式上接受颁奖。"}},{"pos":"VERB 动词","cn":"经受；受到","en":"You can use receive to say that certain kinds of thing happen to someone. For example if they are injured, you can say that they received an injury.","ex":{"en":"He received more of the blame than anyone when the plan failed to work","cn":"计划失败后，他受到了比别人更多的指责。"}},{"pos":"VERB 动词","cn":"接见；迎接；招待","en":"When you receive a visitor or a guest, you greet them.","ex":{"en":"The following evening the duchess was again receiving guests","cn":"第二天晚上公爵夫人又在会客。"}},{"pos":"VERB 动词","cn":"对…作出反应;回应","en":"If you say that something is received in a particular way, you mean that people react to it in that way.","ex":{"en":"The resolution had been received with great disappointment within the PLO","cn":"巴解组织内部对决议表现出极大失望。"}},{"pos":"VERB 动词","cn":"接收（信号）","en":"When a radio or television receives signals that are being transmitted, it picks them up and converts them into sound or pictures.","ex":{"en":"The reception was a little faint but clear enough for him to receive the signal.","cn":"接收到的信号有点弱，但对他来说已够清晰，可以接收到。"}},{"pos":"VERB 动词","cn":"购买，窝藏（赃物）","en":"If someone receives stolen goods, they buy or are given things that have been stolen.","ex":{"en":"He went to prison for receiving stolen scrap iron","cn":"他因为收购偷来的废铁而入狱。"}},{"pos":"PHRASE 短语","cn":"经历（不愉快的事情）；成为受害者","en":"If you are on the receiving end or at the receiving end of something unpleasant, you are the person that it happens to.","ex":{"en":"You saw hate in their eyes and you were on the receiving end of that hate","cn":"你在他们的眼睛里看到仇恨，而且你就是他们仇恨的对象。"}}]},"examples":[{"en":"He received an award for bravery from the police service.","cn":"他以其勇敢行为受到警务部门的嘉奖。"},{"en":"I'm receiving you loud and clear.","cn":"我听得到你的声音，又清晰，又响亮。"}]},"redistribution":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of redistributing something, especially money or land 〔","cn":"尤指钱或土地的〕重新分配"}]},"examples":[{"en":"a major redistribution of land","cn":"大规模的土地重新分配","src":"ld"}],"media":{"uk":"media/uk/redistribution__gb_1.mp3","us":"media/us/redistribution__us_1.mp3"},"oxford":{"phon":"ˌriːdɪstrɪˈbjuːʃn","pos":"noun","senses":[{"en":"the act of sharing something out among people in a different way","cn":"重新分配","ex":{"en":"the redistribution of wealth","cn":"财富的重新分配"}}]}},"repeat":{"media":{"uk":"media/uk/repeat__gb_1.mp3","us":"media/us/repeat__us_1.mp3"},"oxford":{"phon":"rɪˈpiːt","pos":"verb","senses":[{"en":"to say or write something again or more than once","cn":"重复；重说；重写","g":"[transitive]","sc":"say/write again","ex":{"en":"to repeat a question/a claim/an assertion/a warning","cn":"再次提问／声明／断言／警告"}},{"en":"used to emphasize something that you have already said","cn":"（强调说过的话）再说一遍","g":"[intransitive, transitive]","sc":"say/write again","ex":{"en":"The claims are, I repeat, totally unfounded.","cn":"我再说一遍，这些说法是毫无根据的。"}},{"en":"to say something that somebody else has said, especially in order to learn it","cn":"复述，跟读（尤指为学习）","g":"[transitive]","sc":"what somebody else said","ex":{"en":"The teacher's statement is then repeated by the students.","cn":"然后学生重复老师的话。"}},{"en":"to tell somebody something that you have heard or been told by somebody else","cn":"转述；转告","g":"[transitive]","sc":"what somebody else said","ex":{"en":"I don't want you to repeat a word of this to anyone.","cn":"这些话你一个字也不要告诉别人。"}},{"en":"to do or produce something again or more than once","cn":"重做；重新推出；重复","g":"[transitive, intransitive]","sc":"do again","ex":{"en":"to repeat a mistake/process","cn":"重复错误／过程"}},{"en":"to happen more than once in the same way","cn":"重复发生；再次发生","g":"[transitive, intransitive]","sc":"happen again","ex":{"en":"History has a strange way of repeating itself.","cn":"历史会奇怪地重演。"}},{"en":"if food repeats, you can taste it for some time after you have eaten it","cn":"留有余味","g":"[intransitive]","lab":"British English, informal，，","sc":"of food","ex":{"en":"Do you find that onions repeat on you?","cn":"你是不是觉得吃了洋葱嘴里老有一股味儿？"}},{"en":"an event that is very similar to something that happened before","cn":"重演的事物；重复的事件","lab":"business","ex":{"en":"She didn't want a repeat performance of what had happened the night before.","cn":"她不想让前一天晚上的事重演。"},"pos":"noun"},{"en":"a television or radio programme that has been broadcast before","cn":"重播的电视（或广播）节目","ex":{"en":"‘Is it a new series?’ ‘No, a repeat.’","cn":"“这是新播出的连续剧吗？”“不，是重播的。”"},"pos":"noun"},{"en":"a passage that is repeated","cn":"重复段；反复部分","lab":"music","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"重复;重写","en":"If you repeat something, you say or write it again. You can say I repeat to show that you feel strongly about what you are repeating.","ex":{"en":"He repeated that he had been misquoted","cn":"他反复说他的话被错误引用了。"}},{"pos":"VERB 动词","cn":"复述;转述","en":"If you repeat something that someone else has said or written, you say or write the same thing, or tell it to another person.","ex":{"en":"She had an irritating habit of repeating everything I said to her","cn":"她有个惹人讨厌的习惯，我跟她说的每一件事她都告诉别人。"}},{"pos":"VERB 动词","cn":"反复说;说话反反复复","en":"If you repeat yourself, you say something which you have said before, usually by mistake.","ex":{"en":"Then he started rambling and repeating himself.","cn":"他接下来就开始不着边际、说话来回重复了。"}},{"pos":"CONVENTION 惯用语","cn":"再说一次;重申一遍","en":"People sometimes say repeat before saying again a word they have just said, in order to emphasize it or to make sure that people hear it.","ex":{"en":"We are not, I repeat, not actually in the negotiating process","cn":"我们不是，我重申一下，实际上不是在进行谈判。"}},{"pos":"VERB 动词","cn":"重复做(动作)","en":"If you repeat an action, you do it again.","ex":{"en":"The next day I repeated the procedure","cn":"第二天我重复了这个程序。"}},{"pos":"VERB 动词","cn":"重复发生;再次发生","en":"If an event or series of events repeats itself, it happens again.","ex":{"en":"The UN will have to work hard to stop history repeating itself","cn":"联合国必须努力避免历史重演。"}},{"pos":"N-COUNT 可数名词","cn":"(通常指令人不快的事件的)再次发生","en":"If there is a repeat of an event, usually an undesirable event, it happens again.","ex":{"en":"There were fears that there might be a repeat of last year's campaign of strikes.","cn":"有人担心去年的罢工运动可能再次重演。"}},{"pos":"ADJ 形容词","cn":"回头客的;再次光顾的","en":"If a company gets repeat business or repeat customers, people who have bought their goods or services before buy them again.","ex":{"en":"Nearly 60% of our bookings come from repeat business and personal recommendation.","cn":"我们近60%的订单来自于回头客和熟人介绍。"}},{"pos":"N-COUNT 可数名词","cn":"(电视或广播节目的)重播","en":"A repeat is a television or radio programme that has been broadcast before.","ex":{"en":"There's nothing except sport and repeats on TV.","cn":"除了体育节目和重播节目外，电视上没什么新鲜内容。"}},{"pos":"PHRASE 短语","cn":"（通常指令人不快的事件的）再次出现，再次发生","en":"If there is a repeat performance of something, usually something undesirable, it happens again.","ex":{"en":"This year can only see a repeat performance of the decline.","cn":"今年还会出现下降。"}}]},"examples":[{"en":"A repeat of the 1906 earthquake could kill up to 11 000 people.","cn":"如果再次发生 1906 年的地震，可能会有多达 11 000 人死亡。"},{"en":"Lift and lower the right leg 20 times. Repeat with the left leg.","cn":"将右腿提放 20 次，换左腿重复一样的动作。"}]},"relaxes":{"lemma":"relax"},"report":{"media":{"uk":"media/uk/report__gb_1.mp3","us":"media/us/report__us_1.mp3"},"oxford":{"phon":"rɪˈpɔːt","pos":"noun","senses":[{"en":"a written or spoken account of an event, especially one that is published or broadcast","cn":"报道","sc":"of news","ex":{"en":"Are these news reports true?","cn":"这些新闻报道属实吗？"}},{"en":"a spoken or written description of something containing information that somebody needs to have","cn":"汇报；报告；记述","sc":"information","ex":{"en":"a police report","cn":"警方报告"}},{"en":"an official document written by a group of people who have examined a particular situation or problem","cn":"调查报告","sc":"official study","ex":{"en":"to release/issue a report","cn":"发布报告"}},{"en":"a story or piece of information that may or may not be true","cn":"传闻","g":"[plural]","sc":"story","ex":{"en":"There are unconfirmed reports of a shooting in the capital.","cn":"有未经证实的传言说在首都发生了枪击事件。"}},{"en":"a written statement about a student’s work at school, college, etc.","cn":"成绩报告单","lab":"British English","sc":"on student’s work","ex":{"en":"a school report","cn":"学生成绩报告单"}},{"en":"an employee whose work is the responsibility of a particular manager","cn":"（某个主管的）下属","lab":"British English, business，，","sc":"employee","ex":{"en":"a weekly meeting with my direct reports","cn":"同我的直接下属一起开的周会"}},{"en":"the sound of an explosion or of a gun being fired","cn":"爆炸声；射击声","sc":"of gun","ex":{"en":"a loud report","cn":"巨大的爆炸声"}},{"en":"to give people information about something that you have heard, seen, done, etc.","cn":"汇报；报告；通报","g":"[transitive, intransitive]","sc":"give information","ex":{"en":"The crash happened seconds after the pilot reported engine trouble.","cn":"飞行员报告发动机有故障后几秒钟飞机就坠毁了。"},"pos":"verb"},{"en":"to present a written or spoken account of an event in a newspaper, on television, etc.","cn":"报道；公布；发表；宣布","g":"[transitive, intransitive]","sc":"news/story","ex":{"en":"The stabbing was widely reported in the press.","cn":"这起持刀伤人事件被媒体广泛报道。"},"pos":"verb"},{"en":"used to show that something has been stated, and you do not know if it is true or not","cn":"（不知传言是否确凿）据说，传闻","g":"[transitive]","sc":"news/story","ex":{"en":"She is reported to earn over $10 million a year.","cn":"据传她一年挣 1 000 多万美元。"},"pos":"verb"},{"en":"to tell a person in authority about a crime, an accident, an illness, etc. or about something bad that somebody has done","cn":"举报；告发","g":"[transitive]","sc":"crime/accident, etc.","ex":{"en":"Have you reported the incident to the police?","cn":"这起事件你报警了吗？"},"pos":"verb"},{"en":"to tell somebody that you have arrived, for example for work or for a meeting with somebody","cn":"报到","g":"[intransitive]","sc":"arrive","ex":{"en":"You should report for duty at 9.30 a.m.","cn":"你应该在上午 9:30 报到上班。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"报告;汇报;告发","en":"If you report something that has happened, you tell people about it.","ex":{"en":"They had been called in to clear drains after local people reported a foul smell","cn":"当地居民举报闻到恶臭气味后，他们被叫来清理排水沟。"}},{"pos":"VERB 动词","cn":"(就某个事件或主题)报告情况，报道","en":"If you report on an event or subject, you tell people about it, because it is your job or duty to do so.","ex":{"en":"Many journalists enter the country to report on political affairs","cn":"许多记者进入该国对政治事件进行报道。"}},{"pos":"N-COUNT 可数名词","cn":"(报纸或广播的)报道","en":"A report is a news article or broadcast which gives information about something that has just happened.","ex":{"en":"...a report in London's Independent newspaper","cn":"伦敦《独立报》的报道"}},{"pos":"N-COUNT 可数名词","cn":"(调查)报告;情况汇报","en":"A report is an official document which a group of people issue after investigating a situation or event.","ex":{"en":"After an inspection, the inspectors must publish a report.","cn":"在视察之后，视察者必须发表一份报告。"}},{"pos":"N-COUNT 可数名词","cn":"(向某人作出的)报告，汇报","en":"If you give someone a report on something, you tell them what has been happening.","ex":{"en":"She came back to give us a progress report on how the project is going","cn":"她回来给我们作了关于项目进程的报告。"}},{"pos":"N-COUNT 可数名词","cn":"(未经证实的)报道","en":"If you say that there are reports that something has happened, you mean that some people say it has happened but you have no direct evidence of it.","ex":{"en":"There are unconfirmed reports that two people have been shot in the neighbouring town of Lalitpur","cn":"据报道有两人在勒利德布尔城附近被枪杀，但尚未得到证实。"}},{"pos":"VERB 动词","cn":"控告;告发","en":"If someone reports you to a person in authority, they tell that person about something wrong that you have done.","ex":{"en":"His ex-wife reported him to police a few days later","cn":"他的前妻几天后向警方告发了他。"}},{"pos":"VERB 动词","cn":"报到","en":"If you report to a person or place, you go to that person or place and say that you are ready to start work or say that you are present.","ex":{"en":"According to protocol, he first reported to the Director of the hospital","cn":"根据礼节，他先向医院院长报到。"}},{"pos":"VERB 动词","cn":"向…报告；对…负责;隶属","en":"If you say that one employee reports to another, you mean that the first employee is told what to do by the second one and is responsible to them.","ex":{"en":"He reported to a section chief, who reported to a division chief, and so on up the line.","cn":"他由组长领导，组长由部门主管领导，如此逐级向上。"}},{"pos":"N-COUNT 可数名词","cn":"学年（或学期）成绩单","en":"A school report is an official written account of how well or how badly a pupil has done during the term or year that has just finished.","ex":{"en":"And now she was getting bad school reports.","cn":"现在她的学习成绩越来越差。"}},{"pos":"N-COUNT 可数名词","cn":"爆炸声;枪声","en":"A report is a sudden loud noise, for example the sound of a gun being fired or an explosion.","ex":{"en":"Soon afterwards there was a loud report as the fuel tanks exploded.","cn":"不久之后就听到燃料箱爆炸的巨响。"}},{"pos":"","cn":"","en":"相关词组：report back"}]},"examples":[{"en":"The committee will publish their report on the health service in a few weeks.","cn":"委员会将在几周内发表他们对公共医疗服务的调查报告。"},{"en":"The crash happened seconds after the pilot reported engine trouble.","cn":"飞行员报告发动机有故障后几秒钟飞机就坠毁了。"}]},"reconciliation":{"oxford":{"phon":"ˌrekənsɪliˈeɪʃn","pos":"noun","senses":[{"en":"an end to a disagreement or conflict with somebody and the start of a good relationship again","cn":"调解；和解","g":"[singular, uncountable]","ex":{"en":"The pair are bravely attempting a reconciliation.","cn":"这对男女正在尽力尝试和解。"}},{"en":"the process of making it possible for two different ideas, facts, etc. to exist together without being opposed to each other","cn":"协调；和谐一致","g":"[uncountable]","ex":{"en":"the reconciliation between environment and development","cn":"环境保护与发展之间的和谐统一"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"和解;调和;调解","en":"Reconciliation between two people or countries who have quarrelled is the process of their becoming friends again. A reconciliation is an instance of this.","ex":{"en":"...an appeal for reconciliation between Catholics and Protestants","cn":"天主教徒和新教徒之间达成和解的诉求"}},{"pos":"N-SING 单数名词","cn":"（两种貌似对立的信仰、事实或要求的）和谐，调和，一致","en":"The reconciliation of two beliefs, facts, or demands that seem to be opposed is the process of finding a way in which they can both be true or both be successful.","ex":{"en":"...the ideal of democracy based upon a reconciliation of the values of equality and liberty.","cn":"建立在平等和自由两种价值观和谐统一基础上的民主理想"}}]},"media":{"uk":"media/uk/reconciliation__gb_1.mp3","us":"media/us/reconciliation__us_1.mp3"},"examples":[{"en":"Their change of policy brought about a reconciliation with Britain.","cn":"他们的政策改变促成了与英国的和解。"},{"en":"the reconciliation between environment and development","cn":"环境保护与发展之间的协调"}]},"rem":{"oxford":{"phon":"rem","pos":"abbreviation","senses":[{"en":"rapid eye movement (describes a period of sleep during which you dream and your eyes make many small movements)","cn":"快速眼动（夜间做梦时眼睛快速而细微的移动）","ex":{"en":"REM sleep is an essential part of brain function.","cn":"快速眼动睡眠是大脑功能的重要组成部分。"}},{"en":"a US pop group established in 1980. Their albums have included Green (1988), Out of Time (1991) and Automatic for the People (1992).","cn":"成立于1980年的美国流行乐队。他们的专辑包括Green（1988），Out of Time（1991）和Automatic for the People（1992）。","pos":""}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（睡眠）快速眼部运动的","en":"REM sleep is a period of sleep that is very deep, during which your eyes and muscles make many small movements. It is the period during which most of your dreams occur. REM is an abbreviation for (缩略=) 'rapid eye movement'."}]},"media":{"uk":"media/uk/rem__gb_1.mp3","us":"media/us/rem__us_1.mp3"}},"recreation":{"media":{"uk":"media/uk/recreation__gb_2.mp3","us":"media/us/recreation__us_2.mp3"},"oxford":{"phon":"ˌriːkriˈeɪʃn","pos":"noun","senses":[{"en":"the act or process of making something that existed in the past exist or seem to exist again","cn":"复制;再现","ex":{"en":"The writer attempts a recreation of the sights and sounds of his childhood.","cn":"作者尝试再现他儿时的景象和声音。"}},{"en":"the fact of people doing things for pleasure, when they are not working","cn":"娱乐；消遣","g":"[uncountable]","ex":{"en":"the need to improve facilities for leisure and recreation","cn":"改进消遣娱乐设施之必要"}},{"en":"a particular activity that somebody does when they are not working","cn":"娱乐活动；游戏","g":"[countable]","ex":{"en":"His recreations include golf, football and shooting.","cn":"他的娱乐活动包括打高尔夫球、踢足球和射击。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"休闲；娱乐","en":"Recreation consists of things that you do in your spare time to relax.","ex":{"en":"Saturday afternoon is for recreation and outings","cn":"周六午后是休闲和外出游玩的时间。"}},{"pos":"N-COUNT 可数名词","cn":"重现；重建","en":"A recreation of something is the process of making it exist or seem to exist again in a different time or place.","ex":{"en":"They are seeking to build a faithful recreation of the original Elizabethan theatre.","cn":"他们正在试图如实再现伊丽莎白时期剧院的原貌。"}}]},"examples":[{"en":"His recreations include golf, football and shooting.","cn":"他的娱乐活动包括打高尔夫球、踢足球和射击。"},{"en":"the increasing use of land for recreation","cn":"把越来越多的土地用于娱乐"}]},"reference":{"media":{"uk":"media/uk/reference__gb_1.mp3","us":"media/us/reference__us_1.mp3"},"oxford":{"phon":"ˈrefrəns","pos":"noun","senses":[{"en":"a thing you say or write that mentions somebody/something else; the act of mentioning somebody/something","cn":"说到（或写到）的事；提到；谈及；涉及","g":"[countable, uncountable]","sc":"mentioning somebody/something","ex":{"en":"She made no reference to her illness but only to her future plans.","cn":"她没有提到她的病，只说了说她未来的计划。"}},{"en":"the act of looking at something for information","cn":"参考；查询；查阅","g":"[uncountable]","sc":"looking for information","ex":{"en":"A copy of the booklet is given to the employee for reference.","cn":"该手册将发给员工以供参考。"}},{"en":"a number, word or symbol that shows where something is on a map, or where you can find a piece of information","cn":"（为方便查询所用的）标记，标识，编号","g":"[countable]","sc":"number/word/symbol","ex":{"en":"The map reference is Y4.","cn":"地图编号为 Y4。"}},{"en":"the act of asking somebody for help or advice","cn":"（帮助或意见的）征求，征询","g":"[uncountable]","lab":"formal","sc":"asking for advice","ex":{"en":"The emergency nurse can treat minor injuries without reference to a doctor.","cn":"急救护士不必征求医生的意见就可处理轻伤。"}},{"en":"a letter written by somebody who knows you, giving information about your character and abilities, especially to a new employer","cn":"推荐信；介绍信","g":"[countable]","sc":"for new job","ex":{"en":"I'm sure she'll give you a good reference.","cn":"我相信她会给你写一封很好的推荐信。"}},{"en":"a person who agrees to write a reference, for you, for example when you are applying for a job","cn":"推荐人；介绍人","g":"[countable]","sc":"for new job","ex":{"en":"My previous boss will act as a reference for me.","cn":"我的前任上司将做我的推荐人。"}},{"en":"a note in a book that tells you where a particular piece of information comes from","cn":"参考书目","g":"[countable]","sc":"in book","ex":{"en":"There is a list of references at the end of each chapter.","cn":"每一章的后面都有参考书目。"}},{"en":"to refer to something; to provide a book, etc. with references","cn":"查阅；参考；给（书等）附参考资料","ex":{"en":"Each chapter is referenced, citing literature up to 2018.","cn":"每一章都附有参考书目，引用文献近至 2018 年。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"提及；谈到","en":"Reference to someone or something is the act of talking about them or mentioning them. A reference is a particular example of this.","ex":{"en":"He made no reference to any agreement","cn":"他没有提到什么协议。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"咨询;征询;参考;查阅","en":"Reference is the act of consulting someone or something in order to get information or advice.","ex":{"en":"This might be done without reference to Parliament","cn":"这件事情也许可以绕过国会直接进行。"}},{"pos":"ADJ 形容词","cn":"（书）供参考的","en":"Reference books are ones that you look at when you need specific information or facts about a subject.","ex":{"en":"There are several reference books which have been compiled to help you make your choice.","cn":"有几本参考书专门帮你作出选择。"}},{"pos":"N-COUNT 可数名词","cn":"引语；引用的观点；引证","en":"A reference is a word, phrase, or idea which comes from something such as a book, poem, or play and which you use when making a point about something.","ex":{"en":"...a reference from the Quran.","cn":"引自《古兰经》的引文"}},{"pos":"N-COUNT 可数名词","cn":"（方便查询的）编号，标记，索引","en":"A reference is something such as a number or a name that tells you where you can obtain the information you want.","ex":{"en":"...a map reference","cn":"地图索引"}},{"pos":"N-COUNT 可数名词","cn":"介绍信;推荐信","en":"A reference is a letter that is written by someone who knows you and which describes your character and abilities. When you apply for a job, an employer might ask for references .","ex":{"en":"The firm offered to give her a reference.","cn":"公司主动给她开具介绍信。"}},{"pos":"N-COUNT 可数名词","cn":"（求职等时的）推荐人，介绍人，证明人","en":"A reference is a person who gives you a reference, for example when you are applying for a job."},{"pos":"VERB 动词","cn":"引用，参照（某书或某作者）","en":"If you reference a particular book or writer, you make a precise reference to them in what you are saying or writing.","ex":{"en":"It specifically referenced Hermann Noordung's classic 1928 book on this subject.","cn":"在这一问题上它特别参照了赫尔曼·诺丁1928年的经典之作。"}},{"pos":"PHRASE 短语","cn":"（保留信息）以备将来之用","en":"If you keep information for future reference, you keep it because it might be useful in the future.","ex":{"en":"Read these notes carefully and keep them for future reference.","cn":"仔细阅读这些注释并将其保留下来以备将来之用。"}},{"pos":"PREP-PHRASE 短语介词","cn":"关于…","en":"You use with reference to or in reference to in order to indicate what something relates to.","ex":{"en":"I am writing with reference to your article on salaries for scientists","cn":"我写此信是为了回应你那篇探讨科学家薪水的文章。"}}]},"examples":[{"en":"Each chapter is referenced, citing literature up to 2008.","cn":"每一章都附有参考书目，引用文献近至 2008 年。"},{"en":"She made no reference to her illness but only to her future plans.","cn":"她没有提到她的病，只说了说她未来的计划。"}]},"restrict":{"media":{"uk":"media/uk/restrict__gb_1.mp3","us":"media/us/restrict__us_1.mp3"},"oxford":{"phon":"rɪˈstrɪkt","pos":"verb","senses":[{"en":"to limit the size, amount or range of something","cn":"限制，限定（数量、范围等）","ex":{"en":"Speed is restricted to 30 mph in towns.","cn":"在城里车速不得超过每小时 30 英里。"}},{"en":"to stop somebody/something from moving or acting freely","cn":"束缚；妨碍；阻碍","ex":{"en":"The long skirt restricted her movements.","cn":"长裙妨碍了她的行动。"}},{"en":"to control something with rules or laws","cn":"（以法规）限制","ex":{"en":"Access to the club is restricted to members only.","cn":"俱乐部仅对会员开放。"}},{"en":"to allow yourself or somebody to have only a limited amount of something or to do only a particular kind of activity","cn":"约束；管束","ex":{"en":"I restrict myself to one cup of coffee a day.","cn":"我控制自己每天只喝一杯咖啡。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"限制，限定（大小、规模等）","en":"If you restrict something, you put a limit on it in order to reduce it or prevent it becoming too great.","ex":{"en":"There is talk of raising the admission requirements to restrict the number of students on campus","cn":"有传闻称将通过提高录取条件来限制在校学生的数目。"}},{"pos":"VERB 动词","cn":"约束，限制(活动或行为)","en":"To restrict the movement or actions of someone or something means to prevent them from moving or acting freely.","ex":{"en":"Villagers say the fence would restrict public access to the hills","cn":"村民们说架篱笆能限制公众进山。"}},{"pos":"VERB 动词","cn":"限制，限定（人或其行为）","en":"If you restrict someone or their activities to one thing, they can only do, have, or deal with that thing. If you restrict them to one place, they cannot go anywhere else.","ex":{"en":"He was, however, allowed to stay on at the temple as long as he restricted himself to his studies","cn":"然而，只要他专心学习，他就可以继续留在寺庙里。"}},{"pos":"VERB 动词","cn":"将…限制在（某地）；将…限定为（某群体）","en":"If you restrict something to a particular group, only that group can do it or have it. If you restrict something to a particular place, it is allowed only in that place.","ex":{"en":"The hospital may restrict bookings to people living locally","cn":"这家医院可能会限定只有当地居民才能预约。"}}]},"examples":[{"en":"We restrict the number of students per class to 10.","cn":"我们将每个班的学生人数限定为 10 人。"},{"en":"Speed is restricted to 30 mph in towns.","cn":"在城里车速不得超过每小时 30 英里。"}]},"recognition":{"media":{"uk":"media/uk/recognition__gb_1.mp3","us":"media/us/recognition__us_1.mp3"},"oxford":{"phon":"ˌrekəɡˈnɪʃn","pos":"noun","senses":[{"en":"the act of remembering who somebody is when you see them, or of identifying what something is","cn":"认出；认识；识别","g":"[uncountable]","ex":{"en":"He glanced briefly towards her but there was no sign of recognition.","cn":"他瞥了她一眼，但似乎没认出她来。"}},{"en":"the act of accepting that something exists, is true or is official","cn":"承认；认可","g":"[singular, uncountable]","ex":{"en":"a growing recognition that older people have potential too","cn":"越来越多的人认识到老年人也是有潜力的"}},{"en":"public praise and reward for somebody’s work or actions","cn":"赞誉；赏识；奖赏","g":"[uncountable]","ex":{"en":"She gained only minimal recognition for her work.","cn":"她的工作仅仅得到极少的赞誉。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"认识;识别;认出","en":"Recognition is the act of recognizing someone or identifying something when you see it.","ex":{"en":"George said, 'Ida, how are you?' She frowned for a moment and then recognition dawned. 'George Black. Well, I never.'","cn":"乔治说：“艾达，你好吗？”她皱了一会儿眉头，然后才认出他。“乔治·布莱克，噢，我一直都不好。”"}},{"pos":"N-UNCOUNT 不可数名词","cn":"承认;接受;理解","en":"Recognition of something is an understanding and acceptance of it.","ex":{"en":"The CBI welcomed the Chancellor's recognition of the recession and hoped for a reduction in interest rates.","cn":"英国工业联合会对财政大臣承认经济出现衰退表示欢迎，并希望能出台降低利率的政策。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（政府对他国的）外交认可，正式承认","en":"When a government gives diplomatic recognition to another country, they officially accept that its status is valid.","ex":{"en":"South Africa gave diplomatic recognition to Rwanda's new government on September 15","cn":"南非于9月15日正式承认了卢旺达的新政府。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"赞赏;好评;认可","en":"When a person receives recognition for the things that they have done, people acknowledge the value or skill of their work.","ex":{"en":"At last, her father's work has received popular recognition","cn":"最后，她父亲的工作得到了大众的认可。"}},{"pos":"PHRASE 短语","cn":"面目全非;认不出来;无法辨认","en":"If you say that someone or something has changed beyond recognition or out of all recognition, you mean that person or thing has changed so much that you can no longer recognize them.","ex":{"en":"The bodies were mutilated beyond recognition","cn":"尸体都残缺不全，无法辨认了。"}},{"pos":"PREP-PHRASE 短语介词","cn":"获官方认可;正式承认","en":"If something is done in recognition of someone's achievements, it is done as a way of showing official appreciation of them.","ex":{"en":"Brazil normalised its diplomatic relations with South Africa in recognition of the steps taken to end apartheid","cn":"巴西恢复了与南非的外交关系，以示对其采取措施结束种族隔离的正式认可。"}}]},"examples":[{"en":"The town has changed beyond recognition since I was last here.","cn":"自从我上次离开这里以来，这座小镇已经变得让人认不出来了。"},{"en":"to seek international/official/formal recognition as a sovereign state","cn":"寻求国际上的/官方/正式的承认，承认它是一个主权国家"}]},"remarkable":{"media":{"uk":"media/uk/remarkable__gb_1.mp3","us":"media/us/remarkable__us_1.mp3"},"oxford":{"phon":"rɪˈmɑːkəbl","pos":"adjective","senses":[{"en":"unusual or surprising in a way that causes people to take notice","cn":"非凡的；奇异的；显著的；引人注目的","ex":{"en":"a remarkable achievement/career/talent","cn":"非凡的成就／事业／才能"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不同寻常的;非凡的;引人注目的","en":"Someone or something that is remarkable is unusual or special in a way that makes people notice them and be surprised or impressed.","ex":{"en":"He was a remarkable man","cn":"他是个不同寻常的人。"}}]},"examples":[{"en":"The area is remarkable for its scenery.","cn":"这一地区以其优美的景色而引人瞩目。"},{"en":"The car is in remarkably good condition for its age.","cn":"就车龄而论，这辆车的状况好极了。"}]},"ren":{"oxford":{"phon":"ˌɑːr iː ˈen","pos":"noun","senses":[{"en":"registered enrolled nurse","cn":"（已登记）注册护士"}]},"media":{"uk":"media/uk/ren__gb_1.mp3","us":"media/us/ren__us_1.mp3"}},"reach":{"media":{"uk":"media/uk/reach__gb_1.mp3","us":"media/us/reach__us_1.mp3"},"oxford":{"phon":"riːtʃ","pos":"verb","senses":[{"en":"to arrive at the place that you have been travelling to","cn":"到达；抵达","g":"[transitive]","sc":"arrive","ex":{"en":"They didn't reach the border until after dark.","cn":"他们天黑以后才到达边境。"}},{"en":"to come to somebody’s attention","cn":"引起…的注意","g":"[transitive]","sc":"arrive","ex":{"en":"The rumours eventually reached the President.","cn":"传闻最终引起了总统的注意。"}},{"en":"to increase to a particular level, speed, etc. over a period of time","cn":"增加到，提升到（某一水平、速度等）","g":"[transitive]","sc":"level/speed/stage","ex":{"en":"The conflict has now reached a new level of intensity.","cn":"冲突现在已经达到了新的激烈程度。"}},{"en":"to arrive at a particular point or stage of something after a period of time","cn":"达到（某点）；进入（某阶段）","g":"[transitive]","sc":"level/speed/stage","ex":{"en":"We have a good chance of reaching the final.","cn":"我们有很大可能进入决赛。"}},{"en":"to achieve a particular aim","cn":"实现；达到","g":"[transitive]","sc":"achieve aim","ex":{"en":"Politicians again failed to reach an agreement.","cn":"政治家们又一次没有达成一致。"}},{"en":"to stretch your hand towards something in order to touch it, pick it up, etc.","cn":"伸；伸手","g":"[intransitive, transitive]","sc":"with hand/arm","ex":{"en":"She reached inside her bag for a pen.","cn":"她把手伸到包里掏钢笔。"}},{"en":"to be able to stretch your hand far enough in order to touch something, pick something up, etc.","cn":"能伸到；够得着","g":"[intransitive, transitive]","sc":"with hand/arm","ex":{"en":"‘Grab the end of the rope.’ ‘I can't reach that far!’","cn":"“抓住绳子头。”“我够不着！”"}},{"en":"to stretch your hand out or up in order to get something for somebody","cn":"为某人伸手取（物）","g":"[transitive]","sc":"with hand/arm","ex":{"en":"Can you reach that box down for me?","cn":"你帮我把那个盒子拿下来好吗？"}},{"en":"to be big enough, long enough, etc. to arrive at a particular point","cn":"（大或长等）足够达到","g":"[intransitive, transitive]","sc":"be long enough","ex":{"en":"The carpet only reached halfway across the room.","cn":"地毯只够覆盖半间屋。"}},{"en":"to communicate with somebody, especially by phone","cn":"（尤指用电话）联系，与…取得联系","g":"[transitive]","sc":"contact somebody","ex":{"en":"Do you know where I can reach him?","cn":"你知道我在哪儿能跟他联系上吗？"}},{"en":"to be seen or heard by somebody","cn":"被…看到（或听到）","g":"[transitive]","sc":"be seen/heard by somebody","ex":{"en":"Through the internet we are able to reach a wider audience.","cn":"通过互联网，我们能够拥有更广泛的受众。"}},{"en":"the distance over which you can stretch your arms to touch something; the distance over which a particular object can be used to touch something else","cn":"手臂展开的长度；臂展","g":"[uncountable, singular]","sc":"of arms","ex":{"en":"The shot was well beyond the reach of the goalkeeper.","cn":"这次射门使守门员鞭长莫及。"},"pos":"noun"},{"en":"the limit to which somebody/something has the power or influence to do something","cn":"波及范围；影响范围","g":"[uncountable, singular]","sc":"of power/influence","ex":{"en":"The brand now has global reach.","cn":"这个品牌已经辐射全球。"},"pos":"noun"},{"en":"a straight section of water between two bends on a river","cn":"河段；直水道","g":"[countable, usually plural]","sc":"of river","ex":{"en":"the upper/lower reaches of the Nile (= the part that is furthest from/nearest to the sea)","cn":"尼罗河上游／下游"},"pos":"noun"},{"en":"the parts of an area or a place that are a long way from the centre","cn":"边缘地带；边远地区","g":"[plural]","lab":"figurative","sc":"place far from centre","ex":{"en":"the outer reaches of space","cn":"外层太空"},"pos":"noun"},{"en":"the higher, etc. sections of an organization, a system, etc.","cn":"（组织、体制等的）领域，部门","g":"[plural]","sc":"sections of organization","ex":{"en":"There are still few women in the upper reaches of the civil service.","cn":"在高级公务员中，女性仍然寥寥无几。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"到达；抵达","en":"When someone or something reaches a place, they arrive there.","ex":{"en":"He did not stop until he reached the door","cn":"他走到门边才停下。"}},{"pos":"VERB 动词","cn":"达到，到达（一定阶段、程度或数量）","en":"If someone or something has reached a certain stage, level, or amount, they are at that stage, level, or amount.","ex":{"en":"The process of political change in South Africa has reached the stage where it is irreversible","cn":"南非的政治变革已达到不可逆转的地步。"}},{"pos":"VERB 动词","cn":"（伸手）触及，去拿，去碰","en":"If you reach somewhere, you move your arm and hand to take or touch something.","ex":{"en":"Judy reached into her handbag and handed me a small printed leaflet","cn":"朱蒂把手伸进提包，拿出一张小的印刷传单给我。"}},{"pos":"VERB 动词","cn":"（伸手或腿）碰到，触及","en":"If you can reach something, you are able to touch it by stretching out your arm or leg.","ex":{"en":"Can you reach your toes with your fingertips?","cn":"你能用手指尖碰到你的脚趾吗？"}},{"pos":"VERB 动词","cn":"（通常指通过电话）联系，联络","en":"If you try to reach someone, you try to contact them, usually by telephone.","ex":{"en":"Has the doctor told you how to reach him or her in emergencies?","cn":"医生有没有告诉你发生紧急情况时怎样与其取得联系？"}},{"pos":"VERB 动词","cn":"延伸至;伸展到;传至","en":"If something reaches a place, point, or level, it extends as far as that place, point, or level.","ex":{"en":"...a nightshirt which reached to his knees","cn":"长及他膝盖的睡衣"}},{"pos":"VERB 动词","cn":"取得（一致意见）；达成（协议）；作出（决定）","en":"When people reach an agreement or a decision, they succeed in achieving it.","ex":{"en":"A meeting of agriculture ministers in Luxembourg today has so far failed to reach agreement over farm subsidies","cn":"今天参加卢森堡会议的各国农业部长目前尚未就农业补贴问题达成一致意见。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"可达到的距离；所能及的限度","en":"Someone's or something's reach is the distance or limit to which they can stretch, extend, or travel.","ex":{"en":"Isabelle placed a wine cup on the table within his reach.","cn":"伊莎贝尔把酒杯放在桌上他伸手可及的地方。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（伸手）可及之距离;(可接受的)范围","en":"If a place or thing is within reach, it is possible to have it or get to it. If it is out of reach, it is not possible to have it or get to it.","ex":{"en":"It is located within reach of many important Norman towns, including Bayeux","cn":"它邻近许多重要的诺曼城镇，包括贝叶。"}}]},"examples":[{"en":"Through television and radio we are able to reach a wider audience.","cn":"通过电视和收音机，我们能够为更加广泛的观众和听众所熟悉。"},{"en":"The company has now overtaken IBM in terms of size and reach.","cn":"在规模和影响范围上，这家公司已经超越了国际商用机器。"}]},"react":{"media":{"uk":"media/uk/react__gb_1.mp3","us":"media/us/react__us_1.mp3"},"oxford":{"phon":"riˈækt","pos":"verb","senses":[{"en":"to change or behave in a particular way as a result of or in response to something","cn":"起反应；（对…）作出反应；回应","g":"[intransitive]","ex":{"en":"I nudged her but she didn't react.","cn":"我用胳膊肘捅了她一下，可她没有反应。"}},{"en":"to become ill after eating, breathing, etc. a particular substance","cn":"（对食物等）有不良反应，过敏","g":"[intransitive]","ex":{"en":"Some patients may react adversely.","cn":"一些患者可能会产生不良反应。"}},{"en":"to experience a chemical change when coming into contact with another substance","cn":"起化学反应；发生化学变化","g":"[intransitive]","lab":"chemistry","ex":{"en":"Silicon reacts chemically like carbon.","cn":"硅与碳的化学反应相似。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（作出）反应；回应","en":"When you react to something that has happened to you, you behave in a particular way because of it.","ex":{"en":"They reacted violently to the news","cn":"他们对这条新闻反应强烈。"}},{"pos":"VERB 动词","cn":"反抗;不服;反对","en":"If you react against someone's way of behaving, you deliberately behave in a different way because you do not like the way they behave.","ex":{"en":"She reacted against the mindlessness and luxury of their lives","cn":"她对他们生活的盲目和奢侈很反对。"}},{"pos":"VERB 动词","cn":"产生不良反应;过敏","en":"If you react to a substance such as a drug, or to something you have touched, you are affected unpleasantly or made ill by it.","ex":{"en":"Someone allergic to milk is likely to react to cheese","cn":"对牛奶过敏的人可能对奶酪也有不良反应。"}},{"pos":"V-RECIP 相互动词","cn":"起（化学）变化;发生（化学）反应","en":"When one chemical substance reacts with another, or when two chemical substances react, they combine chemically to form another substance.","ex":{"en":"Calcium reacts with water","cn":"钙和水会发生化学反应"}}]},"examples":[{"en":"I nudged her but she didn't react.","cn":"我用胳膊肘捅了她一下，可她没有反应。"},{"en":"People can react badly to certain food additives.","cn":"人们对某些食品添加剂可能会严重过敏。"}]},"reinforce":{"media":{"uk":"media/uk/reinforce__gb_1.mp3","us":"media/us/reinforce__us_1.mp3"},"oxford":{"phon":"ˌriːɪnˈfɔːs","pos":"verb","senses":[{"en":"to make a feeling, an idea, etc. stronger","cn":"加强；充实；使更强烈","ex":{"en":"The experience reinforced my sense of loss.","cn":"这次经历让我感到更加失落。"}},{"en":"to make a structure or material stronger, especially by adding another material to it","cn":"加固；使更结实","ex":{"en":"All buildings are now reinforced to withstand earthquakes.","cn":"所有建筑现都已加固，以抗地震。"}},{"en":"to send more people or equipment in order to make an army, etc. stronger","cn":"给…加强力量（或装备）；使更强大","ex":{"en":"The UN has undertaken to reinforce its military presence along the borders.","cn":"联合国已经着手增强边境驻军。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"加强;增强","en":"If something reinforces a feeling, situation, or process, it makes it stronger or more intense.","ex":{"en":"A stronger European Parliament would, they fear, only reinforce the power of the larger countries","cn":"他们担心一个更加强大的欧洲议会只会增强大国的力量。"}},{"pos":"VERB 动词","cn":"给予…更多支持;为…提供更多证据","en":"If something reinforces an idea or point of view, it provides more evidence or support for it.","ex":{"en":"...films that reinforce the idea that we live in a threatening and risky world.","cn":"让我们更加意识到自己生活的世界充满威胁和危险的电影"}},{"pos":"VERB 动词","cn":"加固;增强","en":"To reinforce an object means to make it stronger or harder.","ex":{"en":"Eventually, they had to reinforce the walls with exterior beams.","cn":"最终，他们不得不通过增加外梁来对墙体进行加固。"}},{"pos":"VERB 动词","cn":"为(军队或警察队伍)增加力量（或装备）；向（某地）增兵;增援","en":"To reinforce an army or a police force means to make it stronger by increasing its size or providing it with more weapons. To reinforce a position or place means to make it stronger by sending more soldiers or weapons.","ex":{"en":"Both sides have been reinforcing their positions after yesterday's fierce fighting","cn":"双方经过昨天的激战后都在向各自的阵地增派兵力。"}}]},"examples":[{"en":"Such jokes tend to reinforce racial stereotypes.","cn":"这样的笑话往往进一步加深对种族的模式化观念。"},{"en":"Success in the talks will reinforce his reputation as an international statesman.","cn":"谈判成功将会增强他作为国际政治家的声望。"}]},"reminder":{"media":{"uk":"media/uk/reminder__gb_1.mp3","us":"media/us/reminder__us_1.mp3"},"oxford":{"phon":"rɪˈmaɪndə(r)","pos":"noun","senses":[{"en":"something that makes you think about or remember somebody/something, that you have forgotten or would like to forget","cn":"引起回忆的事物；提醒人的事物","ex":{"en":"The sheer size of the cathedral is a constant reminder of the power of religion.","cn":"大教堂的宏大规模使人时时感受到宗教的威严。"}},{"en":"a letter or note informing somebody that they have not done something","cn":"（告知该做某事的）通知单，提示信","ex":{"en":"If an invoice is not paid within seven days, we automatically send out a reminder.","cn":"如果账单在七天内未支付，我们将自动发出提醒信息。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"提示;使人回忆起某事的事物","en":"Something that serves as a reminder of another thing makes you think about the other thing.","ex":{"en":"The British are about to be given a sharp reminder of what fighting abroad really means","cn":"有些事将很快让英国人清楚意识到海外作战究竟意味着什么。"}},{"pos":"N-COUNT 可数名词","cn":"缴费单;催缴单;催缴通知","en":"A reminder is a letter or note that is sent to tell you that you have not done something such as pay a bill or return library books.","ex":{"en":"...the final reminder for the gas bill.","cn":"最后一次煤气催缴通知单"}}]},"examples":[{"en":"The incident served as a timely reminder of just how dangerous mountaineering can be.","cn":"这次事故及时地提醒了人们登山运动有可能会很危险。"},{"en":"The sheer size of the cathedral is a constant reminder of the power of religion.","cn":"大教堂的宏大规模使人时刻领略到宗教的威严。"}]},"removed":{"lemma":"remove"},"restraint":{"media":{"uk":"media/uk/restraint__gb_1.mp3","us":"media/us/restraint__us_1.mp3"},"oxford":{"phon":"rɪˈstreɪnt","pos":"noun","senses":[{"en":"a rule, a fact, an idea, etc. that limits or controls what people can do","cn":"约束力；管制措施；制约因素","g":"[countable, usually plural]","ex":{"en":"The government has imposed export restraints on some products.","cn":"政府对一些产品实行了出口控制。"}},{"en":"the act of controlling or limiting something because it is necessary or sensible to do so","cn":"控制；限制","g":"[uncountable]","ex":{"en":"The unions are unlikely to accept any sort of wage restraint.","cn":"工会不大可能接受任何形式的工资限制。"}},{"en":"the quality of behaving calmly and with control","cn":"克制；抑制；约束","g":"[uncountable]","ex":{"en":"The police appealed to the crowd for restraint.","cn":"警方呼吁群众保持克制。"}},{"en":"the use of physical force to control somebody who is behaving in a violent way","cn":"（武力）阻止，制止，制伏","g":"[uncountable]","lab":"formal","ex":{"en":"the physical restraint of prisoners","cn":"对囚犯的人身限制"}},{"en":"a type of seat belt or safety device","cn":"座椅安全带；安全装置","g":"[countable]","lab":"formal","ex":{"en":"Children must use an approved child restraint or adult seat belt.","cn":"儿童必须使用经过认可的儿童安全带或成人座椅安全带。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"限制;制约因素;管制措施","en":"Restraints are rules or conditions that limit or restrict someone or something.","ex":{"en":"The Prime Minister is calling for new restraints on trade unions","cn":"首相正在呼吁对工会施加新的限制措施。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"克制;抑制;遏制","en":"Restraint is calm, controlled, and unemotional behaviour.","ex":{"en":"They behaved with more restraint than I'd expected","cn":"他们表现得比我预料的更为克制。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"限制;控制","en":"Restraint of something is the act of preventing it from increasing too much or from being done freely.","ex":{"en":"For a year and a half, wage restraint on a voluntary basis worked","cn":"在一年半的时间里，自愿实行的限薪措施奏效了。"}}]},"examples":[{"en":"Children must use an approved child restraint or adult seat belt.","cn":"儿童必须使用经过认可的儿童安全带或成人座椅安全带。"},{"en":"He exercised considerable restraint in ignoring the insults.","cn":"他克制住了自己，没去理会种种侮辱。"}]},"remember":{"media":{"uk":"media/uk/remember__gb_1.mp3","us":"media/us/remember__us_1.mp3"},"oxford":{"phon":"rɪˈmembə(r)","pos":"verb","senses":[{"en":"to have or keep an image in your memory of an event, a person, a place, etc. from the past","cn":"回想起；记得；记起","g":"[transitive, intransitive]","lab":"formal","sc":"somebody/something from the past","ex":{"en":"This is Carla. Do you remember her?","cn":"这位是卡拉。你记得她吗？"}},{"en":"to bring back to your mind a fact, piece of information, etc. that you knew","cn":"想起；记起","g":"[transitive, intransitive]","sc":"fact/information","ex":{"en":"You were going to help me with this. Remember?","cn":"你说要帮着我做的。记得吗？"}},{"en":"to keep an important fact in your mind","cn":"记住；把…牢记在心","g":"[transitive]","sc":"fact/information","ex":{"en":"Remember (that) you may feel sleepy after taking the pills.","cn":"记住，吃了这些药片之后，你可能会犯困。"}},{"en":"to not forget to do something; to actually do what you have to do","cn":"记着，不忘（去做）；动手做（必须做的事）","g":"[transitive]","sc":"something you have to do","ex":{"en":"Remember to call me when you arrive!","cn":"你到了之后别忘了给我打电话！"}},{"en":"to think about somebody with respect, especially when saying a prayer","cn":"纪念；缅怀；思念","g":"[transitive]","sc":"in prayers","ex":{"en":"a church service to remember the war dead","cn":"纪念战争死难者的教堂礼拜仪式"}},{"en":"to give money, a present, etc. to somebody/something","cn":"给…送钱（或礼品等）","g":"[transitive]","sc":"give present","ex":{"en":"My aunt always remembers my birthday (= by sending a card or present).","cn":"我姨妈在我的生日总要送我礼物。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"记得;记起;想起","en":"If you remember people or events from the past, you still have an idea of them in your mind and you are able to think about them.","ex":{"en":"You wouldn't remember me. I was in another group","cn":"你不会记得我。我那时在另外一组。"}},{"pos":"VERB 动词","cn":"(经过一段时间后)忆起，回忆起","en":"If you remember that something is the case, you become aware of it again after a time when you did not think about it.","ex":{"en":"She remembered that she was going to the social club that evening","cn":"她记起来那晚她正要去社交俱乐部。"}},{"pos":"VERB 动词","cn":"（用于否定）记起，想起","en":"If you cannot remember something, you are not able to bring it back into your mind when you make an effort to do so.","ex":{"en":"If you can't remember your number, write it in code in a diary","cn":"如果你记不住你的号码，用代码把它记在记事本上。"}},{"pos":"VERB 动词","cn":"记住，记得(做某事)","en":"If you remember to do something, you do it when you intend to.","ex":{"en":"I did remember to take the present","cn":"我的确记得拿了礼物。"}},{"pos":"VERB 动词","cn":"记住，牢记(重要的事)","en":"You tell someone to remember that something is the case when you want to emphasize its importance. It may be something that they already know about or a new piece of information.","ex":{"en":"It is important to remember that each person reacts differently","cn":"重要的是要记住每个人的反应不同。"}},{"pos":"VERB 动词","cn":"(因为某事)记住（某人）","en":"If you say that someone will be remembered for something that they have done, you mean that people will think of this whenever they think about the person.","ex":{"en":"At his grammar school he is remembered for being bad at games","cn":"在文法学校他因不善于玩游戏为大家所熟知。"}},{"pos":"VERB 动词","cn":"代(某人)问候(某人)","en":"If you ask someone to remember you to a person who you have not seen for a long time, you are asking them to pass your greetings on to that person.","ex":{"en":"'Remember me to Lyle, won't you?' I said","cn":"“代我问候莱尔，好吗？”我说。"}},{"pos":"VERB 动词","cn":"值得记忆；令人难忘","en":"If you make a celebration an occasion to remember, you make it very enjoyable for all the people involved.","ex":{"en":"We'll give everyone a night to remember","cn":"我们将带给大家一个难忘的夜晚。"}}]},"examples":[{"en":"He still remembered her as the lively teenager he'd known years before.","cn":"他记忆中的她依然是他多年以前认识的那个活泼的少女。"},{"en":"He is best remembered as the man who brought jazz to England.","cn":"他因为将爵士音乐传到英国而为人们所熟知。"}]},"reluctance":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone is unwilling to do something, or when they do something slowly to show that they are not very willing","cn":"勉强﹔不情愿"}]},"examples":[{"en":"Wells finally agreed, but with reluctance.","cn":"韦尔斯最终同意了﹐但很勉强。","src":"ld"},{"en":"a reluctance to share information","cn":"不情愿分享信息","src":"ld"}],"media":{"uk":"media/uk/reluctance__gb_1.mp3","us":"media/us/reluctance__us_1.mp3"},"oxford":{"phon":"rɪˈlʌktəns","pos":"noun","senses":[{"en":"the feeling of being unwilling to do something and hesitating before you do it, because you do not want to do it or because you are not sure that it is the right thing to do","cn":"不情愿的；勉强的","ex":{"en":"There is still some reluctance on the part of employers to become involved in this project.","cn":"雇主们仍然不太愿意参与这个项目。"}}]}},"restorative":{"media":{"uk":"media/uk/restorative__gb_1.mp3","us":"media/us/restorative__us_1.mp3"},"oxford":{"phon":"rɪˈstɒrətɪv","pos":"adjective","senses":[{"en":"making you feel strong and healthy again","cn":"恢复健康的；促使康复的","lab":"formal","ex":{"en":"the restorative power of fresh air","cn":"新鲜空气的康复功效"}},{"en":"connected with treatment that repairs the body or a part of it","cn":"整容的；整形的","lab":"medical","ex":{"en":"restorative dentistry/surgery","cn":"整形牙科／外科"}},{"en":"a thing that makes you feel better, stronger, etc.","cn":"有助于恢复健康的事物；滋补品","ex":{"en":"Sleep is the best restorative there is.","cn":"睡眠是最好的恢复方式。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恢复健康（或体力、精神）的","en":"Something that is restorative makes you feel healthier, stronger, or more cheerful after you have been feeling tired, weak, or miserable.","ex":{"en":"She opened the door to her bedroom, thinking how restorative a hot bath would feel tonight.","cn":"她打开了卧室的门，想着今晚洗个热水澡该多么令人惬意。"}},{"pos":"N-COUNT 可数名词","cn":"使人恢复健康（或体力、精神）的事物","en":"If you describe something as a restorative, you mean that it makes you feel healthier, stronger, or more cheerful after you have been feeling tired, weak, or miserable.","ex":{"en":"Seven days off could be a wonderful restorative.","cn":"休假7天肯定能让人精神焕发。"}}]},"examples":[{"en":"the restorative power of fresh air","cn":"新鲜空气的康复功效"},{"en":"restorative dentistry/surgery","cn":"整形牙科/外科"}]},"repairs":{"lemma":"repair","media":{"uk":"media/uk/repair__gb_1.mp3","us":"media/us/repair__us_1.mp3"}},"refusal":{"media":{"uk":"media/uk/refusal__gb_1.mp3","us":"media/us/refusal__us_1.mp3"},"oxford":{"phon":"rɪˈfjuːzl","pos":"noun","senses":[{"en":"an act of saying or showing that you will not do, give or accept something","cn":"拒绝；回绝","ex":{"en":"the refusal of a request/an invitation/an offer","cn":"拒绝请求／邀请／建议"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"拒绝；回绝；不接受","en":"Someone's refusal to do something is the fact of them showing or saying that they will not do it, allow it, or accept it.","ex":{"en":"...her refusal to accept change","cn":"她对变革的拒绝"}},{"pos":"PHRASE 短语","cn":"优先取舍权；先买权","en":"If someone has first refusal on something that is being sold or offered, they have the right to decide whether or not to buy it or take it before it is offered to anyone else.","ex":{"en":"If you have a good rapport with a dealer, they will always let you have first refusal on anything interesting","cn":"如果你和经销商关系好，好东西他们会任你先挑。"}}]},"examples":[{"en":"His refusal to discuss the matter is very annoying.","cn":"他拒绝商量这件事，令人很恼火。"},{"en":"the refusal of a request/an invitation/an offer","cn":"拒绝请求/邀请/建议"}]},"rested":{"media":{"uk":"media/uk/rested__gb_1.mp3","us":"media/us/rested__us_1.mp3"},"oxford":{"phon":"ˈrestɪd","pos":"adjective","senses":[{"en":"feeling healthy and full of energy because you have had a rest","cn":"休息后精力恢复（或精神振作）的","ex":{"en":"I awoke feeling rested and refreshed.","cn":"我睡醒后感觉精力充沛，神清气爽。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精力充沛的;精神焕发的","en":"If you feel rested, you feel more energetic because you have just had a rest.","ex":{"en":"He looked tanned and well rested after his vacation.","cn":"度假之后，他皮肤晒得黝黑，精神焕发。"}}]},"examples":[{"en":"I awoke feeling rested and refreshed.","cn":"我睡醒后感觉精力充沛，神清气爽。"},{"en":"We came back from holiday feeling rested and relaxed.","cn":"我们度假归来﹐感到轻松而精力充沛。"}],"base":"rest"},"reform":{"media":{"uk":"media/uk/reform__gb_1.mp3","us":"media/us/reform__us_1.mp3"},"oxford":{"phon":"rɪˈfɔːm","pos":"noun","senses":[{"en":"change that is made to a social system, an organization, etc. in order to improve or correct it","cn":"改革；变革；改良；改善","ex":{"en":"a government committed to reform","cn":"致力于改革的政府"}},{"en":"to improve a system, an organization, a law, etc. by making changes to it","cn":"改革；改进；改良","g":"[transitive]","ex":{"en":"proposals to reform the social security system","cn":"改革社会保障制度的建议"},"pos":"verb"},{"en":"to improve your behaviour; to make somebody do this","cn":"（使）改正，改造（行为）；（使）悔改","g":"[intransitive, transitive]","ex":{"en":"He has promised to reform.","cn":"他许诺要改过自新。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"变革;改革;革新;改良","en":"Reform consists of changes and improvements to a law, social system, or institution. A reform is an instance of such a change or improvement.","ex":{"en":"The party embarked on a programme of economic reform","cn":"这个党开始进行经济改革。"}},{"pos":"VERB 动词","cn":"改良;革新;变革;改革","en":"If someone reforms something such as a law, social system, or institution, they change or improve it.","ex":{"en":"...his plans to reform the country's economy","cn":"他的国家经济改革计划"}},{"pos":"V-ERG 及物/不及物动词","cn":"（人）洗心革面；(使)改过自新；改造","en":"When someone reforms or when something reforms them, they stop doing things that society does not approve of, such as breaking the law or drinking too much alcohol.","ex":{"en":"When his court case was coming up, James promised to reform","cn":"他的案子即将开审的时候，詹姆斯保证会改过自新。"}}]},"examples":[{"en":"She thought she could reform him.","cn":"她觉得她可以使他洗心革面。"},{"en":"proposals to reform the social security system","cn":"改革社会保险体制的建议"}]},"red-hot":{"oxford":{"phon":"ˌred ˈhɒt","pos":"adjective","senses":[{"en":"so hot that it looks red","cn":"炽热的；赤热的；热得发红的","ex":{"en":"Red-hot coals glowed in the fire.","cn":"炽热的煤炭在炉子里发光。"}},{"en":"showing strong feeling","cn":"激烈的；强烈的","ex":{"en":"her red-hot anger","cn":"她的暴怒"}},{"en":"new, exciting and of great interest to people","cn":"热门的","lab":"informal","ex":{"en":"a red-hot issue","cn":"热点问题"}},{"en":"used to describe the person, animal or team that is considered almost certain to win a race, etc.","cn":"几乎一定能获胜的人（或动物、运动队）","ex":{"en":"The race was won by the red-hot favourite.","cn":"夺标呼声最高的选手获得了比赛的胜利。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（金属或岩石）炽热的，火红的","en":"Red-hot metal or rock has been heated to such a high temperature that it has turned red.","ex":{"en":"...red-hot iron.","cn":"烧红了的烙铁"}},{"pos":"ADJ 形容词","cn":"温度极高的;烫手的","en":"A red-hot object is too hot to be touched safely.","ex":{"en":"In the main rooms red-hot radiators were left exposed.","cn":"在主室里，炽热的散热器暴露在外。"}},{"pos":"ADJ 形容词","cn":"炙手可热的;流行的","en":"Red-hot is used to describe a person or thing that is very popular, especially someone who is very good at what they do or something that is new and exciting.","ex":{"en":"Some traders are already stacking the red-hot book on their shelves.","cn":"一些经销商已经把这本火暴的书摆上架了。"}},{"pos":"ADJ 形容词","cn":"激情澎湃的；热力四射的；激烈的","en":"If someone or something is described as red-hot, they show a lot of passion, enthusiasm, or excitement.","ex":{"en":"...a red-hot sex-life.","cn":"充满激情的性生活"}},{"pos":"ADJ 形容词","cn":"夺冠热门的","en":"The red-hot favourite in a race or contest is a person or team that is strongly expected to win.","ex":{"en":"His team are red-hot favourites.","cn":"他的队伍是夺冠大热门。"}}]},"media":{"uk":"media/uk/red_hot_1_gb_1.mp3","us":"media/us/red_hot_1_us_1.mp3"},"examples":[{"en":"The race was won by the red-hot favourite.","cn":"夺标呼声最高的选手获得了比赛的胜利。"},{"en":"Red-hot coals glowed in the fire.","cn":"炽热的煤炭在炉子里发光。"}]},"realization":{"media":{"uk":"media/uk/realization__gb_1.mp3","us":"media/us/realization__us_1.mp3"},"oxford":{"phon":"ˌriːəlaɪˈzeɪʃn","pos":"noun","senses":[{"en":"the process of becoming aware of something","cn":"认识；领会；领悟","g":"[uncountable, singular]","ex":{"en":"As realization dawned, he went pale.","cn":"当他意识到这一点时，他的脸色变得苍白。"}},{"en":"the process of achieving a particular aim, etc.","cn":"（目标等的）实现","g":"[uncountable]","ex":{"en":"It was the realization of his greatest ambition.","cn":"这就实现了他的宏伟抱负。"}},{"en":"the act of selling something that you own, such as property, in order to get the money that you need for something","cn":"变卖；兑换成现金","g":"[uncountable]","lab":"formal"},{"en":"the act of producing a sound, play, design, etc.; or the thing that is produced","cn":"发声；（戏剧）演出；设计成果","g":"[uncountable, countable]","lab":"formal"}]},"examples":[{"en":"There is a growing realization that changes must be made.","cn":"越来越多的人认识到改革势在必行。"},{"en":"the sudden realization of what she had done","cn":"突然意识到她自己究竟干了些什么"}]},"rejects":{"lemma":"reject","media":{"uk":"media/uk/reject__gb_1.mp3","us":"media/us/reject__us_1.mp3"}},"responsible":{"media":{"uk":"media/uk/responsible__gb_1.mp3","us":"media/us/responsible__us_1.mp3"},"oxford":{"phon":"rɪˈspɒnsəbl","pos":"adjective","senses":[{"en":"having the job or duty of doing something or taking care of somebody/something, so that you may be blamed if something goes wrong","cn":"有责任；负责；承担义务","sc":"having job/duty","ex":{"en":"Mike is responsible for designing the entire project.","cn":"迈克负责设计全部工程。"}},{"en":"being able to be blamed for something","cn":"应受责备；有责任","sc":"causing something","ex":{"en":"Who's responsible for this mess?","cn":"是谁弄得这么乱？"}},{"en":"being the cause of something","cn":"作为原因；成为起因","sc":"causing something","ex":{"en":"Cigarette smoking is responsible for about 90 per cent of deaths from lung cancer.","cn":"大约 90% 的肺癌死亡是由吸烟导致的。"}},{"en":"that you can trust and rely on","cn":"可信任的；可信赖的；可靠的","sc":"reliable","ex":{"en":"The child should be accompanied by a parent or other responsible adult.","cn":"儿童应由父母或其他成年责任人陪同。"}},{"en":"needing somebody who can be trusted and relied on; involving important duties","cn":"责任重大的；需要可靠的人负责的","g":"[usually before noun]","sc":"job","ex":{"en":"a responsible position","cn":"重要岗位"}},{"en":"having to report to somebody/something with authority or in a higher position and explain to them what you have done","cn":"（向主管者或上级）承担责任","sc":"to somebody in authority","ex":{"en":"The Council of Ministers is responsible to the Assembly.","cn":"内阁须向议会负责。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"负有责任的;应承担责任的","en":"If someone or something is responsible for a particular event or situation, they are the cause of it or they can be blamed for it.","ex":{"en":"He still felt responsible for her death","cn":"他仍然觉得自己对她的死负有责任。"}},{"pos":"ADJ 形容词","cn":"对(某事物)负责的","en":"If you are responsible for something, it is your job or duty to deal with it and make decisions relating to it.","ex":{"en":"...the minister responsible for the environment","cn":"负责环境工作的部长"}},{"pos":"ADJ 形容词","cn":"对(某人或某团体)负责的","en":"If you are responsible to a person or group, they have authority over you and you have to report to them about what you do.","ex":{"en":"I'm responsible to my board of directors","cn":"我对董事会负责。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"负责的;有责任心的;可靠的","en":"Responsible people behave properly and sensibly, without needing to be supervised.","ex":{"en":"He's a very responsible sort of person","cn":"他是个非常有责任心的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"责任重大的","en":"Responsible jobs involve making important decisions or carrying out important tasks.","ex":{"en":"I work in a government office. It's a responsible position, I suppose, but not very exciting","cn":"我在政府机关工作。我想那是一个责任重大的职位，但并不是很有意思。"}}]},"examples":[{"en":"Even where parents no longer live together, they each continue to be responsible for their children.","cn":"即使父母不再共同生活，他们也要分别对子女负责。"},{"en":"Cigarette smoking is responsible for about 90% of deaths from lung cancer.","cn":"因患肺癌而死亡者，约 90% 是吸烟所致。"}]},"recognize":{"media":{"uk":"media/uk/recognize__gb_1.mp3","us":"media/us/recognize__us_1.mp3"},"oxford":{"phon":"ˈrekəɡnaɪz","pos":"verb","senses":[{"en":"to know who somebody is or what something is when you see or hear them or it, because you have seen or heard them or it before","cn":"认识；认出；辨别出","ex":{"en":"I recognized him as soon as he came in the room.","cn":"他一进屋我就认出了他。"}},{"en":"to admit or to be aware that something exists or is true","cn":"承认；意识到","ex":{"en":"They recognized the need to take the problem seriously.","cn":"他们承认需要严肃对待这个问题。"}},{"en":"to accept and approve of somebody/something officially","cn":"（正式）认可，接受，赞成","ex":{"en":"The UK has refused to recognize the new regime.","cn":"英国已拒绝承认这个新的政权。"}},{"en":"to be thought of as very good or important by people in general","cn":"赞赏；赏识；看重；公认","ex":{"en":"The book is now recognized as a classic.","cn":"这本书现在是一部公认的经典著作。"}},{"en":"to give somebody official thanks for something that they have done or achieved","cn":"正式向…致谢；正式感谢","ex":{"en":"His services to the state were recognized with the award of a knighthood.","cn":"他被封为爵士，以表彰他对国家的贡献。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"认识;认出","en":"If you recognize someone or something, you know who that person is or what that thing is.","ex":{"en":"The receptionist recognized him at once","cn":"接待员一眼就认出他了。"}},{"pos":"VERB 动词","cn":"认可；承认","en":"If someone says that they recognize something, they acknowledge that it exists or that it is true.","ex":{"en":"I recognize my own shortcomings","cn":"我承认自己的缺点。"}},{"pos":"VERB 动词","cn":"正式认可;承认;正式接受;赞成","en":"If people or organizations recognize something as valid, they officially accept it or approve of it.","ex":{"en":"Most doctors appear to recognize homeopathy as a legitimate form of medicine","cn":"大多数医生似乎都接受顺势疗法是一种合理的医疗手段。"}},{"pos":"VERB 动词","cn":"赞赏，认可（某人的所作所为）","en":"When people recognize the work that someone has done, they show their appreciation of it, often by giving that person an award of some kind.","ex":{"en":"The RAF recognized him as an outstandingly able engineer","cn":"英国皇家空军表彰他是一名非常能干的机械师。"}}]},"examples":[{"en":"His services to the state were recognized with the award of a knighthood.","cn":"他被封为爵士，以表彰他对国家的贡献。"},{"en":"It was recognized that this solution could only be temporary.","cn":"人们意识到这只是个临时的解决方案。"}]},"regulation":{"oxford":{"phon":"ˌreɡjuˈleɪʃn","pos":"noun","senses":[{"en":"an official rule made by a government or some other authority","cn":"章程；规章制度；规则；法规","g":"[countable, usually plural]","ex":{"en":"too many rules and regulations","cn":"过多的规章制度"}},{"en":"controlling something by means of rules","cn":"（运用规则条例的）管理，控制","g":"[uncountable]","ex":{"en":"the voluntary regulation of the press","cn":"新闻出版业的自律"}},{"en":"that must be worn or used according to the official rules","cn":"规定的；必须穿戴的；必须使用的","ex":{"en":"in regulation uniform","cn":"穿着规定的制服"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"规则;规章;规定;制度","en":"Regulations are rules made by a government or other authority in order to control the way something is done or the way people behave.","ex":{"en":"The European Union has proposed new regulations to control the hours worked by its employees","cn":"欧盟已经就其雇员工作时间的控制问题拟定了新的规章。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(常指通过规章制度进行的)调控，管理，控制","en":"Regulation is the controlling of an activity or process, usually by means of rules.","ex":{"en":"Social services also have responsibility for the regulation of nurseries","cn":"社会福利部门也有责任对托儿所进行管理。"}}]},"media":{"uk":"media/uk/regulation__gb_1.mp3","us":"media/us/regulation__us_1.mp3"},"examples":[{"en":"Under the new regulations spending on office equipment will be strictly controlled.","cn":"根据新的规定，办公设备开支将受到严格控制。"},{"en":"the strict regulations governing the sale of weapons","cn":"关于武器销售的严格规定"}]},"rev":{"oxford":{"phon":"rev","pos":"verb","senses":[{"en":"when you rev an engine or it revs, it runs quickly","cn":"（使）快速运转","ex":{"en":"The taxi driver revved up his engine.","cn":"出租车司机把发动机发动起来。"}},{"en":"a complete turn of an engine, used when talking about an engine’s speed","cn":"（发动机的转速）一次旋转","ex":{"en":"4 000 revs per minute","cn":"每分钟 4 000 转"},"pos":"noun"},{"en":"(used before a name) reverend","cn":"（尊称神职人员）尊敬的，可敬的","ex":{"en":"Rev. Jesse Jackson","cn":"尊敬的杰西·杰克逊牧师"},"pos":"abbreviation"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)加快转速;(使)加速","en":"When the engine of a vehicle revs, or when you rev it, the engine speed is increased as the accelerator is pressed.","ex":{"en":"The engine started, revved and the car jerked away down the hill","cn":"引擎发动了，油门加大后车冲下了山坡。"}},{"pos":"N-PLURAL 复数名词","cn":"(发动机的)转速","en":"If you talk about the revs of an engine, you are referring to its speed, which is measured in revolutions per minute.","ex":{"en":"The engine delivers instant acceleration whatever the revs.","cn":"不论转速如何，发动机都可以立即加速。"}},{"pos":"","cn":"","en":"相关词组：rev up"}]},"media":{"uk":"media/uk/rev__gb_1.mp3","us":"media/us/rev__us_1.mp3"},"examples":[{"en":"The taxi driver revved up his engine.","cn":"出租车司机把发动机发动起来。"},{"en":"I could hear the car revving outside.","cn":"我听到外面汽车发动的声音。"}]},"regular":{"media":{"uk":"media/uk/regular__gb_1.mp3","us":"media/us/regular__us_1.mp3"},"oxford":{"phon":"ˈreɡjələ(r)","pos":"adjective","senses":[{"en":"following a pattern, especially with the same time or space in between each thing and the next","cn":"规则的；有规律的；间隙均匀的；定时的","sc":"following pattern","ex":{"en":"regular breathing","cn":"均匀的呼吸"}},{"en":"done or happening often","cn":"频繁的；经常做（或发生）的","sc":"frequent","ex":{"en":"Do you take regular exercise?","cn":"你经常锻炼吗？"}},{"en":"doing the same thing or going to the same place often","cn":"经常做某事的；常去某地的","g":"[only before noun]","sc":"frequent","ex":{"en":"regular readers/customers/users","cn":"热心读者；老客户；老用户"}},{"en":"changing their form in the same way as most other verbs and nouns","cn":"规则的；按规则变化的","sc":"grammar","ex":{"en":"The past participle of regular verbs ends in ‘-ed’.","cn":"规则动词的过去分词以 -ed 结尾。"}},{"en":"usual","cn":"通常","g":"[only before noun]","sc":"usual","ex":{"en":"I couldn't see my regular doctor today.","cn":"我今天找不到平常给我看病的医生。"}},{"en":"of a standard size","cn":"标准尺寸的；中等大小的；中号的","lab":"especially North American English","sc":"standard size","ex":{"en":"Regular or large fries?","cn":"中号的还是大号的炸薯条？"}},{"en":"ordinary; without any special or extra features","cn":"普通的；平凡的","g":"[only before noun]","lab":"especially North American English","sc":"ordinary","ex":{"en":"Do you want regular or diet cola?","cn":"你要普通的还是低热量的可乐？"}},{"en":"having an even shape","cn":"均匀的；端正的；齐整的","sc":"even","ex":{"en":"a face with regular features","cn":"五官端正的脸庞"}},{"en":"lasting or happening over a long period","cn":"持久的；稳定的；固定的","sc":"permanent","ex":{"en":"The need to earn a regular income restricted the time he could spend pursuing his real interests.","cn":"赚取固定收入的需要限制了他追求真正兴趣的时间。"}},{"en":"belonging to or connected with the permanent armed forces or police force of a country","cn":"常备军的；正规军的","g":"[only before noun]","sc":"soldier","ex":{"en":"the regular army","cn":"正规军"}},{"en":"used for emphasis to show that somebody/something is an exact or clear example of the thing mentioned","cn":"完全的；彻底的","lab":"informal","sc":"for emphasis","ex":{"en":"The whole thing was a regular disaster.","cn":"整个事情完全是一场灾难。"}},{"en":"a customer who often goes to a particular shop, pub, restaurant, etc.","cn":"常客；老主顾","sc":"customer","ex":{"en":"He's one of our regulars.","cn":"他是我们的一位老主顾。"},"pos":"noun"},{"en":"a person who often plays in a particular team, takes part in a particular television show, etc.","cn":"主力（或正式）队员；（电视节目的）常任主持人；经常参加某项活动的人","sc":"member of team","ex":{"en":"We are missing six first-team regulars because of injury.","cn":"我们有六位一线主力队员因伤不能出场。"},"pos":"noun"},{"en":"a professional soldier who belongs to a country’s permanent army","cn":"正规军人；职业军人","sc":"soldier","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"定时的;定期的;有规律的","en":"Regular events have equal amounts of time between them, so that they happen, for example, at the same time each day or each week.","ex":{"en":"Take regular exercise","cn":"定期进行锻炼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"经常的;频繁的","en":"Regular events happen often.","ex":{"en":"...after a morning punctuated by regular volleys of gunfire","cn":"过了枪声阵阵的早上之后"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"经常光顾的;经常去的","en":"If you are, for example, a regular customer at a shop or a regular visitor to a place, you go there often.","ex":{"en":"'Tell me, Mr Mentakis, was Mrs Savalas one of your regular customers?'","cn":"“告诉我，门塔基斯先生，萨瓦拉斯夫人是您的常客吗？”"}},{"pos":"N-COUNT 可数名词","cn":"常客;老顾客;固定成员;正式成员","en":"The regulars at a place or in a team are the people who often go to the place or are often in the team.","ex":{"en":"Regulars at his local pub have set up a fund to help out","cn":"经常光顾他的酒吧的人伸出援手成立了一个基金会。"}},{"pos":"ADJ 形容词","cn":"经常使用的;固定的","en":"You use regular when referring to the thing, person, time, or place that is usually used by someone. For example, someone's regular place is the place where they usually sit.","ex":{"en":"The man sat at his regular table near the window.","cn":"这个人坐在他固定的靠窗的位置。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（声音或动作）规律的，规则的","en":"A regular rhythm consists of a series of sounds or movements with equal periods of time between them.","ex":{"en":"...a very regular beat","cn":"非常规律的节拍"}},{"pos":"ADJ 形容词","cn":"正常的;常见的;普通的","en":"Regular is used to mean 'normal'.","ex":{"en":"The product looks and burns like a regular cigarette","cn":"这种产品看起来和点燃后都与常见的香烟没什么两样。"}},{"pos":"ADJ 形容词","cn":"(饮品或食物)分量适中的，中份的","en":"In some restaurants, a regular drink or quantity of food is of medium size.","ex":{"en":"...a cheeseburger and regular fries.","cn":"一个奶酪汉堡和中份薯条"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"整齐排列的;（空距）均匀的","en":"A regular pattern or arrangement consists of a series of things with equal spaces between them.","ex":{"en":"...strange small rounded sandy hillocks, that look as if they've been scattered in a regular pattern on the ground.","cn":"奇怪的圆形小沙丘，看上去好像是被整齐地散放在地上似的"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"匀称的;对称的","en":"If something has a regular shape, both halves are the same and it has straight edges or a smooth outline.","ex":{"en":"...some regular geometrical shape.","cn":"一些对称的几何图形"}},{"pos":"ADJ 形容词","cn":"（军队）常规的，常备的","en":"Regular troops are professional soldiers who are a permanent part of an official national army.","ex":{"en":"Most schemes attempt to reduce the cost of defence through a smaller regular army","cn":"大多数方案都试图通过缩减常备军的规模来降低国防支出。"}},{"pos":"ADJ 形容词","cn":"(语法中)按规则变化的，规则的","en":"In grammar, a regular verb, noun, or adjective inflects in the same way as most verbs, nouns, or adjectives in the language."}]},"examples":[{"en":"( approving ) He's just a regular guy who loves his dog.","cn":"他也不过是个十分疼爱自己狗儿的平凡人。"},{"en":"The past participle of regular verbs ends in ‘-ed’.","cn":"规则动词的过去分词以 -ed 结尾。"}]},"reversed":{"lemma":"reverse"},"reflecting":{"lemma":"reflect","media":{"uk":"media/uk/reflect__gb_1.mp3","us":"media/us/reflect__us_1.mp3"}},"revelation":{"media":{"uk":"media/uk/revelation__gb_1.mp3","us":"media/us/revelation__us_1.mp3"},"oxford":{"phon":"ˌrevəˈleɪʃn","pos":"noun","senses":[{"en":"a fact that people are made aware of, especially one that has been secret and is surprising","cn":"被暴露的真相；被曝光的秘闻","g":"[countable]","ex":{"en":"startling/sensational revelations about her private life","cn":"对她的私生活令人吃惊的曝光"}},{"en":"the act of making people aware of something that has been secret","cn":"披露；揭露","g":"[uncountable]","ex":{"en":"The company's financial problems followed the revelation of a major fraud scandal.","cn":"重大的欺诈丑闻被揭露之后，公司随之出现了财务问题。"}},{"en":"something that is considered to be a sign or message from God","cn":"（上帝的）启示","g":"[countable, uncountable]","lab":"North American English","ex":{"en":"These events were seen as a divine revelation.","cn":"这些事件被视为神圣的启示。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"被揭示的真相;被揭露的内情","en":"A revelation is a surprising or interesting fact that is made known to people.","ex":{"en":"...the seemingly everlasting revelations about his private life.","cn":"对他的私生活看似没完没了的曝光"}},{"pos":"N-VAR 可变名词","cn":"揭露;披露;透露","en":"The revelation of something is the act of making it known.","ex":{"en":"...following the revelation of his affair with a former secretary","cn":"在他和前秘书的私情被揭露之后"}},{"pos":"N-SING 单数名词","cn":"意想不到的事物;非常好的事物","en":"If you say that something you experienced was a revelation, you are saying that it was very surprising or very good.","ex":{"en":"The noise, the buildings, the people, came as a revelation","cn":"这里的噪音、建筑物和人都令人出乎意料。"}},{"pos":"N-VAR 可变名词","cn":"(上帝的)启示，默示","en":"A divine revelation is a sign or explanation from God about his nature or purpose.","ex":{"en":"The whole system was based on divine revelation in the Scriptures.","cn":"整个体系都建立在《圣经》的神圣启示的基础之上。"}}]},"examples":[{"en":"The company's financial problems followed the revelation of a major fraud scandal.","cn":"重大的欺诈丑闻被揭露之后，公司随之出现了财政问题。"},{"en":"startling/sensational revelations about her private life","cn":"对她的私生活令人吃惊的/哗众取宠的揭露"}]},"reckless":{"media":{"uk":"media/uk/reckless__gb_1.mp3","us":"media/us/reckless__us_1.mp3"},"oxford":{"phon":"ˈrekləs","pos":"adjective","senses":[{"en":"showing a lack of care about danger and the possible results of your actions","cn":"鲁莽的；不计后果的；无所顾忌的","ex":{"en":"He showed a reckless disregard for his own safety.","cn":"他全然不顾个人安危。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"轻率的;不计后果的;鲁莽的;无所顾忌的","en":"If you say that someone is reckless, you mean that they act in a way which shows that they do not care about danger or the effect their behaviour will have on other people.","ex":{"en":"She loved to ride; on horseback, she was reckless and utterly without fear","cn":"她喜欢骑马；在马背上，她纵横驰骋，毫无畏惧。"}}]},"examples":[{"en":"He showed a reckless disregard for his own safety.","cn":"他对个人安危全然无所顾忌。"},{"en":"She was a good rider, but reckless.","cn":"她是个好骑手，但太鲁莽。"}]},"retire":{"media":{"uk":"media/uk/retire__gb_1.mp3","us":"media/us/retire__us_1.mp3"},"oxford":{"phon":"rɪˈtaɪə(r)","pos":"verb","senses":[{"en":"to leave your job and stop working, especially because you have reached a particular age or because you are ill; to tell somebody they must stop doing their job","cn":"（令）退职；（使）退休","g":"[intransitive, transitive]","sc":"from job","ex":{"en":"He is retiring next year after 30 years with the company.","cn":"他在这家公司工作了30年，明年就要退休了。"}},{"en":"to stop competing during a game, race, etc., usually because you are injured","cn":"（因伤）退出（比赛等）","g":"[intransitive]","sc":"in sport","ex":{"en":"She fell badly, spraining her ankle, and had to retire.","cn":"她摔得很重，扭伤了脚踝，只好退出比赛。"}},{"en":"to leave a place, especially to go somewhere quieter or more private","cn":"离开（尤指去僻静处）","g":"[intransitive]","lab":"formal","sc":"from/to a place","ex":{"en":"The jury retired to consider the evidence.","cn":"陪审团退庭对证据进行评判。"}},{"en":"to move back from a battle in order to organize your soldiers in a different way","cn":"撤离，撤退（以进行休整）","g":"[intransitive]","lab":"formal","sc":"of army"},{"en":"to go to bed","cn":"睡觉；就寝","g":"[intransitive]","lab":"literary","sc":"go to bed","ex":{"en":"I retired late that evening.","cn":"那天晚上我睡得晚。"}},{"en":"to make a player or team have to stop their turn at batting","cn":"使（击球员、击球方）出局","g":"[transitive]","sc":"in baseball","ex":{"en":"He retired twelve batters in a row.","cn":"他一连使十二个击球手出局。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"退休;退职","en":"When older people retire, they leave their job and usually stop working completely.","ex":{"en":"At the age when most people retire, he is ready to face a new career","cn":"在大多数人都退休的年龄，他却准备好面对新的职业。"}},{"pos":"VERB 动词","cn":"（从体育运动中）退役;退出（比赛）","en":"When a sports player retires from their sport, they stop playing in competitions. When they retire from a race or a match, they stop competing in it.","ex":{"en":"I have decided to retire from Formula One racing at the end of the season","cn":"我已经决定在这个赛季末结束一级方程式赛车生涯。"}},{"pos":"VERB 动词","cn":"退出，离开（去别的地方）","en":"If you retire to another room or place, you go there.","ex":{"en":"Eisenhower left the White House and retired to his farm in Gettysburg.","cn":"艾森豪威尔离开白宫，退隐到他在葛底斯堡的农场。"}},{"pos":"VERB 动词","cn":"退庭;休庭","en":"When a jury in a court of law retires, the members of it leave the court in order to decide whether someone is guilty or innocent.","ex":{"en":"The jury will retire to consider its verdict today.","cn":"陪审团今天将退庭商议裁决结果。"}},{"pos":"VERB 动词","cn":"就寝","en":"When you retire, you go to bed.","ex":{"en":"She retires early most nights, exhausted","cn":"她大多数晚上都觉得精疲力尽，很早就睡了。"}},{"pos":"See also:","cn":"","en":"→see usage note at:"}]},"examples":[{"en":"She was forced to retire early from teaching because of ill health.","cn":"她由于身体不好而被迫早早地从教学岗位上退休。"},{"en":"She fell badly, spraining her ankle, and had to retire.","cn":"她摔得很重，扭伤了脚踝，只好退出比赛。"}]},"reply":{"media":{"uk":"media/uk/reply__gb_1.mp3","us":"media/us/reply__us_1.mp3"},"oxford":{"phon":"rɪˈplaɪ","pos":"verb","senses":[{"en":"to say or write something as an answer to somebody/something","cn":"回答；答复","g":"[intransitive, transitive]","ex":{"en":"She didn't even bother to reply.","cn":"她根本就懒得回答。"}},{"en":"to do something as a reaction to something that somebody has said or done","cn":"回应；作出反应","g":"[intransitive]","ex":{"en":"Italy took an early lead but Brazil replied with two goals in the last five minutes.","cn":"意大利队早早取得领先，但巴西队在最后五分钟内连进两球予以反击。"}},{"en":"an act of replying to something/somebody in speech, writing or by some action","cn":"回答；答复","lab":"formal","ex":{"en":"I asked her what her name was but she made no reply.","cn":"我问她叫什么名字，但她没有回答。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"回复;回答","en":"When you reply to something that someone has said or written to you, you say or write an answer to them.","ex":{"en":"'That's a nice dress,' said Michael. 'Thanks,' she replied solemnly","cn":"“那件衣服很好看，”迈克尔说。“谢谢，”她严肃地回答。"}},{"pos":"N-COUNT 可数名词","cn":"回信;回复;回应","en":"A reply is something that you say or write when you answer someone or answer a letter or advertisement.","ex":{"en":"I called out a challenge, but there was no reply","cn":"我提出挑战，但是没人回应。"}},{"pos":"VERB 动词","cn":"(在体育比赛中)以得分回应，回敬，","en":"In sports, if you reply to a goal or a number of points scored by your opponents, you also score a goal or a number of points.","ex":{"en":"Graeme Hick scored an unbeaten 58 as Worcestershire replied to Middlesex's 202 with 132-3","cn":"格雷姆·希克未出局拿得58分，从而使伍斯特郡队以132分3人出局的成绩回敬了米德尔塞克斯队的202分。"}},{"pos":"VERB 动词","cn":"(以行动)作出回应，回击，反击","en":"If you reply to something such as an attack with violence or with another action, you do something in response.","ex":{"en":"Farmers threw eggs and empty bottles at police, who replied with tear gas","cn":"农民向警察扔鸡蛋和空瓶子，警察则以催泪弹回击。"}}]},"examples":[{"en":"( BrE ) Morocco scored four goals without reply to win the game.","cn":"摩洛哥队在一球未失的情况下连入四球，赢得了这场比赛。"},{"en":"The terrorists replied to the government's statement with more violence.","cn":"恐怖分子以更多的暴力事件来回应政府的声明。"}]},"revolutionize":{"media":{"uk":"media/uk/revolutionize__gb_1.mp3","us":"media/us/revolutionize__us_1.mp3"},"oxford":{"phon":"ˌrevəˈluːʃənaɪz","pos":"verb","senses":[{"en":"to completely change the way that something is done","cn":"彻底改变；完全变革","ex":{"en":"Aerial photography has revolutionized the study of archaeology.","cn":"航空摄影已经给考古学研究带来了一场革命。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使发生巨大变革;给…带来革命性剧变","en":"When something revolutionizes an activity, it causes great changes in the way that it is done.","ex":{"en":"Over the past forty years plastics have revolutionised the way we live","cn":"在过去的40年中，塑料彻底改变了我们的生活方式。"}}]},"examples":[{"en":"Aerial photography has revolutionized the study of archaeology.","cn":"航空摄影已经给考古学研究带来了一场革命。"},{"en":"New technology is going to revolutionize everything we do.","cn":"新科技将彻底改变我们做的每一件事。"}]},"reviewing":{"lemma":"review"},"retraining":{"oxford":{"phon":"ˌriːˈtreɪnɪŋ","pos":"noun","senses":[{"en":"the process of learning, or of teaching somebody, a new type of work, a new skill, etc.","cn":"（接受）重新培养，再教育，再培训","ex":{"en":"a retraining programme/course","cn":"再培训计划/课程"}}]},"media":{"uk":"media/uk/retraining__gb_1.mp3","us":"media/us/retraining__us_1.mp3"},"examples":[{"en":"One solution is to retrain the long-term unemployed.","cn":""},{"en":"She’s hoping to retrain as a teacher.","cn":""}],"base":"retrain"},"represent":{"media":{"uk":"media/uk/represent__gb_1.mp3","us":"media/us/represent__us_1.mp3"},"oxford":{"phon":"ˌreprɪˈzent","pos":"verb","senses":[{"en":"to be a member of a group of people and act or speak for them at an event, a meeting, etc.","cn":"代表","g":"[often passive]","sc":"act/speak for somebody","ex":{"en":"The competition attracted over 500 contestants representing eight different countries.","cn":"这次比赛吸引了代表 8 个不同国家的 500 多名参赛者。"}},{"en":"to act or speak officially for somebody and defend their interests","cn":"作为…的代言人；维护…的利益","sc":"act/speak for somebody","ex":{"en":"The union represents over 200 000 teachers.","cn":"工会代表着 20 余万名教师的利益。"}},{"en":"to take part in a sports event for a particular country, city, etc.","cn":"代表…参赛","sc":"in sport","ex":{"en":"He's been chosen to represent Scotland in next year's World Cup Finals.","cn":"他被选中代表苏格兰参加明年的世界杯决赛。"}},{"en":"to be a symbol of something","cn":"象征；是…的象征；代表","sc":"be symbol","ex":{"en":"Each colour on the chart represents a different department.","cn":"图表中的每一种颜色都代表一个不同的部门。"}},{"en":"to be something","cn":"是；等于；相当于","sc":"be equal to","ex":{"en":"This contract represents 20% of the company's annual revenue.","cn":"这份合约相当于公司 20% 的年收入。"}},{"en":"to be present in something to a particular degree","cn":"占（一定数量）","sc":"be present","ex":{"en":"Women and men were represented equally on the teams.","cn":"小组中男女人数相当。"}},{"en":"to be an example or expression of something","cn":"成为…实例；成为典型；体现","g":"[no passive]","sc":"be example of","ex":{"en":"The project represents all that is good in the community.","cn":"这项工程充分体现了社区的美好。"}},{"en":"to show somebody/something, especially in a picture","cn":"展示；描绘","lab":"formal","sc":"in picture","ex":{"en":"The carvings represent a hunting scene.","cn":"这些雕刻作品描绘了一幅狩猎的场面。"}},{"en":"to present or describe somebody/something in a particular way, especially when this may not be fair","cn":"（尤指不公平地）展现，描述，表现","lab":"formal","sc":"describe","ex":{"en":"The king is represented as a villain in the play.","cn":"剧中国王的形象是一个恶棍。"}},{"en":"to make a formal statement to somebody in authority to make your opinions known or to protest","cn":"正式提出（意见、抗议等）","lab":"formal","sc":"make formal statement","ex":{"en":"They represented their concerns to the authorities.","cn":"他们向当局陈述了他们关心的问题。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"代理，代表（个人或团体）","en":"If someone such as a lawyer or a politician represents a person or group of people, they act on behalf of that person or group.","ex":{"en":"...the politicians we elect to represent us","cn":"我们选举出来代表我们的政界人士"}},{"pos":"VERB 动词","cn":"代表（个人或团体）出席","en":"If you represent a person or group at an official event, you go there on their behalf.","ex":{"en":"The general secretary may represent the president at official ceremonies.","cn":"总书记可以在一些官方仪式上代表主席。"}},{"pos":"VERB 动词","cn":"(在竞赛或体育赛事中)代表（国家或地区）","en":"If you represent your country or town in a competition or sports event, you take part in it on behalf of the country or town where you live.","ex":{"en":"My only aim is to represent Britain at the Olympics.","cn":"我唯一的目标是代表英国参加奥运会。"}},{"pos":"V-PASSIVE 被动动词","cn":"使有代表性","en":"If a group of people or things is well represented in a particular activity or in a particular place, a lot of them can be found there.","ex":{"en":"Women are already well represented in the area of TV drama","cn":"女性在电视剧领域占据了一席之地。"}},{"pos":"V-LINK 连系动词","cn":"相当于，代表着（变化、成就、胜利等）","en":"If you say that something represents a change, achievement, or victory, you mean that it is a change, achievement, or victory.","ex":{"en":"The pieces on view are not grouped around any one theme, but rather represent superb examples from various periods","cn":"展出的作品并非围绕着一个主题，而是不同时期的经典之作。"}},{"pos":"VERB 动词","cn":"(标志或符号)意味着，代表着，标志着","en":"If a sign or symbol represents something, it is accepted as meaning that thing.","ex":{"en":"...a black dot in the middle of the circle is supposed to represent the source of the radiation.","cn":"圆圈中心的黑点应该是表示放射源。"}},{"pos":"VERB 动词","cn":"象征;体现;反映","en":"To represent an idea or quality means to be a symbol or an expression of that idea or quality.","ex":{"en":"We believe you represent everything British racing needs.","cn":"我们相信你代表了英国赛马所需要的一切。"}},{"pos":"VERB 动词","cn":"描绘;描写","en":"If you represent a person or thing as a particular thing, you describe them as being that thing.","ex":{"en":"The popular press tends to represent him as an environmental guru.","cn":"大众媒体往往把他描绘成环保领袖。"}}]},"examples":[{"en":"The competition attracted over 500 contestants representing 8 different countries.","cn":"这次比赛吸引了代表 8 个不同国家的 500 多名参赛者。"},{"en":"This decision represents a significant departure from previous policy.","cn":"这个决定意味着在很大程度上脱离了原先的政策。"}]},"rejected":{"lemma":"reject","media":{"uk":"media/uk/reject__gb_1.mp3","us":"media/us/reject__us_1.mp3"}},"revenue":{"media":{"uk":"media/uk/revenue__gb_1.mp3","us":"media/us/revenue__us_1.mp3"},"oxford":{"phon":"ˈrevənjuː","pos":"noun","senses":[{"en":"the money that a government receives from taxes or that an organization, etc. receives from its business","cn":"财政收入；税收收入；收益","lab":"North American English","ex":{"en":"The government is currently facing a shortfall in tax revenue.","cn":"政府目前有税收缺口。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(公司、组织的)收入，收益;（政府的）财政收入，税收","en":"Revenue is money that a company, organization, or government receives from people.","ex":{"en":"...a boom year at the cinema, with record advertising revenue and the highest ticket sales since 1980","cn":"电影院非常景气的一年，创下1980年以来广告及票房收入新高"}}]},"examples":[{"en":"The company's annual revenues rose by 30%.","cn":"公司的年收入增加了 30%。"},{"en":"a slump in oil revenues","cn":"石油收入的下跌"}]},"relegate":{"media":{"uk":"media/uk/relegate__gb_1.mp3","us":"media/us/relegate__us_1.mp3"},"oxford":{"phon":"ˈrelɪɡeɪt","pos":"verb","senses":[{"en":"to give somebody a lower or less important position, rank, etc. than before","cn":"使贬职；使降级；降低…的地位","ex":{"en":"She was then relegated to the role of assistant.","cn":"随后她被降级做助手了。"}},{"en":"to move a sports team from playing with one group of teams to playing in a lower group","cn":"使（运动队）降级，降组","g":"[usually passive]","lab":"British English"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"贬黜;把…降级;把…降格","en":"If you relegate someone or something to a less important position, you give them this position.","ex":{"en":"Might it not be better to relegate the King to a purely ceremonial function?","cn":"让国王变成纯粹发挥典礼仪式上象征作用的元首会不会更好？"}},{"pos":"VERB 动词","cn":"使(球队)降级","en":"If a sports team that competes in a league is relegated, it has to compete in a lower division in the next competition, because it was one of the least successful teams in the higher division.","ex":{"en":"If Leigh lose, they'll be relegated.","cn":"如果利失球，他们将会降级。"}}]},"examples":[{"en":"She was then relegated to the role of assistant.","cn":"随后她被降级做助手了。"},{"en":"He relegated the incident to the back of his mind.","cn":"他将这件事抛到了脑后。"}]},"retail":{"media":{"uk":"media/uk/retail__gb_1.mp3","us":"media/us/retail__us_1.mp3"},"oxford":{"phon":"ˈriːteɪl","pos":"noun","senses":[{"en":"the selling of goods to the public, usually through shops","cn":"零售","ex":{"en":"The recommended retail price is £9.99.","cn":"建议零售价为 9.99 英镑。"}},{"en":"by or to the public, usually through shops","cn":"零售","ex":{"en":"to buy/sell retail","cn":"零买；零卖"},"pos":"adverb"},{"en":"to sell goods to the public, usually through shops","cn":"零售","g":"[transitive]","ex":{"en":"The firm manufactures and retails its own range of sportswear.","cn":"公司生产并零售自己的运动服装系列。"},"pos":"verb"},{"en":"to be sold at a particular price","cn":"以…价格销售","g":"[intransitive]","lab":"business","ex":{"en":"The book retails at £14.95.","cn":"这本书的零售价为 14.95 英镑。"},"pos":"verb"},{"en":"to tell people about something, especially about a person’s behaviour or private life","cn":"详说，述说（尤指别人的事情）","ex":{"en":"She retailed the neighbours' activities with relish.","cn":"她饶有兴趣地对邻居们的活动说三道四。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"零售;零卖","en":"Retail is the activity of selling goods direct to the public, usually in small quantities.","ex":{"en":"...retail stores","cn":"零售店"}},{"pos":"ADV 副词","cn":"以零售方式","en":"If something is sold retail, it is sold in ordinary shops direct to the public."},{"pos":"VERB 动词","cn":"（以…价格）零售，零卖","en":"If an item in a shop retails at or for a particular price, it is on sale at that price.","ex":{"en":"It originally retailed at £23.50.","cn":"它原来的零售价格是23.50英镑。"}},{"pos":"VERB 动词","cn":"（热情而详细地）讲述;详述","en":"If someone retails a story or event, they tell it to someone else, often in detail and in an exciting way.","ex":{"en":"Mr Hastings gleefully retailed the story to Mr Anderson over lunch.","cn":"黑斯廷斯先生在午宴上兴致勃勃地把这个故事向安德森先生详述了一遍。"}}]},"examples":[{"en":"The book retails at £14.95.","cn":"这本书的零售价为 14.95 英镑。"},{"en":"She retailed the neighbours' activities with relish.","cn":"她饶有兴趣地对邻居们的活动说三道四。"}]},"responsibility":{"media":{"uk":"media/uk/responsibility__gb_1.mp3","us":"media/us/responsibility__us_1.mp3"},"oxford":{"phon":"rɪˌspɒnsəˈbɪləti","pos":"noun","senses":[{"en":"a duty to deal with or take care of somebody/something, so that you may be blamed if something goes wrong","cn":"责任；负责","g":"[uncountable, countable]","ex":{"en":"to be in a position of responsibility","cn":"身居要位"}},{"en":"blame for something bad that has happened","cn":"事故责任","g":"[uncountable]","ex":{"en":"The bank refuses to accept responsibility for the mistake.","cn":"银行拒绝为这一错误承担责任。"}},{"en":"a moral duty to do something or to help or take care of somebody because of your job, position, etc.","cn":"职责；义务；任务","g":"[uncountable, countable]","ex":{"en":"We want to instil a sense of personal responsibility in children.","cn":"我们希望向孩子们灌输个人责任感。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"责任;义务","en":"If you have responsibility for something or someone, or if they are your responsibility, it is your job or duty to deal with them and to take decisions relating to them.","ex":{"en":"Each manager had responsibility for just under 600 properties","cn":"每位经理负责将近600处房产。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"责任;过失","en":"If you accept responsibility for something that has happened, you agree that you were to blame for it or you caused it.","ex":{"en":"No one admitted responsibility for the attacks","cn":"没有人对这些袭击负责。"}},{"pos":"N-PLURAL 复数名词","cn":"职责;任务","en":"Your responsibilities are the duties that you have because of your job or position.","ex":{"en":"He handled his responsibilities as a counselor in an intelligent and caring fashion.","cn":"作为一名顾问他精明能干、热心周到。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"重任;职权","en":"If someone is given responsibility, they are given the right or opportunity to make important decisions or to take action without having to get permission from anyone else.","ex":{"en":"She would have loved to have a better-paying job with more responsibility","cn":"她本想有一份报酬更高、职权更大的工作。"}},{"pos":"N-SING 单数名词","cn":"（道义上的）责任，义务","en":"If you think that you have a responsibility to do something, you feel that you ought to do it because it is morally right to do it.","ex":{"en":"The court feels it has a responsibility to ensure that customers are not misled","cn":"法院认为它有责任确保消费者不受误导。"}},{"pos":"N-SING 单数名词","cn":"对…的责任","en":"If you think that you have a responsibility to someone, you feel that it is your duty to take action that will protect their interests.","ex":{"en":"She had decided that as a doctor she had a responsibility to her fellow creatures.","cn":"她已经决定，作为医生，她应该对自己的同胞负责。"}}]},"examples":[{"en":"I think we have a moral responsibility to help these countries.","cn":"我认为我们在道义上有责任帮助这些国家。"},{"en":"We are recruiting a sales manager with responsibility for the European market.","cn":"我们正在招聘负责欧洲市场的销售经理。"}]},"resilient":{"media":{"uk":"media/uk/resilient__gb_1.mp3","us":"media/us/resilient__us_1.mp3"},"oxford":{"phon":"rɪˈzɪliənt","pos":"adjective","senses":[{"en":"able to recover quickly after something unpleasant such as shock, injury, etc.","cn":"可迅速恢复的；适应能力强的","ex":{"en":"He'll get over it—young people are amazingly resilient.","cn":"他会克服的，年轻人的适应力惊人。"}},{"en":"returning to its original shape after being bent, stretched, or pressed","cn":"有弹性（或弹力）的；能复原的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚韧的;有弹性的;有韧性的;有回弹力的","en":"Something that is resilient is strong and not easily damaged by being hit, stretched, or squeezed.","ex":{"en":"Cotton is more resistant to being squashed and polyester is more resilient.","cn":"棉布更抗压，而涤纶更有弹性。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"能复原的;恢复快的;适应力强的","en":"People and things that are resilient are able to recover easily and quickly from unpleasant or damaging events.","ex":{"en":"George Fraser was clearly a good soldier, calm and resilient","cn":"乔治·弗雷泽显然是个好士兵，沉着冷静且适应力强。"}}]},"examples":[{"en":"He'll get over it — young people are amazingly resilient.","cn":"他会克服的，年轻人的适应力惊人。"},{"en":"Children are often very resilient.","cn":"儿童的适应力一般都很强。"}]},"replicated":{"lemma":"replicate"},"recap":{"media":{"uk":"media/uk/recap__gb_1.mp3","us":"media/us/recap__us_1.mp3"},"collins":{"senses":[{"pos":"VERB 动词","cn":"概括;重述(要点)；简要回顾","en":"You can say that you are going to recap when you want to draw people's attention to the fact that you are going to repeat the main points of an explanation, argument, or description, as a summary of it.","ex":{"en":"To recap briefly, an agreement negotiated to cut the budget deficit was rejected 10 days ago","cn":"简要概括起来，一项关于削减预算赤字的协议在10天前遭到了否决。"}}]},"examples":[{"en":"Let me just recap on what we've decided so far.","cn":"让我来概括一下到目前为止我们所作的决定吧。"},{"en":"Let me just recap what’s been discussed so far.","cn":"我来扼要复述一下已讨论过的内容吧。"}],"oxford":{"phon":"ˈriːkæp","pos":"verb","senses":[{"en":"to repeat or give a summary of what has already been said, decided, etc.","cn":"重述；概括","ex":{"en":"Let me just recap.","cn":"让我回顾一下。"}},{"en":"the act of repeating or giving a summary of what has already been said, decided, etc.","cn":"重述；概括","pos":"noun"}]}},"release":{"media":{"uk":"media/uk/release__gb_1.mp3","us":"media/us/release__us_1.mp3"},"oxford":{"phon":"rɪˈliːs","pos":"verb","senses":[{"en":"to let somebody come out of a place where they have been kept or stuck and unable to leave or move","cn":"释放；放出；放走","lab":"figurative","sc":"set somebody free","ex":{"en":"to release a prisoner","cn":"释放囚犯"}},{"en":"to stop holding something or stop it from being held so that it can move, fly, fall, etc. freely","cn":"放开；松开；使自由移动（或飞翔、降落等）","sc":"stop holding something","ex":{"en":"He refused to release her arm.","cn":"他不肯放开她的胳膊。"}},{"en":"to express feelings such as anger or worry in order to get rid of them","cn":"发泄；宣泄","sc":"feelings","ex":{"en":"She burst into tears, releasing all her pent-up emotions.","cn":"她放声大哭，发泄出全部郁积起来的情感。"}},{"en":"to remove something from a fixed position, allowing something else to move or function","cn":"松开；拉开","sc":"part of machine","ex":{"en":"to release the clutch/handbrake/switch","cn":"松开离合器／手闸／开关"}},{"en":"to make information available to the public","cn":"公开；公布；发布","sc":"make available","ex":{"en":"to release a statement/report/document/poll/study","cn":"发布声明／报告／文件／民意调查／研究结果"}},{"en":"to make a film, recording or other product available to the public","cn":"发行，发布（电影、录音等产品）","sc":"make available","ex":{"en":"He's planning to release a solo album.","cn":"他计划发行一张个人专辑。"}},{"en":"to make something available that had previously been limited","cn":"开放；放开；解禁","sc":"make available","ex":{"en":"The new building programme will go ahead as soon as the government releases the funds.","cn":"政府一拨付资金，新的建筑项目就动工。"}},{"en":"to free somebody from a duty, responsibility, contract, etc.","cn":"免除，解除（某人的职责、责任、合同等）；解雇","sc":"free somebody from duty","ex":{"en":"The club is releasing some of its older players.","cn":"俱乐部正在解聘一些老队员。"}},{"en":"to make something less tight","cn":"使不紧张；使松弛；放松","sc":"make less tight","ex":{"en":"You need to release the tension in these shoulder muscles.","cn":"你需要放松肩部肌肉。"}},{"en":"the act of setting a person or an animal free; the state of being set free","cn":"释放；获释","g":"[uncountable, singular]","sc":"setting somebody/something free","ex":{"en":"The government has been working to secure the release of the hostages.","cn":"政府一直在努力争取使人质获释。"},"pos":"noun"},{"en":"the act of making a film, recording or other product available to the public","cn":"公开；发行；发布","g":"[uncountable, singular]","sc":"making something available","ex":{"en":"The new software is planned for release in April.","cn":"新软件计划四月份发行。"},"pos":"noun"},{"en":"a thing that is made available to the public, especially a new film or music recording","cn":"新发行的东西；（尤指）新电影，新专辑","g":"[countable]","sc":"making something available","ex":{"en":"recent/new releases","cn":"最近发行的／新发行的产品"},"pos":"noun"},{"en":"the act of making information available to the public","cn":"公开；发行；发布","g":"[uncountable, singular]","sc":"making something available","ex":{"en":"the release of the report","cn":"报告的公开发布"},"pos":"noun"},{"en":"the act of letting a gas, chemical, etc. move or flow freely","cn":"（气体、化学物质等的）释放，排放","g":"[uncountable, countable]","sc":"of gas/chemical","ex":{"en":"Release of these hormones gives the body a temporary increase in strength and energy.","cn":"这些激素的释放能使力量和体能短时间内增加。"},"pos":"noun"},{"en":"the feeling that you are free from pain, worry or some other unpleasant feeling","cn":"解脱；轻松感","g":"[uncountable, singular]","sc":"from unpleasant feeling","ex":{"en":"a sense of release after the exam","cn":"考试后的解脱感"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"释放;放出","en":"If a person or animal is released from somewhere where they have been locked up or looked after, they are set free or allowed to go.","ex":{"en":"He was released from custody the next day","cn":"第二天他被从拘留所里放了出来。"}},{"pos":"N-COUNT 可数名词","cn":"释放;出院","en":"When someone is released, you refer to their release .","ex":{"en":"He called for the immediate release of all political prisoners.","cn":"他要求立即释放所有政治犯。"}},{"pos":"VERB 动词","cn":"使免除;使免于","en":"If someone or something releases you from a duty, task, or feeling, they free you from it.","ex":{"en":"Divorce releases both the husband and wife from all marital obligations to each other","cn":"离婚解除了夫妻双方相互之间所有的婚姻义务。"}},{"pos":"VERB 动词","cn":"发泄，释放(情感);展示(能力)","en":"To release feelings or abilities means to allow them to be expressed.","ex":{"en":"Becoming your own person releases your creativity","cn":"保持自己的本色才有助于发挥自身创造力。"}},{"pos":"VERB 动词","cn":"发布;发表;公布","en":"If someone in authority releases something such as a document or information, they make it available.","ex":{"en":"They're not releasing any more details yet","cn":"他们还未公布更多细节。"}},{"pos":"VERB 动词","cn":"放手;放开;释放","en":"If you release someone or something, you stop holding them.","ex":{"en":"He stopped and faced her, releasing her wrist.","cn":"他停下来面对着她，放开了她的手腕。"}},{"pos":"VERB 动词","cn":"打开，放开，松开(制动装置)","en":"If you release a device, you move it so that it stops holding something.","ex":{"en":"Wade released the hand brake and pulled away from the curb.","cn":"韦德松开手刹驶离路边。"}},{"pos":"VERB 动词","cn":"释放，放出，排放(气体、热量或某种物质)","en":"If something releases gas, heat, or a substance, it causes it to leave its container or the substance that it was part of and enter the surrounding atmosphere or area.","ex":{"en":"...a weapon which releases toxic nerve gas","cn":"释放神经毒气的武器"}},{"pos":"VERB 动词","cn":"发行，推出(唱片、碟片或电影)","en":"When an entertainer or company releases a new CD, video, or film, it becomes available so that people can buy it or see it.","ex":{"en":"He is releasing an album of love songs.","cn":"他即将推出一张情歌专辑。"}},{"pos":"N-COUNT 可数名词","cn":"新发行的影片;新片;新碟;发行物","en":"A new release is a new CD, video, or film that has just become available for people to buy or see.","ex":{"en":"Which of the new releases do you think are really good?","cn":"在这些新片中你觉得哪些真的不错？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(影片的)上映，公映；（录像带的）发行","en":"If a film or video is on release or on general release, it is available for people to see in public cinemas or for people to buy.","ex":{"en":"The video has sold three million copies in its first three weeks on release.","cn":"影碟推出的前3周就卖出了300万张。"}}]},"examples":[{"en":"Firefighters took two hours to release the driver from the wreckage.","cn":"消防队员花了两个小时将司机从汽车残骸中救出来。"},{"en":"She burst into tears, releasing all her pent-up emotions.","cn":"她放声大哭，发泄出全部郁积起来的情感。"}]},"resourcefulness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"intelligent in a practical way, and able to use your intelligence to get advantages for yourself","cn":""},{"en":"a shrewd person is good at deciding what people, situations etc are really like, so that it is difficult to deceive them - use this especially about people who are successful in business","cn":""}]},"examples":[{"en":"a woman who is energetic and resourceful","cn":"","src":"ld"}],"media":{"uk":"media/uk/resourcefulness__gb_1.mp3","us":"media/us/resourcefulness__us_1.mp3"},"oxford":{"phon":"rɪˈsɔːsflnəs","pos":"noun","senses":[{"en":"the quality of being good at finding ways of doing things and solving problems, etc.","cn":"机敏的；足智多谋的；随机应变的","ex":{"en":"situations that will test your resourcefulness to the utmost","cn":"最大限度考验你的足智多谋的情况"}}]}},"resident":{"media":{"uk":"media/uk/resident__gb_1.mp3","us":"media/us/resident__us_1.mp3"},"oxford":{"phon":"ˈrezɪdənt","pos":"noun","senses":[{"en":"a person who lives in a particular place or who has their home there","cn":"居民；住户","ex":{"en":"a resident of the United States","cn":"美国的居民"}},{"en":"a person who is staying in a hotel","cn":"（旅馆的）住宿者，旅客，房客","lab":"formal","ex":{"en":"The hotel restaurant is open to non-residents.","cn":"旅店的餐馆对外开放。"}},{"en":"a doctor working in a hospital in the US who is receiving special advanced training","cn":"（美国的）高级专科住院实习医生"},{"en":"living in a particular place","cn":"（在某地）居住的","ex":{"en":"the town’s resident population (= not tourists or visitors)","cn":"镇上的居民"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"居民;住户;居住者","en":"The residents of a house or area are the people who live there.","ex":{"en":"The Archbishop called upon the government to build more low cost homes for local residents","cn":"大主教呼吁政府为当地居民建造更多低成本的住宅。"}},{"pos":"ADJ 形容词","cn":"（在某地）居住的，居留的","en":"Someone who is resident in a country or a town lives there.","ex":{"en":"He moved to Belgium in 1990 to live with his son, who had been resident in Brussels since 1967.","cn":"他于1990年搬到比利时和儿子一起住。他儿子自1967年起就住在布鲁塞尔。"}},{"pos":"ADJ 形容词","cn":"(医生或教师)住在任职地的","en":"A resident doctor or teacher lives in the place where he or she works.","ex":{"en":"The morning after your arrival, you meet with the resident physician for a private consultation.","cn":"到达后的第二天早上，你就去见住院医生，进行私人问诊。"}},{"pos":"N-COUNT 可数名词","cn":"实习医生","en":"A resident or a resident doctor is a doctor who is receiving a period of specialized training in a hospital after leaving university."},{"pos":"ADJ 形容词","cn":"特聘的;专聘的","en":"If an institution has a resident specialist, that specialist works for the institution.","ex":{"en":"Having begun her career at Gray's Pottery, she stayed there as resident designer for seven years.","cn":"在格雷陶器场开始自己的职业生涯后，她在那里做了7年的特聘设计师。"}}]},"examples":[{"en":"Tom's our resident expert (= our own expert) on foreign movies.","cn":"汤姆是我们的外国电影常驻专家。"},{"en":"There were confrontations between local residents and the police.","cn":"当地居民和警察之间有过冲突。"}]},"remote":{"media":{"uk":"media/uk/remote__gb_1.mp3","us":"media/us/remote__us_1.mp3"},"oxford":{"phon":"rɪˈməʊt","pos":"adjective","senses":[{"en":"far away from places where other people live","cn":"偏远的；偏僻的","sc":"place","ex":{"en":"a remote village/island/location/region","cn":"偏远的村庄／岛／地点／地区"}},{"en":"far away in time","cn":"遥远的；久远的","g":"[only before noun]","sc":"time","ex":{"en":"in the remote past/future","cn":"在遥远的过去／将来"}},{"en":"not closely related","cn":"关系较远的；远亲的","g":"[only before noun]","sc":"relatives","ex":{"en":"a remote cousin","cn":"远房表亲"}},{"en":"used to describe working away from a usual place, using communications technology","cn":"用于描述使用通信技术在远离平常地点的地方工作","sc":"working","ex":{"en":"Remote working has become the norm for many organizations.","cn":"远程工作已成为许多组织的常态。"}},{"en":"that you can connect to from far away, using an electronic link","cn":"远程的；远程连接的","sc":"computer/system","ex":{"en":"a remote terminal/database/server","cn":"远程终端／数据库／服务器"}},{"en":"very different from something","cn":"相差很大的；极不相同的","sc":"different","ex":{"en":"His theories are somewhat remote from reality.","cn":"他的理论有点儿脱离现实。"}},{"en":"not very friendly or interested in other people","cn":"不很友好的；冷漠的","sc":"not friendly","ex":{"en":"When he spoke, his voice was cold and remote.","cn":"他说话的时候，声音冰冷而遥远。"}},{"en":"not very great","cn":"细微的；微小的","sc":"very small","ex":{"en":"There is still a remote chance that they will find her alive.","cn":"他们仍然有一线希望能把她活着找到。"}},{"en":"a remote control (= a device that allows you to operate a television, etc. from a distance)","cn":"遥控器","lab":"informal","ex":{"en":"The remote's not working.","cn":"遥控器不工作。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"偏僻的;遥远的;边远的","en":"Remote areas are far away from cities and places where most people live, and are therefore difficult to get to.","ex":{"en":"Landslides have cut off many villages in remote areas.","cn":"滑坡使边远地区的许多村庄与外界隔绝。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(过去或未来)遥远的，久远的","en":"The remote past or remote future is a time that is many years distant from the present.","ex":{"en":"Slabs of rock had slipped sideways in the remote past, and formed this hole.","cn":"在久远的过去，岩石板滑落到周边，从而形成了这个洞。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"关系不紧密的;关系疏远的;相距甚远的","en":"If something is remote from a particular subject or area of experience, it is not relevant to it because it is very different.","ex":{"en":"This government depends on the wishes of a few who are remote from the people","cn":"这个政府按照远离民众的少数人的意愿行事。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(可能性或机会)渺茫的，微乎其微的","en":"If you say that there is a remote possibility or chance that something will happen, you are emphasizing that there is only a very small chance that it will happen.","ex":{"en":"I use a sunscreen whenever there is even a remote possibility that I will be in the sun","cn":"不论何时只要有一点可能暴露在阳光下，我就会用防晒霜。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷漠的;冷淡的;与人疏远的;清高的","en":"If you describe someone as remote, you mean that they behave as if they do not want to be friendly or closely involved with other people.","ex":{"en":"She looked so beautiful, and at the same time so remote.","cn":"她相貌如此美丽，同时又如此清高不群。"}}]},"examples":[{"en":"There is still a remote chance that they will find her alive.","cn":"他们仍然有一线希望能把她活着找到。"},{"en":"The farmhouse is remote from any other buildings.","cn":"这家农舍附近没有别的房屋。"}]},"representing":{"lemma":"represent","media":{"uk":"media/uk/represent__gb_1.mp3","us":"media/us/represent__us_1.mp3"}},"resolve":{"media":{"uk":"media/uk/resolve__gb_1.mp3","us":"media/us/resolve__us_1.mp3"},"oxford":{"phon":"rɪˈzɒlv","pos":"verb","senses":[{"en":"to find an acceptable solution to a problem or difficulty","cn":"解决（问题或困难）","g":"[transitive]","ex":{"en":"to resolve an issue/a dispute/a conflict/a crisis","cn":"解决问题／争端／冲突／危机"}},{"en":"to make a definite decision to do something","cn":"决心；决定","g":"[transitive, intransitive]","ex":{"en":"He resolved not to tell her the truth.","cn":"他决定不告诉她真相。"}},{"en":"to reach a decision by means of a formal vote","cn":"（经正式投票）作出决定，作出决议；表决","g":"[transitive]","ex":{"en":"It was resolved that the matter be referred to a higher authority.","cn":"经过表决，决定把这件事提交给上级主管部门。"}},{"en":"a determined desire to achieve something","cn":"决心；坚定的信念","ex":{"en":"The difficulties in her way merely strengthened her resolve.","cn":"她所遇到的困难只是让她更加坚定。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"解决","en":"To resolve a problem, argument, or difficulty means to find a solution to it.","ex":{"en":"We must find a way to resolve these problems before it's too late","cn":"我们必须及时找到解决这些问题的方法。"}},{"pos":"VERB 动词","cn":"决定;下定决心","en":"If you resolve to do something, you make a firm decision to do it.","ex":{"en":"She resolved to report the matter to the hospital's nursing manager","cn":"她决定把这件事汇报给医院的护士长。"}},{"pos":"N-VAR 可变名词","cn":"决心;决意","en":"Resolve is determination to do what you have decided to do.","ex":{"en":"This will strengthen the American public's resolve to go to war.","cn":"这会坚定美国公众诉诸战争的决心。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）分解为","en":"If you resolve something into a clearer form, or if it resolves into a clearer form, its shape or the different parts it contains become clear.","ex":{"en":"...like a musician resolving a confused mass of sound into melodic or harmonic order","cn":"就像音乐家那样将混乱嘈杂的声音变成优美和谐的旋律"}}]},"examples":[{"en":"They resolved that the matter be referred to a higher authority.","cn":"他们经过表决，决定把这件事提交给上级主管部门。"},{"en":"The Supreme Council resolved to resume control over the national press.","cn":"最高委员会决定重新接管对国家新闻机构的控制。"}]},"readership":{"oxford":{"phon":"ˈriːdəʃɪp","pos":"noun","senses":[{"en":"the number or type of people who read a particular newspaper, magazine, etc.","cn":"（统称某报刊等的）读者","g":"[usually singular]","ex":{"en":"a readership of around 10 000","cn":"1 万左右的读者人数"}},{"en":"the position of a Reader at a university","cn":"（英国大学）准教授职位","lab":"British English","ex":{"en":"She currently holds a Readership in Geography at the University of Hull.","cn":"她目前拥有赫尔大学地理学的读者资格。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"读者（人数）","en":"The readership of a book, newspaper, or magazine is the number or type of people who read it.","ex":{"en":"Its readership has grown to over 15,000 subscribers","cn":"它的订阅人数上升到了15,000多人。"}},{"pos":"N-COUNT 可数名词","cn":"（英国大学的）高级讲师职位","en":"In Britain, a readership is the post of a reader at a university."}]},"media":{"uk":"media/uk/readership__gb_1.mp3","us":"media/us/readership__us_1.mp3"},"examples":[{"en":"In its new format, the magazine hopes to attract a much wider readership.","cn":"这份杂志希望以新的版式吸引更多的读者。"},{"en":"a readership of around 10 000 * 1","cn":"万左右的读者人数"}]},"refining":{"lemma":"refine"},"relentless":{"oxford":{"phon":"rɪˈlentləs","pos":"adjective","senses":[{"en":"not stopping; not getting less strong","cn":"不停的；持续强烈的；不减弱的","ex":{"en":"her relentless pursuit of perfection","cn":"她对完美的不懈追求"}},{"en":"refusing to give up or be less strict or severe","cn":"不放弃的；严格的；苛刻的；无情的","ex":{"en":"a relentless enemy","cn":"残酷的敌人"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不停的;不懈的;不间断的；未减轻的","en":"Something bad that is relentless never stops or never becomes less intense.","ex":{"en":"The pressure now was relentless.","cn":"压力现在没完没了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚韧的;不屈不挠的","en":"Someone who is relentless is determined to do something and refuses to give up, even if what they are doing is unpleasant or cruel.","ex":{"en":"Relentless in his pursuit of quality, his technical ability was remarkable","cn":"对质量孜孜不倦的追求使他的技能出类拔萃。"}}]},"media":{"uk":"media/uk/relentless__gb_1.mp3","us":"media/us/relentless__us_1.mp3"},"examples":[{"en":"The sun was relentless.","cn":"太阳还是那么热。"},{"en":"her relentless pursuit of perfection","cn":"她对完美的不懈追求"}]},"rest":{"media":{"img":["media/pic/musicalnotation.jpg","media/thumb/rest.jpg"],"uk":"media/uk/rest__gb_1.mp3","us":"media/us/rest__us_1.mp3"},"oxford":{"phon":"rest","pos":"noun","senses":[{"en":"the part of something that remains","cn":"剩余部分；残留；其余","g":"[singular]","sc":"remaining part/people/things","ex":{"en":"Take what you want and throw the rest away.","cn":"把你想要的拿走，其余的丢掉。"}},{"en":"the people or things that remain; the others","cn":"其余的人；其他事物；其他","g":"[plural]","sc":"remaining part/people/things","ex":{"en":"The first question was difficult, but the rest were pretty easy.","cn":"第一个问题很难，但其余的都相当简单。"}},{"en":"a period of relaxing, sleeping or doing nothing after a period of activity","cn":"休息时间；睡眠时间","g":"[countable, uncountable]","lab":"especially North American English","sc":"period of relaxing","ex":{"en":"I had a good night's rest.","cn":"我睡了一宿好觉。"}},{"en":"an object that is used to support or hold something","cn":"支撑物；支架；基座；托","g":"[countable]","sc":"support","ex":{"en":"an armrest (= for example on a seat or chair)","cn":"座椅扶手"}},{"en":"a period of silence between notes; a sign that shows a rest between notes","cn":"休止；休止符","g":"[countable, uncountable]","sc":"in music"},{"en":"to relax, sleep or do nothing after a period of activity or illness; to not use a part of your body for some time","cn":"休息；放松","g":"[intransitive, transitive]","lab":"figurative","sc":"relax","ex":{"en":"The doctor told me to rest.","cn":"医生叫我休息。"},"pos":"verb"},{"en":"to support something by putting it on or against something; to be supported in this way","cn":"（被）支撑；（使）倚靠；托","g":"[transitive, intransitive]","sc":"support","ex":{"en":"Rest your head on my shoulder.","cn":"把头靠在我肩上。"},"pos":"verb"},{"en":"if you let a matter rest, you stop discussing it or dealing with it","cn":"被搁置；中止","g":"[intransitive]","sc":"be left","ex":{"en":"The matter cannot rest there—I intend to sue.","cn":"这件事不能就此了结，我打算提出诉讼。"},"pos":"verb"},{"en":"to be buried. People say ‘rest’ to avoid saying ‘be buried’","cn":"（委婉说法，与 be buried 同义）安息，长眠","g":"[intransitive]","sc":"be buried","ex":{"en":"She rests beside her husband in the local cemetery.","cn":"在当地的墓地里，她长眠在她丈夫的墓旁。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"QUANT 数量词","cn":"剩余部分","en":"The rest is used to refer to all the parts of something or all the things in a group that remain or that you have not already mentioned.","ex":{"en":"It was an experience I will treasure for the rest of my life","cn":"我的余生都会珍惜这次经历。"}},{"pos":"PHRASE 短语","cn":"诸如此类;如此等等;不一而足","en":"You can add and the rest or all the rest of it to the end of a statement or list when you want to refer in a vague way to other things that are associated with the ones you have already mentioned.","ex":{"en":"...a man with nice clothes, a Range Rover and the rest","cn":"一个穿着体面、开着路虎如此等等的男人"}},{"pos":"VERB 动词","cn":"休息;歇息;放松(身体)","en":"If you rest or if you rest your body, you do not do anything active for a time.","ex":{"en":"He's tired and exhausted, and has been advised to rest for two weeks","cn":"他精疲力竭，被建议休息两周。"}},{"pos":"N-VAR 可变名词","cn":"休息;歇息","en":"If you get some rest or have a rest, you do not do anything active for a time.","ex":{"en":"'You're worn out, Laura,' he said. 'Go home and get some rest.'","cn":"“你太累了，劳拉，”他说，“回家休息一下吧。”"}},{"pos":"VERB 动词","cn":"依赖;取决于;以…为基础","en":"If something such as a theory or someone's success rests on a particular thing, it depends on that thing.","ex":{"en":"Such a view rests on a number of incorrect assumptions","cn":"这样的观点建立在很多不正确的假设之上。"}},{"pos":"VERB 动词","cn":"（权力、责任、决定权）在于，属于","en":"If authority, a responsibility, or a decision rests with you, you have that authority or responsibility, or you are the one who will make that decision.","ex":{"en":"The judge said that whether Miss Bergman wishes to admit it or not, the responsibility rests with her. ","cn":"法官说不管伯格曼小姐愿不愿意承认，这件事的责任都在她。"}},{"pos":"VERB 动词","cn":"放置;安置","en":"If you rest something somewhere, you put it there so that its weight is supported.","ex":{"en":"He rested his arms on the back of the chair","cn":"他把手臂放在椅背上。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）倚靠;（被）支撑","en":"If something is resting somewhere, or if you are resting it there, it is in a position where its weight is supported.","ex":{"en":"His head was resting on her shoulder","cn":"他的头靠在她的肩上。"}},{"pos":"VERB 动词","cn":"靠;倚;躺","en":"If you rest on or against someone or something, you lean on them so that they support the weight of your body.","ex":{"en":"He rested on his pickaxe for a while.","cn":"他在尖嘴镐上靠了一会儿。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指头或四肢的）支撑物;撑架;托架","en":"A rest is an object that is used to support something, especially your head, arms, or feet.","ex":{"en":"When you are sitting, keep your elbow on the arm rest.","cn":"坐立时，把胳膊肘靠在扶手上。"}},{"pos":"VERB 动词","cn":"(目光)停留，凝视","en":"If your eyes rest on a particular person or object, you look directly at them, rather than somewhere else.","ex":{"en":"As she spoke, her eyes rested on her husband's face.","cn":"她说话的时候，眼睛凝视着丈夫的脸。"}},{"pos":"PHRASE 短语","cn":"停止移动","en":"When an object that has been moving comes to rest, it finally stops.","ex":{"en":"The plane had plowed a path through a patch of forest before coming to rest in a field.","cn":"飞机猛冲过一片森林，在一片田野中停了下来。"}},{"pos":"PHRASE 短语","cn":"放心;高枕无忧;不担心","en":"If you say that someone can rest easy, you mean that they don't need to worry about a particular situation.","ex":{"en":"How can any woman rest easy now, knowing her breast cancer may be misdiagnosed?","cn":"知道自己的乳腺癌可能被误诊，哪个女人能不担心呢？"}},{"pos":"PHRASE短语","cn":"暂停;暂时不做","en":"If someone tells you to give something a rest, they want you to stop doing it because it annoys them or because they think it is harming you.","ex":{"en":"Give it a rest, will you? We're trying to get some sleep","cn":"你安静一下，好吗？我们想睡一会儿。"}},{"pos":"PHRASE 短语","cn":"安葬","en":"If you say that someone who has died is laid to rest, you mean that they are buried.","ex":{"en":"His dying wish was to be laid to rest at the church near his Somerset home.","cn":"他的遗愿是把他安葬在家乡萨默塞特郡附近的教堂里。"}},{"pos":"PHRASE 短语","cn":"消除（恐惧）；平息（谣言）","en":"If you lay something such as fears or rumours to rest or if you put them to rest, you succeed in proving that they are not true.","ex":{"en":"His speech should lay those fears to rest","cn":"他的演说应当会消除那些忧虑。"}},{"pos":"PHRASE 短语","cn":"(尤指长时间的谈论后）停止讨论(某个话题)","en":"If someone refuses to let a subject rest, they refuse to stop talking about it, especially after they have been talking about it for a long time.","ex":{"en":"I am not prepared to let this matter rest","cn":"我不准备就此罢休。"}},{"pos":"PHRASE 短语","cn":"让…安心;使…放心","en":"To put someone's mind at rest or set their mind at rest means to tell them something that stops them worrying.","ex":{"en":"She was quick to put his mind at rest. 'Mrs Barrett will be delighted to have your brothers back,' she said","cn":"她很快就让他放心了。“巴雷特太太会很高兴让你的兄弟们回来的，”她说道。"}},{"pos":"","cn":"","en":"rest assured→see: ; to rest on your laurels→see: ; to rest in peace→see: ;"}]},"examples":[{"en":"The book has some interesting passages about the author's childhood. For the rest, it is extremely dull.","cn":"这本书中关于作者童年的一些章节倒还有意思。除此之外，便无聊至极。"},{"en":"‘It cost 250 pounds … ’ ‘And the rest, and the rest!’ “","cn":"这要花 250 英镑 … ” “不止这些，不止这些！”"}]},"replay":{"oxford":{"phon":"ˈriːpleɪ","pos":"noun","senses":[{"en":"a game that is played again because neither side won in the previous game","cn":"（由于未决出胜负而进行的）重赛","lab":"sport","ex":{"en":"United won the replay 3–1.","cn":"重赛时曼联以 3-1 获胜。"}},{"en":"the playing again of a short section of a film, tape, etc. especially to look at or listen to something more carefully","cn":"（录像、录音等的）重放，重演，重播","ex":{"en":"The replay showed that the ball was over the line.","cn":"视频回放证明球过线了。"}},{"en":"something that is repeated or happens in exactly the same way as it did before","cn":"重演的事物；重复出现的事物","lab":"informal","ex":{"en":"This election will not be a replay of the last one.","cn":"这次选举将不会是上一次的重演。"}},{"en":"to play a sports game again because neither team won the first game","cn":"（因胜负未决）重赛","g":"[usually passive]","ex":{"en":"The game will now have to be replayed on Tuesday.","cn":"比赛现在必须在周二重赛。"},"pos":"verb"},{"en":"to play again a video, music recording or video game","cn":"重放；重播","lab":"figurative","ex":{"en":"The police replayed footage of the accident over and over again.","cn":"警察一遍又一遍地重放事故的片段。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"重新比赛","en":"If a match between two sports teams is replayed, the two teams play it again, because neither team won the first time, or because the match was stopped because of bad weather.","ex":{"en":"Drawn matches were replayed three or four days later.","cn":"没有分出胜负的比赛在三四天后重赛。"}},{"pos":"VERB 动词","cn":"(影片或磁带的)重播，重放","en":"If you replay something that you have recorded on film or tape, you play it again in order to watch it or listen to it.","ex":{"en":"He stopped the machine and replayed the message.","cn":"他停下机器，重新播放了一遍信息。"}},{"pos":"VERB 动词","cn":"(反复在脑海里)重放;不断想起","en":"If you replay an event in your mind, you think about it again and again.","ex":{"en":"She spends her nights lying in bed, replaying the fire in her mind.","cn":"她好多个晚上躺在床上，不断想起火灾场面。"}}]},"media":{"uk":"media/uk/replay__gb_1.mp3","us":"media/us/replay__us_1.mp3"},"examples":[{"en":"We watched a replay of the wedding on DVD.","cn":"我们看了婚礼 DVD 录像的重放。"},{"en":"The police replayed footage of the accident over and over again.","cn":"警察一遍又一遍地重放事故的片段。"}]},"receptionist":{"media":{"uk":"media/uk/receptionist__gb_1.mp3","us":"media/us/receptionist__us_1.mp3"},"oxford":{"phon":"rɪˈsepʃənɪst","pos":"noun","senses":[{"en":"a person whose job is to deal with people arriving at or phoning a hotel, an office building, a doctor’s surgery, etc.","cn":"接待员"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（宾馆前台的）接待员","en":"In a hotel, the receptionist is the person whose job is to book rooms for people and answer their questions."},{"pos":"N-COUNT 可数名词","cn":"（办公室或医院的）接待员，咨询处工作人员","en":"In an office or hospital, the receptionist is the person whose job is to answer the telephone, arrange appointments, and deal with people when they first arrive."}]}},"reject":{"media":{"uk":"media/uk/reject__gb_1.mp3","us":"media/us/reject__us_1.mp3"},"oxford":{"phon":"rɪˈdʒekt","pos":"verb","senses":[{"en":"to refuse to accept or consider something","cn":"拒绝接受；不予考虑","sc":"argument/idea/plan","ex":{"en":"to reject an argument/a hypothesis/a notion/a plan","cn":"拒绝接受论点／假设／概念／计划"}},{"en":"to refuse to accept somebody for a job, position, etc.","cn":"拒收；不录用；拒绝接纳","sc":"somebody for job","ex":{"en":"Please reject the following candidates…","cn":"请排除以下候选人…"}},{"en":"to decide not to use, sell, publish, etc. something because its quality is not good enough","cn":"（因质量差）不用，不出售，不出版","sc":"not use/publish","ex":{"en":"Imperfect articles are rejected by our quality control.","cn":"我们严把质量关，不完美的物件都被退回。"}},{"en":"to not accept a new organ after a transplant operation, by producing substances that attack the organ","cn":"排斥（移植的器官）","sc":"new organ","ex":{"en":"Her body has already rejected two kidneys.","cn":"她的身体已经对两个肾脏发生过排斥反应。"}},{"en":"to fail to give a person or an animal enough love or care","cn":"不够关心；慢待","sc":"not love","ex":{"en":"The lioness rejected the smallest cub, which died.","cn":"母狮不理会最小的幼狮，任由它死去。"}},{"en":"something that cannot be used or sold because there is something wrong with it","cn":"废品；次品","sc":"something that cannot be used","pos":"noun"},{"en":"a person who has not been accepted as a member of a team, society, etc.","cn":"不合格者；被剔除者；被拒收者","sc":"person","ex":{"en":"one of society’s rejects","cn":"一名社会弃儿"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"拒绝考虑;不接受;不同意","en":"If you reject something such as a proposal, a request, or an offer, you do not accept it or you do not agree to it.","ex":{"en":"The British government is expected to reject the idea of state subsidy for a new high speed railway","cn":"预计英国政府不会考虑为修建一条新的高速铁路提供国家补贴的设想。"}},{"pos":"VERB 动词","cn":"摈弃，抛弃，不接受(信仰或政治制度)","en":"If you reject a belief or a political system, you refuse to believe in it or to live by its rules.","ex":{"en":"...the children of Eastern European immigrants who had rejected their parents' political and religious beliefs.","cn":"抛弃了父母一代政治和宗教信仰的东欧移民子女"}},{"pos":"VERB 动词","cn":"不录用;不录取","en":"If someone is rejected for a job or course of study, it is not offered to them.","ex":{"en":"One of my most able students was rejected by another university.","cn":"我的一个最有能力的学生申请另一所大学落选了。"}},{"pos":"VERB 动词","cn":"冷漠对待;拒绝…的爱意","en":"If someone rejects another person who expects affection from them, they are cold and unfriendly towards them.","ex":{"en":"You make friends with people and then make unreasonable demands so that they reject you.","cn":"你和别人交朋友，然后向人家提出无理要求，结果被人家拒绝。"}},{"pos":"VERB 动词","cn":"排斥(移植器官)；对…产生排斥反应","en":"If a person's body rejects something such as a new heart that has been transplanted into it, it tries to attack and destroy it.","ex":{"en":"It was feared his body was rejecting a kidney he received in a transplant four years ago.","cn":"令人担心的是，他的身体可能对4年前移植的肾产生了排斥反应。"}},{"pos":"VERB 动词","cn":"(投币设备)拒绝接受(硬币)","en":"If a machine rejects a coin that you put in it, the coin comes out and the machine does not work."},{"pos":"N-COUNT 可数名词","cn":"残次品;等外品","en":"A reject is a product that has not been accepted for use or sale, because there is something wrong with it."}]},"examples":[{"en":"to reject an argument/a claim/a decision/an offer/a suggestion","cn":"拒绝接受一个论点/一项要求/一个决定/一项提议/一个建议"},{"en":"When her husband left home she felt rejected and useless.","cn":"丈夫离家后，她觉得遭到了抛弃，且认为自己一无是处。"}]},"renovate":{"media":{"uk":"media/uk/renovate__gb_1.mp3","us":"media/us/renovate__us_1.mp3"},"oxford":{"phon":"ˈrenəveɪt","pos":"verb","senses":[{"en":"to repair and paint an old building, a piece of furniture, etc. so that it is in good condition again","cn":"修复；翻新；重新粉刷","lab":"British English","ex":{"en":"the newly renovated church","cn":"新近修复的教堂"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"修复;改造;翻新","en":"If someone renovates an old building, they repair and improve it and get it back into good condition.","ex":{"en":"The couple spent thousands renovating the house","cn":"这对夫妇花了几千元来翻新房子。"}}]},"examples":[{"en":"There will be extensive renovations to the hospital.","cn":"这所医院将进行大规模的翻修。"},{"en":"buildings in need of renovation","cn":"需要重新装修的大楼"}]},"remotely":{"media":{"uk":"media/uk/remotely__gb_1.mp3","us":"media/us/remotely__us_1.mp3"},"oxford":{"phon":"rɪˈməʊtli","pos":"adverb","senses":[{"en":"to a very slight degree","cn":"微弱地；细微地；程度很低地","ex":{"en":"It wasn't even remotely funny (= it wasn't at all funny).","cn":"这一点也不好笑。"}},{"en":"away from the place where a person usually works or worked in the past, using communications technology","cn":"远离一个人通常工作或过去工作的地方，使用通信技术","ex":{"en":"Many office workers began to work remotely during the pandemic.","cn":"疫情期间，不少上班族开始远程办公。"}},{"en":"from a distance","cn":"远程地","ex":{"en":"remotely operated","cn":"远程操作的"}},{"en":"far away from places where other people live","cn":"在偏僻地方","ex":{"en":"The church is remotely situated on the north coast of the island.","cn":"教堂位于这个岛偏僻的北部海岸。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"(用于否定句)丝毫，根本","en":"You use remotely with a negative statement to emphasize the statement.","ex":{"en":"We had never seen anything remotely like it before","cn":"我们以前从来没有见过任何类似的事情。"}},{"pos":"ADV-GRADED 副词","cn":"遥远地;偏远地","en":"If someone or something is remotely placed or situated, they are a long way from other people or places.","ex":{"en":"...the remotely situated, five bedroom house.","cn":"地处边远地段的5居室住宅"}}]},"examples":[{"en":"The church is remotely situated on the north coast of the island.","cn":"教堂位于这个岛偏僻的北部海岸。"},{"en":"The two incidents were only remotely connected.","cn":"两次事件之间无甚关联。"}]},"recipe":{"oxford":{"phon":"ˈresəpi","pos":"noun","senses":[{"en":"a set of instructions that tells you how to cook something and the ingredients (= items of food) you need for it","cn":"烹饪法；食谱","lab":"British English","ex":{"en":"a recipe for chicken soup","cn":"鸡汤的做法"}},{"en":"a method or an idea that seems likely to have a particular result","cn":"方法；秘诀；诀窍","ex":{"en":"His plans are a recipe for disaster.","cn":"他的计划后患无穷。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"烹饪配方；食谱","en":"A recipe is a list of ingredients and a set of instructions that tell you how to cook something.","ex":{"en":"...a traditional recipe for oatmeal biscuits.","cn":"燕麦饼干的传统制作配方"}},{"pos":"N-SING 单数名词","cn":"原因","en":"If you say that something is a recipe for a particular situation, you mean that it is likely to result in that situation.","ex":{"en":"Large-scale inflation is a recipe for disaster.","cn":"大规模的通货膨胀会造成灾难。"}}]},"media":{"uk":"media/uk/recipe__gb_1.mp3","us":"media/us/recipe__us_1.mp3"},"examples":[{"en":"What's her recipe for success?","cn":"她成功的秘诀是什么？"},{"en":"His plans are a recipe for disaster.","cn":"他的计划后患无穷。"}]},"restricting":{"lemma":"restrict","media":{"uk":"media/uk/restrict__gb_1.mp3","us":"media/us/restrict__us_1.mp3"}},"reciprocal":{"media":{"uk":"media/uk/reciprocal__gb_1.mp3","us":"media/us/reciprocal__us_1.mp3"},"oxford":{"phon":"rɪˈsɪprəkl","pos":"adjective","senses":[{"en":"involving two people or groups who agree to help each other or behave in the same way to each other","cn":"互惠的；相应的","ex":{"en":"The two colleges have a reciprocal arrangement whereby students from one college can attend classes at the other.","cn":"两所学院有一项互惠协定，允许学生跨院选课。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"互相的；相应的；互惠的","en":"A reciprocal action or agreement involves two people or groups who do the same thing to each other or agree to help each another in a similar way.","ex":{"en":"They expected a reciprocal gesture before more hostages could be freed","cn":"在更多人质获得自由之前他们期望看到对方也有相应的表示。"}}]},"examples":[{"en":"The two colleges have a reciprocal arrangement whereby students from one college can attend classes at the other.","cn":"两所学院有一项互惠协定，允许学生在院际间选课。"},{"en":"He spoke of the necessity for a reciprocal relationship that would be useful for all sides.","cn":"他谈及需要建立对各方都有益的互惠关系。"}]},"reveal":{"media":{"uk":"media/uk/reveal__gb_1.mp3","us":"media/us/reveal__us_1.mp3"},"oxford":{"phon":"rɪˈviːl","pos":"verb","senses":[{"en":"to make something known to somebody","cn":"揭示；显示；透露","ex":{"en":"to reveal a secret","cn":"泄露一条秘密"}},{"en":"to show something that previously could not be seen","cn":"显出；露出；展示","ex":{"en":"He laughed, revealing a line of white teeth.","cn":"他笑了起来，露出一排洁白的牙齿。"}},{"en":"the moment when a previously secret piece of information is made known, such as the winner of a prize, or the solution to a mystery in a film or TV drama","cn":"谜底揭晓的时刻；真相大白的时候","ex":{"en":"The big reveal at the end of the movie answers all questions.","cn":"电影结尾时真相大白，所有谜团都解开了。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"显示;表明;透露","en":"To reveal something means to make people aware of it.","ex":{"en":"She has refused to reveal the whereabouts of her daughter","cn":"她不肯透露她女儿的行踪。"}},{"pos":"VERB 动词","cn":"揭露;展示;使显露","en":"If you reveal something that has been out of sight, you uncover it so that people can see it.","ex":{"en":"A grey carpet was removed to reveal the original pine floor.","cn":"一块灰色的地毯被揭开，露出了原来的松木地板。"}}]},"examples":[{"en":"The report reveals (that) the company made a loss of £20 million last year.","cn":"报告显示，公司去年亏损 2 000 万英镑。"},{"en":"Salted peanuts were recently revealed to be the nation's favourite snack.","cn":"最近发现，咸味花生是该国最受人喜爱的小吃。"}]},"relationship":{"media":{"uk":"media/uk/relationship__gb_1.mp3","us":"media/us/relationship__us_1.mp3"},"oxford":{"phon":"rɪˈleɪʃnʃɪp","pos":"noun","senses":[{"en":"the way in which two people, groups or countries behave towards each other or deal with each other","cn":"（人、团体、国家之间的）关系，联系","g":"[countable]","ex":{"en":"a personal/working relationship","cn":"父子／工作关系"}},{"en":"a loving and/or sexual friendship between two people","cn":"情爱关系；性爱关系","g":"[countable]","ex":{"en":"Their affair did not develop into a long-term relationship.","cn":"他们的暧昧关系未能发展成为持久的恋情。"}},{"en":"the way in which two or more things are connected","cn":"（事物之间的）关联，联系，关系","g":"[countable, uncountable]","ex":{"en":"The study demonstrated associations, but no causal relationship.","cn":"该研究证明了相关性，但没有因果关系。"}},{"en":"the way in which a person is related to somebody else in a family","cn":"血缘关系；姻亲关系","g":"[countable, uncountable]","ex":{"en":"They have a very healthy father-son relationship.","cn":"他们的父子关系很好。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(人、团体等之间的)关系，关联","en":"The relationship between two people or groups is the way in which they feel and behave towards each other.","ex":{"en":"...the friendly relationship between France and Britain","cn":"法国和英国之间的友好关系"}},{"pos":"N-COUNT 可数名词","cn":"恋爱关系；性关系；感情关系","en":"A relationship is a close friendship between two people, especially one involving romantic or sexual feelings.","ex":{"en":"We had been together for two years, but both of us felt the relationship wasn't really going anywhere.","cn":"我们在一起已经两年了，但我们双方都觉得这段感情不会有什么结果。"}},{"pos":"N-COUNT 可数名词","cn":"(事物之间的)关系，关联，联系","en":"The relationship between two things is the way in which they are connected.","ex":{"en":"There is a relationship between diet and cancer.","cn":"饮食结构和癌症之间有一定关联。"}}]},"examples":[{"en":"I'm not sure of the exact relationship between them — I think they're cousins.","cn":"我不太清楚他们之间的确切关系，我想他们是表亲吧。"},{"en":"The relationship between the police and the local community has improved.","cn":"警察和当地民众之间的关系已经得到改善。"}]},"reverence":{"media":{"uk":"media/uk/reverence__gb_1.mp3","us":"media/us/reverence__us_1.mp3"},"oxford":{"phon":"ˈrevərəns","pos":"noun","senses":[{"en":"a feeling of admiring and respecting somebody/something very much","cn":"尊敬；崇敬","ex":{"en":"The poem conveys his deep reverence for nature.","cn":"这首诗表达了他对大自然深深的崇敬之情。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"尊敬;崇敬;敬意","en":"Reverence for someone or something is a feeling of great respect for them.","ex":{"en":"...showing a deep reverence for their religion.","cn":"对他们的宗教表示了深深的敬意"}}]},"examples":[{"en":"The poem conveys his deep reverence for nature.","cn":"这首诗表达了他对大自然的深深崇敬之情。"},{"en":"reverence for tradition","cn":"对传统的尊重"}]},"remedies":{"lemma":"remedy"},"recordings":{"lemma":"record","media":{"uk":"media/uk/recording__gb_1.mp3","us":"media/us/recording__us_1.mp3"}},"regulatory":{"oxford":{"phon":"ˈreɡjələtəri","pos":"adjective","senses":[{"en":"having the power to control an area of business or industry and make sure that it is operating fairly","cn":"（对工商业）具有监管权的，监管的","ex":{"en":"regulatory bodies/authorities/agencies","cn":"监管部门／机构"}}]},"media":{"uk":"media/uk/regulatory__gb_1.mp3","us":"media/us/regulatory__us_1.mp3"},"examples":[{"en":"regulatory bodies/authorities/agencies","cn":"监管部门/机构"}]},"res":{"oxford":{"phon":"reɪ","pos":"prep.","senses":[{"en":"used at the beginning of a business letter, etc. to introduce the subject that it is about; used on an email that you are sending as a reply （","cn":"用于商业信函等开头介绍主题或回复电子邮件）关于，事由"}]},"media":{"uk":"media/uk/re__gb_1.mp3","us":"media/us/re__us_1.mp3"}},"reconnect":{"media":{"uk":"media/uk/reconnect__gb_1.mp3","us":"media/us/reconnect__us_1.mp3"},"oxford":{"phon":"ˌriːkəˈnekt","pos":"verb","senses":[{"en":"to connect something again; to connect to something again","cn":"再连接；再接合","ex":{"en":"I replaced the taps and reconnected the water supply.","cn":"我更换了水龙头，再次接通了自来水。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"重新接通;重新提供","en":"If a company reconnects your electricity, water, gas, or telephone after it has been stopped, they provide you with it once again.","ex":{"en":"They charge a £66.10 fee for reconnecting cut-off customers","cn":"他们向申请重新接通服务的用户收取66.10英镑的费用。"}}]},"examples":[{"en":"Once you have removed the virus it is safe to reconnect to the Internet.","cn":"病毒一消除，就可以安全地重新连接互联网。"},{"en":"I replaced the taps and reconnected the water supply.","cn":"我更换了水龙头，再次接通了自来水。"}]},"regarding":{"oxford":{"phon":"rɪˈɡɑːdɪŋ","pos":"preposition","senses":[{"en":"relating to somebody/something; about somebody/something","cn":"关于；至于","ex":{"en":"She has said nothing regarding your request.","cn":"关于你的要求，她什么也没说。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"关于;至于","en":"You can use regarding to indicate the subject that is being talked or written about.","ex":{"en":"He refused to divulge any information regarding the man's whereabouts.","cn":"关于那个人的行踪他拒绝透露任何信息。"}}]},"media":{"uk":"media/uk/regarding__gb_1.mp3","us":"media/us/regarding__us_1.mp3"},"examples":[{"en":"Call me if you have any problems regarding your work.","cn":"你如果还有什么工作方面的问题就给我打电话。"},{"en":"She has said nothing regarding your request.","cn":"关于你的要求，她什么也没说。"}],"base":"regard"},"reasonably":{"media":{"uk":"media/uk/reasonably__gb_1.mp3","us":"media/us/reasonably__us_1.mp3"},"oxford":{"phon":"ˈriːznəbli","pos":"adverb","senses":[{"en":"to a degree that is fairly good but not very good","cn":"尚可；过得去","ex":{"en":"The instructions are reasonably straightforward.","cn":"用法说明还算简单易懂。"}},{"en":"in a logical and sensible way","cn":"合情合理地；明智地；通情达理地","ex":{"en":"We tried to discuss the matter calmly and reasonably.","cn":"我们试图冷静且通情达理地来讨论这个问题。"}},{"en":"in a fair way","cn":"公平合理地；适度地","ex":{"en":"He couldn't reasonably be expected to pay back the loan all at once.","cn":"公平合理地讲，不可能指望他一下子归还全部借款。"}}]},"examples":[{"en":"He couldn't reasonably be expected to pay back the loan all at once.","cn":"公平合理地讲，不可能指望他一下子归还全部借款。"},{"en":"We tried to discuss the matter calmly and reasonably.","cn":"我们试图冷静且通情达理地来讨论这个问题。"}]},"remain":{"media":{"uk":"media/uk/remain__gb_1.mp3","us":"media/us/remain__us_1.mp3"},"oxford":{"phon":"rɪˈmeɪn","pos":"verb","senses":[{"en":"to continue to be something; to be still in the same state or condition","cn":"仍然是；保持不变","ex":{"en":"to remain silent","cn":"保持沉默"}},{"en":"to still be present after the other parts have been removed, used, etc.; to continue to exist","cn":"剩余；遗留；继续存在","g":"[intransitive]","ex":{"en":"Very little of the house remained after the fire.","cn":"火灾之后，这座房子所剩无几。"}},{"en":"to stay in the same place; to not leave","cn":"逗留；不离去","g":"[intransitive]","ex":{"en":"They remained in Mexico until June.","cn":"他们在墨西哥一直住到了六月。"}},{"en":"to still need to be done, said or dealt with","cn":"仍需去做（或说、处理）","g":"[intransitive]","ex":{"en":"It remains to be seen (= it will only be known later) whether you are right.","cn":"你对不对还有待证实。"}}]},"collins":{"senses":[{"pos":"V-LINK 连系动词","cn":"保持;继续;持续","en":"If someone or something remains in a particular state or condition, they stay in that state or condition and do not change.","ex":{"en":"The three men remained silent","cn":"这3个人保持着沉默。"}},{"pos":"VERB 动词","cn":"留在，停留于(某处)","en":"If you remain in a place, you stay there and do not move away.","ex":{"en":"He will have to remain in hospital for at least 10 days","cn":"他至少得在医院里呆10天。"}},{"pos":"VERB 动词","cn":"仍然存在;继续存在","en":"You can say that something remains when it still exists.","ex":{"en":"Many of the differences in everyday life remain","cn":"日常生活中的许多差异仍然存在。"}},{"pos":"V-LINK 连系动词","cn":"遗留;剩余","en":"If something remains to be done, it has not yet been done and still needs to be done.","ex":{"en":"Major questions remain to be answered about his work","cn":"关于他工作的许多重要问题仍然悬而未决。"}},{"pos":"N-PLURAL 复数名词","cn":"残余（物）;剩余（物）;遗迹","en":"The remains of something are the parts of it that are left after most of it has been taken away or destroyed.","ex":{"en":"They were tidying up the remains of their picnic.","cn":"他们正在收拾野餐后剩下的东西。"}},{"pos":"N-PLURAL 复数名词","cn":"遗体;残骸","en":"The remains of a person or animal are the parts of their body that are left after they have died, sometimes after they have been dead for a long time.","ex":{"en":"The unrecognizable remains of a man had been found","cn":"一具无法辨认的男性尸体被发现了。"}},{"pos":"N-PLURAL 复数名词","cn":"(历史)遗迹，残迹","en":"Historical remains are things that have been found from an earlier period of history, usually buried in the ground, for example parts of buildings and pieces of pottery.","ex":{"en":"There are Roman remains all around us.","cn":"我们周围都是古罗马的遗迹。"}},{"pos":"V-LINK 连系动词","cn":"（事实、问题等)仍然是(表示强调)","en":"You can use remain in expressions such as the fact remains that or the question remains whether to introduce and emphasize something that you want to talk about.","ex":{"en":"The fact remains that inflation is unacceptably high","cn":"事实是通货膨胀率仍高得离谱。"}},{"pos":"PHRASE 短语","cn":"需拭目以待;未见分晓","en":"If you say that it remains to be seen whether something will happen, you mean that nobody knows whether it will happen.","ex":{"en":"It remains to be seen whether her parliamentary colleagues will agree.","cn":"她的国会同僚是否同意，现在还无从知晓。"}}]},"examples":[{"en":"I feel sorry for her, but the fact remains (that) she lied to us.","cn":"我为她感到难过，可事实是她对我们撒了谎。"},{"en":"He will remain (as) manager of the club until the end of his contract.","cn":"他将继续担任俱乐部经理，直至合同期满。"}]},"rethink":{"media":{"uk":"media/uk/rethink__gb_1.mp3","us":"media/us/rethink__us_1.mp3"},"oxford":{"phon":"ˌriːˈθɪŋk","pos":"verb","senses":[{"en":"to think again about an idea, a course of action, etc., especially in order to change it","cn":"重新考虑","ex":{"en":"to rethink a plan","cn":"重新考虑一项计划"}},{"en":"an act of thinking again about an idea, a course of action, etc., especially in order to change it","cn":"重新考虑","ex":{"en":"to have a radical rethink of company policy","cn":"彻底反思公司政策"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"重新考虑;反思","en":"If you rethink something such as a problem, a plan, or a policy, you think about it again and change it.","ex":{"en":"Both major political parties are having to rethink their policies","cn":"两个主要政党都必须反思其政策。"}},{"pos":"N-SING 单数名词","cn":"重新考虑;反思","en":"If you have a rethink of a problem, a plan, or a policy, you think about it again and change it.","ex":{"en":"There must be a rethink of government policy towards this vulnerable group.","cn":"必须重新考虑政府对待这一弱势群体的政策。"}}]},"examples":[{"en":"a radical rethink of company policy","cn":"对公司政策的彻底反思"},{"en":"to rethink a plan","cn":"重新考虑一项计划"}]},"relaxed":{"media":{"uk":"media/uk/relaxed__gb_1.mp3","us":"media/us/relaxed__us_1.mp3"},"oxford":{"phon":"rɪˈlækst","pos":"adjective","senses":[{"en":"calm and not anxious or worried","cn":"放松的；冷静的；镇定的","ex":{"en":"He appeared relaxed and confident before the match.","cn":"比赛前，他显得镇定而自信。"}},{"en":"calm and informal","cn":"安静的；自在的","ex":{"en":"a family-run hotel with a relaxed atmosphere","cn":"家庭经营的旅店，气氛自由随便"}},{"en":"not caring too much about discipline or making people follow rules","cn":"不加以拘束的","ex":{"en":"I take a fairly relaxed attitude towards what the kids wear to school.","cn":"孩子穿什么上学，我觉得无所谓。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"放松的;松弛的;安心的;轻松的","en":"If you are relaxed, you are calm and not worried or tense.","ex":{"en":"As soon as I had made the final decision, I felt a lot more relaxed","cn":"我一作出最后的决定就感到轻松多了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方或情形)轻松的，舒适的，使人安心的","en":"If a place or situation is relaxed, it is calm and peaceful.","ex":{"en":"The atmosphere at lunch was relaxed.","cn":"午餐的气氛很轻松。"}}]},"examples":[{"en":"I take a fairly relaxed attitude towards what the kids wear to school.","cn":"孩子穿什么上学，我觉得无所谓。"},{"en":"a family-run hotel with a relaxed atmosphere","cn":"家庭经营的旅店，气氛自由随便"}],"base":"relax"},"retrospect":{"media":{"uk":"media/uk/retrospect__gb_1.mp3","us":"media/us/retrospect__us_1.mp3"},"oxford":{"phon":"ˈretrəspekt","pos":"noun","senses":[{"en":"thinking about a past event or situation, often with a different opinion of it from the one you had at the time","cn":"回顾；回想；追溯往事"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"回顾;回想","en":"When you consider something in retrospect, you think about it afterwards, and often have a different opinion about it from the one that you had at the time.","ex":{"en":"In retrospect, I wish that I had thought about alternative courses of action","cn":"回想起来，我真希望自己当时考虑过其他做法。"}}]},"examples":[{"en":"The decision seems extremely odd, in retrospect.","cn":"回想起来，这个决定显得极其荒谬。"},{"en":"In retrospect, I think that I was wrong.","cn":"回首往事，我觉得当时我错了。"}]},"reputation":{"media":{"uk":"media/uk/reputation__gb_1.mp3","us":"media/us/reputation__us_1.mp3"},"oxford":{"phon":"ˌrepjuˈteɪʃn","pos":"noun","senses":[{"en":"the opinion that people have about what somebody/something is like, based on what has happened in the past","cn":"名誉；名声","ex":{"en":"to have a good/bad reputation","cn":"有好／坏名声"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"名声;名望;声誉","en":"To have a reputation for something means to be known or remembered for it.","ex":{"en":"Alice Munro has a reputation for being a very depressing writer.","cn":"艾丽斯·芒罗以文风沉郁闻名。"}},{"pos":"N-COUNT 可数名词","cn":"好名誉;名望","en":"Something's or someone's reputation is the opinion that people have about how good they are. If they have a good reputation, people think they are good.","ex":{"en":"This college has a good academic reputation","cn":"这所大学有良好的学术声誉。"}},{"pos":"PHRASE 短语","cn":"听说;耳闻","en":"If you know someone by reputation, you have never met them but you have heard of their reputation.","ex":{"en":"She was by reputation a good organiser.","cn":"听说她的组织能力很强。"}}]},"examples":[{"en":"The weather in England is living up to its reputation (= is exactly as expected).","cn":"英国的天气完全就如人们所说的那样。"},{"en":"She soon acquired a reputation as a first-class cook.","cn":"她不久就获得了一级厨师的荣誉。"}]},"reduce":{"media":{"uk":"media/uk/reduce__gb_1.mp3","us":"media/us/reduce__us_1.mp3"},"oxford":{"phon":"rɪˈdjuːs","pos":"verb","senses":[{"en":"to make something less or smaller in size, quantity, price, etc.; to become less or smaller in size, quantity, etc.","cn":"减少，缩小（尺寸、数量、价格等）","g":"[transitive, intransitive]","ex":{"en":"Reduce speed now (= on a sign).","cn":"减速行驶。"}},{"en":"if you reduce a liquid or a liquid reduces, you boil it so that it becomes less in quantity","cn":"（使）蒸发","g":"[transitive, intransitive]"},{"en":"to lose weight by limiting the amount and type of food that you eat","cn":"减轻体重；节食","g":"[intransitive]","lab":"North American English, informal，，","ex":{"en":"a reducing plan","cn":"节食计划"}},{"en":"to add one or more electrons to a substance or to remove oxygen from a substance","cn":"使还原；去氧；脱氧","g":"[transitive]","lab":"chemistry"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"减少；减小；减轻","en":"If you reduce something, you make it smaller in size or amount, or less in degree.","ex":{"en":"It reduces the risks of heart disease","cn":"这降低了患心脏病的风险。"}},{"pos":"VERB 动词","cn":"使沦为，使陷入（不好的境地）","en":"If someone is reduced to a weaker or inferior state, they become weaker or inferior as a result of something that happens to them.","ex":{"en":"They were reduced to extreme poverty","cn":"他们陷入极端贫困的状态。"}},{"pos":"VERB 动词","cn":"迫使;使不得不（做）；使只得","en":"If you say that someone is reduced to doing something, you mean that they have to do it, although it is unpleasant or embarrassing.","ex":{"en":"He was reduced to begging for a living.","cn":"他不得不以乞讨为生。"}},{"pos":"VERB 动词","cn":"使变成;使简化为","en":"If something is changed to a different or less complicated form, you can say that it is reduced to that form.","ex":{"en":"All the buildings in the town have been reduced to rubble","cn":"城里所有的建筑都成了废墟。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（烹调中）使变浓稠，收汁","en":"If you reduce liquid when you are cooking, or if it reduces, it is boiled in order to make it less in quantity and thicker.","ex":{"en":"Boil the liquid in a small saucepan to reduce it by half","cn":"用小炖锅炖，收一半汤汁。"}},{"pos":"PHRASE 短语","cn":"境况变差;生活拮据","en":"If you say that someone is living in reduced circumstances, you mean that they do not have as much money as they used to have.","ex":{"en":"They are the descendants of emperors and kings and are now living in reduced circumstances.","cn":"他们是帝王的后代，但是现在境况大不如前了。"}},{"pos":"PHRASE 短语","cn":"使…无言","en":"If someone or something reduces you to silence, they make you feel so upset or confused that you cannot speak.","ex":{"en":"Her challenge reduced them to silence.","cn":"她的质问让他们哑口无言。"}},{"pos":"PHRASE 短语","cn":"使…落泪","en":"If someone or something reduces you to tears, they make you feel so unhappy that you cry.","ex":{"en":"The attentions of the media reduced her to tears.","cn":"媒体的关注把她弄哭了。"}}]},"examples":[{"en":"The skirt was reduced to £10 in the sale.","cn":"在大减价期间，这条裙子减价到 10 英镑。"},{"en":"The number of employees was reduced from 40 to 25.","cn":"雇员人数从 40 人减少到了 25 人。"}]},"resort":{"oxford":{"phon":"rɪˈzɔːt","pos":"noun","senses":[{"en":"a place where a lot of people go on holiday","cn":"旅游胜地；度假胜地","g":"[countable]","lab":"British English also","ex":{"en":"seaside/mountain resorts","cn":"海滨/山区度假村"}},{"en":"the act of using something, especially something bad or unpleasant, because nothing else is possible","cn":"诉诸；求助；采取","g":"[uncountable]","ex":{"en":"There are hopes that the conflict can be resolved without resort to violence.","cn":"冲突有望不需要诉诸武力而得到解决。"}},{"en":"the first or last course of action that you should or can take in a particular situation","cn":"应急措施；可首先（或最后）采取的手段","ex":{"en":"Strike action should be regarded as a last resort, when all attempts to negotiate have failed.","cn":"罢工应该是最后一着，在所有的谈判努力都告失败时才使用。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"诉诸;采取","en":"If you resort to a course of action that you do not really approve of, you adopt it because you cannot see any other way of achieving what you want.","ex":{"en":"His punishing work schedule had made him resort to drugs","cn":"异常紧张的工作安排使他开始吸毒。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"采取;凭借;诉诸;求助","en":"If you achieve something without resort to a particular course of action, you succeed without carrying out that action. To have resort to a particular course of action means to have to do that action in order to achieve something.","ex":{"en":"Congress has a responsibility to ensure that all peaceful options are exhausted before resort to war.","cn":"国会有责任确保只有在所有和平手段都不奏效的情况下才会诉诸战争。"}},{"pos":"N-COUNT 可数名词","cn":"(度假)胜地","en":"A resort is a place where a lot of people spend their holidays.","ex":{"en":"...the ski resorts.","cn":"滑雪胜地"}},{"pos":"PHRASE 短语","cn":"最后的办法;最终手段","en":"If you do something as a last resort, you do it because you can find no other way of getting out of a difficult situation or of solving a problem.","ex":{"en":"Nuclear weapons should be used only as a last resort","cn":"不到万不得已时不能选择使用核武器。"}},{"pos":"PHRASE 短语","cn":"最终","en":"You use in the last resort when stating the most basic or important fact that will still be true in a situation whatever else happens.","ex":{"en":"They would in the last resort support their friends whatever they did.","cn":"无论他们的朋友做了什么，他们最终都会支持他们的朋友。"}}]},"media":{"uk":"media/uk/resort__gb_1.mp3","us":"media/us/resort__us_1.mp3"},"examples":[{"en":"Strike action should be regarded as a last resort , when all attempts to negotiate have failed.","cn":"罢工应该是最后一着，在所有的谈判努力都告失败时才使用。"},{"en":"We may have to resort to using untrained staff.","cn":"我们也许只能使用未受过训练的员工了。"}]},"reader":{"media":{"uk":"media/uk/reader__gb_1.mp3","us":"media/us/reader__us_1.mp3"},"oxford":{"phon":"ˈriːdə(r)","pos":"noun","senses":[{"en":"a person who reads, especially one who reads a lot or in a particular way","cn":"读者；读书…的人；阅读量大的人","lab":"US English","ex":{"en":"an avid reader of science fiction","cn":"科幻小说迷"}},{"en":"a person who reads a particular newspaper, magazine, etc.","cn":"（报刊等的）读者","ex":{"en":"readers’ letters","cn":"读者来信"}},{"en":"an easy book that is intended to help people learn to read their own or a foreign language","cn":"简易读物；读本","ex":{"en":"a series of graded English readers","cn":"一系列分级英语读物"}},{"en":"a senior teacher at a British university just below the rank of a professor","cn":"准教授（英国大学教师，仅次于教授）","ex":{"en":"She is Reader in Music at Edinburgh.","cn":"她是爱丁堡大学的音乐准教授。"}},{"en":"an electronic device that reads data stored in one form and changes it into another form so that a computer can perform operations on it","cn":"电子阅读器；电子识读机","lab":"computing"},{"en":"a machine that produces on a screen a large image of a text stored on a microfiche or microfilm","cn":"缩微软片阅读机","lab":"specialist"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"读者","en":"The readers of a newspaper, magazine, or book are the people who read it.","ex":{"en":"If you are a regular reader of Homes & Gardens you will know what an invaluable source of inspiration it is","cn":"如果你常读《家和花园》杂志的话，就会知道它是一个多么宝贵的灵感源泉。"}},{"pos":"N-COUNT 可数名词","cn":"爱读书的人；有读书习惯的人","en":"A reader is a person who reads, especially one who reads for pleasure.","ex":{"en":"Thanks to that job I became an avid reader","cn":"多亏了那份工作我才成了一个喜欢阅读的人。"}},{"pos":"N-COUNT 可数名词","cn":"（出版社的）审稿人，审阅人","en":"A reader is a person who reads books for a publisher in order to give an opinion on whether they should be published or not."},{"pos":"N-COUNT 可数名词","cn":"（英国大学中仅次于教授的）高级讲师","en":"In British universities, a reader is a senior lecturer, with a rank just below that of a professor.","ex":{"en":"John Stevenson is Reader in History at the University of Sheffield.","cn":"约翰·史蒂文森是谢菲尔德大学的历史学高级讲师。"}},{"pos":"N-COUNT 可数名词","cn":"（美国大学的）助教","en":"In American universities and colleges, a reader is an assistant to a teacher. Readers' duties include reading and marking examination papers and other work."},{"pos":"N-COUNT 可数名词","cn":"（帮助阅读或学习外语的）读本，读物","en":"A reader is a book to help children to learn to read, or to help people to learn a foreign language. It contains passages of text, and often exercises to give practice in reading and writing."}]},"examples":[{"en":"She is Reader in Music at Edinburgh.","cn":"她是爱丁堡大学的音乐准教授。"},{"en":"Are you a ‘Times’ reader?","cn":"你是《泰晤士报》的读者吗？"}]},"return":{"media":{"uk":"media/uk/return__gb_1.mp3","us":"media/us/return__us_1.mp3"},"oxford":{"phon":"rɪˈtɜːn","pos":"verb","senses":[{"en":"to come or go back from one place to another","cn":"回来；回去；返回","g":"[intransitive]","sc":"come/go back","ex":{"en":"I waited a long time for him to return.","cn":"我等他回来等了很长时间。"}},{"en":"to bring, give, put or send something back to somebody/something","cn":"带回；送回；放回；退还","g":"[transitive]","sc":"bring/give back","ex":{"en":"We had to return the hairdryer to the store because it was faulty.","cn":"我们不得不将吹风机退回商店，因为它有残损。"}},{"en":"to come back again","cn":"恢复；重现","g":"[intransitive]","sc":"of feeling/situation","ex":{"en":"The following day the pain returned.","cn":"第二天又疼起来了。"}},{"en":"to start discussing a subject you were discussing earlier, or doing an activity you were doing earlier","cn":"重提；重新开始做","g":"[intransitive]","sc":"to previous subject/activity","ex":{"en":"He returns to this topic later in the report.","cn":"他在报告中后来又提到这个话题。"}},{"en":"to go back to a previous state","cn":"恢复；回复","g":"[intransitive]","sc":"to previous state","ex":{"en":"Train services have returned to normal after the strike.","cn":"罢工过后，列车运营已经恢复正常。"}},{"en":"to do or give something to somebody because they have done or given the same to you first; to have the same feeling about somebody that they have about you","cn":"回报；回应","g":"[transitive]","sc":"do/give the same","ex":{"en":"to return a smile/gaze/greeting","cn":"报以微笑；回应凝视／问候"}},{"en":"to hit the ball back to your opponent during a game","cn":"回击；击回","g":"[transitive]","sc":"in tennis","ex":{"en":"to return a service/shot","cn":"击回发球／抽球"}},{"en":"to give a decision about something in court","cn":"宣告（裁决）","g":"[transitive]","sc":"a verdict","ex":{"en":"The jury returned a verdict of not guilty.","cn":"陪审团宣告了无罪的判决。"}},{"en":"to elect somebody to a political position","cn":"选举；选出；推举","g":"[transitive, usually passive]","lab":"British English","sc":"elect politician","ex":{"en":"She was returned as MP for Edgbaston in the last election.","cn":"她在上次选举中当选为埃德巴斯顿议员。"}},{"en":"to give or produce a particular amount of money as a profit or loss","cn":"带来，产生（利润或损失）","g":"[transitive]","lab":"business","sc":"profit/loss","ex":{"en":"to return a high rate of interest","cn":"有很高的利息回报"}},{"en":"the action of arriving in or coming back to a place that you were in before","cn":"回来；归来；返回","g":"[singular]","sc":"coming back","ex":{"en":"A week had passed since their return to Geneva.","cn":"他们回到日内瓦已经一个星期了。"},"pos":"noun"},{"en":"the action of giving, putting or sending something/somebody back","cn":"归还；放回；退回","g":"[uncountable, singular]","sc":"giving/sending back","ex":{"en":"We would appreciate the prompt return of books to the library.","cn":"若能及时将图书归还给图书馆，我们将不胜感激。"},"pos":"noun"},{"en":"the situation when a feeling or state that has not been experienced for some time starts again","cn":"重现；恢复","g":"[singular]","sc":"of feeling/state","ex":{"en":"the return of spring","cn":"春之归来"},"pos":"noun"},{"en":"the action of going back to an activity or a situation that you used to do or be in","cn":"恢复；返回","g":"[singular]","sc":"to previous situation/activity","ex":{"en":"his return to power","cn":"他的重新掌权"},"pos":"noun"},{"en":"the amount of profit that you get from something","cn":"回报；收益；利润","g":"[uncountable, countable]","sc":"profit","ex":{"en":"a high rate of return on capital","cn":"资本的高回报率"},"pos":"noun"},{"en":"an official report or statement that gives particular information to the government or another body","cn":"报告；陈述；申报","g":"[countable]","sc":"official report","ex":{"en":"census returns","cn":"人口普查报告"},"pos":"noun"},{"en":"a ticket for a journey to a place and back again","cn":"往返票","g":"[countable]","lab":"both British English","sc":"ticket","ex":{"en":"‘Brighton, please.’ ‘Single or return?’","cn":"“我要一张到布赖顿的票。”“单程的还是往返的？”"},"pos":"noun"},{"en":"a ticket for the theatre or a sports game that was bought by somebody but is given back to be sold again","cn":"退票","g":"[countable]","sc":"ticket","pos":"noun"},{"en":"the button that you press on a computer when you reach the end of an instruction, or to begin a new line","cn":"返回键；回车键；结束键","g":"[uncountable]","sc":"on computer","ex":{"en":"To exit this option, press return.","cn":"要退出这个选项，就按返回键。"},"pos":"noun"},{"en":"the action of hitting the ball, etc. back to your opponent","cn":"击回球","g":"[countable]","sc":"in tennis","ex":{"en":"a powerful return of serve","cn":"势大力沉的接发球"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"返回，回到（出发地）","en":"When you return to a place, you go back there after you have been away.","ex":{"en":"Blair will return to London tonight","cn":"今晚布莱尔将返回伦敦。"}},{"pos":"N-SING 单数名词","cn":"返回;回来","en":"Your return is your arrival back at a place where you had been before.","ex":{"en":"Ryle explained the reason for his sudden return to London.","cn":"赖尔解释了他突然返回伦敦的原因。"}},{"pos":"VERB 动词","cn":"归还;退还","en":"If you return something that you have borrowed or taken, you give it back or put it back.","ex":{"en":"I enjoyed the book and said so when I returned it","cn":"我喜欢这本书，并且在还书时也这样说了。"}},{"pos":"VERB 动词","cn":"放回;把…放到原处","en":"If you return something somewhere, you put it back where it was.","ex":{"en":"He returned the notebook to his jacket.","cn":"他把笔记本放回到他的夹克里。"}},{"pos":"VERB 动词","cn":"回应，回报（行为或感情）","en":"If you return someone's action, you do the same thing to them as they have just done to you. If you return someone's feeling, you feel the same way towards them as they feel towards you.","ex":{"en":"Back at the station the Chief Inspector returned the call","cn":"探长回到警察局后回了电话。"}},{"pos":"VERB 动词","cn":"(感觉或情况)重新出现，恢复","en":"If a feeling or situation returns, it comes back or happens again after a period when it was not present.","ex":{"en":"Official reports in Algeria suggest that calm is returning to the country","cn":"阿尔及利亚的官方报告表明这个国家正在恢复往日的平静。"}},{"pos":"VERB 动词","cn":"恢复，回到(原来的状态)","en":"If you return to a state that you were in before, you start being in that state again.","ex":{"en":"Life has improved and returned to normal.","cn":"生活已经改善并恢复了正常。"}},{"pos":"VERB 动词","cn":"回到(某个话题)","en":"If you return to a subject that you have mentioned before, you begin talking about it again.","ex":{"en":"The power of the Church is one theme all these writers return to.","cn":"所有这些作家都回归到了教会权力这个主题上。"}},{"pos":"VERB 动词","cn":"重新开始，继续（某项活动）","en":"If you return to an activity that you were doing before, you start doing it again.","ex":{"en":"At that stage he will be 52, young enough to return to politics if he wishes to do so.","cn":"那时他将会是52岁，还很年轻，如果他希望的话，仍可重返政坛。"}},{"pos":"VERB 动词","cn":"宣布(裁决)","en":"When a judge or jury returns a verdict, they announce whether they think the person on trial is guilty or not.","ex":{"en":"They returned a verdict of not guilty.","cn":"他们宣布了无罪的判决。"}},{"pos":"ADJ 形容词","cn":"(票)双程的，往返的","en":"A return ticket is a ticket for a journey from one place to another and then back again.","ex":{"en":"He bought a return ticket and boarded the next train for home.","cn":"他买了往返票，并登上了下一趟回家的火车。"}},{"pos":"ADJ 形容词","cn":"（旅途）返回的，返程的","en":"The return trip or journey is the part of a journey that takes you back to where you started from.","ex":{"en":"Buy an extra ticket for the return trip.","cn":"多买一张返程票。"}},{"pos":"N-COUNT 可数名词","cn":"利润;回报;收益","en":"The return on an investment is the profit that you get from it.","ex":{"en":"Profits have picked up this year but the return on capital remains tiny","cn":"今年的利润已经回升，但是资本收益仍然很少。"}},{"pos":"N-COUNT 可数名词","cn":"（纳税）申报表，申报单","en":"A tax return is an official form that you fill in with details about your income and personal situation, so that the income tax you owe can be calculated.","ex":{"en":"He was convicted of filing false income tax returns","cn":"他因为在纳税申报表上作假而被定罪。"}},{"pos":"N-PLURAL 复数名词","cn":"(选举)结果","en":"Returns are the results of votes after an election.","ex":{"en":"Early returns show Bulgaria's opposition party may have won.","cn":"早期的选举结果表明保加利亚的反对党可能已获胜。"}},{"pos":"CONVENTION 惯用语","cn":"(生日祝词)生日快乐，长命百岁","en":"When it is someone's birthday, people sometimes say 'Many happy returns' to them as a way of greeting them."},{"pos":"PHRASE 短语","cn":"作为回报;作为交换","en":"If you do something in return for what someone else has done for you, you do it because they did that thing for you.","ex":{"en":"You pay regular premiums and in return the insurance company will pay out a lump sum.","cn":"你定期支付保险费，而保险公司则会一次性给你一笔钱作为回报。"}},{"pos":"PHRASE 短语","cn":"不能回头的地步;无路可退","en":"If you say that you have reached the point of no return, you mean that you now have to continue with what you are doing and it is too late to stop.","ex":{"en":"The release of Mr Nelson Mandela marked the point of no return in South Africa's movement away from apartheid.","cn":"纳尔逊·曼德拉先生的释放标志着南非种族隔离政策一去不复返。"}},{"pos":"","cn":"","en":"to return fire→see: ;"}]},"examples":[{"en":"‘You were both wonderful!’ ‘So were you!’ we said, returning the compliment. “","cn":"你们俩太棒了！” “你也一样啊！”我们也称赞道。"},{"en":"‘Brighton, please.’ ‘Single or return?’ “","cn":"我要一张到布莱顿的票。” “单程的还是往返的？”"}]},"registering":{"lemma":"register"},"regulations":{"lemma":"regulation"},"restore":{"media":{"uk":"media/uk/restore__gb_1.mp3","us":"media/us/restore__us_1.mp3"},"oxford":{"phon":"rɪˈstɔː(r)","pos":"verb","senses":[{"en":"to bring back a situation or feeling that existed before","cn":"恢复（某种情况或感受）","ex":{"en":"The measures are intended to restore public confidence in the economy.","cn":"这些举措旨在恢复公众对经济的信心。"}},{"en":"to bring somebody/something back to a former condition, place or position","cn":"使复原；使复位；使复职","ex":{"en":"He is now fully restored to health.","cn":"他现在完全恢复了健康。"}},{"en":"to repair a building, work of art, piece of furniture, etc. so that it looks as good as it did originally","cn":"修复；整修；使复原","ex":{"en":"Her job is restoring old paintings.","cn":"她的工作是修复旧画。"}},{"en":"to bring a law, tradition, way of working, etc. back into use","cn":"重新采用（或实施）；恢复","ex":{"en":"to restore ancient traditions","cn":"恢复古老的传统"}},{"en":"to give something that was lost or stolen back to somebody","cn":"归还（失物、赃款等）","lab":"formal","ex":{"en":"The police have now restored the painting to its rightful owner.","cn":"警察已经把这幅油画归还给了它的合法主人。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"恢复","en":"To restore a situation or practice means to cause it to exist again.","ex":{"en":"The army has recently been brought in to restore order","cn":"最近军队被调来重整秩序。"}},{"pos":"VERB 动词","cn":"使恢复;使康复;使复原","en":"To restore someone or something to a previous condition means to cause them to be in that condition once again.","ex":{"en":"We will restore her to health but it may take time","cn":"我们会让她恢复健康，但可能需要一些时间。"}},{"pos":"VERB 动词","cn":"修复(建筑、画或家具等)","en":"When someone restores something such as an old building, painting, or piece of furniture, they repair and clean it, so that it looks like it did when it was new.","ex":{"en":"...experts who specialise in examining and restoring ancient parchments.","cn":"专门致力于检查和修复古代羊皮纸文稿的专家"}},{"pos":"VERB 动词","cn":"归还;交还;返还","en":"If something that was lost or stolen is restored to its owner, it is returned to them.","ex":{"en":"The following day their horses and goods were restored to them","cn":"第二天，马匹和货物都归还给了他们。"}}]},"examples":[{"en":"The police have now restored the painting to its rightful owner.","cn":"警察已经把这幅油画归还给了它的合法主人。"},{"en":"The measures are intended to restore public confidence in the economy.","cn":"这些举措旨在恢复公众对经济的信心。"}]},"restricts":{"lemma":"restrict","media":{"uk":"media/uk/restrict__gb_1.mp3","us":"media/us/restrict__us_1.mp3"}},"relation":{"media":{"uk":"media/uk/relation__gb_1.mp3","us":"media/us/relation__us_1.mp3"},"oxford":{"phon":"rɪˈleɪʃn","pos":"noun","senses":[{"en":"the way in which two people, groups or countries behave towards each other or deal with each other","cn":"（人、团体、国家之间的）关系，联系","g":"[plural]","lab":"formal","ex":{"en":"diplomatic/international/foreign relations","cn":"外交／国际／对外关系"}},{"en":"the way in which two or more things are connected","cn":"（事物之间的）关系，关联，联系","g":"[uncountable, countable]","lab":"formal","ex":{"en":"the relation between rainfall and crop yields","cn":"降雨量和农作物产量之间的关系"}},{"en":"a person who is in the same family as somebody else","cn":"亲戚；亲属","g":"[countable]","ex":{"en":"a close/near/distant relation of mine","cn":"我的一个近亲／远亲"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(人、团体或国家之间的)联系，关系，往来","en":"Relations between people, groups, or countries are contacts between them and the way in which they behave towards each other.","ex":{"en":"Greece has established full diplomatic relations with Israel","cn":"希腊已经和以色列建立了全面的外交关系。"}},{"pos":"N-COUNT 可数名词","cn":"(两者之间的)关系，联系，关联","en":"If you talk about the relation of one thing to another, you are talking about the ways in which they are connected.","ex":{"en":"It is a question of the relation of ethics to economics.","cn":"这是一个伦理学和经济学的关系问题。"}},{"pos":"N-COUNT 可数名词","cn":"亲戚;亲属;家庭成员","en":"Your relations are the members of your family.","ex":{"en":"...visits to friends and relations","cn":"拜访亲友"}},{"pos":"PREP-PHRASE 短语介词","cn":"与…相比","en":"You can talk about something in relation to something else when you want to compare the size, condition, or position of the two things.","ex":{"en":"The money he'd been ordered to pay was minimal in relation to his salary.","cn":"他被要求支付的金额与他的薪水相比微不足道。"}},{"pos":"PREP-PHRASE 短语介词","cn":"关于;涉及","en":"If something is said or done in relation to a subject, it is said or done in connection with that subject.","ex":{"en":"...a question which has been asked many times in relation to Irish affairs","cn":"被问过多次的关于爱尔兰事务的问题"}}]},"examples":[{"en":"Relations with neighbouring countries are under strain at present.","cn":"目前，与邻国的关系正处于紧张状态。"},{"en":"The fee they are offering bears no relation to the amount of work involved.","cn":"他们支付的酬金和所需的工作量无关。"}]},"refreshment":{"media":{"uk":"media/uk/refreshment__gb_1.mp3","us":"media/us/refreshment__us_1.mp3"},"oxford":{"phon":"rɪˈfreʃmənt","pos":"noun","senses":[{"en":"drinks and small amounts of food that are provided or sold to people in a public place or at a public event","cn":"（在公共场所或公开活动上供应或销售的）饮料，小食","g":"[plural]","ex":{"en":"Light refreshments will be served during the break.","cn":"中间休息时有点心供应。"}},{"en":"food and drink","cn":"食物和饮料","g":"[uncountable]","lab":"formal","ex":{"en":"In York we had a short stop for refreshment.","cn":"在约克，我们稍作停留，吃了点东西。"}},{"en":"the fact of making somebody feel stronger or less tired or hot","cn":"恢复活力；焕发精神","g":"[uncountable]","lab":"formal","ex":{"en":"a place to rest and find refreshment for mind and body","cn":"休息和恢复身心活力的场所"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"（会议或旅行等期间提供的）饮料，点心，茶点","en":"Refreshments are drinks and small amounts of food that are provided, for example, during a meeting or a journey."},{"pos":"N-UNCOUNT 不可数名词","cn":"食物；饮料","en":"You can refer to food and drink as refreshment .","ex":{"en":"May I offer you some refreshment?","cn":"我给你来点吃的怎样？"}}]},"examples":[{"en":"In York we had a short stop for refreshment.","cn":"在约克，我们稍作停留，吃了点东西。"},{"en":"Light refreshments will be served during the break.","cn":"中间休息时有点心供应。"}]},"revolutionary":{"oxford":{"phon":"ˌrevəˈluːʃənəri","pos":"adjective","senses":[{"en":"connected with political revolution","cn":"革命的","g":"[usually before noun]","ex":{"en":"a revolutionary leader","cn":"革命领袖"}},{"en":"involving a great or complete change","cn":"革命性的；大变革的；巨变的","ex":{"en":"a revolutionary idea","cn":"革命性的想法"}},{"en":"a person who starts or supports a revolution, especially a political one","cn":"（支持）改革者；（尤指）革命者，革命支持者","ex":{"en":"socialist revolutionaries","cn":"社会主义革命者"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"革命的","en":"Revolutionary activities, organizations, or people have the aim of causing a political revolution.","ex":{"en":"Do you know anything about the revolutionary movement?","cn":"你了解这场革命运动吗？"}},{"pos":"N-COUNT 可数名词","cn":"革命者;革命家","en":"A revolutionary is a person who tries to cause a revolution or who takes an active part in one.","ex":{"en":"The revolutionaries laid down their arms and its leaders went into voluntary exile.","cn":"革命者放下了武器，其领导人也自愿流亡他国了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"革命性的;突破性的;发生重大变革的","en":"Revolutionary ideas and developments involve great changes in the way that something is done or made.","ex":{"en":"Invented in 1951, the rotary engine is a revolutionary concept in internal combustion","cn":"1951年发明的转缸式发动机是内燃机领域内的革命性概念。"}}]},"media":{"uk":"media/uk/revolutionary__gb_1.mp3","us":"media/us/revolutionary__us_1.mp3"},"examples":[{"en":"a time of rapid and revolutionary change","cn":"迅速剧烈变革的时期"},{"en":"a revolutionary idea","cn":"独出心裁的想法"}]},"reproduction":{"media":{"uk":"media/uk/reproduction__gb_1.mp3","us":"media/us/reproduction__us_1.mp3"},"oxford":{"phon":"ˌriːprəˈdʌkʃn","pos":"noun","senses":[{"en":"the act or process of producing babies, young animals or plants","cn":"生殖；繁殖","g":"[uncountable]","ex":{"en":"sexual reproduction","cn":"有性生殖"}},{"en":"the act or process of producing copies of a document, book, picture, etc.","cn":"复制；再版","g":"[uncountable]","ex":{"en":"Use a black pen on white paper to ensure good reproduction.","cn":"用白纸黑笔，以确保复制清晰。"}},{"en":"the quality of recorded sound","cn":"（录音的）音质，音效","g":"[uncountable]","ex":{"en":"Digital recording gives excellent sound reproduction.","cn":"数字录音的声音效果极佳。"}},{"en":"a thing that has been reproduced, especially a copy of a work of art","cn":"（尤指艺术品的）复制品","g":"[countable]","ex":{"en":"They have a catalogue with colour reproductions of the paintings for sale.","cn":"他们有一个待售画作的彩色图样目录。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"复制品;仿制品","en":"A reproduction is a copy of something such as a piece of furniture or a work of art.","ex":{"en":"...a reproduction of a popular religious painting.","cn":"一幅颇受欢迎的宗教画复制品"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(声音的)录制","en":"Sound reproduction is the recording of sound onto tapes, CDs, or films so that it can be heard by a large number of people.","ex":{"en":"...the increasingly high technology of music reproduction.","cn":"越来越先进的音乐录制技术"}}]},"examples":[{"en":"Use a black pen on white paper to ensure good reproduction.","cn":"用白纸黑笔，以确保复印清晰。"},{"en":"Digital recording gives excellent sound reproduction.","cn":"数码录音的声音效果极佳。"}]},"revolving":{"media":{"uk":"media/uk/revolving__gb_1.mp3","us":"media/us/revolving__us_4.mp3"},"oxford":{"phon":"rɪˈvɒlvɪŋ","pos":"adjective","senses":[{"en":"able to turn in a circle","cn":"旋转的","ex":{"en":"a revolving chair","cn":"转椅"}}]},"examples":[{"en":"The theatre has a revolving stage.","cn":"剧院有一个旋转舞台。"},{"en":"a revolving chair","cn":"转椅"}]},"reassuring":{"media":{"uk":"media/uk/reassuring__gb_1.mp3","us":"media/us/reassuring__us_1.mp3"},"oxford":{"phon":"ˌriːəˈʃʊərɪŋ","pos":"adjective","senses":[{"en":"making you feel less worried or uncertain about something","cn":"令人感到宽慰的；令人放心的","ex":{"en":"a reassuring smile","cn":"使人信心倍增的微笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(语言或动作）令人放心的，令人欣慰的","en":"If you find some-one's words or actions reassuring, they make you feel less worried about something.","ex":{"en":"It was reassuring to hear John's familiar voice","cn":"听到约翰熟悉的声音让人放心。"}}]},"examples":[{"en":"It's reassuring (to know) that we've got the money if necessary.","cn":"我们有了应急的钱，这就不必担心了。"},{"en":"a reassuring smile","cn":"使人信心倍增的微笑"}],"base":"reassure"},"religious":{"media":{"uk":"media/uk/religious__gb_1.mp3","us":"media/us/religious__us_1.mp3"},"oxford":{"phon":"rɪˈlɪdʒəs","pos":"adjective","senses":[{"en":"connected with religion or with a particular religion","cn":"宗教信仰的；宗教的","g":"[only before noun]","ex":{"en":"religious beliefs/convictions/faith","cn":"宗教信仰"}},{"en":"believing strongly in a particular religion and obeying its laws and practices","cn":"笃信宗教的；虔诚的","ex":{"en":"His wife is very religious.","cn":"他的妻子非常虔诚。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"宗教的;信教的","en":"You use religious to describe things that are connected with religion or with one particular religion.","ex":{"en":"...religious groups.","cn":"宗教团体"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"虔诚的;宗教信仰坚定的","en":"Someone who is religious has a strong belief in a god or gods.","ex":{"en":"They are both very religious and felt it was a gift from God.","cn":"他们俩都很虔诚，感觉这是上帝的恩赐。"}}]},"examples":[{"en":"His wife is very religious.","cn":"她的妻子非常虔诚。"},{"en":"religious education (= education about religion)","cn":"宗教教育"}]},"reunite":{"media":{"uk":"media/uk/reunite__gb_1.mp3","us":"media/us/reunite__us_1.mp3"},"oxford":{"phon":"ˌriːjuˈnaɪt","pos":"verb","senses":[{"en":"to bring two or more people together again after they have been separated for a long time; to come together again","cn":"（使）重逢，再次相聚","g":"[usually passive]","ex":{"en":"Last night she was reunited with her children.","cn":"昨天晚上，她和她的子女团聚。"}},{"en":"to join together again separate areas or separate groups within an organization, a political party, etc.; to come together again","cn":"（使）再结合，再联合","ex":{"en":"As leader, his main aim is to reunite the party.","cn":"作为领导，他的主要目标就是要使党内各派团结起来。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）团聚;（使）重聚;（使）重逢","en":"If people are reunited, or if they reunite, they meet each other again after they have been separated for some time.","ex":{"en":"She and her youngest son were finally allowed to be reunited with their family","cn":"她和小儿子终于得到允许和家人团聚。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）统一;（使）重新团结","en":"If a divided organization or country is reunited, or if it reunites, it becomes one united organization or country again.","ex":{"en":"...a federation under which the divided island would be reunited","cn":"将使这个分裂的岛屿实现统一的联邦政府"}}]},"examples":[{"en":"As leader, his main aim is to reunite the party.","cn":"作为领导，他的主要目标就是要使党内各派团结起来。"},{"en":"There have been rumours that the band will reunite for a world tour.","cn":"有传言说这个乐队将再度聚集作一次环球演出。"}]},"remains":{"media":{"uk":"media/uk/remains__gb_1.mp3","us":"media/us/remains__us_1.mp3"},"oxford":{"phon":"rɪˈmeɪnz","pos":"noun","senses":[{"en":"the parts of something that are left after the other parts have been used, eaten, removed, etc.","cn":"剩余物；残留物；剩饭菜","ex":{"en":"She fed the remains of her lunch to the dog.","cn":"她把剩下的午饭喂狗了。"}},{"en":"the parts of ancient objects and buildings that have survived and are discovered in the present day","cn":"古代遗物；古迹；遗迹；遗址","ex":{"en":"The museum has an impressive collection of prehistoric remains.","cn":"那家博物馆的史前遗迹藏品令人赞叹。"}},{"en":"the body of a dead person or animal","cn":"遗体；遗骸","lab":"formal","ex":{"en":"They had discovered human remains.","cn":"他们发现过人类遗骸。"}}]},"examples":[{"en":"She fed the remains of her lunch to the dog.","cn":"她把剩下的午饭喂狗了。"},{"en":"They had discovered human remains.","cn":"他们发现过人类遗骸。"}],"base":"remain"},"reasonable":{"media":{"uk":"media/uk/reasonable__gb_1.mp3","us":"media/us/reasonable__us_1.mp3"},"oxford":{"phon":"ˈriːznəbl","pos":"adjective","senses":[{"en":"fair, practical, and sensible","cn":"公平的；合理的；有理由的；明智的","ex":{"en":"It is reasonable to assume that he knew beforehand that this would happen.","cn":"有理由认为，他事先就知道会发生这样的事。"}},{"en":"acceptable and appropriate in a particular situation","cn":"可以接受的；合乎情理的；公道的","ex":{"en":"The police apparently thought this explanation perfectly reasonable.","cn":"警方显然认为这个解释完全合理。"}},{"en":"not too expensive","cn":"不太贵的；公道的","ex":{"en":"We sell good-quality food at reasonable prices.","cn":"我们以公道的价格出售优质食品。"}},{"en":"fairly good, but not very good","cn":"不错的；还算好的；过得去的","g":"[usually before noun]","ex":{"en":"Most people here have a reasonable standard of living.","cn":"这里大部分人生活水平还不错。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）公平的，明智的，理智的，有判断力的","en":"If you think that someone is fair and sensible you can say that they are reasonable.","ex":{"en":"He's a reasonable sort of chap","cn":"他是个理智的家伙。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（决定或行动）公平的，合理的","en":"If you say that a decision or action is reasonable, you mean that it is fair and sensible.","ex":{"en":"...a perfectly reasonable decision","cn":"完全合理的决定"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（期望或解释）合理的，有道理的","en":"If you say that an expectation or explanation is reasonable, you mean that there are good reasons why it may be correct.","ex":{"en":"It seems reasonable to expect rapid urban growth.","cn":"似乎有理由期望城市快速发展。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（价钱）合理的，公道的，不太贵的","en":"If you say that the price of something is reasonable, you mean that it is fair and not too high.","ex":{"en":"You get an interesting meal for a reasonable price","cn":"你花不多的钱就可以吃一顿很特别的饭。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"还算好的;不错的","en":"You can use reasonable to describe something that is fairly good, but not very good.","ex":{"en":"The boy answered him in reasonable French","cn":"这个男孩用还算流利的法语回答他。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"较多的；相当大的","en":"A reasonable amount of something is a fairly large amount of it.","ex":{"en":"They will need a reasonable amount of desk area and good light.","cn":"他们将需要一个面积较大的摆放办公桌的地方和充足的照明。"}}]},"examples":[{"en":"Be reasonable! We can't work late every night.","cn":"要讲道理呀！我们不能每天晚上都干得很晚呀。"},{"en":"It is reasonable to assume that he knew beforehand that this would happen.","cn":"有理由认为他事先就知道会发生这样的事。"}]},"revision":{"media":{"uk":"media/uk/revision__gb_1.mp3","us":"media/us/revision__us_1.mp3"},"oxford":{"phon":"rɪˈvɪʒn","pos":"noun","senses":[{"en":"a change or set of changes to something","cn":"（一项、一轮等）修订，修改","g":"[countable]","ex":{"en":"He made some minor revisions to the report before printing it out.","cn":"把报告打印出来之前，他做了一些小的修改。"}},{"en":"the act of changing something, or of examining something with the intention of changing it","cn":"修订，修改（的进行）","g":"[uncountable, countable]","ex":{"en":"The system is in need of revision.","cn":"这一系统需要修正。"}},{"en":"the process of learning work for an exam","cn":"复习；温习","g":"[uncountable]","lab":"British English","ex":{"en":"Have you started your revision yet?","cn":"你开始复习了吗？"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"修订;修改;修正;校订","en":"To make a revision of something that is written or something that has been decided means to make changes to it in order to improve it, make it more modern, or make it more suitable for a particular purpose.","ex":{"en":"The phase of writing that is actually most important is revision","cn":"实际上写作过程中最重要的阶段是修改。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（考前）复习，温习","en":"When people who are studying do revision, they read things again and make notes in order to prepare for an examination.","ex":{"en":"Some girls prefer to do their revision at home.","cn":"有些女孩更愿意在家复习功课。"}}]},"examples":[{"en":"He made some minor revisions to the report before printing it out.","cn":"把报告打印出来之前，他做了一些小的修改。"},{"en":"Have you started your revision yet?","cn":"你开始复习了吗？"}]},"recession":{"media":{"uk":"media/uk/recession__gb_1.mp3","us":"media/us/recession__us_1.mp3"},"oxford":{"phon":"rɪˈseʃn","pos":"noun","senses":[{"en":"a difficult time for the economy of a country, when there is less trade and industrial activity than usual and more people are unemployed","cn":"经济衰退；经济萎缩","g":"[countable, uncountable]","ex":{"en":"How do you assess the impact of the current recession on manufacturing?","cn":"你如何评价时下经济萎缩对制造业的影响？"}},{"en":"the movement backwards of something from a previous position","cn":"退后；撤回","g":"[uncountable]","lab":"formal","ex":{"en":"the gradual recession of the floodwater","cn":"洪水的渐渐消退"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"经济衰退；经济不景气","en":"A recession is a period when the economy of a country is doing badly, for example because industry is producing less and more people are becoming unemployed.","ex":{"en":"The recession caused sales to drop off","cn":"经济不景气使销量下降。"}}]},"examples":[{"en":"the impact of the current recession on manufacturing","cn":"时下经济萎缩对制造业的影响"},{"en":"The economy is in deep recession.","cn":"经济正处于严重的衰退之中。"}]},"researching":{"lemma":"research","media":{"uk":"media/uk/research__gb_1.mp3","us":"media/us/research__us_1.mp3"}},"reverse":{"oxford":{"phon":"rɪˈvɜːs","pos":"verb","senses":[{"en":"to change something completely so that it is the opposite of what it was before","cn":"颠倒；彻底转变；使完全相反","g":"[transitive]","sc":"change to opposite","ex":{"en":"Falling birth rates may reverse the trend towards early retirement.","cn":"出生率下降可能扭转提前退休的趋势。"}},{"en":"to change a previous decision, law, etc. to the opposite one","cn":"撤销，废除（决定、法律等）","g":"[transitive]","sc":"change to opposite","ex":{"en":"The Court of Appeal reversed the decision.","cn":"上诉法庭撤销了这项裁决。"}},{"en":"to turn something the opposite way around or change the order of something around","cn":"使反转；使次序颠倒","g":"[transitive]","sc":"change to opposite","ex":{"en":"Writing is reversed in a mirror.","cn":"镜子里的字是反的。"}},{"en":"to exchange the positions or functions of two things","cn":"交换（位置或功能）","g":"[transitive]","sc":"exchange two things","ex":{"en":"It felt as if we had reversed our roles of parent and child.","cn":"感觉我们就像家长和孩子交换了角色。"}},{"en":"to admit you were wrong or to stop having a particular position in an argument","cn":"承认错误；放弃（立场）","g":"[transitive]","lab":"North American English","sc":"yourself","ex":{"en":"He has reversed himself on a dozen issues.","cn":"他已经不再坚持自己在一系列问题上的立场。"}},{"en":"when a vehicle or its driver reverses or the driver reverses a vehicle, the vehicle goes backwards","cn":"（使）倒退行驶；倒车","g":"[intransitive, transitive]","lab":"especially British English","sc":"vehicle","ex":{"en":"He reversed around the corner.","cn":"他倒车转过拐角。"}},{"en":"to make a phone call that will be paid for by the person you are calling, not by you","cn":"打对方付费的电话","g":"[transitive]","lab":"British English","sc":"phone call","ex":{"en":"I want to reverse the charges, please.","cn":"劳驾，我想打一个由受话人付费的电话。"}},{"en":"the opposite of what has just been mentioned","cn":"相反的情况（或事物）","g":"[singular]","sc":"opposite","ex":{"en":"This problem is the reverse of the previous one.","cn":"这个问题和上一个问题相反。"},"pos":"noun"},{"en":"the back of a coin, piece of material, piece of paper, etc.","cn":"后面；背面；反面","g":"[singular]","sc":"back","ex":{"en":"The coin has a coat of arms stamped on the reverse.","cn":"硬币的背面刻有徽章。"},"pos":"noun"},{"en":"the machine in a vehicle used to make it move backwards","cn":"倒挡","g":"[uncountable]","sc":"in vehicle","ex":{"en":"Put the car in/into reverse.","cn":"给汽车挂上倒挡。"},"pos":"noun"},{"en":"a loss or defeat; a change from success to failure","cn":"损失；失败；倒退","g":"[countable]","lab":"formal","sc":"loss/defeat","ex":{"en":"Property values have suffered another reverse.","cn":"房地产价值再次遭受损失。"},"pos":"noun"},{"en":"opposite to what has been mentioned","cn":"相反的；反面的；反向的","sc":"opposite","ex":{"en":"to travel in the reverse direction","cn":"向相反方向行进"},"pos":"adjective"},{"en":"opposite to the front","cn":"背面的；反面的；后面的","sc":"back","ex":{"en":"Iron the garment on the reverse side.","cn":"这件衣服要从反面熨。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"逆转，彻底改变（决定、政策、趋势等）","en":"When someone or something reverses a decision, policy, or trend, they change it to the opposite decision, policy, or trend.","ex":{"en":"They have made it clear they will not reverse the decision to increase prices","cn":"他们已经明确表示不会更改提价的决定。"}},{"pos":"VERB 动词","cn":"颠倒，反转（事物的顺序）","en":"If you reverse the order of a set of things, you arrange them in the opposite order, so that the first thing comes last.","ex":{"en":"In the squares place a penny, nickel, dime and quarter in that order. The object is to reverse the order of these coins","cn":"在这些方块中按顺序放置1分、5分、10分和25分的硬币各一枚。目标是颠倒这些硬币的顺序。"}},{"pos":"VERB 动词","cn":"交换，互换（位置、功能）","en":"If you reverse the positions or functions of two things, you change them so that each thing has the position or function that the other one had.","ex":{"en":"He reversed the position of the two stamps.","cn":"他将两枚邮票的位置调换了一下。"}},{"pos":"V-ERG 及物/不及物动词","cn":"倒（车）","en":"When a car reverses or when you reverse it, the car is driven backwards.","ex":{"en":"Another car reversed out of the drive","cn":"另一辆车倒出了车道。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"倒挡;倒车","en":"If your car is in reverse, you have changed gear so that you can drive it backwards.","ex":{"en":"He lurched the car in reverse along the ruts to the access road.","cn":"他顺着车辙摇摇晃晃地将车倒到了支路上。"}},{"pos":"ADJ 形容词","cn":"相反的","en":"Reverse means opposite to what you expect or to what has just been described.","ex":{"en":"The wrong attitude will have exactly the reverse effect.","cn":"错误的态度会产生完全相反的效果。"}},{"pos":"N-SING 单数名词","cn":"完全相反;正相反","en":"If you say that one thing is the reverse of another, you are emphasizing that the first thing is the complete opposite of the second thing.","ex":{"en":"There is absolutely no evidence at all that spectators want longer cricket matches. Quite the reverse","cn":"完全没有证据表明观众想看时间更长的板球比赛。情况恰恰相反。"}},{"pos":"N-COUNT 可数名词","cn":"严重的失败;挫折","en":"A reverse is a serious failure or defeat.","ex":{"en":"It's clear that the party of the former Prime Minister has suffered a major reverse.","cn":"显然，前首相所在党派遭受了重大的挫折。"}},{"pos":"N-SING 单数名词","cn":"反面;背面","en":"The reverse or the reverse side of a flat object which has two sides is the less important or the other side.","ex":{"en":"Cheques should be made payable to Country Living and your address written on the reverse.","cn":"支票抬头必须写“《乡村生活》杂志”，你的地址应写在背面。"}},{"pos":"PHRASE 短语","cn":"相反地;逆向地;颠倒地","en":"If something happens in reverse or goes into reverse, things happen in the opposite way to what usually happens or to what has been happening.","ex":{"en":"Amis tells the story in reverse, from the moment the man dies","cn":"埃米斯以倒叙的方式讲述了这个故事，从这个男人死去的时候开始讲起。"}},{"pos":"PHRASE 短语","cn":"打对方付费的电话","en":"If you reverse the charges when you make a telephone call, the person who you are phoning pays the cost of the call and not you."}]},"media":{"uk":"media/uk/reverse__gb_1.mp3","us":"media/us/reverse__us_1.mp3"},"examples":[{"en":"Although I expected to enjoy living in the country, in fact the reverse is true.","cn":"尽管我原以为会喜欢乡村生活，但实际情况正好相反。"},{"en":"She used to work for me, but our situations are now reversed.","cn":"过去她为我工作，而现在我们的地位对调了。"}]},"readily":{"media":{"uk":"media/uk/readily__gb_1.mp3","us":"media/us/readily__us_1.mp3"},"oxford":{"phon":"ˈredɪli","pos":"adverb","senses":[{"en":"quickly and without difficulty","cn":"快捷地；轻而易举地；便利地","ex":{"en":"All ingredients are readily available from your local store.","cn":"所有的原料都可以方便地从你当地的商店买到。"}},{"en":"in a way that shows you do not object to something","cn":"欣然地；乐意地","ex":{"en":"Most people readily accept the need for laws.","cn":"大多数人都毫不迟疑地认为法律是必要的。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"乐意地；欣然地","en":"If you do something readily, you do it in a way which shows that you are very willing to do it.","ex":{"en":"I asked her if she would allow me to interview her, and she readily agreed","cn":"我问她是否允许我采访她，她欣然同意了。"}},{"pos":"ADV-GRADED 副词","cn":"迅速地；容易地；轻松地","en":"You also use readily to say that something can be done or obtained quickly and easily. For example, if you say that something can be readily understood, you mean that people can understand it quickly and easily.","ex":{"en":"The components are readily available in hardware shops","cn":"这些零件很容易在五金商店买到。"}}]},"examples":[{"en":"All ingredients are readily available from your local store.","cn":"所有的原料都可以方便地从你当地的商店买到。"},{"en":"Most people readily accept the need for laws.","cn":"大多数人都毫不迟疑地认为法律是必要的。"}]},"reputable":{"media":{"uk":"media/uk/reputable__gb_1.mp3","us":"media/us/reputable__us_1.mp3"},"oxford":{"phon":"ˈrepjətəbl","pos":"adjective","senses":[{"en":"that people consider to be honest; having a good reputation","cn":"声誉好的；值得信赖的","ex":{"en":"a reputable dealer/company/supplier","cn":"可信赖的交易商／公司／供应商"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"声誉好的;可信赖的;有名望的","en":"A reputable company or person is reliable and can be trusted.","ex":{"en":"You are well advised to buy your car through a reputable dealer.","cn":"强烈建议您通过值得信赖的经销商购车。"}}]},"examples":[{"en":"a reputable dealer/company/supplier","cn":"可信赖的交易商/公司/供应商"}]},"reuse":{"media":{"uk":"media/uk/reuse__gb_1.mp3","us":"media/us/reuse__us_1.mp3"},"oxford":{"phon":"ˌriːˈjuːz","pos":"verb","senses":[{"en":"to use something again","cn":"再次使用；重复使用","ex":{"en":"Please reuse your envelopes.","cn":"信封请重复利用。"}},{"en":"the act of using something again","cn":"再次使用；重复使用","ex":{"en":"The water is conserved and reheated for reuse.","cn":"水被保存并重新加热以供再利用。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"再使用;重复使用;重新利用","en":"When you reuse something, you use it again instead of throwing it away.","ex":{"en":"Try where possible to reuse paper.","cn":"尽可能重复使用纸张。"}}]},"examples":[{"en":"Please reuse your envelopes.","cn":"信封请重复利用。"},{"en":"The bottles are designed to be reused up to 20 times.","cn":"这些瓶子最多可供重复使用20次。"}]},"retainer":{"media":{"uk":"media/uk/retainer__gb_1.mp3","us":"media/us/retainer__us_1.mp3"},"oxford":{"phon":"rɪˈteɪnə(r)","pos":"noun","senses":[{"en":"a sum of money that is paid to somebody to make sure they will be available to do work when they are needed","cn":"（聘请律师等的）预付费用，保留金","ex":{"en":"The agency will pay you a monthly retainer.","cn":"这个机构将会每月付给你聘金。"}},{"en":"a small amount of rent that you pay for a room, etc. when you are not there in order to keep it available for your use","cn":"（为保留租房而付的）租房定金","lab":"British English","ex":{"en":"Check whether full rent or a retainer is required during vacations.","cn":"检查假期期间是否需要全额租金或预付金。"}},{"en":"a device that keeps a person’s teeth straight after they have had orthodontic treatment with braces","cn":"（牙齿）固位体，保持器","lab":"North American English"},{"en":"a servant, especially one who has been with a family for a long time","cn":"（尤指服务多年的）仆人，家仆","lab":"old-fashioned"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"定金;预付金","en":"A retainer is a fee that you pay to someone in order to make sure that they will be available to do work for you if you need them to.","ex":{"en":"I'll need a five-hundred-dollar retainer","cn":"我将收取500美元的定金。"}},{"pos":"N-COUNT 可数名词","cn":"（服务多年的）仆人，家仆","en":"A servant who has been with one family for a long time can be referred to as a retainer .","ex":{"en":"I found the gardener, a family retainer, morosely surveying the scene.","cn":"我发现这个园丁——家里一个服侍多年的仆人，愁眉苦脸地审视着这个场景。"}}]},"examples":[{"en":"The agency will pay you a monthly retainer.","cn":"代理机构将会每月付给你聘用金。"}]},"reptile":{"oxford":{"phon":"ˈreptaɪl","pos":"noun","senses":[{"en":"any animal that has cold blood and skin covered in scales, and that lays eggs. Snakes, crocodiles and tortoises are all reptiles.","cn":"爬行动物"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"爬行动物","en":"Reptiles are a group of cold-blooded animals which have skins covered with small hard plates called scales and lay eggs. Snakes, lizards, and crocodiles are reptiles."}]},"media":{"img":["media/pic/reptiles_comp.jpg","media/thumb/turtle.jpg"],"uk":"media/uk/reptile__gb_1.mp3","us":"media/us/reptile__us_1.mp3"},"examples":[{"en":"( figurative ) He licked his lips in an unpleasantly reptilian way.","cn":"他恶心地像爬虫般舔着他的嘴唇。"},{"en":"He licked his lips in an unpleasantly reptilian way.","cn":""}]},"refuge":{"media":{"uk":"media/uk/refuge__gb_1.mp3","us":"media/us/refuge__us_1.mp3"},"oxford":{"phon":"ˈrefjuːdʒ","pos":"noun","senses":[{"en":"shelter or protection from danger, trouble, etc.","cn":"庇护；避难","g":"[uncountable]","ex":{"en":"A further 300 people have taken refuge in the US embassy.","cn":"又有 300 人在美国大使馆避难。"}},{"en":"a place, person or thing that provides shelter or protection for somebody/something","cn":"避难所；庇护者；慰藉","g":"[countable]","ex":{"en":"The marshes are a wetland refuge for seabirds, waders and wild fowl.","cn":"那片沼泽是海鸟、涉禽和野禽的湿地藏身处。"}},{"en":"a building that provides a temporary home for people in need of shelter or protection from somebody/something","cn":"收容所；避难所","g":"[countable]","ex":{"en":"The best option for a female victim of domestic abuse is to contact a women's refuge.","cn":"对受到家庭暴力伤害的女性而言，最佳的做法是联系妇女救助中心。"}},{"en":"an area in the middle of a road where you can stand and wait for cars to go past until it is safe for you to cross","cn":"交通岛（供行人避让车辆）","lab":"both British English"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"庇护；避难","en":"If you take refuge somewhere, you try to protect yourself from physical harm by going there.","ex":{"en":"They took refuge in a bomb shelter","cn":"他们在防空洞中避难。"}},{"pos":"N-COUNT 可数名词","cn":"避难所;庇护处;安全地带","en":"A refuge is a place where you go for safety and protection, for example from violence or from bad weather.","ex":{"en":"...a refuge for battered women","cn":"为受到暴力侵害的妇女建的避难所"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（行为和想法的）逃避，躲避","en":"If you take refuge in a particular way of behaving or thinking, you try to protect yourself from unhappiness or unpleasantness by behaving or thinking in that way.","ex":{"en":"All too often, they get bored, and seek refuge in drink and drugs","cn":"太多的时候，他们觉得无聊就在酒精和毒品中寻求慰藉。"}}]},"examples":[{"en":"As the situation at home got worse she increasingly took refuge in her work.","cn":"随着家庭情况的恶化，她越来越在工作中寻求慰藉。"},{"en":"He regarded the room as a refuge from the outside world.","cn":"他把这个屋子当作是逃避外界的避难所。"}]},"reward":{"media":{"uk":"media/uk/reward__gb_1.mp3","us":"media/us/reward__us_1.mp3"},"oxford":{"phon":"rɪˈwɔːd","pos":"noun","senses":[{"en":"a thing that you are given because you have done something good, worked hard, etc.","cn":"奖励；回报；报酬","g":"[countable, uncountable]","ex":{"en":"a financial reward","cn":"经济奖励"}},{"en":"an amount of money that is offered to somebody for helping the police to find a criminal or for finding something that is lost","cn":"赏格；悬赏金","g":"[countable]","ex":{"en":"A £100 reward has been offered for the return of the necklace.","cn":"已悬赏 100 英镑找寻项链。"}},{"en":"to give something to somebody because they have done something good, worked hard, etc.","cn":"奖励；奖赏；给予报酬","ex":{"en":"She was rewarded for her efforts with a cash bonus.","cn":"她因自己所作的努力而得到一笔奖金。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"奖励;奖赏","en":"A reward is something that you are given, for example because you have behaved well, worked hard, or provided a service to the community.","ex":{"en":"A bonus of up to 5 per cent can be added to a pupil's final exam marks as a reward for good spelling, punctuation and grammar","cn":"小学生期末考试的分数最多可以加5分，作为对其拼写、标点和语法正确的奖励。"}},{"pos":"N-COUNT 可数名词","cn":"赏金;赏格","en":"A reward is a sum of money offered to anyone who can give information about lost or stolen property or about someone who is wanted by the police.","ex":{"en":"The firm last night offered a £10,000 reward for information leading to the conviction of the killer.","cn":"昨晚这家公司悬赏 1万英镑，寻找能将凶手定罪的证据。"}},{"pos":"VERB 动词","cn":"奖赏;奖励;酬谢","en":"If you do something and are rewarded with a particular benefit, you receive that benefit as a result of doing that thing.","ex":{"en":"Make the extra effort to impress the buyer and you will be rewarded with a quicker sale.","cn":"多用心去打动顾客，货物就会更快售出。"}},{"pos":"N-COUNT 可数名词","cn":"报答;回报;酬谢","en":"The rewards of something are the benefits that you receive as a result of doing or having that thing.","ex":{"en":"The company is only just starting to reap the rewards of long-term investments","cn":"这家公司才刚刚开始收获长期投资的回报。"}},{"pos":"VERB 动词","cn":"值得（付出时间或精力）","en":"If you say that something rewards your attention or effort, you mean that it is worth spending time or effort on it.","ex":{"en":"The compression and density make this a difficult book to read, but it richly rewards the effort.","cn":"这本书内容丰富，思想深刻，很难读懂，但是非常值得一读。"}}]},"examples":[{"en":"Winning the match was just reward for the effort the team had made.","cn":"赢得比赛的胜利是全队付出努力应得的回报。"},{"en":"She was rewarded for her efforts with a cash bonus.","cn":"她因自己所作的努力而得到一笔奖金。"}]},"removing":{"lemma":"remove"},"receptive":{"media":{"uk":"media/uk/receptive__gb_1.mp3","us":"media/us/receptive__us_1.mp3"},"oxford":{"phon":"rɪˈseptɪv","pos":"adjective","senses":[{"en":"willing to listen to or to accept new ideas or suggestions","cn":"（对新观点、建议等）愿意倾听的，乐于接受的","ex":{"en":"She was always receptive to new ideas.","cn":"她总是愿意接受新观点。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对新思想或建议）乐于接受的，能接纳的，善于听取的","en":"Someone who is receptive to new ideas or suggestions is prepared to consider them or accept them.","ex":{"en":"The voters had seemed receptive to his ideas","cn":"选民看上去很愿意接受他的想法。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对治疗）反应良好的，能接纳的","en":"If someone who is ill is receptive to treatment, they start to get better when they are given treatment.","ex":{"en":"...those patients who are not receptive to treatment.","cn":"治疗未见效果的那些病人"}}]},"examples":[{"en":"He gave an impressive speech to a receptive audience.","cn":"他做了一次感人的讲演，听众深受感动。"},{"en":"She was always receptive to new ideas.","cn":"她总是愿意接受新观点。"}]},"respectful":{"media":{"uk":"media/uk/respectful__gb_1.mp3","us":"media/us/respectful__us_1.mp3"},"oxford":{"phon":"rɪˈspektfl","pos":"adjective","senses":[{"en":"showing or feeling respect","cn":"表示敬意的；尊敬的","ex":{"en":"The onlookers stood at a respectful distance.","cn":"旁观者站在一定的距离之外，以示尊敬。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"尊重人的;有礼貌的;恭敬的","en":"If you are respectful, you show respect for someone.","ex":{"en":"He was always so polite and respectful","cn":"他总是彬彬有礼，尊敬他人。"}}]},"examples":[{"en":"The onlookers stood at a respectful distance.","cn":"旁观者站在一定的距离之外，以示尊敬。"},{"en":"We were brought up to be respectful of authority.","cn":"我们从小就学会了尊重权威。"}]},"rescue":{"media":{"uk":"media/uk/rescue__gb_1.mp3","us":"media/us/rescue__us_1.mp3"},"oxford":{"phon":"ˈreskjuː","pos":"verb","senses":[{"en":"to save somebody/something from a dangerous or harmful situation","cn":"营救；援救；抢救","ex":{"en":"The coastguard rescued six people from the sinking boat.","cn":"海岸警卫队从沉船上救起来六个人。"}},{"en":"the act of saving somebody/something from a dangerous or difficult situation; the fact of being saved","cn":"救援；营救；抢救；获救","g":"[uncountable]","ex":{"en":"We had given up hope of rescue.","cn":"我们那时已经放弃了获救的希望。"},"pos":"noun"},{"en":"an occasion when somebody/something is saved from a dangerous or difficult situation","cn":"营救行动","g":"[countable]","ex":{"en":"Ten fishermen were saved in a daring sea rescue.","cn":"在一次惊心动魄的海上营救行动中，十名渔民获救。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"营救;救援;救助","en":"If you rescue someone, you get them out of a dangerous or unpleasant situation.","ex":{"en":"Helicopters rescued nearly 20 people from the roof of the burning building","cn":"直升机从失火大楼的楼顶救出了将近20人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"营救;救援;救助","en":"Rescue is help which gets someone out of a dangerous or unpleasant situation.","ex":{"en":"Lights clipped onto life jackets improve the chances of rescue","cn":"别在救生衣上的灯提高了获救可能性。"}},{"pos":"N-COUNT 可数名词","cn":"营救行动;救援行动;救助行为","en":"A rescue is an attempt to save someone from a dangerous or unpleasant situation.","ex":{"en":"A major air-sea rescue is under way","cn":"一场大规模的海空营救行动正在进行。"}},{"pos":"PHRASE 短语","cn":"前去营救;前来救援","en":"If you go to someone's rescue or come to their rescue, you help them when they are in danger or difficulty.","ex":{"en":"The 23-year-old's screams alerted a passerby who went to her rescue","cn":"那个23岁女孩的尖叫引来了一位过路人前去营救。"}}]},"examples":[{"en":"Ten fishermen were saved in a daring sea rescue.","cn":"在一次惊心动魄的海上营救行动中，十名渔民获救。"},{"en":"A wealthy benefactor came to their rescue with a generous donation.","cn":"一位富有的赞助人慷慨解囊挽救了他们。"}]},"refresh":{"media":{"uk":"media/uk/refresh__gb_1.mp3","us":"media/us/refresh__us_1.mp3"},"oxford":{"phon":"rɪˈfreʃ","pos":"verb","senses":[{"en":"to make somebody feel less tired or less hot","cn":"使恢复精力；使凉爽","g":"[transitive]","ex":{"en":"The long sleep had refreshed her.","cn":"一场酣睡使她重又精力充沛。"}},{"en":"to fill somebody’s glass or cup again","cn":"重新斟满","g":"[transitive]","lab":"especially North American English, informal，，","ex":{"en":"Let me refresh your glass.","cn":"我给你再斟一杯吧。"}},{"en":"to remind yourself/somebody of something, especially with the help of something that can be seen or heard","cn":"提醒；提示；使想起","g":"[transitive]","ex":{"en":"He had to refresh his memory by looking at his notes.","cn":"他不得不靠看笔记来提醒自己。"}},{"en":"to make the most recent information show, for example on an internet page","cn":"刷新（网页等）","g":"[transitive, intransitive]","lab":"computing","ex":{"en":"Click here to refresh this document.","cn":"点击此处以刷新文件。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使精神抖擞;使精神振奋;使重新充满活力","en":"If something refreshes you when you have become hot, tired, or thirsty, it makes you feel cooler or more energetic.","ex":{"en":"The lotion cools and refreshes the skin","cn":"这种润肤液凉爽清新，能够焕发肌肤的活力。"}},{"pos":"VERB 动词","cn":"翻新;使变新","en":"If you refresh something old or dull, you make it as good as it was when it was new.","ex":{"en":"Many view these meetings as an occasion to share ideas and refresh friendship","cn":"许多人把这些会面看成是交流想法和保持友谊长青的机会。"}},{"pos":"VERB 动词","cn":"使记起;提醒;提示","en":"If someone refreshes your memory, they tell you something that you had forgotten.","ex":{"en":"Allow me to refresh your memory","cn":"让我帮你回忆吧。"}},{"pos":"VERB 动词","cn":"刷新（网页）","en":"If you refresh a web page, you click a button in order to get the most recent version of the page.","ex":{"en":"Press the 'reload' button on your web browser to refresh the site and get the most current version.","cn":"点击网页浏览器上的“刷新”按钮来刷新页面，显示最新的版本。"}}]},"examples":[{"en":"He had to refresh his memory by looking at his notes.","cn":"他不得不靠看笔记来提醒自己。"},{"en":"The long sleep had refreshed her.","cn":"一场酣睡使她重又精力充沛。"}]},"resonant":{"oxford":{"phon":"ˈrezənənt","pos":"adjective","senses":[{"en":"deep, clear and continuing for a long time","cn":"嘹亮的；响亮的；回响的；悠扬的","lab":"formal","ex":{"en":"a deep resonant voice","cn":"深沉而响亮的声音"}},{"en":"causing sounds to continue for a long time","cn":"共振的；谐振的；共鸣的","lab":"specialist","ex":{"en":"resonant frequencies","cn":"谐振频率"}},{"en":"having the power to bring images, feelings, memories, etc. into your mind","cn":"引起联想的；产生共鸣的","lab":"literary","ex":{"en":"a poem filled with resonant imagery","cn":"充满了让人浮想联翩的意象的诗歌"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"洪亮的;嘹亮的","en":"A sound that is resonant is deep and strong.","ex":{"en":"His voice sounded oddly resonant in the empty room","cn":"他的声音在这空荡荡的房间里听起来异常嘹亮。"}},{"pos":"ADJ 形容词","cn":"有特殊意义的;引起共鸣的","en":"Something that is resonant has a special meaning or is particularly important to people.","ex":{"en":"It is a country resonant with cinematic potential, from its architecture to its landscape.","cn":"从建筑到风景，这个国家到处都体现出其成为电影拍摄地的潜力。"}}]},"media":{"uk":"media/uk/resonant__gb_1.mp3","us":"media/us/resonant__us_1.mp3"},"examples":[{"en":"a poem filled with resonant imagery","cn":"充满了让人浮想联翩的意象的诗歌"},{"en":"a deep resonant voice","cn":"深沉而响亮的声音"}]},"revolution":{"media":{"uk":"media/uk/revolution__gb_1.mp3","us":"media/us/revolution__us_1.mp3"},"oxford":{"phon":"ˌrevəˈluːʃn","pos":"noun","senses":[{"en":"an attempt, by a large number of people, to change the government of a country, especially by violent action","cn":"革命","g":"[countable, uncountable]","lab":"especially North American English","ex":{"en":"a socialist revolution","cn":"社会主义革命"}},{"en":"a great change in conditions, ways of working, beliefs, etc. that affects large numbers of people","cn":"巨变；大变革","g":"[countable]","ex":{"en":"a cultural/social/scientific, etc. revolution","cn":"文化、社会、科学等的重大变革"}},{"en":"a complete circular movement around a point","cn":"（绕中心点的）旋转","g":"[countable, uncountable]","ex":{"en":"The disk rotates at up to 500 revolutions per minute.","cn":"磁盘以高达每分钟 500 转的速度旋转。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"革命;武装运动","en":"A revolution is a successful attempt by a large group of people to change the political system of their country by force.","ex":{"en":"The period since the revolution has been one of political turmoil.","cn":"革命爆发后就陷入了政治动乱期。"}},{"pos":"N-COUNT 可数名词","cn":"重大变革;巨大变化","en":"A revolution in a particular area of human activity is an important change in that area.","ex":{"en":"The nineteenth century witnessed a revolution in ship design and propulsion.","cn":"19世纪船舶设计和船舶动力领域发生了重大的变革。"}}]},"examples":[{"en":"rotating at 300 revolutions per minute","cn":"以每分钟 300 转的速度旋转"},{"en":"A revolution in information technology is taking place.","cn":"信息技术正在发生巨变。"}]},"request":{"media":{"uk":"media/uk/request__gb_1.mp3","us":"media/us/request__us_1.mp3"},"oxford":{"phon":"rɪˈkwest","pos":"noun","senses":[{"en":"the action of asking for something formally and politely; a thing that you formally ask for","cn":"（正式或礼貌的）要求，请求；要求的东西","ex":{"en":"a request for information","cn":"索取资讯"}},{"en":"an instruction to a computer to perform a task","cn":"（计算机的）指令，命令","ex":{"en":"When the software has finished processing the request, a download window pops up.","cn":"当软件处理完请求后，会弹出一个下载窗口。"}},{"en":"a song or tune that somebody asks to have played on a radio programme","cn":"（广播电台中）点播的曲目","ex":{"en":"The next request is from a listener in Aberdeen.","cn":"下一首歌曲是阿伯丁的一位听众点播的。"}},{"en":"to ask for something or ask somebody to do something in a polite or formal way","cn":"（礼貌或正式地）请求，要求","lab":"British English also","ex":{"en":"She requested permission to film at the White House.","cn":"她申请准予在白宫拍摄。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"请求;要求","en":"If you request something, you ask for it politely or formally.","ex":{"en":"Mr Dennis said he had requested access to a telephone","cn":"丹尼斯先生说他已经请求使用电话。"}},{"pos":"VERB 动词","cn":"请求…做;要求…做","en":"If you request someone to do something, you politely or formally ask them to do it.","ex":{"en":"They requested him to leave","cn":"他们要求他离开。"}},{"pos":"N-COUNT 可数名词","cn":"请求;要求","en":"If you make a request, you politely or formally ask someone to do something.","ex":{"en":"France had agreed to his request for political asylum","cn":"法国已经同意了他寻求政治庇护的请求。"}},{"pos":"N-COUNT 可数名词","cn":"点播的乐曲","en":"A request is a song or piece of music which someone has asked a performer or disc jockey to play.","ex":{"en":"If you have any requests, I'd be happy to play them for you.","cn":"您点播任何歌曲，我都会很乐意为您演奏。"}},{"pos":"PHRASE 短语","cn":"应邀;应…的请求;按照…的要求","en":"If you do something at someone's request, you do it because they have asked you to.","ex":{"en":"The evacuation is being organised at the request of the United Nations Secretary General.","cn":"根据联合国秘书长的要求，正在组织撤退。"}},{"pos":"PHRASE 短语","cn":"一经要求;根据请求","en":"If something is given or done on request, it is given or done whenever you ask for it.","ex":{"en":"Leaflets giving details are available on request","cn":"备有介绍详情的传单以供索取。"}}]},"examples":[{"en":"She requested that no one be told of her decision until the next meeting.","cn":"她要求下次开会前不要向任何人透露她的决定。"},{"en":"( BrE also ) She requested that no one should be told of her decision.","cn":"她要求不要向任何人透露她的决定。"}]},"realizes":{"lemma":"realize","media":{"uk":"media/uk/realize__gb_1.mp3","us":"media/us/realize__us_1.mp3"}},"remarked":{"lemma":"remark"},"resigned":{"media":{"uk":"media/uk/resigned__gb_1.mp3","us":"media/us/resigned__us_1.mp3"},"oxford":{"phon":"rɪˈzaɪnd","pos":"adjective","senses":[{"en":"being willing to calmly accept something unpleasant or difficult that you cannot change","cn":"逆来顺受的；顺从的","ex":{"en":"a resigned sigh","cn":"无可奈何的叹息"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"屈从的;顺从的;勉强接受的;逆来顺受的","en":"If you are resigned to an unpleasant situation or fact, you accept it without complaining because you realize that you cannot change it.","ex":{"en":"He is resigned to the noise and mess","cn":"他勉强接受了这里的喧嚣和脏乱。"}}]},"examples":[{"en":"He was resigned to never seeing his birthplace again.","cn":"他认命了，甘愿永不再去他的出生地。"},{"en":"‘I suppose you're right,’ she said resignedly. “","cn":"看来你的话是对的。”她无奈地说。"}],"base":"resign"},"restaurant":{"media":{"uk":"media/uk/restaurant__gb_1.mp3","us":"media/us/restaurant__us_1.mp3"},"oxford":{"phon":"ˈrestrɒnt","pos":"noun","senses":[{"en":"a place where you can buy and eat a meal","cn":"餐馆；餐厅","lab":"especially British English","ex":{"en":"We're going to try this Italian restaurant that just opened.","cn":"我们打算去这家刚开张的意大利餐馆吃吃看。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"餐馆;饭店","en":"A restaurant is a place where you can eat a meal and pay for it. In restaurants your food is usually served to you at your table by a waiter or waitress. →see usage note at:","ex":{"en":"They ate in an Italian restaurant in Forth Street","cn":"他们在第四大街的一家意大利餐馆吃了饭。"}}]},"examples":[{"en":"We went out to a restaurant to celebrate.","cn":"我们到一家餐厅里庆祝了一番。"},{"en":"We had a meal in a restaurant.","cn":"我们在餐厅吃了顿饭。"}]},"restart":{"media":{"uk":"media/uk/restart__gb_1.mp3","us":"media/us/restart__us_1.mp3"},"oxford":{"phon":"ˈriːstɑːt","pos":"noun","senses":[{"en":"the act of starting again, or of making something start again, after it has stopped","cn":"（使）重新开始","ex":{"en":"He is in jail awaiting the restart of his trial for fraud.","cn":"他正在监狱中等待重新开始欺诈罪的审判。"}},{"en":"to start again, or to make something start again, after it has stopped","cn":"（使）重新开始","ex":{"en":"to restart a game","cn":"重新开始游戏"},"pos":"verb"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）重新开始;（使）重新启动","en":"If you restart something that has been interrupted or stopped, or if it restarts, it starts to happen or function again.","ex":{"en":"The commissioners agreed to restart talks as soon as possible","cn":"委员们同意尽快重新开始会谈。"}}]},"examples":[{"en":"The doctors struggled to restart his heart.","cn":"医生竭力重新起搏他的心脏。"},{"en":"to restart a game","cn":"重新开始游戏"}]},"resembles":{"lemma":"resemble","media":{"uk":"media/uk/resemble__gb_1.mp3","us":"media/us/resemble__us_1.mp3"}},"recycling":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"environmentally friendly products and methods do not damage the environment","cn":""},{"en":"involved with or relating to the protection of the environment - used before some adjectives and nouns","cn":""}]},"examples":[{"en":"Recycling is important to help protect our environment.","cn":"回收利用对保护环境很重要。","src":"ld"},{"en":"Don’t forget to take out the recycling.","cn":"别忘了把要回收利用的东西拿出来。","src":"ld"}],"media":{"uk":"media/uk/recycling__gb_1.mp3","us":"media/us/recycling__us_1.mp3"},"oxford":{"phon":"ˌriːˈsaɪklɪŋ","pos":"noun","senses":[{"en":"the process of treating things that have already been used so that they can be used again","cn":"回收利用；再利用","ex":{"en":"the recycling of glass","cn":"玻璃回收"}}]},"base":"recycle"},"republican":{"media":{"uk":"media/uk/republican__gb_1.mp3","us":"media/us/republican__us_1.mp3"},"oxford":{"phon":"rɪˈpʌblɪkən","pos":"noun","senses":[{"en":"a person who supports a form of government with a president and politicians elected by the people and with no king or queen","cn":"拥护共和政体的人；共和主义者"},{"en":"a member or supporter of the Republican Party of the US","cn":"（美国）共和党党员，共和党的支持者"},{"en":"a person from Northern Ireland who believes that Northern Ireland should be part of the Republic of Ireland and not part of the United Kingdom","cn":"北爱尔兰共和主义者（认为北爱尔兰应脱离英国回归爱尔兰共和国）"},{"en":"connected with or like a republic; supporting the principles of a republic","cn":"共和国的；共和政体的；拥护共和政体的","ex":{"en":"a republican government/movement","cn":"共和政体／运动"},"pos":"adjective"},{"en":"connected with the Republican Party in the US","cn":"（美国）共和党的","pos":"adjective"},{"en":"connected with or supporting the Republicans in Northern Ireland","cn":"北爱尔兰共和主义者的；支持北爱尔兰共和主义者的","pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"共和国的;共和政体的","en":"Republican means relating to a republic. In republican systems of government, power is held by the people or the representatives that they elect.","ex":{"en":"...the nations that had adopted the republican form of government.","cn":"实行共和政体的国家"}},{"pos":"ADJ 形容词","cn":"(美国)共和党的，支持共和党的","en":"In the United States, if someone is Republican, they belong to or support the Republican Party.","ex":{"en":"...Republican voters","cn":"支持共和党的选民们"}},{"pos":"ADJ 形容词","cn":"(支持北爱尔兰脱离英国加入爱尔兰共和国的)共和主义者，共和派","en":"In Northern Ireland, if someone is Republican, they believe that Northern Ireland should not be ruled by Britain but should become part of the Republic of Ireland.","ex":{"en":"...a Republican paramilitary group.","cn":"共和派的准军事组织"}}]},"examples":[{"en":"a strong commitment to Republicanism","cn":"对共和主义的强烈的信念"},{"en":"a republican government/movement","cn":"共和政体/运动"}]},"reading":{"media":{"uk":"media/uk/reading__gb_1.mp3","us":"media/us/reading__us_1.mp3"},"oxford":{"phon":"ˈriːdɪŋ","pos":"noun","senses":[{"en":"the activity of somebody who reads","cn":"阅读；读书活动","g":"[uncountable]","sc":"activity","ex":{"en":"My hobbies include reading and painting.","cn":"我的业余爱好包括读书和绘画。"}},{"en":"an act of reading something","cn":"阅读；宣读","g":"[singular]","sc":"activity","ex":{"en":"A closer (= more detailed) reading of the text reveals just how desperate he was feeling.","cn":"细读此文就会看出他当时感到多么绝望。"}},{"en":"books, articles, etc. that are intended to be read","cn":"读本；读物；阅读材料","g":"[uncountable]","sc":"books/articles","ex":{"en":"reading material","cn":"阅读材料"}},{"en":"the particular way in which you understand a book, situation, etc.","cn":"理解；解读","g":"[countable]","sc":"way of understanding","ex":{"en":"Those conclusions are based on a literal reading of the text.","cn":"那些结论是基于对文本的字面理解。"}},{"en":"the amount or number shown on an instrument used for measuring something","cn":"（仪表的）读数","g":"[countable]","sc":"measurement","ex":{"en":"Meter readings are taken every three months.","cn":"每三个月查一次表。"}},{"en":"an event at which something is read to an audience for entertainment; a piece of literature that is read at such an event","cn":"读书会；朗诵会；朗诵的作品","g":"[countable]","sc":"event","ex":{"en":"He was invited to give a poetry reading as part of the literary festival.","cn":"他应邀在文学节上表演诗朗诵。"}},{"en":"a short section from a holy text that is read to people as part of a religious service","cn":"（在礼拜仪式中读经环节）诵读的经文","g":"[countable]","sc":"from Bible","ex":{"en":"The reading today is from the Book of Daniel.","cn":"今天朗读的经文选自《但以理书》。"}},{"en":"one of the stages during which a bill (= a proposal for a new law) must be discussed and accepted by a parliament before it can become law","cn":"议案宣读（法案在成为法律前须经议会讨论通过的步骤）","g":"[countable]","sc":"in parliament","ex":{"en":"The bill looks like it will be given a second reading.","cn":"该法案看起来将进行二读。"}},{"en":"a large town in southern England, governed by a unitary authority. It is famous for its music festivals, especially the Reading Rock Festival. Oscar Wilde spent two years in Reading prison (1895-7), and he wrote his Ballad of Reading Gaol there.","cn":"雷丁（英格兰南部大城镇。奥斯卡 · 王尔德 1895-97 年在雷丁监狱服刑两年，在狱中写下了《雷丁监狱之歌》。雷丁亦以音乐节而闻名）","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"阅读；读书","en":"Reading is the activity of reading books.","ex":{"en":"I have always loved reading.","cn":"我一直喜欢读书。"}},{"pos":"N-COUNT 可数名词","cn":"读书会;朗诵会","en":"A reading is an event at which poetry or extracts from books are read to an audience.","ex":{"en":"This year's event consisted of readings, lectures and workshops.","cn":"今年的活动包括读书会、讲座和研讨会。"}},{"pos":"N-COUNT 可数名词","cn":"理解方法;解读方法","en":"Your reading of a word, text, or situation is the way in which you understand or interpret it.","ex":{"en":"My reading of her character makes me feel that she was too responsible a person to do those things","cn":"照我对她的性格的了解来看，她是个特别负责任的人，不会做出那些事情的。"}},{"pos":"N-COUNT 可数名词","cn":"（测量仪器上的）读数，计量","en":"The reading on a measuring device is the figure or measurement that it shows.","ex":{"en":"Once you have recorded the reading, shake the thermometer down to below 36 degrees","cn":"一旦完成计数，把温度计标数甩到36度以下。"}},{"pos":"N-COUNT 可数名词","cn":"（英国议会或美国国会讨论一项新法案以获通过的三步立法程序之一）议案宣读","en":"In the British Parliament or the US Congress, a reading is one of the three stages of introducing and discussing a new bill before it can be passed as law.","ex":{"en":"The bill is expected to pass its second reading with a comfortable majority.","cn":"预计这项法案将以绝大多数赞成而通过议会第二次宣读。"}},{"pos":"PHRASE 短语","cn":"读起来感觉…","en":"If you say that a book or an article makes interesting reading or makes for interesting reading, you mean that it is interesting to read.","ex":{"en":"The list of drinks, a dozen pages long, makes fascinating reading","cn":"酒水单一共有十几页长，读起来很有趣。"}}]},"examples":[{"en":"A closer (= more detailed) reading of the text reveals just how desperate he was feeling.","cn":"细读此文就会看出他当时感到多么绝望。"},{"en":"The evening ended with a reading from her latest novel.","cn":"晚会最后朗诵了一段她的最新小说。"}],"base":"read"},"rebuke":{"media":{"uk":"media/uk/rebuke__gb_1.mp3","us":"media/us/rebuke__us_1.mp3"},"oxford":{"phon":"rɪˈbjuːk","pos":"noun","senses":[{"en":"the act of speaking severely to somebody because they have done something wrong","cn":"指责；批评","ex":{"en":"He was silenced by her stinging rebuke.","cn":"她的尖锐批评使他哑口无言。"}},{"en":"to speak severely to somebody because they have done something wrong","cn":"指责；批评","ex":{"en":"The company was publicly rebuked for having neglected safety procedures.","cn":"公司因忽略了安全规程而受到公开批评。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"指责；非难；谴责","en":"If you rebuke someone, you speak severely to them because they have said or done something that you do not approve of.","ex":{"en":"The president rebuked the House and Senate for not passing those bills within 100 days.","cn":"总统谴责参众两院没有在100天之内通过那些法案。"}}]},"examples":[{"en":"The company was publicly rebuked for having neglected safety procedures.","cn":"公司因忽略了安全措施而受到公开批评。"},{"en":"He was silenced by her stinging rebuke.","cn":"她的尖锐批评使他哑口无言。"}]},"renewables":{"media":{"uk":"media/uk/renewables__gb_3.mp3","us":"media/us/renewables__us_3.mp3"},"oxford":{"phon":"rɪˈnjuːəblz","pos":"noun","senses":[{"en":"types of energy that can be replaced naturally such as energy produced from wind or water","cn":"可再生能源","lab":"especially British English","ex":{"en":"renewables such as hydro-electricity and solar energy","cn":"水力发电和太阳能之类的可再生能源"}}]},"examples":[{"en":"renewables such as hydroelectricity and solar energy","cn":"水力发电和太阳能之类的可再生能源"},{"en":"investment in renewables","cn":"对可再生能源的投资"}]},"reed":{"oxford":{"phon":"riːd","pos":"noun","senses":[{"en":"a tall plant like grass with a hollow stem that grows in or near water","cn":"芦苇","ex":{"en":"reed beds (= where they grow)","cn":"芦苇荡"}},{"en":"a small thin piece of cane, metal or plastic in some musical instruments such as the oboe or the clarinet that moves very quickly when air is blown over it, producing a sound","cn":"簧舌，簧片（金属或塑料制成，用于双簧管、单簧管等吹奏乐器）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"芦苇","en":"Reeds are tall plants that grow in large groups in shallow water or on ground that is always wet and soft. They have strong, hollow stems that can be used for making things such as mats or baskets."},{"pos":"N-COUNT 可数名词","cn":"（木管乐器中的）簧片","en":"A reed is a small piece of cane or metal inserted into the mouthpiece of a woodwind instrument. The reed vibrates when you blow through it and makes a sound."}]},"media":{"img":["media/pic/plantlabels_plants_comp.jpg","media/thumb/reed.jpg"],"uk":"media/uk/reed__gb_1.mp3","us":"media/us/reed__us_1.mp3"},"examples":[{"en":"reed beds (= where they grow)","cn":"芦苇荡"},{"en":"Reeds grew in clumps all along the river bank.","cn":"沿河岸长着一丛丛芦苇。"}]},"reason":{"media":{"uk":"media/uk/reason__gb_1.mp3","us":"media/us/reason__us_1.mp3"},"oxford":{"phon":"ˈriːzn","pos":"noun","senses":[{"en":"a cause or an explanation for something that has happened or that somebody has done","cn":"原因；理由；解释","g":"[countable]","lab":"formal","ex":{"en":"He said no but he didn't give a reason.","cn":"他说不行，但没有说明原因。"}},{"en":"a fact that makes it right or fair to do something","cn":"正当理由；道理；情理","g":"[uncountable]","ex":{"en":"They have reason to believe she is lying.","cn":"他们有理由相信她在撒谎。"}},{"en":"the power of the mind to think in a logical way, to understand and have opinions, etc.","cn":"思考力；理解力；理性","g":"[uncountable]","ex":{"en":"Only human beings are capable of reason (= of thinking in a logical way, etc.).","cn":"只有人类才有理性思考的能力。"}},{"en":"what is possible, practical or right","cn":"道理；情理；明智","g":"[uncountable]","ex":{"en":"I can't get her to listen to reason.","cn":"我没法跟她讲道理。"}},{"en":"to form a judgement about a situation by considering the facts and using your power to think in a logical way","cn":"推理；推论；推断","g":"[transitive, intransitive]","ex":{"en":"She reasoned that she must have left her bag on the train.","cn":"她断定她准是把包落在火车上了。"},"pos":"verb"},{"en":"to use your power to think and understand","cn":"思考；理解","g":"[intransitive]","ex":{"en":"the human ability to reason","cn":"人的思考能力"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"原因；理由；动机","en":"The reason for something is a fact or situation which explains why it happens or what causes it to happen.","ex":{"en":"There is a reason for every important thing that happens","cn":"每件重要事情的发生都有原因。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"理由；确凿的证据","en":"If you say that you have reason to believe something or to have a particular emotion, you mean that you have evidence for your belief or there is a definite cause of your feeling.","ex":{"en":"They had reason to believe there could be trouble","cn":"他们有理由相信可能会遇到麻烦。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"理性;理智","en":"The ability that people have to think and to make sensible judgments can be referred to as reason .","ex":{"en":"...a conflict between emotion and reason","cn":"情感和理智的冲突"}},{"pos":"VERB 动词","cn":"推理;推论;推断","en":"If you reason that something is true, you decide that it is true after thinking carefully about all the facts.","ex":{"en":"I reasoned that changing my diet would lower my cholesterol level","cn":"我推断改变自己的饮食可以降低我的胆固醇水平。"}},{"pos":"PHRASE 短语","cn":"（常用来暗指不赞成某人的所作所为）只有自己知道为什么，出于自身的理由","en":"If you do not know why someone did something, you can say that they did it for reasons best known to themselves. You usually use this expression when you do not agree with what they did.","ex":{"en":"For reasons best known to himself, Algie changed his name.","cn":"不知是出于什么原因，阿尔吉改了名字。"}},{"pos":"PHRASE 短语","cn":"因为；由于；由…引起；以…为理由","en":"If one thing happens by reason of another, it happens because of it.","ex":{"en":"The boss retains enormous influence by reason of his position","cn":"老板由于自身的地位而一直有极大的影响力。"}},{"pos":"PHRASE 短语","cn":"听从劝告;理智行事","en":"If you try to make someone listen to reason, you try to persuade them to listen to sensible arguments and be influenced by them.","ex":{"en":"The company's top executives had refused to listen to reason.","cn":"公司的高层管理人员拒绝理智行事。"}},{"pos":"PHRASE 短语","cn":"无缘无故；莫名其妙；没有理由","en":"If you say that something happened or was done for no reason ,for no good reason, or for no reason at all, you mean that there was no obvious reason why it happened or was done.","ex":{"en":"The guards, he said, would punch them for no reason","cn":"他说警卫会无缘无故殴打他们。"}},{"pos":"PHRASE 短语","cn":"活着的理由；生存的原因","en":"If a person or thing is someone's reason for living or their reason for being, they are the most important thing in that person's life.","ex":{"en":"Chloe is my reason for living.","cn":"克洛艾是我活着的理由。"}},{"pos":"PHRASE 短语","cn":"不知为何;不知什么原因","en":"If you say that something happened or is true for some reason, you mean that you know it happened or is true, but you do not know why.","ex":{"en":"For some reason, the curtains were shut","cn":"不知什么原因，窗帘拉着。"}},{"pos":"PHRASE 短语","cn":"正当的;合乎情理的;理智范围内的","en":"If you say that you will do anything within reason, you mean that you will do anything that is fair or reasonable and not too extreme.","ex":{"en":"I will take any job that comes along, within reason","cn":"我会接受任何给我的工作，只要是正当的。"}},{"pos":"","cn":"","en":"rhyme or reason→see: ; to reason→see: ; it stands to reason→see: ;"},{"pos":"","cn":"","en":"相关词组：reason with"}]},"examples":[{"en":"They couldn't fire him, he reasoned. He was the only one who knew how the system worked.","cn":"他推断他们不会解雇他。他是唯一知道这套系统如何运转的人。"},{"en":"He wants to keep them all in his office for reasons best known to himself.","cn":"他想把他们都留在他的办公室里，原因只有他自己知道。"}]},"research":{"media":{"uk":"media/uk/research__gb_1.mp3","us":"media/us/research__us_1.mp3"},"oxford":{"phon":"rɪˈsɜːtʃ","pos":"noun","senses":[{"en":"a careful study of a subject, especially in order to discover new facts or information about it","cn":"研究；调查；探索","lab":"British English","ex":{"en":"scientific/medical/academic research","cn":"科学／医学／学术研究"}},{"en":"to study something carefully and try to discover new facts about it","cn":"研究；探讨；调查","ex":{"en":"to research a topic/subject","cn":"研究一个主题／课题"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"研究;探索","en":"Research is work that involves studying something and trying to discover facts about it.","ex":{"en":"65 percent of the 1987 budget went for nuclear weapons research and production.","cn":"1987年65％的预算经费被用于核武器的研究和生产。"}},{"pos":"VERB 动词","cn":"调查;发掘","en":"If you research something, you try to discover facts about it.","ex":{"en":"She spent two years in South Florida researching and filming her documentary","cn":"她花了两年时间在佛罗里达州南部做研究，拍摄纪录片。"}}]},"examples":[{"en":"Recent research on deaf children has produced some interesting findings about their speech.","cn":"对失聪儿童的最新研究已经在说话方面取得了一些令人关注的结果。"},{"en":"I've done some research to find out the cheapest way of travelling there.","cn":"我查阅了一番，想找到去那里最省钱的方式。"}]},"residue":{"oxford":{"phon":"ˈrezɪdjuː","pos":"noun","senses":[{"en":"a small amount of something that remains at the end of a process","cn":"剩余物；残留物；残渣","ex":{"en":"pesticide residues in fruit and vegetables","cn":"残留在水果和蔬菜中的杀虫剂"}},{"en":"the part of the money, property, etc. of a person who has died that remains after all the debts, gifts, etc. have been paid","cn":"剩余遗产","lab":"law","ex":{"en":"The residue of the estate was divided equally among his children.","cn":"剩余遗产被他的孩子平分了。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"残余物;遗留物;残渣","en":"A residue of something is a small amount that remains after most of it has gone.","ex":{"en":"Always using the same shampoo means that a residue can build up on the hair.","cn":"总是用同一种洗发水就意味着某种残留物会在头发上越积越多。"}}]},"media":{"uk":"media/uk/residue__gb_1.mp3","us":"media/us/residue__us_1.mp3"},"examples":[{"en":"pesticide residues in fruit and vegetables","cn":"残留在水果和蔬菜中的杀虫剂"},{"en":"The residue of the estate was divided equally among his children.","cn":"剩余遗产被他的孩子平分了。"}]},"recently":{"media":{"uk":"media/uk/recently__gb_1.mp3","us":"media/us/recently__us_1.mp3"},"oxford":{"phon":"ˈriːsntli","pos":"adverb","senses":[{"en":"not long ago","cn":"不久前；最近","ex":{"en":"a recently published book","cn":"最近出版的一本书"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"近来；最近","en":"If you have done something recently or if something happened recently, it happened only a short time ago.","ex":{"en":"The bank recently opened a branch in Germany","cn":"这家银行最近在德国开设了分行。"}}]},"examples":[{"en":"We received a letter from him recently.","cn":"我们不久以前收到了他的一封信。"},{"en":"Until recently they were living in York.","cn":"他们不久以前还住在约克。"}]},"resist":{"media":{"uk":"media/uk/resist__gb_1.mp3","us":"media/us/resist__us_1.mp3"},"oxford":{"phon":"rɪˈzɪst","pos":"verb","senses":[{"en":"to refuse to accept something and try to stop it from happening","cn":"抵制；阻挡","g":"[transitive, intransitive]","ex":{"en":"They are determined to resist pressure to change the law.","cn":"他们决心顶住要求改革法律的压力。"}},{"en":"to fight back when attacked; to use force to stop something from happening","cn":"反抗；回击；抵抗","g":"[intransitive, transitive]","ex":{"en":"He tried to pin me down, but I resisted.","cn":"他试图按住我，但我奋力反抗。"}},{"en":"to stop yourself from having something you like or doing something you very much want to do","cn":"忍住；抵挡","g":"[transitive]","ex":{"en":"I finished the cake. I couldn't resist it.","cn":"我忍不住把整块蛋糕都吃了。"}},{"en":"to not be harmed or damaged by something","cn":"使不受…的伤害；抗（伤害）","g":"[transitive]","ex":{"en":"A healthy diet should help your body resist infection.","cn":"健康饮食有助于身体抗感染。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"抵抗;抵制;反对","en":"If you resist something such as a change, you refuse to accept it and try to prevent it.","ex":{"en":"She says she will resist a single European currency being imposed","cn":"她说她会反对在欧洲推行单一货币。"}},{"pos":"VERB 动词","cn":"抵御;抵抗","en":"If you resist someone or resist an attack by them, you fight back against them.","ex":{"en":"The man was shot outside his house as he tried to resist arrest","cn":"该男子在其住宅外拒捕时被击毙。"}},{"pos":"VERB 动词","cn":"按捺;克制;忍住","en":"If you resist doing something, or resist the temptation to do it, you stop yourself from doing it although you would like to do it.","ex":{"en":"Students should resist the temptation to focus on exams alone","cn":"学生们应当抵制诱惑，集中精力备考。"}},{"pos":"VERB 动词","cn":"经得起;耐得住;抵挡","en":"If someone or something resists damage of some kind, they are not damaged.","ex":{"en":"...bodies trained and toughened to resist the cold","cn":"经过训练和磨炼，可以抵御寒冷的身体"}}]},"examples":[{"en":"They are determined to resist pressure to change the law.","cn":"他们决心顶住要求改革法律的压力。"},{"en":"He tried to pin me down, but I resisted.","cn":"他试图制伏我，但我奋力反抗。"}]},"reserved":{"media":{"uk":"media/uk/reserved__gb_1.mp3","us":"media/us/reserved__us_1.mp3"},"oxford":{"phon":"rɪˈzɜːvd","pos":"adjective","senses":[{"en":"slow or unwilling to show feelings or express opinions","cn":"内向的；寡言少语的；矜持的","ex":{"en":"Neighbours described him as a reserved man who didn't mix much.","cn":"邻居称他是个内向的人，不怎么与人交往。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"矜持的;内敛的;寡言少语的","en":"Someone who is reserved keeps their feelings hidden.","ex":{"en":"He was unemotional, quite quiet, and reserved","cn":"他感情淡漠，沉默寡言，性格内敛。"}},{"pos":"ADJ 形容词","cn":"预订的;保留的;预约的","en":"A table in a restaurant or a seat in a theatre that is reserved is being kept for someone rather than given or sold to anyone else.","ex":{"en":"Seats, or sometimes entire tables, were reserved.","cn":"一些散座，有时候是整桌，都被预订了。"}}]},"examples":[{"en":"Ellen was a shy, reserved girl.","cn":"埃伦是个腼腆﹑寡言的姑娘。"}],"base":"reserve"},"requirement":{"media":{"uk":"media/uk/requirement__gb_1.mp3","us":"media/us/requirement__us_1.mp3"},"oxford":{"phon":"rɪˈkwaɪəmənt","pos":"noun","senses":[{"en":"something that you need or want","cn":"所需的（或所要的）东西","g":"[plural]","ex":{"en":"the basic requirements of life","cn":"基本生活所需"}},{"en":"something that you must have in order to do something else","cn":"必要条件；必备的条件","ex":{"en":"to meet/fulfil/satisfy the requirements","cn":"符合／具备／满足必备的条件"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"要求;需求;必要条件","en":"A requirement is a quality or qualification that you must have in order to be allowed to do something or to be suitable for something.","ex":{"en":"Its products met all legal requirements","cn":"它的产品符合所有的法律要求。"}},{"pos":"N-COUNT 可数名词","cn":"必需品;需要的东西","en":"Your requirements are the things that you need.","ex":{"en":"Variations of this programme can be arranged to suit your requirements.","cn":"本方案可以进行调整，以满足您的需求。"}}]},"examples":[{"en":"What is the minimum entrance requirement for this course?","cn":"这门课程的基本入学条件是什么？"},{"en":"These goods are surplus to requirements (= more than we need).","cn":"这些货物超过了我们的需要。"}]},"relax":{"oxford":{"phon":"rɪˈlæks","pos":"verb","senses":[{"en":"to rest while you are doing something that you enjoy, especially after work or effort","cn":"放松；休息","g":"[intransitive]","ex":{"en":"Just relax and enjoy the movie.","cn":"休息休息，看看电影吧。"}},{"en":"to become or make somebody become calmer and less worried","cn":"宽慰；（使）冷静，放心，镇定","g":"[intransitive, transitive]","ex":{"en":"I'll only relax when I know you're safe.","cn":"我只有知道你安然无恙才会放心。"}},{"en":"to become or make something become less tight or stiff","cn":"（使）放松，松懈；松开","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"Allow your muscles to relax completely.","cn":"让你的肌肉完全放松。"}},{"en":"to allow rules, laws, etc. to become less strict","cn":"放宽（限制等）","g":"[transitive]","ex":{"en":"to relax rules/restrictions/regulations/requirements","cn":"放宽规则／限制／规定／要求"}},{"en":"to allow your attention or effort to become weaker","cn":"放松精神（或思想）","g":"[transitive]","ex":{"en":"You cannot afford to relax your concentration for a moment.","cn":"你必须集中精力，一刻都不能松懈。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)放松;(使)松弛","en":"If you relax or if something relaxes you, you feel more calm and less worried or tense.","ex":{"en":"I ought to relax and stop worrying about it","cn":"我应该放松一下，不要再担心它了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使）（身体)放松;（使）松弛","en":"When a part of your body relaxes, or when you relax it, it becomes less stiff or firm.","ex":{"en":"Massage is used to relax muscles, relieve stress and improve the circulation","cn":"按摩可以使肌肉放松，缓解压力和促进血液循环。"}},{"pos":"VERB 动词","cn":"松手;放开;放松","en":"If you relax your grip or hold on something, you hold it less tightly than before.","ex":{"en":"He gradually relaxed his grip on the arms of the chair.","cn":"他紧握椅子扶手的手逐渐松开了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"放宽，放松，削弱(规定或控制)","en":"If you relax a rule or your control over something, or if it relaxes, it becomes less firm or strong.","ex":{"en":"Rules governing student conduct relaxed somewhat in recent years","cn":"近年来约束学生行为的规定有所放宽。"}}]},"media":{"uk":"media/uk/relax__gb_1.mp3","us":"media/us/relax__us_1.mp3"},"examples":[{"en":"The council has relaxed the ban on dogs in city parks.","cn":"委员会已经放宽了对带狗到市内公园里去的禁令。"},{"en":"When I get home from work I like to relax with the newspaper.","cn":"我下班回到家里，喜欢看看报纸，放松一下。"}]},"removal":{"media":{"uk":"media/uk/removal__gb_1.mp3","us":"media/us/removal__us_1.mp3"},"oxford":{"phon":"rɪˈmuːvl","pos":"noun","senses":[{"en":"the act of taking somebody/something away from a particular place","cn":"移动；调动；去除","g":"[uncountable]","ex":{"en":"Clearance of the site required the removal of a number of trees.","cn":"清理这一场所需要移走不少树。"}},{"en":"the act of getting rid of something","cn":"除去；消除；清除","g":"[uncountable]","ex":{"en":"stain removal","cn":"清除污渍"}},{"en":"the act of dismissing somebody from their job","cn":"免职；解职","g":"[uncountable]","ex":{"en":"events leading to the removal of the president from office","cn":"导致总统下台的一些事件"}},{"en":"an act of taking furniture, etc. from one house to another","cn":"搬迁；迁移","g":"[countable]","lab":"British English","ex":{"en":"house removals","cn":"搬家"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"消除;去除","en":"The removal of something is the act of removing it.","ex":{"en":"What they expected to be the removal of a small lump turned out to be major surgery","cn":"他们原以为只需切除小肿块的手术最后变成了一次大手术。"}},{"pos":"N-VAR 可变名词","cn":"搬家;搬移;搬迁","en":"Removal is the process of transporting furniture or equipment from one building to another.","ex":{"en":"Home removals are best done in cool weather","cn":"最好在天气凉爽时搬家。"}}]},"examples":[{"en":"Clearance of the site required the removal of a number of trees.","cn":"清理这一场所需要移走不少树。"},{"en":"events leading to the removal of the president from office","cn":"导致总统下台的一些事件"}]},"rewarding":{"media":{"uk":"media/uk/rewarding__gb_1.mp3","us":"media/us/rewarding__us_1.mp3"},"oxford":{"phon":"rɪˈwɔːdɪŋ","pos":"adjective","senses":[{"en":"worth doing; that makes you happy because you think it is useful or important","cn":"值得做的；有益的","ex":{"en":"a rewarding experience/job","cn":"有益的经历／工作"}},{"en":"producing a lot of money","cn":"报酬高的","ex":{"en":"Teaching is not very financially rewarding (= is not very well paid).","cn":"教书不会有很高的报酬。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有益的;值得的;有意义的;令人满意的","en":"An experience or action that is rewarding gives you satisfaction or brings you benefits.","ex":{"en":"...a career which she found stimulating and rewarding","cn":"她觉得刺激而有意义的职业"}}]},"examples":[{"en":"Teaching is not very financially rewarding (= is not very well paid).","cn":"教书不会有很高的报酬。"},{"en":"a rewarding experience/job","cn":"有益的经历/工作"}],"base":"reward"},"remove":{"oxford":{"phon":"rɪˈmuːv","pos":"verb","senses":[{"en":"to take somebody/something away from a place","cn":"移开；拿开；去掉；从…机构开除","ex":{"en":"Illegally parked vehicles will be removed.","cn":"非法停放的车辆将被拖走。"}},{"en":"to take off clothing, etc. from the body","cn":"脱去（衣服等）；摘下","ex":{"en":"She removed her glasses and rubbed her eyes.","cn":"她摘下眼镜，揉了揉眼睛。"}},{"en":"to get rid of something unpleasant, dirty, etc.; to make something disappear","cn":"去除，排除（污渍、不愉快的事物等）；使消失","ex":{"en":"She has had the tumour removed.","cn":"她已经将肿瘤切除了。"}},{"en":"to dismiss somebody from their position or job","cn":"免除，解除（职务等）","ex":{"en":"The elections removed the government from power.","cn":"这几次选举使得政府倒台。"}},{"en":"an amount by which two things are separated","cn":"距离；差距；间距","ex":{"en":"Charlotte seemed to be living at one remove from reality.","cn":"夏洛特好像生活在现实之外。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"移动;搬动;取出","en":"If you remove something from a place, you take it away.","ex":{"en":"As soon as the cake is done, remove it from the oven","cn":"蛋糕一烤好，立即把它从烤箱中取出。"}},{"pos":"VERB 动词","cn":"脱下(衣服)","en":"If you remove clothing, you take it off.","ex":{"en":"He removed his jacket.","cn":"他脱下了夹克。"}},{"pos":"VERB 动词","cn":"(用化学品)去除，洗掉(污渍)","en":"If you remove a stain from something, you make the stain disappear by treating it with a chemical or by washing it.","ex":{"en":"This treatment removes the most stubborn stains","cn":"这种处理方式会清除最顽固的污渍。"}},{"pos":"VERB 动词","cn":"免除(职务)","en":"If people remove someone from power or from something such as a committee, they stop them being in power or being a member of the committee.","ex":{"en":"The student senate voted to remove Fuller from office","cn":"学生评议会投票免除了富勒的职位。"}},{"pos":"VERB 动词","cn":"消除(障碍);取消(限制);解决(问题)","en":"If you remove an obstacle, a restriction, or a problem, you get rid of it.","ex":{"en":"The agreement removes the last serious obstacle to the signing of the arms treaty","cn":"这个协议排除了签订武器条约的最后一个严重障碍。"}},{"pos":"PHRASE 短语","cn":"间接地","en":"If you do or experience something at one remove, you do not do it or experience it yourself, but someone else does it or experiences it instead of you.","ex":{"en":"She enjoyed his company and the excitement of feeling herself linked at one remove to London society","cn":"她喜欢他的陪伴，也很享受离伦敦社交圈仅仅一步之遥的兴奋感觉。"}}]},"media":{"uk":"media/uk/remove__gb_1.mp3","us":"media/us/remove__us_1.mp3"},"examples":[{"en":"He's my cousin's son so he's my first cousin once removed.","cn":"他是我表兄的儿子，所以他是我隔了一代的表亲。"},{"en":"Many of these books are far removed from the reality of the children's lives.","cn":"很多这样的书都远远地脱离了孩子们的现实生活。"}]},"reception":{"media":{"uk":"media/uk/reception__gb_1.mp3","us":"media/us/reception__us_1.mp3"},"oxford":{"phon":"rɪˈsepʃn","pos":"noun","senses":[{"en":"the area inside the entrance of a hotel, an office building, etc. where guests or visitors go first when they arrive","cn":"接待处；接待区","g":"[uncountable]","lab":"especially British English","ex":{"en":"Please report to reception on arrival.","cn":"到达后请立即到接待处报到。"}},{"en":"a formal social occasion to welcome somebody or celebrate something","cn":"接待仪式；欢迎会；招待会","g":"[countable]","ex":{"en":"Are you having a big reception after the wedding?","cn":"婚礼后你们要举行大型招待会吗？"}},{"en":"the type of welcome that is given to somebody/something","cn":"欢迎；反应；反响","g":"[singular]","ex":{"en":"The reception from critics and audiences was at best lukewarm","cn":"评论家和观众的反应充其量是冷淡的"}},{"en":"the quality of radio and television signals that are broadcast","cn":"（无线电和电视信号的）接收效果","g":"[uncountable]","ex":{"en":"good/bad reception","cn":"良好的／差的接收效果"}},{"en":"the act of receiving or welcoming somebody","cn":"接纳；接待；迎接","g":"[uncountable]","ex":{"en":"The locals provided facilities for the reception of children from the war zone.","cn":"当地人提供设施接收来自战区的儿童。"}},{"en":"the first class at school for children aged 4 or 5","cn":"（为 4 至 5 岁儿童开设的）学前班，预备班","g":"[uncountable]","ex":{"en":"My son is in reception.","cn":"我儿子在预备班。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（宾馆的）前台，服务台","en":"The reception in a hotel is the desk or office that books rooms for people and answers their questions.","ex":{"en":"Have him bring a car round to the reception","cn":"让他把车开到前台来。"}},{"pos":"N-SING 单数名词","cn":"（办公室或医院的）接待处，服务台","en":"The reception in an office or hospital is the place where people's appointments and questions are dealt with.","ex":{"en":"Wait at reception for me.","cn":"在接待处等我。"}},{"pos":"N-COUNT 可数名词","cn":"招待会;欢迎会","en":"A reception is a formal party which is given to welcome someone or to celebrate a special event.","ex":{"en":"At the reception they served smoked salmon.","cn":"招待会的餐桌上有熏制鲑鱼。"}},{"pos":"N-COUNT 可数名词","cn":"对待;待遇;反应","en":"If someone or something has a particular kind of reception, that is the way that people react to them.","ex":{"en":"Mr Mandela was given a tumultuous reception in Washington","cn":"曼德拉先生在华盛顿受到热情的款待。"}},{"pos":"N-SING 单数名词","cn":"（正式的）招待，接待，欢迎","en":"The reception of guests is the act of formally welcoming them.","ex":{"en":"The preparations for the reception of his Royal Highness proceeded.","cn":"迎接殿下到来的准备工作在有序进行。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（无线电或电视节目的）接收效果","en":"If you get good reception from your radio or television, the sound or picture is clear because the signal is strong. If the reception is poor, the sound or picture is unclear because the signal is weak.","ex":{"en":"Adjust the aerial's position and direction for the best reception.","cn":"调整天线的位置和方向以达到最佳接收效果。"}}]},"examples":[{"en":"Delegates gave him a warm reception as he called for more spending on education.","cn":"由于他呼吁增加教育经费，代表们向他报以热烈的欢迎。"},{"en":"We arranged to meet in reception at 6.30.","cn":"我们约定 6:30 在接待处会面。"}]},"relaxing":{"media":{"uk":"media/uk/relaxing__gb_1.mp3","us":"media/us/relaxing__us_1.mp3"},"oxford":{"phon":"rɪˈlæksɪŋ","pos":"adjective","senses":[{"en":"helping you to rest and become less anxious","cn":"有助于休息的；令人放松的；轻松的","ex":{"en":"a relaxing evening with friends","cn":"和朋友在一起的轻松夜晚"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愉快的;放松的","en":"Something that is relaxing is pleasant and helps you to relax.","ex":{"en":"I find cooking very relaxing","cn":"我发现烹饪可以令人非常放松。"}}]},"examples":[{"en":"a relaxing evening with friends","cn":"和朋友在一起的轻松夜晚"},{"en":"a relaxing evening at home","cn":"在家里度过的一个轻松的夜晚"}],"base":"relax"},"resonance":{"media":{"uk":"media/uk/resonance__gb_1.mp3","us":"media/us/resonance__us_1.mp3"},"oxford":{"phon":"ˈrezənəns","pos":"noun","senses":[{"en":"the quality of being resonant","cn":"洪亮；响亮","g":"[uncountable]","lab":"formal","ex":{"en":"Her voice had a strange and thrilling resonance.","cn":"她的声音洪亮，有一种奇特的震撼人心的效果。"}},{"en":"the sound or other vibration produced in an object by sound or vibrations of a similar frequency from another object","cn":"共鸣；共振；谐振","g":"[countable, uncountable]","lab":"specialist"},{"en":"the power to bring images, feelings, etc. into the mind of the person reading or listening; the images, etc. produced in this way","cn":"激发联想的力量；引起共鸣的力量；引起的联想（或共鸣）","g":"[uncountable, countable]","lab":"formal"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"共鸣;特殊意义","en":"If something has a resonance for someone, it has a special meaning or is particularly important to them.","ex":{"en":"The ideas of order, security, family, religion and country had the same resonance for them as for Michael.","cn":"秩序、安全、家庭、宗教和国家这些概念对于他们和迈克尔来说有着同样特殊的意义。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"嘹亮;洪亮","en":"If a sound has resonance, it is deep, clear, and strong.","ex":{"en":"His voice had lost its resonance; it was tense and strained.","cn":"他的声音不再洪亮，而是显得紧张，不太自然。"}},{"pos":"N-VAR 可变名词","cn":"共鸣;共振;谐振","en":"A resonance is the sound which is produced by an object when it vibrates at the same rate as the sound waves from another object.","ex":{"en":"The ear has a set of filaments to vibrate in resonance with incoming sound-waves.","cn":"耳朵里有一组细丝能和进入的声波产生共振。"}}]},"examples":[{"en":"Her voice had a strange and thrilling resonance.","cn":"她的声音洪亮，有一种奇特的震撼人心的效果。"},{"en":"a tradition that has little resonance in the 21st century","cn":"在21世纪难以引起共鸣的传统"}]},"relate":{"media":{"uk":"media/uk/relate__gb_1.mp3","us":"media/us/relate__us_1.mp3"},"oxford":{"phon":"rɪˈleɪt","pos":"verb","senses":[{"en":"show or make a connection between two or more things","cn":"联系；使有联系；把…联系起来","ex":{"en":"I found it difficult to relate the two ideas in my mind.","cn":"我觉得很难把这两种想法联系在一起。"}},{"en":"to give a spoken or written report of something; to tell a story","cn":"叙述；讲述；讲（故事）","lab":"formal","ex":{"en":"Then he related a story about his days working in a research laboratory.","cn":"然后他讲述了一个他在科研实验室工作时的故事。"}},{"en":"a British organization that gives advice to people who are having difficulties in a relationship, and has a number of centres around the country where couples can talk with trained staff. It also gives advice by phone and on its website. It was formed in 1938 as the Marriage Guidance Council and changed its name in 1988.","cn":"有关系：一家英国组织，为有关系困难的人提供建议，并在全国各地设有许多中心，夫妻可以与经过培训的工作人员交谈。它还通过电话和在其网站上提供建议。它成立于1938年，当时是婚姻指导委员会，并于1988年更名。","pos":""}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"涉及;关于","en":"If something relates to a particular subject, it concerns that subject.","ex":{"en":"Other recommendations relate to the details of how such data is stored","cn":"其他建议涉及此类信息储存方面的一些细节。"}},{"pos":"V-RECIP-ERG","cn":"相关;有关联","en":"The way that two things relate, or the way that one thing relates to another, is the sort of connection that exists between them.","ex":{"en":"More studies will be required before we know what the functions of these genes are and whether they relate to each other","cn":"要弄清这些基因的功能以及它们彼此之间是否关联，我们还需要开展更多的研究。"}},{"pos":"VERB 动词","cn":"产生共鸣;认同","en":"If you can relate to someone, you can understand how they feel or behave so that you are able to communicate with them or deal with them easily.","ex":{"en":"He is unable to relate to other people","cn":"他无法理解他人的想法。"}},{"pos":"VERB 动词","cn":"叙述;讲述","en":"If you relate a story, you tell it.","ex":{"en":"There were officials to whom he could relate the whole story","cn":"有一些官员会听他讲述整个故事。"}}]},"examples":[{"en":"She relates her childhood experiences in the first chapters.","cn":"在开始的几章中，她描述了自己童年的经历。"},{"en":"We shall discuss the problem as it relates to our specific case.","cn":"我们应针对我们的具体情况来讨论这个问题。"}]},"remark":{"oxford":{"phon":"rɪˈmɑːk","pos":"noun","senses":[{"en":"something that you say or write which expresses an opinion, a thought, etc. about somebody/something","cn":"谈论；言论；评述","g":"[countable]","ex":{"en":"to make a remark","cn":"发表评论"}},{"en":"the quality of being important or interesting enough to be noticed","cn":"引人注目；显耀","g":"[uncountable]","lab":"old-fashioned or formal","ex":{"en":"The exhibition contains nothing that is worthy of remark.","cn":"这次展览没有任何值得看的东西。"}},{"en":"to say or write a comment about something/somebody","cn":"说起；谈论；评论","ex":{"en":"Sport, George Orwell once remarked, is like war.","cn":"乔治·奥威尔曾经说过，体育就像战争。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"说;谈到","en":"If you remark that something is the case, you say that it is the case.","ex":{"en":"I remarked that I would go shopping that afternoon","cn":"我说过我那天下午要去购物。"}},{"pos":"N-COUNT 可数名词","cn":"评论;意见","en":"If you make a remark about something, you say something about it.","ex":{"en":"She has made outspoken remarks about the legalisation of cannabis in Britain","cn":"她对英国关于大麻的立法进行了大胆评论。"}}]},"media":{"uk":"media/uk/remark__gb_1.mp3","us":"media/us/remark__us_1.mp3"},"examples":[{"en":"He made a number of rude remarks about the food.","cn":"关于这里的食物他说了许多无礼的评论。"},{"en":"‘It's much colder than yesterday,’ he remarked casually. “","cn":"今天比昨天冷多了。”他漫不经心地说。"}]},"refine":{"oxford":{"phon":"rɪˈfaɪn","pos":"verb","senses":[{"en":"to make a substance pure by taking other substances out of it","cn":"精炼；提纯；去除杂质","ex":{"en":"The process of refining oil produces several useful chemicals.","cn":"炼油的过程会产生几种有用的化学品。"}},{"en":"to improve something by making small changes to it","cn":"改进；改善；使精练","ex":{"en":"She has refined her playing technique over the years.","cn":"多年来，她不断完善自己的演奏技巧。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"提炼;精炼","en":"When a substance is refined, it is made pure by having all other substances removed from it.","ex":{"en":"Oil is refined to remove naturally occurring impurities.","cn":"油经过提炼去除天然存在的杂质。"}},{"pos":"VERB 动词","cn":"改进，改善，改良（过程、理论或机器）","en":"If something such as a process, theory, or machine is refined, it is improved by having small changes made to it.","ex":{"en":"Surgical techniques are constantly being refined.","cn":"外科手术的技术不断得到完善。"}}]},"media":{"uk":"media/uk/refine__gb_1.mp3","us":"media/us/refine__us_1.mp3"},"examples":[{"en":"the process of refining oil/sugar","cn":"炼油的/炼糖的工序"},{"en":"Car makers are constantly refining their designs.","cn":"汽车制造商在不断完善他们的设计。"}]},"regretfully":{"media":{"uk":"media/uk/regretfully__gb_1.mp3","us":"media/us/regretfully__us_1.mp3"},"oxford":{"phon":"rɪˈɡretfəli","pos":"adverb","senses":[{"en":"in a way that shows you are sad or disappointed about something","cn":"遗憾地；痛惜地；失望地；懊悔地","ex":{"en":"‘I'm afraid not,’ he said regretfully.","cn":"他遗憾地说：“恐怕不行。”"}},{"en":"used to show that you are sorry that something is the case and you wish the situation were different","cn":"遗憾的是；十分遗憾","ex":{"en":"There is, regretfully, no space in this article to examine all these issues.","cn":"遗憾的是，本文没有篇幅来探讨所有这些问题。"}}]},"examples":[{"en":"Regretfully, mounting costs have forced the museum to close.","cn":"遗憾的是，成本不断增加，博物馆不得不关闭。"},{"en":"Regrettably, some jobs will be lost.","cn":"令人遗憾的是有些工作将会被裁。"}]},"register":{"oxford":{"phon":"ˈredʒɪstə(r)","pos":"verb","senses":[{"en":"to record your/somebody’s/something’s name on an official list","cn":"登记；注册","g":"[transitive, intransitive]","sc":"put name on list","ex":{"en":"You can also register online.","cn":"你也可以在线注册。"}},{"en":"to make your opinion known officially or publicly","cn":"（正式地或公开地）发表意见，提出主张","g":"[transitive]","lab":"formal","sc":"give opinion publicly","ex":{"en":"Many saw the vote as a way to register a protest.","cn":"许多人将投票视为表达抗议的一种方式。"}},{"en":"if a measuring instrument registers an amount or something registers an amount on a measuring instrument, the instrument shows or records that amount","cn":"显示（读数）；记录","g":"[intransitive, transitive]","sc":"on measuring instrument","ex":{"en":"The thermometer registered 32°C.","cn":"温度计显示读数为 32 摄氏度。"}},{"en":"to show or express a feeling","cn":"流露出；显得；表达出","g":"[transitive, no passive, intransitive]","lab":"formal","sc":"show feeling","ex":{"en":"Her face registered disapproval.","cn":"她脸上流露出不赞同的神色。"}},{"en":"to notice something and remember it; to be noticed","cn":"注意到；记住；受到注意","g":"[transitive, no passive, intransitive]","sc":"notice something","ex":{"en":"He barely registered our presence.","cn":"他几乎没有注意到我们在场。"}},{"en":"to send something by mail, paying extra money to protect it against loss or damage","cn":"把…挂号邮寄","g":"[transitive, usually passive]","sc":"letter/package","ex":{"en":"Can I register this, please?","cn":"请给我把这个挂号邮寄。"}},{"en":"an official list or record of names, items, etc.; a book that contains such a list","cn":"登记表；注册簿；登记簿","g":"[countable]","lab":"British English","sc":"list of names","ex":{"en":"The bride and groom signed the register.","cn":"新娘和新郎在登记册上签名。"},"pos":"noun"},{"en":"the range, or part of a range, of a human voice or a musical instrument","cn":"声区；音区","g":"[countable]","sc":"of voice/instrument","ex":{"en":"in the upper/middle/lower register","cn":"在高／中／低声区"},"pos":"noun"},{"en":"the level and style of a piece of writing or speech, that is usually appropriate to the situation that it is used in","cn":"（适合特定场合使用的）语体风格；语域","g":"[countable, uncountable]","lab":"linguistics","sc":"of writing/speech","ex":{"en":"The essay suddenly switches from a formal to an informal register.","cn":"这篇文章的语体风格突然从正式转为非正式。"},"pos":"noun"},{"en":"an opening, with a cover that you can have open or shut, that allows hot or cold air from a heating or cooling system into a room","cn":"（供暖或制冷设备的）调风口，节气门，百叶型风口","g":"[countable]","lab":"North American English","sc":"for hot/cold air","pos":"noun"},{"en":"a machine used in shops, restaurants, etc. for keeping money in, and that shows and records the amount of money received for each thing that is sold","cn":"现金收入记录机；现金出纳机","g":"[countable]","lab":"North American English","sc":"machine","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"登记本；注册簿；（官方）记录","en":"A register is an official list or record of people or things.","ex":{"en":"...registers of births, deaths and marriages","cn":"出生、死亡和婚姻记录"}},{"pos":"VERB 动词","cn":"登记；注册","en":"If you register to do something, you put your name on an official list, in order to be able to do that thing or to receive a service.","ex":{"en":"Have you come to register at the school?","cn":"你来学校注册了吗？"}},{"pos":"VERB 动词","cn":"登记;正式记录;给…注册","en":"If you register something, such as the name of a person who has just died or information about something you own, you have these facts recorded on an official list.","ex":{"en":"In order to register a car in Japan, the owner must have somewhere to park it","cn":"在日本要登记一辆汽车，车主必须先要有车位。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（仪表等）显示，指示","en":"When something registers on a scale or measuring instrument, it shows on the scale or instrument. You can also say that something registers a certain amount or level on a scale or measuring instrument.","ex":{"en":"It will only register on sophisticated X-ray equipment","cn":"只有精密的X射线仪器才能显示出来。"}},{"pos":"VERB 动词","cn":"表示，表达（情绪或意见）","en":"If you register your feelings or opinions about something, you do something that makes them clear to other people.","ex":{"en":"Voters wish to register their dissatisfaction with the ruling party","cn":"选民希望表达他们对执政党的不满。"}},{"pos":"VERB 动词","cn":"（表情）流露，显露，显出","en":"If a feeling registers on someone's face, their expression shows clearly that they have that feeling.","ex":{"en":"Surprise again registered on Rodney's face.","cn":"罗德尼的脸上再次露出诧异的神情。"}},{"pos":"V-ERG 及物/不及物动词","cn":"引起注意;（被）意识到;（使）留下印象","en":"If a piece of information does not register or if you do not register it, you do not really pay attention to it, and so you do not remember it or react to it.","ex":{"en":"What I said sometimes didn't register in her brain","cn":"有时我说的话她根本没听进去。"}},{"pos":"N-COUNT 可数名词","cn":"（嗓音或乐器的）音域","en":"If you sing or play something in a high or low register, you sing, or play it using high or low notes. If you say something in a high or low register, you say it in a high or low voice."},{"pos":"N-VAR 可变名词","cn":"（语言学中的）语域","en":"In linguistics, the register of a piece of speech or writing is its level and style of language, which is usually appropriate to the situation or circumstances in which it is used."}]},"media":{"uk":"media/uk/register__gb_1.mp3","us":"media/us/register__us_1.mp3"},"examples":[{"en":"The essay suddenly switches from a formal to an informal register.","cn":"这篇文章的语体风格突然从正式转为非正式。"},{"en":"I told her my name, but it obviously didn't register.","cn":"我把名字告诉了她，但她显然没有在意。"}]},"relaxation":{"media":{"uk":"media/uk/relaxation__gb_1.mp3","us":"media/us/relaxation__us_1.mp3"},"oxford":{"phon":"ˌriːlækˈseɪʃn","pos":"noun","senses":[{"en":"a way of resting and enjoying yourself; time spent resting and enjoying yourself","cn":"放松；休息；消遣；用于放松消遣的时间","g":"[uncountable, countable]","ex":{"en":"I go hill-walking for relaxation.","cn":"我要是想放松一下，就到山上走走。"}},{"en":"the state of feeling calm and not anxious or worried","cn":"平静；无忧","g":"[uncountable]","ex":{"en":"Some people take up yoga to aid relaxation.","cn":"有些人练习瑜伽来帮助放松。"}},{"en":"the fact of a part of the body, especially a muscle, becoming less tight","cn":"（尤指肌肉的）放松","g":"[uncountable]","ex":{"en":"an ointment that helps muscle relaxation","cn":"有助于肌肉放松的药膏"}},{"en":"the act of making a rule or some form of control less strict or severe","cn":"（对规章制度的）放宽，放松","g":"[uncountable, countable, usually singular]","ex":{"en":"the relaxation of foreign currency controls","cn":"对外汇管制的放宽"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"放松;松弛;休息","en":"Relaxation is a way of spending time in which you rest and feel comfortable.","ex":{"en":"You should be able to find the odd moment for relaxation","cn":"你应该能抽空休息一下。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(规定或控制的)放松，放宽，削弱","en":"If there is relaxation of a rule or control, it is made less firm or strong.","ex":{"en":"...the relaxation of travel restrictions.","cn":"旅游限制的放宽"}}]},"examples":[{"en":"I go hill-walking for relaxation.","cn":"我要是想放松一下，就到山上走走。"},{"en":"Fishing is his favourite relaxation.","cn":"钓鱼是他最喜欢的消遣活动。"}]},"resolution":{"media":{"uk":"media/uk/resolution__gb_1.mp3","us":"media/us/resolution__us_1.mp3"},"oxford":{"phon":"ˌrezəˈluːʃn","pos":"noun","senses":[{"en":"a definite decision to do or not to do something","cn":"决心；决定","g":"[countable]","ex":{"en":"Have you made any New Year's resolutions (= for example, to give up smoking from 1 January)?","cn":"你有什么新年计划吗？"}},{"en":"a formal statement of an opinion agreed on by a committee or a council, especially by means of a vote","cn":"决议；正式决定","g":"[countable]","ex":{"en":"to pass/adopt/approve a resolution","cn":"通过／采纳／批准决议"}},{"en":"the act of solving or settling a problem, argument, etc.","cn":"（问题、分歧等的）解决，消除","g":"[uncountable, singular]","ex":{"en":"dispute/conflict resolution","cn":"争端／冲突的解决"}},{"en":"the quality of being resolute or determined","cn":"坚定；坚决；有决心","g":"[uncountable]","ex":{"en":"The reforms owe a great deal to the resolution of one man.","cn":"这些改革主要归功于一个人的坚定决心。"}},{"en":"the power of a computer screen, printer, etc. to give a clear image, depending on the size of the dots (= marks) that make up the image","cn":"清晰度；析像；分辨率","g":"[uncountable, singular]","ex":{"en":"The graphics look fine, even at low resolution.","cn":"图形看起来不错，尽管分辨率很低。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"正式决定;决议","en":"Aresolution is a formal decision taken at a meeting by means of a vote.","ex":{"en":"He replied that the UN had passed two major resolutions calling for a complete withdrawal.","cn":"他答复说联合国已经通过了两项号召全面撤军的重要决议。"}},{"pos":"N-COUNT 可数名词","cn":"决心;决定","en":"If you make a resolution, you decide to try very hard to do something.","ex":{"en":"They made a resolution to lose all the weight gained during the Christmas period.","cn":"他们下定决心要减去圣诞期间增加的体重。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"坚定;坚决;果断","en":"Resolution is determination to do something or not do something.","ex":{"en":"'I think I'll try a hypnotist,' I said with sudden resolution.","cn":"“我会找催眠师试试，”我突然坚决地说。"}},{"pos":"N-SING 单数名词","cn":"解决","en":"The resolution of a problem or difficulty is the final solving of it.","ex":{"en":"...the successful resolution of a dispute involving UN inspectors in Baghdad.","cn":"涉及联合国驻巴格达观察员的争端的成功解决"}},{"pos":"N-UNCOUNT 不可数名词","cn":"分辨率;清晰度","en":"The resolution of an image is how clear the image is.","ex":{"en":"Now this machine gives us such high resolution that we can see very small specks of calcium.","cn":"现在这台机器可以呈现很高的分辨率，我们可以看见非常小的钙微粒。"}}]},"examples":[{"en":"The reforms owe a great deal to the resolution of one man.","cn":"这些改革主要归功于一个人的坚定决心。"},{"en":"The government is pressing for an early resolution of the dispute.","cn":"政府正在不断敦促早日解决这起纠纷。"}]},"recharge":{"media":{"uk":"media/uk/recharge__gb_1.mp3","us":"media/us/recharge__us_1.mp3"},"oxford":{"phon":"ˌriːˈtʃɑːdʒ","pos":"verb","senses":[{"en":"to fill a battery with electrical power; to be filled with electrical power","cn":"给（电池）充电；充电","g":"[transitive, intransitive]","ex":{"en":"He plugged his razor in to recharge it.","cn":"他把剃刀插在插座上，给它充电。"}},{"en":"to get back your strength and energy by resting for a time","cn":"恢复体力；恢复精力；休整","g":"[intransitive]","lab":"informal","ex":{"en":"We needed the break in order to recharge.","cn":"我们需要休息一下以恢复体力。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"给（电池）充电","en":"If you recharge a battery, you put an electrical charge back into the battery by connecting it to a machine that draws power from another source of electricity such as the mains.","ex":{"en":"He is using your mains electricity to recharge his car battery.","cn":"他在用你家里的电源给他的车载蓄电池充电。"}},{"pos":"PHRASE 短语","cn":"放松；休息；补充精力","en":"If you recharge your batteries, you take a break from activities which are tiring or difficult in order to relax and feel better when you return to these activities.","ex":{"en":"He wanted to recharge his batteries and come back feeling fresh and positive.","cn":"他想去放松休息一下，然后精力充沛、干劲十足地回来。"}}]},"examples":[{"en":"He plugged his razor in to recharge it.","cn":"他把剃刀插在插座上，给它充电。"},{"en":"The drill takes about three hours to recharge.","cn":"钻机充一次电大约要三个小时。"}]},"relieved":{"media":{"uk":"media/uk/relieved__gb_1.mp3","us":"media/us/relieved__us_1.mp3"},"oxford":{"phon":"rɪˈliːvd","pos":"adjective","senses":[{"en":"feeling happy because something unpleasant has stopped or has not happened; showing this","cn":"感到宽慰的；放心的；显得开心的","ex":{"en":"She sounded relieved.","cn":"她听上去很放心。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感到宽慰的;感到安心的;宽心的","en":"If you are relieved, you feel happy because something unpleasant has not happened or is no longer happening.","ex":{"en":"We are all relieved to be back home","cn":"回到家里我们都感到安心了。"}}]},"examples":[{"en":"You'll be relieved to know your jobs are safe.","cn":"现在知道你们的工作保住了，可以放心了。"},{"en":"I'm just relieved that nobody was hurt.","cn":"谁都没有受伤，我深感宽慰。"}],"base":"relieve"},"repeating":{"lemma":"repeat","media":{"uk":"media/uk/repeat__gb_1.mp3","us":"media/us/repeat__us_1.mp3"}},"relative":{"media":{"uk":"media/uk/relative__gb_1.mp3","us":"media/us/relative__us_1.mp3"},"oxford":{"phon":"ˈrelətɪv","pos":"adjective","senses":[{"en":"considered and judged by being compared with something else","cn":"相比较而言的；比较的","ex":{"en":"You must consider the relative merits of the two plans.","cn":"你必须考虑相比较之下两个计划各自的优点。"}},{"en":"referring to an earlier noun, sentence or part of a sentence","cn":"（指代前面的名词、句子或句子的一部分）","lab":"grammar","ex":{"en":"In ‘the man who came’, ‘who’ is a relative pronoun and ‘who came’ is a relative clause.","cn":"在 the man who came 中，who 是关系代词，而 who came 是关系从句。"}},{"en":"that exists or that has a particular quality only when compared with something else","cn":"相比之下存在（或有）的","g":"[only before noun]","ex":{"en":"They now live in relative comfort (= compared with how they lived before).","cn":"他们现在过得比较舒适。"}},{"en":"a person who is in the same family as somebody else","cn":"亲戚；亲属","ex":{"en":"a close/distant relative","cn":"近亲；远亲"},"pos":"noun"},{"en":"a thing that belongs to the same group as something else","cn":"同类事物","ex":{"en":"The ibex is a distant relative of the mountain goat.","cn":"北山羊与石山羊有较远的亲缘关系。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"亲戚;亲属;家属","en":"Your relatives are the members of your family.","ex":{"en":"Do relatives of yours still live in Siberia?","cn":"你的亲属仍然住在西伯利亚吗？"}},{"pos":"ADJ 形容词","cn":"相对的","en":"You use relative to say that something is true to a certain degree, especially when compared with other things of the same kind.","ex":{"en":"The fighting resumed after a period of relative calm","cn":"战斗在相对平静的一段时间之后再次打响。"}},{"pos":"ADJ 形容词","cn":"相对的;比较而言的","en":"You use relative when you are comparing the quality or size of two things.","ex":{"en":"They chatted about the relative merits of London and Paris as places to live","cn":"他们聊起了伦敦和巴黎两座城市相比较都有哪些宜居的优点。"}},{"pos":"PREP-PHRASE 短语介词","cn":"与…相比;与…有关;涉及;关于","en":"Relative to something means with reference to it or in comparison with it.","ex":{"en":"Japanese interest rates rose relative to America's","cn":"日本利率随美国利率上浮。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"相对的;比较而言的","en":"If you say that something is relative, you mean that it needs to be considered and judged in relation to other things.","ex":{"en":"Fitness is relative; one must always ask 'Fit for what?'","cn":"“适合”是相对而言的;应该常常问一问“适合什么？”"}},{"pos":"N-COUNT 可数名词","cn":"亲缘动物（或植物、语言、发明等)","en":"If one animal, plant, language, or invention is a relative of another, they have both developed from the same type of animal, plant, language, or invention.","ex":{"en":"The pheasant is a close relative of the Guinea hen.","cn":"雉与珍珠鸡有很近的亲缘关系。"}}]},"examples":[{"en":"It's all relative though, isn't it? We never had any money when I was a kid and $500 was a fortune to us.","cn":"不过，一切都是相对的，是不是？我小的时候，我们根本没有钱，500 块钱对于我们来说就是很大的一笔钱了。"},{"en":"In ‘the man who came’, ‘who’ is a relative pronoun and ‘who came’ is a relative clause.","cn":"在 the man who came 中，who 是关系代词，而 who came 是关系从句。"}]},"republic":{"oxford":{"phon":"rɪˈpʌblɪk","pos":"noun","senses":[{"en":"a country that is governed by a president and politicians elected by the people and where there is no king or queen","cn":"共和国；共和政体","ex":{"en":"newly independent republics","cn":"新独立的共和国"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"共和国;共和政体","en":"A republic is a country where power is held by the people or the representatives that they elect. Republics have presidents who are elected, rather than kings or queens.","ex":{"en":"In 1918, Austria became a republic.","cn":"1918年，奥地利成为共和国。"}}]},"media":{"uk":"media/uk/republic__gb_1.mp3","us":"media/us/republic__us_1.mp3"},"examples":[{"en":"newly independent republics","cn":"新独立的共和国"},{"en":"the Republic of Ireland","cn":"爱尔兰共和国"}]},"reaches":{"lemma":"reach"},"recruitment":{"media":{"uk":"media/uk/recruitment__gb_1.mp3","us":"media/us/recruitment__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"招募；招聘","en":"The recruitment of workers, soldiers, or members is the act or process of selecting them for an organization or army and persuading them to join.","ex":{"en":"...the examination system for the recruitment of civil servants.","cn":"招募公务员的考试体制"}}]},"examples":[{"en":"the recruitment of new members","cn":"新成员的招募"},{"en":"a recruitment drive","cn":"征兵运动"}],"oxford":{"phon":"rɪˈkruːtmənt","pos":"noun","senses":[{"en":"the act or process of finding new people to join a company, an organization, the armed forces, etc.","cn":"吸收（新成员）；征募（新兵）","ex":{"en":"the recruitment of new members","cn":"新成员招募"}}]}},"resource":{"media":{"uk":"media/uk/resource__gb_1.mp3","us":"media/us/resource__us_1.mp3"},"oxford":{"phon":"rɪˈsɔːs","pos":"noun","senses":[{"en":"a supply of something that a country, an organization or a person has and can use, especially to increase their wealth","cn":"资源；财力","g":"[countable, usually plural]","lab":"especially British English","ex":{"en":"the exploitation of minerals and other natural resources","cn":"矿产和其他自然资源的开发"}},{"en":"something that can be used to help achieve an aim, especially a book, equipment, etc. that provides information for teachers and students","cn":"有助于实现目标的东西；资料","g":"[countable]","ex":{"en":"The website is an invaluable educational resource.","cn":"该网站是宝贵的教育资源。"}},{"en":"personal qualities such as courage and imagination that help you deal with difficult situations","cn":"勇气；才智；谋略","g":"[plural]","ex":{"en":"He has no inner resources and hates being alone.","cn":"他没有什么精神力量，因而害怕独处。"}},{"en":"to provide something with the money or equipment that is needed","cn":"向…提供资金（或设备）","ex":{"en":"Schools in the area are still inadequately resourced.","cn":"本地区的学校仍然没有足够的资金。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"资源;物力;财力","en":"The resources of an organization or person are the materials, money, and other things that they have and can use in order to function properly.","ex":{"en":"Some families don't have the resources to feed themselves properly","cn":"有些家庭无力维持生活。"}},{"pos":"N-COUNT 可数名词","cn":"(国家的)资源，财富","en":"A coun-try's resources are the things that it has and can use to increase its wealth, such as coal, oil, or land.","ex":{"en":"...resources like coal, tungsten, oil and copper","cn":"煤、钨、石油和铜之类的资源"}}]},"examples":[{"en":"The database could be used as a teaching resource in colleges.","cn":"该数据库可用作大学里的一种教学辅助工具。"},{"en":"Time is your most valuable resource, especially in examinations.","cn":"时间是你最宝贵的东西，尤其是在考试中。"}]},"repel":{"media":{"uk":"media/uk/repel__gb_1.mp3","us":"media/us/repel__us_1.mp3"},"oxford":{"phon":"rɪˈpel","pos":"verb","senses":[{"en":"to successfully fight somebody who is attacking you, your country, etc. and drive them away","cn":"击退；驱逐","g":"[transitive]","lab":"formal","ex":{"en":"to repel an attack/invasion/invader","cn":"击退进攻／入侵；驱逐入侵者"}},{"en":"to drive, push or keep something away","cn":"推开；赶走；驱除","g":"[transitive]","ex":{"en":"a cream that repels insects","cn":"驱除昆虫的乳剂"}},{"en":"to make somebody feel horror or disgust","cn":"使恐惧；使厌恶","g":"[transitive]","ex":{"en":"I was repelled by the smell.","cn":"这种气味让我恶心。"}},{"en":"if one thing repels another, or if two things repel each other, an electrical or magnetic force pushes them apart","cn":"排斥；相斥","g":"[transitive, intransitive]","lab":"specialist","ex":{"en":"Like poles repel each other.","cn":"同极相斥。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"击退;驱逐","en":"When an army repels an attack, they successfully fight and drive back soldiers from another army who have attacked them.","ex":{"en":"They have fifty thousand troops along the border ready to repel any attack.","cn":"他们有5万人的部队驻扎在边境，随时准备击退任何进攻。"}},{"pos":"V-RECIP 相互动词","cn":"(磁极、电荷之间)排斥","en":"When a magnetic pole repels another magnetic pole, it gives out a force that pushes the other pole away. You can also say that two magnetic poles repel each other or that they repel .","ex":{"en":"Like poles repel, unlike poles attract","cn":"同极相斥，异极相吸。"}},{"pos":"VERB 动词","cn":"使厌恶;使讨厌","en":"If something repels you, you find it horrible and disgusting.","ex":{"en":"...a violent excitement that frightened and repelled her.","cn":"使她恐惧和厌恶的强烈兴奋感"}}]},"examples":[{"en":"( figurative ) The reptile's prickly skin repels nearly all of its predators.","cn":"这种爬行动物浑身是刺，几乎所有的捕食者都退避三舍。"},{"en":"Troops repelled an attempt to infiltrate the south of the island.","cn":"部队挫败了对该岛南部的潜入企图。"}]},"reflexive":{"oxford":{"phon":"rɪˈfleksɪv","pos":"adjective","senses":[{"en":"a reflexive word or form of a word shows that the action of the verb affects the person who performs the action","cn":"（词或词形）反身的","ex":{"en":"In ‘He cut himself’, ‘cut’ is a reflexive verb and ‘himself’ is a reflexive pronoun.","cn":"在 He cut himself 一句中，cut 是反身动词，himself 是反身代词。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"应激反应的;本能反应的;条件反射的","en":"A reflexive reaction or movement occurs immediately in response to something that happens.","ex":{"en":"...that reflexive urge for concealment.","cn":"想要躲藏起来的本能冲动"}}]},"media":{"uk":"media/uk/reflexive__gb_1.mp3","us":"media/us/reflexive__us_1.mp3"},"examples":[{"en":"In ‘He cut himself’, ‘cut’ is a reflexive verb and ‘himself’ is a reflexive pronoun.","cn":"在 He cut himself 一句中，cut 是反身动词，himself 是反身代词。"}]},"reveals":{"lemma":"reveal","media":{"uk":"media/uk/reveal__gb_1.mp3","us":"media/us/reveal__us_1.mp3"}},"resolved":{"media":{"uk":"media/uk/resolved__gb_1.mp3","us":"media/us/resolved__us_1.mp3"},"oxford":{"phon":"rɪˈzɒlvd","pos":"adjective","senses":[{"en":"determined","cn":"下定决心；坚定","ex":{"en":"I was resolved not to see him.","cn":"我决意不见他。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"下定决心的;决意的","en":"If you are resolved to do something, you are determined to do it.","ex":{"en":"Barnes was resolved to moving on when his contract expired.","cn":"合同到期以后，巴恩斯决定做点别的。"}}]},"examples":[{"en":"I was resolved not to see him.","cn":"我决意不见他。"}],"base":"resolve"},"rely":{"media":{"uk":"media/uk/rely__gb_1.mp3","us":"media/us/rely__us_1.mp3"},"oxford":{"phon":"rɪˈlaɪ","pos":"verb","senses":[{"en":"to need or depend on sb/sth","cn":"依赖；依靠"},{"en":"to trust or have faith in sb/sth","cn":"信任；信赖"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"依赖;依靠","en":"If you rely on someone or something, you need them and depend on them in order to live or work properly.","ex":{"en":"They relied heavily on the advice of their professional advisers","cn":"他们非常依赖职业咨询师提供的建议。"}},{"pos":"VERB 动词","cn":"信赖;信任","en":"If you can rely on someone to work well or to behave as you want them to, you can trust them to do this.","ex":{"en":"I know I can rely on you to sort it out","cn":"我相信你会把它解决好的。"}}]},"examples":[{"en":"These days we rely heavily on computers to organize our work.","cn":"现在，我们在很大程度上依赖电脑来安排我们的工作。"},{"en":"As babies, we rely entirely on others for food.","cn":"在婴儿时期，我们完全依赖别人喂食。"}]},"ready":{"media":{"uk":"media/uk/ready__gb_1.mp3","us":"media/us/ready__us_1.mp3"},"oxford":{"phon":"ˈredi","pos":"adjective","senses":[{"en":"fully prepared for what you are going to do and able to start it immediately","cn":"准备好；准备完毕","g":"[not before noun]","sc":"prepared/available","ex":{"en":"Just a minute—I'm almost ready.","cn":"请稍等，我快准备好了。"}},{"en":"having the experience, attitude, etc. that you need in order to be able to deal with something","cn":"（经验或心理上）准备好，有准备","g":"[not before noun]","sc":"prepared/available","ex":{"en":"Her husband wants to start a family, but she isn't ready.","cn":"她丈夫想要个孩子，但她还没有准备好。"}},{"en":"completed and available to be used","cn":"已完成；准备好；可利用","g":"[not before noun]","sc":"prepared/available","ex":{"en":"Come on, dinner's ready!","cn":"快过来，饭好了！"}},{"en":"available to be used easily and immediately","cn":"方便使用的；现成的","sc":"prepared/available","ex":{"en":"All the relevant records are ready to hand.","cn":"所有相关记录都已准备就绪。"}},{"en":"willing and quick to do or give something","cn":"愿意迅速做某事（或给某物）；急于行动","g":"[not before noun]","sc":"willing","ex":{"en":"I was very angry and ready for a fight.","cn":"我非常生气，想打一架。"}},{"en":"likely to do something very soon","cn":"马上要，很可能即将（做某事）","sc":"likely to do something","ex":{"en":"She looked ready to collapse at any minute.","cn":"她看样子随时都会倒下。"}},{"en":"needing something as soon as possible","cn":"急需；需尽快得到","sc":"needing something","ex":{"en":"Right, I'm ready for bed.","cn":"对，我现在就想睡觉。"}},{"en":"quick and clever","cn":"聪明的；机敏的","g":"[only before noun]","sc":"quick/clever","ex":{"en":"She has great charm and a ready wit.","cn":"她光彩照人，头脑机敏。"}},{"en":"to prepare somebody/yourself/something for something","cn":"做好…的准备；（为…）做好准备","ex":{"en":"British companies were readying themselves for big changes.","cn":"英国公司正在为重大变革做好准备。"},"pos":"verb"},{"en":"already done","cn":"已做完；已完成","ex":{"en":"ready-cooked meals","cn":"现成的饭菜"},"pos":"adverb"},{"en":"money that you can use immediately","cn":"现钱","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（人）准备就绪的;（物品）准备好的","en":"If someone is ready, they are properly prepared for something. If something is ready, it has been properly prepared and is now able to be used.","ex":{"en":"It took her a long time to get ready for church","cn":"她花了很长时间才做好去教堂的准备。"}},{"pos":"ADJ 形容词","cn":"准备好的;胜任的","en":"If you are ready for something or ready to do something, you have enough experience to do it or you are old enough and sensible enough to do it.","ex":{"en":"She says she's not ready for marriage","cn":"她说自己还没有准备好结婚。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愿意的；乐意的；情愿的；甘愿的","en":"If you are ready to do something, you are willing to do it.","ex":{"en":"They were ready to die for their beliefs","cn":"他们甘愿为信仰而死。"}},{"pos":"ADJ 形容词","cn":"需要的；想要的","en":"If you are ready for something, you need it or want it.","ex":{"en":"I don't know about you, but I'm ready for bed","cn":"我不知道你怎样，但是我要睡觉了。"}},{"pos":"ADJ 形容词","cn":"即将…的;可能…的","en":"To be ready to do something means to be about to do it or likely to do it.","ex":{"en":"She looked ready to cry","cn":"她看起来要哭了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"现成的;就绪的;易于得到的","en":"You use ready to describe things that are able to be used very quickly and easily.","ex":{"en":"I didn't have a ready answer for this dilemma","cn":"我没有想出解决这个困境的现成答案。"}},{"pos":"ADJ 形容词","cn":"现金的;现钱的","en":"Ready money is in the form of notes and coins rather than cheques or credit cards, and so it can be used immediately.","ex":{"en":"I'm afraid I don't have enough ready cash.","cn":"恐怕我身上没有足够的现金。"}},{"pos":"VERB 动词","cn":"使做好准备;准备好","en":"When you ready something, you prepare it for a particular purpose.","ex":{"en":"John's soldiers were readying themselves for the final assault","cn":"约翰的手下正在为最后的进攻做准备。"}},{"pos":"COMB in ADJ 与形容词构成的词","cn":"（与过去分词连用）表示“已经…好的”，“事先…的”","en":"Ready combines with past participles to indicate that something has already been done, and that therefore you do not have to do it yourself.","ex":{"en":"You can buy ready-printed forms for wills at stationery shops","cn":"你可以在文具店买到已印好的遗嘱单。"}},{"pos":"PHRASE 短语","cn":"现成的；可以立即使用的；在手边的","en":"If you have something at the ready, you have it in a position where it can be quickly and easily used.","ex":{"en":"Soldiers came charging through the forest, guns at the ready.","cn":"荷枪实弹的士兵穿过林区冲了上来。"}},{"pos":"PHRASE 短语","cn":"准备就绪；整装待发","en":"If you want to emphasize that a person is properly prepared for something, or that something can now be used, you can say that they are ready and waiting .","ex":{"en":"She liked to be ready and waiting at home when Bernard returned from work","cn":"她想在伯纳德下班回家的时候把一切准备就绪。"}},{"pos":"CONVENTION 惯用语","cn":"已经准备就绪；就等你先开始","en":"If you say to someone 'Ready when you are', you are telling them that you are now ready to do something and that as soon as they are ready, you will do it.","ex":{"en":"'Are you ready to pull out?' — 'I'm ready when you are, Captain.'","cn":"“准备好出发了吗?”——“就等你了，船长。”"}}]},"examples":[{"en":"‘Shall we go?’ ‘I'm ready when you are! ’ “","cn":"我们可以走了吗？” “我准备好了，就等你了！”"},{"en":"Western companies were readying themselves for the challenge from Eastern markets.","cn":"西方的公司正在为迎接来自东方市场的挑战作准备。"}]},"reflections":{"lemma":"reflection","media":{"uk":"media/uk/reflection__gb_1.mp3","us":"media/us/reflection__us_1.mp3"}},"re":{"media":{"uk":"media/uk/re__gb_1.mp3","us":"media/us/re__us_1.mp3"},"oxford":{"phon":"reɪ","pos":"noun","senses":[{"en":"the second note of a major scale","cn":"大调音阶的第 2 音"},{"en":"used at the beginning of a business letter, etc. to introduce the subject that it is about; used on an email that you are sending as a reply","cn":"（用于商业信函等开头介绍主题或回复电子邮件）关于，事由","ex":{"en":"Re your letter of 1 September…","cn":"关于你 9 月 1 日的来信…"},"pos":"preposition"},{"en":"a school subject in which students learn about different religions (the abbreviation for ‘religious education’)","cn":"宗教教育（学科名称，全写为 religious education）","ex":{"en":"an RE teacher","cn":"宗教教育科老师"}},{"en":"Royal Engineers","cn":"皇家工程师","pos":""},{"en":"again","cn":"又；再；重新","ex":{"en":"reapply","cn":"再申请"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"","cn":"关于（用于商业信函、传真或其他文件中）","en":"You use re in business letters, faxes, or other documents to introduce a subject or item which you are going to discuss or refer to in detail.","ex":{"en":"Dear Mrs Cox, Re: Household Insurance. We note from our files that we have not yet received your renewal instructions.","cn":"亲爱的考克斯夫人，关于房屋保险一事，我们的文件显示尚未收到您的续保通知。"}}]},"examples":[{"en":"an RE teacher","cn":"宗教教育科老师"},{"en":"re your enquiry of the 19th October","cn":"关于您10月19日的咨询"}]},"retired":{"media":{"uk":"media/uk/retired__gb_1.mp3","us":"media/us/retired__us_1.mp3"},"oxford":{"phon":"rɪˈtaɪəd","pos":"adjective","senses":[{"en":"having retired from work","cn":"已退休的；已退职的","ex":{"en":"a retired doctor/teacher/officer/general","cn":"退休医生／教师／军官／将军"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"退休的;退职的","en":"A retired person is an older person who has left his or her job and has usually stopped working completely.","ex":{"en":"...a seventy-three-year-old retired teacher from Florida.","cn":"佛罗里达州73岁的退休教师"}}]},"examples":[{"en":"Dad is retired now.","cn":"爸爸现在已经退休了。"},{"en":"a retired doctor","cn":"退休医生"}],"base":"retire"},"regulates":{"lemma":"regulate"},"resignation":{"media":{"uk":"media/uk/resignation__gb_1.mp3","us":"media/us/resignation__us_1.mp3"},"oxford":{"phon":"ˌrezɪɡˈneɪʃn","pos":"noun","senses":[{"en":"the act of giving up your job or position; the occasion when you do this","cn":"辞职","g":"[uncountable, countable]","lab":"British English","ex":{"en":"a letter of resignation","cn":"辞职信"}},{"en":"a letter, for example to your employers, to say that you are giving up your job or position","cn":"辞职信；辞呈","g":"[countable]","ex":{"en":"to offer/hand in/tender your resignation","cn":"呈递／上交／提交辞职信"}},{"en":"the quality of being willing to accept a difficult or unpleasant situation that you cannot change","cn":"顺从；听任","g":"[uncountable]","ex":{"en":"They accepted their defeat with resignation.","cn":"他们无可奈何地承认失败。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"辞职书;辞呈","en":"Your resignation is a formal statement of your intention to leave a job or position.","ex":{"en":"Mr Morgan has offered his resignation and it has been accepted.","cn":"摩根先生己经递交了辞呈，并已获准。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"屈从;顺从;听任;勉强接受","en":"Resignation is the acceptance of an unpleasant situation or fact because you realize that you cannot change it.","ex":{"en":"There was no grief in his expression, only deep resignation","cn":"他的表情里没有悲痛，只有深深的无奈。"}}]},"examples":[{"en":"There were calls for her resignation from the board of directors.","cn":"有人要求她辞去董事会中的职务。"},{"en":"We haven't received his resignation yet.","cn":"我们还没有收到他的辞呈。"}]},"registered":{"lemma":"register"},"relevance":{"media":{"uk":"media/uk/relevance__gb_1.mp3","us":"media/us/relevance__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(对…的)重要性，意义，相关性","en":"Something's relevance to a situation or person is its importance or significance in that situation or to that person.","ex":{"en":"Politicians' private lives have no relevance to their public roles","cn":"政治家的私生活与他们的公众角色不相关。"}}]},"examples":[{"en":"What he said has no direct relevance to the matter in hand.","cn":"他所说的话与眼下的事没有直接关系。"},{"en":"I don't see the relevance of your question.","cn":"我不懂你这个问题有什么意义。"}],"oxford":{"phon":"ˈreləvəns","pos":"noun","senses":[{"en":"a close connection with the subject you are discussing or the situation you are in","cn":"紧密相关；切题","ex":{"en":"I don't see the relevance of your question.","cn":"你的问题似乎不太相关。"}},{"en":"the fact of being valuable and useful to people in their lives and work","cn":"有价值；有意义","ex":{"en":"a classic play of contemporary relevance","cn":"至今依然意义重大的经典剧作"}}]}},"reluctant":{"media":{"uk":"media/uk/reluctant__gb_1.mp3","us":"media/us/reluctant__us_1.mp3"},"oxford":{"phon":"rɪˈlʌktənt","pos":"adjective","senses":[{"en":"hesitating before doing something because you do not want to do it or because you are not sure that it is the right thing to do","cn":"不情愿的；勉强的","ex":{"en":"He finally gave a reluctant smile.","cn":"他最后露出了一丝无可奈何的微笑。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"勉强的;不情愿的","en":"If you are reluctant to do something, you are unwilling to do it and hesitate before doing it, or do it slowly and without enthusiasm.","ex":{"en":"Mr Spero was reluctant to ask for help","cn":"斯佩罗先生不愿意寻求帮助。"}}]},"examples":[{"en":"They finally agreed to our terms with a certain reluctance.","cn":"他们最终有点勉强地同意了我们的条件。"},{"en":"He finally gave a reluctant smile.","cn":"他最后露出了一丝无可奈何的微笑。"}]},"retain":{"media":{"uk":"media/uk/retain__gb_1.mp3","us":"media/us/retain__us_1.mp3"},"oxford":{"phon":"rɪˈteɪn","pos":"verb","senses":[{"en":"to keep something; to continue to have something","cn":"保持；持有；保留；继续拥有","ex":{"en":"to retain your independence","cn":"保持独立"}},{"en":"to continue to hold or contain something","cn":"保持；继续容纳","lab":"figurative","ex":{"en":"These plants will need a soil that retains moisture during the summer months.","cn":"这些植物需要种在能在夏天里保持湿润的土壤里。"}},{"en":"if a member of the public retains somebody such as a lawyer, they pay money regularly or in advance so the lawyer, etc. will do work for them","cn":"聘请（律师等）","lab":"law","ex":{"en":"You will be paid a retaining fee.","cn":"你将收到预付辩护费。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"保留;保持;保存","en":"To retain something means to continue to have that thing.","ex":{"en":"The interior of the shop still retains a nineteenth-century atmosphere","cn":"这家商店的内部装修仍然保留着19世纪的风格。"}},{"pos":"VERB 动词","cn":"预聘，付定金聘请（律师）","en":"If you retain a lawyer, you pay him or her a fee to make sure that he or she will represent you when your case comes before the court.","ex":{"en":"He decided to retain him for the trial.","cn":"他决定聘请他为出庭律师。"}}]},"examples":[{"en":"This information is no longer retained within the computer's main memory.","cn":"这些数据不再保留在计算机的主存贮器中。"},{"en":"The house retains much of its original charm.","cn":"这所房子保留了许多原有的魅力。"}]},"relieve":{"oxford":{"phon":"rɪˈliːv","pos":"verb","senses":[{"en":"to remove or reduce an unpleasant feeling or pain","cn":"解除，减轻，缓和（不快或痛苦）","ex":{"en":"to relieve the symptoms of a cold","cn":"减轻感冒的症状"}},{"en":"to make a problem less serious","cn":"减轻（问题的严重性）；缓和；缓解","ex":{"en":"efforts to relieve poverty","cn":"缓解贫困的努力"}},{"en":"to make something less boring, especially by introducing something different","cn":"调剂；使有趣","ex":{"en":"We played cards to relieve the boredom of the long wait.","cn":"长时间等待实在无聊，我们就打扑克来解闷儿。"}},{"en":"to replace somebody at the end of their period of duty","cn":"换（某人的）岗（或班）；接替","ex":{"en":"to relieve a sentry","cn":"换岗"}},{"en":"to free a town, etc. from an enemy army that has surrounded it","cn":"将（城镇从敌人的围困中）解围"},{"en":"a polite way of referring to going to the toilet","cn":"（去厕所的一种委婉说法）方便，解手","ex":{"en":"I had to relieve myself behind a bush.","cn":"我只好在灌木丛后面方便了一下。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"缓和，缓解，减轻，解除(不愉快的情绪或形势)","en":"If something relieves an unpleasant feeling or situation, it makes it less unpleasant or causes it to disappear completely.","ex":{"en":"Drugs can relieve much of the pain","cn":"药物能够大大地缓解病痛。"}},{"pos":"VERB 动词","cn":"使解脱;使摆脱","en":"If someone or something relieves you of an unpleasant feeling or difficult task, they take it from you.","ex":{"en":"A part-time bookkeeper will relieve you of the burden of chasing unpaid invoices and paying bills.","cn":"雇一个兼职会计将使你摆脱追讨未付单据和支付账单的负担。"}},{"pos":"VERB 动词","cn":"使（从…中）解脱出来","en":"If someone relieves you of something, they take it away from you.","ex":{"en":"A porter relieved her of the three large cases.","cn":"一个行李搬运工替她扛了3个大包。"}},{"pos":"VERB 动词","cn":"接替…的职位;代…的班","en":"If you relieve someone, you take their place and continue to do the job or duty that they have been doing.","ex":{"en":"At seven o'clock the night nurse came in to relieve her.","cn":"7点钟的时候夜班护士来接她的班。"}},{"pos":"VERB 动词","cn":"解除（或免除）…的职务","en":"If someone is relieved of their duties or is relieved of their post, they are told that they are no longer required to continue in their job.","ex":{"en":"The officer involved was relieved of his duties because he had violated strict guidelines","cn":"那名相关的官员被免除了职务，因为他违反了要求严格的规章制度。"}},{"pos":"VERB 动词","cn":"解围;解放","en":"If an army relieves a town or another place which has been surrounded by enemy forces, it frees it.","ex":{"en":"The offensive began several days ago as an attempt to relieve the town.","cn":"进攻于几天前开始，试图解放这个城镇。"}},{"pos":"VERB 动词","cn":"上厕所;排便","en":"If people or animals relieve themselves, they urinate or defecate.","ex":{"en":"It is not difficult to train your dog to relieve itself on command.","cn":"训练你的狗按指令大小便并非难事。"}}]},"media":{"uk":"media/uk/relieve__gb_1.mp3","us":"media/us/relieve__us_1.mp3"},"examples":[{"en":"We played cards to relieve the boredom of the long wait.","cn":"长时间等待实在无聊，我们就打扑克来解闷儿。"},{"en":"The new secretary will relieve us of some of the paperwork.","cn":"新来的秘书会减轻我们文案工作的一些负担。"}]},"residual":{"media":{"uk":"media/uk/residual__gb_1.mp3","us":"media/us/residual__us_1.mp3"},"oxford":{"phon":"rɪˈzɪdjuəl","pos":"adjective","senses":[{"en":"left at the end of a process","cn":"剩余的；残留的","ex":{"en":"There are still a few residual problems with the computer program.","cn":"电脑程序还有一些残留问题。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"残留的;剩余的;遗留的","en":"Residual is used to describe what remains of something when most of it has gone.","ex":{"en":"...residual radiation from nuclear weapons testing","cn":"核武器实验后残留的辐射"}}]},"examples":[{"en":"There are still a few residual problems with the computer program.","cn":"电脑程序还有一些残留问题。"},{"en":"the residual effects of drug treatment","cn":"药物治疗的残留作用"}]},"receives":{"lemma":"receive","media":{"uk":"media/uk/receive__gb_1.mp3","us":"media/us/receive__us_1.mp3"}},"reggae":{"oxford":{"phon":"ˈreɡeɪ","pos":"noun","senses":[{"en":"a type of popular music with strong rhythms, developed in Jamaica in the 1960s","cn":"雷鬼乐（20 世纪 60 年代于牙买加兴起的一种节奏强劲的流行音乐）"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"雷盖音乐（西印度群岛的节奏感很强的流行乐）","en":"Reggae is a kind of West Indian popular music with a very strong beat.","ex":{"en":"Bob Marley provided them with their first taste of Reggae music.","cn":"鲍勃·马利让他们首次接触到了雷盖音乐。"}}]},"media":{"uk":"media/uk/reggae__gb_1.mp3","us":"media/us/reggae__us_1.mp3"}},"remind":{"oxford":{"phon":"rɪˈmaɪnd","pos":"verb","senses":[{"en":"to help somebody remember something, especially something important that they must do","cn":"提醒；使想起","ex":{"en":"I'm sorry, I've forgotten your name. Can you remind me?","cn":"对不起，我忘了你的名字。提醒我一下好吗？"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使想起;使记起;提醒","en":"If someone reminds you of a fact or event that you already know about, they say something which makes you think about it.","ex":{"en":"So she simply welcomed him and reminded him of the last time they had met","cn":"于是她只是对他表示欢迎，并且提醒说他们上次见过面。"}},{"pos":"VERB 动词","cn":"让我提醒你…/我能提醒你…","en":"You use remind in expressions such as Let me remind you that and May I remind you that to introduce a piece of information that you want to emphasize. It may be something that the hearer already knows about or a new piece of information. Sometimes these expressions can sound unfriendly.","ex":{"en":"'Let me remind you,' said Marianne, 'that Manchester is also my home town.'","cn":"“让我来提醒你，”玛丽安娜说，“曼彻斯特也是我的家乡。”"}},{"pos":"VERB 动词","cn":"提醒(某人做某事);使想起(做某事)","en":"If someone reminds you to do a particular thing, they say something which makes you remember to do it.","ex":{"en":"Can you remind me to buy a bottle of Martini?","cn":"你能提醒我买一瓶马提尼酒吗？"}},{"pos":"VERB 动词","cn":"(因为相似)使联想到","en":"If you say that someone or something reminds you of another person or thing, you mean that they are similar to the other person or thing and that they make you think about them. →see usage note at:","ex":{"en":"She reminds me of the wife of the pilot who used to work for you","cn":"她让我想到过去为你工作的飞行员的妻子。"}}]},"media":{"uk":"media/uk/remind__gb_1.mp3","us":"media/us/remind__us_1.mp3"},"examples":[{"en":"‘Don't forget the camera.’ ‘Remind me about it nearer the time.’ “","cn":"别忘了带相机。” “到时候再提醒我一下。”"},{"en":"I'm sorry, I've forgotten your name. Can you remind me?","cn":"对不起，我忘了你的名字。提醒我一下好吗？"}]},"revels":{"oxford":{"phon":"ˈrevl","pos":"verb","senses":[{"en":"to spend time enjoying yourself in a noisy, enthusiastic way","cn":"狂欢作乐"},{"en":"to enjoy sth very much","cn":"陶醉于；着迷于；纵情于"}]}},"records":{"lemma":"record"},"reads":{"lemma":"read"},"recorded":{"lemma":"record"},"recognized":{"lemma":"recognize"},"relied":{"oxford":{"phon":"rɪˈlaɪ","pos":"verb","senses":[{"en":"to need or depend on sb/sth","cn":"依赖；依靠"},{"en":"to trust or have faith in sb/sth","cn":"信任；信赖"}]}},"resources":{"lemma":"resource"},"relying":{"oxford":{"phon":"rɪˈlaɪ","pos":"verb","senses":[{"en":"to need or depend on sb/sth","cn":"依赖；依靠"},{"en":"to trust or have faith in sb/sth","cn":"信任；信赖"}]}},"religions":{"lemma":"religion"},"released":{"lemma":"release"},"returns":{"lemma":"return"},"remained":{"lemma":"remain"},"revealed":{"lemma":"reveal"},"reconsiderations":{"oxford":{"phon":"ˌriːkənˈsɪdə(r)","pos":"verb","senses":[{"en":"to think about sth again, especially because you might want to change a previous decision or opinion","cn":"重新考虑；重新审议"}]}},"reservations":{"lemma":"reservation"},"requests":{"lemma":"request"},"researchers":{"lemma":"researcher"},"recognizes":{"lemma":"recognize"},"receptions":{"lemma":"reception"},"requirements":{"lemma":"requirement"},"represented":{"lemma":"represent"},"readers":{"lemma":"reader"},"reacting":{"lemma":"react"},"refers":{"lemma":"refer"},"reshaping":{"oxford":{"phon":"ˌriːˈʃeɪp","pos":"verb","senses":[{"en":"to change the shape or structure of sth","cn":"改变 … 的形状（或结构）；重塑；改组"}]}},"receiving":{"lemma":"receive","media":{"uk":"media/ldoce/hwd/bre/c/receiving0205.mp3","us":"media/ldoce/hwd/ame/a/ld41receiving.mp3"}},"requires":{"lemma":"require"},"retains":{"lemma":"retain"},"relationships":{"lemma":"relationship"},"resembled":{"lemma":"resemble"},"resulted":{"lemma":"result"},"referred":{"lemma":"refer"},"rests":{"lemma":"rest"},"reroute":{"collins":{"senses":[{"pos":"VERB 动词","cn":"改变线路;改道","en":"If vehicles or planes are re-routed, they are directed along a different route because the usual route cannot be used.","ex":{"en":"The heavy traffic was re-routed past my front door","cn":"大量的车流改道经过我家前门。"}}]},"oxford":{"phon":"ˌriːˈruːt","pos":"verb","senses":[{"en":"to change the route that a road, vehicle, phone call, etc. normally follows","cn":"改变…的路线；改变…的线路","lab":"figurative","ex":{"en":"to reroute a road","cn":"改变道路路线"}}]}},"reforms":{"lemma":"reform"},"republicans":{"lemma":"republican"},"recruited":{"lemma":"recruit"},"relates":{"lemma":"relate"},"repairing":{"lemma":"repair"},"reuniting":{"lemma":"reunite"},"resided":{"oxford":{"phon":"rɪˈzaɪd","pos":"verb","senses":[{"en":"( formal ) to live in a particular place","cn":"居住在；定居于"},{"en":"to be in sb/sth; to be caused by sth","cn":"在于；由 … 造成（或引起）"}]}},"recognise":{"lemma":"recognize"},"reinforced":{"lemma":"reinforce"},"recovering":{"lemma":"recover"},"replied":{"lemma":"reply"},"refused":{"lemma":"refuse"},"rewards":{"lemma":"reward"},"retrieved":{"lemma":"retrieve"},"represents":{"lemma":"represent"},"remembered":{"lemma":"remember"},"reported":{"lemma":"report"},"requiring":{"lemma":"require"},"residing":{"oxford":{"phon":"rɪˈzaɪd","pos":"verb","senses":[{"en":"( formal ) to live in a particular place","cn":"居住在；定居于"},{"en":"to be in sb/sth; to be caused by sth","cn":"在于；由 … 造成（或引起）"}]}},"revelations":{"lemma":"revelation","media":{"uk":"media/ldoce/hwd/bre/5/p028-000010369.mp3","us":"media/ldoce/hwd/ame/5/p028-000010369.mp3"}},"reared":{"lemma":"rear"},"revisions":{"lemma":"revision"},"resisted":{"lemma":"resist"},"regions":{"lemma":"region"},"renders":{"lemma":"render"},"returning":{"lemma":"return"},"resentments":{"lemma":"resentment"},"results":{"lemma":"result"},"recruiting":{"lemma":"recruit"},"reflects":{"lemma":"reflect"},"recitations":{"oxford":{"phon":"ˌresɪˈteɪʃn","pos":"noun","senses":[{"en":"an act of saying a piece of poetry or literature that you have learned to an audience","cn":"朗诵；朗读"},{"en":"an act of talking or writing about a series of things","cn":"逐一列举；逐个叙述"}]}},"remembering":{"lemma":"remember"},"replaced":{"lemma":"replace"},"reckons":{"lemma":"reckon"},"regurgitated":{"oxford":{"phon":"rɪˈɡɜːdʒɪteɪt","pos":"verb","senses":[{"en":"( formal ) to bring food that has been swallowed back up into the mouth again","cn":"使（咽下的食物）返回到口中；反刍"},{"en":"( disapproving ) to repeat sth you have heard or read without really thinking about it or understanding it","cn":"照搬；照本宣科"}]}},"recipients":{"lemma":"recipient"},"reductions":{"lemma":"reduction"},"retires":{"lemma":"retire"},"rents":{"lemma":"rent"},"rewarded":{"lemma":"reward"},"reducing":{"lemma":"reduce"},"recesses":{"lemma":"recess"},"retailers":{"lemma":"retailer"},"restrictions":{"lemma":"restriction"},"respected":{"lemma":"respect","media":{"uk":"media/ldoce/hwd/bre/5/brelasderespected.mp3","us":"media/ldoce/hwd/ame/3/laadrespected.mp3"}},"resting":{"lemma":"rest"},"retreated":{"lemma":"retreat"},"reports":{"lemma":"report"},"reached":{"lemma":"reach"},"resolving":{"lemma":"resolve"},"responses":{"lemma":"response"},"refuses":{"lemma":"refuse"},"relations":{"lemma":"relation"},"releasing":{"lemma":"release"},"resounded":{"oxford":{"phon":"rɪˈzaʊnd","pos":"verb","senses":[{"en":"to fill a place with sound","cn":"回响；回荡"},{"en":"to be filled with sound","cn":"回荡着声音；回响着声音"}]}},"rehabilitated":{"oxford":{"phon":"ˌriːəˈbɪlɪteɪt","pos":"verb","senses":[{"en":"to help sb to have a normal, useful life again after they have been very ill/sick or in prison for a long time","cn":"使（重病患者）康复；使（长期服刑者）恢复正常生活"},{"en":"to begin to consider that sb is good or acceptable after a long period during which they were considered bad or unacceptable","cn":"恢复 … 的名誉；给 … 平反昭雪"}]}},"regarded":{"lemma":"regard"},"residents":{"lemma":"resident"},"required":{"lemma":"require"},"restored":{"lemma":"restore","media":{"uk":"media/ldoce/hwd/bre/2/restored0205.mp3","us":"media/ldoce/hwd/ame/7/ld41restored.mp3"}},"reaching":{"lemma":"reach"},"rewriting":{"lemma":"rewrite"},"recognizing":{"lemma":"recognize"},"readjusting":{"oxford":{"phon":"ˌriːəˈdʒʌst","pos":"verb","senses":[{"en":"to get used to a changed or new situation","cn":"重新适应；再适应"},{"en":"to change or move sth slightly","cn":"稍作改变；微调"}]}},"reverberations":{"oxford":{"phon":"rɪˌvɜːbəˈreɪʃn","pos":"noun","senses":[{"en":"a loud noise that continues for some time after it has been produced because of the surfaces around it","cn":"回响；回声；反响"},{"en":"the effects of sth that happens, especially unpleasant ones that spread among a large number of people","cn":"影响；（尤指）广泛的消极影响"}]}},"realized":{"lemma":"realize"},"returned":{"lemma":"return"},"responding":{"lemma":"respond"},"reflected":{"lemma":"reflect"},"referring":{"lemma":"refer"},"resembling":{"lemma":"resemble"},"reduced":{"lemma":"reduce"},"rescued":{"lemma":"rescue"},"restoring":{"lemma":"restore"},"reasons":{"lemma":"reason"},"resisting":{"lemma":"resist"},"recommendations":{"lemma":"recommendation"},"recruits":{"lemma":"recruit"},"restaurants":{"lemma":"restaurant"},"revenues":{"lemma":"revenue"},"representatives":{"lemma":"representative"},"relegated":{"lemma":"relegate"},"regards":{"lemma":"regard"},"recognised":{"lemma":"recognize"},"reunions":{"lemma":"reunion"},"regretted":{"lemma":"regret"},"relatives":{"lemma":"relative"},"rearranged":{"oxford":{"phon":"ˌriːəˈreɪndʒ","pos":"verb","senses":[{"en":"to change the position or order of things; to change your position","cn":"重新排列；改变位置"},{"en":"to change the time, date or place of an event","cn":"重新安排；改变时间（或日期、地点）"}]}},"rescues":{"lemma":"rescue"},"reddened":{"oxford":{"phon":"ˈredn","pos":"verb","senses":[{"en":"to become red; to make sth red （","cn":"使）变红"}]}},"reconstruct":{"collins":{"senses":[{"pos":"VERB 动词","cn":"重建;重造;修复","en":"If you reconstruct something that has been destroyed or badly damaged, you build it and make it work again.","ex":{"en":"The government must reconstruct the shattered economy","cn":"政府必须重建支离破碎的经济。"}},{"pos":"VERB 动词","cn":"改造;改组","en":"To reconstruct a system or policy means to change it so that it works in a different way.","ex":{"en":"She actually wanted to reconstruct the state and transform society","cn":"她实际上想要重建国家，改造社会。"}},{"pos":"VERB 动词","cn":"使（过去的事件）重现，使再现","en":"If you reconstruct an event that happened in the past, you try to get a complete understanding of it by combining a lot of small pieces of information.","ex":{"en":"He began to reconstruct the events of 21 December 1988, when flight 103 disappeared","cn":"他开始再现1988年12月21日的103次航班失踪事件。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to produce a complete description or copy of an event by collecting together pieces of information 〔","cn":"由零碎的信息〕重现〔事情全貌〕﹐使〔完整的情景〕再现"},{"en":"to build something again after it has been destroyed or damaged","cn":"重建﹐再建"}]},"vocab":{"pos":"v","senses":[{"en":"If the verb to \"construct\" means to build something, then to reconstruct means to build it again. You can reconstruct a building, a city, or even an idea."}]},"collocations":{"phrases":["ADV. completely | partially | painstakingly Every aspect of the original has been closely studied and painstakingly reconstructed.","VERB + RECONSTRUCT attempt to, try to | be possible to It is not possible to reconstruct the complete symphony from these manuscript sketche","PREP. from Local historians have reconstructed from contemporary descriptions how the hall may have looked in 1300.","PHRASES an attempt to reconstruct sth"]},"media":{"uk":"media/ldoce/hwd/bre/0/reconstruct0205.mp3","us":"media/ldoce/hwd/ame/a/reconstruct.mp3"},"examples":[{"en":"They have tried to reconstruct the settlement as it would have been in Iron Age times.","cn":"他们已试着按铁器时代的样子重建这个小村落。"},{"en":"Investigators are trying to reconstruct the circumstances of the crash.","cn":"调查人员正试图重现撞车时的情形。"}],"oxford":{"phon":"ˌriːkənˈstrʌkt","pos":"verb","senses":[{"en":"to build or make something again that has been damaged or that no longer exists","cn":"修复；重建；重造","ex":{"en":"Old London Bridge was bought by an American and reconstructed in the US.","cn":"旧伦敦桥被一个美国人买下，并在美国重新组装。"}},{"en":"to be able to describe or show exactly how a past event happened, using the information you have gathered","cn":"重现描述；使重现","ex":{"en":"Investigators are trying to reconstruct the circumstances of the crash.","cn":"调查人员正试图重现撞车时的情形。"}}]}},"recommendation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"建议;提议;劝告","en":"The recommendations of a person or a committee are their suggestions or advice on what is the best thing to do.","ex":{"en":"The committee's recommendations are unlikely to be made public","cn":"委员会的建议不大可能公开。"}},{"pos":"N-VAR 可变名词","cn":"推荐；介绍","en":"A recommendation of something is the suggestion that someone should have or use it because it is good.","ex":{"en":"On O'Leary's recommendation, they started with tortellini","cn":"在奥利里的推荐下，他们首先点了意大利饺子。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an opinion that is given to someone about what they should do","cn":""},{"en":"a simple but useful piece of advice about the best way to do something","cn":""},{"en":"advice about what to do, usually given by an expert or a group of people who have studied the matter","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you give someone a recommendation, you're saying, \"try this, it's good\" or \"this is the best way to proceed,\" or \"this person will do a great job.\""}]},"collocations":{"phrases":["ADJ. firm, strong | clear | unanimous | detailed | specific | broad, general, wide-ranging The committee put forward broad recommendations f","QUANT. list, series, set","VERB + RECOMMENDATION come up with, make, produce The council has produced a set of recommendations on ethics in health care. | give, offer,","RECOMMENDATION + VERB arise from sth, be based on sth, follow (from) sth, relate to sth a detailed set of recommendations following a compre","PREP. on/upon sb/sth's ~ I had the operation on the recommendation of my doctor. | ~ about/as to/concerning/on recommendations on how health","ADJ. glowing, high/highest | personal It's best to find a builder through personal recommendation.","VERB + RECOMMENDATION give sb/sth | get, receive | come on/with The new housekeeper came on the highest recommendation. The chef comes with ","PREP. at/on/upon sb's ~ At the recommendation of a psychiatrist, the accused will remain under observation. We went to Corfu on your recomme"]},"media":{"uk":"media/ldoce/hwd/bre/a/recommendation0205.mp3","us":"media/ldoce/hwd/ame/e/recommendation.mp3"},"examples":[{"en":"The committee made recommendations to the board on teachers' pay and conditions.","cn":"委员会就教师的工资和工作条件问题向董事会提出建议。"},{"en":"Here's a list of my top CD recommendations.","cn":"这是我认为最值得推荐的 CD 的清单。"}],"oxford":{"phon":"ˌrekəmenˈdeɪʃn","pos":"noun","senses":[{"en":"an official suggestion about the best thing to do","cn":"正式建议；提议","g":"[countable]","ex":{"en":"to accept/reject a recommendation","cn":"接受／拒绝一项建议"}},{"en":"the act of telling somebody that something is good or useful or that somebody would be suitable for a particular job, etc.","cn":"推荐；介绍","g":"[uncountable, countable]","ex":{"en":"It's best to find a builder through personal recommendation.","cn":"最好通过私人介绍寻找施工人员。"}},{"en":"a formal letter or statement that somebody would be suitable for a particular job, etc.","cn":"推荐信；求职介绍信","g":"[countable]","lab":"especially North American English","ex":{"en":"The company gave her a glowing recommendation.","cn":"这家公司为她写了一封评价很高的推荐信。"}}]}},"rewrite":{"collins":{"senses":[{"pos":"VERB 动词","cn":"重写;改写;重新修订","en":"If someone rewrites a piece of writing such as a book, an article, or a law, they write it in a different way in order to improve it.","ex":{"en":"Following this critique, students rewrite their papers and submit them for final evaluation","cn":"学生们遵照这一评语修改了他们的论文，并交上去进行最后的评审。"}},{"pos":"VERB 动词","cn":"改写，篡改(历史)","en":"If you accuse a government of rewriting history, you are criticizing them for selecting and presenting particular historical events in a way that suits their own purposes.","ex":{"en":"We have always been an independent people, no matter how they rewrite history","cn":"不管他们如何篡改历史，我们一直都是一个独立的民族。"}},{"pos":"VERB 动词","cn":"改写，刷新(纪录)","en":"When journalists say that a sports player has rewritten the record books or the history books, they mean that the player has broken a record or several records.","ex":{"en":"...the extraordinary West Country team that have rewritten all the record books in those three years","cn":"在此3年间刷新了所有纪录的超级西南球队"}},{"pos":"N-COUNT 可数名词","cn":"(对剧本等的)改写，修改","en":"In the film and television industries, a rewrite is the writing of parts of a film again in order to improve it.","ex":{"en":"Only after countless rewrites did John consider the script ready.","cn":"只有经过了无数次修改后，约翰才认为剧本写好了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to dishonestly change the meaning of a piece of information or of something that someone has said, in order to get some advantage for yourself or to support your own opinion","cn":""},{"en":"to give people a wrong idea about someone or their opinions, by what you write or say","cn":""},{"en":"to explain facts, statements etc in a way that makes them seem different from what they really are","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you rewrite something, you start from scratch, writing it again to improve it. You might decide to rewrite a poem after your entire poetry class seems confused by your original version."}]},"collocations":{"phrases":["ADV. drastically, extensively, substantially | completely | slightly","PHRASES an attempt to rewrite sth attempts to rewrite history"]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasderewrite.mp3","us":"media/ldoce/hwd/ame/6/rewrite.mp3"},"examples":[{"en":"I intend to rewrite the story for younger children.","cn":"我想为年纪更小的孩子改写这篇故事。"},{"en":"This essay will have to be completely rewritten.","cn":"这篇文章得全部重写。"}],"oxford":{"phon":"ˌriːˈraɪt","pos":"verb","senses":[{"en":"to write something again in a different way, usually in order to improve it or because there is some new information","cn":"重写；改写","ex":{"en":"I intend to rewrite the story for younger children.","cn":"我想为年纪更小的孩子改写这篇故事。"}},{"en":"an act of writing something again in a different way, usually in order to improve it or because there is some new information; something that has been written again in this way","cn":"重写；改写","ex":{"en":"The film underwent many drafts and rewrites.","cn":"这部电影经历了多次草稿和重写。"},"pos":"noun"}]}},"referee":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（比赛的）裁判员","en":"The referee is the official who controls a sports event such as a football game or a boxing match."},{"pos":"VERB 动词","cn":"为…担任裁判；执法（比赛）","en":"When someone referees a sports event or contest, they act as referee.","ex":{"en":"The match will be refereed by Derek Bevan from Wales","cn":"这场比赛将由来自威尔士的德里克·贝文执法。"}},{"pos":"N-COUNT 可数名词","cn":"（求职等时的）推荐人，介绍人，证明人","en":"A referee is a person who gives you a reference, for example when you are applying for a job."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who makes sure that the rules of a sport are obeyed in soccer, American football, rugby, ice hockey, basketball, boxing, or wrestling","cn":""},{"en":"someone who makes sure that the rules are obeyed in baseball, cricket, tennis, or hockey","cn":""},{"en":"someone who decides the result of a competition or sporting contest","cn":""}]},"vocab":{"pos":"1 n v 2 n 3 n v","senses":[{"en":"That guy on the field in black and white stripes? He's a referee , an official in a sport like football or basketball who enforces the rules."}]},"collocations":{"phrases":["ADJ. boxing, football | match, tournament decisions taken by the match referee | international","REFEREE + VERB award sb sth The referee awarded a free kick to the home team. | book sb, send sb off The referee booked three players for of","PHRASES the referee's decision 2 recommends sb for a job","ADJ. academic, professional","VERB + REFEREE act as, be","PREP. ~ for His former employer agreed to act as a referee for him. 3 settles a dispute between people","ADJ. official","VERB + REFEREE act as to act as referee between the parties involved"]},"media":{"uk":"media/ldoce/hwd/bre/2/referee_n0205.mp3","us":"media/ldoce/hwd/ame/2/referee1.mp3"},"examples":[{"en":"He was sent off for arguing with the referee.","cn":"他因为和裁判发生争执而被罚出场。"},{"en":"to act as a referee between the parties involved","cn":"充当相关各方的调解人"}],"oxford":{"phon":"ˌrefəˈriː","pos":"noun","senses":[{"en":"the official who controls the game in some sports","cn":"（某些体育比赛的）裁判，裁判员","lab":"informal","ex":{"en":"He was sent off for arguing with the referee.","cn":"他因为和裁判发生争执而被罚出场。"}},{"en":"a person who gives information about your character and ability, usually in a letter, for example when you are applying for a job","cn":"介绍人；推荐人","lab":"British English","ex":{"en":"The principal often acts as a referee for his students.","cn":"校长经常充当学生的裁判员。"}},{"en":"a person who is asked to settle an argument","cn":"仲裁员；调解人","ex":{"en":"to act as a referee between the parties involved","cn":"充当相关各方的调解人"}},{"en":"a person who reads and checks the quality of an academic article before it is published","cn":"（学术论文的）审阅人，鉴定专家","ex":{"en":"All papers are sent out to external referees.","cn":"所有论文都送外审。"}},{"en":"to act as the referee in a game","cn":"担任裁判；裁判","g":"[intransitive, transitive]","lab":"informal","ex":{"en":"He began refereeing in 2008.","cn":"他于2008年开始担任裁判。"},"pos":"verb"},{"en":"to read and check the quality of an academic article before it is published","cn":"审阅，鉴定（学术论文）","g":"[transitive]","pos":"verb"}]}},"repatriate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"遣返;遣送回国","en":"If a country repatriates someone, it sends them back to their home country.","ex":{"en":"It was not the policy of the government to repatriate genuine refugees","cn":"遣返真正的难民回国并非政府的政策。"}},{"pos":"VERB 动词","cn":"把(海外利润）调回国内","en":"If a company repatriates profits that it has made in another country, it brings them back into its home country.","ex":{"en":"Foreign investors are to be allowed to repatriate profits over one billion rupees.","cn":"外国投资者将被允许将利润额超过10亿卢比的部分调回国内。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a foreigner leave a country because they have broken the law, or for political reasons","cn":""},{"en":"if the authorities in a country deport a foreign person or a member of a particular race who is living in that country, they force them to leave","cn":""},{"en":"to officially send someone back to another country where they are believed to have committed a crime, in order to be tried in a court of law","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When a country repatriates people, they are usually refugees who are being sent back to their homeland, often against their wishes."}]},"collocations":{"phrases":["ADV. forcibly","PREP. from, to The refugees were forcibly repatriated from Hong Kong to Vietnam."]},"media":{"uk":"media/ldoce/hwd/bre/d/repatriate0205.mp3","us":"media/ldoce/hwd/ame/d/repatriate.mp3"},"examples":[{"en":"The refugees were forcibly repatriated.","cn":"难民被强制遣送回国。"},{"en":"the repatriation of immigrants/profits","cn":"遣返移民；调回利润"}],"oxford":{"phon":"ˌriːˈpætrieɪt","pos":"verb","senses":[{"en":"to send or bring somebody back to their own country","cn":"遣送回国；遣返","lab":"formal","ex":{"en":"The refugees were forcibly repatriated.","cn":"难民被强制遣送回国。"}},{"en":"to send money or profits back to your own country","cn":"寄（钱）回国；将（利润）调回本国","lab":"business","ex":{"en":"An agreement between the countries enables companies to repatriate their profits freely.","cn":"两国之间的协议使公司能够自由汇回利润。"}}]}},"replica":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"复制品;仿制品","en":"A replica of something such as a statue, building, or weapon is an accurate copy of it.","ex":{"en":"...a human-sized replica of the Statue of Liberty","cn":"真人大小的自由女神像复制品"}},{"pos":"N-COUNT 可数名词","cn":"翻版;酷似的人","en":"If you say that one person is a replica of another, you mean that the first person looks very like the second.","ex":{"en":"Tina as a child was a replica of her mother.","cn":"蒂娜小的时候和她妈妈简直一模一样。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that has been copied and made to look exactly like something else","cn":""},{"en":"a copy of a piece of paper or a picture that has been made using a machine","cn":""},{"en":"an exact copy of something that can be used in the same way, especially when the original one has been lost","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A replica of something is a close — sometimes exact — likeness. The \"Mona Lisa\" that you bought at the department store is not the original but a replica of da Vinci's masterpiece. Sorry, but you can always take it back."}]},"collocations":{"phrases":["ADJ. exact | full-scale, full-size, life-sized | half-scale, 1:5 scale, etc. | miniature","VERB + REPLICA build, create, construct, make She made a 1:5 scale replica of Captain Cook's ship, &lsquo;The Endeavour&rsquo;.","PREP. in ~ The original conservatory has been rebuilt in replica."]},"media":{"uk":"media/ldoce/hwd/bre/e/replica0205.mp3","us":"media/ldoce/hwd/ame/5/replica.mp3"},"examples":[{"en":"The weapon used in the raid was a replica.","cn":"抢劫案中使用的武器是一件仿制品。"},{"en":"a replica of the Eiffel Tower","cn":"埃菲尔铁塔模型"}],"oxford":{"phon":"ˈreplɪkə","pos":"noun","senses":[{"en":"a very good or exact copy of something","cn":"复制品；仿制品","ex":{"en":"There is even a scaled-down replica of the Eiffel Tower there.","cn":"那儿甚至有一个缩小比例的埃菲尔铁塔模型。"}}]}},"redundancy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"裁减冗员;裁员","en":"When there are redundancies, an organization tells some of its employees to leave because their jobs are no longer necessary or because the organization can no longer afford to pay them.","ex":{"en":"The ministry has said it hopes to avoid compulsory redundancies.","cn":"该部称希望避免强制性裁员。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"裁员;被解雇","en":"Redundancy means being made redundant.","ex":{"en":"Thousands of bank employees are facing redundancy as their employers cut costs","cn":"雇主削减成本的时候，数千名银行雇员面临被解雇的命运。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to make someone leave their job, especially because they have done something wrong","cn":""},{"en":"to make someone leave their job, for example, because they are not good enough at it, they are no longer needed, or they have done something wrong","cn":""},{"en":"to make workers, especially workers in a large factory or organization, leave their jobs, because there is not enough work for them to do, or not enough money to pay their wages","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Use the noun redundancy to refer to something that's needlessly repeated. As much as you hate the redundancy of math drills, you have to admit that repetition is how you learned to multiply in the first place."}]},"collocations":{"phrases":["ADJ. large-scale, major, mass, massive The closure of the mine led to large-scale redundancies. | widespread | threatened | compulsory, enfo","QUANT. round, wave a fresh wave of redundancies","VERB + REDUNDANCY make The bank will be making 3,500 redundancies over the next five years. | lead to, result in | avoid | announce | be thr","REDUNDANCY + VERB occur, take place","REDUNDANCY + NOUN policy | programme | notice Redundancy notices have been sent to 200 workers. | compensation, package, terms | money, pay,","PHRASES the threat of redundancy"]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41redundancy.mp3","us":"media/ldoce/hwd/ame/f/ld41redundancy.mp3"},"examples":[{"en":"Thousands of factory workers are facing redundancy.","cn":"数千名工厂工人面临裁汰。"},{"en":"Natural language is characterized by redundancy (= words are used that are not really necessary for sb to understand the meaning).","cn":"自然语言的特点是繁复。"}],"oxford":{"phon":"rɪˈdʌndənsi","pos":"noun","senses":[{"en":"the situation when somebody has to leave their job because there is no more work available for them","cn":"裁员","g":"[uncountable, countable, usually plural]","lab":"British English","ex":{"en":"Thousands of factory workers are facing redundancy.","cn":"数千名工厂工人面临裁汰。"}},{"en":"the state of not being necessary or useful","cn":"多余；累赘","g":"[uncountable]","lab":"formal or specialist","ex":{"en":"Natural language is characterized by redundancy (= words are used that are not really necessary for somebody to understand the meaning).","cn":"自然语言的特点是繁复。"}}]}},"reprimand":{"collins":{"senses":[{"pos":"VERB 动词","cn":"训斥;斥责;谴责","en":"If someone is reprimanded, they are spoken to angrily or seriously for doing something wrong, usually by a person in authority.","ex":{"en":"He was reprimanded by a teacher for talking in the corridor","cn":"他因为在走廊里讲话受到了一位老师的斥责。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tell someone that they have done something wrong or illegal and are being punished for it – used especially in official contexts","cn":""},{"en":"if a parent, teacher, or other adult scolds a child, they talk to them angrily because they have done something wrong. Scold sounds rather formal and old-fashioned. In everyday English people usually say tell somebody off","cn":""},{"en":"to talk angrily to someone because they have done something wrong. Tell somebody off is more common in British English than American English","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you're reprimanded , someone in authority speaks to you in an angry way because you've done something wrong. Or you might reprimand your dog if he steals your hot dog."}]},"collocations":{"phrases":["ADV. severely | gently | officially | publicly","PREP. for She was severely reprimanded for accepting the money."]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdereprimand.mp3","us":"media/ldoce/hwd/ame/1/reprimand.mp3"},"examples":[{"en":"The officers were severely reprimanded for their unprofessional behaviour.","cn":"军官们因违反专业操守而受到了严厉的斥责。"},{"en":"He received a severe reprimand for his behaviour.","cn":"他的行为受到了谴责。"}],"oxford":{"phon":"ˈreprɪmɑːnd","pos":"noun","senses":[{"en":"the act of telling somebody officially that you do not approve of them or their actions","cn":"正式告诉某人你不赞成他们或他们的行为","ex":{"en":"He received a severe reprimand for his behaviour.","cn":"他因其行为受到了严厉的斥责。"}},{"en":"to tell somebody officially that you do not approve of them or their actions","cn":"申斥；训斥；斥责","ex":{"en":"The officers were severely reprimanded for their unprofessional behaviour.","cn":"军官们因违反职业操守而受到了严厉的斥责。"},"pos":"verb"}]}},"reassurance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"安慰；慰藉","en":"If someone needs reassurance, they are very worried and need someone to help them stop worrying by saying kind or helpful things.","ex":{"en":"She needed reassurance that she belonged somewhere","cn":"她需要一种归属感让她安心。"}},{"pos":"N-COUNT 可数名词","cn":"安慰（的话语）；保证","en":"Reassurances are things that you say to help people stop worrying about something.","ex":{"en":"...reassurances that pesticides are not harmful.","cn":"杀虫剂没有危害的保证"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is said or done which makes someone feel calmer and less worried or frightened about a problem","cn":"令人安心的保证﹔能消除疑惧的言行"}]},"collocations":{"phrases":["ADJ. great | further | constant, continual | calm Continual calm reassurance should be given.","VERB + REASSURANCE have We have had some reassurances from the council that the building will be saved. | need, want | look for, seek He gla","PREP. despite ~ She kept looking in the mirror despite my constant reassurances that her hair looked fine. | for ~ He held onto her hand for"]},"media":{"uk":"media/ldoce/hwd/bre/7/reassurance0205.mp3","us":"media/ldoce/hwd/ame/e/laadreassurance.mp3"},"examples":[{"en":"We have been given reassurances that the water is safe to drink.","cn":"我们得到保证说这水适合饮用。"},{"en":"to give/provide/offer reassurance","cn":"表明肯定的态度"}],"oxford":{"phon":"ˌriːəˈʃʊərəns","pos":"noun","senses":[{"en":"the fact of giving advice or help that takes away a person’s fears or doubts","cn":"（能消除疑虑等的）肯定，保证","g":"[uncountable]","ex":{"en":"to give/provide/offer reassurance","cn":"表明肯定的态度"}},{"en":"something that is said or done to take away a person’s fears or doubts","cn":"能消除疑虑的话（或行动）；保证","g":"[countable]","ex":{"en":"We have been given reassurances that the water is safe to drink.","cn":"我们得到保证说这水适合饮用。"}}]}},"recover":{"collins":{"senses":[{"pos":"VERB 动词","cn":"恢复健康；复原","en":"When you recover from an illness or an injury, you become well again.","ex":{"en":"He is recovering from a knee injury","cn":"他的膝伤正在康复。"}},{"pos":"VERB 动词","cn":"（从不开心或不愉快的经历中）恢复，复原","en":"If you recover from an unhappy or unpleasant experience, you stop being upset by it.","ex":{"en":"...a tragedy from which he never fully recovered","cn":"他一直未能完全从中走出的悲剧"}},{"pos":"VERB 动词","cn":"（从弱势或困境中）好转，扭转，恢复","en":"If something recovers from a period of weakness or difficulty, it improves or gets stronger again.","ex":{"en":"He recovered from a 4-2 deficit to reach the quarter-finals","cn":"他在2比4落后的情况下实现逆转闯进1/4决赛。"}},{"pos":"VERB 动词","cn":"重新找到;重新拿回","en":"If you recover something that has been lost or stolen, you find it or get it back.","ex":{"en":"Police raided five houses in south-east London and recovered stolen goods","cn":"警方突击搜查了伦敦东南区的5幢房屋，找到了失窃物品。"}},{"pos":"VERB 动词","cn":"恢复（意识、神志或身体状态）","en":"If you recover a mental or physical state, it comes back again. For example, if you recover consciousness, you become conscious again.","ex":{"en":"For a minute he looked uncertain, and then recovered his composure","cn":"有一小会儿他看上去有些迟疑不定，之后又恢复了镇定。"}},{"pos":"VERB 动词","cn":"收回（花掉、投资或借出的钱）","en":"If you recover money that you have spent, invested, or lent to someone, you get the same amount back.","ex":{"en":"Legal action is being taken to try to recover the money","cn":"正在进行诉讼以收回那笔钱。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to become healthy again after you have been seriously ill or injured, or had a bad experience 〔","cn":"从伤病中〕康复﹔〔从糟糕经历中〕恢复"},{"en":"to recover from an injury or illness. In everyday English, people usually say get better rather than recover 〔","cn":"受伤或生病后〕康复﹐好转〔在日常英语中﹐人们一般说get better﹐而不说recover〕"},{"en":"to recover from a bad experience, or a minor illness. In everyday English, people usually say get over rather than recover","cn":"从〔糟糕经历或小病中〕恢复过来〔在日常英语中﹐人们一般说get over﹐而不说recover〕"}]},"vocab":{"pos":"1 v 2 v 3 v 4 v","senses":[{"en":"To recover something is to get it back. After you lose your watch, you might recover it from the wastebasket."}]},"collocations":{"phrases":["ADV. completely, fully | partially | only just | hardly, never/not quite, never really She had hardly recovered from the birth of her last b","VERB + RECOVER help sb (to) | struggle to Yates is struggling to recover form a serious knee injury.","PREP. from Mrs Burton was last night recovering from her injuries in hospital."]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasderecover.mp3","us":"media/ldoce/hwd/ame/c/recover.mp3"},"examples":[{"en":"It can take many years to recover from the death of a loved one.","cn":"从心爱的人去世的痛苦中恢复过来可能要花很多年。"},{"en":"She is now fully recovered from her injuries.","cn":"她现在已经完全从伤痛中恢复过来了。"}],"oxford":{"phon":"rɪˈkʌvə(r)","pos":"verb","senses":[{"en":"to get well again after being ill, hurt, etc.","cn":"恢复健康；康复；痊愈","g":"[intransitive]","sc":"from illness","ex":{"en":"He's still recovering from his operation.","cn":"手术后，他仍在恢复之中。"}},{"en":"to return to a normal state after an unpleasant or unusual experience or a period of difficulty","cn":"复原；恢复常态","g":"[intransitive]","sc":"from something unpleasant","ex":{"en":"It can take many years to recover from the death of a loved one.","cn":"从心爱的人去世的痛苦中恢复过来可能要花很多年。"}},{"en":"to get back the same amount of money that you have spent or that is owed to you","cn":"全额收回；追回","g":"[transitive]","sc":"money","ex":{"en":"He is unlikely to ever recover his legal costs.","cn":"他不大可能收回他的诉讼费用了。"}},{"en":"to get back or find something that was lost, stolen or missing","cn":"找回；寻回；找到","g":"[transitive]","sc":"something lost/stolen","ex":{"en":"The police eventually recovered the stolen paintings.","cn":"警方最终追回了失窃的油画。"}},{"en":"to win back a position, level, status, etc. that has been lost","cn":"赢回；重新获得","g":"[transitive]","sc":"position/status","ex":{"en":"The team recovered its lead in the second half.","cn":"下半场这支队再次领先。"}},{"en":"to get back the use of your senses, control of your emotions, etc.","cn":"恢复；重新控制","g":"[transitive]","sc":"senses/emotions","ex":{"en":"It took her a few minutes to recover consciousness.","cn":"过了几分钟她才恢复知觉。"}}]}},"recoil":{"collins":{"senses":[{"pos":"VERB 动词","cn":"退缩;后退","en":"If something makes you recoil, you move your body quickly away from it because it frightens, offends, or hurts you.","ex":{"en":"For a moment I thought he was going to kiss me. I recoiled in horror","cn":"我当时以为他要亲我，所以吓得直往后退。"}},{"pos":"VERB 动词","cn":"（因为不喜欢而）拒绝，回绝，退避","en":"If you recoil from doing something or recoil at the idea of something, you refuse to do it or accept it because you dislike it so much.","ex":{"en":"People used to recoil from the idea of getting into debt","cn":"过去人们不能接受欠债这种事情。"}},{"pos":"N-SING 单数名词","cn":"（枪炮的）反冲","en":"The recoil of a gun is the quick backward movement that it makes when it is fired.","ex":{"en":"The policeman fires again, tensed against the recoil, unleashing round after round at his assailant","cn":"警察再次开火，紧抵着反冲机构，不断向袭击他的人射击。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to walk backwards in a particular direction, especially in order to leave a room or building","cn":""},{"en":"to walk slowly backwards, especially to get further away from someone or to avoid a dangerous situation","cn":""},{"en":"to move backwards a little, for example in order to give someone enough space to move","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"A recoil is a movement backwards, usually from some force or impact. The recoil of a gun is a backward movement caused by momentum. Your trip to the shooting range might make your mom recoil — from horror, not momentum."}]},"collocations":{"phrases":["ADV. a little, slightly | instinctively As he leaned towards her she instinctively recoiled.","PREP. at Howard recoiled a little at the sharpness in my voice. | from She felt him recoil from her, frightened. | in He recoiled in apparen"]},"media":{"uk":"media/ldoce/hwd/bre/0/recoil0205.mp3","us":"media/ldoce/hwd/ame/b/l3recoil.mp3"},"examples":[{"en":"She recoiled from the idea of betraying her own brother.","cn":"背叛自己亲兄弟的这个想法使她感到恐惧。"},{"en":"He recoiled in horror at the sight of the corpse.","cn":"他一见到尸体就吓得往后缩了。"}],"oxford":{"phon":"rɪˈkɔɪl","pos":"verb","senses":[{"en":"to move your body quickly away from somebody/something because you find them or it frightening or unpleasant","cn":"退缩；畏缩","g":"[intransitive]","ex":{"en":"She recoiled from his touch.","cn":"她躲开他的触摸。"}},{"en":"to react to an idea or a situation with strong dislike or fear","cn":"对…作出厌恶（或恐惧）的反应","g":"[intransitive]","ex":{"en":"She recoiled from the idea of betraying her own brother.","cn":"背叛自己亲兄弟的这个想法使她感到恐惧。"}},{"en":"to move suddenly backwards when it is fired","cn":"反冲；产生后坐力","g":"[intransitive]"},{"en":"a sudden movement backwards, especially of a gun when it is fired","cn":"反冲；（尤指枪炮的）后坐力","ex":{"en":"The recoil was so violent it almost tore the weapon from his grasp.","cn":"后坐力如此猛烈，几乎将武器从他手中夺走。"},"pos":"noun"}]}},"reinforcement":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"援军;增援部队","en":"Reinforcements are soldiers or policemen who are sent to join an army or group of police in order to make it stronger.","ex":{"en":"...the despatch of police and troop reinforcements.","cn":"派遣警察和军队支援"}},{"pos":"N-VAR 可变名词","cn":"增强;加强;加固","en":"The reinforcement of something is the process of making it stronger.","ex":{"en":"I am sure that this meeting will contribute to the reinforcement of peace and security all over the world","cn":"我相信这次会议将会促进世界范围内的和平与安全。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"more soldiers, police etc who are sent to a battle, fight etc to make their group stronger","cn":"援兵﹐增援部队"},{"en":"positive reinforcement is when you give someone praise or rewards for their behaviour or work, so they want to continue doing well. Negative reinforcement is when you give someone punishments or criticism when their behaviour or work is bad, so that they want ","cn":"正强化/负强化〔正强化指给予某人表扬或奖励﹐使其继续表现良好﹔负强化指给予某人惩罚或批评﹐使其改正以免再次受到惩罚〕"},{"en":"the act of making something stronger","cn":"加强﹐加固"}]},"vocab":{"pos":"n","senses":[{"en":"Reinforcement is a way to learn and remember things, like a student who repeats the facts he has studied for a test over and over, or the ways we praise children when they share their toys or say \"please\" and \"thank you\" — reinforcement of the good manners we want them to use."}]},"collocations":{"phrases":["ADJ. powerful","VERB + REINFORCEMENT provide The minister's statement provides reinforcement for the view that tax cuts are likely in the budget. | receive ","ADJ. police, troop","VERB + REINFORCEMENT call for, call in, send for, summon The crowd was very large and police reinforcements were called in. | bring in, send","REINFORCEMENT + VERB arrive Reinforcements arrived too late."]},"media":{"uk":"media/ldoce/hwd/bre/5/reinforcement0205.mp3","us":"media/ldoce/hwd/ame/e/laadreinforcement.mp3"},"examples":[{"en":"to send in reinforcements","cn":"派出增援部队"},{"en":"The police called for reinforcements .","cn":"警方要求增援。"}],"oxford":{"phon":"ˌriːɪnˈfɔːsmənt","pos":"noun","senses":[{"en":"extra soldiers or police officers who are sent to a place because more are needed","cn":"援军；增援警力","g":"[plural]","ex":{"en":"to send in reinforcements","cn":"派出增援部队"}},{"en":"the act of making something stronger, especially a feeling or an idea","cn":"（感情或思想等的）巩固，加强，强化","g":"[uncountable, singular]","ex":{"en":"the reinforcement of existing prejudices by the media","cn":"媒体强化现有偏见"}}]}},"recycle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"回收利用；循环利用","en":"If you recycle things that have already been used, such as bottles or sheets of paper, you process them so that they can be used again.","ex":{"en":"The objective would be to recycle 98 per cent of domestic waste","cn":"目标是对 98%的生活垃圾进行回收利用。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use something more than once","cn":""},{"en":"to put bottles, newspapers, cans etc through a process so that they can be used for making new glass products, paper etc","cn":""},{"en":"to put used objects or materials through a special process so that they can be used again","cn":"再利用﹐回收利用"}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"When you recycle something, you process it so it can be used again. You might recycle an old tire and make it into a snazzy black knapsack with some very cool skid marks."}]},"collocations":{"phrases":["ADV. endlessly, regularly (often figurative) endlessly recycling the same worn-out arguments","PREP. from made of plastic recycled from old packaging material | into These materials can be recycled into other packaging products."]},"media":{"uk":"media/ldoce/hwd/bre/7/recycle0205.mp3","us":"media/ldoce/hwd/ame/b/recycle.mp3"},"examples":[{"en":"He recycled all his old jokes.","cn":"他把那些老掉牙的笑话又说了一遍。"},{"en":"Denmark recycles nearly 85% of its paper.","cn":"丹麦的纸张回收率接近 85%。"}],"oxford":{"phon":"ˌriːˈsaɪkl","pos":"verb","senses":[{"en":"to treat things that have already been used so that they can be used again","cn":"回收利用；再利用","lab":"especially British English","ex":{"en":"to recycle waste/rubbish","cn":"回收废品／垃圾"}},{"en":"to use the same ideas, methods, jokes, etc. again","cn":"再次应用，重新使用（概念、方法、玩笑等）","ex":{"en":"He recycled all his old jokes.","cn":"他把那些老掉牙的笑话又说了一遍。"}}]}},"repressed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(感情、欲望，尤指性欲)被压抑的，受到抑制的","en":"A repressed person is someone who does not allow themselves to have natural feelings and desires, especially sexual ones.","ex":{"en":"Some have charged that the Puritans were sexually repressed and inhibited.","cn":"一些人谴责说清教徒的性欲受到压抑，并且个性拘谨。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feelings or attitudes that are disguised are kept hidden, but usually not very well","cn":""},{"en":"strong feelings, such as anger, fear, or happiness, that are suppressed are ones that you do not allow yourself to feel or show","cn":""},{"en":"feelings that are repressed are ones that you deliberately stop yourself from feeling, or have been taught not to feel from when you were a child, especially feelings that you are ashamed of","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If something is repressed , it's restrained or held in. You may be full of repressed anger toward your brother over that terrifying incident from 4 years ago involving the frog and your hooded sweatshirt."}]},"collocations":{"phrases":["VERBS be | become","ADV. extremely, severely, very | rather | sexually women who are sexually repressed"]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasderepressed.mp3","us":"media/ldoce/hwd/ame/0/laadrepressed.mp3"},"examples":[{"en":"repressed anger","cn":"被抑制的怒气"},{"en":"a repressed middle-aged woman","cn":"一个压抑的中年妇女"}],"oxford":{"phon":"rɪˈprest","pos":"adjective","senses":[{"en":"having emotions or desires that are not allowed to be expressed","cn":"压抑的；克制的","ex":{"en":"people who are sexually repressed","cn":"性压抑的人"}},{"en":"not expressed openly","cn":"受压抑的；被抑制的","ex":{"en":"repressed anger","cn":"被抑制的怒气"}}]},"base":"repress"},"refinement":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"完善;修正;改进","en":"Refinements are small changes or additions that you make to something in order to improve it. Refinement is the process of making refinements.","ex":{"en":"Older cars inevitably lack the latest safety refinements.","cn":"老款的汽车难免缺少经过改进的最新安全保护装置。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"彬彬有礼;有教养","en":"Refinement is politeness and good manners.","ex":{"en":"...a girl who possessed both dignity and refinement.","cn":"既有尊严又有教养的女孩"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an improvement, usually a small one, to something 〔","cn":"一般指细微的〕改进﹐改善"},{"en":"something which is an improved version of an existing product, system etc","cn":"改良品﹐经过改进的东西"},{"en":"the process of improving something","cn":"改良﹐改进"}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"Do you know which fork is for your salad and which one for dessert? Then you have some refinement — good manners and taste."}]},"collocations":{"phrases":["ADJ. considerable, great A greater refinement of the categorization is possible. | extra, further | continuous, endless All programs have bu","QUANT. degree","VERB + REFINEMENT need, require The technology requires a great deal of refinement. | add, introduce","PREP. ~ in a refinement in the masonry | ~ on a refinement on previous methods | ~ to to add a further refinement to the computer system 2 b","ADJ. great a woman of great refinement and beauty","VERB + REFINEMENT lack The kite was star shaped and lacked the refinement of current designs.","PREP. ~ in a lack of refinement in engine design","PHRASES a lack of refinement"]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41refinement.mp3","us":"media/ldoce/hwd/ame/9/refinement.mp3"},"examples":[{"en":"This particular model has a further refinement.","cn":"这一款式又有了进一步的改进。"},{"en":"The new plan is a refinement of the one before.","cn":"新计划比原计划有改进。"}],"oxford":{"phon":"rɪˈfaɪnmənt","pos":"noun","senses":[{"en":"a small change to something that improves it","cn":"（精细的）改进，改善","g":"[countable]","ex":{"en":"This particular model has a further refinement.","cn":"这一款式又有了进一步的改进。"}},{"en":"a thing that is an improvement on an earlier, similar thing; the quality of being improved in this way","cn":"改良品；经过改进的东西；改良","g":"[countable, uncountable]","ex":{"en":"The new plan is a refinement of the one before.","cn":"新计划比原计划有改进。"}},{"en":"the process of improving something or of making something pure","cn":"精炼；提炼；提纯","g":"[uncountable]","ex":{"en":"the refinement of industrial techniques","cn":"工业技术的进一步提高"}},{"en":"the quality of being polite and well educated and able to judge the quality of things; the state of having the sort of manners that are considered typical of a high social class","cn":"礼貌；优雅；有教养","g":"[uncountable]","ex":{"en":"a person of considerable refinement","cn":"很有教养的人"}}]}},"relinquish":{"collins":{"senses":[{"pos":"VERB 动词","cn":"放弃，出让(权力或控制)","en":"If you relinquish something such as power or control, you give it up.","ex":{"en":"He does not intend to relinquish power.","cn":"他没有打算放弃权力。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give something to someone in authority, for example to the police or a teacher","cn":""},{"en":"to give something such as weapons or important documents to the police or to government officials, when you should not legally have them or you have been officially asked to give them","cn":""},{"en":"to give something to someone because they have asked or forced you to","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you relinquish something, you let it go. You relinquish control of the army when you resign as general. Your relinquish your plan to sneak into town when your parents find out what's going on."}]},"collocations":{"phrases":["ADV. voluntarily They will never voluntarily relinquish their independence.","VERB + RELINQUISH be forced to He was forced to relinquish control of the company. | refuse to | be willing to | be reluctant to | persuade ","PREP. to She has relinquished the post to her cousin, Sir Edward."]},"media":{"uk":"media/ldoce/hwd/bre/6/relinquish0205.mp3","us":"media/ldoce/hwd/ame/1/relinquish.mp3"},"examples":[{"en":"They had relinquished all hope that she was alive.","cn":"他们已经完全不指望她还活着了。"},{"en":"He was forced to relinquish control of the company.","cn":"他被迫放弃对公司的控制权。"}],"oxford":{"phon":"rɪˈlɪŋkwɪʃ","pos":"verb","senses":[{"en":"to stop having something, especially when this happens unwillingly","cn":"（尤指不情愿地）放弃","ex":{"en":"He was forced to relinquish control of the company.","cn":"他被迫放弃对公司的控制权。"}}]}},"reminiscent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人想起的;使人忆起的","en":"If you say that one thing is reminiscent of another, you mean that it reminds you of it.","ex":{"en":"The decor was reminiscent of a municipal arts-and-leisure centre","cn":"这种布置让人想起都市里的艺术休闲中心。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"怀旧的;缅怀过去的","en":"A reminiscent look or smile is a look or smile which shows that you are remembering something from the past, usually with pleasure.","ex":{"en":"A slow, reminiscent smile spread over her face.","cn":"怀旧的微笑慢慢浮现在她脸上。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"reminding you of something","cn":"使人想起某事物的"},{"en":"thinking about the past","cn":"回忆往事的﹐怀旧的"}]},"vocab":{"pos":"adj","senses":[{"en":"If your uncle tells you that your outfit is reminiscent of the way your mother dressed when she was young, it means your clothes remind him of your mother. Hopefully that doesn't mean your mother is still dressing you."}]},"collocations":{"phrases":["VERBS be","ADV. closely, highly, strongly, very This painting is strongly reminiscent of da Vinci's &lsquo;Annunciation&rsquo;. | faintly, slightly, so","PREP. of"]},"media":{"uk":"media/ldoce/hwd/bre/d/reminiscent0205.mp3","us":"media/ldoce/hwd/ame/0/reminiscent.mp3"},"examples":[{"en":"The way he laughed was strongly reminiscent of his father.","cn":"他笑的样子让人很容易想起他的父亲。"},{"en":"a reminiscent smile","cn":"追忆往事时露出的微笑"}],"oxford":{"phon":"ˌremɪˈnɪsnt","pos":"adjective","senses":[{"en":"reminding you of somebody/something","cn":"使回忆起（人或事）","ex":{"en":"The way he laughed was strongly reminiscent of his father.","cn":"他笑的样子让人很容易想起他的父亲。"}},{"en":"showing that you are thinking about the past, especially in a way that causes you pleasure","cn":"回忆过去的；怀旧的；缅怀往事的","g":"[only before noun]","lab":"formal","ex":{"en":"a reminiscent smile","cn":"追忆往事时露出的微笑"}}]}},"reprisal":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"报复（行为）","en":"If you do something to a person in reprisal, you hurt or punish them because they have done something violent or unpleasant to you.","ex":{"en":"There were fears that some of the Western hostages might be killed in reprisal","cn":"有人担心一些西方人质可能会受到报复性杀害。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an action, especially a military or political one, that is a reaction to something that has been done by a country, government, organization etc","cn":""},{"en":"revenge, especially in the form of violent actions or behaviour, for something very harmful or violent that someone has done","cn":""},{"en":"a quarrel between two people or groups of people that has continued for a long time and during which the two sides keep trying to get revenge on each other","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A reprisal is an act of retaliation, especially one committed by one country against another. If you attack your enemy's village and cause lots of damage, expect a reprisal ."}]},"collocations":{"phrases":["ADJ. bloody, savage","VERB + REPRISAL take The gang threatened to take reprisals against them. | threaten (sb with) | suffer She tried to persuade the soldiers th","REPRISAL + NOUN attack, raid","PREP. in ~ for A dozen hostages were shot in reprisal for the killing of an army officer. | ~ against reprisals against witnesses for the ev","PHRASES fear of reprisals"]},"media":{"uk":"media/ldoce/hwd/bre/c/reprisal0205.mp3","us":"media/ldoce/hwd/ame/6/reprisal.mp3"},"examples":[{"en":"They shot ten hostages in reprisal for the assassination of their leader.","cn":"他们的首领遭到暗杀。为了报复，他们枪杀了十名人质。"},{"en":"They did not want to give evidence for fear of reprisals.","cn":"他们因为害怕报复而不想提供证据。"}],"oxford":{"phon":"rɪˈpraɪzl","pos":"noun","senses":[{"en":"a violent or aggressive act towards somebody because of something bad that they have done towards you","cn":"报复；报复行动","ex":{"en":"They did not want to give evidence for fear of reprisals.","cn":"他们因为害怕报复而不想作证。"}}]}},"regime":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"政权，政体（指非民主且统治手段不被认可的政府或政权体系）","en":"If you refer to a government or system of running a country as a regime, you are critical of it because you think it is not democratic and uses unacceptable methods.","ex":{"en":"...the collapse of the Fascist regime at the end of the war","cn":"在战争末期法西斯政权的倒台"}},{"pos":"N-COUNT 可数名词","cn":"（机构、公司、经济等的）管理制度，组织方法","en":"A regime is the way that something such as an institution, company, or economy is run, especially when it involves tough or severe action.","ex":{"en":"The authorities moved him to the less rigid regime of an open prison.","cn":"当局把他转到一个管制不那么严格的开放式监狱。"}},{"pos":"N-COUNT 可数名词","cn":"养生法","en":"A regime is a set of rules about food, exercise, or beauty that some people follow in order to stay healthy or attractive.","ex":{"en":"He has a new fitness regime to strengthen his back.","cn":"他有一个增强背部力量的新健身计划。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the group of people who govern a country or the system they use to govern it","cn":""},{"en":"the government of a country, especially one such as the US, which is led by a president","cn":""},{"en":"a government, especially one that was not elected fairly or that you disapprove of","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A regime is the ruling government of a country. The amount of freedom and restriction that citizens of a country have can change from regime to regime ."}]},"collocations":{"phrases":["ADJ. new | old | current, established, existing, present | former, previous | interim | political | conservative, liberal, radical | authori","VERB + REGIME establish, install, set up | defeat, overthrow, topple | bolster, strengthen Education was seen as a way of bolstering the exi","REGIME + VERB exist | come to power The communist regime came to power in 1975. | collapse, fall","PREP. against a/the ~ She called for sanctions against the regime. | under a/the ~ He spoke of the abhorrent crimes that had been committed ","PHRASES a change of regime, the collapse/fall/overthrow of a regime, a member of a regime 2 set of rules/procedures","ADJ. harsh, rigorous, strict, tight | relaxed | new | special | exercise, fitness, health, training | dietary | drug, therapeutic, treatment","VERB + REGIME create, introduce, set up, start It will be necessary to create a regime to monitor compliance with the agreements. | impose |","REGIME + VERB be based on sth a regime based on discipline and training"]},"media":{"uk":"media/ldoce/hwd/bre/b/regime0205.mp3","us":"media/ldoce/hwd/ame/f/regime.mp3"},"examples":[{"en":"Our tax regime is one of the most favourable in Europe.","cn":"我们的税收管理体制是欧洲最受欢迎的税收体制之一。"},{"en":"a fascist/totalitarian/military, etc. regime","cn":"法西斯、极权主义、军事等政权"}],"oxford":{"phon":"reɪˈʒiːm","pos":"noun","senses":[{"en":"a method or system of government, especially one that has not been elected in a fair way","cn":"（尤指未通过公正选举的）统治方式，统治制度，政权，政体","lab":"especially North American English","ex":{"en":"a fascist/totalitarian/military, etc. regime","cn":"法西斯、极权主义、军事等政权"}},{"en":"a method or system of organizing or managing something","cn":"组织方法；管理体制","ex":{"en":"Our tax regime is one of the most favourable in Europe.","cn":"我们的税收管理体制是欧洲最受欢迎的税收体制之一。"}},{"en":"a set of rules about food and exercise or medical treatment that you follow in order to stay healthy or to improve your health","cn":"生活规则；养生之道；养生法","lab":"medical or formal","ex":{"en":"a dietary regime","cn":"饮食规则"}}]}},"reappraisal":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"重新评价；重新评估；再评定","en":"If there is a reappraisal of something such as an idea or plan, people think about the idea carefully and decide whether they want to change it.","ex":{"en":"Britain's worst jail riot will force a fundamental reappraisal of prison policy","cn":"英国最严重的监狱暴动会迫使政府对监狱政策进行彻底的重新评估。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to examine something again in order to consider whether you should change it or your opinion of it","cn":""}]},"collocations":{"phrases":["ADJ. fundamental, major, radical | complete | constant | careful | critical a critical reappraisal of existing ideas and social institutions","VERB + REAPPRAISAL cause, lead to Her theory is that disillusionment with employment leads to reappraisal of career goals. | undertake They "]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41reappraise.mp3","us":"media/ldoce/hwd/ame/6/reappraise.mp3"},"examples":[{"en":"People began to reappraise their values.","cn":""}],"oxford":{"phon":"ˌriːəˈpreɪzl","pos":"noun","senses":[{"en":"the act of examining something again to see if it needs to be changed","cn":"重新检查；重新评价","ex":{"en":"a reappraisal of the country’s defence needs","cn":"重新评估国家的国防需求"}}]}},"recognizable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可辨认的;可认出的","en":"If something can be easily recognized or identified, you can say that it is easily recognizable .","ex":{"en":"The body was found to be well preserved, his features easily recognizable","cn":"尸体保存完好，他的容貌特征清晰可辨。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to know who someone is or what something is, especially because you have seen or heard them before","cn":""},{"en":"to recognize someone or something and say who or what they are","cn":""},{"en":"to recognize and understand the difference between two or more things or people","cn":""}]},"collocations":{"phrases":["VERBS be | become | remain","ADV. clearly, easily, immediately, instantly, quite, readily John's car was easily recognizable in the car park. a building that was immedia","PREP. as a language barely recognizable as English | by recognizable by their distinctive uniforms | to The scheme's benefits were recogniza"]},"media":{"uk":"media/ldoce/hwd/bre/d/recognize0205.mp3","us":"media/ldoce/hwd/ame/0/recognize.mp3"},"examples":[{"en":"After so many years she was still instantly recognizable.","cn":"过了这么多年，还是一眼就能认出她。"},{"en":"The building was easily recognizable as a prison.","cn":"很容易看出这座建筑是所监狱。"}],"oxford":{"phon":"ˈrekəɡnaɪzəbl","pos":"adjective","senses":[{"en":"easy to know or identify","cn":"容易认出的；易于识别的","ex":{"en":"The building was easily recognizable as a prison.","cn":"很容易看出这座建筑是所监狱。"}}]}},"reliance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"依赖；依靠","en":"A person's or thing's reliance on something is the fact that they need it and often cannot live or work without it.","ex":{"en":"...the country's increasing reliance on foreign aid.","cn":"这个国家日益依赖外国援助"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone or something is dependent on someone or something else","cn":"依靠﹔依赖"}]},"vocab":{"pos":"n","senses":[{"en":"The word reliance is the noun form of the verb rely , which means to depend. Your reliance on the Internet for your information will be your undoing, if the power ever goes out."}]},"collocations":{"phrases":["ADJ. complete, total | considerable, great, heavy, strong Too heavy a reliance on a particular market may be dangerous for the company. | ex","QUANT. degree a high degree of reliance on newspaper reports","VERB + RELIANCE place I don't think you should place too much reliance on these figures. | act in (law) | increase | reduce | eliminate the ","PREP. in ~ on/upon (law) He acted in complete reliance on the account of a couple of eyewitnesses. | ~ on/upon the increased reliance of the"]},"media":{"uk":"media/ldoce/hwd/bre/9/reliance0205.mp3","us":"media/ldoce/hwd/ame/4/reliance.mp3"},"examples":[{"en":"Such learning methods encourage too great a reliance upon the teacher.","cn":"这样的学习方法会造成对老师的过分依赖。"},{"en":"Heavy reliance on one client is risky when you are building up a business.","cn":"创业时过分依赖某一个客户是有风险的。"}],"oxford":{"phon":"rɪˈlaɪəns","pos":"noun","senses":[{"en":"the state of needing somebody/something in order to survive, be successful, etc.; the fact of being able to rely on somebody/something","cn":"依赖；依靠；信任","ex":{"en":"Heavy reliance on one client is risky when you are building up a business.","cn":"创业时过分依赖某一个客户是有风险的。"}}]}},"resentment":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"怨恨;愤慨;憎恨","en":"Resentment is bitterness and anger that someone feels about something.","ex":{"en":"She expressed resentment at being interviewed by a social worker","cn":"她表达了对被一位社工采访的愤恨。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong emotion that you feel because someone has behaved badly or because a situation seems bad or unfair","cn":""},{"en":"slight anger or impatience","cn":""},{"en":"a feeling of being annoyed and impatient, especially because something keeps happening or someone keeps saying something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Resentment, or the strong and painful bitterness you feel when someone does something wrong to you, doesn’t have actual physical weight, but it feels very heavy and can last a long time. Forgiveness is one way to get rid of resentment."}]},"collocations":{"phrases":["ADJ. angry, bitter, considerable, deep, deep-seated, great, intense, smouldering | growing, increasing | popular, widespread | old She felt ","VERB + RESENTMENT bear, feel, harbour I bore him no resentment. You seem to be harbouring some resentment against your boss. | express, show","RESENTMENT + VERB build up, grow Don't let your resentment build up. | flare up","PREP. ~ about/over Maggie was filled with resentment about her treatment. | ~ against the growing resentment against foreigners | ~ among Th","PHRASES a cause/source of resentment, a feeling/sense of resentment"]},"media":{"uk":"media/ldoce/hwd/bre/1/resentment0205.mp3","us":"media/ldoce/hwd/ame/b/resentment.mp3"},"examples":[{"en":"She could not conceal the deep resentment she felt at the way she had been treated.","cn":"受到那样的待遇，她无法掩藏内心强烈的愤恨。"},{"en":"to feel/harbour/bear resentment towards/against sb","cn":"对某人感到/深怀/有怨恨"}],"oxford":{"phon":"rɪˈzentmənt","pos":"noun","senses":[{"en":"a feeling of anger or unhappiness about something that you think is unfair","cn":"愤恨；怨恨","ex":{"en":"to feel/harbour/bear resentment towards/against somebody","cn":"对某人感到／深怀／有怨恨"}}]}},"reprieve":{"collins":{"senses":[{"pos":"VERB 动词","cn":"对…缓期执行，撤销…的刑罚","en":"If someone who has been sentenced in a court is reprieved, their punishment is officially delayed or cancelled.","ex":{"en":"Fourteen people, waiting to be hanged for the murder of a former prime minister, have been reprieved.","cn":"因谋杀前首相而即将处以绞刑的14个人已获缓刑。"}},{"pos":"N-COUNT 可数名词","cn":"(不好或艰难情况的)暂缓，延缓","en":"A reprieve is a delay before a very unpleasant or difficult situation which may or may not take place.","ex":{"en":"It looked as though the college would have to shut, but this week it was given a reprieve.","cn":"这所大学看起来要关闭了，但这周情况暂时有所缓解。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to not punish someone, or give them a less severe punishment than they deserve","cn":""},{"en":"an official order stopping or delaying someone's punishment, especially when the punishment is death","cn":""},{"en":"an official order forgiving people who have done something illegal or freeing prisoners - used especially in political contexts","cn":""}]},"vocab":{"pos":"1 v n 2 v n","senses":[{"en":"A reprieve is a break in or cancellation of a painful or otherwise lousy situation. If you're being tortured, a reprieve is a break from whatever's tormenting you."}]},"collocations":{"phrases":["ADJ. temporary | last-minute He was saved from the gallows by a last-minute reprieve.","VERB + REPRIEVE earn, gain, get, win | give sb/sth, grant (sb/sth) The railway line, due for closure, has been granted a six-month reprieve.","PREP. ~ from The family have won a temporary reprieve from eviction."]},"media":{"uk":"media/ldoce/hwd/bre/c/reprieve_n0205.mp3","us":"media/ldoce/hwd/ame/e/ld44reprieve.mp3"},"examples":[{"en":"Campaigners have won a reprieve for the hospital threatened with closure.","cn":"活动家们为这家受关闭威胁的医院赢得了喘息的机会。"},{"en":"70 jobs have been reprieved until next April.","cn":"有 70 个职位暂时保留到明年四月份。"}],"oxford":{"phon":"rɪˈpriːv","pos":"verb","senses":[{"en":"to officially cancel or delay a punishment for a prisoner who is condemned to death","cn":"撤销…的死刑；缓期执行…的死刑","ex":{"en":"a reprieved murderer","cn":"被判死刑缓期执行的杀人犯"}},{"en":"to officially cancel or delay plans to close something or end something","cn":"取消关闭；暂缓终止","ex":{"en":"70 jobs have been reprieved until next April.","cn":"有 70 个职位暂时保留到明年四月份。"}},{"en":"an official order stopping a punishment, especially for a prisoner who is condemned to death","cn":"刑罚终止令；（尤指）死刑缓刑令","ex":{"en":"He was saved from the gallows by a last-minute reprieve.","cn":"最后一刻的缓刑令使他得以免受绞刑。"},"pos":"noun"},{"en":"a delay before something bad happens","cn":"延缓；缓解","ex":{"en":"Campaigners have won a reprieve for the hospital threatened with closure.","cn":"活动家们为这家受关闭威胁的医院赢得了喘息的机会。"},"pos":"noun"}]}},"rendezvous":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(常指秘密的)约会，会面，会合","en":"A rendezvous is a meeting, often a secret one, that you have arranged with someone for a particular time and place.","ex":{"en":"I had almost decided to keep my rendezvous with Tony.","cn":"我差不多已经决定如约和托尼见面了。"}},{"pos":"N-COUNT 可数名词","cn":"约会地点;见面地点","en":"A rendezvous is the place where you have arranged to meet someone, often secretly.","ex":{"en":"Their rendezvous would be the Penta Hotel at Heathrow Airport.","cn":"他们将在希思罗机场的五角饭店碰面。"}},{"pos":"V-RECIP 相互动词","cn":"与…约会;和…会面","en":"If you rendezvous with someone or if the two of you rendezvous, you meet them at a time and place that you have arranged.","ex":{"en":"The plan was to rendezvous with him on Sunday afternoon","cn":"计划在周日下午和他会面。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when people meet in order to discuss something","cn":""},{"en":"an organized event, especially one that continues for several days, at which a lot of people meet to discuss a particular subject and hear speeches about it","cn":""},{"en":"a large formal meeting of people who belong to a political party, or to an organization of people with the same interests","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Rendezvous is a very French way to say \"meeting\" or \"date.\" So go ahead and call your next dentist appointment or lunch date with friends a rendezvous ."}]},"collocations":{"phrases":["ADJ. secret","VERB + RENDEZVOUS have | arrange | keep Although it was late, there was still enough time to keep the rendezvous. | make She made the rendez","PREP. ~ with I have a rendezvous with Peter at a restaurant on the harbour.","PHRASES a place for a rendezvous 2 place where people meet","ADJ. popular The cafe is a popular rendezvous for young lovers. | secret | pre-arranged","VERB + RENDEZVOUS make your way (back) to/towards The platoon made its way to the pre-arranged rendezvous in the desert.","RENDEZVOUS + NOUN point"]},"media":{"uk":"media/ldoce/hwd/bre/c/rendezvous_v0205.mp3","us":"media/ldoce/hwd/ame/f/rendezvous1.mp3"},"examples":[{"en":"a lively Paris rendezvous","cn":"巴黎一个很热闹的公共场所"},{"en":"He made a rendezvous with her in Times Square.","cn":"他和她相约在时代广场见面。"}],"oxford":{"phon":"ˈrɒndɪvuː","pos":"noun","senses":[{"en":"an arrangement to meet somebody at a particular time and place","cn":"约会","ex":{"en":"I had a secret rendezvous with John that evening.","cn":"那天晚上我和约翰秘密会面。"}},{"en":"a place where people have arranged to meet","cn":"约会地点","ex":{"en":"He didn’t recognize the address of the rendezvous.","cn":"他不认识约会的地址。"}},{"en":"a bar, etc. that is a popular place for people to meet","cn":"（酒吧等）热门聚会场所，聚会处","ex":{"en":"a lively Paris rendezvous","cn":"巴黎一处很热闹的公共场所"}},{"en":"to meet at a time and place that have been arranged in advance","cn":"（在约定的时间和地点）会面，相会，集合","pos":"verb"}]}},"rehearse":{"collins":{"senses":[{"pos":"VERB 动词","cn":"排练，演练，预演(戏剧、舞蹈或音乐作品)","en":"When people rehearse a play, dance, or piece of music, they practise it in order to prepare for a performance.","ex":{"en":"A group of actors are rehearsing a play about Joan of Arc","cn":"一群演员正在排演一出关于圣女贞德的戏。"}},{"pos":"VERB 动词","cn":"默默练习;默述;默诵","en":"If you rehearse something that you are going to say or do, you silently practise it by imagining that you are saying or doing it.","ex":{"en":"Anticipate any tough questions and rehearse your answers","cn":"预先考虑可能遇到的各种棘手问题，并且自己练习回答。"}},{"pos":"VERB 动词","cn":"复述;详述;重复","en":"If you rehearse something, you repeat it in detail.","ex":{"en":"Yesterday's speech to the Scottish party conference rehearsed the arguments again.","cn":"昨天在苏格兰党人会议上的演讲中又一次重复了这些观点。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do an activity many times in order to improve your skill or to prepare for a test","cn":""},{"en":"to practise physical movements or activities in preparation for a race or game","cn":""},{"en":"to practise a play, speech, or music in preparation for a public performance","cn":""}]},"collocations":{"phrases":["ADV. carefully | mentally She mentally rehearsed what she would say to Jeff.","PREP. for rehearsing for the show","PHRASES well rehearsed He had all the words he needed typed out and well rehearsed."]},"media":{"uk":"media/ldoce/hwd/bre/1/rehearse0205.mp3","us":"media/ldoce/hwd/ame/8/rehearse.mp3"},"examples":[{"en":"She walked along rehearsing her excuse for being late.","cn":"她一边走一边默诵着她迟到的托辞。"},{"en":"Today, we'll just be rehearsing the final scene.","cn":"今天，我们只排演最后一幕。"}],"oxford":{"phon":"rɪˈhɜːs","pos":"verb","senses":[{"en":"to practise or make people practise a play, piece of music, etc. in preparation for a public performance","cn":"排练；排演","g":"[intransitive, transitive]","ex":{"en":"We were given only two weeks to rehearse.","cn":"只给了我们两个星期排练。"}},{"en":"to prepare in your mind or practise privately what you are going to do or say to somebody","cn":"默诵；背诵；默默地练习","g":"[transitive]","ex":{"en":"She walked along rehearsing her excuse for being late.","cn":"她一边走一边默诵着她迟到的托辞。"}},{"en":"to repeat ideas or opinions that have often been expressed before","cn":"照搬；重复","g":"[transitive]","lab":"formal, usually disapproving，，"}]}},"rehearsal":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"排练;彩排","en":"A rehearsal of a play, dance, or piece of music is a practice of it in preparation for a performance.","ex":{"en":"The band was scheduled to begin rehearsals for a concert tour","cn":"这支乐队准备开始为巡演排练。"}},{"pos":"N-COUNT 可数名词","cn":"预演;试演;演习;演练","en":"You can describe an event or object which is a preparation for a more important event or object as a rehearsal for it.","ex":{"en":"The sketch should be a kind of rehearsal for the eventual painting","cn":"草图应该是最终绘画的某种演练。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things you do regularly in order to get better at something, or an occasion when you do these things","cn":""},{"en":"time that you spend practising and doing exercise in order to get better at a sport","cn":""},{"en":"an occasion when all the people in a play, concert etc practise it in order to prepare for it to be performed for the public","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A rehearsal is a practice, especially for a performance of some kind. You're likely to be nervous about your magic show if the rehearsal goes badly."}]},"collocations":{"phrases":["ADJ. dress","VERB + REHEARSAL do, have, hold We only had one full rehearsal. | attend, go to","REHEARSAL + VERB take place | go How did the rehearsal go?","REHEARSAL + NOUN room, space, studio | time","PREP. at (a/the) ~ He apologized for his outburst at rehearsal. | during (a/the) ~ During the dress rehearsal she suddenly forgot her lines."]},"media":{"uk":"media/ldoce/hwd/bre/a/rehearsal0205.mp3","us":"media/ldoce/hwd/ame/7/rehearsal.mp3"},"examples":[{"en":"Our new production of ‘Hamlet’ is currently in rehearsal.","cn":"我们的新版《哈姆雷特》正在排练之中。"},{"en":"We listened to his lengthy rehearsal of the arguments.","cn":"我们听着他没完没了地重复他的论点。"}],"oxford":{"phon":"rɪˈhɜːsl","pos":"noun","senses":[{"en":"time that is spent practising a play or piece of music in preparation for a public performance","cn":"排演；排练","g":"[countable, uncountable]","ex":{"en":"to have a rehearsal","cn":"进行排练"}},{"en":"an experience or event that helps to prepare you for something that is going to happen in the future","cn":"预演；演习","g":"[countable, usually singular]","ex":{"en":"These training exercises are designed to be a rehearsal for the invasion.","cn":"这些训练是为了入侵而进行的演习。"}},{"en":"the act of repeating something that has been said before","cn":"复述；重复；叙述","g":"[countable, usually singular]","lab":"formal","ex":{"en":"We listened to his lengthy rehearsal of the arguments.","cn":"我们听着他没完没了地重复他的论点。"}}]}},"relish":{"collins":{"senses":[{"pos":"VERB 动词","cn":"喜爱;玩味;欣赏;品味","en":"If you relish something, you get a lot of enjoyment from it.","ex":{"en":"I relish the challenge of doing jobs that others turn down","cn":"我喜欢挑战别人拒绝做的工作。"}},{"pos":"VERB 动词","cn":"盼望;期待;享受","en":"If you relish the idea, thought, or prospect of something, you are looking forward to it very much.","ex":{"en":"Jacqueline is not relishing the prospect of another spell in prison","cn":"杰奎琳可不想再蹲一阵子监狱。"}},{"pos":"N-MASS 物质名词","cn":"开胃小菜;调味品","en":"Relish is a sauce or pickle that you eat with other food in order to give the other food more flavour."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to enjoy something that most people would not like","cn":""},{"en":"to enjoy doing something, especially something that is difficult, dangerous, or unkind","cn":""},{"en":"to very much enjoy doing something that is difficult or hurts other people","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"Relish isn't just a hotdog topping. The verb relish means to enjoy something immensely. You may relish eating the relish on your hotdog, or you may relish taking an afternoon nap."}]},"collocations":{"phrases":["ADV. positively, really | not particularly He did not particularly relish the prospect of a meeting with his boss. | rather | clearly, obvio","VERB + RELISH appear to, seem to"]},"media":{"uk":"media/ldoce/hwd/bre/4/relish_n0205.mp3","us":"media/ldoce/hwd/ame/e/relish1.mp3"},"examples":[{"en":"She savoured the moment with obvious relish.","cn":"她显然津津有味地回味着那一刻。"},{"en":"I don't relish the prospect of getting up early tomorrow.","cn":"我可不愿意明天早上早起。"}],"oxford":{"phon":"ˈrelɪʃ","pos":"verb","senses":[{"en":"to get great pleasure from something; to want very much to do or have something","cn":"享受；从…获得乐趣；渴望；喜欢","ex":{"en":"to relish a challenge","cn":"喜欢挑战"}},{"en":"great pleasure","cn":"享受；很大的乐趣","g":"[uncountable]","ex":{"en":"She savoured the moment with obvious relish.","cn":"她显然津津有味地回味着那一刻。"},"pos":"noun"},{"en":"a cold, thick, spicy sauce made from fruit and vegetables that have been boiled, that is served with meat, cheese, etc.","cn":"风味佐料（用水果和蔬菜煮后制成的冷稠酱汁）","g":"[uncountable, countable]","pos":"noun"}]}},"reich":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the German state between 1933 and 1945","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/p028-000010336.mp3","us":"media/ldoce/hwd/ame/9/p028-000010336.mp3"}},"receipt":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"收条；收据；购物小票（在美语里常用 sales slip）","en":"A receipt is a piece of paper that you get from someone as proof that they have received money or goods from you. In British English a receipt is a piece of paper that you get in a shop when you buy something, but in American English the more usual term for this is sales slip .","ex":{"en":"I wrote her a receipt for the money.","cn":"我给她写了一张收钱的收条。"}},{"pos":"N-PLURAL 复数名词","cn":"（商店或影院等一定时期的）收入，收益","en":"Receipts are the amount of money received during a particular period, for example by a shop or theatre.","ex":{"en":"The film opened to healthy box office receipts before rapidly falling off","cn":"这部影片的票房收入开始的时候持续上涨，但是后来急剧下降。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"收到；接到","en":"The receipt of something is the act of receiving it.","ex":{"en":"Goods should be supplied within 28 days after the receipt of your order.","cn":"应该在收到订单后28天内供货。"}},{"pos":"PHRASE 短语","cn":"已收到；经常收到","en":"If you are in receipt of something, you have received it or you receive it regularly.","ex":{"en":"We are taking action, having been in receipt of a letter from him","cn":"收到他的信之后我们正在采取行动。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to get a letter, phone call, or message","cn":""},{"en":"if telephone calls, messages, letters etc come in , they arrive at a place where people are waiting for them","cn":""},{"en":"if letters, calls, messages etc pour in or flood in , a very large number of them are received","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"You know that slim, white piece of paper the grocery store clerk gives you that lists everything you bought, how much you paid, and the change you received? That's a receipt ."}]},"collocations":{"phrases":["ADJ. original","VERB + RECEIPT ask (sb) for | get, obtain | receive | have Could I have a receipt for that please? | make out, write (out) a receipt made ou","RECEIPT + NOUN book","PREP. ~ for She issued a receipt for the goods. 2 act of receiving sth","VERB + RECEIPT acknowledge I would be grateful if you would acknowledge receipt of this letter.","PREP. in ~ of people in receipt of housing benefit | on/upon ~ of The goods will be sent on receipt of your cheque.","PHRASES the date for receipt The closing date for receipt of your application is July 14. | within &hellip; days of receipt Items should be ","ADJ. total Cash income is calculated by subtracting total trading income from total receipts. | net | capital | income, revenue | tax | cash"]},"media":{"uk":"media/ldoce/hwd/bre/3/receipt0205.mp3","us":"media/ldoce/hwd/ame/d/receipt.mp3"},"examples":[{"en":"Are you in receipt of any state benefits?","cn":"你目前是否享有政府补助金？"},{"en":"Can I have a receipt, please?","cn":"请给我开个收据，好吗？"}],"oxford":{"phon":"rɪˈsiːt","pos":"noun","senses":[{"en":"a piece of paper or an electronic document that shows that goods or services have been paid for","cn":"收据；收条","g":"[countable]","lab":"especially British English","ex":{"en":"Can I have a receipt, please?","cn":"请给我开个收据，好吗？"}},{"en":"the act of receiving something","cn":"接收；收到","g":"[uncountable]","lab":"formal","ex":{"en":"You will get an automatic reply to your email confirming receipt.","cn":"您将收到一封自动回复的电子邮件，确认收到。"}},{"en":"money that a business, bank or government receives","cn":"（企业、银行、政府等）收到的款项，收入","g":"[plural]","lab":"business","ex":{"en":"net/gross receipts","cn":"净收入；总收入"}}]}},"refund":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"退款;返还金额","en":"A refund is a sum of money which is returned to you, for example because you have paid too much or because you have returned goods to a shop."},{"pos":"VERB 动词","cn":"退还（钱款）","en":"If someone refunds your money, they return it to you, for example because you have paid too much or because you have returned goods to a shop.","ex":{"en":"We guarantee to refund your money if you're not delighted with your purchase","cn":"我们承诺如果您对所买物品不满意可以退款。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to give someone back money that you have borrowed from them","cn":""},{"en":"to pay a large amount of money that you owe, especially to a bank","cn":""},{"en":"to finish paying back an amount of money that you have borrowed","cn":""}]},"collocations":{"phrases":["ADV. in full Your money will be refunded in full. | promptly","PREP. to If you are not satisfied with the goods, the price will be refunded to you."]},"media":{"uk":"media/ldoce/hwd/bre/c/ld44refund.mp3","us":"media/ldoce/hwd/ame/8/l3refund.mp3"},"examples":[{"en":"If there is a delay of 12 hours or more, you will receive a full refund of the price of your trip.","cn":"如果耽搁达到或超过 12 小时，你会得到旅费全额退款。"},{"en":"We will refund your money to you in full if you are not entirely satisfied.","cn":"如果你并不感到完全满意，我们会退还全部金额。"}],"oxford":{"phon":"ˈriːfʌnd","pos":"noun","senses":[{"en":"a sum of money that is paid back to you, especially because you paid too much or because you returned goods to a shop","cn":"退款；返还款；偿还金额","lab":"especially British English","ex":{"en":"a tax refund","cn":"税金退款"}},{"en":"to give somebody their money back, especially because they have paid too much or because they are not satisfied with something they bought","cn":"退还；退（款）；偿付","ex":{"en":"Tickets cannot be exchanged or money refunded.","cn":"门票不可退换。"},"pos":"verb"}]}},"repentance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"后悔;悔改;悔意;忏悔","en":"If you show repentance for something wrong that you have done, you make it clear that you are sorry for doing it.","ex":{"en":"They showed no repentance during their trial.","cn":"在他们受审的过程中没有表现出一丝悔意。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you are sorry for something wrong that you have done","cn":"忏悔﹔懊悔﹐后悔"}]},"vocab":{"pos":"n","senses":[{"en":"Repentance is the guilt you feel when you do something wrong — and the steps you take to make up for it, like a sincere apology: repentance for hurting your friend's feelings."}]},"collocations":{"phrases":["ADJ. genuine, sincere, true | deathbed","VERB + REPENTANCE show They refused to showed repentance for their crimes.","PHRASES a sign of repentance They were released on parole for showing signs of repentance."]},"media":{"uk":"media/ldoce/hwd/bre/a/repentance0205.mp3","us":"media/ldoce/hwd/ame/c/laadrepentance.mp3"},"examples":[{"en":"He shows no sign of repentance.","cn":"他毫无悔意。"}],"oxford":{"phon":"rɪˈpentəns","pos":"noun","senses":[{"en":"the fact of showing that you are sorry for something wrong that you have done","cn":"后悔；懊悔；悔过；忏悔","ex":{"en":"He shows no sign of repentance.","cn":"他毫无悔意。"}}]}},"remnant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"剩余部分;残余部分;残迹;残存物","en":"The remnants of something are small parts of it that are left over when the main part has disappeared or been destroyed.","ex":{"en":"After twenty-four hours of fighting, the remnants of the force were fleeing","cn":"战斗持续了24个小时后，该部队残部打算溜掉。"}},{"pos":"N-COUNT 可数名词","cn":"布头;边角余料","en":"A remnant is a small piece of cloth that is left over when most of the cloth has been sold. Shops usually sell remnants cheaply."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"what is left after everything or everyone else has gone, been used, or been dealt with","cn":""},{"en":"the small amount that remains after everything else has gone, or been eaten, used, destroyed etc. What remains of is more formal than what is left of","cn":""},{"en":"the very last part of something that is left after everything else has gone","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A remnant is something that's left over, once the rest is used up. If you plan to sew a shirt using only a remnant , it might have to be a midriff shirt."}]},"collocations":{"phrases":["ADJ. small | last, surviving The museum is one of the last remnants of the 17th-century palace. | faint, tattered the tattered remnants of t","PREP. ~ from (figurative) Their outdated attitudes are a remnant from colonial days.","PHRASES a remnant from/of the past"]},"media":{"uk":"media/ldoce/hwd/bre/2/remnant0205.mp3","us":"media/ldoce/hwd/ame/5/remnant.mp3"},"examples":[{"en":"The woods are remnants of a huge forest which once covered the whole area.","cn":"这片树林只是剩下的一部分，原来这一带是一大片森林。"},{"en":"The remnants of a meal stood on the table.","cn":"吃剩的饭菜摆在桌上。"}],"oxford":{"phon":"ˈremnənt","pos":"noun","senses":[{"en":"a part of something that is left after the other parts have been used, removed, destroyed, etc.","cn":"残余部分；剩余部分","g":"[usually plural]","ex":{"en":"The woods are remnants of a huge forest which once covered the whole area.","cn":"这片树林只是剩下的一部分，原来这一带是一大片森林。"}},{"en":"a small piece of cloth that is left when the rest has been sold","cn":"（织物的）零头，零料；布头"}]}},"residence":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"住处;居所;住宅","en":"A residence is a house where people live.","ex":{"en":"...hotels and private residences.","cn":"旅馆和私人住宅"}},{"pos":"N-UNCOUNT 不可数名词","cn":"住处;居住地","en":"Your place of residence is the place where you live.","ex":{"en":"...differences among women based on age, place of residence and educational levels.","cn":"不同年龄、居住地和教育程度的女性之间的差异"}},{"pos":"N-UNCOUNT 不可数名词","cn":"居住（权）；居留（权）","en":"Someone's residence in a particular place is the fact that they live there or that they are officially allowed to live there.","ex":{"en":"They had entered the country and had applied for permanent residence","cn":"他们已经入境该国，并申请了永久居留权。"}},{"pos":"PHRASE 短语","cn":"住在;居住","en":"If someone is in residence in a particular place, they are living there.","ex":{"en":"Windsor is open to visitors when the Royal Family is not in residence.","cn":"王室未在温莎城堡居住期间，城堡会对游客开放。"}},{"pos":"PHRASE 短语","cn":"（作家、艺术家等）常驻的","en":"An artist or writer in residence is one who teaches in an institution such as a university or theatre company.","ex":{"en":"Wakoski is writer in residence at Michigan State University.","cn":"瓦科斯基是密歇根州立大学的常驻作家。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the house, apartment, or place where you live","cn":""},{"en":"a building that someone lives in, especially a building intended for one person, couple, or family","cn":""},{"en":"the house, apartment, or room where someone lives","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The house or apartment where you live is your place of residence . If you're house proud, it means you keep your residence nice and tidy."}]},"collocations":{"phrases":["ADJ. desirable | palatial | official | royal | private | main, principal Versailles was the principal residence of the kings of France until","ADJ. long | permanent | temporary | main, normal, principal","VERB + RESIDENCE establish, take up The family took up temporary residence in the manor house. | remain in, stay in The family house was sol","RESIDENCE + NOUN permit He has applied for a residence permit.","PREP. in ~ The flag flying above the palace indicates that the Queen is in residence.","PHRASES a change of residence, a hall of residence The university has two halls of residence for its postgraduate students. | a place of res"]},"media":{"uk":"media/ldoce/hwd/bre/b/residence0205.mp3","us":"media/ldoce/hwd/ame/b/residence.mp3"},"examples":[{"en":"10 Downing Street is the British Prime Minister's official residence.","cn":"唐宁街 10 号是英国首相的官邸。"},{"en":"They were not able to take up residence in their new home until the spring.","cn":"他们到第二年春天才住进了新家。"}],"oxford":{"phon":"ˈrezɪdəns","pos":"noun","senses":[{"en":"a house, especially a large or impressive one","cn":"住所；住房；（尤指）宅第，豪宅","g":"[countable]","ex":{"en":"a desirable family residence for sale (= for example, in an advertisement)","cn":"待售的理想家居"}},{"en":"the state of living in a particular place","cn":"居住；定居","g":"[uncountable]","ex":{"en":"They were not able to take up residence in their new home until the spring.","cn":"他们到第二年春天才住进了新家。"}},{"en":"permission to live in a country that is not your own","cn":"（在他国的）居住权，居留许可","g":"[uncountable]","ex":{"en":"They have been denied residence in this country.","cn":"这个国家不给他们居住资格。"}}]}},"recompense":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"酬金;酬劳;奖赏;赔偿","en":"If you are given something, usually money, in recompense, you are given it as a reward or because you have suffered.","ex":{"en":"He demands no financial recompense for his troubles","cn":"他没有对自己遭遇的麻烦要求经济赔偿。"}},{"pos":"VERB 动词","cn":"（常以金钱形式）偿付，赔偿，报答","en":"If you recompense someone for their efforts or their loss, you give them something, usually money, as a payment or reward.","ex":{"en":"The fees offered by the NHS do not recompense dental surgeons for their professional time","cn":"国民医疗保健系统所支付的费用中不涵盖牙科诊疗费用。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give someone a payment for trouble or losses that you have caused them, or a reward for their efforts to help you","cn":"补偿﹔赔偿﹔酬谢"},{"en":"something that you give to someone for trouble or losses that you have caused them, or as a reward for their help","cn":"补偿﹔赔偿﹔报酬"}]},"vocab":{"pos":"v n","senses":[{"en":"Say you a loan a few bucks to a friend who is short on cash, and he wins the lottery. Presumably, he'll be able to recompense , or pay you back what he owes."}]},"collocations":{"phrases":["ADJ. adequate, sufficient | financial","VERB + RECOMPENSE have All struggles should have their recompense. | expect | receive | give (sth in), pay (sth in) Substantial damages were","PREP. as/in ~ She received a gift as recompense. | ~ for He was given &pound; 1,000 in recompense for his loss. | ~ from recompense from the"]},"media":{"uk":"media/ldoce/hwd/bre/2/recompense_n0205.mp3","us":"media/ldoce/hwd/ame/0/recompense1.mp3"},"examples":[{"en":"I received $1 000 in recompense for loss of earnings.","cn":"我得到了 1 000 元的收入损失赔偿。"},{"en":"There was no attempt to recompense the miners for the loss of their jobs.","cn":"没有人有意向失业矿工给予补偿。"}],"oxford":{"phon":"ˈrekəmpens","pos":"noun","senses":[{"en":"something, usually money, that you are given because you have suffered in some way, or as a payment for something","cn":"赔偿；补偿；报酬","ex":{"en":"There must be adequate recompense for workers who lose their jobs.","cn":"必须给失业的工人足够的补偿。"}},{"en":"to do something for somebody or give them a payment for something that they have suffered","cn":"给…以补偿；赔偿","ex":{"en":"There was no attempt to recompense the miners for the loss of their jobs.","cn":"没有人表示要对失业矿工给予补偿。"},"pos":"verb"}]}},"regrettable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人遗憾的;可惜的;令人惋惜的","en":"You describe something as regrettable when you think that it is bad and that it should not happen or have happened.","ex":{"en":"...an investigation into what the army described as a regrettable incident","cn":"对军方称之为令人遗憾的事件的调查"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is regrettable makes you feel sorry because it has unpleasant results","cn":""},{"en":"something that is regrettable is unpleasant, and you wish things could be different","cn":"令人懊悔的﹐可惜的﹐令人遗憾的"}]},"vocab":{"pos":"adj","senses":[{"en":"Regrettable describes things that make you feel sorry. Letting your sister borrow your own snow shovel became a regrettable decision the moment the big storm started."}]},"collocations":{"phrases":["VERBS be, seem","ADV. deeply, extremely, highly, very a deeply regrettable incident It is highly regrettable that the minister cannot be here in person. | ra"]},"media":{"uk":"media/ldoce/hwd/bre/2/regrettable0205.mp3","us":"media/ldoce/hwd/ame/6/regrettable.mp3"},"examples":[{"en":"Regrettably, crime has been increasing in this area.","cn":"令人遗憾的是这一地区的犯罪率在不断上升。"},{"en":"It is regrettable that the police were not informed sooner.","cn":"遗憾的是没有早些报警。"}],"oxford":{"phon":"rɪˈɡretəbl","pos":"adjective","senses":[{"en":"that you are sorry about and wish had not happened","cn":"令人惋惜的；可惜的；令人遗憾的","ex":{"en":"It is regrettable that the police were not informed sooner.","cn":"遗憾的是没有早些报警。"}}]}},"recur":{"collins":{"senses":[{"pos":"VERB 动词","cn":"复发;重现;再次发生","en":"If something recurs, it happens more than once.","ex":{"en":"...a theme that was to recur frequently in his work.","cn":"一个在他的作品中反复出现的主题"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to happen again, once or repeatedly","cn":""},{"en":"an event or action that is the same as something that happened before","cn":""},{"en":"something that happens in exactly the same way as it happened before, usually with all the same problems","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"Have you ever had the same crazy dream night after night? If so, you know that dreams can recur , meaning they repeat, or happen again."}]},"collocations":{"phrases":["ADV. constantly, frequently, regularly This is a constantly recurring problem which we must deal with.","VERB + RECUR be likely to | tend to","PREP. throughout a theme that recurs throughout the book","PHRASES keep recurring"]},"media":{"uk":"media/ldoce/hwd/bre/6/recur0205.mp3","us":"media/ldoce/hwd/ame/2/recur.mp3"},"examples":[{"en":"a recurring illness/problem/nightmare, etc.","cn":"反复发作的疾病、反复出现的问题、一再出现的噩梦等"},{"en":"This theme recurs several times throughout the book.","cn":"这一主题在整部书里出现了好几次。"}],"oxford":{"phon":"rɪˈkɜː(r)","pos":"verb","senses":[{"en":"to happen again or a number of times","cn":"再发生；反复出现","ex":{"en":"This theme recurs several times throughout the book.","cn":"这一主题在整部书里出现了好几次。"}}]}},"repay":{"collins":{"senses":[{"pos":"VERB 动词","cn":"偿还，偿付(贷款或债务)","en":"If you repay a loan or a debt, you pay back the money that you owe to the person who you borrowed or took it from.","ex":{"en":"It will take 30 years to repay the loan","cn":"还清贷款需要30年的时间。"}},{"pos":"VERB 动词","cn":"报答，回报（恩惠等）","en":"If you repay a favour that someone did for you, you do something for them in return.","ex":{"en":"It was very kind. I don't know how I can ever repay you","cn":"真是太好了。我都不知道怎么报答你才好。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give someone back money that you have borrowed from them","cn":""},{"en":"to pay a large amount of money that you owe, especially to a bank","cn":""},{"en":"to finish paying back an amount of money that you have borrowed","cn":""}]},"collocations":{"phrases":["ADV. fully, in full The loan must be repaid in full by December 31.","VERB + REPAY be able/unable to, can/could (afford to) | use sth to The proceeds from the sale will be used to repay the loan.","PREP. to This money must be repaid to the bank. 2 bring you sth in return for your efforts","ADV. amply, more than, well The charter can be seen in the town museum, which more than repays a visit.","PREP. for I felt that I had been amply repaid for my exertions."]},"media":{"uk":"media/ldoce/hwd/bre/1/repay0205.mp3","us":"media/ldoce/hwd/ame/0/repay.mp3"},"examples":[{"en":"The advance must be repaid to the publisher if the work is not completed on time.","cn":"如果作品没有按时完成，预付款必须返还给出版商。"},{"en":"How can I ever repay you for your generosity?","cn":"你对我这样慷慨，我怎么才能报答你呢？"}],"oxford":{"phon":"rɪˈpeɪ","pos":"verb","senses":[{"en":"to pay back the money that you have borrowed from somebody","cn":"归还；偿还；清偿","ex":{"en":"to repay a debt/loan/mortgage","cn":"偿还债务／贷款／按揭贷款"}},{"en":"to give something to somebody or do something for them in return for something that they have done for you","cn":"酬报；报答","ex":{"en":"How can I ever repay you for your generosity?","cn":"你对我这样慷慨，我怎么才能报答你呢？"}},{"en":"if something repays your attention, interest, study, etc., it is worth spending time to look at it, etc.","cn":"值得","lab":"formal","ex":{"en":"The report repays careful reading.","cn":"这份报告值得仔细阅读。"}}]}},"recorder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（卡式或磁带）录音机;录像机","en":"You can refer to a cassette recorder, a tape recorder, or a video recorder as a recorder.","ex":{"en":"Rodney put the recorder on the desk top and pushed the play button.","cn":"罗德尼把录音机放在桌面上，按下了播放键。"}},{"pos":"N-VAR 可变名词","cn":"直笛；竖笛","en":"A recorder is a wooden or plastic musical instrument in the shape of a pipe. You play the recorder by blowing into the top of it and covering and uncovering the holes with your fingers."},{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"刑事法院兼职法官（英格兰和威尔士的法律体制下被任命在刑事法庭兼任法官的律师）","en":"In the legal system of England and Wales, a recorder is a lawyer who is appointed as a part-time judge in the Crown Court."},{"pos":"N-COUNT 可数名词","cn":"记录装置;记录器","en":"A recorder is a machine or instrument that keeps a record of something, for example in an experiment or on a vehicle.","ex":{"en":"Data recorders also pinpoint mechanical faults rapidly, reducing repair times.","cn":"数据记录仪还能迅速查明机械故障，减少维修次数。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of electrical equipment that records music, films etc","cn":"盒式录音机/磁带录音机/录像机等"},{"en":"a simple wooden or plastic musical instrument like a tube with holes in it, which you play by blowing into it and covering different holes with your fingers to change the notes","cn":"竖笛﹔直笛"},{"en":"a judge in a city court, in some areas of Britain and the US 〔","cn":"英﹑美某些地区市法院的〕法官"}]},"media":{"uk":"media/ldoce/hwd/bre/f/recorder0205.mp3","us":"media/ldoce/hwd/ame/0/recorder.mp3","img":["media/thumb/recorder.jpg"]},"examples":[{"en":"a tape/cassette/video/DVD recorder","cn":"磁带/盒式录音机；录像机； DVD 录像机"}],"oxford":{"phon":"rɪˈkɔːdə(r)","pos":"noun","senses":[{"en":"a machine for recording sound or pictures or both","cn":"录音机；录像机","ex":{"en":"The cockpit voice recorder indicated that the crew did not call for any checklist.","cn":"驾驶舱录音机显示机组人员没有要求提供任何检查单。"}},{"en":"a musical instrument in the shape of a pipe that you blow into, with holes that you cover with your fingers","cn":"竖笛；直笛"},{"en":"a judge in a court in some parts of the UK and the US","cn":"（英国和美国部分地区的）刑事法院法官，法官"},{"en":"a person who keeps a record of events or facts","cn":"记录员；书记员","ex":{"en":"In natural history the careful observer and recorder was very important in the advance of the science.","cn":"在自然历史中，细心的观察者和记录者对于科学的进步非常重要。"}}]}},"revulsion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"深恶痛绝;强烈反对;嫌恶","en":"Someone's revulsion at something is the strong feeling of disgust or disapproval they have towards it.","ex":{"en":"...their revulsion at the act of desecration","cn":"他们对亵渎神灵的行为的憎恶"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong, sudden feeling of shock and disgust","cn":""},{"en":"feeling shocked and angry at something you think is very wrong, cruel, unpleasant etc","cn":""},{"en":"very shocked and angry at something such as violence or suffering","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Revulsion means an intense, violent, sometimes physical, dislike of something. People feel revulsion to different things. You may feel revulsion at the thought of seeing a horror movie, but other people can't wait to be scared by the latest zombie or slasher flick."}]},"collocations":{"phrases":["ADJ. deep, utter | widespread The killing caused widespread revulsion. | instinctive","VERB + REVULSION be filled with, feel | cause | express | conceal","PREP. in/with ~ The children shrank back from him in revulsion. | ~ against public revulsion against violence in our society | ~ at He tried","PHRASES a feeling/sense of revulsion"]},"media":{"uk":"media/ldoce/hwd/bre/9/revulsion0205.mp3","us":"media/ldoce/hwd/ame/8/revulsion.mp3"},"examples":[{"en":"I started to feel a revulsion against their decadent lifestyle.","cn":"我对他们那腐朽的生活方式开始感到厌恶。"},{"en":"Most people viewed the bombings with revulsion.","cn":"大多数人对爆炸事件表现出惊恐不安。"}],"oxford":{"phon":"rɪˈvʌlʃn","pos":"noun","senses":[{"en":"a strong feeling of horror","cn":"惊恐；恐惧；憎恶","ex":{"en":"Most people viewed the bombings with revulsion.","cn":"大多数人对爆炸事件表现出惊恐不安。"}}]}},"reservoir":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"水库;蓄水池","en":"A reservoir is a lake that is used for storing water before it is supplied to people."},{"pos":"N-COUNT 可数名词","cn":"储藏;蓄积","en":"A reservoir of something is a large quantity of it that is available for use when needed.","ex":{"en":"...the huge oil reservoir beneath the Kuwaiti desert.","cn":"科威特沙漠下面巨大的石油储藏"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a lake, especially an artificial one, where water is stored before it is supplied to people’s houses","cn":"水库﹐蓄水池"},{"en":"a large amount of something that is available and has not yet been used","cn":"储藏﹐积蓄"},{"en":"a part of a machine or engine where a liquid is kept before it is used 〔","cn":"机器或引擎的〕储液器"}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"The word reservoir refers to a place where large amounts of water get stored. It can also be used to describe great amounts of other things, such as when you refer to a trivia expert as a reservoir of useless knowledge."}]},"collocations":{"phrases":["ADJ. natural | artificial, man-made | underground","PREP. in a/the ~ 2 amount of sth that can be used","ADJ. huge, vast","VERB + RESERVOIR tap (into)","PREP. ~ of tapping into the vast reservoir of information available on the Internet"]},"media":{"uk":"media/ldoce/hwd/bre/b/reservoir0205.mp3","us":"media/ldoce/hwd/ame/f/reservoir.mp3"},"examples":[{"en":"She found she had reservoirs of unexpected strength.","cn":"她发现自己潜藏着意想不到的力量。"}],"oxford":{"phon":"ˈrezəvwɑː(r)","pos":"noun","senses":[{"en":"a natural or artificial lake where water is stored before it is taken by pipes to houses, etc.","cn":"水库；蓄水池","ex":{"en":"The water content of the country's reservoirs had fallen to less than 50% of their capacity.","cn":"这个国家的水库蓄水量已降至不足其库容量的50%。"}},{"en":"a large amount of something that is available to be used","cn":"（大量的）储备，储藏","lab":"formal","ex":{"en":"We can tap into the vast reservoir of information available on the internet","cn":"我们可以开发利用因特网上丰富的信息储备。"}},{"en":"a place in an engine or a machine where a liquid is kept before it is used","cn":"储液槽","lab":"specialist","ex":{"en":"an oil reservoir","cn":"油槽"}}]}},"revise":{"collins":{"senses":[{"pos":"VERB 动词","cn":"改正，改变，修正(想法)","en":"If you revise the way you think about something, you adjust your thoughts, usually in order to make them better or more suited to how things are.","ex":{"en":"He soon came to revise his opinion of the profession.","cn":"他很快就改变了对这个职业的看法。"}},{"pos":"VERB 动词","cn":"调整，改变(价格、数目、估计等)","en":"If you revise a price, amount, or estimate, you change it to make it more fair, realistic, or accurate.","ex":{"en":"They realised that some of their prices were higher than their competitors' and revised prices accordingly","cn":"他们意识到自己有些价格高于竞争对手，就相应调整了价格。"}},{"pos":"VERB 动词","cn":"修改（音乐作品）；修订（法律）；审定，校订（文章、书籍）","en":"When you revise an article, a book, a law, or a piece of music, you change it in order to improve it, make it more modern, or make it more suitable for a particular purpose.","ex":{"en":"Three editors handled the work of revising the articles for publication","cn":"3位编辑负责文章的修订出版工作。"}},{"pos":"VERB 动词","cn":"（考前）复习，温习","en":"When you revise for an examination, you read things again and make notes in order to be prepared for the examination.","ex":{"en":"I have to revise for maths","cn":"我得复习数学。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to gain knowledge of a subject or skill, especially by being taught or trained","cn":""},{"en":"to learn about a subject by reading books, going to classes etc, especially at school or university","cn":""},{"en":"to learn the skills and get the experience that you need in order to do a particular job","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To revise means to alter or improve a preliminary draft of something, usually a text. When you want your writing to be really great, you must revise it several times until it is perfect."}]},"collocations":{"phrases":["ADV. extensively, drastically, heavily, radically, substantially The text has been quite radically revised. | completely, fully, thoroughly ","VERB + REVISE be forced to, have to The estimate for the building work had to be revised upwards. | be necessary to","PREP. from, to The figure has now been revised from &pound; 1 million to &pound; 2 million."]},"media":{"uk":"media/ldoce/hwd/bre/f/revise0205.mp3","us":"media/ldoce/hwd/ame/9/revise.mp3"},"examples":[{"en":"I can see I will have to revise my opinions of his abilities now.","cn":"我明白我现在不得不改变对他的能力的看法了。"},{"en":"The government may need to revise its policy in the light of this report.","cn":"政府可能需要根据这份报告改变其政策。"}],"oxford":{"phon":"rɪˈvaɪz","pos":"verb","senses":[{"en":"to change your opinions or plans, for example because of something you have learned","cn":"改变，修改（意见或计划）","g":"[transitive]","ex":{"en":"I can see I will have to revise my opinions of his abilities now.","cn":"我明白我现在不得不改变对他的能力的看法了。"}},{"en":"to change something, such as a book or an estimate, in order to correct or improve it","cn":"修改，修订（书刊、估算等）","g":"[transitive]","ex":{"en":"a revised edition of a textbook","cn":"课本的修订版"}},{"en":"to prepare for an exam by looking again at work that you have done","cn":"复习；温习","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"I can't come out tonight. I have to revise.","cn":"我今晚不能出去。我得复习。"}}]}},"renewal":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(活动或状态的)恢复，重新开始，复兴","en":"If there is a renewal of an activity or a situation, it starts again.","ex":{"en":"They will discuss the possible renewal of diplomatic relations","cn":"他们将讨论恢复外交关系的可能性。"}},{"pos":"N-VAR 可变名词","cn":"(执照、合同等的)续签，延期","en":"The renewal of a document such as a licence or a contract is an official increase in the period of time for which it remains valid.","ex":{"en":"His contract came up for renewal","cn":"他的合同该续签了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"恢复;更新;再生;重建","en":"Renewal of something lost, dead, or destroyed is the process of it growing again or being replaced.","ex":{"en":"...urban renewal and regeneration","cn":"城市改造和重建"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when an activity, situation, or process begins again after a period when it had stopped 〔","cn":"中止后的〕恢复，重新开始"},{"en":"when you make an agreement or official document continue for a further period of time after it ends 〔","cn":"有效期的〕延长﹔展期﹔续订﹔更新"},{"en":"when the poor areas of towns are improved by making new jobs, industries, homes etc","cn":"旧城区/市区改造"}]},"collocations":{"phrases":["ADJ. annual | cultural, economic, national, physical, religious, spiritual, urban an urban renewal programme in the city centre","VERB + RENEWAL seek He sought renewal of the grant. to seek spiritual renewal | apply for | obtain to obtain a renewal of the certificate | ","RENEWAL + NOUN programme, project | date | notice If you have any queries, please contact us on the number shown on your policy or last rene"]},"media":{"uk":"media/ldoce/hwd/bre/7/renewal0205.mp3","us":"media/ldoce/hwd/ame/d/laadrenewal.mp3"},"examples":[{"en":"The lease comes up for renewal at the end of the month.","cn":"本租约到月底需要办理展期。"},{"en":"a renewal of interest in traditional teaching methods","cn":"对传统教学法重新产生兴趣"}],"oxford":{"phon":"rɪˈnjuːəl","pos":"noun","senses":[{"en":"a situation in which something begins again after it stopped or was interrupted","cn":"恢复；更新；重新开始","ex":{"en":"a renewal of interest in traditional teaching methods","cn":"对传统教学法重新产生兴趣"}},{"en":"the act of making a contract, etc. legally acceptable for a further period of time after it has finished","cn":"（对合同等的）有效期延长，展期，续订，更新","ex":{"en":"The lease comes up for renewal at the end of the month.","cn":"本租约到月底需要办理展期。"}},{"en":"a situation in which something is replaced, improved or made more successful","cn":"更新；改进；复兴；振兴","ex":{"en":"economic renewal","cn":"经济复兴"}}]}},"researcher":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who studies a subject in detail in order to discover new facts or test new ideas","cn":"研究者；调查员"}]},"vocab":{"pos":"n","senses":[{"en":"A researcher is someone who conducts research , i.e., an organized and systematic investigation into something. Scientists are often described as researchers ."}]},"collocations":{"phrases":["ADJ. eminent, experienced, leading | chief, senior | young | early She based her work on that of earlier researchers. | independent | academ","QUANT. group, team","RESEARCHER + VERB investigate sth, work in/on sth researchers working in different disciplines researchers working on the biochemistry of le","PHRASES researchers in the field The book is written by experts who are well known as researchers in the field. • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/e/ldoce6researcher.mp3","us":"media/ldoce/hwd/ame/d/researcher_n.mp3"},"examples":[{"en":"Researchers have found links between stress and heart disease.","cn":"研究人员已经发现了压力与心脏病的联系。"},{"en":"medical researchers","cn":"医学研究人员"}],"oxford":{"phon":"rɪˈsɜːtʃə(r)","pos":"noun","senses":[{"en":"a person who studies something carefully and tries to discover new facts about it","cn":"研究者；探索者","ex":{"en":"European researchers say olive oil could help prevent cancer.","cn":"欧洲研究人员说橄榄油有助于预防癌症。"}}]}},"recess":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（委员会、法庭或政府等的）休会期间，休息期间","en":"A recess is a break between the periods of work of an official body such as a committee, a court of law, or a government.","ex":{"en":"The conference broke for a recess","cn":"会议暂时休会。"}},{"pos":"VERB 动词","cn":"休会;休庭","en":"When formal meetings or court cases recess, they stop temporarily.","ex":{"en":"The hearings have now recessed for dinner","cn":"听证会现已休会就餐。"}},{"pos":"N-COUNT 可数名词","cn":"（墙上的）凹处;壁龛","en":"In a room, a recess is part of a wall which is built further back than the rest of the wall. Recesses are often used as a place to put furniture such as shelves.","ex":{"en":"...a discreet recess next to a fireplace.","cn":"壁炉边上一个不起眼的壁龛"}},{"pos":"N-COUNT 可数名词","cn":"暗处；隐蔽处","en":"The recesses of something or somewhere are the parts of it which are hard to see because light does not reach them or they are hidden from view.","ex":{"en":"He emerged from the dark recesses of the garage","cn":"他从车库的暗处走出来。"}},{"pos":"N-COUNT 可数名词","cn":"（思想或心灵的）深处","en":"If you refer to the recesses of someone's mind or soul, you are referring to thoughts or feelings they have which are hidden or difficult to describe.","ex":{"en":"...the inner recesses of the soul","cn":"心灵最深处"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short time between school classes when children can play, eat something etc","cn":""},{"en":"a planned pause during a play, concert, or film","cn":""},{"en":"a planned pause during a play or concert, when music is often played","cn":""}]},"vocab":{"pos":"1 n v 2 n v","senses":[{"en":"Recess is a break from doing something, like work or school. Almost everyone looks forward to taking a recess — even if you don't have access to monkey bars."}]},"collocations":{"phrases":["ADJ. Christmas, summer, Whitsun | parliamentary","VERB + RECESS go into, rise for (formal) , take Parliament is taking the Christmas recess a little early this year. | return from","PREP. in ~ The decision cannot be made while the council is in recess. 2 part of a wall, set back from the rest of the wall","ADJ. deep | shallow | dark | window","PREP. in/inside to fit a blind inside a window recess 3 (usually recesses ) part furthest from the light","ADJ. dark, deep, dim He stared into the dark recesses of the room. | far, inner | hidden","VERB + RECESS lurk in (figurative) fears lurking deep in the recesses of our minds | push sth into/to (figurative) I had continually pushed ","PREP. in/within the ~ of The statue was in the inner recesses of the temple."]},"media":{"uk":"media/ldoce/hwd/bre/3/recess_n0205.mp3","us":"media/ldoce/hwd/ame/4/l3recess.mp3"},"examples":[{"en":"( figurative ) The doubt was still there, in the deep recesses of her mind.","cn":"在她的内心深处依然存有疑虑。"},{"en":"He stared into the dark recesses of the room.","cn":"他盯着房间里黑暗的角落。"}],"oxford":{"phon":"ˈriːses","pos":"noun","senses":[{"en":"a period of time during the year when the members of a parliament, committee, etc. do not meet","cn":"休会期","g":"[countable, uncountable]","ex":{"en":"Parliament went into its long summer recess.","cn":"议会进入漫长的夏季休会期。"}},{"en":"a short break in a trial in court","cn":"休庭","g":"[countable]","ex":{"en":"The judge called a short recess.","cn":"法官宣布短暂休庭。"}},{"en":"a period of time between lessons at school","cn":"课间休息","g":"[uncountable]","lab":"North American English","ex":{"en":"He wouldn't play with me at recess.","cn":"他课间休息时不愿跟我玩耍。"}},{"en":"a part of a wall that is set further back than the rest of the wall, forming a space","cn":"壁龛；壁橱；凹室","g":"[countable]","ex":{"en":"a recess for books","cn":"放书的壁橱"}},{"en":"the part of a place that is furthest from the light and hard to see or get to","cn":"隐蔽处；幽深处","g":"[countable, usually plural]","lab":"figurative","ex":{"en":"He stared into the dark recesses of the room.","cn":"他盯着房间里黑暗的角落。"}},{"en":"to take or to order a recess","cn":"休会；暂停；宣布暂停","g":"[transitive, intransitive]","lab":"North American English","ex":{"en":"The hearing was recessed for the weekend.","cn":"听证会周末暂停。"},"pos":"verb"},{"en":"to put something in a position that is set back into a wall, etc.","cn":"把…放进壁龛（或壁橱）；将…嵌入墙壁","g":"[transitive]","ex":{"en":"The lights should be recessed into the ceiling.","cn":"灯应嵌入天花板。"},"pos":"verb"}]}},"recourse":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"依靠;求援;诉诸","en":"If you achieve something without recourse to a particular course of action, you succeed without carrying out that action. To have recourse to a particular course of action means to have to do that action in order to achieve something.","ex":{"en":"It enabled its members to settle their differences without recourse to war","cn":"这样，其成员就可以不必诉诸战争来解决分歧。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you do to achieve something or deal with a situation, or the act of doing it 〔","cn":"实现或解决某事的〕手段﹐途径﹔依赖﹔求助"}]},"vocab":{"pos":"n","senses":[{"en":"Recourse is a source of help. If you're failing trigonometry in spite of studying until your brain hurts, you may have no recourse but to hire a tutor."}]},"collocations":{"phrases":["ADJ. constant, frequent | limited | no other, only I have no other recourse than to inform the police. | direct The study of these creatures","VERB + RECOURSE have The mother of an illegitimate child had no legal recourse to the father. | seek An order was made against which he soug","PREP. by ~ to people who deal with emotional pain by recourse to drugs and alcohol | without ~ to They tried to settle the dispute without r"]},"media":{"uk":"media/ldoce/hwd/bre/a/recourse0205.mp3","us":"media/ldoce/hwd/ame/3/recourse.mp3"},"examples":[{"en":"She made a complete recovery without recourse to surgery.","cn":"她未做手术就完全恢复了健康。"},{"en":"Your only recourse is legal action.","cn":"你的唯一依靠就是诉诸法律。"}],"oxford":{"phon":"rɪˈkɔːs","pos":"noun","senses":[{"en":"the fact of having to, or being able to, use something that can provide help in a difficult situation","cn":"依靠；依赖；求助","ex":{"en":"Your only recourse is legal action.","cn":"你的唯一依靠就是诉诸法律。"}}]}},"recital":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"独奏会，诗歌朗诵会，个人演唱会","en":"A recital is a performance of music or poetry, usually given by one person.","ex":{"en":"...a solo recital by the harpsichordist Maggie Cole.","cn":"大键琴演奏家玛吉·科尔的个人独奏会"}},{"pos":"N-COUNT 可数名词","cn":"（乏味的）叙说;唠叨;老生常谈","en":"If someone speaks for a long time, or says something that is boring or that has been heard many times before, you can describe it as a recital.","ex":{"en":"Before long we all grew bored with his frequent recital of the foods he couldn't eat","cn":"他总是唠叨自己不能吃的那些食物，不久我们所有人都听烦了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a performance of music or poetry, usually given by one performer","cn":"演奏会，演唱会，朗诵会〔一般由一个人表演〕"},{"en":"a spoken description of a series of events 〔","cn":"对一连串事件的〕叙述﹐口头描述"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"The hardest part about piano lessons is having to give a recital , or to demonstrate what you've learned in front of an audience."}]},"collocations":{"phrases":["ADJ. brief, short | solo | lunchtime | organ, piano, etc. | poetry, song","VERB + RECITAL give, play | attend, go to | listen to","PREP. ~ by a recital by the Grieg Trio"]},"media":{"uk":"media/ldoce/hwd/bre/7/recital0205.mp3","us":"media/ldoce/hwd/ame/d/recital.mp3"},"examples":[{"en":"to give a piano recital","cn":"举办钢琴演奏会"},{"en":"a long recital of her adventures","cn":"大谈特谈她的奇遇"}],"oxford":{"phon":"rɪˈsaɪtl","pos":"noun","senses":[{"en":"a public performance of music or poetry, usually given by one person or a small group","cn":"音乐演奏会；诗歌朗诵会","lab":"British English","ex":{"en":"to give a piano recital","cn":"举办钢琴演奏会"}},{"en":"a spoken description of a series of events, etc. that is often long and boring","cn":"（口述）逐一列举；赘述","ex":{"en":"They both launched into a recital of their misfortunes.","cn":"他们俩开始讲述自己的不幸经历。"}}]}},"remorse":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"懊悔;自责;悔恨","en":"Remorse is a strong feeling of sadness and regret about something wrong that you have done.","ex":{"en":"He was full of remorse","cn":"他充满了悔恨。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling you have when you have done something you know is wrong","cn":""},{"en":"the feeling of being guilty or embarrassed that you have after doing something that is wrong, when you feel you have lost people’s respect","cn":""},{"en":"a feeling of sadness about something, especially because you wish it had not happened","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Remorse , a noun, is what you feel if you regret your actions or wish for another outcome."}]},"collocations":{"phrases":["ADJ. deep, genuine, real","QUANT. pang, stab","VERB + REMORSE be filled with, be full of, be overcome with, be stricken with, feel, have, suffer She knew that the next day she would be gu","PREP. without ~ He died without remorse. | ~ at He felt some remorse at his behaviour. | ~ for She was filled with remorse for the crime. | ","PHRASES a feeling of remorse, tears of remorse"]},"media":{"uk":"media/ldoce/hwd/bre/f/remorse0205.mp3","us":"media/ldoce/hwd/ame/a/remorse.mp3"},"examples":[{"en":"He was filled with remorse for not believing her.","cn":"他因为没有相信她而懊悔不已。"},{"en":"I felt guilty and full of remorse.","cn":"我感到内疚，并且非常懊悔。"}],"oxford":{"phon":"rɪˈmɔːs","pos":"noun","senses":[{"en":"the feeling of being extremely sorry for something wrong or bad that you have done","cn":"懊悔；非常遗憾；自责","ex":{"en":"I felt guilty and full of remorse.","cn":"我感到内疚，并且非常懊悔。"}}]}},"remand":{"collins":{"senses":[{"pos":"VERB 动词","cn":"将…还押候审;使取保候审","en":"If a person who is accused of a crime is remanded in custody or on bail, they are told to return to the court at a later date, when their trial will take place.","ex":{"en":"Carter was remanded in custody for seven days","cn":"卡特在押候审7天。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"还押候审（期）；取保候审（期）","en":"Remand is used to refer to the process of remanding someone in custody or on bail, or to the period of time until their trial begins.","ex":{"en":"The remand hearing is often over in three minutes","cn":"取保候审听证会通常在3分钟内结束。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to send someone back from a court of law, to wait for their trial","cn":"将…还押候审"},{"en":"to send a case to be dealt with in another court","cn":"将〔案件〕发回下级法院重审"},{"en":"the period of time that someone spends in prison before their trial 〔","cn":"审前〕在押期"}]},"collocations":{"phrases":["ADJ. custodial","VERB + REMAND be held on He was held on remand, charged with causing malicious damage to property.","REMAND + NOUN centre, home | prisoner","PREP. on ~ I was in prison on remand for three weeks."]},"media":{"uk":"media/ldoce/hwd/bre/b/remand_n0205.mp3","us":"media/ldoce/hwd/ame/e/remand.mp3"},"examples":[{"en":"The two men were charged with burglary and remanded in custody (= sent to prison until their trial).","cn":"两名男子被控入室偷窃而被还押候审。"},{"en":"She was remanded on bail (= allowed to go free until the trial after leaving a sum of money with the court).","cn":"她获准取保候审。"}],"oxford":{"phon":"rɪˈmɑːnd","pos":"verb","senses":[{"en":"to send somebody away from a court to wait for their trial which will take place at a later date","cn":"将（嫌疑人）还押候审","ex":{"en":"The two men were charged with burglary and remanded in custody (= sent to prison until their trial).","cn":"两名男子被控入室偷窃而被还押候审。"}},{"en":"the process of keeping somebody in prison while they are waiting for their trial","cn":"还押；押候","ex":{"en":"He is currently being held on remand.","cn":"他正被还押候审。"},"pos":"noun"}]}},"reservation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"保留意见;疑义","en":"If you have reservations about something, you are not sure that it is entirely good or right.","ex":{"en":"I told him my main reservation about his film was the ending","cn":"我告诉他我主要是对他电影的结尾有保留意见。"}},{"pos":"N-COUNT 可数名词","cn":"预订;预约","en":"If you make a reservation, you arrange for something such as a table in a restaurant or a room in a hotel to be kept for you.","ex":{"en":"He went to the desk to make a reservation","cn":"他到服务台进行了预订。"}},{"pos":"N-COUNT 可数名词","cn":"保留地;居留地","en":"A reservation is an area of land that is kept separate for a particular group of people to live in.","ex":{"en":"Seventeen thousand Indians live in Arizona on a reservation.","cn":"1.7万印第安人生活在亚利桑那州的保留地。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an arrangement you make with a hotel, airline, restaurant etc so that they will keep a room or seat for you to use at a later time or date","cn":""},{"en":"an arrangement you make with a hotel, theatre, etc so that they will keep a room or seat for you to use at a later time or date","cn":""},{"en":"to not be sure whether you should do something or whether it is good or right","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A reservation is something set aside, like a table at a restaurant or land for Native Americans."}]},"collocations":{"phrases":["ADJ. airline, hotel","VERB + RESERVATION have Do you have a reservation? | make | confirm | cancel","RESERVATION + NOUN service | fee | form","PREP. ~ for I'd like to make a reservation for four people for Friday night, please. 2 feeling of doubt about sth","ADJ. considerable, deep, grave, major, serious, severe, strong | minor, slight | certain I have certain reservations regarding several of th","VERB + RESERVATION have | express, voice NATO generals voiced reservations about making air strikes.","RESERVATION + VERB concern sth","PREP. despite ~s Despite his initial reservations, he came to love London. | with ~s The employees are backing the reorganization plans, wit"]},"media":{"uk":"media/ldoce/hwd/bre/3/reservation0205.mp3","us":"media/ldoce/hwd/ame/5/reservation.mp3"},"examples":[{"en":"I have serious reservations about his ability to do the job.","cn":"我非常怀疑他有没有能力胜任这项工作。"},{"en":"I'll call the restaurant and make a reservation.","cn":"我要给餐厅打个电话预订座位。"}],"oxford":{"phon":"ˌrezəˈveɪʃn","pos":"noun","senses":[{"en":"an arrangement for a seat on a plane or train, a room in a hotel, etc. to be kept for you","cn":"预订；预约","g":"[countable]","lab":"especially British English","ex":{"en":"I'll call the restaurant and make a reservation.","cn":"我要给餐厅打个电话预订座位。"}},{"en":"a feeling of doubt about a plan or an idea","cn":"保留意见；疑惑","g":"[countable, uncountable]","ex":{"en":"I have serious reservations about his ability to do the job.","cn":"我非常怀疑他有没有能力胜任这项工作。"}},{"en":"an area of land in the US that is kept separate for native North Americans to live in","cn":"（美国为美洲土著居民划出的）保留地，居留地","g":"[countable]"},{"en":"(in India) the policy of keeping a fixed number of jobs or places in schools, colleges, etc. for people who are members of scheduled castes, scheduled tribes or other backward classes","cn":"预留政策（印度为表列种族、表列部族或落后种姓成员保留一定数量的工作岗位或入学名额等）","g":"[uncountable]"}]}},"reestablish":{"vocab":{"pos":"v","senses":[{"en":"Use the verb reestablish to describe what you do when you set something up again, or bring it back. You might try to reestablish your place as the best math student in class after a terrible midterm grade."}]}},"receiver":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(电话的）听筒","en":"A telephone's receiver is the part that you hold near to your ear and speak into."},{"pos":"N-COUNT 可数名词","cn":"（收音机或电视机的）信号接收器，信号接收装置","en":"A receiver is the part of a radio or television that picks up signals and converts them into sound or pictures.","ex":{"en":"Auto-tuning VHF receivers are now common in cars.","cn":"自动调节甚高频接收器现在普遍应用于汽车。"}},{"pos":"N-COUNT 可数名词","cn":"（法庭指定的）破产接管人","en":"The receiver is someone who is appointed by a court of law to manage the affairs of a business, usually when it is facing financial failure.","ex":{"en":"Between July and September, a total of 1,059 firms called in the receiver.","cn":"7月到9月间，一共有1,059家公司破产在管。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a telephone that you can carry with you, that works by using a network of radio stations to pass on signals","cn":""},{"en":"a mobile phone","cn":""},{"en":"a system that records messages so that you can listen to them on your phone","cn":""}]},"collocations":{"phrases":["ADJ. phone, telephone","VERB + RECEIVER lift, pick up She took a deep breath and lifted the receiver off its hook. | hold | put back/down, replace | snatch up | ban","RECEIVER + VERB dangle The receiver was dangling from the payphone.","PREP. over the ~ &lsquo;It's your mother on the phone again!&rsquo;, said John with his hand over the receiver.","PHRASES hold/put the receiver to your ear She picked up the receiver and put it to her ear. 2 piece of radio/television equipment","ADJ. portable | radio, satellite, television","RECEIVER + NOUN unit To change channel, select the desired number on the receiver unit. 3 person in charge of a bankrupt company","ADJ. official | administrative"]},"media":{"uk":"media/ldoce/hwd/bre/4/receiver0205.mp3","us":"media/ldoce/hwd/ame/2/receiver.mp3"},"examples":[{"en":"Molly's more of a giver than a receiver.","cn":"莫利是捐赠者而不是接收者。"},{"en":"to pick up/lift/put down/replace the receiver","cn":"拿起/放回听筒"}],"oxford":{"phon":"rɪˈsiːvə(r)","pos":"noun","senses":[{"en":"the part of a phone that you hold close to your mouth and ear","cn":"（电话）听筒，受话器","lab":"British English","ex":{"en":"to pick up/lift/put down/replace the receiver","cn":"拿起／放回听筒"}},{"en":"a piece of radio or television equipment that changes broadcast signals into sound or pictures","cn":"无线电接收机；收音机；电视机","ex":{"en":"a satellite/GPS receiver","cn":"卫星／GPS 接收机"}},{"en":"a person who is chosen by a court to be in charge of a company that is bankrupt","cn":"（破产公司的）财产管理人，官方接管人","lab":"British English also","ex":{"en":"They had to lay off 200 staff and call in the receivers.","cn":"他们不得不解雇 200 名职工，并申请破产管理人协助。"}},{"en":"a person who receives something","cn":"受方；接受者","ex":{"en":"Molly's more of a giver than a receiver.","cn":"莫莉更乐于给予而不是接受。"}},{"en":"a person who buys or accepts stolen goods, knowing that they have been stolen","cn":"购买（或接受）贼赃的人"},{"en":"a player who plays in a position in which the ball can be caught when it is being passed forward","cn":"（前传球的）接球手"}]}},"rebate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"退款；（税金、租金等的）退还部分","en":"A rebate is an amount of money which is paid to you when you have paid more tax, rent, or rates than you needed to.","ex":{"en":"...a tax rebate","cn":"退税"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to give someone back money that you have borrowed from them","cn":""},{"en":"to pay a large amount of money that you owe, especially to a bank","cn":""},{"en":"to finish paying back an amount of money that you have borrowed","cn":""}]},"vocab":{"pos":"1 n v 2 n v","senses":[{"en":"A rebate is a partial refund of the cost of an item. It acts as an incentive to help sell the product. If your new cell phone came with a rebate , you'll get a check in the mail for a certain amount of the cost."}]},"collocations":{"phrases":["ADJ. generous, substantial | maximum | rate, rent, tax She's claiming a 100% tax rebate.","VERB + REBATE be eligible for, be entitled to People on low incomes are entitled to a rebate of up to 80%. | apply for, claim | get, receive","REBATE + NOUN scheme, system","PREP. ~ on rebates on the new council tax","PHRASES a system of rebates"]},"media":{"uk":"media/ldoce/hwd/bre/c/rebate0205.mp3","us":"media/ldoce/hwd/ame/0/rebate.mp3"},"examples":[{"en":"Buyers are offered a cash rebate.","cn":"购买者享受现金回扣。"},{"en":"a tax rebate","cn":"退还税款"}],"oxford":{"phon":"ˈriːbeɪt","pos":"noun","senses":[{"en":"an amount of money that is paid back to you because you have paid too much","cn":"退还款","ex":{"en":"She's claiming a 100% tax rebate.","cn":"她正在索要百分之百的退税。"}},{"en":"an amount of money that is taken away from the cost of something, before you pay for it","cn":"折扣，返还（退还的部分货价）","ex":{"en":"Buyers are offered a cash rebate.","cn":"购买者享受现金折扣。"}}]}},"regimen":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"养生法","en":"A regimen is a set of rules about food and exercise that some people follow in order to stay healthy.","ex":{"en":"Whatever regimen has been prescribed should be rigorously followed.","cn":"不管制订的是什么样的养生计划，都要严格遵守。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special plan of food, exercise etc that is intended to improve your health","cn":"养生之道﹐摄生法"}]},"vocab":{"pos":"n","senses":[{"en":"A regimen is a systematic plan for some kind of therapy. If your doctor tells you to eat more vegetables, cut out potato chips, exercise, and take vitamins, he is prescribing a regimen for better health."}]},"collocations":{"phrases":["ADJ. strict | combined | dietary | treatment | drug | dosage/dose","VERB + REGIMEN use We used a combined regimen of injection treatment and radiation therapy.","REGIMEN + VERB comprise sth a treatment regimen comprising two antibiotics"]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41regimen.mp3","us":"media/ldoce/hwd/ame/d/regimen.mp3"},"examples":[{"en":"a regimen of morning stretching exercises","cn":"早上进行伸展锻炼的养生法"},{"en":"Patients maintain a strict dietary regimen.","cn":"病人严格遵守饮食规律。"}],"oxford":{"phon":"ˈredʒɪmən","pos":"noun","senses":[{"en":"a set of rules about food and exercise or medical treatment that you follow in order to stay healthy or to improve your health","cn":"生活规则；养生之道；养生法","ex":{"en":"a strict regimen","cn":"严格的养生法"}}]}},"retort":{"collins":{"senses":[{"pos":"VERB 动词","cn":"反驳;回嘴","en":"To retort means to reply angrily to someone.","ex":{"en":"Was he afraid, he was asked. 'Afraid of what?' he retorted","cn":"有人问他是否害怕。“害怕什么？”他反问道。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something to someone when they have asked you a question or spoken to you","cn":""},{"en":"to answer someone – used especially in written English to report what someone said","cn":""},{"en":"to answer someone","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"What's a retort ? It's a reply that's short. \"Why did the monkey fall out of the tree; please give me a report?\" I said \"The monkey's dead,\" with a dry retort ."}]},"collocations":{"phrases":["ADJ. quick, sharp | angry, caustic, furious","VERB + RETORT hurl, make He opened his mouth to make a caustic retort. | bite back, refrain from, suppress He bit back a sharp retort. | bri"]},"media":{"uk":"media/ldoce/hwd/bre/0/retort_n0205.mp3","us":"media/ldoce/hwd/ame/7/retort1.mp3","img":["media/thumb/retort.jpg"]},"examples":[{"en":"She bit back (= stopped herself from making) a sharp retort.","cn":"她克制住了自己，没有尖刻地反驳。"},{"en":"‘Don't be ridiculous!’ Pat retorted angrily. “","cn":"别荒唐了！”帕特生气地回答道。"}],"oxford":{"phon":"rɪˈtɔːt","pos":"verb","senses":[{"en":"to reply quickly to a comment, in an angry, offended or humorous way","cn":"（生气或幽默地）反驳，回嘴","ex":{"en":"‘Don't be ridiculous!’ Pat retorted angrily.","cn":"“别荒唐了！”帕特生气地回答道。"}},{"en":"a quick, angry or humorous reply","cn":"（生气或幽默的）回应，反驳","ex":{"en":"She bit back (= stopped herself from making) a sharp retort.","cn":"她克制住了自己，没有尖刻地反驳。"},"pos":"noun"},{"en":"a closed bottle with a long narrow bent spout that is used in a laboratory for heating chemicals","cn":"曲颈甑；曲颈瓶；蒸馏器","pos":"noun"}]}},"reconnaissance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（派士兵或飞机）侦察；（用卫星）搜索，勘测","en":"Reconnaissance is the activity of obtaining military information about a place by sending soldiers or planes there, or by the use of satellites.","ex":{"en":"The helicopter was returning from a reconnaissance mission","cn":"直升机完成侦察任务后正在返航。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the military activity of sending soldiers and aircraft to find out about the enemy’s forces","cn":"侦察"}]},"vocab":{"pos":"n","senses":[{"en":"Reconnaissance is checking out a situation before taking action. Often it’s used as a military term, but you could also do reconnaissance on a new employee before you hire her, or a resort before you take a vacation."}]},"collocations":{"phrases":["ADJ. general | preliminary | aerial/air, maritime, military Spotter planes made a preliminary aerial reconnaissance of the island.","VERB + RECONNAISSANCE carry out, conduct, do, make","RECONNAISSANCE + VERB reveal sth Reconnaissance revealed not a single large ship.","RECONNAISSANCE + NOUN flight, mission, sortie | party, patrol, team, unit | aircraft, plane"]},"media":{"uk":"media/ldoce/hwd/bre/d/reconnaissance0205.mp3","us":"media/ldoce/hwd/ame/5/reconnaissance.mp3"},"examples":[{"en":"Time spent on reconnaissance is seldom wasted.","cn":"花在侦察上的时间很少会白费。"},{"en":"to make an aerial reconnaissance of the island","cn":"对这座岛进行空中侦察"}],"oxford":{"phon":"rɪˈkɒnɪsns","pos":"noun","senses":[{"en":"the activity of getting information about an area for military purposes, using soldiers, planes, etc.","cn":"侦察","ex":{"en":"to make an aerial reconnaissance of the island","cn":"对这座岛进行空中侦察"}}]}},"restrained":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"克制的;冷静的;不动声色的","en":"Someone who is restrained is very calm and unemotional.","ex":{"en":"In the circumstances he felt he'd been very restrained","cn":"在那种情况下，他觉得自己一直非常冷静。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(穿着、装饰等)简单的，淡雅的，朴素的","en":"If you describe someone's clothes or the decorations in a house as restrained, you mean that you like them because they are simple and not too brightly-coloured.","ex":{"en":"Her black suit was restrained and expensive.","cn":"她的黑色套装简单而昂贵。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaviour that is restrained is calm and controlled 〔","cn":"行为〕克制的﹐有节制的"},{"en":"not too brightly coloured or decorated 〔","cn":"颜色﹑装饰〕淡雅的﹐朴素的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Use the adjective restrained to describe something that's kept under control, such as strong emotion or even physical movement. If you're angry but you don't want it to show, you might speak in a restrained manner."}]},"collocations":{"phrases":["VERBS be | become","ADV. remarkably, unusually, very I thought she was remarkably restrained in the circumstances. | fairly, quite"]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasderestrained.mp3","us":"media/ldoce/hwd/ame/8/restrained.mp3"},"examples":[{"en":"The costumes and lighting in the play were restrained.","cn":"这出戏的服装和灯光都很朴实。"},{"en":"her restrained smile","cn":"她克制的微笑"}],"oxford":{"phon":"rɪˈstreɪnd","pos":"adjective","senses":[{"en":"showing calm control rather than emotion","cn":"克制的；有节制的","ex":{"en":"her restrained smile","cn":"她克制的微笑"}},{"en":"not too brightly coloured or decorated","cn":"不艳丽的；朴素的","ex":{"en":"The costumes and lighting in the play were restrained.","cn":"这出戏的服装和灯光都很朴实。"}}]},"base":"restrain"},"reorganize":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"改组;改造;改编;重新安排","en":"To reorganize something or to reorganize means to change the way in which something is organized, arranged, or done.","ex":{"en":"It is the mother who is expected to reorganize her busy schedule","cn":"应该让母亲来重新安排自己紧张的日程。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change the way that a system or organization works","cn":""},{"en":"to completely change the way something is organized, especially a large political or economic system or a big company, in order to make it more effective","cn":""},{"en":"to change a law, system, or organization, so that it is fairer or more effective","cn":""}]},"collocations":{"phrases":["ADV. completely, totally | systematically","PREP. as The laboratory was reorganized as a separate establishment. | into Their headquarters was reorganized into five regional offices."]},"media":{"uk":"media/ldoce/hwd/bre/f/reorganize0205.mp3","us":"media/ldoce/hwd/ame/c/reorganize.mp3"},"examples":[{"en":"the reorganization of the school system","cn":"学校体制的整顿"},{"en":"Our office is being completely reorganized.","cn":"我们办公室正在彻底改组。"}],"oxford":{"phon":"riˈɔːɡənaɪz","pos":"verb","senses":[{"en":"to change the way in which something is organized or done","cn":"重新组织；改组；整顿","ex":{"en":"The laboratory was reorganized as a separate establishment.","cn":"实验室被改组为一个独立机构。"}}]}},"reversible":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可逆的;可恢复原状的","en":"If a process or an action is reversible, its effects can be reversed so that the original situation returns.","ex":{"en":"Heart disease is reversible in some cases, according to a study published last summer.","cn":"根据去年夏天公布的一项研究，心脏病在某些情况下是可以治愈的。"}},{"pos":"ADJ 形容词","cn":"可两面穿的;正反两用的","en":"Reversible clothes or materials have been made so that either side can be worn or shown as the outside.","ex":{"en":"...a reversible waistcoat.","cn":"可两面穿的背心"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a change that is reversible can be changed back to how it was before","cn":"可恢复原状的﹔可逆的"},{"en":"a piece of clothing or material that is reversible can be worn with either side showing on the outside","cn":"可两面穿的﹐正反两用的"}]},"vocab":{"pos":"adj n","senses":[{"en":"A sweater designed to be worn right-side-out and inside-out is reversible , so are the health effects of a cold. Reversible means able to be undone or able to be used inside-out."}]},"collocations":{"phrases":["VERBS be The operation is easily reversible.","ADV. easily, readily | completely, totally"]},"media":{"uk":"media/ldoce/hwd/bre/d/reversible0205.mp3","us":"media/ldoce/hwd/ame/6/laadreversible.mp3"},"examples":[{"en":"Is the trend towards privatization reversible?","cn":"私有化趋势可能逆转吗？"},{"en":"a reversible jacket","cn":"可两面穿的夹克"}],"oxford":{"phon":"rɪˈvɜːsəbl","pos":"adjective","senses":[{"en":"that can be turned inside out and worn or used with either side showing","cn":"可翻转的；可两面穿的；正反两用的","ex":{"en":"a reversible jacket","cn":"可两面穿的夹克"}},{"en":"that can be changed so that something returns to its original state or situation","cn":"可逆的；可恢复原状的；可医治的","ex":{"en":"Is the trend towards privatization reversible?","cn":"私有化趋势可能逆转吗？"}}]}},"redemption":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"赎回;偿还;拯救;救赎","en":"Redemption is the act of redeeming something or of being redeemed by something.","ex":{"en":"He craves redemption for his sins.","cn":"他渴望赎清自己的罪孽。"}},{"pos":"PHRASE 短语","cn":"无可挽救的；不可救药的","en":"If you say that someone or something is beyond redemption, you mean that they are so bad it is unlikely that anything can be done to improve them.","ex":{"en":"No man is beyond redemption","cn":"没有人是不可救药的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of being freed from the power of evil, believed by Christians to be made possible by Jesus Christ 〔","cn":"基督教指耶稣的〕救赎﹐赎罪"},{"en":"the act of exchanging a piece of paper worth a particular amount of money for money, goods, or services","cn":"兑换﹔兑现"},{"en":"too bad to be saved, repaired, or improved","cn":"不可救药的﹐无可挽回的"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Redemption is the buying back of something. You might try for redemption by attempting to buy back a bike you sold, or you might attempt to buy back your soul after you steal someone else’s bike."}]},"collocations":{"phrases":["VERB + REDEMPTION be in need of, need She believes that humanity is in need of redemption.","PREP. beyond ~ After another incident at the weekend, the club's reputation for violence is beyond redemption. | ~ from redemption from evil","ADJ. early There is a fee for early redemption. | capital, loan, share","REDEMPTION + NOUN date | price, value, yield","PREP. on ~ A charge is payable on redemption."]},"media":{"uk":"media/ldoce/hwd/bre/6/redemption0205.mp3","us":"media/ldoce/hwd/ame/8/redemption.mp3"},"examples":[{"en":"the redemption of the world from sin","cn":"将世界从罪恶中拯救出来"}],"oxford":{"phon":"rɪˈdempʃn","pos":"noun","senses":[{"en":"the act of saving or state of being saved from the power of evil; the act of redeeming","cn":"拯救；救赎","lab":"formal","ex":{"en":"the redemption of the world from sin","cn":"将世界从罪恶中拯救出来"}},{"en":"the act of exchanging shares for money (= of redeeming them)","cn":"赎回（股票等）","lab":"finance","ex":{"en":"A charge is payable on redemption.","cn":"赎回应支付费用。"}}]}},"rebuild":{"collins":{"senses":[{"pos":"VERB 动词","cn":"重建；重修","en":"When people rebuild something such as a building or a city, they build it again after it has been damaged or destroyed.","ex":{"en":"They say they will stay to rebuild their homes rather than retreat to refugee camps","cn":"他们说他们将留下重建家园而不是躲到难民营里。"}},{"pos":"VERB 动词","cn":"重建，重组，复原（机构、制度或生活的某些方面）","en":"When people rebuild something such as an institution, a system, or an aspect of their lives, they take action to bring it back to its previous condition.","ex":{"en":"Everyone would have to work hard together to rebuild the economy","cn":"所有人都应该一起努力以重建经济。"}},{"pos":"VERB 动词","cn":"复原，修复（身体某一部分）","en":"If doctors rebuild part of someone's body that has been damaged, they operate on that person to make them well again.","ex":{"en":"Two weeks later, surgeons carried out the operation to rebuild his face.","cn":"两周后，外科医生实施了手术以复原他的面部。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to build something again, after it has been damaged or destroyed","cn":"重建"},{"en":"to make something strong and successful again","cn":"使复原﹐恢复"}]},"collocations":{"phrases":["ADV. completely, entirely, totally The hall had to be completely rebuilt after the fire. | virtually | extensively, largely, substantially |","VERB + REBUILD begin to, start to beginning to rebuild her life | try to | help (to) The international community must step in to help rebuil","PHRASES newly/recently rebuilt, rebuild sth from scratch Much of the damaged vehicle had to be rebuilt from scratch."]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasderebuild.mp3","us":"media/ldoce/hwd/ame/f/rebuild.mp3"},"examples":[{"en":"When she lost her job, she had to rebuild her life completely.","cn":"她丢了工作以后，不得不彻底重新安排自己的生活。"},{"en":"He rebuilt the engine using parts from cars that had been scrapped.","cn":"他用废弃的汽车零件重新组装了发动机。"}],"oxford":{"phon":"ˌriːˈbɪld","pos":"verb","senses":[{"en":"to build or put something together again","cn":"重建；重组；重新装配","g":"[transitive, intransitive]","ex":{"en":"After the earthquake, the people set about rebuilding their homes.","cn":"地震过后，人们开始重建家园。"}},{"en":"to make something/somebody complete and strong again","cn":"使复原；使恢复","g":"[transitive]","ex":{"en":"When she lost her job, she had to rebuild her life completely.","cn":"她丢了工作以后，不得不彻底重新安排自己的生活。"}}]}},"reproach":{"collins":{"senses":[{"pos":"VERB 动词","cn":"责备;斥责;指责;责怪","en":"If you reproach someone, you say or show that you are disappointed, upset, or angry because they have done something wrong.","ex":{"en":"She is quick to reproach anyone who doesn't live up to her own high standards","cn":"只要有人不符合她自己的高标准，她马上就会加以指责。"}},{"pos":"N-VAR 可变名词","cn":"责备;斥责;指责;责怪","en":"If you look at or speak to someone with reproach, you show or say that you are disappointed, upset, or angry because they have done something wrong.","ex":{"en":"He looked at her with reproach","cn":"他用责备的目光看着她。"}},{"pos":"VERB 动词","cn":"自责","en":"If you reproach yourself, you think with regret about something you have done wrong.","ex":{"en":"You've no reason to reproach yourself, no reason to feel shame","cn":"你没有理由自责，也没有理由感到惭愧。"}},{"pos":"N-SING 单数名词","cn":"（某群体的）耻辱","en":"If you consider someone's actions or behaviour to be a reproach to a group of people, you consider them to be harmful or insulting to that group.","ex":{"en":"The shootings and bombings were 'a scandal and reproach to all of us in Europe'.","cn":"这些枪杀和轰炸事件是“我们所有欧洲人的丑闻和耻辱”。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"morally correct","cn":""},{"en":"morally correct, especially according to a set of ideas about how people should behave in a particular profession","cn":""},{"en":"fair, honest, or kind","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"Reproach means to mildly criticize. If you show poor manners at your grandmother's dinner table, she will reproach you."}]},"collocations":{"phrases":["ADJ. bitter | mild There was mild reproach in his tone.","PREP. beyond/above ~ Her conduct had always been beyond reproach. | with ~ He glanced at her with reproach. | ~ about There was no reproach ","PHRASES full of reproach Her voice was full of reproach. | a look of reproach He gave Helen a look of bitter reproach. | a word of reproach "]},"media":{"uk":"media/ldoce/hwd/bre/0/reproach_v0205.mp3","us":"media/ldoce/hwd/ame/0/reproach1.mp3"},"examples":[{"en":"She was reproached by colleagues for leaking the story to the press.","cn":"她因为将这件事透露给新闻媒体而受到同事的指责。"},{"en":"Such living conditions are a reproach to our society.","cn":"这样的生活条件是我们这个社会的耻辱。"}],"oxford":{"phon":"rɪˈprəʊtʃ","pos":"noun","senses":[{"en":"blame or criticism for something you have done","cn":"责备；批评","g":"[uncountable]","ex":{"en":"His voice was full of reproach.","cn":"他的话完全是一种责备的语气。"}},{"en":"a word or remark expressing blame or criticism","cn":"责备的话语；批评的言辞","g":"[countable]","ex":{"en":"He listened to his wife's bitter reproaches.","cn":"他听着妻子严厉的责备。"}},{"en":"a state of shame or loss of honour","cn":"羞耻；没面子；丢脸","g":"[uncountable]","ex":{"en":"Her actions brought reproach upon herself.","cn":"她的举动使她很丢面子。"}},{"en":"a person or thing that brings shame on somebody/something","cn":"（给…）带来羞辱的人（或事）；（使…）丢脸的人（或事）","g":"[singular]","ex":{"en":"Such living conditions are a reproach to our society.","cn":"这样的生活条件是我们这个社会的耻辱。"}},{"en":"to blame or criticize somebody for something that they have done or not done, because you are disappointed in them","cn":"责备；指责；批评","ex":{"en":"Nobody has a right to reproach me.","cn":"没有人有权利责备我。"},"pos":"verb"},{"en":"to feel guilty about something that you think you should have done in a different way","cn":"自责；（为…）感到内疚","ex":{"en":"She had no reason to reproach herself.","cn":"她没有理由责备自己。"},"pos":"verb"}]}},"reactor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同nuclear reactor","en":"A reactor is the same as a nuclear reactor ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a nuclear reactor","cn":"核反应堆"}]},"vocab":{"pos":"n","senses":[{"en":"A reactor is where a nuclear reaction is controlled, making it possible to create energy or any number of artificial elements."}]},"collocations":{"phrases":["ADJ. nuclear | fast, fast-breeder, fission, fusion, gas-cooled, pressurized-water, thermal","VERB + REACTOR build | operate, run | close (down), decommission, shut down","REACTOR + VERB operate, run","REACTOR + NOUN building, site | fuel | core | accident, safety, shut-down"]},"media":{"uk":"media/ldoce/hwd/bre/a/reactor0205.mp3","us":"media/ldoce/hwd/ame/f/reactor.mp3"},"oxford":{"phon":"riˈæktə(r)","pos":"noun","senses":[{"en":"a large structure used to produce nuclear energy","cn":"核反应堆","ex":{"en":"plans to build a new reactor at the nuclear power plant","cn":"计划在核电站建造一座新反应堆"}}]}},"revolver":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"左轮手枪","en":"A revolver is a kind of hand gun. Its bullets are kept in a revolving cylinder in the gun."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of small gun. The bullets are in a case which turns around as you fire the gun, so that when you fire one bullet the next bullet is ready to be fired.","cn":"左轮手枪"}]},"collocations":{"phrases":["ADJ. army, service","VERB + REVOLVER load | draw | aim | fire | shoot sb with | be armed with, carry"]},"media":{"uk":"media/ldoce/hwd/bre/2/revolver0205.mp3","us":"media/ldoce/hwd/ame/1/revolver.mp3"},"oxford":{"phon":"rɪˈvɒlvə(r)","pos":"noun","senses":[{"en":"a small gun that has a container for bullets that turns around so that shots can be fired quickly without having to stop to put more bullets in","cn":"左轮手枪","ex":{"en":"The man stood over him, aiming the revolver at his head.","cn":"那个男人站在他上方，用左轮手枪指着他的头。"}}]}},"repent":{"collins":{"senses":[{"pos":"VERB 动词","cn":"后悔;忏悔;悔悟","en":"If you repent, you show or say that you are sorry for something wrong you have done.","ex":{"en":"Those who refuse to repent, he said, will be punished","cn":"那些拒不悔改的人，他说，将会受到惩罚。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be sorry for something and wish you had not done it – used especially when considering your actions in a religious way","cn":"忏悔，懊悔﹐后悔〔尤用于从宗教角度看待自己的行为时〕"}]},"vocab":{"pos":"v","senses":[{"en":"The verb repent means \"to feel sorry for something you've done.\" When you repent , you acknowledge what you did and vow to change your ways."}]},"collocations":{"phrases":["ADV. bitterly She bitterly repented what she had done.","VERB + REPENT come to He came to repent his hasty decision.","PREP. of She has repented of her sins."]},"media":{"uk":"media/ldoce/hwd/bre/1/repent0205.mp3","us":"media/ldoce/hwd/ame/e/repent.mp3"},"examples":[{"en":"She had repented of what she had done.","cn":"她对自己所做的事深感懊悔。"},{"en":"He came to repent his hasty decision (= wished he had not taken it).","cn":"他开始后悔自己的草率决定。"}],"oxford":{"phon":"rɪˈpent","pos":"verb","senses":[{"en":"to feel and show that you are sorry for something bad or wrong that you have done","cn":"后悔；悔过；忏悔","ex":{"en":"God welcomes the sinner who repents.","cn":"上帝欢迎悔过的罪人。"}}]}},"replacement":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"替代;替换;取代","en":"If you refer to the replacement of one thing by another, you mean that the second thing takes the place of the first.","ex":{"en":"...the replacement of damaged or lost books.","cn":"受损或丢失图书的更换或补充"}},{"pos":"N-COUNT 可数名词","cn":"替补(成员或队员)；接替者","en":"Someone who takes someone else's place in an organization, government, or team can be referred to as their replacement .","ex":{"en":"Taylor has nominated Adams as his replacement","cn":"泰勒提名亚当斯接替他。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who replaces another person in a job or in a team, especially permanently","cn":""},{"en":"the next person to have a permanent job or position after someone else has left it","cn":""},{"en":"someone who temporarily takes another person's place in a job or performance when they are unable to do it themselves, especially when this happens unexpectedly","cn":""}]},"collocations":{"phrases":["ADJ. complete, full Complete replacement of the roof tiles would be very costly. | partial | direct The series III gearbox is a direct repla","VERB + REPLACEMENT be in need of, need, require The original furnishings are now in need of replacement.","REPLACEMENT + NOUN programme | cost, value Rare instruments are usually insured for their full replacement value. | equipment","PHRASES hormone replacement therapy 2 sb/sth that replaces sb/sth else","ADJ. permanent | temporary | immediate | likely He is the most likely replacement for the captain. | possible | ideal | adequate | appropria","VERB + REPLACEMENT appoint, bring in (sb/sth as), hire We'll have to see how bad the injury is before deciding whether to bring in a replace","REPLACEMENT + NOUN teacher | part, unit Do you know where I can get the replacement part? | car, vehicle","PREP. as ~ Trams are now often preferred as replacements for buses. | ~ by the president's temporary replacement by the Chief of Staff | ~ f"]},"media":{"uk":"media/ldoce/hwd/bre/c/replacement0205.mp3","us":"media/ldoce/hwd/ame/8/replacement.mp3"},"examples":[{"en":"We need to find a replacement for Sue.","cn":"我们需要找一个替代苏的人。"},{"en":"the replacement of worn car parts","cn":"汽车上旧零件的更换"}],"oxford":{"phon":"rɪˈpleɪsmənt","pos":"noun","senses":[{"en":"the act of replacing one thing with another, especially something that is newer or better","cn":"替换；更换","g":"[uncountable]","ex":{"en":"the replacement of worn car parts","cn":"汽车上损坏零件的更换"}},{"en":"a thing that replaces something, especially because the first thing is old, broken, etc.","cn":"替代品；替换物","g":"[countable]","ex":{"en":"She had a hip replacement six years ago.","cn":"她 6 年前做了髋关节置换手术。"}},{"en":"a person who replaces another person in an organization, especially in their job","cn":"（尤指工作中的）接替者，替代者","g":"[countable]","ex":{"en":"We need to find a replacement for Sue.","cn":"我们需要找一个替代休的人。"}}]}},"reassure":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使安心;使得到保证;打消…的疑虑","en":"If you reassure someone, you say or do things to make them stop worrying about something.","ex":{"en":"I tried to reassure her, 'Don't worry about it. We won't let it happen again.'","cn":"我试图使她安心，“不要担心。我们不会让它再次发生了。”"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to comfort someone, for example by telling them there is nothing to worry about or putting your arms around them","cn":""},{"en":"to say something to someone or give them something that makes them feel less upset, sad, worried etc","cn":""},{"en":"to make someone feel happier when they are disappointed or sad about something","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When we reassure other people, we pat them on the head, give them a hug, or say soothing words to convince them that everything is going to be OK."}]},"collocations":{"phrases":["ADV. constantly He was constantly reassuring himself that he had acted for the best. | quickly","VERB + REASSURE be able to, can | seek to, try to | hasten to | do little to, do nothing to | do much to The report will do much to reassure","PREP. about trying to reassure the public about the safety of public transport | of She needed to be reassured of his love for her. | with H","PHRASES feel reassured Kate nodded, but she didn't feel reassured. | need reassuring Often parents simply need reassuring that their childre"]},"media":{"uk":"media/ldoce/hwd/bre/5/reassure0205.mp3","us":"media/ldoce/hwd/ame/d/reassure.mp3"},"examples":[{"en":"They tried to reassure her, but she still felt anxious.","cn":"他们设法让她放心，可她还是焦虑不安。"},{"en":"The doctor reassured him that there was nothing seriously wrong.","cn":"医生安慰他说，没什么严重的病。"}],"oxford":{"phon":"ˌriːəˈʃʊə(r)","pos":"verb","senses":[{"en":"to say or do something that makes somebody less frightened or worried","cn":"使…安心；打消…的疑虑","ex":{"en":"They tried to reassure her, but she still felt anxious.","cn":"他们设法让她放心，可她还是焦虑不安。"}}]}},"renew":{"collins":{"senses":[{"pos":"VERB 动词","cn":"重新开始;更新","en":"If you renew an activity, you begin it again.","ex":{"en":"He renewed his attack on government policy towards Europe","cn":"他重新开始对政府的欧洲政策进行抨击。"}},{"pos":"V-RECIP 相互动词","cn":"恢复，重新建立(关系)","en":"If you renew a relationship with someone, you start it again after you have not seen them or have not been friendly with them for some time.","ex":{"en":"When the two men met again after the war they renewed their friendship","cn":"两个人在战争结束后再次见面时重归于好。"}},{"pos":"VERB 动词","cn":"延长(执照、合同等)的有效期;使续签","en":"When you renew something such as a licence or a contract, you extend the period of time for which it is valid.","ex":{"en":"Larry's landlord threatened not to renew his lease","cn":"拉里的房东威胁说不跟他续租。"}},{"pos":"VERB 动词","cn":"使（受到损毁或丢失后)重获新生","en":"You can say that something is renewed when it grows again or is replaced after it has been destroyed or lost.","ex":{"en":"Cells are being constantly renewed.","cn":"细胞不断再生。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you continue doing something, or it continues, it starts again after stopping","cn":""},{"en":"to start again , continuing the same thing that you were doing before you stopped, or continuing to happen in the same way as before","cn":""},{"en":"to continue doing something after stopping for a short time","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you make something like new, you renew it. When you catch up with an old friend you haven't seen in a long time, you renew your friendship."}]},"collocations":{"phrases":["ADV. completely | annually Membership must be renewed annually. | periodically, regularly | constantly, continually, repeatedly | automatica","VERB + RENEW decide to | agree to | refuse to","PHRASES a chance/an opportunity to renew sth a chance to renew acquaintance with old friends | need renewing The paintwork will need renewin"]},"media":{"uk":"media/ldoce/hwd/bre/0/renew0205.mp3","us":"media/ldoce/hwd/ame/0/renew.mp3"},"examples":[{"en":"The project is to go ahead following renewed promises of aid from the UN.","cn":"在得到联合国重申提供帮助的承诺以后，这个项目将着手进行。"},{"en":"to renew a licence/lease/subscription/contract, etc.","cn":"延长执照的期限、续签租约、续订、续签合约等"}],"oxford":{"phon":"rɪˈnjuː","pos":"verb","senses":[{"en":"to begin something again after it stopped or was interrupted","cn":"重新开始；中止后继续","ex":{"en":"The army renewed its assault on the capital.","cn":"军队重新发动对首都的攻击。"}},{"en":"to make something legally acceptable for a further period of time","cn":"使继续有效；延长…的期限","ex":{"en":"to renew a licence/lease/subscription/contract","cn":"延长执照的期限；续签租约；续订；续签合同"}},{"en":"to emphasize something by saying or stating it again","cn":"重申；重复强调","ex":{"en":"to renew an appeal/a request/a complaint","cn":"再次呼吁／请求／投诉"}},{"en":"to change something that is old or damaged and replace it with something new of the same kind","cn":"更新；更换","ex":{"en":"The wiring in your house should be renewed every ten to fifteen years.","cn":"家里的电线应该每十到十五年更换一次。"}}]}},"rebel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"叛军；反叛者；叛乱者","en":"Rebels are people who are fighting against their own country's army in order to change the political system there.","ex":{"en":"...fighting between rebels and government forces.","cn":"叛军和政府军之间的战争"}},{"pos":"N-COUNT 可数名词","cn":"（政党内部的）持不同政见者，反对派","en":"Politicians who oppose some of their own party's policies can be referred to as rebels.","ex":{"en":"The rebels want another 1% cut in interest rates.","cn":"反对派希望利率再降一个百分点。"}},{"pos":"VERB 动词","cn":"（政见不同者）反抗，反对","en":"If politicians rebel against one of their own party's policies, they show that they oppose it.","ex":{"en":"More than forty Conservative MPs rebelled against the government and voted against the bill.","cn":"40多个保守党议员反对政府的主张，对法案投了反对票。"}},{"pos":"N-COUNT 可数名词","cn":"叛逆者;不循规蹈矩的人","en":"You can say that someone is a rebel if you think that they behave differently from other people and have rejected the values of society or of their parents.","ex":{"en":"She had been a rebel at school.","cn":"她在学校时就是个叛逆者。"}},{"pos":"VERB 动词","cn":"表现叛逆；不守规矩","en":"When someone rebels, they start to behave differently from other people and reject the values of society or of their parents.","ex":{"en":"The child who rebels is unlikely to be overlooked","cn":"叛逆的孩子不太容易被忽视。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone, especially a child, who is disobedient does not do what he or she is told to do by a parent, teacher etc","cn":""},{"en":"not obeying people in authority and showing that you have no respect for them","cn":""},{"en":"someone, especially a young person, who is rebellious deliberately disobeys people in authority such as their parents or teachers","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"When you rebel against your parents by dying your hair green and staying out without calling, you are acting in a way that questions both their authority and their rules about what is right and acceptable."}]},"collocations":{"phrases":["ADJ. anti-government | left-wing, right-wing | US-backed, etc. | former | armed","QUANT. band, group","VERB + REBEL back, help, support They sent in troops to back the rebels. | repel | defeat | join | lead","REBEL + VERB be based &hellip; The rebels were based in camps along the border. | advance | attack sth | capture sth, gain/regain/seize/take","REBEL + NOUN faction, group, movement | army, fighters, force/forces, soldiers, troops, officers | commander, leader | control The southern ","PREP. against the ~ military operations against the rebels | ~ against a group of rebels against the emperor","PHRASES a bit/something of a rebel (figurative) He's a bit of a rebel (= he doesn't like to obey rules) ."]},"media":{"uk":"media/ldoce/hwd/bre/8/rebel_n0205.mp3","us":"media/ldoce/hwd/ame/5/l3rebel.mp3"},"examples":[{"en":"He later rebelled against his strict religious upbringing.","cn":"他后来背叛了他所受的严格的宗教教育。"},{"en":"Most teenagers find something to rebel against.","cn":"大多数青少年都有反抗意识。"}],"oxford":{"phon":"ˈrebl","pos":"noun","senses":[{"en":"a person who fights against the government of their country","cn":"反政府的人；叛乱者；造反者","ex":{"en":"rebel forces","cn":"叛乱武装"}},{"en":"a person who opposes somebody in authority over them within an organization, a political party, etc.","cn":"反抗权威者","ex":{"en":"A number of Tory rebels are planning to vote against the government.","cn":"一些保守党人倒戈，计划投票反对政府。"}},{"en":"a person who does not like to obey rules or who does not follow generally accepted standards of behaviour, dress, etc.","cn":"叛逆者；不守规矩者","ex":{"en":"I've always been the rebel of the family.","cn":"我在家里向来是个叛逆者。"}},{"en":"to fight against or refuse to obey an authority, for example a government, a system, your parents, etc.","cn":"造反；反抗；背叛","ex":{"en":"He later rebelled against his strict religious upbringing.","cn":"他后来背叛了他所受的严格的宗教教育。"},"pos":"verb"}]}},"reactionary":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"反动的;保守的","en":"A reactionary person or group tries to prevent changes in the political or social system of their country.","ex":{"en":"It grew ever more clear to everyone that the Minister was too reactionary, too blinkered","cn":"大家都越来越清楚部长太保守、心胸太狭窄。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who has fixed ideas has opinions and attitudes that never change, and often seem unreasonable","cn":""},{"en":"strongly opposed to change, especially social or political change, in a way that you think is unreasonable","cn":""},{"en":"entrenched attitudes are ones that people have had for a long time and are very difficult to change","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Reactionary describes people on the far right politically. Reactionaries occupy a political space past conservative , near where ultra-conservative bumps shoulders with fascist ."}]},"collocations":{"phrases":["VERBS be, seem","ADV. extremely, highly, very | politically"]},"media":{"uk":"media/ldoce/hwd/bre/1/reactionary_ad0205.mp3","us":"media/ldoce/hwd/ame/d/reactionary.mp3"},"examples":[{"en":"a reactionary government","cn":"反动的政府"},{"en":"reactionary attitudes","cn":"反动的态度"}],"oxford":{"phon":"riˈækʃənri","pos":"adjective","senses":[{"en":"opposed to political or social change","cn":"反动分子；反对政治（或社会）变革者","ex":{"en":"a reactionary government","cn":"反动政府"}},{"en":"a person who is opposed to political or social change","cn":"反动分子；反对政治（或社会）变革者","pos":"noun"}]}},"recipient":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"接受者；领受人","en":"The recipient of something is the person who receives it.","ex":{"en":"...the largest recipient of American foreign aid","cn":"美国对外援助的最大受惠者"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who receives something","cn":"接受者﹐领受者"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A recipient is the person on the receiving end of something. Meryl Streep is the recipient of more Academy Award nominations than any other actor."}]},"collocations":{"phrases":["ADJ. largest | main, major | intended She was not the intended recipient of the reward. | ultimate the ultimate recipient of the money | sui"]},"media":{"uk":"media/ldoce/hwd/bre/4/recipient0205.mp3","us":"media/ldoce/hwd/ame/7/recipient.mp3"},"examples":[{"en":"recipients of awards","cn":"领奖者"},{"en":"the recipient of the Nobel Peace Prize","cn":"诺贝尔和平奖得主"}],"oxford":{"phon":"rɪˈsɪpiənt","pos":"noun","senses":[{"en":"a person who receives something","cn":"受方；接受者","ex":{"en":"recipients of awards","cn":"领奖者"}}]}},"responsive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"反应敏捷的;易流露感情的;易受影响的","en":"A responsive person is quick to react to people or events and to show emotions such as pleasure and affection.","ex":{"en":"Harriet was an easy, responsive little girl","cn":"哈丽雅特是一个随和机灵的小女孩。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"反应迅速的;积极响应的","en":"If someone or something is responsive, they react quickly and favourably.","ex":{"en":"With an election coming soon, your MP should be very responsive to your request.","cn":"选举在即，你的下院议员应当对你的要求作出积极的回应。"}},{"pos":"ADJ 形容词","cn":"回应的;应答的;回答的","en":"A responsive action is made as a reaction to something that has just been said or done.","ex":{"en":"At hearing his name spoken, the dog gave a responsive wag of his tail.","cn":"听到有人喊它的名字，这条狗摆了摆尾巴。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"reacting quickly, in a positive way","cn":"反应快的﹔灵敏的﹔积极的"},{"en":"eager to communicate with people, and to react to them in a positive way","cn":"积极回应的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"People who are responsive are alert and aware — they've giving responses. The least responsive people in the world are people in deep comas."}]},"collocations":{"phrases":["VERBS be, seem | become | remain","ADV. extremely, highly, very The company is highly responsive to changes in demand. | fully | fairly, quite | directly, immediately | sexual","PREP. to She's fairly responsive to new ideas."]},"media":{"uk":"media/ldoce/hwd/bre/8/responsive0205.mp3","us":"media/ldoce/hwd/ame/1/responsive.mp3"},"examples":[{"en":"Firms have to be responsive to consumer demand.","cn":"公司必须对顾客的需求作出积极反应。"},{"en":"The club is responsive to new ideas.","cn":"俱乐部对新的想法都表示欢迎。"}],"oxford":{"phon":"rɪˈspɒnsɪv","pos":"adjective","senses":[{"en":"reacting quickly and in a positive way","cn":"反应敏捷；反应积极","g":"[not usually before noun]","ex":{"en":"Firms have to be responsive to consumer demand.","cn":"公司必须对顾客的需求作出积极反应。"}},{"en":"reacting with interest or enthusiasm","cn":"反应热烈的；热情的","ex":{"en":"The club is responsive to new ideas.","cn":"俱乐部对新的想法都表示欢迎。"}},{"en":"used to describe a website, etc. that changes to suit the kind of device you are using, for example by changing the size of the text or the way that items are arranged on the screen","cn":"（网站等）响应式设计的，自适应的（可根据使用者的装置以适当的样式呈现内容）","lab":"computing"}]}},"readiness":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"愿意；乐意","en":"If someone is very willing to do something, you can talk about their readiness to do it.","ex":{"en":"...their readiness to co-operate with the new US envoy.","cn":"他们乐意和新任美国特使合作"}},{"pos":"N-UNCOUNT 不可数名词","cn":"准备就绪;以备","en":"If you do something in readiness for a future event, you do it so that you are prepared for that event.","ex":{"en":"Security tightened in the capital in readiness for the president's arrival.","cn":"首都加强了警备，准备迎接总统的到来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if something is ready , you can use it or eat it immediately","cn":""},{"en":"if equipment, a system, a rule, or a plan is in place , it is ready to start being used","cn":""},{"en":"ripe fruit is soft, sweet, and ready to eat","cn":""}]},"collocations":{"phrases":["ADJ. greater | constant | combat The troops were in a state of combat readiness.","VERB + READINESS declare, express, indicate, show, signal Hungary has indicated its readiness to sign the treaty. | hold sb/sth in He held h","PREP. in ~ (for) service the car in readiness for the journey | ~ for to express a readiness for change","PHRASES a state of readiness"]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdereadiness.mp3","us":"media/ldoce/hwd/ame/6/readiness.mp3"},"examples":[{"en":"Everyone has doubts about their readiness for parenthood.","cn":"对于自己是否准备好了为人父母，人人都会感到疑虑。"},{"en":"Over half the people interviewed expressed their readiness to die for their country.","cn":"半数以上接受采访的人都表示愿意为国献身。"}],"oxford":{"phon":"ˈredinəs","pos":"noun","senses":[{"en":"the state of being ready or prepared for something","cn":"准备就绪","g":"[uncountable]","ex":{"en":"Everyone has doubts about their readiness for parenthood.","cn":"对于自己是否准备好了为人父母，人人都会感到疑虑。"}},{"en":"the state of being willing to do something","cn":"愿意；乐意","g":"[uncountable, singular]","ex":{"en":"Over half the people interviewed expressed their readiness to die for their country.","cn":"半数以上受访者表示愿意为国献身。"}}]}},"repellent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"讨厌的;令人厌恶的;令人排斥的","en":"If you think that something is horrible and disgusting you can say that it is repellent .","ex":{"en":"...a very large, very repellent toad","cn":"个头很大、令人生厌的癞蛤蟆"}},{"pos":"N-MASS 物质名词","cn":"驱虫剂","en":"Insect repellent is a product containing chemicals that you spray into the air or on your body in order to keep insects away.","ex":{"en":"...mosquito repellent.","cn":"驱蚊剂"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very unpleasant","cn":"令人不快的﹐讨厌的"},{"en":"→ repulsive : She found him physically repellent.","cn":"她觉得他的长相很讨厌。 repellent to The sight of blood is repellent to some people. 有些人看到血会不舒服。"},{"en":"a substance that keeps insects away","cn":"驱虫剂"}]},"vocab":{"pos":"1 adj n 2 adj","senses":[{"en":"How can you tell that something is repellent ? You dislike it so much, you want nothing to do with it. If something is repellent , it is highly offensive or disgusting."}]},"collocations":{"phrases":["VERBS be | find sb/sth","ADV. utterly | slightly, vaguely | mutually mutually repellent substances such as oil and water","PREP. to His arrogance was utterly repellent to her."]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasderepellent.mp3","us":"media/ldoce/hwd/ame/b/repellent1.mp3"},"examples":[{"en":"Their political ideas are repellent to most people.","cn":"他们的政治观点令大多数人反感。"},{"en":"water-repellent cloth","cn":"防水布"}],"oxford":{"phon":"rɪˈpelənt","pos":"adjective","senses":[{"en":"very unpleasant; causing strong dislike","cn":"使人反感的；令人厌恶的","lab":"formal","ex":{"en":"I found the pictures repellent.","cn":"我发现这些照片令人厌恶。"}},{"en":"not letting a particular substance, especially water, pass through it","cn":"防…的；隔绝…的","ex":{"en":"water-repellent cloth","cn":"防水布"}},{"en":"a substance that is used for keeping insects away from you","cn":"驱虫剂","ex":{"en":"(an) insect repellent","cn":"驱虫剂"},"pos":"noun"},{"en":"a substance that is used on cloth, stone, etc. to prevent water from passing through it","cn":"防水剂","ex":{"en":"(a) water repellent","cn":"防水剂"},"pos":"noun"}]}},"referendum":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"公民投票；全民公决","en":"If a country holds a referendum on a particular policy, they ask the people to vote on the policy and show whether or not they agree with it.","ex":{"en":"Estonia said it too planned to hold a referendum on independence.","cn":"爱沙尼亚称其也计划就独立问题进行全民公决。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when people choose a government or leader by voting","cn":""},{"en":"an occasion when the members of an organization vote by marking what they want on a piece of paper, especially to make sure that it is secret","cn":""},{"en":"an occasion when everyone in a country votes on an important political subject","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A referendum is an official vote on a specific issue. It's often part of a larger election."}]},"collocations":{"phrases":["ADJ. planned, proposed | popular | national, nationwide | constitutional, independence","VERB + REFERENDUM conduct, hold The referendum will be held on July 14th. | put sth to The proposals were put to a referendum. | call The pr","REFERENDUM + VERB show sth A popular referendum showed that the majority of people want reform.","REFERENDUM + NOUN proposal The Democrats rejected the referendum proposal. | campaign | result","PREP. in a/the ~ The issue will be decided in a national referendum. | ~ on a referendum on a new constitution","PHRASES declare a referendum fair/illegal UN monitors declared the referendum fair. | the result/results of a referendum"]},"media":{"uk":"media/ldoce/hwd/bre/4/referendum0205.mp3","us":"media/ldoce/hwd/ame/b/referendum.mp3"},"examples":[{"en":"Switzerland decided to hold a referendum on joining the EU.","cn":"瑞士决定就加入欧盟问题举行全民投票。"},{"en":"The changes were approved by referendum.","cn":"全民投票赞同这些变革。"}],"oxford":{"phon":"ˌrefəˈrendəm","pos":"noun","senses":[{"en":"an occasion when all the people of a country can vote on an important issue","cn":"全民公投；全民公决","lab":"especially North American English","ex":{"en":"Switzerland decided to hold a referendum on joining the EU.","cn":"瑞士决定就加入欧盟问题举行全民公投。"}}]}},"repetition":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(常指令人不快的事件的)反复发生，重复出现，重演","en":"If there is a repetition of an event, usually an undesirable event, it happens again.","ex":{"en":"Today the city government has taken measures to prevent a repetition of last year's confrontation","cn":"今天市政府已经采取措施，防止去年的冲突重演。"}},{"pos":"N-VAR 可变名词","cn":"(词语的)重复","en":"Repetition means using the same words again.","ex":{"en":"He could also have cut out much of the repetition and thus saved many pages.","cn":"他原本也可以砍去许多重复的内容，从而缩减许多页。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to happen again, once or repeatedly","cn":""},{"en":"an event or action that is the same as something that happened before","cn":""},{"en":"something that happens in exactly the same way as it happened before, usually with all the same problems","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun repetition to describe something that is repeated over and over, like the repetition of singing the alphabet song several times a day to help young children learn the letters."}]},"collocations":{"phrases":["ADJ. exact | frequent | constant, endless","VERB + REPETITION use Blues is a musical form that uses a lot of repetition. | avoid, prevent She said I should avoid repetition of words in","PHRASES the risk of repetition At the risk of repetition (= although I have already mentioned this) , it is worth mentioning again that youn"]},"media":{"uk":"media/ldoce/hwd/bre/6/repetition0205.mp3","us":"media/ldoce/hwd/ame/1/repetition.mp3"},"examples":[{"en":"We do not want to see a repetition of last year's tragic events.","cn":"我们不想看到去年的悲剧重演。"},{"en":"learning by repetition","cn":"通过重复来学习"}],"oxford":{"phon":"ˌrepəˈtɪʃn","pos":"noun","senses":[{"en":"the fact of doing or saying the same thing many times","cn":"重复；重做；重说","g":"[uncountable, countable]","ex":{"en":"learning by repetition","cn":"通过重复来学习"}},{"en":"a thing that has been done or said before","cn":"重做的事；重说的话","g":"[countable]","ex":{"en":"We do not want to see a repetition of last year's tragic events.","cn":"我们不想看到去年的悲剧重演。"}}]}},"retribution":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"惩罚;报应","en":"Retribution is punishment for a crime, especially punishment which is carried out by someone other than the official authorities.","ex":{"en":"He didn't want any further involvement for fear of retribution.","cn":"他担心受到惩罚，不想再牵涉其中。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is done to someone in order to punish them","cn":""},{"en":"an amount of money that you are ordered to pay as a punishment","cn":""},{"en":"an official punishment for someone who breaks a law, a rule, or a legal agreement","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Retribution is the act of taking revenge. If you pull a prank on someone, expect retribution ."}]},"collocations":{"phrases":["ADJ. fair, just | divine","VERB + RETRIBUTION demand, seek | exact | fear","RETRIBUTION + VERB come, follow Violent retribution soon followed.","PREP. in ~ His armies invaded their lands in retribution. | ~ against retribution against wrongdoers | ~ for He saw his suffering as retribu","PHRASES an act of retribution, fear of retribution The victim did not report the incident for fear of retribution."]},"media":{"uk":"media/ldoce/hwd/bre/6/retribution0205.mp3","us":"media/ldoce/hwd/ame/d/retribution.mp3"},"examples":[{"en":"People are seeking retribution for the latest terrorist outrages.","cn":"人们在设法对恐怖分子最近的暴行进行严惩。"},{"en":"fear of divine retribution (= punishment from God)","cn":"对上帝的惩罚的畏惧"}],"oxford":{"phon":"ˌretrɪˈbjuːʃn","pos":"noun","senses":[{"en":"severe punishment for something seriously wrong that somebody has done","cn":"严惩；惩罚；报应","ex":{"en":"People are seeking retribution for the latest terrorist outrages.","cn":"人们在设法对恐怖分子最近的暴行进行严惩。"}}]}},"relapse":{"collins":{"senses":[{"pos":"VERB 动词","cn":"故态复萌;重新陷入;倒退","en":"If you say that someone relapses into a way of behaving that is undesirable, you mean that they start to behave in that way again.","ex":{"en":"'I wish I did,' said Phil Jordan, relapsing into his usual gloom","cn":"“我要是那样做了就好了，”菲尔·乔丹说道，又像往常一样消沉起来。"}},{"pos":"VERB 动词","cn":"旧病复发;再次发病","en":"If a sick person relapses, their health suddenly gets worse after it had been improving.","ex":{"en":"In 90 per cent of cases the patient will relapse within six months.","cn":"90%的病人在6个月内会再次发病。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if someone who is ill gets worse or their condition gets worse , they become more seriously ill","cn":""},{"en":"if someone's medical condition deteriorates , it gets worse","cn":""},{"en":"if someone who has a serious illness relapses , they get worse when they had previously been getting better","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"A relapse is a decline, especially of someone's health. If your grandmother survived cancer only to have it return two years later, you could say she suffered a relapse ."}]},"collocations":{"phrases":["ADJ. acute","VERB + RELAPSE suffer | cause, trigger A wide range of emotionally stressful events may trigger a relapse. | prevent","RELAPSE + VERB occur","PREP. in ~ Even in relapse there will be times when the patient's general condition improves.","PHRASES a risk of relapse"]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41relapse.mp3","us":"media/ldoce/hwd/ame/8/ld44relapse.mp3"},"examples":[{"en":"Two days after leaving the hospital she relapsed into a coma.","cn":"出院两天后，她再度昏迷。"},{"en":"They relapsed into silence.","cn":"他们又都沉默不语。"}],"oxford":{"phon":"ˈriːlæps","pos":"noun","senses":[{"en":"the fact of becoming ill again after making an improvement","cn":"旧病复发","ex":{"en":"to have/suffer a relapse","cn":"旧病复发"}},{"en":"to go back into a previous condition or into a worse state after making an improvement","cn":"退回原状；（好转后）再倒退","ex":{"en":"They relapsed into silence.","cn":"他们再次陷入了沉默。"},"pos":"verb"}]}},"regain":{"collins":{"senses":[{"pos":"VERB 动词","cn":"恢复；失而复得；重新得到","en":"If you regain something that you have lost, you get it back again.","ex":{"en":"Troops have regained control of the city","cn":"军队重新控制了该市。"}},{"pos":"VERB 动词","cn":"重返","en":"If you regain a place that you have left, you succeed in getting back there.","ex":{"en":"Davis went to regain his carriage.","cn":"戴维斯回到他的马车上。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to become conscious again after being unconscious","cn":""},{"en":"to become conscious again gradually, especially after an accident or injury","cn":""},{"en":"to become gradually conscious again after being made unconscious, especially by being hit on the head","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"After you get off of a crazy carnival ride, you'll probably have to regain your balance, or get it back."}]},"collocations":{"phrases":["ADV. completely He hadn't completely regained his strength. | quickly, rapidly | gradually, slowly | eventually, finally | never He was seve","VERB + REGAIN fight to, struggle to, try to The team are struggling to regain last season's form. | be desperate to, be determined to, hope ","PHRASES an attempt/a bid/an effort to regain sth He is making a bid to regain his World No 1 ranking. | a chance/an opportunity to regain st"]},"media":{"uk":"media/ldoce/hwd/bre/b/regain0205.mp3","us":"media/ldoce/hwd/ame/3/regain.mp3"},"examples":[{"en":"The party has regained control of the region.","cn":"这一政党重新获得了这个地区的控制权。"},{"en":"She paused on the edge, trying to regain her balance.","cn":"她在边缘上暂停下来，努力恢复平衡。"}],"oxford":{"phon":"rɪˈɡeɪn","pos":"verb","senses":[{"en":"to get back something you no longer have, especially an ability or a quality","cn":"重新获得，恢复（尤指能力或品质等）","ex":{"en":"I struggled to regain some dignity.","cn":"我努力恢复自己的一点儿尊严。"}},{"en":"to get back to a place that you have left","cn":"回到（原位）；返回","lab":"literary","ex":{"en":"They finally managed to regain the beach.","cn":"他们最后终于回到了海滩。"}}]}},"restrain":{"collins":{"senses":[{"pos":"VERB 动词","cn":"制止;阻止","en":"If you restrain someone, you stop them from doing what they intended or wanted to do, usually by using your physical strength.","ex":{"en":"Wally gripped my arm, partly to restrain me and partly to reassure me","cn":"沃利抓住我的手臂，一是想制止我，二是想稳住我。"}},{"pos":"VERB 动词","cn":"克制(情绪);抑制（自己）","en":"If you restrain an emotion or you restrain yourself from doing something, you prevent yourself from showing that emotion or doing what you wanted or intended to do.","ex":{"en":"She was unable to restrain her desperate anger","cn":"她无法控制自己极度的愤怒。"}},{"pos":"VERB 动词","cn":"抑制;限制;控制","en":"To restrain something that is growing or increasing means to prevent it from getting too large.","ex":{"en":"The radical 500-day plan was very clear on how it intended to try to restrain inflation","cn":"这个为期500天的激进计划明确阐明将如何控制通货膨胀。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you control yourself or control your feelings, you continue to behave calmly and sensibly and do not become too angry, excited, or upset","cn":""},{"en":"the ability to behave calmly and sensibly and not become too angry, excited, or upset, even when you have a good reason to","cn":""},{"en":"to manage to stay calm and not become angry, especially when someone is trying to make you angry","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Restrain means to hold yourself back, which is exactly what you'd have to do if, after weeks of dieting, you found yourself face to face with a dessert case filled with pies, cakes, and cookies."}]},"collocations":{"phrases":["ADV. barely I barely restrained myself from hitting him. | effectively | forcibly, physically She had to be physically restrained.","VERB + RESTRAIN be unable to, can't/couldn't, can/could no longer She could not restrain a flash of pride. | seek to, try to | manage to","PREP. from He restrained himself from shouting at her.","PHRASES an attempt/effort to restrain sb"]},"media":{"uk":"media/ldoce/hwd/bre/b/restrain0205.mp3","us":"media/ldoce/hwd/ame/a/restrain.mp3"},"examples":[{"en":"They have obtained an injunction restraining the company from selling the product.","cn":"他们已经得到阻止这家公司出售这一产品的禁销令。"},{"en":"The government is taking steps to restrain inflation.","cn":"政府正在采取措施控制通货膨胀。"}],"oxford":{"phon":"rɪˈstreɪn","pos":"verb","senses":[{"en":"to stop somebody/something from doing something, especially by using physical force","cn":"（尤指用武力）制止，阻止，管制","ex":{"en":"The prisoner had to be restrained by the police.","cn":"警方只好强行制住囚犯。"}},{"en":"to stop yourself from feeling an emotion or doing something that you would like to do","cn":"约束（自己）；控制（自己）；忍住","ex":{"en":"John managed to restrain his anger.","cn":"约翰努力压制住自己的怒气。"}},{"en":"to stop something that is growing or increasing from becoming too large","cn":"抑制；控制","ex":{"en":"The government is taking steps to restrain inflation.","cn":"政府正在采取措施控制通货膨胀。"}}]}},"reversal":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（过程、政策或趋势的）反转，倒转，逆转","en":"A reversal of a process, policy, or trend is a complete change in it.","ex":{"en":"The Financial Times says the move represents a complete reversal of previous US policy","cn":"《金融时报》说此举一反美国以往的政策。"}},{"pos":"N-COUNT 可数名词","cn":"（角色的）交换，互换","en":"When there is a role reversal or a reversal of roles, two people or groups exchange their positions or functions.","ex":{"en":"When children end up taking care of their parents, it is a strange role reversal indeed.","cn":"当孩子们最终要照顾父母时，这的确是一种奇妙的角色互换。"}},{"pos":"N-COUNT 可数名词","cn":"(通常涉及金钱损失的)失败，逆境，挫折","en":"A reversal is a failure, usually involving the loss of money.","ex":{"en":"They teach managers to accept reversals as a fact of business life.","cn":"他们教给管理人员要将挫折视为生意上的平常事。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a complete, and usually sudden, change from one thing to another","cn":""},{"en":"a change from one job or type of work to another","cn":""},{"en":"a change to an opposite process or effect","cn":""}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"A reversal is a change of decision or direction, often to the opposite. You liked history, but thought you'd major in business because there were more jobs. Then you took an economics class and hated it. So in a reversal , you majored in history after all."}]},"collocations":{"phrases":["ADJ. complete, total | dramatic, sudden | apparent | policy | role Some people looking after elderly parents have trouble with the role reve","VERB + REVERSAL amount to, mark, represent This represents an apparent reversal of previous US policy. | bring about, lead to, result in","PREP. ~ in the dramatic reversal in population decline | ~ of a reversal of current trends","PHRASES a reversal of fortunes Industrial unrest and cheaper imports played their part in the company's reversal of fortunes."]},"media":{"uk":"media/ldoce/hwd/bre/b/reversal0205.mp3","us":"media/ldoce/hwd/ame/f/reversal.mp3"},"examples":[{"en":"The government suffered a total reversal of fortune(s) last week.","cn":"上星期，政府的命运发生了逆转。"},{"en":"The company's financial problems were only a temporary reversal.","cn":"公司的财务问题只是暂时的挫折。"}],"oxford":{"phon":"rɪˈvɜːsl","pos":"noun","senses":[{"en":"a change of something so that it is the opposite of what it was","cn":"颠倒；彻底转变；反转；倒置","g":"[countable, uncountable]","ex":{"en":"a complete/dramatic/sudden reversal of policy","cn":"政策的全面／剧烈／突然转变"}},{"en":"a change from being successful to having problems or being defeated","cn":"倒退；逆转；退步；转胜为败","g":"[countable]","ex":{"en":"the team’s recent reversal","cn":"球队最近的失败"}},{"en":"an exchange of positions or functions between two or more people","cn":"（位置或功能的）转换，交换","g":"[countable, uncountable]","ex":{"en":"It’s a complete role reversal/reversal of roles (= for example when a child cares for a parent).","cn":"这是彻底的角色转换。"}}]}},"registry":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"登记文档；登记处；注册处","en":"A registry is a collection of all the official records relating to something, or the place where they are kept.","ex":{"en":"It agreed to set up a central registry of arms sales.","cn":"它同意成立一个中央武器销售登记处。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where information used by an organization is kept, especially official records or lists","cn":"登记处﹔注册处﹔档案处"},{"en":"used when saying where something, especially a ship, is officially register ed","cn":"登记〔尤指船舶在某地登记〕"}]},"collocations":{"phrases":["ADJ. public | private | central a central registry for all applicants | district, national, regional | land, companies' The deed of transfer","VERB + REGISTRY enter sth at/in, lodge sth at/in, register sth at The certificate will have to be lodged at the registry.","REGISTRY + VERB have sth, hold sth, keep sth The registry holds records of all major operations.","REGISTRY + NOUN fee | office | staff","PHRASES at a/the ~ The map is kept at the local land registry."]},"media":{"uk":"media/ldoce/hwd/bre/a/registry0205.mp3","us":"media/ldoce/hwd/ame/a/registry.mp3"},"examples":[{"en":"the registry of the vessel","cn":"船舶登记"}],"oxford":{"phon":"ˈredʒɪstri","pos":"noun","senses":[{"en":"a place where registers are kept; an official list or register","cn":"登记处；注册处；登记表","ex":{"en":"The registry holds records of all major operations.","cn":"登记处有所有重大手术的记录。"}}]}},"reflex":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"本能反应;习惯性动作","en":"A reflex or a reflex action is something that you do automatically and without thinking, as a habit or as a reaction to something.","ex":{"en":"Walsh fumbled in his pocket, a reflex from his smoking days","cn":"沃尔什在口袋里摸索着，这是他抽烟时养成的习惯动作。"}},{"pos":"N-COUNT 可数名词","cn":"条件反射；反射性动作","en":"A reflex or a reflex action is a normal, uncontrollable reaction of your body to something that you feel, see, or experience.","ex":{"en":"...tests for reflexes, like tapping the knee or the heel with a rubber hammer.","cn":"如用橡胶槌敲击膝盖或脚跟那样的反射性动作测试"}},{"pos":"N-PLURAL 复数名词","cn":"反应力;应激能力","en":"Your reflexes are your ability to react quickly with your body when something unexpected happens, for example when you are involved in sport or when you are driving a car.","ex":{"en":"It takes great skill, cool nerves and the reflexes of an athlete.","cn":"那需要运动员有高超的技巧、冷静的头脑和迅速的反应能力。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you give an answer off the top of your head , you say it without thinking about it for very long and without being sure it is correct","cn":""},{"en":"if you say or do something in the heat of the moment , you do it very suddenly and without thinking when you are feeling angry or excited, so that you feel sorry about it afterwards","cn":""},{"en":"an automatic response, reaction, or answer is one that happens immediately and without you having to think, especially because you have done it many times before","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A reflex is an action your body does without your thinking about it, like sneezing, or jumping a little when you dream you’re falling. If you suddenly catch a ball before it crashes into a window, you have quick reflexes ."}]},"collocations":{"phrases":["ADJ. good, lightning, quick | poor | automatic | natural | conditioned","VERB + REFLEX trigger The rapid movement of an object towards the eye triggers the blink reflex. | control | sharpen, speed up The training ","REFLEX + NOUN action, reaction Almost as a reflex action, I grab my pen as the phone rings.","PREP. by ~ Almost by reflex, he helped himself to a drink."]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdereflex.mp3","us":"media/ldoce/hwd/ame/5/reflex.mp3"},"examples":[{"en":"Almost as a reflex action , I grab my pen as the phone rings.","cn":"几乎是一种本能反应，电话铃一响，我就抓起笔。"},{"en":"Only the goalkeeper's reflexes (= his ability to react quickly) stopped the ball from going in.","cn":"只是因为守门员反应迅速，球才没有进。"}],"oxford":{"phon":"ˈriːfleks","pos":"noun","senses":[{"en":"an action or a movement of your body that happens naturally in response to something and that you cannot control; something that you do without thinking","cn":"反射动作；本能反应；反射作用","ex":{"en":"The doctor tested her reflexes.","cn":"医生检测了她的反射动作。"}}]}},"rein":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"(马的)缰绳","en":"Reins are the thin leather straps attached round a horse's neck which are used to control the horse."},{"pos":"N-PLURAL 复数名词","cn":"(新闻用语)支配权，控制权","en":"Journalists sometimes use the expression the reins or the reins of power to refer to the control of a country or organization.","ex":{"en":"He was determined to see the party keep a hold on the reins of power","cn":"他决意要确保这个政党掌握政权。"}},{"pos":"PHRASE 短语","cn":"放任;不管;纵容","en":"If you give free rein to someone, you give them a lot of freedom to do what they want.","ex":{"en":"The government continued to believe it should give free rein to the private sector in transport.","cn":"政府仍然认为应该给予交通领域的私营企业以经营自由。"}},{"pos":"PHRASE 短语","cn":"严加控制;严格管束","en":"If you keep a tight rein on someone, you control them firmly.","ex":{"en":"Her parents had kept her on a tight rein with their narrow and inflexible views.","cn":"她的父母观念狭隘而僵化，对她管束很严。"}},{"pos":"","cn":"","en":"相关词组：rein back rein in"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if someone who employs you gives you free rein to plan, make, or operate something, they let you decide what to do and how to do it","cn":""},{"en":"if someone in authority gives someone carte blanche , they give them complete power over what is done and how it is done - use this especially when you do not approve of the power they are given or the decisions they make","cn":""},{"en":"to let someone have as much money as they need to do something - use this especially about government or business activity","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Rein is both a noun and a verb for guiding and restraining. You can use the long strap, or rein, on a horse to control its speed and direction, and you can rein in your own tongue by closing your mouth."}]},"collocations":{"phrases":["VERB + REIN hold Can you hold the reins for a minute? | gather (up), pick up Sean gathered up the horse's reins. | grab (at), pull on She pu","PREP. on a ~ She had the horse on a long rein. 2 the reins: being in control/the leader of sth","VERB + REIN hold It's the Treasury that effectively holds the reins. | grasp, take up The vice-president was forced to take up the reins of ","PHRASES the reins of government/office/power"]},"media":{"uk":"media/ldoce/hwd/bre/2/reign_v0205.mp3","us":"media/ldoce/hwd/ame/3/rain1.mp3"},"examples":[{"en":"The script allows full rein to her larger-than-life acting style.","cn":"剧本允许她充分展现她那夸张的表演风格。"},{"en":"We need to rein back public spending.","cn":"我们需要严格控制公共开销。"}],"oxford":{"phon":"reɪn","pos":"noun","senses":[{"en":"a long narrow leather band that is attached to a metal bar in a horse’s mouth (= a bit) and is held by the rider in order to control the horse","cn":"缰绳","g":"[countable, usually plural]","ex":{"en":"She pulled gently on the reins.","cn":"她轻轻地拉着缰绳。"}},{"en":"a pair of long narrow pieces of cloth or other material worn by a small child and held by an adult in order to stop the child from walking off and getting lost","cn":"（把儿童和成人的手系在一起以防走失的）牵引绳，防走失带","g":"[plural]","lab":"British English"},{"en":"the state of being in control or the leader of something","cn":"控制；主宰；掌管","g":"[plural]","ex":{"en":"It was time to hand over the reins of power (= to give control to somebody else).","cn":"是该让权的时候了。"}}]}},"relay":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"接力比赛(如赛跑或游泳)","en":"A relay or a relay race is a race between two or more teams, for example teams of runners or swimmers. Each member of the team runs or swims one section of the race.","ex":{"en":"Britain's prospects of beating the United States in the relay looked poor.","cn":"英国要在接力赛中战胜美国，前景看上去并不那么乐观。"}},{"pos":"VERB 动词","cn":"转播，传送，传输(电视或收音机信号)","en":"To relay television or radio signals means to send them or broadcast them.","ex":{"en":"The satellite will be used mainly to relay television programmes","cn":"这颗人造卫星主要用途是转播电视节目。"}},{"pos":"N-COUNT 可数名词","cn":"(接受和发送电视或广播信号的)转播设备，中继设备","en":"A relay is a piece of equipment that receives television or radio signals from one place and sends them to another place.","ex":{"en":"...a security system with satellite relays.","cn":"带有卫星传输设备的保安系统"}},{"pos":"VERB 动词","cn":"传（话）；转述","en":"If you relay something that has been said to you, you repeat it to another person.","ex":{"en":"She relayed the message, then frowned","cn":"她把消息带到了，然后皱紧了眉头。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if people do something in relays, several small groups of them do it, one group after another, so that the activity is continuous","cn":"轮班﹐轮换"},{"en":"a relay race","cn":"接力赛"},{"en":"a piece of electrical equipment that receives radio or television signals and sends them on","cn":"中继设备﹐转播设备"}]},"vocab":{"pos":"1 n v 2 n v","senses":[{"en":"If you relay something, you pass it to another person. When you relay the information that your pet monkey is known to attack people to your neighbors, you should bring a basket of muffins."}]},"collocations":{"phrases":["ADJ. 4 亊 400, etc. | medley, sprint","VERB + RELAY run (in) She ran in the 4 亊 400 relay. | win","RELAY + NOUN race | team"]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasderelay1.mp3","us":"media/ldoce/hwd/ame/1/l3relay.mp3"},"examples":[{"en":"The game was relayed by satellite to audiences all over the world.","cn":"这场比赛通过卫星向全世界的观众进行了转播。"},{"en":"He relayed the message to his boss.","cn":"他将这个消息转给了他的老板。"}],"oxford":{"phon":"ˈriːleɪ","pos":"noun","senses":[{"en":"a race between teams in which each member of the team runs or swims one section of the race","cn":"接力赛","ex":{"en":"the 4 × 100m relay","cn":"4 × 100 米接力赛"}},{"en":"a fresh set of people or animals that take the place of others that are tired or have finished a period of work","cn":"接班的人（或动物）；轮换者","ex":{"en":"The wagons were pulled by relays of horses.","cn":"货车由一组接一组的马匹轮流拉"}},{"en":"an electronic device that receives radio or television signals and sends them on again with greater strength","cn":"中继设备","ex":{"en":"a relay station","cn":"中继站"}},{"en":"to receive and send on information, news, etc. to somebody","cn":"转发（信息、消息等）","ex":{"en":"He relayed the message to his boss.","cn":"他将这个消息转给了他的老板。"},"pos":"verb"},{"en":"to broadcast television or radio signals","cn":"播放，转播（电视或广播信号）","ex":{"en":"The game was relayed by satellite to audiences all over the world.","cn":"这场比赛通过卫星向全世界的观众进行了转播。"},"pos":"verb"},{"en":"to lay something again or in a different way","cn":"重新铺设","ex":{"en":"The council are going to relay the road surface outside our house next month.","cn":"议会将于下个月在我们家外面铺设路面。"},"pos":"verb"}]}},"repress":{"collins":{"senses":[{"pos":"VERB 动词","cn":"压制，压抑，克制(情感)","en":"If you repress a feeling, you make a deliberate effort not to show or have this feeling.","ex":{"en":"People who repress their emotions risk having nightmares","cn":"压抑情感的人容易做噩梦。"}},{"pos":"VERB 动词","cn":"忍住;控制住","en":"If you repress a smile, sigh, or moan, you try hard not to smile, sigh, or moan.","ex":{"en":"He repressed a smile","cn":"他忍住笑。"}},{"pos":"VERB 动词","cn":"压制，限制(自由)","en":"If a section of society is repressed, their freedom is restricted by the people who have authority over them.","ex":{"en":"Turkish Kurds have been repressed for decades by the Ankara government.","cn":"土耳其的库尔德人已经被安卡拉政府压制了几十年。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use force to control large groups of people - use this especially about governments and people in authority","cn":""},{"en":"oppressive laws or governments control people so tightly that they have very little freedom left","cn":""},{"en":"to control people by not allowing them to use their natural abilities, intelligence, or energy to improve their situation","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"Whether you're repressing a feeling, an idea or even a revolution you're almost always going to be taking advantage of the press in repress . To repress something is to \"press it down\" where it can't be seen, heard or even recognized."}]},"collocations":{"phrases":["ADV. firmly feelings that had been firmly repressed | barely She could barely repress a sigh of relief.","VERB + REPRESS try to | be unable to"]},"media":{"uk":"media/ldoce/hwd/bre/0/repress0205.mp3","us":"media/ldoce/hwd/ame/e/repress.mp3"},"examples":[{"en":"He burst in, making no effort to repress his fury.","cn":"他冲了进来，毫不掩饰自己的愤怒。"},{"en":"to repress a smile","cn":"忍住不笑"}],"oxford":{"phon":"rɪˈpres","pos":"verb","senses":[{"en":"to try not to have or show an emotion, a feeling, etc.","cn":"克制；压抑；抑制","ex":{"en":"to repress a smile","cn":"忍住不笑"}},{"en":"to use political and/or military force to control a group of people and limit their freedom","cn":"压制；镇压","g":"[often passive]","ex":{"en":"The government was quick to repress any opposition.","cn":"政府迅速镇压一切反对势力。"}}]}},"repression":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"镇压;压制;控制","en":"Repression is the use of force to restrict and control a society or other group of people.","ex":{"en":"...a society conditioned by violence and repression.","cn":"受暴力和镇压制约的社会"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(情感，尤指性欲的)压抑，控制","en":"Repression of feelings, especially sexual ones, is a person's unwillingness to allow themselves to have natural feelings and desires.","ex":{"en":"...the repression of his feelings about men.","cn":"他对男人情感的压抑"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone does not allow themselves to express feelings or desires which they are ashamed of, especially sexual ones – used when you think someone should express these feelings 〔","cn":"对性爱或性欲等羞于表达的感情或欲望的〕抑制﹐克制﹐压抑"},{"en":"cruel and severe control of a large group of people","cn":"镇压"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Repression is a kind of holding back or holding down. There's repression of feelings (willing yourself not to cry), as well as social repression (where the government limits freedom or shuts out certain groups)."}]},"collocations":{"phrases":["ADJ. extreme, massive, severe | bloody, brutal, ruthless | political | government, military, police, state","VERB + REPRESSION suffer (from) The trade unions suffered brutal repression after the coup. | subject (sb/sth) to Reports claimed that civil","PREP. ~ against repression against ethnic minorities | ~ by repression by the state","PHRASES a target for/of repression 2 controlling strong emotions/desires","ADJ. emotional, sexual"]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41repression.mp3","us":"media/ldoce/hwd/ame/b/repression.mp3"},"examples":[{"en":"government repression","cn":"政府的压制"},{"en":"sexual repression","cn":"性压抑"}],"oxford":{"phon":"rɪˈpreʃn","pos":"noun","senses":[{"en":"the act of using force to control a group of people and limit their freedom","cn":"压制；镇压","ex":{"en":"Peasant farmers face poverty and severe government repression.","cn":"农民面临贫困和政府的严厉镇压。"}},{"en":"the act of controlling strong emotions and desires and not allowing them to be expressed so that they no longer seem to exist","cn":"抑制；克制；压抑","ex":{"en":"sexual repression","cn":"性压抑"}}]}},"resentful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"怨恨的;愤慨的;憎恨的","en":"If you are resentful, you feel resentment.","ex":{"en":"At first I felt very resentful and angry about losing my job","cn":"起初我对丢掉工作感到非常怨恨和恼怒。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a group of people are up in arms , they are protesting angrily about something that has been done or decided, especially by the government or some other official group","cn":""},{"en":"to feel very angry and disappointed because you think that someone's actions are very wrong, dishonest, or immoral","cn":""},{"en":"extremely angry about something wrong, immoral, or unfair, especially something violent","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you are resentful of someone, you feel ill will toward him, mixed with envy, like when a newer coworker gets the promotion you've been working toward for years."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound | become, grow They grew bitter and resentful. | remain","ADV. bitterly, deeply, extremely, very They were bitterly resentful of the fact that they had to work such long hours. | increasingly | almo","PREP. about/at She felt resentful at the way she had been treated. | of He was very resentful of their success. | towards He felt deeply res"]},"media":{"uk":"media/ldoce/hwd/bre/0/resentful0205.mp3","us":"media/ldoce/hwd/ame/1/laadresentful.mp3"},"examples":[{"en":"They seemed to be resentful of our presence there.","cn":"他们好像对我们在那里露面很生气。"},{"en":"She was resentful at having been left out of the team.","cn":"她对被运动队淘汰感到气愤。"}],"oxford":{"phon":"rɪˈzentfl","pos":"adjective","senses":[{"en":"feeling bitter or angry about something that you think is unfair","cn":"感到气愤的；憎恨的；愤慨的","ex":{"en":"a resentful look","cn":"充满怨恨的眼神"}}]}},"repertoire":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（一个演员所能表演的）全部节目，曲目","en":"A per-former's repertoire is all the plays or pieces of music that he or she has learned and can perform.","ex":{"en":"Meredith D'Ambrosio has thousands of songs in her repertoire.","cn":"梅雷迪思·丹布罗西奥会唱几千首歌曲。"}},{"pos":"N-SING 单数名词","cn":"全部技能（或才能）","en":"The repertoire of a person or thing is all the things of a particular kind that the person or thing is capable of doing.","ex":{"en":"...Mike's impressive repertoire of funny stories","cn":"迈克会讲大量有趣故事的非凡才能"}},{"pos":"N-SING 单数名词","cn":"（某个种类的）全部剧目(或曲目)","en":"You can refer to all the plays or music of a particular kind as, for example, the classical repertoire or the jazz repertoire .","ex":{"en":"It is no coincidence that the works in the 'standard repertoire' tend to have names.","cn":"在“标准剧目”中的作品有各自的名字并非偶然。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"all the plays, pieces of music etc that a performer or group knows and can perform 〔","cn":"某个表演者或团体的〕全部剧目﹐常备节目"},{"en":"the total number of things that someone or something is able to do","cn":"全部技能"}]},"vocab":{"pos":"n","senses":[{"en":"Repertoire refers to the full supply of what you can do. A singer's repertoire is all the songs they can sing. A chef's repertoire is what she knows how to cook."}]},"collocations":{"phrases":["ADJ. extensive, large, vast, wide | full | limited, small | mainstream, standard | emotional An actor has to build a character and extend hi","VERB + REPERTOIRE have She has a rather limited repertoire. | add (sth) to, broaden, build (up), develop, expand, extend, increase He has ad","REPERTOIRE + VERB include sth His repertoire includes a large number of Scottish folk songs.","PREP. in the/your ~ a key piece in the standard concert repertoire"]},"media":{"uk":"media/ldoce/hwd/bre/4/repertoire0205.mp3","us":"media/ldoce/hwd/ame/1/repertoire.mp3"},"examples":[{"en":"a young child's growing verbal repertoire","cn":"小孩不断增长的语言表达能力"},{"en":"a pianist with a wide repertoire","cn":"能演奏很多曲子的钢琴师"}],"oxford":{"phon":"ˈrepətwɑː(r)","pos":"noun","senses":[{"en":"all the plays, songs, pieces of music, etc. that a performer knows and can perform","cn":"（总称某人的）可表演项目","lab":"formal","ex":{"en":"to add to/extend your repertoire","cn":"增加/扩展你的曲目"}},{"en":"all the things that a person is able to do","cn":"（某人的）全部才能，全部本领","ex":{"en":"a young child’s growing verbal repertoire","cn":"小孩不断增长的语言表达能力"}}]}},"recede":{"collins":{"senses":[{"pos":"VERB 动词","cn":"退回;后退;远离","en":"If something recedes from you, it moves away.","ex":{"en":"Luke's footsteps receded into the night","cn":"卢克在夜色中渐行渐远。"}},{"pos":"VERB 动词","cn":"（质量）下降;（问题或疾病等）逐渐减弱，好转","en":"When something such as a quality, problem, or illness recedes, it becomes weaker, smaller, or less intense.","ex":{"en":"Just as I started to think that I was never going to get well, the illness began to recede","cn":"正当我开始觉得自己永远都好不了了的时候，我的病开始好转了。"}},{"pos":"VERB 动词","cn":"（前额的头发）脱落","en":"If a man's hair starts to recede, it no longer grows on the front of his head.","ex":{"en":"...a youngish man with dark hair just beginning to recede","cn":"前额黑发刚开始脱落的年轻人"}},{"pos":"VERB 动词","cn":"（常指牙龈因为感染）萎缩","en":"If your gums start to recede, they begin to cover less of your teeth, usually as the result of an infection.","ex":{"en":"If untreated, the gums recede, become swollen and bleed","cn":"如果不进行治疗，牙龈会开始萎缩、红肿和出血。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something such as fear, anxiety, trouble or laughter subsides , it gradually decreases","cn":""},{"en":"if something such as people's liking or support for something or someone wanes , that feeling gradually becomes slightly less and will probably continue to decrease","cn":""},{"en":"if a possibility or chance recedes , it gradually becomes less and less likely","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Recede means to pull back, retreat, or become faint or distant. Flood waters recede, as do glaciers, and even abstractions like \"panic\" and \"hope.\" Think \" receding hairline.\" (That means bald.)"}]},"collocations":{"phrases":["ADV. a bit, a little, slightly His fine dark hair was receding a little. | further | gradually, slowly The pain was gradually receding. | fa","PREP. from These worries now receded from his mind.","PHRASES recede into the background/distance His footsteps receded into the distance."]},"media":{"uk":"media/ldoce/hwd/bre/3/recede0205.mp3","us":"media/ldoce/hwd/ame/9/recede.mp3"},"examples":[{"en":"The sound of the truck receded into the distance.","cn":"卡车的声音渐渐在远处消失了。"},{"en":"She watched his receding figure.","cn":"她看着他的身影渐渐远去。"}],"oxford":{"phon":"rɪˈsiːd","pos":"verb","senses":[{"en":"to move gradually away from somebody or away from a previous position","cn":"逐渐远离；渐渐远去","g":"[intransitive]","ex":{"en":"The sound of the truck receded into the distance.","cn":"卡车的声音渐渐在远处消失了。"}},{"en":"to become gradually weaker or smaller","cn":"逐渐减弱；慢慢变小","g":"[intransitive]","ex":{"en":"The prospect of bankruptcy has now receded (= it is less likely).","cn":"破产的可能性现已减少了。"}},{"en":"to stop growing at the front of the head","cn":"（头顶前部）头发停止生长，变秃","g":"[intransitive]","ex":{"en":"a middle-aged man with receding hair/a receding hairline","cn":"发际线后移的中年男子"}},{"en":"a chin (= part of the face below the mouth) that slopes backwards towards the neck","cn":"向后缩的下巴","g":"[intransitive]"}]}},"recall":{"collins":{"senses":[{"pos":"VERB 动词","cn":"记起;回想起;回忆说","en":"When you recall something, you remember it and tell others about it.","ex":{"en":"Henderson recalled that he first met Pollard during a business trip to Washington","cn":"亨德森记起他第一次见到波拉德是在一次去华盛顿出差的时候。"}},{"pos":"VERB 动词","cn":"（用于引出双方都已意识到的事）记得","en":"You can say as I recall ,you might recall, or you will recall to someone that you are talking to when you want to mention something that you are both already aware of which is relevant to the discussion.","ex":{"en":"As I recall, you're not on the board, Joe; you're only a minor shareholder","cn":"我记得你并没有进董事会，乔，你只是一个小股东而已。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"记性;记忆力","en":"Recall is the ability to remember something that has happened in the past or the act of remembering it.","ex":{"en":"He had a good memory, and total recall of her spoken words.","cn":"他记忆力很好，她当时说的话他全都记得起来。"}},{"pos":"VERB 动词","cn":"召回;叫回","en":"If you are recalled to your home, country, or the place where you work, you are ordered to return there.","ex":{"en":"Spain has recalled its Ambassador after a row over refugees seeking asylum at the embassy","cn":"在对难民到使馆寻求庇护一事产生严重分歧后，西班牙召回了其大使。"}},{"pos":"VERB 动词","cn":"召回（运动员）；使归队","en":"In sport, if a player is recalled to a team, he or she is included in that team again after being left out.","ex":{"en":"Dean Richards was recalled to the England squad for the match with Wales","cn":"迪安·理查兹被召回英格兰队参加对阵威尔士的比赛。"}},{"pos":"VERB 动词","cn":"召回（公司产品）","en":"If a company recalls a product, it asks the shops or the people who have bought that product to return it because there is something wrong with it.","ex":{"en":"The company said it was recalling one of its drugs","cn":"这个公司说正在召回他们生产的一种药。"}},{"pos":"PHRASE 短语","cn":"记不起来；无法忆起；无法恢复原状；面目全非","en":"If something is beyond recall, it is no longer possible to remember how it was or to bring it back to its original condition.","ex":{"en":"The ground has been polluted beyond recall","cn":"这片土地已被污染得面目全非。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to form an idea in your mind of people, events, places etc from the past","cn":""},{"en":"to remember a particular fact, event, or situation, especially in order to tell someone about it","cn":""},{"en":"to remember an event or situation","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 n","senses":[{"en":"When you recall something, you remember it, like telling your friend, \"As I recall , you said you'd buy my lunch the next time we got together.\""}]},"collocations":{"phrases":["ADV. clearly, distinctly, vividly, well I well recall walking the five miles to school every morning. | dimly, vaguely | correctly If I reca","VERB + RECALL seem to I seem to recall that she said she was going away. | be able to, can/could (barely), can't/couldn't (quite) | try to"]},"media":{"uk":"media/ldoce/hwd/bre/5/recall_v0205.mp3","us":"media/ldoce/hwd/ame/c/l3recall.mp3"},"examples":[{"en":"‘It was on a Thursday in March,’ he recalled. “","cn":"那是三月份的一个星期四。”他回忆道。"},{"en":"The poem recalls Eliot's ‘The Waste Land’.","cn":"这首诗令人想起艾略特的《荒原》。"}],"oxford":{"phon":"rɪˈkɔːl","pos":"verb","senses":[{"en":"to remember something","cn":"记起；回忆起；回想起","g":"[transitive, intransitive]","lab":"formal","ex":{"en":"She could not recall his name.","cn":"她想不起他的名字。"}},{"en":"to make somebody think of something","cn":"使想起；使想到；勾起","g":"[transitive]","ex":{"en":"The poem recalls Eliot's ‘The Waste Land’.","cn":"这首诗令人想起艾略特的《荒原》。"}},{"en":"to order somebody to return","cn":"召回","g":"[transitive]","ex":{"en":"Both countries recalled their ambassadors.","cn":"两个国家都召回了各自的大使。"}},{"en":"to ask for something to be returned, often because there is something wrong with it","cn":"收回，召回（残损货品等）","g":"[transitive]","ex":{"en":"The company has recalled all the faulty hairdryers.","cn":"公司回收了所有有瑕疵的吹风机。"}},{"en":"the ability to remember something that you have learned or something that has happened in the past","cn":"记忆力；记性","g":"[uncountable]","ex":{"en":"She has amazing powers of recall.","cn":"她有惊人的记忆力。"},"pos":"noun"},{"en":"an official order or request for somebody/something to return, or for something to be given back","cn":"召回令；回归请求；回收令","g":"[singular]","ex":{"en":"Thomas’s recall to the Welsh team","cn":"让托马斯回归威尔士队的要求"},"pos":"noun"}]}},"revival":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"复苏;复兴;恢复;再次流行","en":"When there is a revival of something, it becomes active or popular again.","ex":{"en":"This return to realism has produced a revival of interest in a number of artists","cn":"这种重回现实主义的趋势已经重新激起了人们对许多艺术家的兴趣。"}},{"pos":"N-COUNT 可数名词","cn":"(戏剧、歌剧或芭蕾等的)重新上演","en":"A revival is a new production of a play, an opera, or a ballet.","ex":{"en":"...John Clement's revival of Chekhov's 'The Seagull'.","cn":"约翰·克莱门特对于契诃夫的《海鸥》的重新演绎"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（复兴基督教信仰的）奋兴布道会","en":"A revival meeting is a public religious event that is intended to make people more interested in Christianity.","ex":{"en":"He toured South Africa organizing revival meetings.","cn":"他游历南非，组织奋兴布道会。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when something or someone becomes popular and fashionable again, for example a kind of music, a style of clothes, a writer, or a singer","cn":""},{"en":"a process in which something becomes active or strong again","cn":"复兴﹔复苏"},{"en":"when something becomes popular again","cn":"再流行"}]},"vocab":{"pos":"n","senses":[{"en":"If something experiences a revival , that means it’s once again popular or important. If a news story mentions a revival in the technology industry, that means the industry, having gone through a slump, is once again thriving."}]},"collocations":{"phrases":["ADJ. great, major, marked | modern, recent | cultural, economic, industrial, literary, religious, etc. The late 19th century was a time of r","VERB + REVIVAL enjoy, experience, undergo His work is enjoying a revival in popularity. | stage The economy has staged something of a reviva","PREP. ~ in a revival in the fortunes of the Democratic Party | ~ of a revival of ancient skills","PHRASES a revival of interest the revival of interest in local radio | signs of (a) revival He claimed the housing market was showing signs "]},"media":{"uk":"media/ldoce/hwd/bre/0/revival0205.mp3","us":"media/ldoce/hwd/ame/3/revival.mp3"},"examples":[{"en":"a revival of Peter Shaffer's ‘Equus’","cn":"彼得 · 谢弗的《马》的重演"},{"en":"a revival of interest in folk music","cn":"对民间音乐的兴趣的恢复"}],"oxford":{"phon":"rɪˈvaɪvl","pos":"noun","senses":[{"en":"an improvement in the condition or strength of something","cn":"（状况或力量的）进步，振兴，复苏","g":"[uncountable, countable]","ex":{"en":"the revival of trade","cn":"贸易振兴"}},{"en":"the process of something becoming or being made popular or fashionable again","cn":"复兴；再流行","g":"[countable, uncountable]","ex":{"en":"a religious revival","cn":"宗教的奋兴"}},{"en":"a new production of a play that has not been performed for some time","cn":"（戏剧的）重演","g":"[countable]","ex":{"en":"a revival of Peter Shaffer’s ‘Equus’","cn":"彼得·谢弗的《马》的重演"}}]}},"recurrence":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"复发；重现；再现","en":"If there is a recurrence of something, it happens again.","ex":{"en":"Police are out in force to prevent a recurrence of the violence.","cn":"警方出动大量警力防止暴力事件再次发生。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when something that has happened before happens again","cn":"再次发生﹐再次出现"}]},"vocab":{"pos":"n","senses":[{"en":"If something is happening yet again, there's a recurrence of it. Most sports fans hope there isn't a recurrence of last year's losing season."}]},"collocations":{"phrases":["ADJ. high | frequent | tumour, ulcer, etc.","VERB + RECURRENCE avoid, prevent | experience, have, suffer He has suffered a recurrence of his hamstring injury.","RECURRENCE + NOUN rate","PHRASES the likelihood of a recurrence, the risk of recurrence a high risk of recurrence"]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41recurrence.mp3","us":"media/ldoce/hwd/ame/d/recurrence.mp3"},"examples":[{"en":"attempts to prevent a recurrence of the problem","cn":"防止问题再次发生的努力"},{"en":"after the recurrence of a back problem","cn":"背疾复发之后"}],"oxford":{"phon":"rɪˈkʌrəns","pos":"noun","senses":[{"en":"if there is a recurrence of something, it happens again","cn":"重现；复发","ex":{"en":"attempts to prevent a recurrence of the problem","cn":"防止问题再次发生的努力"}}]}},"recollection":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"记忆；回忆","en":"If you have a recollection of something, you remember it.","ex":{"en":"Pat has vivid recollections of the trip","cn":"帕特清清楚楚地记得那次旅行。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to no longer remember information, something that happened in the past, or something that you must do","cn":""},{"en":"to not be able to remember something that you want to remember","cn":""},{"en":"to not be able to remember something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Recollection is either the process of remembering something or a specific memory."}]},"collocations":{"phrases":["ADJ. clear, distinct, vivid | dim, faint, hazy, vague | earliest | sudden | painful | personal","VERB + RECOLLECTION have (no) I have only a vague recollection of sunshine and sand. I have absolutely no recollection of the incident. | br","PREP. in ~ She stared at him in sudden recollection. | ~ from recollections from Eliot's own life","PHRASES to the best of your recollection To the best of my recollection (= if I remember correctly) , he was not there that day."]},"media":{"uk":"media/ldoce/hwd/bre/1/recollection0205.mp3","us":"media/ldoce/hwd/ame/9/recollection.mp3"},"examples":[{"en":"to have a clear/vivid/dim/vague recollection of sth","cn":"对某事的记忆清晰/历历在目/模糊不清/依稀如烟"},{"en":"To the best of my recollection (= if I remember correctly) I was not present at that meeting.","cn":"如果我没记错的话，我没有出席那次会议。"}],"oxford":{"phon":"ˌrekəˈlekʃn","pos":"noun","senses":[{"en":"the ability to remember something; the act of remembering something","cn":"记忆力；回忆；记忆","g":"[uncountable]","ex":{"en":"I have no recollection of meeting her before.","cn":"我不记得以前见过她。"}},{"en":"a thing that you remember from the past","cn":"往事；回忆的事","g":"[countable]","ex":{"en":"to have a clear/vivid/dim/vague recollection of something","cn":"对某事的记忆清晰／历历在目／模糊不清／依稀如烟"}}]}},"repayment":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"分期偿付款","en":"Repayments are amounts of money which you pay at regular intervals to a person or organization in order to repay a debt.","ex":{"en":"They were unable to meet their mortgage repayments","cn":"他们不能按时偿还抵押贷款。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"偿还;偿付","en":"The repayment of money is the act or process of paying it back to the person you owe it to.","ex":{"en":"He failed to meet last Friday's deadline for repayment of a 114m loan","cn":"他没能在上星期五的最后期限前偿还1.14亿的贷款。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you pay back money that you have borrowed 〔","cn":"借款的〕归还；〔债务的〕偿还"},{"en":"an amount of money that you pay regularly until you do not owe any more","cn":"分期偿还额"}]},"collocations":{"phrases":["ADJ. full | partial | early Interest will be refunded in the event of early repayment of the loan. | regular | monthly, weekly, etc. | capit","VERB + REPAYMENT make The repayments can be made directly from your current account. | keep up, meet They are struggling to keep up their lo","REPAYMENT + NOUN period | method, schedule, terms | loan, mortgage","PREP. ~ on repayments on the mortgage | ~ to repayment to the fund"]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41repayment.mp3","us":"media/ldoce/hwd/ame/e/repayment.mp3"},"examples":[{"en":"We were unable to meet (= pay) the repayments on the loan.","cn":"我们无法支付贷款的分期偿还额。"},{"en":"The loan is due for repayment by the end of the year.","cn":"这笔借款要在年底还清。"}],"oxford":{"phon":"rɪˈpeɪmənt","pos":"noun","senses":[{"en":"the act of paying back money that you have borrowed from a bank, etc.","cn":"归还借款；偿还债务","g":"[uncountable]","ex":{"en":"The loan is due for repayment by the end of the year.","cn":"这笔借款要在年底还清。"}},{"en":"a sum of money that you pay regularly to a bank, etc. until you have returned all the money that you owe","cn":"按期偿还的款项；分期偿还额","g":"[countable, usually plural]","lab":"British English","ex":{"en":"We were unable to meet (= pay) the repayments on the loan.","cn":"我们无法支付贷款的分期偿还额。"}}]}},"readable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有可读性的；值得一读的","en":"If you say that a book or article is readable, you mean that it is enjoyable and easy to read.","ex":{"en":"This is an impeccably researched and very readable book.","cn":"这本书中的研究缜密透彻，可读性很强。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易读的;字迹清晰的","en":"A piece of writing that is readable is written or printed clearly and can be read easily.","ex":{"en":"My secretary worked long hours translating my almost illegible writing into a typewritten and readable script.","cn":"我的秘书花了很长时间把我写的几乎无法辨认的手稿用打字机打印成易读的文本。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"easy and interesting or enjoyable to read","cn":""},{"en":"something that is well-written has been written in a good, clear style that makes it enjoyable or interesting to read","cn":""},{"en":"a book or piece of writing that is worth reading is good enough or interesting enough to make you want to read it","cn":""}]},"collocations":{"phrases":["VERBS be | make sth","ADV. eminently, extremely, highly, immensely, very a stimulating and highly readable account | quite 2 able to be read","VERBS be","ADV. clearly, easily The figures should be clearly readable. printed in large, easily readable type","PHRASES machine readable"]},"media":{"uk":"media/ldoce/hwd/bre/b/readable0205.mp3","us":"media/ldoce/hwd/ame/e/readable.mp3"},"examples":[{"en":"The book is informative and highly readable.","cn":"这本书内容丰富﹐读来饶有趣味。"}],"oxford":{"phon":"ˈriːdəbl","pos":"adjective","senses":[{"en":"that is easy, interesting and enjoyable to read","cn":"可读性强的；通俗易懂的","ex":{"en":"a highly readable account of life in prison","cn":"一部可读性极强的狱中生活记述"}},{"en":"clear and easy to read","cn":"清晰可辨的；易于识读的","ex":{"en":"The lettering on the front of the building is no longer readable.","cn":"建筑物正面的字迹已无法辨认。"}}]}},"revolt":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"反叛;起义;叛乱;抗争","en":"A revolt is an illegal and often violent attempt by a group of people to change their country's political system.","ex":{"en":"It was undeniably a revolt by ordinary people against their leaders","cn":"不可否认，这是一场平民百姓反抗领导人的起义。"}},{"pos":"VERB 动词","cn":"反叛;起义;叛乱;抗争","en":"When people revolt, they make an illegal and often violent attempt to change their country's political system.","ex":{"en":"In 1375 the townspeople revolted","cn":"1375年，市民奋起反抗。"}},{"pos":"N-VAR 可变名词","cn":"（对权威的）反抗，拒绝服从","en":"A revolt by a person or group against someone or something is a refusal to accept the authority of that person or thing.","ex":{"en":"The prime minister is facing a revolt by party activists over his refusal to hold a referendum","cn":"因为拒绝进行公民投票，首相正面临着党内激进分子的反抗。"}},{"pos":"VERB 动词","cn":"反抗，拒绝服从（权威）","en":"When people revolt against someone or something, they reject the authority of that person or reject that thing.","ex":{"en":"The prime minister only reacted when three of his senior cabinet colleagues revolted and resigned in protest on Friday night","cn":"直到周五晚上首相的3位高级内阁同僚倒戈并辞职以示抗议时，首相才有所反应。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt by a large group of people at revolution","cn":""},{"en":"an occasion when a group of people, especially soldiers, suddenly take control of a country","cn":""},{"en":"an organized attempt to change the government or other authority, often by using violence","cn":""}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"Revolt means to rise up against an authority in an act of rebellion. You might see an opposition group revolt against a government, or you might revolt against your oppressive 10:00 curfew."}]},"collocations":{"phrases":["ADJ. great The Great Revolt of 1381 may have been caused by attempts to keep wages down. | full-scale, general, large-scale, mass, popular, ","VERB + REVOLT cause, prompt, provoke, stir up | lead a student-led revolt | stage | control, crush, deal with, put down, quash, suppress The","REVOLT + VERB break out Revolt broke out when the government decided to raise the price of bread. | spread | overthrow sb/sth The regime was","PREP. in ~ The farmers rose in revolt. | ~ against the revolt against the poll tax in Britain | ~ by a revolt by backbenchers | ~ over the f"]},"media":{"uk":"media/ldoce/hwd/bre/2/revolt_v0205.mp3","us":"media/ldoce/hwd/ame/e/revolt1.mp3"},"examples":[{"en":"the biggest back-bench revolt this government has ever seen","cn":"本届政府所遭遇到的规模最大的一次普通下院议员的反抗"},{"en":"All the violence in the movie revolted me.","cn":"电影里的各种暴力场面令我非常震惊。"}],"oxford":{"phon":"rɪˈvəʊlt","pos":"noun","senses":[{"en":"a protest against authority, especially that of a government, often involving violence; the action of protesting against authority","cn":"（尤指针对政府的）反抗，违抗；起义；叛乱","lab":"formal","ex":{"en":"The Peasants Revolt of 1381 was the first popular uprising in England.","cn":"1381年的（瓦特·泰勒）农民起义是英国第一次人民起义。"}},{"en":"to take violent action against the people in power","cn":"反抗，反叛（当权者）","g":"[intransitive]","ex":{"en":"The peasants threatened to revolt.","cn":"农民威胁说要造反。"},"pos":"verb"},{"en":"to behave in a way that is the opposite of what somebody expects of you, especially in protest","cn":"叛逆；违抗","g":"[intransitive]","ex":{"en":"Teenagers often revolt against parental discipline.","cn":"青少年常常不遵从父母的条条框框。"},"pos":"verb"},{"en":"to make you feel horror","cn":"使惊骇；使恐惧；使憎恶","g":"[transitive]","ex":{"en":"All the violence in the movie revolted me.","cn":"电影里的各种暴力场面令我非常震惊。"},"pos":"verb"}]}},"restoration":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"王政复辟（指1660年英王查理二世复辟）","en":"The Restoration was the event in 1660 when Charles the Second became King of England, Scotland, and Ireland after a period when there had been no King or Queen."},{"pos":"ADJ 形容词","cn":"（戏剧、建筑等）王政复辟时期的","en":"Restoration is used to refer to the style of drama and architecture that was popular during and just after the rule of Charles the Second in England.","ex":{"en":"...a Restoration comedy.","cn":"王政复辟时期的喜剧"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you repair something such as an old building or a piece of furniture, so that it looks the same as when it was first built or made 〔","cn":"旧建筑或旧家具等的〕修复﹐整修"},{"en":"the act of bringing back a law, tax, or system of government 〔","cn":"法律﹑税收﹑政体的〕重新采用﹐恢复"},{"en":"the return of Charles II as king of England in 1660, and the period afterwards","cn":"王政复辟（时期）〔1660年英王查理二世复辟及其后的一段时期〕"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A restoration is when you bring something back to what it was. A crumbling house that is lovingly-rebuilt in its original style, a king who was kicked off his throne only to get it back — these are restorations ."}]},"collocations":{"phrases":["ADJ. complete, full | extensive Many of the older paintings have undergone extensive restoration.","VERB + RESTORATION carry out | undergo | await, be in need of, need This historic watermill is currently awaiting restoration.","RESTORATION + NOUN programme, project, work","PREP. for ~ The palace is closed for restoration. | under ~ a steam engine under restoration 2 bringing sth back into use/existence","ADJ. full the full restoration of Sino-US relations | immediate Protesters called for the immediate restoration of civil liberties.","PHRASES the restoration of diplomatic relations, the restoration of the monarchy"]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41restoration.mp3","us":"media/ldoce/hwd/ame/b/restoration1.mp3"},"examples":[{"en":"the restoration of the Elgin marbles to Greece","cn":"埃尔金大理石雕像之交还希腊"},{"en":"Restoration comedy/poetry (= written during and after this time)","cn":"王政复辟时期的喜剧/诗歌"}],"oxford":{"phon":"ˌrestəˈreɪʃn","pos":"noun","senses":[{"en":"the work of repairing and cleaning an old building, a painting, etc. so that its condition is as good as it originally was","cn":"整修；修复","g":"[uncountable, countable]","ex":{"en":"restoration work","cn":"修复工作"}},{"en":"the act of bringing back a system, a law, etc. that existed previously","cn":"（规章制度等的）恢复","g":"[uncountable, countable]","ex":{"en":"the restoration of diplomatic relations between the two countries","cn":"两国恢复外交关系"}},{"en":"the act of returning something to its correct place, condition or owner","cn":"复原；复位；回归；归还","g":"[uncountable]","ex":{"en":"the restoration of the Elgin marbles to Greece","cn":"埃尔金大理石雕塑品之交还希腊"}},{"en":"the time in Britain after 1660 when, following a period with no king or queen, Charles II became king","cn":"王政复辟时期（1660 年，英国经历了一段无王时期后，查理二世登基为王）","g":"[singular]","ex":{"en":"Restoration comedy/poetry (= written during and after this time)","cn":"王政复辟时期的喜剧／诗歌"}}]}},"rebellion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"谋反；叛乱；反叛","en":"A rebellion is a violent organized action by a large group of people who are trying to change their country's political system.","ex":{"en":"The British soon put down the rebellion.","cn":"英国人很快平息了叛乱。"}},{"pos":"N-VAR 可变名词","cn":"内讧；（来自政党内部的）反抗","en":"A situation in which politicians show their opposition to their own party's policies can be referred to as a rebellion .","ex":{"en":"There was a Labour rebellion when some left-wing MPs voted against the Chancellor's tax cuts","cn":"工党内部发生内讧，一些左翼国会议员对财政大臣提出的减税政策投了反对票。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt by a large group of people at revolution","cn":""},{"en":"an occasion when a group of people, especially soldiers, suddenly take control of a country","cn":""},{"en":"an organized attempt to change the government or other authority, often by using violence","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A rebellion is when you rise up and fight those in power, usually on a large scale. In \"Star Wars,\" the good guys fighting the powerful, evil empire were known as the rebellion ."}]},"collocations":{"phrases":["ADJ. full-scale, major | minor, small | general, open | armed | military, peasant, popular","VERB + REBELLION rise (up) in Simon de Montfort rose in rebellion in 1258. | launch, raise (literary) , stage They staged a rebellion agains","REBELLION + VERB occur Peasant rebellions occurred throughout the 16th century. | begin, break out Rebellion broke out in the Rhineland. | f","PREP. in ~ They are in rebellion against the conservative hierarchy of the Church. | ~ against a rebellion against the new king | ~ over a r","ADJ. adolescent, teenage, youthful","REBELLION + VERB stir The band refused to go on stage and rebellion began to stir in the audience.","PREP. ~ against rebellion against their parents","PHRASES an act of rebellion, a form of rebellion"]},"media":{"uk":"media/ldoce/hwd/bre/8/rebellion0205.mp3","us":"media/ldoce/hwd/ame/2/rebellion.mp3"},"examples":[{"en":"The north of the country rose in rebellion against the government.","cn":"这个国家的北方地区发生了反对政府的叛乱。"},{"en":"The army put down the rebellion.","cn":"军队镇压了叛乱。"}],"oxford":{"phon":"rɪˈbeljən","pos":"noun","senses":[{"en":"an attempt by some of the people in a country to change their government, using violence","cn":"谋反；叛乱；反叛","g":"[uncountable, countable]","ex":{"en":"The north of the country rose in rebellion against the government.","cn":"这个国家的北方地区发生了反对政府的叛乱。"}},{"en":"opposition to authority within an organization, a political party, etc.","cn":"（对权威的）反抗，不服从","g":"[uncountable, countable]","ex":{"en":"Some members are in rebellion against proposed cuts in spending.","cn":"一些成员反对削减开支的提议。"}},{"en":"opposition to authority; being unwilling to obey rules or accept normal standards of behaviour, dress, etc.","cn":"不顺从；叛逆","g":"[uncountable]","ex":{"en":"Teenage rebellion often starts in the home.","cn":"青少年的叛逆常常始于家庭。"}}]}},"retarded":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"智力迟钝的;智力发育迟缓的","en":"Someone who is retarded is much less advanced mentally than most people of their age.","ex":{"en":"...a special school for mentally retarded children.","cn":"为智障孩子设立的特殊学校"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"less mentally developed than other people of the same age. Many people think that this word is offensive.","cn":"弱智的﹐智力发育迟缓的〔许多人认为该词具有冒犯性〕"}]},"vocab":{"pos":"adj n","senses":[{"en":"Retarded is a word to describe someone who is mentally slow. This is a medical word that spread to slang, and is today considered very insulting and inappropriate."}]},"collocations":{"phrases":["VERBS be, look","ADV. severely Many of the children are severely retarded. | slightly | educationally, emotionally, mentally a mentally retarded child"]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasderetarded.mp3","us":"media/ldoce/hwd/ame/b/retarded.mp3"},"oxford":{"phon":"rɪˈtɑːdɪd","pos":"adjective","senses":[{"en":"slow to learn or develop mentally; finding it difficult to make progress in learning","cn":"迟钝的；弱智的；智力发育迟缓的"}]}},"repulsive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人憎恶的;让人厌恶的;使人反感的","en":"If you describe something or someone as repulsive, you mean that they are horrible and disgusting and you want to avoid them.","ex":{"en":"...repulsive fat white slugs.","cn":"让人恶心的白白胖胖的鼻涕虫"}},{"pos":"ADJ 形容词","cn":"相斥的;排斥的;斥力的","en":"A repulsive force is a force which pushes away what is around it.","ex":{"en":"The repulsive force within the nucleus is enormous.","cn":"核子内部的斥力是巨大的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely unattractive, with a face that is not at all nice to look at","cn":""},{"en":"extremely ugly, especially because you were born with something wrong with you","cn":""},{"en":"very ugly and extremely unpleasant to look at, especially so that people do not like to look at you","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"If something's repulsive , it's so disgusting you don't want to go near it. You may find rotting meat repulsive , but maggots find it delicious. To each its own!"}]},"collocations":{"phrases":["VERBS be, look, smell | find sb/sth","ADV. deeply, extremely She found the idea deeply repulsive. | utterly | slightly | morally, sexually","PREP. to He was utterly repulsive to her."]},"media":{"uk":"media/ldoce/hwd/bre/d/repulsive0205.mp3","us":"media/ldoce/hwd/ame/d/repulsive.mp3"},"examples":[{"en":"What a repulsive man!","cn":"这个人真讨厌！"},{"en":"a repulsive sight/smell/habit","cn":"令人厌恶的情景/气味/习惯"}],"oxford":{"phon":"rɪˈpʌlsɪv","pos":"adjective","senses":[{"en":"causing a feeling of strong dislike; very unpleasant","cn":"令人厌恶的；令人反感的；十分讨厌的","ex":{"en":"a repulsive sight/smell/habit","cn":"令人厌恶的情景／气味／习惯"}},{"en":"causing repulsion (= a force that pushes away)","cn":"引起排斥的；斥力的","lab":"physics","ex":{"en":"repulsive forces","cn":"斥力"}}]}},"revive":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)复苏;(使)复兴;(使)恢复;(使)再次流行","en":"When something such as the economy, a business, a trend, or a feeling is revived or when it revives, it becomes active, popular, or successful again.","ex":{"en":"...an attempt to revive the British economy","cn":"试图复兴英国经济的努力"}},{"pos":"VERB 动词","cn":"重新上演(戏剧、歌剧或芭蕾等)","en":"When someone revives a play, opera, or ballet, they present a new production of it.","ex":{"en":"The Gaiety is reviving John B. Kean's comedy 'The Man from Clare'.","cn":"盖伊提剧院正在重新上演约翰·B. 基恩的喜剧《来自克莱尔的人》。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)苏醒；(使)清醒","en":"If you manage to revive someone who has fainted or if they revive, they become conscious again.","ex":{"en":"She and a neighbour tried in vain to revive him","cn":"她和邻居想尽一切办法都没能让他苏醒过来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to start using a custom, system, law etc again, that was used in the past but then stopped","cn":""},{"en":"to start using a law or system again after you had previously stopped using it","cn":""},{"en":"to start or strengthen something such as an old practice, custom, or idea after it had begun to disappear, so that it becomes popular again","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To revive something is to provide it with new energy or life, like when you revive a drooping plant by watering it, or when you revive a boring party by breaking out the karaoke machine."}]},"collocations":{"phrases":["ADV. quickly, rapidly Banks and businesses had been rapidly reviving business activities in China. | suddenly","VERB + REVIVE try to trying to revive some of the old customs | help (to), help sb (to) the country's readiness to help revive the economic ","PHRASES an attempt/effort to revive sth attempts to revive falling sales | be aimed at reviving sth an initiative aimed at reviving talks on","VERB + REVIVE try to","PREP. with They revived him with cold water.","PHRASES an attempt/effort to revive sb Attempts to revive her failed and she was dead on arrival at hospital."]},"media":{"uk":"media/ldoce/hwd/bre/9/revive0205.mp3","us":"media/ldoce/hwd/ame/e/revive.mp3"},"examples":[{"en":"This 1930s musical is being revived at the National Theatre.","cn":"这部 20 世纪 30 年代的音乐剧正在国家剧院重新上演。"},{"en":"This movie is intended to revive her flagging career.","cn":"这部电影意在使她渐趋衰败的事业再现辉煌。"}],"oxford":{"phon":"rɪˈvaɪv","pos":"verb","senses":[{"en":"to become, or to make somebody/something become, conscious or healthy and strong again","cn":"（使）苏醒，复活，恢复","g":"[intransitive, transitive]","ex":{"en":"The flowers soon revived in water.","cn":"这些花见了水很快就活过来了。"}},{"en":"to make something start being used or done again","cn":"重新使用；使重做","g":"[transitive]","ex":{"en":"This quaint custom should be revived.","cn":"应该恢复这一独特的风俗。"}},{"en":"to produce again a play, etc. that has not been performed for some time","cn":"重新上演","g":"[transitive]","ex":{"en":"This 1930s musical is being revived at the National Theatre.","cn":"这部 20 世纪 30 年代的音乐剧正在国家剧院重新上演。"}}]}},"repercussion":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(不良)反响，反应，影响","en":"If an action or event has repercussions, it causes unpleasant things to happen some time after the original action or event.","ex":{"en":"It was an effort which was to have painful repercussions","cn":"这么做会带来极坏的负面影响。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a result that happens in addition to the result that you intended - use this especially about the unintended bad effects of medical treatment or drugs","cn":""},{"en":"a result that is indirectly caused by something you do or that happens","cn":""},{"en":"an unexpected result of an event or something you do, which happens in addition to the result you intended","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A repercussion is something that happens because of another action. You could quit paying your rent, but getting evicted from your apartment might be the repercussion ."}]},"collocations":{"phrases":["ADJ. considerable, important, major, serious, significant | wide/widespread | international | economic, political, social","VERB + REPERCUSSION have","REPERCUSSION + VERB be felt The repercussions of the change in policy will be felt throughout Europe.","PREP. ~ for Changes in the industry had major repercussions for the local community. | ~ on The pay cuts are likely to have serious repercus"]},"media":{"uk":"media/ldoce/hwd/bre/0/repercussion0205.mp3","us":"media/ldoce/hwd/ame/0/amelasderepercussion.mp3"},"examples":[{"en":"The collapse of the company will have repercussions for the whole industry.","cn":"这家公司的垮台将会给整个行业造成间接的负面影响。"}],"oxford":{"phon":"ˌriːpəˈkʌʃn","pos":"noun","senses":[{"en":"an indirect and usually bad result of an action or event that may happen some time afterwards","cn":"（间接的）影响，反响，恶果","ex":{"en":"The collapse of the company will have repercussions for the whole industry.","cn":"这家公司的垮台将会给整个行业造成间接的负面影响。"}}]}},"restrictive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"限制性的;约束性的","en":"Something that is restrictive prevents people from doing what they want to do, or from moving freely.","ex":{"en":"Britain is to adopt a more restrictive policy on arms sales.","cn":"英国将对武器出售采取更具限制性的政策。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is restrictive stops people doing what they want to do","cn":"限制（性）的﹐约束（性）的"}]},"vocab":{"pos":"adj","senses":[{"en":"Restrictive is an adjective that describes something that keeps people within certain boundaries. A household where you aren't allowed to play video-games, watch TV, or eat junk food is restrictive ."}]},"collocations":{"phrases":["VERBS be, seem","ADV. extremely, highly, very | increasingly | fairly, rather, somewhat | unduly, unnecessarily He argued that the law was unduly restrictive"]},"media":{"uk":"media/ldoce/hwd/bre/d/restrictive0205.mp3","us":"media/ldoce/hwd/ame/7/restrictive.mp3"},"examples":[{"en":"restrictive laws","cn":"限制性法规"},{"en":"Many members thought the rules were too restrictive.","cn":"很多会员认为这些规定限制得过于严苛。"}],"oxford":{"phon":"rɪˈstrɪktɪv","pos":"adjective","senses":[{"en":"preventing people from doing what they want","cn":"限制性的；约束的","ex":{"en":"restrictive laws","cn":"限制性法规"}},{"en":"explaining which particular person or thing you are talking about rather than giving extra information about them. In ‘The books which are on the table are mine’, ‘which are on the table’ is a restrictive relative clause.","cn":"限制性的","lab":"grammar"}]}},"recyclable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可回收的；可再次利用的","en":"Recyclable waste or materials can be processed and used again.","ex":{"en":"...a separate bin for recyclable waste products.","cn":"一个专门收集可回收废弃物的垃圾桶"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used materials or substances that are recyclable can be recycled","cn":"可回收利用的"}]},"collocations":{"phrases":["VERBS be","ADV. easily Paper is easily recyclable. | completely Glass products are completely recyclable. | potentially"]},"media":{"uk":"media/ldoce/hwd/bre/1/recyclable0205.mp3","us":"media/ldoce/hwd/ame/3/recyclable.mp3"},"examples":[{"en":"recyclable cardboard packaging","cn":"可回收利用的纸板包装材料"}],"oxford":{"phon":"ˌriːˈsaɪkləbl","pos":"adjective","senses":[{"en":"able to be recycled","cn":"可回收利用的；可再循环的","ex":{"en":"Glass products are completely recyclable.","cn":"玻璃制品可以完全回收利用。"}}]}},"resourceful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"足智多谋的;机智的;办法多的","en":"Someone who is resourceful is good at finding ways of dealing with problems.","ex":{"en":"He was amazingly inventive and resourceful, and played a major role in my career","cn":"他极具创造力，而且足智多谋，在我的职业生涯中起到了重要的作用。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"intelligent in a practical way, and able to use your intelligence to get advantages for yourself","cn":""},{"en":"a shrewd person is good at deciding what people, situations etc are really like, so that it is difficult to deceive them - use this especially about people who are successful in business","cn":""},{"en":"someone who is astute easily understands why people behave in a particular way, why a situation is happening etc, without anyone having to tell them","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you are interviewing employees for your new pet store, you may want to ask if they are resourceful . If they are, it means they are good at problem solving, and this could come in very handy."}]},"collocations":{"phrases":["VERBS be He is very clever and endlessly resourceful.","ADV. highly, very | endlessly"]},"media":{"uk":"media/ldoce/hwd/bre/1/resourceful0205.mp3","us":"media/ldoce/hwd/ame/e/resourceful.mp3"},"examples":[{"en":"a woman who is energetic and resourceful","cn":"精力充沛且足智多谋的女人"}],"oxford":{"phon":"rɪˈsɔːsfl","pos":"adjective","senses":[{"en":"good at finding ways of doing things and solving problems, etc.","cn":"机敏的；足智多谋的；随机应变的","ex":{"en":"These women were strong, resourceful and courageous.","cn":"这些女性坚强、足智多谋且勇敢。"}}]}},"reconstruction":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（战后的）重建","en":"Reconstruction is the process of making a country normal again after a war, for example by making the economy stronger and by replacing buildings that have been damaged.","ex":{"en":"...America's part in the post-war reconstruction of Germany.","cn":"美国在战后德国重建中的作用"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（建筑物或道路的）重新修建","en":"The reconstruction of a building, structure, or road is the activity of building it again, because it has been damaged.","ex":{"en":"Work began on the reconstruction of the road.","cn":"道路的重建工作开始了。"}},{"pos":"N-COUNT 可数名词","cn":"（犯罪现场的）重现","en":"The reconstruction of a crime or event is when people try to understand or show exactly what happened, often by acting it out.","ex":{"en":"Mrs Kerr was too upset to take part in a reconstruction of her ordeal.","cn":"克尔夫人受惊过度，不堪再参与自己所受折磨的场景重现。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the work that is done to repair the damage to a city, industry etc, especially after a war","cn":"修复﹔〔尤指战后的〕重建"},{"en":"a description or copy of an event or a place, which you produce by collecting information about it","cn":"再现﹐重现"}]},"vocab":{"pos":"n","senses":[{"en":"When you put something back together or rebuild it, you do a reconstruction , like the reconstruction of a neighborhood after a flood or earthquake."}]},"collocations":{"phrases":["ADJ. fundamental, major | complete, total | large/large-scale, life-size a life-size reconstruction of a Viking longboat | dramatic a dramat","VERB + RECONSTRUCTION undertake A group of enthusiasts have undertaken the reconstruction of a steam locomotive. | stage The police have sta","RECONSTRUCTION + NOUN period | work | plan, programme, scheme | cost reconstruction costs following the cyclone"]},"media":{"uk":"media/ldoce/hwd/bre/3/reconstruction0205.mp3","us":"media/ldoce/hwd/ame/6/reconstruction.mp3"},"examples":[{"en":"The doorway is a 19th century reconstruction of Norman work.","cn":"门廊是 19 世纪时模仿诺曼式建筑修建的。"},{"en":"Last night police staged a reconstruction of the incident.","cn":"昨天晚上，警方放映了再现事故经过的影片。"}],"oxford":{"phon":"ˌriːkənˈstrʌkʃn","pos":"noun","senses":[{"en":"the process of changing or improving the condition of something or the way it works; the process of putting something back into the state it was in before","cn":"重建；改造；复原","g":"[uncountable]","ex":{"en":"the reconstruction of the educational system","cn":"重建教育体系"}},{"en":"the activity of building again something that has been damaged or destroyed","cn":"修复；修理","g":"[uncountable]","ex":{"en":"the reconstruction of the sea walls","cn":"海堤的修复"}},{"en":"a copy of something that no longer exists","cn":"重现","g":"[countable]","ex":{"en":"The doorway is a nineteenth-century reconstruction of Norman work.","cn":"门廊是 19 世纪时模仿诺曼式建筑修建的。"}},{"en":"an act of acting out events that are known to have happened, in order to try and get more information or better understanding about what happened, especially a crime","cn":"（尤指犯罪过程的）再现影片，模拟还原片","g":"[countable]","ex":{"en":"Last night police staged a reconstruction of the incident.","cn":"昨天晚上，警方放映了再现事故经过的影片。"}},{"en":"(in the US) the period after the Civil War when the southern states returned to the US and laws were passed that gave rights to African Americans","cn":"重建时期（美国南北战争后南方各州重新加入联邦）","g":"[uncountable]"}]}},"refreshing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人耳目一新的；新鲜的","en":"You say that something is refreshing when it is pleasantly different from what you are used to.","ex":{"en":"It's refreshing to hear somebody speaking common sense","cn":"听到有人说话通情达理真是令人耳目一新。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（沐浴或饮料）使人精神焕发的，提神的，清凉的","en":"A refreshing bath or drink makes you feel energetic or cool again after you have been tired or hot.","ex":{"en":"Herbs have been used for centuries to make refreshing drinks.","cn":"草药用于调制提神饮品已有好几个世纪了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel less tired or less hot","cn":"消除疲劳的﹐提神的﹔清凉的"},{"en":"pleasantly different from what is familiar and boring","cn":"令人耳目一新的"}]},"collocations":{"phrases":["VERBS be | find sth","ADV. extremely, highly, really, very, wonderfully The water was cold and wonderfully refreshing. | quite"]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasderefreshing.mp3","us":"media/ldoce/hwd/ame/f/refreshing.mp3"},"examples":[{"en":"It made a refreshing change to be taken seriously for once.","cn":"总算有一次受到认真对待，这变化真是令人耳目一新。"},{"en":"The house was refreshingly cool inside.","cn":"屋内清凉宜人。"}],"oxford":{"phon":"rɪˈfreʃɪŋ","pos":"adjective","senses":[{"en":"pleasantly new or different","cn":"令人耳目一新的；别具一格的","ex":{"en":"It made a refreshing change to be taken seriously for once.","cn":"总算有一次受到认真对待，这变化真是令人耳目一新。"}},{"en":"making you feel less tired or hot","cn":"使人精力充沛的；使人凉爽的","ex":{"en":"a refreshing drink/shower","cn":"提神的饮料／淋浴"}}]},"base":"refresh"},"resign":{"collins":{"senses":[{"pos":"VERB 动词","cn":"辞职;辞去;放弃","en":"If you resign from a job or position, you formally announce that you are leaving it.","ex":{"en":"A hospital administrator has resigned over claims he lied to get the job","cn":"一位医院的管理人员辞职了，因为有人指责他为了得到这份工作而撒了谎。"}},{"pos":"VERB 动词","cn":"屈从;顺从;安于;勉强接受","en":"If you resign yourself to an unpleasant situation or fact, you accept it because you realize that you cannot change it.","ex":{"en":"Pat and I resigned ourselves to yet another summer without a boat","cn":"我和帕特在没有船的情况下勉强又凑合了一个夏天。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to leave your job permanently because you are not happy with it","cn":""},{"en":"to officially announce that you have decided to leave your job","cn":""},{"en":"to write an official letter to your employer saying that you are going to leave your job on a particular date","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"To resign is to quit or retire from a position. You can also resign yourself to something inevitable, like death — meaning you just accept that it's going to happen."}]},"collocations":{"phrases":["ADV. formally","VERB + RESIGN be forced to, be obliged to, have to He was forced to resign due to ill health. | intend to | offer to, threaten to The minist","PREP. as He resigned as chairman. | from She formally resigned from the government. | over Three members of the committee resigned over the "]},"media":{"uk":"media/ldoce/hwd/bre/e/resign0205.mp3","us":"media/ldoce/hwd/ame/9/resign.mp3"},"examples":[{"en":"Two members resigned from the board in protest.","cn":"董事会的两名成员辞职以示抗议。"},{"en":"He resigned as manager after eight years.","cn":"八年后，他辞去了经理的职务。"}],"oxford":{"phon":"rɪˈzaɪn","pos":"verb","senses":[{"en":"to officially tell somebody that you are leaving your job, an organization, etc.","cn":"辞职；辞去（某职务）","ex":{"en":"She was forced to resign due to ill health.","cn":"由于身体不好，她被迫辞职。"}}]}},"respite":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（不快事情中的）喘息，缓解，暂息","en":"A respite is a short period of rest from something unpleasant.","ex":{"en":"It was some weeks now since they had had any respite from shellfire.","cn":"他们已经好几周没有在炮火中获得任何喘息的机会了。"}},{"pos":"N-SING 单数名词","cn":"（不快或困难的）暂缓，暂延","en":"A respite is a short delay before a very unpleasant or difficult situation which may or may not take place.","ex":{"en":"Devaluation would only give the economy a brief respite.","cn":"贬值只能让经济得到暂时的缓解。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long or short period when you stop your work or normal activities, before continuing them again later","cn":""},{"en":"a short period during which you stop speaking or stop doing something before starting again","cn":""},{"en":"a short time when something unpleasant stops happening so that the situation is temporarily better","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A respite is a break from something that's difficult or unpleasant. If you're cramming for exams, take an occasional walk to give yourself a respite from the intensity."}]},"collocations":{"phrases":["ADJ. brief, moment's, temporary a moment's respite from the ringing of the phone | much needed, welcome","VERB + RESPITE have | bring (sb), give (sb), provide (sb with) The tablets brought temporary respite from the excruciating pain. | gain (sb)","RESPITE + NOUN care","PREP. without ~ The storm continued for two hours without respite. | ~ from They had no respite from the demands of their children.","PHRASES a period of respite"]},"media":{"uk":"media/ldoce/hwd/bre/4/respite0205.mp3","us":"media/ldoce/hwd/ame/9/respite.mp3"},"examples":[{"en":"respite care (= temporary care arranged for old, mentally ill, etc. people so that the people who usually care for them can have a rest)","cn":"暂时托管（为老人或病人提供短期照料以使长期照顾者获得短暂休息）"},{"en":"His creditors agreed to give him a temporary respite.","cn":"他的债权人同意给他一个喘息的机会。"}],"oxford":{"phon":"ˈrespaɪt","pos":"noun","senses":[{"en":"a short break or escape from something difficult or unpleasant","cn":"暂停；暂缓","lab":"especially North American English","ex":{"en":"The drug brought a brief respite from the pain.","cn":"药物暂时缓解了疼痛。"}},{"en":"a short delay allowed before something difficult or unpleasant must be done","cn":"短暂的延缓；喘息","ex":{"en":"His creditors agreed to give him a temporary respite.","cn":"他的债权人同意给他一个喘息的机会。"}}]}},"rebuff":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拒绝;回绝","en":"If you rebuff someone or rebuff a suggestion that they make, you refuse to do what they suggest.","ex":{"en":"He wanted sex with Julie but she rebuffed him","cn":"他想和朱莉上床但被她拒绝了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to say firmly that you will not do something that someone has asked you to do","cn":""},{"en":"to say that you will not do something when someone asks you","cn":""},{"en":"to refuse to accept an offer or invitation, or a formal request","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you rebuff someone, you reject or snub him. You might decide to rebuff a classmate's invitation to the dance after hearing him gossip meanly about a friend."}]},"collocations":{"phrases":["ADJ. harsh, sharp, stinging | humiliating","VERB + REBUFF meet (sth) with, receive, suffer Her efforts were met with a sharp rebuff. | risk My father was too proud to risk a rebuff, so","PREP. (in) a ~ to In a rebuff to the president, Congress voted against the bill. | ~ from She suffered a rebuff from her manager when she ra"]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41rebuff.mp3","us":"media/ldoce/hwd/ame/5/rebuff.mp3"},"examples":[{"en":"They rebuffed her request for help.","cn":"他们拒绝了她的请求，不给她帮助。"},{"en":"Her offer of help was met with a sharp rebuff.","cn":"她主动帮忙，却遭到断然拒绝。"}],"oxford":{"phon":"rɪˈbʌf","pos":"verb","senses":[{"en":"to refuse a friendly offer, request or suggestion in an unkind way","cn":"粗暴回绝；生硬的拒绝","ex":{"en":"They rebuffed her request for help.","cn":"他们严词拒绝了她的求助。"}},{"en":"an act of unkindly refusing a friendly offer, request or suggestion","cn":"严词回绝；生硬的拒绝","ex":{"en":"Her offer of help was met with a sharp rebuff.","cn":"她主动帮忙，却遭到断然拒绝。"},"pos":"noun"}]}},"recount":{"collins":{"senses":[{"pos":"VERB 动词","cn":"讲述;描述;描绘","en":"If you recount a story or event, you tell or describe it to people.","ex":{"en":"He then recounted the story of the interview for his first job","cn":"他接着讲述了自己第一次找工作时面试的情形。"}},{"pos":"N-COUNT 可数名词","cn":"（选举中的）重新计票，重新点票","en":"A recount is a second count of votes in an election when the result is very close.","ex":{"en":"She wanted a recount. She couldn't believe that I had got more votes than her.","cn":"她想要重新计票。她不相信我比她得票多。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give someone information by speaking or writing to them","cn":""},{"en":"to tell someone something when you know more about it","cn":""},{"en":"to tell another person the information that has been told to you","cn":""}]},"vocab":{"pos":"1 v 2 v n","senses":[{"en":"As a verb, recount can mean either \"tell the story of\" or \"add up again.\" As a noun, recount usually refers to the second (or third or fourth) tallying of votes in a close election."}]},"collocations":{"phrases":["ADV. vividly The story of his life is vividly recounted in this new book."]},"media":{"uk":"media/ldoce/hwd/bre/9/recount_las2_br.mp3","us":"media/ldoce/hwd/ame/4/l3recount.mp3"},"examples":[{"en":"She was asked to recount the details of the conversation to the court.","cn":"她被要求向法庭陈述谈话细节。"},{"en":"They recounted what had happened during those years.","cn":"他们叙述了那些年里发生的事。"}],"oxford":{"phon":"rɪˈkaʊnt","pos":"verb","senses":[{"en":"to tell somebody about something, especially something that you have experienced","cn":"讲述，叙述（亲身经历）","ex":{"en":"She was asked to recount the details of the conversation to the court.","cn":"她被要求向法庭陈述谈话细节。"}},{"en":"an act of telling somebody about something, especially something that you have experienced","cn":"（尤指对亲身经历的）讲述，叙述","ex":{"en":"By the time we got home, I had finished my recount of the events.","cn":"我们到家时，我已经讲完了这些事情的经过。"},"pos":"noun"},{"en":"to count something again, especially votes","cn":"重数；重新清点（选票）"},{"en":"an act of counting again to find the total number of something, especially votes at an election when the result is very close","cn":"重新计数；重新计票","ex":{"en":"The defeated candidate demanded a recount.","cn":"落选的候选人要求重新计票。"},"pos":"noun"}]}},"regularity":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"规律性;规律","en":"A regularity is the fact that the same thing always happens in the same circumstances.","ex":{"en":"Children seek out regularities and rules in acquiring language.","cn":"儿童在学习语言过程中会找出各种规律和规则。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to do something many times, in a way that is annoying","cn":""},{"en":"if someone or something is always doing something, or someone or something does something all the time , it annoys you because they do it too often","cn":""},{"en":"use this when you are very annoyed because something happens repeatedly over a long period of time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Something that happens with regularity is typical and expected. Fashion trends change with regularity , which is great for stores that want to sell you a new wardrobe every year."}]},"collocations":{"phrases":["QUANT. degree Sons followed their fathers' trade with a high degree of regularity.","VERB + REGULARITY maintain The idea is to maintain the regularity of the heartbeat.","PREP. with (a) ~ He exercised with a regularity that amazed us. | ~ in Is there any regularity in English word stress?","PHRASES with alarming/depressing/monotonous regularity the statistics that he quotes with monotonous regularity | with great/increasing regu"]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41regularity.mp3","us":"media/ldoce/hwd/ame/d/ld41regularity.mp3"},"examples":[{"en":"Aircraft passed overhead with monotonous regularity.","cn":"飞机一次又一次反复从头顶飞过。"},{"en":"They had observed regularities in the behaviour of the animals.","cn":"他们曾观察过这些动物的习性。"}],"oxford":{"phon":"ˌreɡjuˈlærəti","pos":"noun","senses":[{"en":"the fact that the same thing happens again and again, and usually with the same length of time between each time it happens","cn":"规律性；经常性","g":"[uncountable]","ex":{"en":"Aircraft passed overhead with monotonous regularity.","cn":"飞机一次又一次反复从头顶飞过。"}},{"en":"the fact that something is arranged in an even way or in an organized pattern","cn":"匀称；端正；有规则的分布","g":"[uncountable]","ex":{"en":"the striking regularity of her features","cn":"她的五官非常端正"}},{"en":"a thing that has a pattern to it","cn":"有规则的东西；有规律的事物","g":"[countable]","ex":{"en":"They had observed regularities in the behaviour of the animals.","cn":"他们曾观察过这些动物的习性。"}}]}},"redundant":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（人员因过剩）被解雇的，被裁减的","en":"If you are made redundant, your employer tells you to leave because your job is no longer necessary or because your employer cannot afford to keep paying you.","ex":{"en":"My husband was made redundant late last year.","cn":"我丈夫去年年底被裁了。"}},{"pos":"ADJ 形容词","cn":"多余的；不再需要的；过剩的","en":"Something that is redundant is no longer needed because its job is being done by something else or because its job is no longer necessary or useful.","ex":{"en":"Changes in technology may mean that once-valued skills are now redundant.","cn":"技术上的革新可能意味着曾经被重视的技术现在已变得多余。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is unemployed does not have a job","cn":""},{"en":"unemployed, especially for a long period of time, when you had a job before","cn":""},{"en":"if someone is redundant, they have been told that they no longer have a job","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"The word redundant applies to things that are unnecessary or could be left out. Calling a blank sheet of paper empty is redundant ."}]},"collocations":{"phrases":["VERBS be | become | make sb the decision to make 800 employees compulsorily redundant","ADV. compulsorily 2 not necessary or wanted","VERBS be, feel, seem | become | declare sth, make sth, render sth The chapel was declared redundant in 1995.","ADV. completely | virtually | largely"]},"media":{"uk":"media/ldoce/hwd/bre/8/redundant0205.mp3","us":"media/ldoce/hwd/ame/9/redundant.mp3"},"examples":[{"en":"The picture has too much redundant detail.","cn":"这幅画中不必要的细节太多。"},{"en":"to be made redundant from your job","cn":"成为冗员而被裁减"}],"oxford":{"phon":"rɪˈdʌndənt","pos":"adjective","senses":[{"en":"without a job because there is no more work available for you in a company","cn":"被裁减的","lab":"British English","ex":{"en":"to be made redundant from your job","cn":"成为冗员而被裁减"}},{"en":"not needed or useful","cn":"多余的；不需要的","ex":{"en":"The picture has too much redundant detail.","cn":"这幅画中不必要的细节太多。"}}]}},"render":{"collins":{"senses":[{"pos":"VERB 动词","cn":"致使;造成","en":"You can use render with an adjective that describes a particular state to say that someone or something is changed into that state. For example, if someone or something makes a thing harmless, you can say that they render it harmless.","ex":{"en":"It contained so many errors as to render it worthless.","cn":"它错误太多,所以毫无用处。"}},{"pos":"VERB 动词","cn":"给予(帮助);提供(服务)","en":"If you render someone help or service, you help them.","ex":{"en":"He had a chance to render some service to his country","cn":"他有了一个为国服务的机会。"}},{"pos":"VERB 动词","cn":"宣布，作出(判决、决定或回应)","en":"When a jury or authority renders a verdict, decision, or response, they announce it.","ex":{"en":"The Board had been slow to render its verdict.","cn":"董事会迟迟未能作出决定。"}},{"pos":"VERB 动词","cn":"翻译","en":"To render something in a particular language or in a particular way means to translate it into that language or in that way.","ex":{"en":"...'Zensho shimasu,' which the translator rendered literally as, 'I will do my best.'","cn":"“Zensho shimasu,”译者直译为“我会尽全力”。"}},{"pos":"VERB 动词","cn":"（用石灰或水泥）粉刷(墙壁)","en":"To render a wall means to cover it with a layer of plaster or cement, usually in order to protect it."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something be in a particular condition, especially so that it is ready to be used","cn":""},{"en":"to make someone or something unable to do something, work properly, cause any damage etc","cn":""},{"en":"to cause someone or something to suddenly be in a very bad situation","cn":""}]},"vocab":{"pos":"1 v 2 v 3 v n 4 v","senses":[{"en":"Render is a synonym of make––technically it means \"cause to become.\" An illness might render you unable to walk, or a shocking site might render you speechless."}]},"media":{"uk":"media/ldoce/hwd/bre/9/render0205.mp3","us":"media/ldoce/hwd/ame/6/render.mp3"},"examples":[{"en":"The artist has rendered the stormy sea in dark greens and browns.","cn":"画家用了深绿色和棕色来表现波涛汹涌的大海。"},{"en":"The Italian phrase can be rendered as ‘I did my best’.","cn":"这个意大利语的短语可以译为“我尽力了”。"}],"oxford":{"phon":"ˈrendə(r)","pos":"verb","senses":[{"en":"to cause somebody/something to be in a particular state or condition","cn":"使成为；使变得；使处于某状态","lab":"formal","sc":"cause somebody/something to be something","ex":{"en":"to render something harmless/useless/ineffective","cn":"使某事物无害／无用／无效"}},{"en":"to give somebody something, especially in return for something or because it is expected","cn":"给予；提供；回报","lab":"formal","sc":"give help","ex":{"en":"They rendered assistance to the disaster victims.","cn":"他们给灾民提供了援助。"}},{"en":"to present something, especially when it is done officially","cn":"递交；呈献；提交","lab":"formal","sc":"present something","ex":{"en":"The committee was asked to render a report on the housing situation.","cn":"要求委员会提交一份有关住房情况的报告。"}},{"en":"to express or perform something","cn":"表达；表演；演示","lab":"formal","sc":"express/perform","ex":{"en":"He stood up and rendered a beautiful version of ‘Summertime’.","cn":"他站起来表演了一段优美的《夏日时光》。"}},{"en":"to express something in a different language","cn":"（用不同的语言）表达；翻译；把…译成","sc":"translate","ex":{"en":"The Italian phrase can be rendered as ‘I did my best’.","cn":"这个意大利语的短语可以译为“我尽力了”。"}},{"en":"to cover a wall with a layer of plaster or cement","cn":"粉刷；给（墙壁）抹灰","lab":"specialist","sc":"wall"},{"en":"to make fat liquid by heating it; to melt something","cn":"将（脂肪）熬成油；熔化","sc":"melt"}]}},"rejection":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of not accepting, believing in, or agreeing with something","cn":"拒绝接受[相信﹐赞同]﹔否决"},{"en":"the act of not accepting someone for a job, school etc 〔","cn":"对求职者﹑求学者等的〕拒绝"},{"en":"a situation in which someone stops giving you love or attention","cn":"嫌弃﹐厌弃"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"The noun rejection can refer to the actual act of rejecting something or to the feeling one has after being rejected. In other words, you might have feelings of rejection after experiencing the rejection of others."}]},"collocations":{"phrases":["ADJ. blanket, outright, total, wholesale | deliberate","VERB + REJECTION fear Children who have had bad experiences fear rejection. | risk | cope with, take It takes a very buoyant personality to ","REJECTION + NOUN letter, slip a publisher's rejection slip","PREP. ~ by the rejection of the child by its mother","PHRASES fear of rejection, feelings of rejection, the rejection of an idea/a proposal/a theory"]},"media":{"uk":"media/ldoce/hwd/bre/a/rejection0205.mp3","us":"media/ldoce/hwd/ame/2/rejection.mp3"},"examples":[{"en":"What are the reasons for his rejection of the theory?","cn":"他不接受这个理论的原因是什么？"},{"en":"They sent me a rejection letter.","cn":"他们给我发了一封回绝信。"}],"oxford":{"phon":"rɪˈdʒekʃn","pos":"noun","senses":[{"en":"the act of refusing to accept or consider something","cn":"拒绝接受；不予考虑","ex":{"en":"Her proposal met with unanimous rejection.","cn":"她的建议遭到一致否决。"}},{"en":"the act of refusing to accept somebody for a job, position, etc.","cn":"拒收；不录用；拒绝接纳","ex":{"en":"a rejection letter (= a letter in which you are told, for example, that you have not been accepted for a job)","cn":"回绝信"}},{"en":"the decision not to use, sell, publish, etc. something because its quality is not good enough","cn":"（因质量差）不用，不出售，不出版","ex":{"en":"I've had letters of rejection from several publishers.","cn":"我收过几家出版社的退稿信。"}},{"en":"the failure of somebody's body to accept a new organ after a transplant operation","cn":"（对移植器官的）排斥（反应）","ex":{"en":"He had a second lung transplant after rejection of the first.","cn":"他在第一次肺移植手术发生排斥反应后又做了第二次。"}},{"en":"failure to give a person or an animal enough love or care","cn":"不够关心；冷落；慢待","ex":{"en":"painful feelings of rejection","cn":"受冷落的痛苦感受"}}]}}});
